  site_column_ref INT,
  declaration_graph_ref  VARCHAR,
  declaration_type_ref   VARCHAR,
  declaration_source_ref VARCHAR,
  declaration_line_ref   INT,
  declaration_column_ref INT,
  PRIMARY KEY (graph_name, union_name, member_type_name),
  FOREIGN KEY (graph_name, union_name) REFERENCES graphql_type_element (graph_name, type_name) ON DELETE CASCADE,
  FOREIGN KEY (declaration_graph_ref, declaration_type_ref, declaration_source_ref,
               declaration_line_ref, declaration_column_ref)
    REFERENCES graphql_type_declaration (graph_name, type_name, source_name, source_line, source_column)
    ON DELETE SET NULL,
  CHECK (declaration_graph_ref IS NULL OR declaration_graph_ref = graph_name),
  CHECK (declaration_type_ref IS NULL OR declaration_type_ref = union_name),
  CHECK (declaration_source_ref IS NULL OR declaration_source_ref = source_name),
  CHECK (declaration_line_ref IS NULL OR declaration_line_ref = declaration_line),
  CHECK (declaration_column_ref IS NULL OR declaration_column_ref = declaration_column),
  FOREIGN KEY (site_graph_ref, site_source_ref, site_line_ref, site_column_ref)
    REFERENCES graphql_ast_entry (graph_name, source_name, source_line, source_column)
    ON DELETE SET NULL,
  CHECK (site_graph_ref IS NULL OR site_graph_ref = graph_name),
  CHECK (site_source_ref IS NULL OR site_source_ref = source_name),
  CHECK (site_line_ref IS NULL OR site_line_ref = source_line),
  CHECK (site_column_ref IS NULL OR site_column_ref = source_column)
);

CREATE TABLE graphql_implements_interface (
  graph_name          VARCHAR NOT NULL,
  type_name           VARCHAR NOT NULL,
  interface_name      VARCHAR NOT NULL,
  position            INT     NOT NULL,
  declaration_line    INT     NOT NULL,
  declaration_column  INT     NOT NULL,
  source_name         VARCHAR NOT NULL,
  source_line         INT,
  source_column       INT,
  touched_at          TIMESTAMP NOT NULL,
  site_graph_ref  VARCHAR,
  site_source_ref VARCHAR,
  site_line_ref   INT,
  site_column_ref INT,
  declaration_graph_ref  VARCHAR,
  declaration_type_ref   VARCHAR,
  declaration_source_ref VARCHAR,
  declaration_line_ref   INT,
  declaration_column_ref INT,
  PRIMARY KEY (graph_name, type_name, interface_name),
  FOREIGN KEY (graph_name, type_name) REFERENCES graphql_type_element (graph_name, type_name) ON DELETE CASCADE,
  FOREIGN KEY (declaration_graph_ref, declaration_type_ref, declaration_source_ref,
               declaration_line_ref, declaration_column_ref)
    REFERENCES graphql_type_declaration (graph_name, type_name, source_name, source_line, source_column)
    ON DELETE SET NULL,
  CHECK (declaration_graph_ref IS NULL OR declaration_graph_ref = graph_name),
  CHECK (declaration_type_ref IS NULL OR declaration_type_ref = type_name),
  CHECK (declaration_source_ref IS NULL OR declaration_source_ref = source_name),
  CHECK (declaration_line_ref IS NULL OR declaration_line_ref = declaration_line),
  CHECK (declaration_column_ref IS NULL OR declaration_column_ref = declaration_column),
  FOREIGN KEY (site_graph_ref, site_source_ref, site_line_ref, site_column_ref)
    REFERENCES graphql_ast_entry (graph_name, source_name, source_line, source_column)
    ON DELETE SET NULL,
  CHECK (site_graph_ref IS NULL OR site_graph_ref = graph_name),
  CHECK (site_source_ref IS NULL OR site_source_ref = source_name),
  CHECK (site_line_ref IS NULL OR site_line_ref = source_line),
  CHECK (site_column_ref IS NULL OR site_column_ref = source_column)
);

COMMENT ON TABLE graphql_union_member IS 'A union names a member: one row per member type the union declares, in the order it wrote them. For example union Result = Film | Actor is two rows, (Result, Film) at position 0 and (Result, Actor) at 1.';
COMMENT ON COLUMN graphql_union_member.union_name IS 'the union declaring the membership, which is also the declaration this row hangs off';
COMMENT ON COLUMN graphql_union_member.member_type_name IS 'the type the union admits, author-spelled and unanchored: a union may name a type no document declares, which assembly refuses and this relation records';
COMMENT ON COLUMN graphql_union_member.position IS 'source order within the union, numbered from zero. Inherited rather than intended, and it disagrees with graphql_implements_interface.position on the base; a mapping-constant fingerprint digests a list in this order, so rebasing is a change of its own.';
COMMENT ON COLUMN graphql_union_member.touched_at IS 'when the reading that derived this row ran, on graphql_element.touched_at''s terms: swept per graph, and NOT NULL so the sweep is total';
COMMENT ON COLUMN graphql_union_member.graph_name IS 'the owning graph''s partition, anchored by store_graph; the leading key dimension that keeps one workspace''s graphs apart';
COMMENT ON COLUMN graphql_union_member.declaration_line IS 'line of the declaration site that contributed this membership, as on graphql_field';
COMMENT ON COLUMN graphql_union_member.declaration_column IS 'column of the same, the site key''s fourth part';
COMMENT ON COLUMN graphql_union_member.source_name IS 'the file the member or interface token itself was written in; NOT NULL as on graphql_field';
COMMENT ON COLUMN graphql_union_member.source_line IS 'source line of that token, 1-based per the graphql-java convention';
COMMENT ON COLUMN graphql_union_member.source_column IS 'source column of that token, 1-based per the graphql-java convention';
COMMENT ON COLUMN graphql_union_member.site_graph_ref IS 'the graph, copied beside graph_name so the reference to the entry this row was read from can be nulled without touching the key; NULL once that entry is gone';
COMMENT ON COLUMN graphql_union_member.site_source_ref IS 'the file of the entry this row was read from, a copy of source_name the delete of that entry nulls rather than deletes this row by. NULL marks a row whose source went and that the next anchoring re-derives or sweeps';
COMMENT ON COLUMN graphql_union_member.site_line_ref IS 'the line of that entry, a copy of source_line nulled with it';
COMMENT ON COLUMN graphql_union_member.site_column_ref IS 'the column of that entry, a copy of source_column nulled with it';
COMMENT ON COLUMN graphql_union_member.declaration_graph_ref IS 'the graph, copied beside graph_name so the reference to the declaration site this row hangs off can be nulled without touching the key; NULL once that site is gone';
COMMENT ON COLUMN graphql_union_member.declaration_type_ref IS 'the declaring type, a copy of union_name nulled with the reference';
COMMENT ON COLUMN graphql_union_member.declaration_source_ref IS 'the file of the declaration site, a copy of source_name nulled with the reference';
COMMENT ON COLUMN graphql_union_member.declaration_line_ref IS 'the line of the declaration site, a copy of declaration_line nulled with the reference';
COMMENT ON COLUMN graphql_union_member.declaration_column_ref IS 'the column of the declaration site, a copy of declaration_column nulled with the reference. The site is a declaration entry, so a rewrite of its document deletes it; this row outlives that delete with its reference nulled, which is what keeps what hangs off it, and the next anchoring re-points or sweeps it';
COMMENT ON TABLE graphql_implements_interface IS 'A type answers to an interface: one row per interface the type declares it implements. For example type Film implements Node & Named is two rows, (Film, Node) and (Film, Named).';
COMMENT ON COLUMN graphql_implements_interface.type_name IS 'the implementing type, which is the declaration this row hangs off';
COMMENT ON COLUMN graphql_implements_interface.interface_name IS 'the interface named in the implements clause, author-spelled and unanchored';
COMMENT ON COLUMN graphql_implements_interface.position IS 'source order of this implementor among the interface''s implementors, numbered from one, which is what the merged relation counted and what a reader ordering them still expects. Not the interface''s position within this type''s implements clause: the split moved the key and left the numbering alone, renumbering being visible to a mapping-constant fingerprint. See graphql_union_member.position for why the two bases differ.';
COMMENT ON COLUMN graphql_implements_interface.touched_at IS 'when the reading that derived this row ran, on graphql_element.touched_at''s terms: swept per graph, and NOT NULL so the sweep is total';
COMMENT ON COLUMN graphql_implements_interface.graph_name IS 'the owning graph''s partition, anchored by store_graph; the leading key dimension that keeps one workspace''s graphs apart';
COMMENT ON COLUMN graphql_implements_interface.declaration_line IS 'line of the declaration site that contributed this membership, as on graphql_field';
COMMENT ON COLUMN graphql_implements_interface.declaration_column IS 'column of the same, the site key''s fourth part';
COMMENT ON COLUMN graphql_implements_interface.source_name IS 'the file the member or interface token itself was written in; NOT NULL as on graphql_field';
COMMENT ON COLUMN graphql_implements_interface.source_line IS 'source line of that token, 1-based per the graphql-java convention';
COMMENT ON COLUMN graphql_implements_interface.source_column IS 'source column of that token, 1-based per the graphql-java convention';
COMMENT ON COLUMN graphql_implements_interface.site_graph_ref IS 'the graph, copied beside graph_name so the reference to the entry this row was read from can be nulled without touching the key; NULL once that entry is gone';
COMMENT ON COLUMN graphql_implements_interface.site_source_ref IS 'the file of the entry this row was read from, a copy of source_name the delete of that entry nulls rather than deletes this row by. NULL marks a row whose source went and that the next anchoring re-derives or sweeps';
COMMENT ON COLUMN graphql_implements_interface.site_line_ref IS 'the line of that entry, a copy of source_line nulled with it';
COMMENT ON COLUMN graphql_implements_interface.site_column_ref IS 'the column of that entry, a copy of source_column nulled with it';
COMMENT ON COLUMN graphql_implements_interface.declaration_graph_ref IS 'the graph, copied beside graph_name so the reference to the declaration site this row hangs off can be nulled without touching the key; NULL once that site is gone';
COMMENT ON COLUMN graphql_implements_interface.declaration_type_ref IS 'the declaring type, a copy of type_name nulled with the reference';
COMMENT ON COLUMN graphql_implements_interface.declaration_source_ref IS 'the file of the declaration site, a copy of source_name nulled with the reference';
COMMENT ON COLUMN graphql_implements_interface.declaration_line_ref IS 'the line of the declaration site, a copy of declaration_line nulled with the reference';
COMMENT ON COLUMN graphql_implements_interface.declaration_column_ref IS 'the column of the declaration site, a copy of declaration_column nulled with the reference. The site is a declaration entry, so a rewrite of its document deletes it; this row outlives that delete with its reference nulled, which is what keeps what hangs off it, and the next anchoring re-points or sweeps it';
-- The container end of each arm, which is what a reader arriving with a container name probes by
-- and what the graphql_poly_member view unions. One index apiece rather than one shared, the two
-- containers being different columns of different relations.
CREATE INDEX graphql_union_member_union_ix
  ON graphql_union_member (graph_name, union_name);
CREATE INDEX graphql_implements_interface_interface_ix
  ON graphql_implements_interface (graph_name, interface_name);

CREATE TABLE graphql_root_operation (
  graph_name    VARCHAR NOT NULL,
  operation     VARCHAR NOT NULL,
  type_name     VARCHAR NOT NULL,
  source_name   VARCHAR,
  source_line   INT,
  source_column INT,
  touched_at    TIMESTAMP NOT NULL,
  site_graph_ref  VARCHAR,
  site_source_ref VARCHAR,
  site_line_ref   INT,
  site_column_ref INT,
  PRIMARY KEY (graph_name, operation),
  FOREIGN KEY (graph_name) REFERENCES store_graph (graph_name),
  CHECK (operation IN ('QUERY', 'MUTATION', 'SUBSCRIPTION')),
  FOREIGN KEY (site_graph_ref, site_source_ref, site_line_ref, site_column_ref)
    REFERENCES graphql_ast_entry (graph_name, source_name, source_line, source_column)
    ON DELETE SET NULL,
  CHECK (site_graph_ref IS NULL OR site_graph_ref = graph_name),
  CHECK (site_source_ref IS NULL OR site_source_ref = source_name),
  CHECK (site_line_ref IS NULL OR site_line_ref = source_line),
  CHECK (site_column_ref IS NULL OR site_column_ref = source_column)
);
COMMENT ON TABLE graphql_root_operation IS 'The schema binds a root operation to a type: one row per operation it names. For example schema { query: Query mutation: Mutation } is two rows, (QUERY, Query) and (MUTATION, Mutation).';
COMMENT ON COLUMN graphql_root_operation.graph_name IS 'the owning graph''s partition, anchored by store_graph; the leading key dimension that keeps one workspace''s graphs apart';
COMMENT ON COLUMN graphql_root_operation.operation IS 'which root slot';
COMMENT ON COLUMN graphql_root_operation.type_name IS 'the object type serving it';
COMMENT ON COLUMN graphql_root_operation.source_name IS 'position of the binding inside the schema { } block; all three NULL exactly when the binding is the name-convention default no SDL line spells';
COMMENT ON COLUMN graphql_root_operation.source_line IS 'line of the binding; NULL with the siblings when the binding is the name-convention default';
COMMENT ON COLUMN graphql_root_operation.source_column IS 'column of the binding; NULL with the siblings when the binding is the name-convention default';
COMMENT ON COLUMN graphql_root_operation.touched_at IS 'when the reading that derived this row ran, on graphql_element.touched_at''s terms: swept per graph, and NOT NULL so the sweep is total';
COMMENT ON COLUMN graphql_root_operation.site_graph_ref IS 'the graph, copied beside graph_name so the reference to the entry this row was read from can be nulled without touching the key; NULL once that entry is gone';
COMMENT ON COLUMN graphql_root_operation.site_source_ref IS 'the file of the entry this row was read from, a copy of source_name the delete of that entry nulls rather than deletes this row by. NULL marks a row whose source went and that the next anchoring re-derives or sweeps';
COMMENT ON COLUMN graphql_root_operation.site_line_ref IS 'the line of that entry, a copy of source_line nulled with it';
COMMENT ON COLUMN graphql_root_operation.site_column_ref IS 'the column of that entry, a copy of source_column nulled with it';

-- ==== Directive definitions =======================================================
-- The definition side of the directive surface: what a directive is, where it may sit, what
-- arguments it declares. Capture is total over the registry, so user-authored, spec built-in,
-- federation-imported, and graphitron's own bundled definitions are all rows. An emitter
-- re-declares the first three and strips the fourth, and it tells them apart the same way
-- anything else does, by reading source_name; the family does not encode the answer.
-- Totality is what makes every application's directive_name resolve to a definition, so
-- reading a repeatable flag or an argument default is one join rather than a namespace case.
CREATE TABLE graphql_directive (
  graph_name     VARCHAR NOT NULL,
  directive_name VARCHAR NOT NULL,
  repeatable     BOOLEAN NOT NULL,
  description    VARCHAR,
  source_name    VARCHAR NOT NULL,
  source_line    INT NOT NULL,
  source_column  INT NOT NULL,
  touched_at     TIMESTAMP NOT NULL,
  site_graph_ref  VARCHAR,
  site_source_ref VARCHAR,
  site_line_ref   INT,
  site_column_ref INT,
  PRIMARY KEY (graph_name, directive_name),
  FOREIGN KEY (graph_name) REFERENCES store_graph (graph_name),
  FOREIGN KEY (graph_name, directive_name)
    REFERENCES graphql_directive_element (graph_name, directive_name) ON DELETE CASCADE,
  FOREIGN KEY (site_graph_ref, site_source_ref, site_line_ref, site_column_ref)
    REFERENCES graphql_ast_entry (graph_name, source_name, source_line, source_column)
    ON DELETE SET NULL,
  CHECK (site_graph_ref IS NULL OR site_graph_ref = graph_name),
  CHECK (site_source_ref IS NULL OR site_source_ref = source_name),
  CHECK (site_line_ref IS NULL OR site_line_ref = source_line),
  CHECK (site_column_ref IS NULL OR site_column_ref = source_column)
);
COMMENT ON TABLE graphql_directive IS 'A directive is defined: whether it repeats, its description and the site that declared it. For example directive @paged repeatable on FIELD_DEFINITION is the row (paged) with repeatable true.';
COMMENT ON COLUMN graphql_directive.graph_name IS 'the owning graph''s partition, anchored by store_graph; the leading key dimension that keeps one workspace''s graphs apart';
COMMENT ON COLUMN graphql_directive.directive_name IS 'the defined directive name, without the leading @, anchored by graphql_directive_element';
COMMENT ON COLUMN graphql_directive.repeatable IS 'whether the definition says ''repeatable''; governs the ordinal on applications';
COMMENT ON COLUMN graphql_directive.description IS 'SDL description string, when the author wrote one';
COMMENT ON COLUMN graphql_directive.source_name IS 'the SDL file the row was captured from';
COMMENT ON COLUMN graphql_directive.source_line IS 'source line, 1-based per the graphql-java convention';
COMMENT ON COLUMN graphql_directive.source_column IS 'source column, 1-based per the graphql-java convention';
COMMENT ON COLUMN graphql_directive.touched_at IS 'when the reading that derived this row ran, on graphql_element.touched_at''s terms: swept per graph, and NOT NULL so the sweep is total';
COMMENT ON COLUMN graphql_directive.site_graph_ref IS 'the graph, copied beside graph_name so the reference to the entry this row was read from can be nulled without touching the key; NULL once that entry is gone';
COMMENT ON COLUMN graphql_directive.site_source_ref IS 'the file of the entry this row was read from, a copy of source_name the delete of that entry nulls rather than deletes this row by. NULL marks a row whose source went and that the next anchoring re-derives or sweeps';
COMMENT ON COLUMN graphql_directive.site_line_ref IS 'the line of that entry, a copy of source_line nulled with it';
COMMENT ON COLUMN graphql_directive.site_column_ref IS 'the column of that entry, a copy of source_column nulled with it';

CREATE TABLE graphql_directive_location (
  graph_name     VARCHAR NOT NULL,
  directive_name VARCHAR NOT NULL,
  location       VARCHAR NOT NULL,
  touched_at     TIMESTAMP NOT NULL,
  PRIMARY KEY (graph_name, directive_name, location),
  FOREIGN KEY (graph_name, directive_name) REFERENCES graphql_directive (graph_name, directive_name) ON DELETE CASCADE
);
COMMENT ON TABLE graphql_directive_location IS 'A directive definition names a permitted location. For example directive @paged on FIELD_DEFINITION | ARGUMENT_DEFINITION is two rows.';
COMMENT ON COLUMN graphql_directive_location.graph_name IS 'the owning graph''s partition, anchored by store_graph; the leading key dimension that keeps one workspace''s graphs apart';
COMMENT ON COLUMN graphql_directive_location.directive_name IS 'the applied or defined directive name, without the leading @';
COMMENT ON COLUMN graphql_directive_location.location IS 'introspection location name, e.g. FIELD_DEFINITION, INPUT_FIELD_DEFINITION';
COMMENT ON COLUMN graphql_directive_location.touched_at IS 'when the reading that derived this row ran, on graphql_element.touched_at''s terms: swept per graph, and NOT NULL so the sweep is total';

CREATE TABLE graphql_directive_argument (
  graph_name        VARCHAR NOT NULL,
  directive_name    VARCHAR NOT NULL,
  argument_name     VARCHAR NOT NULL,
  ordinal           INT     NOT NULL,
  type_sdl          VARCHAR NOT NULL,
  named_type        VARCHAR NOT NULL,
  non_null          BOOLEAN NOT NULL,
  is_list           BOOLEAN GENERATED ALWAYS AS (list_depth > 0) NOT NULL,
  item_non_null     BOOLEAN,
  list_depth        INT     NOT NULL,
  default_value_sdl VARCHAR,
  description       VARCHAR,
  source_name       VARCHAR NOT NULL,
  source_line       INT NOT NULL,
  source_column     INT NOT NULL,
  touched_at        TIMESTAMP NOT NULL,
  site_graph_ref  VARCHAR,
  site_source_ref VARCHAR,
  site_line_ref   INT,
  site_column_ref INT,
  PRIMARY KEY (graph_name, directive_name, argument_name),
  FOREIGN KEY (graph_name, directive_name) REFERENCES graphql_directive (graph_name, directive_name) ON DELETE CASCADE,
  FOREIGN KEY (graph_name, directive_name, argument_name)
    REFERENCES graphql_directive_argument_element (graph_name, directive_name, argument_name) ON DELETE CASCADE,
  CHECK (is_list OR item_non_null IS NULL),
  FOREIGN KEY (site_graph_ref, site_source_ref, site_line_ref, site_column_ref)
    REFERENCES graphql_ast_entry (graph_name, source_name, source_line, source_column)
    ON DELETE SET NULL,
  CHECK (site_graph_ref IS NULL OR site_graph_ref = graph_name),
  CHECK (site_source_ref IS NULL OR site_source_ref = source_name),
  CHECK (site_line_ref IS NULL OR site_line_ref = source_line),
  CHECK (site_column_ref IS NULL OR site_column_ref = source_column)
);
COMMENT ON TABLE graphql_directive_argument IS 'A directive definition declares a formal argument: its type expression, its default, its description and the site that declared it. For example the pagedName of directive @paged(pagedName: String) is the row (paged, pagedName) with type_sdl String.';
COMMENT ON COLUMN graphql_directive_argument.graph_name IS 'the owning graph''s partition, anchored by store_graph; the leading key dimension that keeps one workspace''s graphs apart';
COMMENT ON COLUMN graphql_directive_argument.directive_name IS 'the defined directive name, without the leading @, anchored by graphql_directive';
COMMENT ON COLUMN graphql_directive_argument.argument_name IS 'the formal argument name within the owning directive; with it, anchored by graphql_directive_argument_element';
COMMENT ON COLUMN graphql_directive_argument.ordinal IS 'declaration order in the definition';
COMMENT ON COLUMN graphql_directive_argument.type_sdl IS 'rendered argument type, e.g. ''[ReferenceElement!]!''';
COMMENT ON COLUMN graphql_directive_argument.named_type IS 'the named type the expression bottoms out in; author-spelled, no FK';
COMMENT ON COLUMN graphql_directive_argument.non_null IS 'outermost non-null wrapper present';
COMMENT ON COLUMN graphql_directive_argument.is_list IS 'a list wrapper is present. Generated from list_depth, so nothing writes it';
COMMENT ON COLUMN graphql_directive_argument.item_non_null IS 'item-level non-null when is_list; NULL otherwise';
COMMENT ON COLUMN graphql_directive_argument.list_depth IS 'how many list wrappers the expression has: 0 for a named type, 1 for a list of one, 2 for a list of lists. Carried from the entry rather than left behind by the anchoring, because the four columns beside it describe a type expression exactly when this is 0 or 1 and a reader that must tell those from a deeper one has nothing else to ask';
COMMENT ON COLUMN graphql_directive_argument.default_value_sdl IS 'rendered default; the value an application inherits when it omits the argument';
COMMENT ON COLUMN graphql_directive_argument.description IS 'SDL description string, when the author wrote one';
COMMENT ON COLUMN graphql_directive_argument.source_name IS 'the SDL file the formal argument was declared in, which is its directive''s one definition''s file';
COMMENT ON COLUMN graphql_directive_argument.source_line IS 'source line, 1-based per the graphql-java convention';
COMMENT ON COLUMN graphql_directive_argument.source_column IS 'source column, 1-based per the graphql-java convention';
COMMENT ON COLUMN graphql_directive_argument.touched_at IS 'when the reading that derived this row ran, on graphql_element.touched_at''s terms: swept per graph, and NOT NULL so the sweep is total';
COMMENT ON COLUMN graphql_directive_argument.site_graph_ref IS 'the graph, copied beside graph_name so the reference to the entry this row was read from can be nulled without touching the key; NULL once that entry is gone';
COMMENT ON COLUMN graphql_directive_argument.site_source_ref IS 'the file of the entry this row was read from, a copy of source_name the delete of that entry nulls rather than deletes this row by. NULL marks a row whose source went and that the next anchoring re-derives or sweeps';
COMMENT ON COLUMN graphql_directive_argument.site_line_ref IS 'the line of that entry, a copy of source_line nulled with it';
COMMENT ON COLUMN graphql_directive_argument.site_column_ref IS 'the column of that entry, a copy of source_column nulled with it';

-- ==== Directive applications ======================================================
-- One row per application the author wrote, one child row per argument the author passed.
-- Values are the rendered SDL literal, so an application is legible here without knowing what
-- the directive means. Capture is total: graphitron's own applications are rows like any
-- other, and the ones that carry meaning additionally get a decoded row in the graphitron_
-- family. A directive that is both re-emitted and decoded (federation's @key) is just an
-- application with both projections rather than a special case.
--
-- One relation for every site, keyed at the coordinate the application was written on. The five
-- relations this replaces stated one fact and keyed it five ways, three columns at the schema
-- block and seven at a field argument, because each carried its site's decomposed key instead of
-- the site's coordinate. graphql_element holds the coordinate for all of them, so an application
-- keys into that and a reader stops choosing a relation by where the author happened to write.
CREATE TABLE graphql_directive_application (
  graph_name     VARCHAR NOT NULL,
  coordinate     VARCHAR NOT NULL,
  directive_name VARCHAR NOT NULL,
  ordinal        INT     NOT NULL,
  source_name    VARCHAR NOT NULL,
  source_line    INT     NOT NULL,
  source_column  INT     NOT NULL,
  touched_at     TIMESTAMP NOT NULL,
  site_graph_ref  VARCHAR,
  site_source_ref VARCHAR,
  site_line_ref   INT,
  site_column_ref INT,
  PRIMARY KEY (graph_name, coordinate, directive_name, ordinal),
  FOREIGN KEY (graph_name, coordinate) REFERENCES graphql_element (graph_name, coordinate)
    ON DELETE CASCADE,
  FOREIGN KEY (site_graph_ref, site_source_ref, site_line_ref, site_column_ref)
    REFERENCES graphql_ast_entry (graph_name, source_name, source_line, source_column)
    ON DELETE SET NULL,
  CHECK (site_graph_ref IS NULL OR site_graph_ref = graph_name),
  CHECK (site_source_ref IS NULL OR site_source_ref = source_name),
  CHECK (site_line_ref IS NULL OR site_line_ref = source_line),
  CHECK (site_column_ref IS NULL OR site_column_ref = source_column)
);
COMMENT ON TABLE graphql_directive_application IS 'One directive an author applied, at the coordinate they applied it to: one row per application, however many sites the corpus writes them at. For example type Film @key(fields: "id") is one row at coordinate Film, and the @external on Film.title is another at Film.title.';
COMMENT ON COLUMN graphql_directive_application.graph_name IS 'the owning graph''s partition, anchored by store_graph through the element below; the leading key dimension that keeps one workspace''s graphs apart';
COMMENT ON COLUMN graphql_directive_application.coordinate IS 'the schema coordinate the application was written on, in the specification''s grammar: a type is its own name, a field or an enum value or an input field is the parent''s name and a dot, an argument goes one deeper, and the schema block is $schema. A reference into graphql_element, which is a table and not a union so this foreign key can name it, and the whole reason five relations are one: the coordinate is what every site has and the decomposed key is what none of them shares';
COMMENT ON COLUMN graphql_directive_application.directive_name IS 'the applied directive name, without the leading @';
COMMENT ON COLUMN graphql_directive_application.ordinal IS 'the repeat, numbered from zero within one coordinate and one directive name, in the order the declarations carrying them merge. A directive is not repeatable unless its definition says so, so on almost every application this is zero and the column exists for the ones that are';
COMMENT ON COLUMN graphql_directive_application.source_name IS 'the file the application was written in, the first of the three columns naming the position of its at sign. NOT NULL because this relation''s one writer reads the entries, and every entry was written somewhere';
COMMENT ON COLUMN graphql_directive_application.source_line IS 'source line, 1-based per the graphql-java convention';
COMMENT ON COLUMN graphql_directive_application.source_column IS 'source column, 1-based per the graphql-java convention';
COMMENT ON COLUMN graphql_directive_application.touched_at IS 'when the reading that derived this row ran, on graphql_element.touched_at''s terms: swept per graph, and NOT NULL so the sweep is total. The sweep is what collects an application an author deleted from a coordinate that still stands; a coordinate the author deleted takes its applications with it through the cascade above';
COMMENT ON COLUMN graphql_directive_application.site_graph_ref IS 'the graph, copied beside graph_name so the reference to the entry this row was read from can be nulled without touching the key; NULL once that entry is gone';
COMMENT ON COLUMN graphql_directive_application.site_source_ref IS 'the file of the entry this row was read from, a copy of source_name the delete of that entry nulls rather than deletes this row by. NULL marks a row whose source went and that the next anchoring re-derives or sweeps';
COMMENT ON COLUMN graphql_directive_application.site_line_ref IS 'the line of that entry, a copy of source_line nulled with it';
COMMENT ON COLUMN graphql_directive_application.site_column_ref IS 'the column of that entry, a copy of source_column nulled with it';
-- The position of the at sign, which is what GraphQLAstCapture.directiveApplicationArguments joins
-- an argument entry to its application by. The position is no prefix of the key, so without this
-- every entry scans every application. touched_at stays out: it is a residual on the rows the
-- seek finds, not a dimension of it.
CREATE INDEX graphql_directive_application_position_ix
  ON graphql_directive_application (graph_name, source_name, source_line, source_column);

CREATE TABLE graphql_directive_application_arg (
  graph_name              VARCHAR NOT NULL,
  coordinate              VARCHAR NOT NULL,
  directive_name          VARCHAR NOT NULL,
  ordinal                 INT     NOT NULL,
  directive_argument_name VARCHAR NOT NULL,
  value_sdl               VARCHAR NOT NULL,
  touched_at              TIMESTAMP NOT NULL,
  PRIMARY KEY (graph_name, coordinate, directive_name, ordinal, directive_argument_name),
  FOREIGN KEY (graph_name, coordinate, directive_name, ordinal)
    REFERENCES graphql_directive_application (graph_name, coordinate, directive_name, ordinal)
    ON DELETE CASCADE
);
COMMENT ON TABLE graphql_directive_application_arg IS 'One argument an author passed to an application: the application''s own key and the formal argument the value binds. For example the fields: "id" of type Film @key(fields: "id") is one row.';
COMMENT ON COLUMN graphql_directive_application_arg.graph_name IS 'the owning graph''s partition, carried from the application above; the leading key dimension that keeps one workspace''s graphs apart';
COMMENT ON COLUMN graphql_directive_application_arg.coordinate IS 'the coordinate the owning application was written on, the second of the four columns naming it';
COMMENT ON COLUMN graphql_directive_application_arg.directive_name IS 'the owning application''s directive name, the third';
COMMENT ON COLUMN graphql_directive_application_arg.ordinal IS 'the owning application''s ordinal, the fourth; with the three columns above, a reference into graphql_directive_application';
COMMENT ON COLUMN graphql_directive_application_arg.directive_argument_name IS 'the definition''s formal argument this value binds, and the rest of the grain. An argument is named once inside one application, so nothing is ranked here; a document naming one twice is a schema problem and the upsert keeps the later of the two rather than refusing the row';
COMMENT ON COLUMN graphql_directive_application_arg.value_sdl IS 'the value as written, rendered from the AST. The literal rather than a parse of it, so an application is legible without knowing what the directive means, and so a consumer that does know reads the same string the author typed';
COMMENT ON COLUMN graphql_directive_application_arg.touched_at IS 'when the reading that derived this row ran, on graphql_element.touched_at''s terms: swept per graph, and NOT NULL so the sweep is total';

CREATE VIEW graphql_poly_member (graph_name, container_kind, container_name, member_type_name,
    position, declared_on, declaration_line, declaration_column, source_name, source_line,
    source_column, touched_at) AS
  SELECT graph_name, 'UNION', union_name, member_type_name, position, union_name,
         declaration_line, declaration_column, source_name, source_line, source_column, touched_at
  FROM graphql_union_member
  UNION ALL
  SELECT graph_name, 'INTERFACE', interface_name, type_name, position, type_name,
         declaration_line, declaration_column, source_name, source_line, source_column, touched_at
  FROM graphql_implements_interface;
COMMENT ON VIEW graphql_poly_member IS 'Union membership and interface implementation as one relation, for the readers that take either. Two relations hold the facts, because a union declares who it admits and a type declares which interfaces it answers to: the declaring end differs, and with it the key and every foreign key. What the two share is the shape a reader wants when it does not care which it has, a container and a member, and that is this view. declared_on is the declaring end, which the arms supply as the column that already is it rather than as a CHECK policing a copy: the union on one arm, the implementing type on the other.';
-- COMMENT ON COLUMN graphql_poly_member.graph_name IS 'the owning graph''s partition, anchored by store_graph; the leading key dimension that keeps one workspace''s graphs apart';
-- COMMENT ON COLUMN graphql_poly_member.container_kind IS 'which arm this row came from, UNION or INTERFACE, which is also which base relation holds it; a literal in each arm of the union rather than a stored column';
-- COMMENT ON COLUMN graphql_poly_member.container_name IS 'the union or the interface holding the member, whichever arm this row is';
-- COMMENT ON COLUMN graphql_poly_member.member_type_name IS 'the member type on the union arm, the implementing type on the interface arm';
-- COMMENT ON COLUMN graphql_poly_member.position IS 'source order within the container, as the arm that holds it recorded it';
-- COMMENT ON COLUMN graphql_poly_member.declared_on IS 'the type that declared this membership: the container on a UNION row, the member on an INTERFACE row. The anchored end, and what the two arms disagree about, which is why they are two relations';
-- COMMENT ON COLUMN graphql_poly_member.declaration_line IS 'line of the declaration site that contributed this membership, as on graphql_field';
-- COMMENT ON COLUMN graphql_poly_member.declaration_column IS 'column of the same, the site key''s fourth part';
-- COMMENT ON COLUMN graphql_poly_member.source_name IS 'the file the member or interface token itself was written in; NOT NULL as on graphql_field';
-- COMMENT ON COLUMN graphql_poly_member.source_line IS 'source line of that token, 1-based per the graphql-java convention';
-- COMMENT ON COLUMN graphql_poly_member.source_column IS 'source column of that token, 1-based per the graphql-java convention';
-- COMMENT ON COLUMN graphql_poly_member.touched_at IS 'when the reading that derived the underlying row ran, carried through from the arm that holds it';

-- ==== The decoded graphitron and federation inventory =============================
-- A derivation over the transcription: every relation below is a function of the generic
-- directive applications the graphql_ family captured, decoded into graphitron's vocabulary.

-- The dotted paths this family stores as written, decomposed once each. Every relation below
-- whose right-hand side is an argument path shares this one decode, so it leads the family.
CREATE TABLE graphitron_argmapping_candidate (
  graph_name    VARCHAR NOT NULL,
  coordinate    VARCHAR NOT NULL,
  path          VARCHAR NOT NULL,
  parent_path   VARCHAR,
  name          VARCHAR NOT NULL,
  element_kind  VARCHAR NOT NULL,
  container_type_name VARCHAR,
  named_type    VARCHAR,
  is_list       BOOLEAN NOT NULL,
  depth         INT     NOT NULL,
  closes_cycle  BOOLEAN NOT NULL,
  deprecated    BOOLEAN NOT NULL,
  ambiguous     BOOLEAN NOT NULL,
  PRIMARY KEY (graph_name, coordinate, path),
  FOREIGN KEY (graph_name) REFERENCES store_graph (graph_name),
  FOREIGN KEY (graph_name, coordinate) REFERENCES graphql_element (graph_name, coordinate)
    ON DELETE CASCADE,
  FOREIGN KEY (graph_name, coordinate, parent_path)
    REFERENCES graphitron_argmapping_candidate (graph_name, coordinate, path) ON DELETE CASCADE,
  CHECK (path <> ''),
  CHECK (element_kind IN ('ARGUMENT', 'INPUT_FIELD', 'SIGIL')),
  CHECK ((parent_path IS NULL) = (depth = 0)),
  CHECK ((container_type_name IS NULL) = (element_kind IN ('ARGUMENT', 'SIGIL'))),
  CHECK ((named_type IS NULL) = (element_kind = 'SIGIL')),
  CHECK (element_kind <> 'SIGIL' OR (depth = 0 AND is_list = FALSE AND closes_cycle = FALSE)),
  CHECK (NOT deprecated OR depth > 0)
);
CREATE INDEX graphitron_argmapping_candidate_parent_ix
  ON graphitron_argmapping_candidate (graph_name, coordinate, parent_path);
COMMENT ON TABLE graphitron_argmapping_candidate IS 'What an argMapping right-hand side may name: one row per writable path, under the schema coordinate the directive carrying it sits on. For example at Mutation.rentFilm(input:) the argument''s own name is one row, every field of the input type below it is another, and the input-prefixed spelling of each of those is a third row marked deprecated, so an author who writes either spelling meets a candidate.';
COMMENT ON COLUMN graphitron_argmapping_candidate.graph_name IS 'the owning graph''s partition, anchored by store_graph; the leading key dimension that keeps one workspace''s graphs apart';
COMMENT ON COLUMN graphitron_argmapping_candidate.coordinate IS 'the schema coordinate the argMapping is written at, spelled as the GraphQL specification spells one and anchored by graphql_element: Type.field where a directive sits on a field, Type.field(argument:) where it sits on an argument, and InputType.field where it sits on an input field. A directive location and never a container, which is the difference from what this column held before: the three shapes are the three placements argMapping reaches capture from, so a reader wanting the parts joins the coordinate relation rather than reading a decomposition kept beside the spelling.';
COMMENT ON COLUMN graphitron_argmapping_candidate.path IS 'the right-hand side an author writes to name this element at this coordinate, from its head down, dot-separated. Every row is something writable, so no path is empty: a root is a row whose parent_path is null, not one whose path is blank. An entry''s written path meets its candidate on this column exactly, with no head to strip first and no prefix probe to rank.';
COMMENT ON COLUMN graphitron_argmapping_candidate.parent_path IS 'the path one segment shorter, NULL at a root; a foreign key back to this relation, so a subtree is deleted by deleting what it hangs from. This is what says a row is a root, and no blank path stands in for it';
COMMENT ON COLUMN graphitron_argmapping_candidate.name IS 'the last segment of the path, which is what this row''s own element is called. At a root it is the whole path. An entry naming one thing below a resolved position meets this column, so the completion set at a position is the names of that position''s children';
COMMENT ON COLUMN graphitron_argmapping_candidate.element_kind IS 'what this row''s own element is: ARGUMENT for a field''s argument, INPUT_FIELD for a field of an input type, SIGIL for a value the runtime holds. A property of the element rather than of the coordinate it is written at, so a reader switching on it needs no depth test, and the two nullnesses beside it are stated against this column. An argument and a sigil have no declaring type, so neither carries a container; a sigil names no GraphQL type, so it carries no named type either.';
COMMENT ON COLUMN graphitron_argmapping_candidate.container_type_name IS 'the type this candidate''s element is declared on, NULL where the element is an argument or a sigil and no type declares it';
COMMENT ON COLUMN graphitron_argmapping_candidate.named_type IS 'the type of the value at this candidate, unwrapped of list and non-null. The whole of what says whether anything opens below: a candidate whose type is an input object has children and every other candidate is a leaf, so a reader needs no separate kind column and no rule of its own';
COMMENT ON COLUMN graphitron_argmapping_candidate.is_list IS 'whether the value at this candidate is a list, carried from the argument or input field it stands for. A consumer binding a parameter to this candidate needs the arity as much as the type, and reading it here is what keeps such a consumer from joining back to the SDL relation the writer already read';
COMMENT ON COLUMN graphitron_argmapping_candidate.depth IS 'how many segments below the root this candidate sits, zero at a root; carried because a reader ranking how far a path resolved compares it rather than counting separators';
COMMENT ON COLUMN graphitron_argmapping_candidate.closes_cycle IS 'whether this candidate''s type already stands above it on its own ancestry, which is what makes it the element that closes a cycle. Such a candidate is nameable and so has a row, and nothing below it does, so this column is the difference between a leaf and a stopping point and a reader never has to infer one from the absence of children. Cyclic input nesting is not supported yet and the refusal an author sees is stated over these rows: a true here is where the candidate set stops, and saying so is what keeps the deferral visible instead of silent';
COMMENT ON COLUMN graphitron_argmapping_candidate.deprecated IS 'whether this spelling repeats the coordinate''s own name as its head, which every argument-level and input-field-level argMapping in the wild does today and which the clean spelling beside it replaces. A candidate all the same, because refusing what authors have already written is not this relation''s business: both spellings resolve and this column is what lets a warning tell them apart. False at every candidate under a field coordinate, where a head names an argument and repeats nothing, and false on the coordinate''s own name, that being the only spelling for binding the whole value';
COMMENT ON COLUMN graphitron_argmapping_candidate.ambiguous IS 'whether more than one reading produced this exact spelling at this coordinate, the surviving row being the one the resolution picked. The relation cannot hold both because an author cannot write both, so the loser is not a row and this column is what keeps its absence from being silent. Which other reading it was needs no column of its own, both being recoverable here: the deprecated reading of a dotted spelling is the row at the same coordinate whose path is this one with its head removed, and the other reading of the coordinate''s own name is the coordinate itself';

CREATE TABLE graphitron_ast_table_entry (
  graph_name    VARCHAR NOT NULL,
  source_name   VARCHAR NOT NULL,
  source_line   INT     NOT NULL,
  source_column INT     NOT NULL,
  touched_at    TIMESTAMP NOT NULL,
  table_ref     VARCHAR NOT NULL,
  table_ref_namespace_part VARCHAR,
  table_ref_name_part      VARCHAR NOT NULL,
  table_ref_namespace_part_upper VARCHAR GENERATED ALWAYS AS (UPPER(table_ref_namespace_part)),
  table_ref_name_part_upper      VARCHAR GENERATED ALWAYS AS (UPPER(table_ref_name_part)),
  PRIMARY KEY (graph_name, source_name, source_line, source_column),
  FOREIGN KEY (graph_name) REFERENCES store_graph (graph_name),
  FOREIGN KEY (graph_name, source_name, source_line, source_column)
    REFERENCES graphql_ast_directive_application_entry (graph_name, source_name, source_line, source_column)
    ON DELETE CASCADE
);
COMMENT ON TABLE graphitron_ast_table_entry IS 'What an @table application says: the table this declaration is bound to, as written. For example type Film @table(name: "film") gives one row reading film.';
COMMENT ON COLUMN graphitron_ast_table_entry.graph_name IS 'the owning graph''s partition, anchored by store_graph; the leading key dimension that keeps one workspace''s graphs apart';
COMMENT ON COLUMN graphitron_ast_table_entry.source_name IS 'the file the application was written in';
COMMENT ON COLUMN graphitron_ast_table_entry.source_line IS 'source line of the at sign, 1-based per the graphql-java convention';
COMMENT ON COLUMN graphitron_ast_table_entry.source_column IS 'source column of the same. The four key columns are the applied directive''s own key, so this row is the decode of exactly one row of graphql_ast_directive_application_entry and neither carries what the other holds';
COMMENT ON COLUMN graphitron_ast_table_entry.touched_at IS 'when the reading that produced this row ran. The reading finishes by deleting its file''s rows carrying an older instant, which are the applications the author removed or renamed in place; an application the author moved is swept with the directive row it hangs on';
COMMENT ON COLUMN graphitron_ast_table_entry.table_ref IS 'the name argument exactly as written. A bare @table writes no row: the author is asking for the table name to be deduced from the type''s own, which is a thing they said and which the absence of a row here is what records';
COMMENT ON COLUMN graphitron_ast_table_entry.table_ref_namespace_part IS 'the schema half of the written name, or NULL where none was written; split by QualifiedNameGrammar, which only cuts the string';
COMMENT ON COLUMN graphitron_ast_table_entry.table_ref_name_part IS 'the table half of the same';
COMMENT ON COLUMN graphitron_ast_table_entry.table_ref_namespace_part_upper IS 'the upper-cased form of the column beside it, for the case-insensitive match against sql_table''s table_schema_upper. Generated, so nothing writes it and nothing can. NULL where the column beside it is, which is an unqualified spelling and is admitted against any schema the graph''s sources carry';
COMMENT ON COLUMN graphitron_ast_table_entry.table_ref_name_part_upper IS 'the upper-cased form of the column beside it, for the case-insensitive match against sql_table''s table_name_upper. Generated, so nothing writes it and nothing can. It exists because an authored spelling meets a catalog name here, which is the only reason anything in this schema is folded';

CREATE TABLE graphitron_ast_scalar_type_entry (
  graph_name    VARCHAR NOT NULL,
  source_name   VARCHAR NOT NULL,
  source_line   INT     NOT NULL,
  source_column INT     NOT NULL,
  touched_at    TIMESTAMP NOT NULL,
  scalar_ref    VARCHAR NOT NULL,
  scalar_ref_class_part VARCHAR,
  scalar_ref_field_part VARCHAR,
  PRIMARY KEY (graph_name, source_name, source_line, source_column),
  FOREIGN KEY (graph_name) REFERENCES store_graph (graph_name),
  FOREIGN KEY (graph_name, source_name, source_line, source_column)
    REFERENCES graphql_ast_directive_application_entry (graph_name, source_name, source_line, source_column)
    ON DELETE CASCADE
);
COMMENT ON TABLE graphitron_ast_scalar_type_entry IS 'What a @scalarType application says: the constant holding the scalar this declaration is bound to, as written. For example scalar Money @scalarType(scalar: "com.example.Scalars.MONEY") gives one row.';
COMMENT ON COLUMN graphitron_ast_scalar_type_entry.graph_name IS 'the owning graph''s partition, anchored by store_graph; the leading key dimension that keeps one workspace''s graphs apart';
COMMENT ON COLUMN graphitron_ast_scalar_type_entry.source_name IS 'the file the application was written in';
COMMENT ON COLUMN graphitron_ast_scalar_type_entry.source_line IS 'source line of the at sign, 1-based per the graphql-java convention';
COMMENT ON COLUMN graphitron_ast_scalar_type_entry.source_column IS 'source column of the same. The four key columns are the applied directive''s own key, so this row is the decode of exactly one row of graphql_ast_directive_application_entry and neither carries what the other holds';
COMMENT ON COLUMN graphitron_ast_scalar_type_entry.touched_at IS 'when the reading that produced this row ran. The reading finishes by deleting its file''s rows carrying an older instant, which are the applications the author removed or renamed in place; an application the author moved is swept with the directive row it hangs on';
COMMENT ON COLUMN graphitron_ast_scalar_type_entry.scalar_ref IS 'the scalar argument exactly as written. Required by the definition, so an application omitting it asserts nothing and writes no row; the applied-directive row says it was applied and the argument''s own value says what was written instead';
COMMENT ON COLUMN graphitron_ast_scalar_type_entry.scalar_ref_class_part IS 'the class half of the written constant, or NULL where the string does not split; ConstantReferenceGrammar only cuts it';
COMMENT ON COLUMN graphitron_ast_scalar_type_entry.scalar_ref_field_part IS 'the field half of the same';

CREATE TABLE graphitron_ast_enum_entry (
  graph_name    VARCHAR NOT NULL,
  source_name   VARCHAR NOT NULL,
  source_line   INT     NOT NULL,
  source_column INT     NOT NULL,
  touched_at    TIMESTAMP NOT NULL,
  class_name    VARCHAR NOT NULL,
  method        VARCHAR,
  argmapping    VARCHAR,
  PRIMARY KEY (graph_name, source_name, source_line, source_column),
  FOREIGN KEY (graph_name) REFERENCES store_graph (graph_name),
  FOREIGN KEY (graph_name, source_name, source_line, source_column)
    REFERENCES graphql_ast_directive_application_entry (graph_name, source_name, source_line, source_column)
    ON DELETE CASCADE
);
COMMENT ON TABLE graphitron_ast_enum_entry IS 'What an @enum application says: the external code reference this enum declaration is bound to, as written. For example enum Rating @enum(enumReference: {className: "com.example.Ratings"}) gives one row.';
COMMENT ON COLUMN graphitron_ast_enum_entry.graph_name IS 'the owning graph''s partition, anchored by store_graph; the leading key dimension that keeps one workspace''s graphs apart';
COMMENT ON COLUMN graphitron_ast_enum_entry.source_name IS 'the file the application was written in';
COMMENT ON COLUMN graphitron_ast_enum_entry.source_line IS 'source line of the at sign, 1-based per the graphql-java convention';
COMMENT ON COLUMN graphitron_ast_enum_entry.source_column IS 'source column of the same. The four key columns are the applied directive''s own key, so this row is the decode of exactly one row of graphql_ast_directive_application_entry and neither carries what the other holds';
COMMENT ON COLUMN graphitron_ast_enum_entry.touched_at IS 'when the reading that produced this row ran. The reading finishes by deleting its file''s rows carrying an older instant, which are the applications the author removed or renamed in place; an application the author moved is swept with the directive row it hangs on';
COMMENT ON COLUMN graphitron_ast_enum_entry.class_name IS 'the className field of the reference, as written. The identity of the fact this row states, so an application naming no class writes no row rather than a row nothing identifies';
COMMENT ON COLUMN graphitron_ast_enum_entry.method IS 'the method field of the reference, as written, or NULL where none was';
COMMENT ON COLUMN graphitron_ast_enum_entry.argmapping IS 'the argMapping field of the reference, as written, or NULL where none was. Kept as the one string the author typed; what its segments name is a question for the argument-mapping derivation';

CREATE TABLE graphitron_ast_error_entry (
  graph_name    VARCHAR NOT NULL,
  source_name   VARCHAR NOT NULL,
  source_line   INT     NOT NULL,
  source_column INT     NOT NULL,
  touched_at    TIMESTAMP NOT NULL,
  PRIMARY KEY (graph_name, source_name, source_line, source_column),
  FOREIGN KEY (graph_name) REFERENCES store_graph (graph_name),
  FOREIGN KEY (graph_name, source_name, source_line, source_column)
    REFERENCES graphql_ast_directive_application_entry (graph_name, source_name, source_line, source_column)
    ON DELETE CASCADE
);
COMMENT ON TABLE graphitron_ast_error_entry IS 'One @error application, at its @ token. For example type FilmNotFound @error(handlers: [{handler: VALIDATION}]) gives one row, and its one handler is a row of graphitron_ast_error_handler_entry hanging off it.';
COMMENT ON COLUMN graphitron_ast_error_entry.graph_name IS 'the owning graph''s partition, anchored by store_graph; the leading key dimension that keeps one workspace''s graphs apart';
COMMENT ON COLUMN graphitron_ast_error_entry.source_name IS 'the file the application was written in';
COMMENT ON COLUMN graphitron_ast_error_entry.source_line IS 'source line of the at sign, 1-based per the graphql-java convention';
COMMENT ON COLUMN graphitron_ast_error_entry.source_column IS 'source column of the same. The four key columns are the applied directive''s own key, so this row is the decode of exactly one row of graphql_ast_directive_application_entry';
COMMENT ON COLUMN graphitron_ast_error_entry.touched_at IS 'when the reading that produced this row ran. The reading finishes by deleting its file''s rows carrying an older instant; an application the author moved is swept with the directive row it hangs on';

CREATE TABLE graphitron_ast_error_handler_entry (
  graph_name         VARCHAR NOT NULL,
  source_name        VARCHAR NOT NULL,
  source_line        INT     NOT NULL,
  source_column      INT     NOT NULL,
  touched_at         TIMESTAMP NOT NULL,
  application_line   INT     NOT NULL,
  application_column INT     NOT NULL,
  position           INT     NOT NULL,
  handler            VARCHAR NOT NULL,
  PRIMARY KEY (graph_name, source_name, source_line, source_column),
  UNIQUE (graph_name, source_name, application_line, application_column, position),
  CHECK (position >= 0),
  CHECK (handler IN ('GENERIC', 'DATABASE', 'VALIDATION')),
  FOREIGN KEY (graph_name) REFERENCES store_graph (graph_name),
  FOREIGN KEY (graph_name, source_name, source_line, source_column)
    REFERENCES graphql_ast_value_entry (graph_name, source_name, source_line, source_column)
    ON DELETE CASCADE,
  FOREIGN KEY (graph_name, source_name, application_line, application_column)
    REFERENCES graphitron_ast_error_entry (graph_name, source_name, source_line, source_column)
    ON DELETE CASCADE
);
COMMENT ON TABLE graphitron_ast_error_handler_entry IS 'One element of an @error application''s handlers list, with the kind it names. For example handlers: [{handler: DATABASE, sqlState: "23503"}, {handler: VALIDATION}] gives two rows, one of each kind, under the one application.';
COMMENT ON COLUMN graphitron_ast_error_handler_entry.graph_name IS 'the owning graph''s partition, anchored by store_graph; the leading key dimension that keeps one workspace''s graphs apart';
COMMENT ON COLUMN graphitron_ast_error_handler_entry.source_name IS 'the file the element was written in, which is the application''s file too';
COMMENT ON COLUMN graphitron_ast_error_handler_entry.source_line IS 'source line of the element this row decodes, 1-based per the graphql-java convention';
COMMENT ON COLUMN graphitron_ast_error_handler_entry.source_column IS 'source column of the same. The four columns are the element''s own key in graphql_ast_value_entry';
COMMENT ON COLUMN graphitron_ast_error_handler_entry.touched_at IS 'when the reading that produced this row ran. The reading finishes by deleting its file''s rows carrying an older instant; a handler whose application went is swept with the application row it hangs on';
COMMENT ON COLUMN graphitron_ast_error_handler_entry.application_line IS 'source line of the @error application holding the list, the parent key into graphitron_ast_error_entry together with the column beside it';
COMMENT ON COLUMN graphitron_ast_error_handler_entry.application_column IS 'source column of the same';
COMMENT ON COLUMN graphitron_ast_error_handler_entry.position IS 'the index the element was written at in its list, from 0. A list written as one object rather than a list is a list of that one object, at 0';
COMMENT ON COLUMN graphitron_ast_error_handler_entry.handler IS 'the kind the element names. The CHECK states an invariant rather than judging input: DirectiveLegality admits no application whose element names another kind or none, so the constraint costs nothing while that gate holds and fails at the row if it ever drifts. A VALIDATION element carries nothing beyond its kind, so this row is the whole of it';

CREATE TABLE graphitron_ast_error_generic_handler_entry (
  graph_name    VARCHAR NOT NULL,
  source_name   VARCHAR NOT NULL,
  source_line   INT     NOT NULL,
  source_column INT     NOT NULL,
  touched_at    TIMESTAMP NOT NULL,
  class_name    VARCHAR,
  matches       VARCHAR,
  description   VARCHAR,
  PRIMARY KEY (graph_name, source_name, source_line, source_column),
  FOREIGN KEY (graph_name) REFERENCES store_graph (graph_name),
  FOREIGN KEY (graph_name, source_name, source_line, source_column)
    REFERENCES graphitron_ast_error_handler_entry (graph_name, source_name, source_line, source_column)
    ON DELETE CASCADE
);
COMMENT ON TABLE graphitron_ast_error_generic_handler_entry IS 'A GENERIC handler of an @error application, at its position in the list, as written. For example {handler: GENERIC, className: "java.lang.IllegalStateException"} at position 0.';
COMMENT ON COLUMN graphitron_ast_error_generic_handler_entry.graph_name IS 'the owning graph''s partition, anchored by store_graph; the leading key dimension that keeps one workspace''s graphs apart';
COMMENT ON COLUMN graphitron_ast_error_generic_handler_entry.source_name IS 'the file the element was written in';
COMMENT ON COLUMN graphitron_ast_error_generic_handler_entry.source_line IS 'source line of the element this row decodes, 1-based per the graphql-java convention';
COMMENT ON COLUMN graphitron_ast_error_generic_handler_entry.source_column IS 'source column of the same. The four columns are the key of graphitron_ast_error_handler_entry, which names the element''s row of graphql_ast_value_entry and the application holding it, so this relation carries what the kind reads and nothing the supertype does';
COMMENT ON COLUMN graphitron_ast_error_generic_handler_entry.touched_at IS 'when the reading that produced this row ran. The reading finishes by deleting its file''s rows carrying an older instant; a handler whose whole application went is swept with the supertype row it hangs on';
COMMENT ON COLUMN graphitron_ast_error_generic_handler_entry.class_name IS 'the exception class this handler matches on, as written, or NULL where none was. A GENERIC handler naming no class is still a row, so its other fields are not lost; that it names none is a detection''s business';
COMMENT ON COLUMN graphitron_ast_error_generic_handler_entry.matches IS 'a substring the exception message must contain, as written, or NULL where the handler takes every exception of the class';
COMMENT ON COLUMN graphitron_ast_error_generic_handler_entry.description IS 'the client-facing message this handler returns, as written, or NULL where the exception''s own message is used';

-- The field site's decode. Every relation below is keyed by the position of the @ token, which is
-- graphql_ast_directive_application_entry's key, so a row is the decode of exactly one application there
-- and carries no type name, no field name and no file: all three are one join away. Five of the
-- site's seventeen directive names get no relation at all. @splitQuery, @tenantFanOut and
-- @globalData declare no argument, and @multitableReference is rejected before anything reads its
-- one argument, so a row under any of the four would carry its key and nothing else, which is what
-- the applied-directive row already says. @reference and @referenceFor are not decoded here: a path
-- is one grammar wherever it is written, so the path family below decodes both directives at every
-- site at once.
--
-- A list argument becomes a child relation, and a child hangs off the decode of the application it
-- was written inside, so deleting that decode takes its elements. A decode that carries nothing but
-- its key is not empty when children hang from it: it is what they reference and cascade from.
CREATE TABLE graphitron_ast_binding_entry (
  graph_name    VARCHAR NOT NULL,
  source_name   VARCHAR NOT NULL,
  source_line   INT     NOT NULL,
  source_column INT     NOT NULL,
  touched_at    TIMESTAMP NOT NULL,
  name_ref      VARCHAR NOT NULL,
  PRIMARY KEY (graph_name, source_name, source_line, source_column),
  FOREIGN KEY (graph_name) REFERENCES store_graph (graph_name),
  FOREIGN KEY (graph_name, source_name, source_line, source_column)
    REFERENCES graphql_ast_directive_application_entry (graph_name, source_name, source_line, source_column)
    ON DELETE CASCADE
);
COMMENT ON TABLE graphitron_ast_binding_entry IS 'What a @field application says: the name written, wherever it was written. For example title: String @field(name: "title") on an output field, films(titleFilter: String @field(name: "title")) on an argument and TITLE @field(name: "title") on an enum value give one row each, all reading title.';
COMMENT ON COLUMN graphitron_ast_binding_entry.graph_name IS 'the owning graph''s partition, anchored by store_graph; the leading key dimension that keeps one workspace''s graphs apart';
COMMENT ON COLUMN graphitron_ast_binding_entry.source_name IS 'the file the application was written in';
COMMENT ON COLUMN graphitron_ast_binding_entry.source_line IS 'source line of the at sign, 1-based per the graphql-java convention';
COMMENT ON COLUMN graphitron_ast_binding_entry.source_column IS 'source column of the same. The four key columns are the applied directive''s own key, so this row is the decode of exactly one row of graphql_ast_directive_application_entry and neither carries what the other holds';
COMMENT ON COLUMN graphitron_ast_binding_entry.touched_at IS 'when the reading that produced this row ran. The reading finishes by deleting its file''s rows carrying an older instant, which are the applications the author removed or renamed in place; an application the author moved is swept with the directive row it hangs on';
COMMENT ON COLUMN graphitron_ast_binding_entry.name_ref IS 'the name argument exactly as written. The definition requires it, so an application that omits it is malformed rather than meaning anything, and it writes no row here at all: the applied-directive row says the directive was applied and the argument''s own value says what was written instead';

CREATE TABLE graphitron_ast_node_id_entry (
  graph_name    VARCHAR NOT NULL,
  source_name   VARCHAR NOT NULL,
  source_line   INT     NOT NULL,
  source_column INT     NOT NULL,
  touched_at    TIMESTAMP NOT NULL,
  node_type_ref VARCHAR,
  PRIMARY KEY (graph_name, source_name, source_line, source_column),
  FOREIGN KEY (graph_name) REFERENCES store_graph (graph_name),
  FOREIGN KEY (graph_name, source_name, source_line, source_column)
    REFERENCES graphql_ast_directive_application_entry (graph_name, source_name, source_line, source_column)
    ON DELETE CASCADE
);
COMMENT ON TABLE graphitron_ast_node_id_entry IS 'What a @nodeId application says: the node type the identifier belongs to, as written, wherever it was written. For example id: ID! @nodeId(typeName: "Film") on an output field and actorId: ID @nodeId on an input field give one row each, the first reading Film and the second naming no type.';
COMMENT ON COLUMN graphitron_ast_node_id_entry.graph_name IS 'the owning graph''s partition, anchored by store_graph; the leading key dimension that keeps one workspace''s graphs apart';
COMMENT ON COLUMN graphitron_ast_node_id_entry.source_name IS 'the file the application was written in';
COMMENT ON COLUMN graphitron_ast_node_id_entry.source_line IS 'source line of the at sign, 1-based per the graphql-java convention';
COMMENT ON COLUMN graphitron_ast_node_id_entry.source_column IS 'source column of the same. The four key columns are the applied directive''s own key, so this row is the decode of exactly one row of graphql_ast_directive_application_entry and neither carries what the other holds';
COMMENT ON COLUMN graphitron_ast_node_id_entry.touched_at IS 'when the reading that produced this row ran. The reading finishes by deleting its file''s rows carrying an older instant, which are the applications the author removed or renamed in place; an application the author moved is swept with the directive row it hangs on';
COMMENT ON COLUMN graphitron_ast_node_id_entry.node_type_ref IS 'the typeName argument as written, or NULL on a bare @nodeId. The row is what says the directive was applied and the NULL is what says the author left the type to be inferred, which is a resolution over other relations and none of this one''s';

CREATE TABLE graphitron_ast_field_condition_entry (
  graph_name    VARCHAR NOT NULL,
  source_name   VARCHAR NOT NULL,
  source_line   INT     NOT NULL,
  source_column INT     NOT NULL,
  touched_at    TIMESTAMP NOT NULL,
  class_name    VARCHAR NOT NULL,
  method        VARCHAR,
  argmapping    VARCHAR,
  override      BOOLEAN,
  PRIMARY KEY (graph_name, source_name, source_line, source_column),
  FOREIGN KEY (graph_name) REFERENCES store_graph (graph_name),
  FOREIGN KEY (graph_name, source_name, source_line, source_column)
    REFERENCES graphql_ast_directive_application_entry (graph_name, source_name, source_line, source_column)
    ON DELETE CASCADE
);
COMMENT ON TABLE graphitron_ast_field_condition_entry IS 'What a @condition application on an output field says: the external method constraining the field''s query, as written. For example summary: String @condition(condition: {className: "no.example.Conditions", method: "visibleFilm"}) gives one row.';
COMMENT ON COLUMN graphitron_ast_field_condition_entry.graph_name IS 'the owning graph''s partition, anchored by store_graph; the leading key dimension that keeps one workspace''s graphs apart';
COMMENT ON COLUMN graphitron_ast_field_condition_entry.source_name IS 'the file the application was written in';
COMMENT ON COLUMN graphitron_ast_field_condition_entry.source_line IS 'source line of the at sign, 1-based per the graphql-java convention';
COMMENT ON COLUMN graphitron_ast_field_condition_entry.source_column IS 'source column of the same. The four key columns are the applied directive''s own key, so this row is the decode of exactly one row of graphql_ast_directive_application_entry and neither carries what the other holds';
COMMENT ON COLUMN graphitron_ast_field_condition_entry.touched_at IS 'when the reading that produced this row ran. The reading finishes by deleting its file''s rows carrying an older instant, which are the applications the author removed or renamed in place; an application the author moved is swept with the directive row it hangs on';
COMMENT ON COLUMN graphitron_ast_field_condition_entry.class_name IS 'the className field of the reference, as written';
COMMENT ON COLUMN graphitron_ast_field_condition_entry.method IS 'the method field of the same, as written, or NULL where none was';
COMMENT ON COLUMN graphitron_ast_field_condition_entry.argmapping IS 'the argMapping field of the same, kept as the one string the author typed. What its segments name is a question for the argument-mapping derivation, which is where the grammar that cuts it lives';
COMMENT ON COLUMN graphitron_ast_field_condition_entry.override IS 'the override argument as written, or NULL where the author wrote none. The definition''s own default is not supplied here: what an omitted argument falls back to stands in graphql_directive_argument.default_value_sdl, and filling it in would lose the difference between a default taken and a value written';

-- The path family: @reference and @referenceFor both carry path: [ReferenceElement!]!, at a field,
-- an argument and an input field alike, so their applications and their elements are decoded here
-- once rather than once per directive and site. Which directive and which site an application is
-- under is the applied-directive row's to say, one join away.
CREATE TABLE graphitron_ast_reference_entry (
  graph_name    VARCHAR NOT NULL,
  source_name   VARCHAR NOT NULL,
  source_line   INT     NOT NULL,
  source_column INT     NOT NULL,
  touched_at    TIMESTAMP NOT NULL,
  PRIMARY KEY (graph_name, source_name, source_line, source_column),
  FOREIGN KEY (graph_name) REFERENCES store_graph (graph_name),
  FOREIGN KEY (graph_name, source_name, source_line, source_column)
    REFERENCES graphql_ast_directive_application_entry (graph_name, source_name, source_line, source_column)
    ON DELETE CASCADE
);
COMMENT ON TABLE graphitron_ast_reference_entry IS 'One application of a directive that carries a path, @reference or @referenceFor, at whichever site it was written. For example @reference(path: [{table: "film_actor"}, {table: "actor"}]) on Film.actors gives one row at its at sign.';
COMMENT ON COLUMN graphitron_ast_reference_entry.graph_name IS 'the owning graph''s partition, anchored by store_graph; the leading key dimension that keeps one workspace''s graphs apart';
COMMENT ON COLUMN graphitron_ast_reference_entry.source_name IS 'the file the application was written in';
COMMENT ON COLUMN graphitron_ast_reference_entry.source_line IS 'source line of the at sign, 1-based per the graphql-java convention';
COMMENT ON COLUMN graphitron_ast_reference_entry.source_column IS 'source column of the same. The four columns are the applied directive''s own key, so which directive and which site this application is are one join away rather than columns here';
COMMENT ON COLUMN graphitron_ast_reference_entry.touched_at IS 'when the reading that produced this row ran. The reading finishes by deleting its file''s rows carrying an older instant; an application the author removed is swept with the directive row it hangs on, and its elements with it';

CREATE TABLE graphitron_ast_reference_element_entry (
  graph_name         VARCHAR NOT NULL,
  source_name        VARCHAR NOT NULL,
  source_line        INT     NOT NULL,
  source_column      INT     NOT NULL,
  touched_at         TIMESTAMP NOT NULL,
  application_line   INT     NOT NULL,
  application_column INT     NOT NULL,
  position           INT     NOT NULL,
  PRIMARY KEY (graph_name, source_name, source_line, source_column),
  UNIQUE (graph_name, source_name, application_line, application_column, position),
  FOREIGN KEY (graph_name) REFERENCES store_graph (graph_name),
  FOREIGN KEY (graph_name, source_name, source_line, source_column)
    REFERENCES graphql_ast_value_entry (graph_name, source_name, source_line, source_column)
    ON DELETE CASCADE,
  FOREIGN KEY (graph_name, source_name, application_line, application_column)
    REFERENCES graphitron_ast_reference_entry (graph_name, source_name, source_line, source_column)
    ON DELETE CASCADE,
  CHECK (position >= 0)
);
COMMENT ON TABLE graphitron_ast_reference_element_entry IS 'One element of the path an application of @reference or @referenceFor wrote, at its index in the list, whatever it says. For example @reference(path: [{table: "film_actor"}, {}, {key: "film_actor_actor_id_fk"}]) gives three rows at positions 0, 1 and 2, the second naming nothing.';
COMMENT ON COLUMN graphitron_ast_reference_element_entry.graph_name IS 'the owning graph''s partition, anchored by store_graph; the leading key dimension that keeps one workspace''s graphs apart';
COMMENT ON COLUMN graphitron_ast_reference_element_entry.source_name IS 'the file the element was written in, which is the application''s file too';
COMMENT ON COLUMN graphitron_ast_reference_element_entry.source_line IS 'source line of the element, 1-based per the graphql-java convention';
COMMENT ON COLUMN graphitron_ast_reference_element_entry.source_column IS 'source column of the same. The four columns are the element''s own key in graphql_ast_value_entry';
COMMENT ON COLUMN graphitron_ast_reference_element_entry.touched_at IS 'when the reading that produced this row ran. The reading finishes by deleting its file''s rows carrying an older instant; an element whose application went is swept with it';
COMMENT ON COLUMN graphitron_ast_reference_element_entry.application_line IS 'source line of the application the element was written in, the first half of its key in graphitron_ast_reference_entry; the file is the element''s own';
COMMENT ON COLUMN graphitron_ast_reference_element_entry.application_column IS 'source column of the same';
COMMENT ON COLUMN graphitron_ast_reference_element_entry.position IS 'the index the element was written at in its path, from 0. A path written as one object rather than a list is a list of that one object, at 0';

CREATE TABLE graphitron_ast_reference_table_step_entry (
  graph_name    VARCHAR NOT NULL,
  source_name   VARCHAR NOT NULL,
  source_line   INT     NOT NULL,
  source_column INT     NOT NULL,
  touched_at    TIMESTAMP NOT NULL,
  table_ref                VARCHAR NOT NULL,
  table_ref_namespace_part VARCHAR,
  table_ref_name_part      VARCHAR NOT NULL,
  table_ref_namespace_part_upper VARCHAR GENERATED ALWAYS AS (UPPER(table_ref_namespace_part)),
  table_ref_name_part_upper      VARCHAR GENERATED ALWAYS AS (UPPER(table_ref_name_part)),
  PRIMARY KEY (graph_name, source_name, source_line, source_column),
  FOREIGN KEY (graph_name) REFERENCES store_graph (graph_name),
  FOREIGN KEY (graph_name, source_name, source_line, source_column)
    REFERENCES graphitron_ast_reference_element_entry (graph_name, source_name, source_line, source_column)
    ON DELETE CASCADE
);
COMMENT ON TABLE graphitron_ast_reference_table_step_entry IS 'The table a path element of a @reference or @referenceFor application names, at any site, at its position in the list, as written. For example @reference(path: [{table: "film_actor"}, {table: "actor", key: "film_actor_actor_id_fk"}]) gives two rows.';
COMMENT ON COLUMN graphitron_ast_reference_table_step_entry.graph_name IS 'the owning graph''s partition, anchored by store_graph; the leading key dimension that keeps one workspace''s graphs apart';
COMMENT ON COLUMN graphitron_ast_reference_table_step_entry.source_name IS 'the file the element was written in';
COMMENT ON COLUMN graphitron_ast_reference_table_step_entry.source_line IS 'source line of the element this row decodes, 1-based per the graphql-java convention';
COMMENT ON COLUMN graphitron_ast_reference_table_step_entry.source_column IS 'source column of the same. The four columns are the element''s key in graphitron_ast_reference_element_entry, which holds the application it was written in and the index it was written at';
COMMENT ON COLUMN graphitron_ast_reference_table_step_entry.touched_at IS 'when the reading that produced this row ran. The reading finishes by deleting its file''s rows carrying an older instant; an element whose whole application went is swept with the directive row it hangs on';
COMMENT ON COLUMN graphitron_ast_reference_table_step_entry.table_ref IS 'the table field of the element as written. NOT NULL because a row exists exactly where the author named a table, which is what this relation says';
COMMENT ON COLUMN graphitron_ast_reference_table_step_entry.table_ref_namespace_part IS 'the schema half of the written name, or NULL where none was written; split by QualifiedNameGrammar, which only cuts the string';
COMMENT ON COLUMN graphitron_ast_reference_table_step_entry.table_ref_name_part IS 'the table half of the same, total because the grammar always yields one where a name was written';
COMMENT ON COLUMN graphitron_ast_reference_table_step_entry.table_ref_namespace_part_upper IS 'the upper-cased form of the column beside it, for the case-insensitive match against sql_table''s table_schema_upper. Generated, so nothing writes it and nothing can. NULL where the column beside it is, which is an unqualified spelling and is admitted against any schema the graph''s sources carry';
COMMENT ON COLUMN graphitron_ast_reference_table_step_entry.table_ref_name_part_upper IS 'the upper-cased form of the column beside it, for the case-insensitive match against sql_table''s table_name_upper. Generated, so nothing writes it and nothing can. It exists because an authored spelling meets a catalog name here, which is the only reason anything in this schema is folded';

CREATE TABLE graphitron_ast_reference_key_step_entry (
  graph_name    VARCHAR NOT NULL,
  source_name   VARCHAR NOT NULL,
  source_line   INT     NOT NULL,
  source_column INT     NOT NULL,
  touched_at    TIMESTAMP NOT NULL,
  key_ref                  VARCHAR NOT NULL,
  key_ref_namespace_part   VARCHAR,
  key_ref_name_part        VARCHAR NOT NULL,
  key_ref_namespace_part_upper VARCHAR GENERATED ALWAYS AS (UPPER(key_ref_namespace_part)),
  key_ref_name_part_upper      VARCHAR GENERATED ALWAYS AS (UPPER(key_ref_name_part)),
  PRIMARY KEY (graph_name, source_name, source_line, source_column),
  FOREIGN KEY (graph_name) REFERENCES store_graph (graph_name),
  FOREIGN KEY (graph_name, source_name, source_line, source_column)
    REFERENCES graphitron_ast_reference_element_entry (graph_name, source_name, source_line, source_column)
    ON DELETE CASCADE
);
COMMENT ON TABLE graphitron_ast_reference_key_step_entry IS 'The foreign key a path element of a @reference or @referenceFor application names, at any site, at its position in the list, as written. For example the second element of @reference(path: [{table: "film_actor"}, {table: "actor", key: "film_actor_actor_id_fk"}]) gives one row.';
COMMENT ON COLUMN graphitron_ast_reference_key_step_entry.graph_name IS 'the owning graph''s partition, anchored by store_graph; the leading key dimension that keeps one workspace''s graphs apart';
COMMENT ON COLUMN graphitron_ast_reference_key_step_entry.source_name IS 'the file the element was written in';
COMMENT ON COLUMN graphitron_ast_reference_key_step_entry.source_line IS 'source line of the element this row decodes, 1-based per the graphql-java convention';
COMMENT ON COLUMN graphitron_ast_reference_key_step_entry.source_column IS 'source column of the same. The four columns are the element''s key in graphitron_ast_reference_element_entry, which holds the application it was written in and the index it was written at';
COMMENT ON COLUMN graphitron_ast_reference_key_step_entry.touched_at IS 'when the reading that produced this row ran. The reading finishes by deleting its file''s rows carrying an older instant; an element whose whole application went is swept with the directive row it hangs on';
COMMENT ON COLUMN graphitron_ast_reference_key_step_entry.key_ref IS 'the key field of the element as written, naming a foreign-key constraint. NOT NULL because a row exists exactly where the author named one';
COMMENT ON COLUMN graphitron_ast_reference_key_step_entry.key_ref_namespace_part IS 'the schema half of the written name, which scopes the lookup to constraints held in that schema; NULL where none was written';
COMMENT ON COLUMN graphitron_ast_reference_key_step_entry.key_ref_name_part IS 'the constraint half of the same, total because the grammar always yields one where a name was written';
COMMENT ON COLUMN graphitron_ast_reference_key_step_entry.key_ref_namespace_part_upper IS 'the upper-cased form of the column beside it, for the case-insensitive match against sql_constraint''s table_schema_upper, a written qualifier naming the schema of the table holding the constraint rather than a namespace of the constraint''s own. Generated, so nothing writes it and nothing can. NULL where the column beside it is, which is an unqualified spelling and matches on its name half alone';
COMMENT ON COLUMN graphitron_ast_reference_key_step_entry.key_ref_name_part_upper IS 'the upper-cased form of the column beside it, for the case-insensitive match against sql_constraint''s constraint_name_upper and jooq_name_upper, in that precedence. Generated, so nothing writes it and nothing can. It exists because an authored spelling meets a catalog name here, which is the only reason anything in this schema is folded';

CREATE TABLE graphitron_ast_reference_condition_step_entry (
  graph_name    VARCHAR NOT NULL,
  source_name   VARCHAR NOT NULL,
  source_line   INT     NOT NULL,
  source_column INT     NOT NULL,
  touched_at    TIMESTAMP NOT NULL,
  class_name               VARCHAR,
  method                   VARCHAR,
  argmapping               VARCHAR,
  PRIMARY KEY (graph_name, source_name, source_line, source_column),
  FOREIGN KEY (graph_name) REFERENCES store_graph (graph_name),
  FOREIGN KEY (graph_name, source_name, source_line, source_column)
    REFERENCES graphitron_ast_reference_element_entry (graph_name, source_name, source_line, source_column)
    ON DELETE CASCADE
);
COMMENT ON TABLE graphitron_ast_reference_condition_step_entry IS 'The condition a path element of a @reference or @referenceFor application names, at any site, at its position in the list, as written. For example {table: "actor", condition: {className: "no.example.Conditions", method: "liveActor"}} gives one row here and one in the table relation.';
COMMENT ON COLUMN graphitron_ast_reference_condition_step_entry.graph_name IS 'the owning graph''s partition, anchored by store_graph; the leading key dimension that keeps one workspace''s graphs apart';
COMMENT ON COLUMN graphitron_ast_reference_condition_step_entry.source_name IS 'the file the element was written in';
COMMENT ON COLUMN graphitron_ast_reference_condition_step_entry.source_line IS 'source line of the element this row decodes, 1-based per the graphql-java convention';
COMMENT ON COLUMN graphitron_ast_reference_condition_step_entry.source_column IS 'source column of the same. The four columns are the element''s key in graphitron_ast_reference_element_entry, which holds the application it was written in and the index it was written at';
COMMENT ON COLUMN graphitron_ast_reference_condition_step_entry.touched_at IS 'when the reading that produced this row ran. The reading finishes by deleting its file''s rows carrying an older instant; an element whose whole application went is swept with the directive row it hangs on';
COMMENT ON COLUMN graphitron_ast_reference_condition_step_entry.class_name IS 'the className of the element''s condition reference, as written, or null where the author wrote a condition naming none: a row exists exactly where a condition object was written, and the reference''s className is optional in the vocabulary, so a condition with no class is a detection''s to state rather than a condition lost. This is the one arm of an element that reaches the classpath rather than the catalog';
COMMENT ON COLUMN graphitron_ast_reference_condition_step_entry.method IS 'the method of the same, as written, or NULL where none was';
COMMENT ON COLUMN graphitron_ast_reference_condition_step_entry.argmapping IS 'the argMapping of the same, kept as the one string the author typed; what its segments name is a question for the argument-mapping derivation';

CREATE TABLE graphitron_ast_reference_for_entry (
  graph_name    VARCHAR NOT NULL,
  source_name   VARCHAR NOT NULL,
  source_line   INT     NOT NULL,
  source_column INT     NOT NULL,
  touched_at    TIMESTAMP NOT NULL,
  participant_type_ref VARCHAR NOT NULL,
  PRIMARY KEY (graph_name, source_name, source_line, source_column),
  FOREIGN KEY (graph_name) REFERENCES store_graph (graph_name),
  FOREIGN KEY (graph_name, source_name, source_line, source_column)
    REFERENCES graphitron_ast_reference_entry (graph_name, source_name, source_line, source_column)
    ON DELETE CASCADE
);
COMMENT ON TABLE graphitron_ast_reference_for_entry IS 'What a @referenceFor application says, at any site: the participant type whose join path this application replaces, as written. For example media: [Media!] @referenceFor(type: "Book", path: [{table: "book"}]) gives one row reading Book.';
COMMENT ON COLUMN graphitron_ast_reference_for_entry.graph_name IS 'the owning graph''s partition, anchored by store_graph; the leading key dimension that keeps one workspace''s graphs apart';
COMMENT ON COLUMN graphitron_ast_reference_for_entry.source_name IS 'the file the application was written in';
COMMENT ON COLUMN graphitron_ast_reference_for_entry.source_line IS 'source line of the at sign, 1-based per the graphql-java convention';
COMMENT ON COLUMN graphitron_ast_reference_for_entry.source_column IS 'source column of the same. The four key columns are the applied directive''s own key, so this row adds the participant to exactly one row of graphitron_ast_reference_entry and neither carries what the other holds';
COMMENT ON COLUMN graphitron_ast_reference_for_entry.touched_at IS 'when the reading that produced this row ran. The reading finishes by deleting its file''s rows carrying an older instant, which are the applications the author removed or renamed in place; an application the author moved is swept with the directive row it hangs on';
COMMENT ON COLUMN graphitron_ast_reference_for_entry.participant_type_ref IS 'the type argument exactly as written, naming the participant this path applies to. Nullable although the definition marks it required, because a document that omits it still applied the directive. Two applications naming one participant are two rows here and the conflict is a detection over them, this relation refusing nothing';

CREATE TABLE graphitron_ast_field_path_entry (
  graph_name     VARCHAR NOT NULL,
  source_name    VARCHAR NOT NULL,
  field_line     INT     NOT NULL,
  field_column   INT     NOT NULL,
  position       INT     NOT NULL,
  element_line   INT     NOT NULL,
  element_column INT     NOT NULL,
  touched_at     TIMESTAMP NOT NULL,
  PRIMARY KEY (graph_name, source_name, field_line, field_column, position),
  -- Each element sits at one place in one field's path. A reader standing on an element asks for
  -- the one after it by where the element was written, which this serves.
  UNIQUE (graph_name, source_name, element_line, element_column),
  FOREIGN KEY (graph_name) REFERENCES store_graph (graph_name),
  FOREIGN KEY (graph_name, source_name, field_line, field_column)
    REFERENCES graphql_ast_field_definition_entry (graph_name, source_name, source_line, source_column)
    ON DELETE CASCADE,
  FOREIGN KEY (graph_name, source_name, element_line, element_column)
    REFERENCES graphql_ast_entry (graph_name, source_name, source_line, source_column)
    ON DELETE CASCADE,
  CHECK (position >= 0)
);
COMMENT ON TABLE graphitron_ast_field_path_entry IS 'One element of the path a field declaration wrote, at its place in that path: one row per element of the field''s @routine and @reference applications, composed in the order they were written. For example hopped @routine(name: "films_for_actor") @reference(path: [{table: "film"}]) gives two rows, the routine at 0 and the element at 1.';
COMMENT ON COLUMN graphitron_ast_field_path_entry.graph_name IS 'the owning graph''s partition, anchored by store_graph; the leading key dimension that keeps one workspace''s graphs apart';
COMMENT ON COLUMN graphitron_ast_field_path_entry.source_name IS 'the file the field was declared in, which holds every directive applied to it';
COMMENT ON COLUMN graphitron_ast_field_path_entry.field_line IS 'the field declaration''s source line, 1-based';
COMMENT ON COLUMN graphitron_ast_field_path_entry.field_column IS 'the field declaration''s source column; with the two columns before it, the declaration in graphql_ast_field_definition_entry, which names the type and the field';
COMMENT ON COLUMN graphitron_ast_field_path_entry.position IS 'the element''s place in the field''s path, numbered from zero across its @routine and @reference applications in the order they were written, each @reference application''s elements in their own order. Capture composes it, reading every directive on the field together, where a reader would have to rank the applications back into order; a @referenceFor path is a participant''s and no element of this one';
COMMENT ON COLUMN graphitron_ast_field_path_entry.element_line IS 'the element''s source line: a @routine application''s own, or a path element''s value node''s';
COMMENT ON COLUMN graphitron_ast_field_path_entry.element_column IS 'the element''s source column; with the line, the written position every decode of the element is keyed by, graphitron_ast_routine_entry''s for a routine and graphitron_ast_reference_element_entry''s and its steps'' for a path element';
COMMENT ON COLUMN graphitron_ast_field_path_entry.touched_at IS 'when the reading that produced this row ran. The reading finishes by deleting its file''s rows carrying an older instant';

CREATE TABLE graphitron_ast_path_entry (
  graph_name     VARCHAR NOT NULL,
  source_name    VARCHAR NOT NULL,
  anchor_line    INT     NOT NULL,
  anchor_column  INT     NOT NULL,
  place          INT     NOT NULL,
  element_line   INT     NOT NULL,
  element_column INT     NOT NULL,
  as_name        VARCHAR,
  touched_at     TIMESTAMP NOT NULL,
  PRIMARY KEY (graph_name, source_name, anchor_line, anchor_column, place),
  -- Each element sits at one place under one anchor; a reader standing on an element finds its
  -- anchor and its place by where the element was written.
  UNIQUE (graph_name, source_name, element_line, element_column),
  FOREIGN KEY (graph_name) REFERENCES store_graph (graph_name),
  -- The anchor and the element are written in the one file, so both positions key within it.
  FOREIGN KEY (graph_name, source_name, anchor_line, anchor_column)
    REFERENCES graphql_ast_entry (graph_name, source_name, source_line, source_column)
    ON DELETE CASCADE,
  FOREIGN KEY (graph_name, source_name, element_line, element_column)
    REFERENCES graphql_ast_entry (graph_name, source_name, source_line, source_column)
    ON DELETE CASCADE,
  CHECK (place >= 0)
);
COMMENT ON TABLE graphitron_ast_path_entry IS 'One element of one written path, at its place under the anchor that wrote it: a field declaration''s @routine and @reference applications composed in order, a @referenceFor application, an argument or an input field. For example Store.people @referenceFor(type: "Staff", path: [{key: "staff_store_id_fkey"}]) gives one row, the key element at place 0 under the @referenceFor application.';
COMMENT ON COLUMN graphitron_ast_path_entry.graph_name IS 'the owning graph''s partition, anchored by store_graph; the leading key dimension that keeps one workspace''s graphs apart';
COMMENT ON COLUMN graphitron_ast_path_entry.source_name IS 'the file the anchor was written in, which holds every element of its path';
COMMENT ON COLUMN graphitron_ast_path_entry.anchor_line IS 'the anchor''s source line, 1-based: a field declaration''s, a @referenceFor application''s at sign, an argument''s or an input field''s';
COMMENT ON COLUMN graphitron_ast_path_entry.anchor_column IS 'the anchor''s source column; with the line, a position in graphql_ast_entry within this file, and graphitron_join_path_claim names the same anchor by its declared element and target type for a reference from elsewhere';
COMMENT ON COLUMN graphitron_ast_path_entry.place IS 'the element''s place in its anchor''s path, numbered from zero in the order written; for a field declaration across its @routine and @reference applications, each application''s elements in their own order. A reference from another file names an element by its anchor and this place';
COMMENT ON COLUMN graphitron_ast_path_entry.element_line IS 'the element''s source line: a @routine application''s own, or a path element''s value node''s';
COMMENT ON COLUMN graphitron_ast_path_entry.element_column IS 'the element''s source column; with the line, the written position every decode of the element is keyed by, within this file';
COMMENT ON COLUMN graphitron_ast_path_entry.as_name IS 'the name the element''s as: argument gives it, which an argument or input field starting on this step names; NULL where none is written';
COMMENT ON COLUMN graphitron_ast_path_entry.touched_at IS 'when the reading that produced this row ran. The reading finishes by deleting its file''s rows carrying an older instant';

CREATE TABLE graphitron_ast_argmapping_pair_entry (
  graph_name    VARCHAR NOT NULL,
  source_name   VARCHAR NOT NULL,
  source_line   INT     NOT NULL,
  source_column INT     NOT NULL,
  position      INT     NOT NULL,
  touched_at    TIMESTAMP NOT NULL,
  param_name    VARCHAR NOT NULL,
  bound_to      VARCHAR NOT NULL,
  argument_name  VARCHAR NOT NULL,
  argument_index INT,
  path_index     INT,
  root_name     VARCHAR GENERATED ALWAYS AS (REGEXP_REPLACE(bound_to, '\..*$', '')),
  head_path     VARCHAR GENERATED ALWAYS AS
                  (CASE WHEN POSITION('.', bound_to) = 0 THEN NULL
                        ELSE REGEXP_REPLACE(bound_to, '\.[^.]*$', '') END),
  tail_name     VARCHAR GENERATED ALWAYS AS (REGEXP_REPLACE(bound_to, '^.*\.', '')),
  tail_name_upper VARCHAR GENERATED ALWAYS AS (UPPER(REGEXP_REPLACE(bound_to, '^.*\.', ''))),
  PRIMARY KEY (graph_name, source_name, source_line, source_column, position),
  FOREIGN KEY (graph_name) REFERENCES store_graph (graph_name),
  -- The string the mapping was written as, which the transcription already holds verbatim.
  FOREIGN KEY (graph_name, source_name, source_line, source_column)
    REFERENCES graphql_ast_value_entry (graph_name, source_name, source_line, source_column)
    ON DELETE CASCADE,
  CHECK (position >= 0)
);
COMMENT ON TABLE graphitron_ast_argmapping_pair_entry IS 'One entry of an argMapping as one document wrote it: at this position in this mapping, this parameter is bound to this. For example argMapping: "customerId: input.customerId, session: $session" gives two rows, customerId bound to input.customerId at position 0 and session to $session at 1.';
COMMENT ON COLUMN graphitron_ast_argmapping_pair_entry.graph_name IS 'the owning graph''s partition, anchored by store_graph; the leading key dimension that keeps one workspace''s graphs apart';
COMMENT ON COLUMN graphitron_ast_argmapping_pair_entry.source_name IS 'the file the mapping was written in';
COMMENT ON COLUMN graphitron_ast_argmapping_pair_entry.source_line IS 'source line of the string the mapping was written as, 1-based per the graphql-java convention';
COMMENT ON COLUMN graphitron_ast_argmapping_pair_entry.source_column IS 'source column of the same. The four columns are that string''s key in graphql_ast_value_entry, which holds it verbatim, so the directive or reference it was written in is a join from here and the raw text is not repeated';
COMMENT ON COLUMN graphitron_ast_argmapping_pair_entry.position IS 'the entry''s 0-based position in the mapping as written, completing the key; the order an author wrote the entries in';
COMMENT ON COLUMN graphitron_ast_argmapping_pair_entry.touched_at IS 'when the reading that produced this row ran. The reading finishes by deleting its file''s rows carrying an older instant; a mapping whose string went is swept with it';
COMMENT ON COLUMN graphitron_ast_argmapping_pair_entry.param_name IS 'the parameter the entry names, as written: a Java parameter at a code reference, a routine parameter at @routine';
COMMENT ON COLUMN graphitron_ast_argmapping_pair_entry.root_name IS 'the first segment of what the entry binds to, which at a site rooted on a field is the argument the value enters through. Generated, so nothing writes it and nothing can';
COMMENT ON COLUMN graphitron_ast_argmapping_pair_entry.head_path IS 'what the entry binds to with its last segment removed, NULL where it is one segment. Generated. The position an author had resolved when the whole path does not';
COMMENT ON COLUMN graphitron_ast_argmapping_pair_entry.tail_name IS 'the last segment of what the entry binds to, the whole of it where there is one. Generated';
COMMENT ON COLUMN graphitron_ast_argmapping_pair_entry.tail_name_upper IS 'the upper-cased form of the column beside it, for the one crossing where an authored spelling meets a catalog name: a trailing name matched against a node type''s key columns. Generated, the expression repeated rather than read, a generated column not being allowed to read another';
COMMENT ON COLUMN graphitron_ast_argmapping_pair_entry.bound_to IS 'what the entry binds the parameter to, as written: a dotted path into the arguments, or a sigil such as $session. Which sites admit a sigil is a rule about the site and not about the string, so nothing here judges it';
COMMENT ON COLUMN graphitron_ast_argmapping_pair_entry.argument_name IS 'the application''s argument the mapping string is written under: the code reference''s argument, service or condition or path, where the string is a reference''s field, and argMapping where the application takes it as its own, as @routine and @outbox do';
COMMENT ON COLUMN graphitron_ast_argmapping_pair_entry.argument_index IS 'the string''s index in its argument''s list, NULL where the argument is no list: the path element whose reference it is a field of';
COMMENT ON COLUMN graphitron_ast_argmapping_pair_entry.path_index IS 'the string''s index in a path below its argument, NULL where it sits in none';

CREATE TABLE graphitron_ast_code_reference_entry (
  graph_name    VARCHAR NOT NULL,
  source_name   VARCHAR NOT NULL,
  source_line   INT     NOT NULL,
  source_column INT     NOT NULL,
  touched_at    TIMESTAMP NOT NULL,
  class_name    VARCHAR NOT NULL,
  method        VARCHAR,
  argument_name  VARCHAR NOT NULL,
  argument_index INT,
  path_index     INT,
  PRIMARY KEY (graph_name, source_name, source_line, source_column),
  FOREIGN KEY (graph_name) REFERENCES store_graph (graph_name),
  -- The node the reference was written as, an object value, is a position, and this is the
  -- relation that holds every position.
  FOREIGN KEY (graph_name, source_name, source_line, source_column)
    REFERENCES graphql_ast_entry (graph_name, source_name, source_line, source_column)
    ON DELETE CASCADE
);
COMMENT ON TABLE graphitron_ast_code_reference_entry IS 'A Java code reference as one document wrote it: this position names this class and, where it says, this method. For example @service(service: {className: "no.example.FilmService", method: "films"}) gives one row at the object value, and @enum(enumReference: {className: "no.example.Rating"}) gives one naming no method.';
COMMENT ON COLUMN graphitron_ast_code_reference_entry.graph_name IS 'the owning graph''s partition, anchored by store_graph; the leading key dimension that keeps one workspace''s graphs apart';
COMMENT ON COLUMN graphitron_ast_code_reference_entry.source_name IS 'the file the reference was written in';
COMMENT ON COLUMN graphitron_ast_code_reference_entry.source_line IS 'source line of the node the reference was written as, 1-based per the graphql-java convention';
COMMENT ON COLUMN graphitron_ast_code_reference_entry.source_column IS 'source column of the same. The four columns are a graphql_ast_entry key: the ExternalCodeReference object value wherever one is written, so which directive and which argument wrote the reference are joins from here rather than columns';
COMMENT ON COLUMN graphitron_ast_code_reference_entry.touched_at IS 'when the reading that produced this row ran. The reading finishes by deleting its file''s rows carrying an older instant; a reference whose node went is swept with that node';
COMMENT ON COLUMN graphitron_ast_code_reference_entry.class_name IS 'the class the reference names, as written. NOT NULL because a reference naming no class asserts nothing this relation can hold, and writes no row';
COMMENT ON COLUMN graphitron_ast_code_reference_entry.method IS 'the method the reference names, as written, or NULL where it names none. A default a site applies to an omitted method is a resolution and is not applied here';
COMMENT ON COLUMN graphitron_ast_code_reference_entry.argument_name IS 'the application''s argument the reference is written under: service, condition, reference, enumReference, record, path, fields or routes. With the two indices, the names that tell the references of one application apart, read off the vocabulary walk rather than climbed back to from the position';
COMMENT ON COLUMN graphitron_ast_code_reference_entry.argument_index IS 'the reference''s index in its argument''s list, NULL where the argument is no list: the path element under @reference(path:), the field under @order(fields:), the route under @multitableReference(routes:)';
COMMENT ON COLUMN graphitron_ast_code_reference_entry.path_index IS 'the reference''s index in a path below its argument, NULL where it sits in none: the condition in fields[1].path[0] is 0. An argument that is itself the path has its index as argument_index';

CREATE VIEW graphitron_argmapping_site_rule
  (graph_name, coordinate, directive_name, ordinal, owner, kind, element_kind,
   source_name, source_line, source_column) AS
SELECT v.graph_name, el.coordinate, da.name, gd.ordinal,
       m.argument_name
         || COALESCE('.' || CAST(m.argument_index AS VARCHAR), '')
         || COALESCE('.path.' || CAST(m.path_index AS VARCHAR), ''),
       CASE WHEN m.argument_index IS NULL THEN 'ROOT'
            WHEN m.argument_name = 'path' THEN 'PATH_ELEMENT'
            WHEN m.argument_name = 'fields' AND m.path_index IS NULL THEN 'ORDER_FIELD'
            WHEN m.argument_name = 'fields' THEN 'ORDER_FIELD_PATH'
            WHEN m.argument_name = 'routes' THEN 'ROUTE_PATH' END,
       en.entry_kind, v.source_name, v.source_line, v.source_column
  FROM (SELECT DISTINCT graph_name, source_name, source_line, source_column, argument_name,
               argument_index, path_index
          FROM graphitron_ast_argmapping_pair_entry) m
  JOIN graphql_ast_value_entry v
    ON v.graph_name = m.graph_name AND v.source_name = m.source_name
   AND v.source_line = m.source_line AND v.source_column = m.source_column
  -- The applied argument holding the string, at any depth, and the application it belongs to.
  JOIN graphql_ast_entry arg
    ON arg.graph_name = v.graph_name AND arg.source_name = v.source_name
   AND arg.source_line = v.holder_line AND arg.source_column = v.holder_column
  JOIN graphql_ast_directive_application_entry da
    ON da.graph_name = arg.graph_name AND da.source_name = arg.source_name
   AND da.source_line = arg.parent_line AND da.source_column = arg.parent_column
  JOIN graphql_ast_entry an
    ON an.graph_name = da.graph_name AND an.source_name = da.source_name
   AND an.source_line = da.source_line AND an.source_column = da.source_column
  JOIN graphql_ast_element_entry el
    ON el.graph_name = an.graph_name AND el.source_name = an.source_name
   AND el.source_line = an.parent_line AND el.source_column = an.parent_column
  JOIN graphql_ast_entry en
    ON en.graph_name = el.graph_name AND en.source_name = el.source_name
   AND en.source_line = el.source_line AND en.source_column = el.source_column
  -- The application anchored: where it was written names its element, directive and ordinal.
  JOIN graphql_directive_application gd
    ON gd.graph_name = da.graph_name AND gd.source_name = da.source_name
   AND gd.source_line = da.source_line AND gd.source_column = da.source_column
   AND gd.directive_name = da.name;
COMMENT ON VIEW graphitron_argmapping_site_rule IS 'One row the climb from a written argMapping to where it sits computes, in the shape graphitron_argmapping_site stores: the rule itself, evaluated on demand rather than read off disk. For example the graphitron anchor inserts this view''s rows for one graph into graphitron_argmapping_site, which is the name every reader spells.';
-- COMMENT ON COLUMN graphitron_argmapping_site_rule.graph_name IS 'the graph_name of a row of this rule, which the anchor writes into graphitron_argmapping_site.graph_name';
-- COMMENT ON COLUMN graphitron_argmapping_site_rule.coordinate IS 'the coordinate of a row of this rule, which the anchor writes into graphitron_argmapping_site.coordinate';
-- COMMENT ON COLUMN graphitron_argmapping_site_rule.directive_name IS 'the directive_name of a row of this rule, which the anchor writes into graphitron_argmapping_site.directive_name';
-- COMMENT ON COLUMN graphitron_argmapping_site_rule.ordinal IS 'the ordinal of a row of this rule, which the anchor writes into graphitron_argmapping_site.ordinal';
-- COMMENT ON COLUMN graphitron_argmapping_site_rule.owner IS 'the owner of a row of this rule, which the anchor writes into graphitron_argmapping_site.owner';
-- COMMENT ON COLUMN graphitron_argmapping_site_rule.kind IS 'the kind of a row of this rule, which the anchor writes into graphitron_argmapping_site.kind';
-- COMMENT ON COLUMN graphitron_argmapping_site_rule.element_kind IS 'the element_kind of a row of this rule, which the anchor writes into graphitron_argmapping_site.element_kind';
-- COMMENT ON COLUMN graphitron_argmapping_site_rule.source_name IS 'the source_name of a row of this rule, which the anchor writes into graphitron_argmapping_site.source_name';
-- COMMENT ON COLUMN graphitron_argmapping_site_rule.source_line IS 'the source_line of a row of this rule, which the anchor writes into graphitron_argmapping_site.source_line';
-- COMMENT ON COLUMN graphitron_argmapping_site_rule.source_column IS 'the source_column of a row of this rule, which the anchor writes into graphitron_argmapping_site.source_column';

CREATE TABLE graphitron_argmapping_site (
  graph_name       VARCHAR NOT NULL,
  coordinate       VARCHAR NOT NULL,
  directive_name   VARCHAR NOT NULL,
  ordinal          INT     NOT NULL,
  owner            VARCHAR NOT NULL,
  kind             VARCHAR NOT NULL,
  element_kind     VARCHAR NOT NULL,
  source_name      VARCHAR NOT NULL,
  source_line      INT     NOT NULL,
  source_column    INT     NOT NULL,
  touched_at       TIMESTAMP NOT NULL,
  -- A mapping is named by its application and what it is written under there, the code reference
  -- whose field it is, or the application itself where it takes the mapping as its own.
  PRIMARY KEY (graph_name, coordinate, directive_name, ordinal, owner),
  -- Where the string was written, for a reader holding a pair entry to find its mapping by.
  UNIQUE (graph_name, source_name, source_line, source_column),
  FOREIGN KEY (graph_name, coordinate, directive_name, ordinal)
    REFERENCES graphql_directive_application (graph_name, coordinate, directive_name, ordinal)
    ON DELETE CASCADE,
  -- The string as written, so where a mapping sits cannot outlive the mapping.
  FOREIGN KEY (graph_name, source_name, source_line, source_column)
    REFERENCES graphql_ast_value_entry (graph_name, source_name, source_line, source_column)
    ON DELETE CASCADE,
  CHECK (kind IN ('ROOT', 'PATH_ELEMENT', 'ORDER_FIELD', 'ORDER_FIELD_PATH', 'ROUTE_PATH'))
);
-- A @routine's mapping is found from the application it is written on.
CREATE INDEX graphitron_argmapping_site_application_ix
  ON graphitron_argmapping_site (graph_name, coordinate, directive_name, ordinal);
COMMENT ON TABLE graphitron_argmapping_site IS 'Where one written argMapping sits: the directive and its repeat, the element it is written on, the code reference it is a field of and the path element that reference sits in. For example @reference(path: [{table: "film", condition: {className: "no.example.Conditions", method: "byActor", argMapping: "actorId: id"}}]) on Actor.films sits under reference at ordinal 0, on Actor.films, in the condition''s reference, at step 0.';
COMMENT ON COLUMN graphitron_argmapping_site.graph_name IS 'the owning graph''s partition, carried from the written mapping';
COMMENT ON COLUMN graphitron_argmapping_site.source_name IS 'the file the mapping was written in; with the line and the column, where the string sits, an attribute a reader holding a pair entry finds its mapping by and a defect points at, unique but no longer the key';
COMMENT ON COLUMN graphitron_argmapping_site.source_line IS 'source line of the string the mapping was written as';
COMMENT ON COLUMN graphitron_argmapping_site.source_column IS 'source column of the same';
COMMENT ON COLUMN graphitron_argmapping_site.directive_name IS 'the directive whose application wrote the mapping, reached through the argument holding the string at any depth';
COMMENT ON COLUMN graphitron_argmapping_site.ordinal IS 'that application''s repeat on its element, as graphql_directive_application numbers it, which is what tells two applications of a repeatable directive on one element apart';
COMMENT ON COLUMN graphitron_argmapping_site.coordinate IS 'the element the application is written on, as graphql_ast_element_entry spells it';
COMMENT ON COLUMN graphitron_argmapping_site.element_kind IS 'what kind of element that is, a field, an argument, an input field or a type, as graphql_ast_entry names its kinds';
COMMENT ON COLUMN graphitron_argmapping_site.owner IS 'what the mapping is written under in its application, spelled as graphitron_code_reference''s owner, completing the key: the code reference whose field the string is (service, path.0), so a mapping and its reference share a key, or argMapping where the application takes the mapping as its own, as @routine and @outbox do';
COMMENT ON COLUMN graphitron_argmapping_site.kind IS 'which owner that is, as graphitron_code_reference''s kind: ROOT on the application, PATH_ELEMENT on a path element''s reference';
COMMENT ON COLUMN graphitron_argmapping_site.touched_at IS 'when the reading that derived this row ran. Swept per graph after the reading upserts, so a mapping whose site no longer derives leaves; a mapping the author removed goes through the cascade on its written string';

CREATE VIEW graphitron_code_reference_site
  (graph_name, source_name, source_line, source_column,
   directive_name, coordinate, type_name, field_name, class_name, method_name,
   ordinal, owner, kind) AS
SELECT w.graph_name, w.source_name, w.source_line, w.source_column,
       da.name, el.coordinate, ef.type_name, ef.field_name, w.class_name,
       -- The one site whose omitted method has a default: an @externalField names its field.
       COALESCE(w.method, CASE WHEN da.name = 'externalField' THEN ef.field_name END),
       app.ordinal,
       -- The names the reference was written under, spelled: the argument, its index in the
       -- argument's list, its index in a path below it.
       w.argument_name
         || COALESCE('.' || CAST(w.argument_index AS VARCHAR), '')
         || COALESCE('.path.' || CAST(w.path_index AS VARCHAR), ''),
       CASE WHEN w.argument_index IS NULL THEN 'ROOT'
            WHEN w.argument_name = 'path' THEN 'PATH_ELEMENT'
            WHEN w.argument_name = 'fields' AND w.path_index IS NULL THEN 'ORDER_FIELD'
            WHEN w.argument_name = 'fields' THEN 'ORDER_FIELD_PATH'
            WHEN w.argument_name = 'routes' THEN 'ROUTE_PATH' END
  FROM (
    -- The value's holder is the applied argument, at any depth, and the argument's parent is the
    -- application.
    SELECT r.graph_name, r.source_name, r.source_line, r.source_column, r.class_name, r.method,
           r.argument_name, r.argument_index, r.path_index,
           arg.parent_line AS application_line, arg.parent_column AS application_column
      FROM graphitron_ast_code_reference_entry r
      JOIN graphql_ast_value_entry v
        ON v.graph_name = r.graph_name AND v.source_name = r.source_name
       AND v.source_line = r.source_line AND v.source_column = r.source_column
      JOIN graphql_ast_entry arg
        ON arg.graph_name = v.graph_name AND arg.source_name = v.source_name
       AND arg.source_line = v.holder_line AND arg.source_column = v.holder_column
  ) w
  JOIN graphql_ast_directive_application_entry da
    ON da.graph_name = w.graph_name AND da.source_name = w.source_name
   AND da.source_line = w.application_line AND da.source_column = w.application_column
  JOIN graphql_ast_entry an
    ON an.graph_name = da.graph_name AND an.source_name = da.source_name
   AND an.source_line = da.source_line AND an.source_column = da.source_column
  JOIN graphql_ast_element_entry el
    ON el.graph_name = an.graph_name AND el.source_name = an.source_name
   AND el.source_line = an.parent_line AND el.source_column = an.parent_column
  -- The application anchored: where it was written names its element, directive and ordinal.
  JOIN graphql_directive_application app
    ON app.graph_name = da.graph_name AND app.source_name = da.source_name
   AND app.source_line = da.source_line AND app.source_column = da.source_column
  LEFT JOIN graphql_element_field ef
    ON ef.graph_name = el.graph_name AND ef.coordinate = el.coordinate;
COMMENT ON VIEW graphitron_code_reference_site IS 'Where one written Java code reference sits: the directive that wrote it, the element it is on, and the method it names once that site''s default applies. For example isEnglish: Boolean @externalField(reference: {className: "no.example.FilmExtensions"}) sits at Film.isEnglish under externalField and names isEnglish.';
-- COMMENT ON COLUMN graphitron_code_reference_site.graph_name IS 'the owning graph''s partition, carried from the written reference';
-- COMMENT ON COLUMN graphitron_code_reference_site.source_name IS 'the file the reference was written in, the first of the four columns that are the written reference''s key';
-- COMMENT ON COLUMN graphitron_code_reference_site.source_line IS 'source line of the node the reference was written as';
-- COMMENT ON COLUMN graphitron_code_reference_site.source_column IS 'source column of the same, completing the key';
-- COMMENT ON COLUMN graphitron_code_reference_site.directive_name IS 'the directive whose application wrote the reference, reached through the argument that holds it';
-- COMMENT ON COLUMN graphitron_code_reference_site.coordinate IS 'the element the application is written on, as graphql_ast_element_entry spells it: a type, a field, an argument or an input field';
-- COMMENT ON COLUMN graphitron_code_reference_site.type_name IS 'the type owning that element where the element is a field or an argument, NULL where it is a type';
-- COMMENT ON COLUMN graphitron_code_reference_site.field_name IS 'the field that element is or belongs to, NULL where it is a type';
-- COMMENT ON COLUMN graphitron_code_reference_site.class_name IS 'the class the reference names, as written';
-- COMMENT ON COLUMN graphitron_code_reference_site.method_name IS 'the method the reference names: as written, or the field''s own name where an @externalField wrote none, which is the one default any site applies. NULL where the reference names a class only, as @enum does';
-- COMMENT ON COLUMN graphitron_code_reference_site.ordinal IS 'the application''s ordinal, graphql_directive_application''s, which with the coordinate and the directive names the application';
-- COMMENT ON COLUMN graphitron_code_reference_site.owner IS 'the names the reference was written under in its application, spelled: service for a root reference, path.0 for a path element''s condition, fields.1 for an @order field''s method, fields.1.path.0 for a condition in that field''s path';
-- COMMENT ON COLUMN graphitron_code_reference_site.kind IS 'which of those the reference is: ROOT, PATH_ELEMENT, ORDER_FIELD, ORDER_FIELD_PATH, or ROUTE_PATH under the removed @multitableReference';

CREATE TABLE graphitron_ast_connection_entry (
  graph_name    VARCHAR NOT NULL,
  source_name   VARCHAR NOT NULL,
  source_line   INT     NOT NULL,
  source_column INT     NOT NULL,
  touched_at    TIMESTAMP NOT NULL,
  default_first_value INT,
  connection_name     VARCHAR,
  PRIMARY KEY (graph_name, source_name, source_line, source_column),
  FOREIGN KEY (graph_name) REFERENCES store_graph (graph_name),
  FOREIGN KEY (graph_name, source_name, source_line, source_column)
    REFERENCES graphql_ast_directive_application_entry (graph_name, source_name, source_line, source_column)
    ON DELETE CASCADE
);
COMMENT ON TABLE graphitron_ast_connection_entry IS 'What an @asConnection application says: the page size the field defaults to and the Connection type name it overrides, as written. For example films: [Film!] @asConnection(defaultFirstValue: 25) gives one row reading 25.';
COMMENT ON COLUMN graphitron_ast_connection_entry.graph_name IS 'the owning graph''s partition, anchored by store_graph; the leading key dimension that keeps one workspace''s graphs apart';
COMMENT ON COLUMN graphitron_ast_connection_entry.source_name IS 'the file the application was written in';
COMMENT ON COLUMN graphitron_ast_connection_entry.source_line IS 'source line of the at sign, 1-based per the graphql-java convention';
COMMENT ON COLUMN graphitron_ast_connection_entry.source_column IS 'source column of the same. The four key columns are the applied directive''s own key, so this row is the decode of exactly one row of graphql_ast_directive_application_entry and neither carries what the other holds';
COMMENT ON COLUMN graphitron_ast_connection_entry.touched_at IS 'when the reading that produced this row ran. The reading finishes by deleting its file''s rows carrying an older instant, which are the applications the author removed or renamed in place; an application the author moved is swept with the directive row it hangs on';
COMMENT ON COLUMN graphitron_ast_connection_entry.default_first_value IS 'the defaultFirstValue argument as written, or NULL where the author wrote none. The definition''s own default of 100 is not supplied here: it stands in graphql_directive_argument.default_value_sdl, and filling it in would lose the difference between a default taken and a value written. A bare @asConnection is therefore a row of two nulls, which is what says the directive was applied with nothing said';
COMMENT ON COLUMN graphitron_ast_connection_entry.connection_name IS 'the connectionName argument as written, or NULL where the author wrote none. The argument is deprecated and the deprecation is the directive definition''s to state; a transcription records the value and says nothing about whether it should have been written';

CREATE TABLE graphitron_ast_mutation_entry (
  graph_name    VARCHAR NOT NULL,
  source_name   VARCHAR NOT NULL,
  source_line   INT     NOT NULL,
  source_column INT     NOT NULL,
  touched_at    TIMESTAMP NOT NULL,
  operation     VARCHAR NOT NULL,
  multi_row     BOOLEAN,
  fail_on_missing BOOLEAN,
  table_ref     VARCHAR,
  table_ref_namespace_part VARCHAR,
  table_ref_name_part      VARCHAR,
  PRIMARY KEY (graph_name, source_name, source_line, source_column),
  FOREIGN KEY (graph_name) REFERENCES store_graph (graph_name),
  FOREIGN KEY (graph_name, source_name, source_line, source_column)
    REFERENCES graphql_ast_directive_application_entry (graph_name, source_name, source_line, source_column)
    ON DELETE CASCADE
);
COMMENT ON TABLE graphitron_ast_mutation_entry IS 'What a @mutation application says: which write the field performs, over how many rows, against which table, as written. For example deleteFilm(input:): Boolean @mutation(typeName: DELETE, multiRow: true, table: "film") gives one row.';
COMMENT ON COLUMN graphitron_ast_mutation_entry.graph_name IS 'the owning graph''s partition, anchored by store_graph; the leading key dimension that keeps one workspace''s graphs apart';
COMMENT ON COLUMN graphitron_ast_mutation_entry.source_name IS 'the file the application was written in';
COMMENT ON COLUMN graphitron_ast_mutation_entry.source_line IS 'source line of the at sign, 1-based per the graphql-java convention';
COMMENT ON COLUMN graphitron_ast_mutation_entry.source_column IS 'source column of the same. The four key columns are the applied directive''s own key, so this row is the decode of exactly one row of graphql_ast_directive_application_entry and neither carries what the other holds';
COMMENT ON COLUMN graphitron_ast_mutation_entry.touched_at IS 'when the reading that produced this row ran. The reading finishes by deleting its file''s rows carrying an older instant, which are the applications the author removed or renamed in place; an application the author moved is swept with the directive row it hangs on';
COMMENT ON COLUMN graphitron_ast_mutation_entry.operation IS 'the typeName argument as the author spelled it, an enum token being kept as its own text and never checked against the vocabulary the definition declares. Nothing upstream has validated it, so a CHECK here would turn a typo into a constraint violation; membership is a detection';
COMMENT ON COLUMN graphitron_ast_mutation_entry.multi_row IS 'the multiRow argument as written, or NULL where the author wrote none; the definition''s own default of false stands in graphql_directive_argument.default_value_sdl rather than being filled in here';
COMMENT ON COLUMN graphitron_ast_mutation_entry.fail_on_missing IS 'the failOnMissing argument as written, or NULL where the author wrote none; the definition''s own default of false stands in graphql_directive_argument.default_value_sdl rather than being filled in here';
COMMENT ON COLUMN graphitron_ast_mutation_entry.table_ref IS 'the table argument as written, or NULL where none was; what an omitted table resolves to is a resolution and not this relation''s business';
COMMENT ON COLUMN graphitron_ast_mutation_entry.table_ref_namespace_part IS 'the schema half of the written name, or NULL where none was written; split by QualifiedNameGrammar, which only cuts the string';
COMMENT ON COLUMN graphitron_ast_mutation_entry.table_ref_name_part IS 'the table half of the same';

CREATE TABLE graphitron_ast_routine_entry (
  graph_name    VARCHAR NOT NULL,
  source_name   VARCHAR NOT NULL,
  source_line   INT     NOT NULL,
  source_column INT     NOT NULL,
  touched_at    TIMESTAMP NOT NULL,
  routine_ref   VARCHAR NOT NULL,
  routine_ref_namespace_part VARCHAR,
  routine_ref_name_part      VARCHAR,
  argmapping    VARCHAR,
  PRIMARY KEY (graph_name, source_name, source_line, source_column),
  FOREIGN KEY (graph_name) REFERENCES store_graph (graph_name),
  FOREIGN KEY (graph_name, source_name, source_line, source_column)
    REFERENCES graphql_ast_directive_application_entry (graph_name, source_name, source_line, source_column)
    ON DELETE CASCADE
);
COMMENT ON TABLE graphitron_ast_routine_entry IS 'What a @routine application says: the database routine backing the field and the mapping binding its parameters, as written. For example reportedFilms: [Film!] @routine(name: "public.reported_films", argMapping: "pEnv: env") gives one row.';
COMMENT ON COLUMN graphitron_ast_routine_entry.graph_name IS 'the owning graph''s partition, anchored by store_graph; the leading key dimension that keeps one workspace''s graphs apart';
COMMENT ON COLUMN graphitron_ast_routine_entry.source_name IS 'the file the application was written in';
COMMENT ON COLUMN graphitron_ast_routine_entry.source_line IS 'source line of the at sign, 1-based per the graphql-java convention';
COMMENT ON COLUMN graphitron_ast_routine_entry.source_column IS 'source column of the same. The four key columns are the applied directive''s own key, so this row is the decode of exactly one row of graphql_ast_directive_application_entry, and the ordinal the anchors give a repeated @routine is not a column here: the position the application was written at is what tells two of them apart';
COMMENT ON COLUMN graphitron_ast_routine_entry.touched_at IS 'when the reading that produced this row ran. The reading finishes by deleting its file''s rows carrying an older instant, which are the applications the author removed or renamed in place; an application the author moved is swept with the directive row it hangs on';
COMMENT ON COLUMN graphitron_ast_routine_entry.routine_ref IS 'the name argument exactly as written, optionally schema-qualified. Nullable although the definition marks it required, because a document that omits it still applied the directive';
COMMENT ON COLUMN graphitron_ast_routine_entry.routine_ref_namespace_part IS 'the schema half of the written name, or NULL where none was written; split by QualifiedNameGrammar, which only cuts the string';
COMMENT ON COLUMN graphitron_ast_routine_entry.routine_ref_name_part IS 'the routine half of the same';
COMMENT ON COLUMN graphitron_ast_routine_entry.argmapping IS 'the argMapping argument, kept as the one string the author typed; what its segments name is a question for the argument-mapping derivation';

CREATE TABLE graphitron_ast_outbox_entry (
  graph_name    VARCHAR NOT NULL,
  source_name   VARCHAR NOT NULL,
  source_line   INT     NOT NULL,
  source_column INT     NOT NULL,
  touched_at    TIMESTAMP NOT NULL,
  event_ref     VARCHAR,
  argmapping    VARCHAR,
  PRIMARY KEY (graph_name, source_name, source_line, source_column),
  FOREIGN KEY (graph_name) REFERENCES store_graph (graph_name),
  FOREIGN KEY (graph_name, source_name, source_line, source_column)
    REFERENCES graphql_ast_directive_application_entry (graph_name, source_name, source_line, source_column)
    ON DELETE CASCADE
);
COMMENT ON TABLE graphitron_ast_outbox_entry IS 'What an @outbox application says: the event it names and the mapping that builds its payload, as written. For example createFilm(in: FilmCreateInput!): Film @outbox(event: "FilmCreated", argMapping: "filmId: $result.id") gives one row.';
COMMENT ON COLUMN graphitron_ast_outbox_entry.graph_name IS 'the owning graph''s partition, anchored by store_graph; the leading key dimension that keeps one workspace''s graphs apart';
COMMENT ON COLUMN graphitron_ast_outbox_entry.source_name IS 'the file the application was written in';
COMMENT ON COLUMN graphitron_ast_outbox_entry.source_line IS 'source line of the at sign, 1-based per the graphql-java convention';
COMMENT ON COLUMN graphitron_ast_outbox_entry.source_column IS 'source column of the same. The four key columns are the applied directive''s own key, so this row is the decode of exactly one row of graphql_ast_directive_application_entry, and the ordinal the anchor gives a repeated @outbox is not a column here: the position the application was written at is what tells two of them apart';
COMMENT ON COLUMN graphitron_ast_outbox_entry.touched_at IS 'when the reading that produced this row ran. The reading finishes by deleting its file''s rows carrying an older instant, which are the applications the author removed or renamed in place; an application the author moved is swept with the directive row it hangs on';
COMMENT ON COLUMN graphitron_ast_outbox_entry.event_ref IS 'the event argument exactly as written, or NULL where the author left it out; what an omitted event defaults to is the anchor''s resolution, not a value to keep here';
COMMENT ON COLUMN graphitron_ast_outbox_entry.argmapping IS 'the argMapping argument, kept as the one string the author typed; what its entries name is a question for the derivation over the argument-mapping pairs';

CREATE TABLE graphitron_ast_issue_entry (
  graph_name    VARCHAR NOT NULL,
  source_name   VARCHAR NOT NULL,
  source_line   INT     NOT NULL,
  source_column INT     NOT NULL,
  touched_at    TIMESTAMP NOT NULL,
  scope         VARCHAR,
  ttl           VARCHAR,
  claims        VARCHAR,
  PRIMARY KEY (graph_name, source_name, source_line, source_column),
  FOREIGN KEY (graph_name) REFERENCES store_graph (graph_name),
  FOREIGN KEY (graph_name, source_name, source_line, source_column)
    REFERENCES graphql_ast_directive_application_entry (graph_name, source_name, source_line, source_column)
    ON DELETE CASCADE
);
COMMENT ON TABLE graphitron_ast_issue_entry IS 'What an @issue application says: the scope, the lifetime and the claims of the vouchers it issues, as written. For example voucher: String! @issue(scope: "results", ttl: "PT5M", claims: "ownerId") gives one row.';
COMMENT ON COLUMN graphitron_ast_issue_entry.graph_name IS 'the owning graph''s partition, anchored by store_graph';
COMMENT ON COLUMN graphitron_ast_issue_entry.source_name IS 'the file the application was written in';
COMMENT ON COLUMN graphitron_ast_issue_entry.source_line IS 'source line of the at sign, 1-based per the graphql-java convention';
COMMENT ON COLUMN graphitron_ast_issue_entry.source_column IS 'source column of the same; the four key columns are the applied directive''s own key, so this row is the decode of exactly one row of graphql_ast_directive_application_entry';
COMMENT ON COLUMN graphitron_ast_issue_entry.touched_at IS 'when the reading that produced this row ran; the reading finishes by deleting its file''s rows carrying an older instant';
COMMENT ON COLUMN graphitron_ast_issue_entry.scope IS 'the scope argument as written, or NULL where it is missing';
COMMENT ON COLUMN graphitron_ast_issue_entry.ttl IS 'the ttl argument as written, an ISO-8601 duration, or NULL where it is missing; parsing it is the voucher stage''s';
COMMENT ON COLUMN graphitron_ast_issue_entry.claims IS 'the claims argument, the field set as written, or NULL where it is missing; which fields it names is decided by the voucher stage';

CREATE TABLE graphitron_ast_issue_claim_entry (
  graph_name    VARCHAR NOT NULL,
  source_name   VARCHAR NOT NULL,
  source_line   INT     NOT NULL,
  source_column INT     NOT NULL,
  position      INT     NOT NULL,
  touched_at    TIMESTAMP NOT NULL,
  field_name    VARCHAR NOT NULL,
  nested        BOOLEAN NOT NULL,
  PRIMARY KEY (graph_name, source_name, source_line, source_column, position),
  FOREIGN KEY (graph_name) REFERENCES store_graph (graph_name),
  FOREIGN KEY (graph_name, source_name, source_line, source_column)
    REFERENCES graphitron_ast_issue_entry (graph_name, source_name, source_line, source_column)
    ON DELETE CASCADE,
  CHECK (position >= 0)
);
COMMENT ON TABLE graphitron_ast_issue_claim_entry IS 'One selection an @issue''s claims field set parsed into, at its index in that parse. For example claims: "eierId" gives one row, eierId at position 0, not nested.';
COMMENT ON COLUMN graphitron_ast_issue_claim_entry.graph_name IS 'the owning graph''s partition';
COMMENT ON COLUMN graphitron_ast_issue_claim_entry.source_name IS 'the @issue''s file';
COMMENT ON COLUMN graphitron_ast_issue_claim_entry.source_line IS 'the @issue''s line';
COMMENT ON COLUMN graphitron_ast_issue_claim_entry.source_column IS 'the @issue''s column';
COMMENT ON COLUMN graphitron_ast_issue_claim_entry.position IS 'the selection''s place in the field set as written, numbered from zero';
COMMENT ON COLUMN graphitron_ast_issue_claim_entry.touched_at IS 'when the reading that produced this row ran';
COMMENT ON COLUMN graphitron_ast_issue_claim_entry.field_name IS 'the selection''s first segment, the field it names on the issuing type';
COMMENT ON COLUMN graphitron_ast_issue_claim_entry.nested IS 'whether the selection goes on into a nested selection, which a claim cannot';

CREATE TABLE graphitron_ast_accept_entry (
  graph_name    VARCHAR NOT NULL,
  source_name   VARCHAR NOT NULL,
  source_line   INT     NOT NULL,
  source_column INT     NOT NULL,
  touched_at    TIMESTAMP NOT NULL,
  scope         VARCHAR,
  key_fields    VARCHAR,
  claims        VARCHAR,
  PRIMARY KEY (graph_name, source_name, source_line, source_column),
  FOREIGN KEY (graph_name) REFERENCES store_graph (graph_name),
  FOREIGN KEY (graph_name, source_name, source_line, source_column)
    REFERENCES graphql_ast_directive_application_entry (graph_name, source_name, source_line, source_column)
    ON DELETE CASCADE
);
COMMENT ON TABLE graphitron_ast_accept_entry IS 'What an @accept application says: the scope of the vouchers it accepts, the authored key they decode to and the claims they carry, as written. For example voucher: String! @accept(scope: "results", claims: "ownerId") gives one row with no key.';
COMMENT ON COLUMN graphitron_ast_accept_entry.graph_name IS 'the owning graph''s partition, anchored by store_graph';
COMMENT ON COLUMN graphitron_ast_accept_entry.source_name IS 'the file the application was written in';
COMMENT ON COLUMN graphitron_ast_accept_entry.source_line IS 'source line of the at sign, 1-based per the graphql-java convention';
COMMENT ON COLUMN graphitron_ast_accept_entry.source_column IS 'source column of the same; the four key columns are the applied directive''s own key, so this row is the decode of exactly one row of graphql_ast_directive_application_entry';
COMMENT ON COLUMN graphitron_ast_accept_entry.touched_at IS 'when the reading that produced this row ran; the reading finishes by deleting its file''s rows carrying an older instant';
COMMENT ON COLUMN graphitron_ast_accept_entry.scope IS 'the scope argument as written, or NULL where it is missing';
COMMENT ON COLUMN graphitron_ast_accept_entry.key_fields IS 'the key argument, the field set of the authored @key the vouchers decode to, as written, or NULL where the author left it out; which key it names is decided by the entity key stage';
COMMENT ON COLUMN graphitron_ast_accept_entry.claims IS 'the claims argument, the field set as written, or NULL where it is missing; which fields it names is decided by the voucher stage';

CREATE TABLE graphitron_ast_accept_claim_entry (
  graph_name    VARCHAR NOT NULL,
  source_name   VARCHAR NOT NULL,
  source_line   INT     NOT NULL,
  source_column INT     NOT NULL,
  position      INT     NOT NULL,
  touched_at    TIMESTAMP NOT NULL,
  field_name    VARCHAR NOT NULL,
  nested        BOOLEAN NOT NULL,
  PRIMARY KEY (graph_name, source_name, source_line, source_column, position),
  FOREIGN KEY (graph_name) REFERENCES store_graph (graph_name),
  FOREIGN KEY (graph_name, source_name, source_line, source_column)
    REFERENCES graphitron_ast_accept_entry (graph_name, source_name, source_line, source_column)
    ON DELETE CASCADE,
  CHECK (position >= 0)
);
COMMENT ON TABLE graphitron_ast_accept_claim_entry IS 'One selection an @accept''s claims field set parsed into, at its index in that parse. For example claims: "eierId" gives one row, eierId at position 0, not nested.';
COMMENT ON COLUMN graphitron_ast_accept_claim_entry.graph_name IS 'the owning graph''s partition';
COMMENT ON COLUMN graphitron_ast_accept_claim_entry.source_name IS 'the @accept''s file';
COMMENT ON COLUMN graphitron_ast_accept_claim_entry.source_line IS 'the @accept''s line';
COMMENT ON COLUMN graphitron_ast_accept_claim_entry.source_column IS 'the @accept''s column';
COMMENT ON COLUMN graphitron_ast_accept_claim_entry.position IS 'the selection''s place in the field set as written, numbered from zero';
COMMENT ON COLUMN graphitron_ast_accept_claim_entry.touched_at IS 'when the reading that produced this row ran';
COMMENT ON COLUMN graphitron_ast_accept_claim_entry.field_name IS 'the selection''s first segment, the field it names on the accepting type';
COMMENT ON COLUMN graphitron_ast_accept_claim_entry.nested IS 'whether the selection goes on into a nested selection, which a claim cannot';

CREATE TABLE graphitron_ast_accept_key_entry (
  graph_name    VARCHAR NOT NULL,
  source_name   VARCHAR NOT NULL,
  source_line   INT     NOT NULL,
  source_column INT     NOT NULL,
  position      INT     NOT NULL,
  touched_at    TIMESTAMP NOT NULL,
  field_name    VARCHAR NOT NULL,
  nested        BOOLEAN NOT NULL,
  PRIMARY KEY (graph_name, source_name, source_line, source_column, position),
  FOREIGN KEY (graph_name) REFERENCES store_graph (graph_name),
  FOREIGN KEY (graph_name, source_name, source_line, source_column)
    REFERENCES graphitron_ast_accept_entry (graph_name, source_name, source_line, source_column)
    ON DELETE CASCADE,
  CHECK (position >= 0)
);
COMMENT ON TABLE graphitron_ast_accept_key_entry IS 'One selection an @accept''s key field set parsed into, at its index in that parse. For example key: "id" gives one row, id at position 0, not nested; an @accept with no key gives none.';
COMMENT ON COLUMN graphitron_ast_accept_key_entry.graph_name IS 'the owning graph''s partition';
COMMENT ON COLUMN graphitron_ast_accept_key_entry.source_name IS 'the @accept''s file';
COMMENT ON COLUMN graphitron_ast_accept_key_entry.source_line IS 'the @accept''s line';
COMMENT ON COLUMN graphitron_ast_accept_key_entry.source_column IS 'the @accept''s column';
COMMENT ON COLUMN graphitron_ast_accept_key_entry.position IS 'the selection''s place in the field set as written, numbered from zero';
COMMENT ON COLUMN graphitron_ast_accept_key_entry.touched_at IS 'when the reading that produced this row ran';
COMMENT ON COLUMN graphitron_ast_accept_key_entry.field_name IS 'the selection''s first segment, the field it names on the accepting type';
COMMENT ON COLUMN graphitron_ast_accept_key_entry.nested IS 'whether the selection goes on into a nested selection, which the voucher''s lookup part, top-level scalars, cannot fill';

-- The input-value site's decode. One writer over the three parents the parser treats alike, a
-- field's argument, an input object's field and a directive definition's own argument, every
-- relation below keyed by the position of the @ token, which is
-- graphql_ast_directive_application_entry's key. Four of the site's nine directive names get no
-- relation: @lookupKey, @orderBy, @asFacet and @tenant declare no argument at all, so a row would
-- carry its key and repeat what the applied-directive row says. @reference's only argument is its path, so
-- the steps get the relation and the application does not.
CREATE TABLE graphitron_ast_input_value_condition_entry (
  graph_name    VARCHAR NOT NULL,
  source_name   VARCHAR NOT NULL,
  source_line   INT     NOT NULL,
  source_column INT     NOT NULL,
  touched_at    TIMESTAMP NOT NULL,
  class_name    VARCHAR NOT NULL,
  method        VARCHAR,
  argmapping    VARCHAR,
  override      BOOLEAN,
  PRIMARY KEY (graph_name, source_name, source_line, source_column),
  FOREIGN KEY (graph_name) REFERENCES store_graph (graph_name),
  FOREIGN KEY (graph_name, source_name, source_line, source_column)
    REFERENCES graphql_ast_directive_application_entry (graph_name, source_name, source_line, source_column)
    ON DELETE CASCADE
);
COMMENT ON TABLE graphitron_ast_input_value_condition_entry IS 'What a @condition application on an input value says: the external method deciding the predicate, as written. For example scope: ID @condition(condition: {className: "no.example.Conditions", method: "inScope"}) gives one row.';
COMMENT ON COLUMN graphitron_ast_input_value_condition_entry.graph_name IS 'the owning graph''s partition, anchored by store_graph; the leading key dimension that keeps one workspace''s graphs apart';
COMMENT ON COLUMN graphitron_ast_input_value_condition_entry.source_name IS 'the file the application was written in';
COMMENT ON COLUMN graphitron_ast_input_value_condition_entry.source_line IS 'source line of the at sign, 1-based per the graphql-java convention';
COMMENT ON COLUMN graphitron_ast_input_value_condition_entry.source_column IS 'source column of the same. The four key columns are the applied directive''s own key, so this row is the decode of exactly one row of graphql_ast_directive_application_entry and neither carries what the other holds';
COMMENT ON COLUMN graphitron_ast_input_value_condition_entry.touched_at IS 'when the reading that produced this row ran. The reading finishes by deleting its file''s rows carrying an older instant, which are the applications the author removed or renamed in place; an application the author moved is swept with the directive row it hangs on';
COMMENT ON COLUMN graphitron_ast_input_value_condition_entry.class_name IS 'the className field of the condition reference, as written. The class the anchor joins the classpath census on, so an application naming none writes no row rather than a row nothing can be resolved from';
COMMENT ON COLUMN graphitron_ast_input_value_condition_entry.method IS 'the method field of the same, as written, or NULL where none was';
COMMENT ON COLUMN graphitron_ast_input_value_condition_entry.argmapping IS 'the argMapping field of the same, as written, or NULL where none was. Kept as the one string the author typed; what its segments name is a question for the argument-mapping derivation';
COMMENT ON COLUMN graphitron_ast_input_value_condition_entry.override IS 'the override argument as written, or NULL where the author wrote none. The definition''s default of false is not filled in here: it stands in graphql_directive_argument.default_value_sdl, and writing it would lose the difference between a default taken and a value written';

CREATE VIEW graphitron_call_context_key_written
  (graph_name, coordinate, directive_name, ordinal, owner, parameter_name, context_key, origin,
   source_name, origin_line, origin_column, origin_position) AS
-- A $context pair names its parameter on the left and its key after the dot, exactly one name. Its
-- call is the code reference its string is a field of, which shares the mapping's key; a mapping
-- with none, a @routine's, has no call to fill here and is refused where the sigil is judged.
SELECT p.graph_name, s.coordinate, s.directive_name, s.ordinal, s.owner, p.param_name,
       SUBSTRING(p.bound_to, 10), 'PAIR', p.source_name, p.source_line, p.source_column, p.position
  FROM graphitron_ast_argmapping_pair_entry p
  JOIN graphitron_argmapping_site s
    ON s.graph_name = p.graph_name AND s.source_name = p.source_name
   AND s.source_line = p.source_line AND s.source_column = p.source_column
 WHERE p.bound_to LIKE '$context.%'
   AND CHAR_LENGTH(p.bound_to) > 9 AND POSITION('.', SUBSTRING(p.bound_to, 10)) = 0
   AND EXISTS (SELECT 1 FROM graphitron_code_reference_site r
                WHERE r.graph_name = s.graph_name AND r.coordinate = s.coordinate
                  AND r.directive_name = s.directive_name AND r.ordinal = s.ordinal
                  AND r.owner = s.owner)
UNION ALL
-- A contextArguments element is the pair naming the parameter of its own name: a string written in
-- the list a @service or @condition application takes under that name. Its call is the code
-- reference written as the application's other argument, the object at that argument's top. A
-- lone string is the list holding it, as an input list coerces one value.
SELECT v.graph_name, r.coordinate, r.directive_name, r.ordinal, r.owner, v.written_text,
       v.written_text, 'CONTEXT_ARGUMENTS', v.source_name, v.source_line, v.source_column,
       COALESCE(v.position, 0)
  FROM graphql_ast_applied_argument_entry a
  JOIN graphql_ast_directive_application_entry da
    ON da.graph_name = a.graph_name AND da.source_name = a.source_name
   AND da.source_line = a.parent_line AND da.source_column = a.parent_column
  JOIN graphql_ast_value_entry v
    ON v.graph_name = a.graph_name AND v.source_name = a.source_name
   AND v.holder_line = a.source_line AND v.holder_column = a.source_column
   AND v.kind = 'STRING'
  JOIN graphql_ast_applied_argument_entry ra
    ON ra.graph_name = a.graph_name AND ra.source_name = a.source_name
   AND ra.parent_line = a.parent_line AND ra.parent_column = a.parent_column
  JOIN graphql_ast_value_entry rv
    ON rv.graph_name = ra.graph_name AND rv.source_name = ra.source_name
   AND rv.holder_line = ra.source_line AND rv.holder_column = ra.source_column
   AND rv.parent_line IS NULL
  JOIN graphitron_code_reference_site r
    ON r.graph_name = rv.graph_name AND r.source_name = rv.source_name
   AND r.source_line = rv.source_line AND r.source_column = rv.source_column
 WHERE a.name = 'contextArguments' AND da.name IN ('service', 'condition');
COMMENT ON VIEW graphitron_call_context_key_written IS 'One context key written for one parameter of one call, at the place it was written: a $context pair, or a contextArguments element read as the pair naming its own parameter. For example contextArguments: ["tenantId"] on a @service writes tenantId for the parameter tenantId of the method its service names.';
-- COMMENT ON COLUMN graphitron_call_context_key_written.graph_name IS 'the owning graph''s partition';
-- COMMENT ON COLUMN graphitron_call_context_key_written.coordinate IS 'the element the call''s application is on';
-- COMMENT ON COLUMN graphitron_call_context_key_written.directive_name IS 'the call''s directive';
-- COMMENT ON COLUMN graphitron_call_context_key_written.ordinal IS 'its application''s ordinal';
-- COMMENT ON COLUMN graphitron_call_context_key_written.owner IS 'what the call''s code reference is written under in it; with the three before it, the reference''s key';
-- COMMENT ON COLUMN graphitron_call_context_key_written.parameter_name IS 'the parameter the key fills';
-- COMMENT ON COLUMN graphitron_call_context_key_written.context_key IS 'the key';
-- COMMENT ON COLUMN graphitron_call_context_key_written.origin IS 'PAIR or CONTEXT_ARGUMENTS';
-- COMMENT ON COLUMN graphitron_call_context_key_written.source_name IS 'the file the key was written in';
-- COMMENT ON COLUMN graphitron_call_context_key_written.origin_line IS 'where it was written, the pair''s string or the element';
-- COMMENT ON COLUMN graphitron_call_context_key_written.origin_column IS 'the same';
-- COMMENT ON COLUMN graphitron_call_context_key_written.origin_position IS 'the pair''s position in its mapping or the element''s in its list';

CREATE VIEW graphitron_call_context_key_rule
  (graph_name, coordinate, directive_name, ordinal, owner, parameter_name, context_key, origin,
   source_name, origin_line, origin_column, origin_position) AS
-- A parameter written once. One written twice, by two elements or by an element and a pair, fills
-- nothing here and is CONTEXT_KEY_DUPLICATE at each place it was written.
SELECT w.graph_name, w.coordinate, w.directive_name, w.ordinal, w.owner, w.parameter_name,
       w.context_key, w.origin, w.source_name, w.origin_line, w.origin_column, w.origin_position
  FROM graphitron_call_context_key_written w
 WHERE NOT EXISTS (SELECT 1 FROM graphitron_call_context_key_written o
                    WHERE o.graph_name = w.graph_name AND o.coordinate = w.coordinate
                      AND o.directive_name = w.directive_name AND o.ordinal = w.ordinal
                      AND o.owner = w.owner AND o.parameter_name = w.parameter_name
                      AND (o.origin_line <> w.origin_line OR o.origin_column <> w.origin_column
                           OR o.origin_position <> w.origin_position));
COMMENT ON VIEW graphitron_call_context_key_rule IS 'One row the context-key rule computes, in the shape graphitron_call_context_key stores: the rule itself, evaluated on demand rather than read off disk. For example the graphitron anchor inserts this view''s rows for one graph into graphitron_call_context_key, which is the name every reader spells.';
-- COMMENT ON COLUMN graphitron_call_context_key_rule.graph_name IS 'the graph_name of a row of this rule, which the anchor writes into graphitron_call_context_key.graph_name';
-- COMMENT ON COLUMN graphitron_call_context_key_rule.coordinate IS 'the coordinate of a row of this rule, which the anchor writes into graphitron_call_context_key.coordinate';
-- COMMENT ON COLUMN graphitron_call_context_key_rule.directive_name IS 'the directive_name of a row of this rule, which the anchor writes into graphitron_call_context_key.directive_name';
-- COMMENT ON COLUMN graphitron_call_context_key_rule.ordinal IS 'the ordinal of a row of this rule, which the anchor writes into graphitron_call_context_key.ordinal';
-- COMMENT ON COLUMN graphitron_call_context_key_rule.owner IS 'the owner of a row of this rule, which the anchor writes into graphitron_call_context_key.owner';
-- COMMENT ON COLUMN graphitron_call_context_key_rule.parameter_name IS 'the parameter_name of a row of this rule, which the anchor writes into graphitron_call_context_key.parameter_name';
-- COMMENT ON COLUMN graphitron_call_context_key_rule.context_key IS 'the context_key of a row of this rule, which the anchor writes into graphitron_call_context_key.context_key';
-- COMMENT ON COLUMN graphitron_call_context_key_rule.origin IS 'the origin of a row of this rule, which the anchor writes into graphitron_call_context_key.origin';
-- COMMENT ON COLUMN graphitron_call_context_key_rule.source_name IS 'the source_name of a row of this rule, which the anchor writes into graphitron_call_context_key.source_name';
-- COMMENT ON COLUMN graphitron_call_context_key_rule.origin_line IS 'the origin_line of a row of this rule, which the anchor writes into graphitron_call_context_key.origin_line';
-- COMMENT ON COLUMN graphitron_call_context_key_rule.origin_column IS 'the origin_column of a row of this rule, which the anchor writes into graphitron_call_context_key.origin_column';
-- COMMENT ON COLUMN graphitron_call_context_key_rule.origin_position IS 'the origin_position of a row of this rule, which the anchor writes into graphitron_call_context_key.origin_position';

CREATE TABLE graphitron_call_context_key (
  graph_name      VARCHAR   NOT NULL,
  coordinate      VARCHAR   NOT NULL,
  directive_name  VARCHAR   NOT NULL,
  ordinal         INT       NOT NULL,
  owner           VARCHAR   NOT NULL,
  parameter_name  VARCHAR   NOT NULL,
  context_key     VARCHAR   NOT NULL,
  origin          VARCHAR   NOT NULL,
  source_name     VARCHAR   NOT NULL,
  origin_line     INT       NOT NULL,
  origin_column   INT       NOT NULL,
  origin_position INT       NOT NULL,
  touched_at      TIMESTAMP NOT NULL,
  -- A parameter is filled once per call; one written twice is a defect and no row.
  PRIMARY KEY (graph_name, coordinate, directive_name, ordinal, owner, parameter_name),
  -- The call's application, so a key cannot outlive what it fills a parameter of.
  FOREIGN KEY (graph_name, coordinate, directive_name, ordinal)
    REFERENCES graphql_directive_application (graph_name, coordinate, directive_name, ordinal)
    ON DELETE CASCADE,
  CHECK (origin IN ('PAIR', 'CONTEXT_ARGUMENTS'))
);
COMMENT ON TABLE graphitron_call_context_key IS 'The context key that fills one parameter of one call: one row per code reference and parameter a $context pair or a contextArguments element names once. For example contextArguments: ["tenantId"] on a @service fills the parameter tenantId of the method its service names with the value the request context carries under tenantId.';
COMMENT ON COLUMN graphitron_call_context_key.graph_name IS 'the owning graph''s partition';
COMMENT ON COLUMN graphitron_call_context_key.coordinate IS 'the element the call''s application is on';
COMMENT ON COLUMN graphitron_call_context_key.directive_name IS 'the call''s directive, @service or @condition';
COMMENT ON COLUMN graphitron_call_context_key.ordinal IS 'the application''s ordinal';
COMMENT ON COLUMN graphitron_call_context_key.owner IS 'what the call''s code reference is written under in its application; with the three before it, the reference''s key in graphitron_code_reference, which is what a call is until its method resolves';
COMMENT ON COLUMN graphitron_call_context_key.source_name IS 'the file the key was written in, with the origin columns where a defect about it points';
COMMENT ON COLUMN graphitron_call_context_key.parameter_name IS 'the parameter the key fills, completing the key: a pair''s left side, or a contextArguments element itself';
COMMENT ON COLUMN graphitron_call_context_key.context_key IS 'the key the request context carries the value under, which a pair may spell apart from the parameter it fills';
COMMENT ON COLUMN graphitron_call_context_key.origin IS 'PAIR where a $context pair wrote it, CONTEXT_ARGUMENTS where a contextArguments element did, for the surfaces that point back at the writing';
COMMENT ON COLUMN graphitron_call_context_key.origin_line IS 'source line of what wrote it: the mapping string for a pair, the element for contextArguments';
COMMENT ON COLUMN graphitron_call_context_key.origin_column IS 'source column of the same';
COMMENT ON COLUMN graphitron_call_context_key.origin_position IS 'the pair''s position in its mapping, or the element''s in its list';
COMMENT ON COLUMN graphitron_call_context_key.touched_at IS 'the reading that last wrote this row; the sweep deletes the rows an older reading wrote';

CREATE TABLE graphitron_ast_input_value_deprecated_entry (
  graph_name    VARCHAR NOT NULL,
  source_name   VARCHAR NOT NULL,
  source_line   INT     NOT NULL,
  source_column INT     NOT NULL,
  touched_at    TIMESTAMP NOT NULL,
  reason        VARCHAR,
  PRIMARY KEY (graph_name, source_name, source_line, source_column),
  FOREIGN KEY (graph_name) REFERENCES store_graph (graph_name),
  FOREIGN KEY (graph_name, source_name, source_line, source_column)
    REFERENCES graphql_ast_directive_application_entry (graph_name, source_name, source_line, source_column)
    ON DELETE CASCADE
);
COMMENT ON TABLE graphitron_ast_input_value_deprecated_entry IS 'What a deprecation marker on an input value says: the replacement hint the author gave, decoded. For example a connectionName argument marked with the reason "own your Connection type" gives one row carrying that text.';
COMMENT ON COLUMN graphitron_ast_input_value_deprecated_entry.graph_name IS 'the owning graph''s partition, anchored by store_graph; the leading key dimension that keeps one workspace''s graphs apart';
COMMENT ON COLUMN graphitron_ast_input_value_deprecated_entry.source_name IS 'the file the application was written in';
COMMENT ON COLUMN graphitron_ast_input_value_deprecated_entry.source_line IS 'source line of the at sign, 1-based per the graphql-java convention';
COMMENT ON COLUMN graphitron_ast_input_value_deprecated_entry.source_column IS 'source column of the same. The four key columns are the applied directive''s own key, so this row is the decode of exactly one row of graphql_ast_directive_application_entry and neither carries what the other holds';
COMMENT ON COLUMN graphitron_ast_input_value_deprecated_entry.touched_at IS 'when the reading that produced this row ran. The reading finishes by deleting its file''s rows carrying an older instant, which are the applications the author removed or renamed in place; an application the author moved is swept with the directive row it hangs on';
COMMENT ON COLUMN graphitron_ast_input_value_deprecated_entry.reason IS 'the reason argument decoded to the string the author wrote, or NULL where they wrote none or wrote something that is not a string. The decode is the whole reason this relation exists beside the applied-argument row: that row carries the rendered literal, quotes included, and a consumer wanting the text would have to re-read SDL to get it';

CREATE TABLE graphitron_ast_index_entry (
  graph_name    VARCHAR NOT NULL,
  source_name   VARCHAR NOT NULL,
  source_line   INT     NOT NULL,
  source_column INT     NOT NULL,
  touched_at    TIMESTAMP NOT NULL,
  index_ref     VARCHAR NOT NULL,
  PRIMARY KEY (graph_name, source_name, source_line, source_column),
  FOREIGN KEY (graph_name) REFERENCES store_graph (graph_name),
  FOREIGN KEY (graph_name, source_name, source_line, source_column)
    REFERENCES graphql_ast_directive_application_entry (graph_name, source_name, source_line, source_column)
    ON DELETE CASCADE
);
COMMENT ON TABLE graphitron_ast_index_entry IS 'What an @index application says: the database index the enum value names, as written. For example TITLE_INDEX @index(name: "idx_film_title") gives one row whose index_ref is idx_film_title.';
COMMENT ON COLUMN graphitron_ast_index_entry.graph_name IS 'the owning graph''s partition, anchored by store_graph; the leading key dimension that keeps one workspace''s graphs apart';
COMMENT ON COLUMN graphitron_ast_index_entry.source_name IS 'the file the application was written in';
COMMENT ON COLUMN graphitron_ast_index_entry.source_line IS 'source line of the at sign, 1-based per the graphql-java convention';
COMMENT ON COLUMN graphitron_ast_index_entry.source_column IS 'source column of the same. The four key columns are the applied directive''s own key, so this row is the decode of exactly one row of graphql_ast_directive_application_entry and neither carries what the other holds';
COMMENT ON COLUMN graphitron_ast_index_entry.touched_at IS 'when the reading that produced this row ran. The reading finishes by deleting its file''s rows carrying an older instant, which are the applications the author removed or renamed in place; an application the author moved is swept with the directive row it hangs on';
COMMENT ON COLUMN graphitron_ast_index_entry.index_ref IS 'the name argument decoded to the string the author wrote. NOT NULL because it is the only argument the directive has, so an application without it would give a row carrying its key and nothing else, which is what the applied-directive row already says';

CREATE TABLE graphitron_ast_order_entry (
  graph_name    VARCHAR NOT NULL,
  source_name   VARCHAR NOT NULL,
  source_line   INT     NOT NULL,
  source_column INT     NOT NULL,
  touched_at    TIMESTAMP NOT NULL,
  index_ref     VARCHAR,
  primary_key   BOOLEAN,
  PRIMARY KEY (graph_name, source_name, source_line, source_column),
  FOREIGN KEY (graph_name) REFERENCES store_graph (graph_name),
  FOREIGN KEY (graph_name, source_name, source_line, source_column)
    REFERENCES graphql_ast_directive_application_entry (graph_name, source_name, source_line, source_column)
    ON DELETE CASCADE
);
COMMENT ON TABLE graphitron_ast_order_entry IS 'What an @order application says: which of the three sorting surfaces an enum value selects, as written. For example BY_TITLE @order(fields: [{name: "title"}]) gives one row whose two columns are both NULL, the sort being the child rows.';
COMMENT ON COLUMN graphitron_ast_order_entry.graph_name IS 'the owning graph''s partition, anchored by store_graph; the leading key dimension that keeps one workspace''s graphs apart';
COMMENT ON COLUMN graphitron_ast_order_entry.source_name IS 'the file the application was written in';
COMMENT ON COLUMN graphitron_ast_order_entry.source_line IS 'source line of the at sign, 1-based per the graphql-java convention';
COMMENT ON COLUMN graphitron_ast_order_entry.source_column IS 'source column of the same. The four key columns are the applied directive''s own key, so this row is the decode of exactly one row of graphql_ast_directive_application_entry and neither carries what the other holds';
COMMENT ON COLUMN graphitron_ast_order_entry.touched_at IS 'when the reading that produced this row ran. The reading finishes by deleting its file''s rows carrying an older instant, which are the applications the author removed or renamed in place; an application the author moved is swept with the directive row it hangs on';
COMMENT ON COLUMN graphitron_ast_order_entry.index_ref IS 'the index argument decoded to the string the author wrote, or NULL where they wrote none or wrote something that is not a string';
COMMENT ON COLUMN graphitron_ast_order_entry.primary_key IS 'the primaryKey argument decoded to the boolean the author wrote, or NULL where they wrote none. NULL rather than false, the directive''s own default being a generator constant and not a fact about the document';

CREATE TABLE graphitron_ast_order_field_entry (
  graph_name    VARCHAR NOT NULL,
  source_name   VARCHAR NOT NULL,
  source_line   INT     NOT NULL,
  source_column INT     NOT NULL,
  touched_at    TIMESTAMP NOT NULL,
  name_ref      VARCHAR,
  collate       VARCHAR,
  direction     VARCHAR,
  PRIMARY KEY (graph_name, source_name, source_line, source_column),
  FOREIGN KEY (graph_name) REFERENCES store_graph (graph_name),
  FOREIGN KEY (graph_name, source_name, source_line, source_column)
    REFERENCES graphql_ast_value_entry (graph_name, source_name, source_line, source_column)
    ON DELETE CASCADE
);
COMMENT ON TABLE graphitron_ast_order_field_entry IS 'One fields element of an @order application, at its position in the list, as written. For example fields: [{name: "title", collate: "xdanish_ai"}] gives one row at position 0.';
COMMENT ON COLUMN graphitron_ast_order_field_entry.graph_name IS 'the owning graph''s partition, anchored by store_graph; the leading key dimension that keeps one workspace''s graphs apart';
COMMENT ON COLUMN graphitron_ast_order_field_entry.source_name IS 'the file the element was written in';
COMMENT ON COLUMN graphitron_ast_order_field_entry.source_line IS 'source line of the element this row decodes, 1-based per the graphql-java convention';
COMMENT ON COLUMN graphitron_ast_order_field_entry.source_column IS 'source column of the same. The four columns are the element''s own key in graphql_ast_value_entry, so the list it sits in, the index it was written at and the application holding it are one join away rather than columns here';
COMMENT ON COLUMN graphitron_ast_order_field_entry.touched_at IS 'when the reading that produced this row ran. The reading finishes by deleting its file''s rows carrying an older instant, which are the applications the author removed or renamed in place; an application the author moved is swept with the directive row it hangs on';
COMMENT ON COLUMN graphitron_ast_order_field_entry.name_ref IS 'the element''s name field decoded to the string the author wrote, or NULL where they wrote none or wrote something that is not a string';
COMMENT ON COLUMN graphitron_ast_order_field_entry.collate IS 'the element''s collate field on the same terms. A database-specific collation name, resolving against nothing here';
COMMENT ON COLUMN graphitron_ast_order_field_entry.direction IS 'the element''s direction field as the enum token the author wrote, or NULL where they wrote none';

CREATE TABLE graphitron_ast_link_entry (
  graph_name    VARCHAR NOT NULL,
  source_name   VARCHAR NOT NULL,
  source_line   INT     NOT NULL,
  source_column INT     NOT NULL,
  touched_at    TIMESTAMP NOT NULL,
  url           VARCHAR,
  PRIMARY KEY (graph_name, source_name, source_line, source_column),
  FOREIGN KEY (graph_name) REFERENCES store_graph (graph_name),
  FOREIGN KEY (graph_name, source_name, source_line, source_column)
    REFERENCES graphql_ast_directive_application_entry (graph_name, source_name, source_line, source_column)
    ON DELETE CASCADE
);
COMMENT ON TABLE graphitron_ast_link_entry IS 'What a federation @link application says: the specification the schema opts in to, as written. For example a schema extension applying @link with federation v2.10 as its url argument gives one row carrying that string.';
COMMENT ON COLUMN graphitron_ast_link_entry.graph_name IS 'the owning graph''s partition, anchored by store_graph; the leading key dimension that keeps one workspace''s graphs apart';
COMMENT ON COLUMN graphitron_ast_link_entry.source_name IS 'the file the application was written in';
COMMENT ON COLUMN graphitron_ast_link_entry.source_line IS 'source line of the at sign, 1-based per the graphql-java convention';
COMMENT ON COLUMN graphitron_ast_link_entry.source_column IS 'source column of the same. The four key columns are the applied directive''s own key, so this row is the decode of exactly one row of graphql_ast_directive_application_entry and neither carries what the other holds';
COMMENT ON COLUMN graphitron_ast_link_entry.touched_at IS 'when the reading that produced this row ran. The reading finishes by deleting its file''s rows carrying an older instant, which are the applications the author removed or renamed in place; an application the author moved is swept with the directive row it hangs on';
COMMENT ON COLUMN graphitron_ast_link_entry.url IS 'the url argument decoded to the string the author wrote, or NULL where they wrote none or wrote something that is not a string. Nothing here reads the specification it names, and no version is parsed out of it';

CREATE TABLE graphitron_ast_federation_link_entry (
  graph_name    VARCHAR NOT NULL,
  source_name   VARCHAR NOT NULL,
  source_line   INT     NOT NULL,
  source_column INT     NOT NULL,
  touched_at    TIMESTAMP NOT NULL,
  version       VARCHAR NOT NULL,
  PRIMARY KEY (graph_name, source_name, source_line, source_column),
  FOREIGN KEY (graph_name) REFERENCES store_graph (graph_name),
  FOREIGN KEY (graph_name, source_name, source_line, source_column)
    REFERENCES graphitron_ast_link_entry (graph_name, source_name, source_line, source_column)
    ON DELETE CASCADE
);
COMMENT ON TABLE graphitron_ast_federation_link_entry IS 'A @link application whose url names the federation specification, and the version it names. For example a schema extension applying @link with federation v2.10 as its url gives one row carrying v2.10, and a @link to any other specification gives none.';
COMMENT ON COLUMN graphitron_ast_federation_link_entry.graph_name IS 'the owning graph''s partition, anchored by store_graph; the leading key dimension that keeps one workspace''s graphs apart';
COMMENT ON COLUMN graphitron_ast_federation_link_entry.source_name IS 'the file the application was written in';
COMMENT ON COLUMN graphitron_ast_federation_link_entry.source_line IS 'source line of the at sign, 1-based per the graphql-java convention';
COMMENT ON COLUMN graphitron_ast_federation_link_entry.source_column IS 'source column of the same. The four key columns are the link entry''s, so this row decodes exactly one application graphitron_ast_link_entry holds';
COMMENT ON COLUMN graphitron_ast_federation_link_entry.touched_at IS 'when the reading that produced this row ran, swept with the schema site''s other entries';
COMMENT ON COLUMN graphitron_ast_federation_link_entry.version IS 'what the url names after the federation specification''s prefix, as written, for example v2.10. Not parsed further, nothing reading a version yet';

CREATE TABLE graphitron_ast_link_import_entry (
  graph_name    VARCHAR NOT NULL,
  source_name   VARCHAR NOT NULL,
  source_line   INT     NOT NULL,
  source_column INT     NOT NULL,
  touched_at    TIMESTAMP NOT NULL,
  name          VARCHAR NOT NULL,
  alias         VARCHAR,
  PRIMARY KEY (graph_name, source_name, source_line, source_column),
  FOREIGN KEY (graph_name) REFERENCES store_graph (graph_name),
  FOREIGN KEY (graph_name, source_name, source_line, source_column)
    REFERENCES graphql_ast_value_entry (graph_name, source_name, source_line, source_column)
    ON DELETE CASCADE
);
COMMENT ON TABLE graphitron_ast_link_import_entry IS 'One import element of a @link application, at its position in the list, as written. For example import: ["@key", {name: "@shareable", as: "@federatedShareable"}] gives two rows, the second carrying an alias.';
COMMENT ON COLUMN graphitron_ast_link_import_entry.graph_name IS 'the owning graph''s partition, anchored by store_graph; the leading key dimension that keeps one workspace''s graphs apart';
COMMENT ON COLUMN graphitron_ast_link_import_entry.source_name IS 'the file the element was written in';
COMMENT ON COLUMN graphitron_ast_link_import_entry.source_line IS 'source line of the element this row decodes, 1-based per the graphql-java convention';
COMMENT ON COLUMN graphitron_ast_link_import_entry.source_column IS 'source column of the same. The four columns are the element''s own key in graphql_ast_value_entry, so the list it sits in, the index it was written at and the application holding it are one join away rather than columns here';
COMMENT ON COLUMN graphitron_ast_link_import_entry.touched_at IS 'when the reading that produced this row ran. The reading finishes by deleting its file''s rows carrying an older instant, which are the applications the author removed or renamed in place; an application the author moved is swept with the directive row it hangs on';
COMMENT ON COLUMN graphitron_ast_link_import_entry.name IS 'the name the element imports, taken from the element itself where it was written as a bare string and from its name field where it was written as an object. NOT NULL because it is the element''s whole identity: an element that named nothing imports nothing, and the applied-directive row already says the @link was applied';
COMMENT ON COLUMN graphitron_ast_link_import_entry.alias IS 'the local name the element binds the import to, from an object element''s as field, NULL on a bare string and on an object that wrote none. NULL is the fact that the import keeps its own name rather than a default filled in here';

CREATE TABLE graphitron_ast_compose_directive_entry (
  graph_name     VARCHAR NOT NULL,
  source_name    VARCHAR NOT NULL,
  source_line    INT     NOT NULL,
  source_column  INT     NOT NULL,
  touched_at     TIMESTAMP NOT NULL,
  directive_name VARCHAR NOT NULL,
  PRIMARY KEY (graph_name, source_name, source_line, source_column),
  FOREIGN KEY (graph_name) REFERENCES store_graph (graph_name),
  FOREIGN KEY (graph_name, source_name, source_line, source_column)
    REFERENCES graphql_ast_directive_application_entry (graph_name, source_name, source_line, source_column)
    ON DELETE CASCADE
);
COMMENT ON TABLE graphitron_ast_compose_directive_entry IS 'What a schema-level @composeDirective application says: the directive the schema asks the supergraph to carry, as written. For example extend schema @composeDirective(name: "@nodeType") gives one row whose directive_name is @nodeType.';
COMMENT ON COLUMN graphitron_ast_compose_directive_entry.graph_name IS 'the owning graph''s partition, anchored by store_graph; the leading key dimension that keeps one workspace''s graphs apart';
COMMENT ON COLUMN graphitron_ast_compose_directive_entry.source_name IS 'the file the application was written in';
COMMENT ON COLUMN graphitron_ast_compose_directive_entry.source_line IS 'source line of the at sign, 1-based per the graphql-java convention';
COMMENT ON COLUMN graphitron_ast_compose_directive_entry.source_column IS 'source column of the same. The four key columns are the applied directive''s own key, so this row is the decode of exactly one row of graphql_ast_directive_application_entry and neither carries what the other holds';
COMMENT ON COLUMN graphitron_ast_compose_directive_entry.touched_at IS 'when the reading that produced this row ran. The reading finishes by deleting its file''s rows carrying an older instant, which are the applications the author removed or renamed in place; an application the author moved is swept with the directive row it hangs on';
COMMENT ON COLUMN graphitron_ast_compose_directive_entry.directive_name IS 'the name argument decoded to the string the author wrote, with its leading at sign, which is how federation asks for a directive by name. NOT NULL because it is the application''s whole payload: an application that wrote no string name asks for nothing, and the applied-directive row already says the directive was applied';

CREATE TABLE graphitron_ast_node_entry (
  graph_name    VARCHAR NOT NULL,
  source_name   VARCHAR NOT NULL,
  source_line   INT     NOT NULL,
  source_column INT     NOT NULL,
  touched_at    TIMESTAMP NOT NULL,
  type_id       VARCHAR,
  resolvable    BOOLEAN,
  PRIMARY KEY (graph_name, source_name, source_line, source_column),
  FOREIGN KEY (graph_name) REFERENCES store_graph (graph_name),
  FOREIGN KEY (graph_name, source_name, source_line, source_column)
    REFERENCES graphql_ast_directive_application_entry (graph_name, source_name, source_line, source_column)
    ON DELETE CASCADE
);
COMMENT ON TABLE graphitron_ast_node_entry IS 'What a @node application says: that the type is addressable by an opaque id, and what it calls itself inside one, as written. For example type Film @node(typeId: "F") gives one row whose type_id is F.';
COMMENT ON COLUMN graphitron_ast_node_entry.graph_name IS 'the owning graph''s partition, anchored by store_graph; the leading key dimension that keeps one workspace''s graphs apart';
COMMENT ON COLUMN graphitron_ast_node_entry.source_name IS 'the file the application was written in';
COMMENT ON COLUMN graphitron_ast_node_entry.source_line IS 'source line of the at sign, 1-based per the graphql-java convention';
COMMENT ON COLUMN graphitron_ast_node_entry.source_column IS 'source column of the same. The four key columns are the applied directive''s own key, so this row is the decode of exactly one row of graphql_ast_directive_application_entry and neither carries what the other holds';
COMMENT ON COLUMN graphitron_ast_node_entry.touched_at IS 'when the reading that produced this row ran. The reading finishes by deleting its file''s rows carrying an older instant, which are the applications the author removed or renamed in place; an application the author moved is swept with the directive row it hangs on';
COMMENT ON COLUMN graphitron_ast_node_entry.type_id IS 'the typeId argument decoded to the string the author wrote, or NULL where they wrote none or wrote something that is not a string. NULL is the fact that the author left it out, which the directive documents as meaning the type''s own name; substituting the name here would lose which of the two they wrote';
COMMENT ON COLUMN graphitron_ast_node_entry.resolvable IS 'the resolvable argument as the author wrote it, or NULL where they wrote none or wrote something that is not a Boolean. NULL is the directive''s default, true, which graphitron_node reads it as; false is a stub of an entity another subgraph owns, a node for its id that this subgraph does not fetch by it';

CREATE TABLE graphitron_ast_node_keycolumn_entry (
  graph_name         VARCHAR NOT NULL,
  source_name        VARCHAR NOT NULL,
  source_line        INT     NOT NULL,
  source_column      INT     NOT NULL,
  touched_at         TIMESTAMP NOT NULL,
  application_line   INT     NOT NULL,
  application_column INT     NOT NULL,
  position           INT     NOT NULL,
  column_ref         VARCHAR NOT NULL,
  PRIMARY KEY (graph_name, source_name, source_line, source_column),
  UNIQUE (graph_name, source_name, application_line, application_column, position),
  CHECK (position >= 0),
  FOREIGN KEY (graph_name) REFERENCES store_graph (graph_name),
  FOREIGN KEY (graph_name, source_name, source_line, source_column)
    REFERENCES graphql_ast_value_entry (graph_name, source_name, source_line, source_column)
    ON DELETE CASCADE,
  FOREIGN KEY (graph_name, source_name, application_line, application_column)
    REFERENCES graphitron_ast_node_entry (graph_name, source_name, source_line, source_column)
    ON DELETE CASCADE
);
COMMENT ON TABLE graphitron_ast_node_keycolumn_entry IS 'One keyColumns element of a @node application, as written. For example keyColumns: ["film_id"] gives one row, keyed where film_id was written.';
COMMENT ON COLUMN graphitron_ast_node_keycolumn_entry.graph_name IS 'the owning graph''s partition, anchored by store_graph; the leading key dimension that keeps one workspace''s graphs apart';
COMMENT ON COLUMN graphitron_ast_node_keycolumn_entry.source_name IS 'the file the application was written in';
COMMENT ON COLUMN graphitron_ast_node_keycolumn_entry.source_line IS 'source line the element was written at, 1-based per the graphql-java convention';
COMMENT ON COLUMN graphitron_ast_node_keycolumn_entry.source_column IS 'source column of the same. The four key columns are the element''s own position, so this row is the decode of exactly one row of graphql_ast_value_entry';
COMMENT ON COLUMN graphitron_ast_node_keycolumn_entry.touched_at IS 'when the reading that produced this row ran. The reading finishes by deleting its file''s rows carrying an older instant, which are the applications the author removed or renamed in place; an application the author moved is swept with the directive row it hangs on';
COMMENT ON COLUMN graphitron_ast_node_keycolumn_entry.application_line IS 'source line of the @node application holding the list, the parent key into graphitron_ast_node_entry together with the column beside it';
COMMENT ON COLUMN graphitron_ast_node_keycolumn_entry.application_column IS 'source column of the same';
COMMENT ON COLUMN graphitron_ast_node_keycolumn_entry.position IS 'the index the element was written at in its list, from 0, which is the place the column takes inside an id. A list written as one string rather than a list is a list of that one string, at 0';
COMMENT ON COLUMN graphitron_ast_node_keycolumn_entry.column_ref IS 'the column the element names, as the author spelled it. Whether the database has a column of that name, and whether the columns together are a key, are questions for a resolution and not for this row';

CREATE TABLE graphitron_ast_node_legacykeycolumn_entry (
  graph_name         VARCHAR NOT NULL,
  source_name        VARCHAR NOT NULL,
  source_line        INT     NOT NULL,
  source_column      INT     NOT NULL,
  touched_at         TIMESTAMP NOT NULL,
  application_line   INT     NOT NULL,
  application_column INT     NOT NULL,
  position           INT     NOT NULL,
  column_ref         VARCHAR NOT NULL,
  PRIMARY KEY (graph_name, source_name, source_line, source_column),
  UNIQUE (graph_name, source_name, application_line, application_column, position),
  CHECK (position >= 0),
  FOREIGN KEY (graph_name) REFERENCES store_graph (graph_name),
  FOREIGN KEY (graph_name, source_name, source_line, source_column)
    REFERENCES graphql_ast_value_entry (graph_name, source_name, source_line, source_column)
    ON DELETE CASCADE,
  FOREIGN KEY (graph_name, source_name, application_line, application_column)
    REFERENCES graphitron_ast_node_entry (graph_name, source_name, source_line, source_column)
    ON DELETE CASCADE
);
COMMENT ON TABLE graphitron_ast_node_legacykeycolumn_entry IS 'One legacyKeyColumns element of a @node application, as written. For example legacyKeyColumns: ["customer_id", "rental_id", "rental_date"] gives three rows, each keyed where its column was written.';
COMMENT ON COLUMN graphitron_ast_node_legacykeycolumn_entry.graph_name IS 'the owning graph''s partition, anchored by store_graph; the leading key dimension that keeps one workspace''s graphs apart';
COMMENT ON COLUMN graphitron_ast_node_legacykeycolumn_entry.source_name IS 'the file the application was written in';
COMMENT ON COLUMN graphitron_ast_node_legacykeycolumn_entry.source_line IS 'source line the element was written at, 1-based per the graphql-java convention';
COMMENT ON COLUMN graphitron_ast_node_legacykeycolumn_entry.source_column IS 'source column of the same. The four key columns are the element''s own position, so this row is the decode of exactly one row of graphql_ast_value_entry';
COMMENT ON COLUMN graphitron_ast_node_legacykeycolumn_entry.touched_at IS 'when the reading that produced this row ran. The reading finishes by deleting its file''s rows carrying an older instant, which are the applications the author removed or renamed in place; an application the author moved is swept with the directive row it hangs on';
COMMENT ON COLUMN graphitron_ast_node_legacykeycolumn_entry.application_line IS 'source line of the @node application holding the list, the parent key into graphitron_ast_node_entry together with the column beside it';
COMMENT ON COLUMN graphitron_ast_node_legacykeycolumn_entry.application_column IS 'source column of the same';
COMMENT ON COLUMN graphitron_ast_node_legacykeycolumn_entry.position IS 'the index the element was written at in its list, from 0, which is the place the column takes inside an id. A list written as one string rather than a list is a list of that one string, at 0';
COMMENT ON COLUMN graphitron_ast_node_legacykeycolumn_entry.column_ref IS 'the column the element names, as the author spelled it. Whether the database has a column of that name, and whether the list covers the current key, are questions for a resolution and not for this row';

CREATE TABLE graphitron_ast_discriminate_entry (
  graph_name    VARCHAR NOT NULL,
  source_name   VARCHAR NOT NULL,
  source_line   INT     NOT NULL,
  source_column INT     NOT NULL,
  touched_at    TIMESTAMP NOT NULL,
  on_column     VARCHAR NOT NULL,
  PRIMARY KEY (graph_name, source_name, source_line, source_column),
  FOREIGN KEY (graph_name) REFERENCES store_graph (graph_name),
  FOREIGN KEY (graph_name, source_name, source_line, source_column)
    REFERENCES graphql_ast_directive_application_entry (graph_name, source_name, source_line, source_column)
    ON DELETE CASCADE
);
COMMENT ON TABLE graphitron_ast_discriminate_entry IS 'What a @discriminate application says: the column whose value decides which subtype a row is, as written. For example interface Media @discriminate(on: "media_type") gives one row whose on_column is media_type.';
COMMENT ON COLUMN graphitron_ast_discriminate_entry.graph_name IS 'the owning graph''s partition, anchored by store_graph; the leading key dimension that keeps one workspace''s graphs apart';
COMMENT ON COLUMN graphitron_ast_discriminate_entry.source_name IS 'the file the application was written in';
COMMENT ON COLUMN graphitron_ast_discriminate_entry.source_line IS 'source line of the at sign, 1-based per the graphql-java convention';
COMMENT ON COLUMN graphitron_ast_discriminate_entry.source_column IS 'source column of the same. The four key columns are the applied directive''s own key, so this row is the decode of exactly one row of graphql_ast_directive_application_entry and neither carries what the other holds';
COMMENT ON COLUMN graphitron_ast_discriminate_entry.touched_at IS 'when the reading that produced this row ran. The reading finishes by deleting its file''s rows carrying an older instant, which are the applications the author removed or renamed in place; an application the author moved is swept with the directive row it hangs on';
COMMENT ON COLUMN graphitron_ast_discriminate_entry.on_column IS 'the on argument decoded to the string the author wrote. NOT NULL because the definition requires the argument, so an application without it is refused before a decode sees it. Whether the database has a column of that name is a question for a resolution and not for this row';

CREATE TABLE graphitron_ast_discriminator_entry (
  graph_name          VARCHAR NOT NULL,
  source_name         VARCHAR NOT NULL,
  source_line         INT     NOT NULL,
  source_column       INT     NOT NULL,
  touched_at          TIMESTAMP NOT NULL,
  discriminator_value VARCHAR NOT NULL,
  PRIMARY KEY (graph_name, source_name, source_line, source_column),
  FOREIGN KEY (graph_name) REFERENCES store_graph (graph_name),
  FOREIGN KEY (graph_name, source_name, source_line, source_column)
    REFERENCES graphql_ast_directive_application_entry (graph_name, source_name, source_line, source_column)
    ON DELETE CASCADE
);
COMMENT ON TABLE graphitron_ast_discriminator_entry IS 'What a @discriminator application says: the value of the discriminating column that means a row is this subtype, as written. For example type Book implements Media @discriminator(value: "BOOK") gives one row whose discriminator_value is BOOK.';
COMMENT ON COLUMN graphitron_ast_discriminator_entry.graph_name IS 'the owning graph''s partition, anchored by store_graph; the leading key dimension that keeps one workspace''s graphs apart';
COMMENT ON COLUMN graphitron_ast_discriminator_entry.source_name IS 'the file the application was written in';
COMMENT ON COLUMN graphitron_ast_discriminator_entry.source_line IS 'source line of the at sign, 1-based per the graphql-java convention';
COMMENT ON COLUMN graphitron_ast_discriminator_entry.source_column IS 'source column of the same. The four key columns are the applied directive''s own key, so this row is the decode of exactly one row of graphql_ast_directive_application_entry and neither carries what the other holds';
COMMENT ON COLUMN graphitron_ast_discriminator_entry.touched_at IS 'when the reading that produced this row ran. The reading finishes by deleting its file''s rows carrying an older instant, which are the applications the author removed or renamed in place; an application the author moved is swept with the directive row it hangs on';
COMMENT ON COLUMN graphitron_ast_discriminator_entry.discriminator_value IS 'the value argument decoded to the string the author wrote. NOT NULL because the definition requires the argument, so an application without it is refused before a decode sees it. Always a string here whatever the column''s SQL type, the comparison being the resolution''s to make';

CREATE TABLE graphitron_ast_federation_key_entry (
  graph_name    VARCHAR NOT NULL,
  source_name   VARCHAR NOT NULL,
  source_line   INT     NOT NULL,
  source_column INT     NOT NULL,
  touched_at    TIMESTAMP NOT NULL,
  fields_sdl    VARCHAR NOT NULL,
  resolvable    BOOLEAN,
  PRIMARY KEY (graph_name, source_name, source_line, source_column),
  FOREIGN KEY (graph_name) REFERENCES store_graph (graph_name),
  FOREIGN KEY (graph_name, source_name, source_line, source_column)
    REFERENCES graphql_ast_directive_application_entry (graph_name, source_name, source_line, source_column)
    ON DELETE CASCADE
);
COMMENT ON TABLE graphitron_ast_federation_key_entry IS 'What a federation @key application says: the field set naming the entity''s key, and whether the subgraph resolves it, as written. For example type Film @key(fields: "id reviews { id }") gives one row carrying that field set verbatim.';
COMMENT ON COLUMN graphitron_ast_federation_key_entry.graph_name IS 'the owning graph''s partition, anchored by store_graph; the leading key dimension that keeps one workspace''s graphs apart';
COMMENT ON COLUMN graphitron_ast_federation_key_entry.source_name IS 'the file the application was written in';
COMMENT ON COLUMN graphitron_ast_federation_key_entry.source_line IS 'source line of the at sign, 1-based per the graphql-java convention';
COMMENT ON COLUMN graphitron_ast_federation_key_entry.source_column IS 'source column of the same, so this row is the decode of exactly one row of graphql_ast_directive_application_entry and neither carries what the other holds';
COMMENT ON COLUMN graphitron_ast_federation_key_entry.touched_at IS 'when the reading that produced this row ran. The reading finishes by deleting its file''s rows carrying an older instant, which are the applications the author removed or renamed in place; an application the author moved is swept with the directive row it hangs on';
COMMENT ON COLUMN graphitron_ast_federation_key_entry.fields_sdl IS 'the fields argument as the author typed it, kept whole beside the selections it parsed into. The parse is a reading and this is what was read, so a reader wanting to re-emit the directive takes this column and a reader wanting its structure takes the rows below';
COMMENT ON COLUMN graphitron_ast_federation_key_entry.resolvable IS 'the resolvable argument decoded to the boolean the author wrote, or NULL where they wrote none. NULL rather than true, the directive''s declared default being a generator constant and not a fact about the document';

CREATE TABLE graphitron_ast_federation_key_selection_entry (
  graph_name    VARCHAR NOT NULL,
  source_name   VARCHAR NOT NULL,
  source_line   INT     NOT NULL,
  source_column INT     NOT NULL,
  position      INT     NOT NULL,
  touched_at    TIMESTAMP NOT NULL,
  PRIMARY KEY (graph_name, source_name, source_line, source_column, position),
  FOREIGN KEY (graph_name) REFERENCES store_graph (graph_name),
  FOREIGN KEY (graph_name, source_name, source_line, source_column)
    REFERENCES graphitron_ast_federation_key_entry (graph_name, source_name, source_line, source_column)
    ON DELETE CASCADE
);
COMMENT ON TABLE graphitron_ast_federation_key_selection_entry IS 'One leaf selection the field set parsed into, at its index in that parse. For example "id reviews { id }" gives two rows, one for id and one for the id inside reviews.';
COMMENT ON COLUMN graphitron_ast_federation_key_selection_entry.graph_name IS 'the owning graph''s partition, anchored by store_graph; the leading key dimension that keeps one workspace''s graphs apart';
COMMENT ON COLUMN graphitron_ast_federation_key_selection_entry.source_name IS 'the file the application was written in';
COMMENT ON COLUMN graphitron_ast_federation_key_selection_entry.source_line IS 'source line of the at sign, 1-based per the graphql-java convention';
COMMENT ON COLUMN graphitron_ast_federation_key_selection_entry.source_column IS 'source column of the same, so the four together name the application whose field set was parsed';
COMMENT ON COLUMN graphitron_ast_federation_key_selection_entry.touched_at IS 'when the reading that produced this row ran. The reading finishes by deleting its file''s rows carrying an older instant, which are the applications the author removed or renamed in place; an application the author moved is swept with the directive row it hangs on';
COMMENT ON COLUMN graphitron_ast_federation_key_selection_entry.position IS 'the index of this selection in the field set, counting leaves in written order. The grammar yields a list and a relation holds a set, so the order is a column; a decoded element that is a node the author wrote needs none, being identified by the position it was written at';

CREATE TABLE graphitron_ast_federation_key_segment_entry (
  graph_name    VARCHAR NOT NULL,
  source_name   VARCHAR NOT NULL,
  source_line   INT     NOT NULL,
  source_column INT     NOT NULL,
  position         INT     NOT NULL,
  segment_position INT     NOT NULL,
  touched_at       TIMESTAMP NOT NULL,
  segment_name     VARCHAR NOT NULL,
  PRIMARY KEY (graph_name, source_name, source_line, source_column, position, segment_position),
  FOREIGN KEY (graph_name) REFERENCES store_graph (graph_name),
  FOREIGN KEY (graph_name, source_name, source_line, source_column, position)
    REFERENCES graphitron_ast_federation_key_selection_entry
      (graph_name, source_name, source_line, source_column, position)
    ON DELETE CASCADE
);
COMMENT ON TABLE graphitron_ast_federation_key_segment_entry IS 'One segment of one parsed selection, at its depth from the outermost inward. For example the selection reached by "reviews { id }" gives two rows, reviews then id.';
COMMENT ON COLUMN graphitron_ast_federation_key_segment_entry.graph_name IS 'the owning graph''s partition, anchored by store_graph; the leading key dimension that keeps one workspace''s graphs apart';
COMMENT ON COLUMN graphitron_ast_federation_key_segment_entry.source_name IS 'the file the application was written in';
COMMENT ON COLUMN graphitron_ast_federation_key_segment_entry.source_line IS 'source line of the at sign, 1-based per the graphql-java convention';
COMMENT ON COLUMN graphitron_ast_federation_key_segment_entry.source_column IS 'source column of the same, so the four together name the application whose field set was parsed';
COMMENT ON COLUMN graphitron_ast_federation_key_segment_entry.touched_at IS 'when the reading that produced this row ran. The reading finishes by deleting its file''s rows carrying an older instant, which are the applications the author removed or renamed in place; an application the author moved is swept with the directive row it hangs on';
COMMENT ON COLUMN graphitron_ast_federation_key_segment_entry.position IS 'which selection of the parse this segment belongs to';
COMMENT ON COLUMN graphitron_ast_federation_key_segment_entry.segment_position IS 'the depth of this segment within that selection, zero being the outermost. Nesting survives the parse as segments rather than being rendered back into a dotted name a reader would take apart again';
COMMENT ON COLUMN graphitron_ast_federation_key_segment_entry.segment_name IS 'the field this segment names, as the grammar cut it. Whether the type declares such a field is a question for a resolution and not for this row';

CREATE TABLE graphitron_deprecated (
  graph_name VARCHAR NOT NULL,
  coordinate VARCHAR NOT NULL,
  reason     VARCHAR NOT NULL,
  touched_at TIMESTAMP NOT NULL,
  PRIMARY KEY (graph_name, coordinate),
  FOREIGN KEY (graph_name) REFERENCES store_graph (graph_name),
  FOREIGN KEY (graph_name, coordinate) REFERENCES graphql_element (graph_name, coordinate)
    ON DELETE CASCADE
);
COMMENT ON TABLE graphitron_deprecated IS 'This schema element is deprecated, and this is the replacement hint the author gave: whatever the corpus retired, under the coordinate that names it. For example a retired directive draws the row @asConnection and a retired argument of one draws @asConnection(connectionName:).';
COMMENT ON COLUMN graphitron_deprecated.graph_name IS 'the owning graph''s partition, anchored by store_graph';
COMMENT ON COLUMN graphitron_deprecated.coordinate IS 'the element that was deprecated, in the specification''s grammar. No foreign key into graphql_element, and the reason is a producer rather than the model: that relation still has two writers, and the older one predates the two directive coordinate kinds, so a row here naming a retired directive would resolve under one producer and dangle under the other. The key becomes a reference the day the second writer goes. One relation rather than three, which is what a coordinate buys: this was a relation per shape of key, a directive under its name, an argument of one under two names, an input field under a type and a field, each carrying the same reason under a differently spelled key. A reader asking whether something is deprecated asks once and does not sort out which of three relations to ask';
COMMENT ON COLUMN graphitron_deprecated.reason IS 'the replacement hint, as the author wrote it. Empty where the marker carried none, which is a marker without advice rather than no marker: absence of a row is what says a thing is not deprecated. Which of the two markers said so is not recorded and not asked. GraphQL forces them apart, the native marker being illegal on a directive definition, so a retired directive says so with a token in its description instead; unifying the two is what this family is for';
COMMENT ON COLUMN graphitron_deprecated.touched_at IS 'when the reading that derived this row ran, on graphql_element.touched_at''s terms: swept per graph, and NOT NULL so the sweep is total';

CREATE TABLE graphitron_field_reference_entry (
  graph_name    VARCHAR NOT NULL,
  type_name     VARCHAR NOT NULL,
  field_name    VARCHAR NOT NULL,
  ordinal       INT     NOT NULL,
  source_name   VARCHAR,
  source_line   INT,
  source_column INT,
  PRIMARY KEY (graph_name, type_name, field_name, ordinal),
  FOREIGN KEY (graph_name, type_name, field_name) REFERENCES graphql_field_element (graph_name, type_name, field_name)
    ON DELETE CASCADE
);
COMMENT ON TABLE graphitron_field_reference_entry IS '@reference on a field or input field: one row per application, because an application is a fact of its own. An empty path means FK auto-discovery between the endpoints, and the rule that every application in a multi-application chain must carry an element is per-application; both are invisible in a flat concatenated chain. The effective chain the consumers read is the steps ordered by (ordinal, position), and the written-order interleaving with @routine applications on the same field is an ORDER BY over the two relations'' source positions. Deprecated: written by the decode the incumbent walk drives, which goes when the decode reads the entry relations instead of a registry. Nothing has been written to replace it yet.';
COMMENT ON COLUMN graphitron_field_reference_entry.graph_name IS 'the owning graph''s partition, anchored by store_graph; the leading key dimension that keeps one workspace''s graphs apart';
COMMENT ON COLUMN graphitron_field_reference_entry.type_name IS 'the GraphQL type this row is about';
COMMENT ON COLUMN graphitron_field_reference_entry.field_name IS 'the field name within the owning type';
COMMENT ON COLUMN graphitron_field_reference_entry.ordinal IS 'repeatable; document order';
COMMENT ON COLUMN graphitron_field_reference_entry.source_name IS 'the SDL file the row was captured from';
COMMENT ON COLUMN graphitron_field_reference_entry.source_line IS 'source line, 1-based per the graphql-java convention';
COMMENT ON COLUMN graphitron_field_reference_entry.source_column IS 'source column, 1-based per the graphql-java convention';

-- @experimental_constructType has no relation, and unlike every other name in this section it
-- is not a graphitron directive: its declaration in directives.graphqls is a bug (the census
-- found no consumer anywhere; the declaration's only effect is that emission strips
-- applications, silently swallowing a directive graphitron does not own). Once the stray
-- declaration is removed the name is foreign like any user-authored directive and its
-- applications land in the graphql_ family as fidelity rows, re-emitted verbatim; the store
-- needs no special case for it.

-- Retired directives get no relation of their own; graphql_directive_application holds their
-- applications.
--
-- @notGenerated, like @experimental_constructType above, is not a graphitron directive and its
-- declaration in directives.graphqls is a bug, so it gets no relations. Once the stray
-- declaration is removed its applications take the graphql_ fidelity path, and the current
-- hard rejection ("no longer supported") becomes, if it is kept at all, a detection over the
-- directive name in the graphql_ rows; whether to keep steering on a name graphitron does not
-- own is a directive-lifecycle question outside this spec.

-- ==== The element family the generator emits ======================================
-- Every schema element the generator works with, the author's and the ones macro expansion minted,
-- at one key and at the grain each kind is asked about. graphitron_element is the supertype over
-- graphitron_type, graphitron_field and graphitron_argument, which is graphql_element and its
-- subtypes with one difference. The graphql side splits an element's existence from its attributes
-- because the two sit at different cadences, a coordinate settled by the per-file parse and a
-- payload only once the document composes; this family is derived at one cadence, so anchor and
-- payload are one relation and graphitron_type carries the kind and the description that
-- graphql_type carries beside graphql_type_element.
--
-- The anchors carry the payload rather than joining the twin for it. A minted element has no twin,
-- so a reader that joins graphql_field for the details is reading a union again, which is the shape
-- this family exists to remove; the copy is bounded by schema size and not by data. The line it
-- draws is that the anchor carries what rendering needs and the twin keeps what only the
-- transcription can assert, which is why graphql_field.declaration_line and its foreign key into
-- graphql_type_declaration do not come across: a minted field has no declaration site to point at,
-- and a reader asking where an element was written is asking the transcription's question and reads
-- it there.
--
-- This is where a graphitron relation keys. A foreign key into graphql_*_element excludes exactly
-- the coordinates macro expansion minted, which is what a connection is made of, so a graphitron
-- relation naming a coordinate names one of these instead; graphitron_field was written with the
-- other key once and the build failed on QueryFilmsConnection.nodes.
--
-- Three subtypes and not the transcription's four. Enum values are minted by nothing and asked for
-- by no reader here, so an anchor over them would be a copy of graphql_enum_value with no question
-- to answer; the CHECK on element_kind is where that boundary is stated rather than left to the
-- population, and an emitter reading this family for a whole schema is what would move it.

CREATE TABLE graphitron_element (
  graph_name        VARCHAR NOT NULL,
  coordinate        VARCHAR NOT NULL,
  element_kind      VARCHAR NOT NULL,
  touched_at        TIMESTAMP NOT NULL,
  PRIMARY KEY (graph_name, coordinate),
  FOREIGN KEY (graph_name) REFERENCES store_graph (graph_name),
  CHECK (element_kind IN ('NAMED_TYPE', 'FIELD', 'INPUT_FIELD', 'ENUM_VALUE', 'FIELD_ARGUMENT'))
);
COMMENT ON TABLE graphitron_element IS 'A schema element the generator emits exists in this graph, whether an author declared it or macro expansion minted it: the supertype of the four element relations beside it, keyed by the schema coordinate the GraphQL specification spells for it. For example a QueryFilmsConnection no author wrote is the row QueryFilmsConnection here and no row at all in graphql_element, and the field carrying the macro is one row in each.';
COMMENT ON COLUMN graphitron_element.graph_name IS 'the owning graph''s partition, anchored by store_graph; the leading key dimension that keeps one workspace''s graphs apart';
COMMENT ON COLUMN graphitron_element.coordinate IS 'the coordinate itself, in the specification''s own grammar and spelled exactly as graphql_element spells it: Type for a named type, Type.field for a field or an input field of one, and Type.field(argument:) for an argument of a field. Total by construction, which is what lets one column stand for a coordinate of any kind where the decomposed keys beside it cannot';
COMMENT ON COLUMN graphitron_element.element_kind IS 'which kind of schema element this row is, in the specification''s own vocabulary, and so which relation beside this one a reader joins to get the parts, FIELD and INPUT_FIELD sharing one. Five of the specification''s seven kinds, the two directive forms being the ones left out';
COMMENT ON COLUMN graphitron_element.touched_at IS 'the reading that last wrote this row, which is what its sweep tells readings apart by: a row this reading did not rewrite is one the corpus stopped stating and goes. The other half of the lifecycle the walk''s clear used to stand in for, the cascade above being the first';

CREATE TABLE graphitron_type (
  graph_name  VARCHAR NOT NULL,
  type_name   VARCHAR NOT NULL,
  coordinate  VARCHAR GENERATED ALWAYS AS (type_name) NOT NULL,
  kind        VARCHAR NOT NULL,
  origin      VARCHAR NOT NULL,
  description VARCHAR,
  PRIMARY KEY (graph_name, type_name),
  -- What a subtype references, so a subtype row can only hang under a type of the kind it is for:
  -- a table is an object or an interface, and a node is a table.
  UNIQUE (graph_name, type_name, kind),
  FOREIGN KEY (graph_name, coordinate) REFERENCES graphitron_element (graph_name, coordinate),
  CHECK (kind IN ('OBJECT', 'INTERFACE', 'UNION', 'ENUM', 'INPUT_OBJECT', 'SCALAR')),
  CHECK (origin IN ('AUTHORED', 'MINTED', 'FEDERATION'))
);
COMMENT ON TABLE graphitron_type IS 'Every type the generator works with, the author''s and the ones macro expansion minted, under one key: one row per type name in the graph. For example a Connection type the connection macro minted sits here beside the type whose field carried the macro. Total from federation-vocabulary on, the stage adding the last population, so a consumer from there joins this rather than left-joining it.';
COMMENT ON COLUMN graphitron_type.graph_name IS 'the owning graph''s partition, carried from whichever arm supplied the row; the leading key dimension that keeps one workspace''s graphs apart';
COMMENT ON COLUMN graphitron_type.type_name IS 'the type''s name; with the graph, the grain, and one row per name however many declaration sites or minting sites contributed to it';
COMMENT ON COLUMN graphitron_type.coordinate IS 'this row as graphitron_element spells it, which for a type is the type name beside it; the join down from the supertype, so a reader holding a coordinate reaches the parts here rather than splitting the spelling. Generated from the key columns beside it, so nothing writes it; the foreign key into graphitron_element is what holds that relation''s spelling to this one';
COMMENT ON COLUMN graphitron_type.kind IS 'the type''s kind in graphql_type''s vocabulary, carried across rather than restated so a reader joins one column whichever arm supplied its row';
COMMENT ON COLUMN graphitron_type.origin IS 'which population answered: AUTHORED, a type a document declares; MINTED, one a macro adds; FEDERATION, a scalar or enum of the federation vocabulary the graph imports. Each population is written and swept by the stage that owns it, macro-expansion the first two and federation-vocabulary the third';
COMMENT ON COLUMN graphitron_type.description IS 'the docstring the generator emits: authored on an authored type, with its file''s configured note appended, which mints it, and written by the macro on a minted one; display material, never a dimension';

CREATE TABLE graphitron_field (
  graph_name        VARCHAR NOT NULL,
  type_name         VARCHAR NOT NULL,
  field_name        VARCHAR NOT NULL,
  coordinate        VARCHAR GENERATED ALWAYS AS (type_name || '.' || field_name) NOT NULL,
  ordinal           INT     NOT NULL,
  type_sdl          VARCHAR NOT NULL,
  named_type        VARCHAR NOT NULL,
  non_null          BOOLEAN NOT NULL,
  list_depth        INT     NOT NULL,
  is_list           BOOLEAN GENERATED ALWAYS AS (list_depth > 0) NOT NULL,
  item_non_null     BOOLEAN,
  default_value_sdl VARCHAR,
  description       VARCHAR,
  bound_name        VARCHAR NOT NULL,
  bound_name_upper  VARCHAR GENERATED ALWAYS AS (UPPER(bound_name)),
  PRIMARY KEY (graph_name, type_name, field_name),
  UNIQUE (graph_name, coordinate),
  FOREIGN KEY (graph_name, type_name) REFERENCES graphitron_type (graph_name, type_name),
  FOREIGN KEY (graph_name, coordinate) REFERENCES graphitron_element (graph_name, coordinate),
  CHECK (is_list OR item_non_null IS NULL)
);
COMMENT ON TABLE graphitron_field IS 'Every field the generator works with, at the type expression it works with: one row per field coordinate, output and input alike, carrying the wrapping columns graphql_field carries. For example a field the connection macro rewrote reads here as the Connection it returns, where graphql_field is where a reader goes for what the author wrote instead.';
COMMENT ON COLUMN graphitron_field.graph_name IS 'the owning graph''s partition, carried from whichever arm supplied the row';
COMMENT ON COLUMN graphitron_field.type_name IS 'the type owning the field, anchored by graphitron_type';
COMMENT ON COLUMN graphitron_field.field_name IS 'the field''s name within the owning type; with the two columns above, the grain';
COMMENT ON COLUMN graphitron_field.coordinate IS 'this row as graphitron_element spells it, Type.field in the specification''s grammar; the join down from the supertype, on graphitron_type.coordinate''s terms. Generated from the key columns beside it, so nothing writes it; the foreign key into graphitron_element is what holds that relation''s spelling to this one';
COMMENT ON COLUMN graphitron_field.ordinal IS 'the field''s position within its type, merge-ordered across declaration sites exactly as graphql_field numbers it, and the order the macro wrote them in on a minted type';
COMMENT ON COLUMN graphitron_field.type_sdl IS 'the type expression as the generator reads it: the authored literal on an ordinary field, and the macro''s rewrite where one happened';
COMMENT ON COLUMN graphitron_field.named_type IS 'that expression''s named type with its list and non-null wrappers stripped, which is the column readers actually join on';
COMMENT ON COLUMN graphitron_field.non_null IS 'whether the outermost wrapper is non-null';
COMMENT ON COLUMN graphitron_field.list_depth IS 'how many list wrappers the expression has: 0 for a named type, 1 for a list of one, 2 for a list of lists, as graphql_ states it for what the author wrote and the macro expansion for what it mints';
COMMENT ON COLUMN graphitron_field.is_list IS 'whether the expression is a list. Generated from list_depth, so nothing writes it';
COMMENT ON COLUMN graphitron_field.item_non_null IS 'whether a list''s item is non-null; NULL where the expression is not a list, which the CHECK holds';
COMMENT ON COLUMN graphitron_field.default_value_sdl IS 'the default literal where the coordinate is an input field with one; display material, never a dimension';
COMMENT ON COLUMN graphitron_field.description IS 'the docstring the generator emits: authored, with its file''s configured note appended, which mints it, or macro-written; display material, never a dimension';
COMMENT ON COLUMN graphitron_field.bound_name IS 'the name the field reads by: its @field(name:) where the field''s first @field application wrote one, else the field''s own name. Stated once here so that no reader joins the binding and falls back to the field name itself; what a name finds, a column or a member of a class, is the reader''s question';
COMMENT ON COLUMN graphitron_field.bound_name_upper IS 'the upper-cased form of bound_name, for the case-insensitive match against sql_column''s column_name_upper and jooq_name_upper. Generated, so nothing writes it';
CREATE INDEX graphitron_field_name_ix ON graphitron_field (graph_name, field_name);
COMMENT ON INDEX graphitron_field_name_ix IS 'Serves a rule asking a graph for the fields of one name, as the Relay shape names its edges and node fields: without it, a rule filtered to one graph probes the fields by graph alone, and graphitron_edge_rule did so once per object type, 2.9 s on sis against 0.1 s with this index.';

CREATE TABLE graphitron_enum_value (
  graph_name  VARCHAR NOT NULL,
  type_name   VARCHAR NOT NULL,
  value_name  VARCHAR NOT NULL,
  coordinate  VARCHAR GENERATED ALWAYS AS (type_name || '.' || value_name) NOT NULL,
  ordinal     INT     NOT NULL,
  description VARCHAR,
  PRIMARY KEY (graph_name, type_name, value_name),
  UNIQUE (graph_name, coordinate),
  FOREIGN KEY (graph_name, type_name) REFERENCES graphitron_type (graph_name, type_name),
  FOREIGN KEY (graph_name, coordinate) REFERENCES graphitron_element (graph_name, coordinate)
);
COMMENT ON TABLE graphitron_enum_value IS 'Every enum value the generator emits: one row per enum value coordinate. For example enum Rating { G PG } is the rows Rating.G and Rating.PG. Authored only, the macros minting no enum.';
COMMENT ON COLUMN graphitron_enum_value.graph_name IS 'the owning graph''s partition';
COMMENT ON COLUMN graphitron_enum_value.type_name IS 'the enum the value belongs to, anchored by graphitron_type';
COMMENT ON COLUMN graphitron_enum_value.value_name IS 'the value''s name within its enum; with the two columns above, the grain';
COMMENT ON COLUMN graphitron_enum_value.coordinate IS 'this row as graphitron_element spells it, Type.VALUE. Generated from the key columns beside it, so nothing writes it; the foreign key into graphitron_element is what holds that relation''s spelling to this one';
COMMENT ON COLUMN graphitron_enum_value.ordinal IS 'the value''s position in the effective enum, as graphql_enum_value numbers it';
COMMENT ON COLUMN graphitron_enum_value.description IS 'the docstring the generator emits: authored, with its file''s configured note appended, which mints it; display material, never a dimension';

CREATE TABLE graphitron_argument (
  graph_name        VARCHAR NOT NULL,
  type_name         VARCHAR NOT NULL,
  field_name        VARCHAR NOT NULL,
  argument_name     VARCHAR NOT NULL,
  coordinate        VARCHAR GENERATED ALWAYS AS (type_name || '.' || field_name || '(' || argument_name || ':)') NOT NULL,
  ordinal           INT     NOT NULL,
  type_sdl          VARCHAR NOT NULL,
  named_type        VARCHAR NOT NULL,
  non_null          BOOLEAN NOT NULL,
  list_depth        INT     NOT NULL,
  is_list           BOOLEAN GENERATED ALWAYS AS (list_depth > 0) NOT NULL,
  item_non_null     BOOLEAN,
  default_value_sdl VARCHAR,
  description       VARCHAR,
  PRIMARY KEY (graph_name, type_name, field_name, argument_name),
  UNIQUE (graph_name, coordinate),
  FOREIGN KEY (graph_name, type_name, field_name)
    REFERENCES graphitron_field (graph_name, type_name, field_name),
  FOREIGN KEY (graph_name, coordinate) REFERENCES graphitron_element (graph_name, coordinate),
  CHECK (is_list OR item_non_null IS NULL)
);
COMMENT ON TABLE graphitron_argument IS 'Every field argument the generator works with, the author''s and the ones macro expansion minted: one row per argument coordinate, carrying the wrapping columns graphql_argument carries. For example the first and after arguments a connection carrier gets when its author wrote no pagination argument sit here, where graphql_argument holds only what the document declares and therefore holds no row for them.';
COMMENT ON COLUMN graphitron_argument.graph_name IS 'the owning graph''s partition, carried from whichever arm supplied the row';
COMMENT ON COLUMN graphitron_argument.type_name IS 'owning type of the field the argument sits on';
COMMENT ON COLUMN graphitron_argument.field_name IS 'the field the argument sits on, anchored by graphitron_field';
COMMENT ON COLUMN graphitron_argument.argument_name IS 'the argument''s name within the owning field; with the three columns above, the grain';
COMMENT ON COLUMN graphitron_argument.coordinate IS 'this row as graphitron_element spells it, Type.field(argument:) in the specification''s grammar, the trailing colon included because the specification writes it. Generated from the key columns beside it, so nothing writes it; the foreign key into graphitron_element is what holds that relation''s spelling to this one';
COMMENT ON COLUMN graphitron_argument.ordinal IS 'the argument''s position within its field, declaration order on an authored one and the order the macro appended on a minted one, which is after every authored argument';
COMMENT ON COLUMN graphitron_argument.type_sdl IS 'the type expression as the generator reads it';
COMMENT ON COLUMN graphitron_argument.named_type IS 'that expression''s named type with its list and non-null wrappers stripped, which is the column readers actually join on';
COMMENT ON COLUMN graphitron_argument.non_null IS 'whether the outermost wrapper is non-null';
COMMENT ON COLUMN graphitron_argument.list_depth IS 'how many list wrappers the expression has: 0 for a named type, 1 for a list of one, 2 for a list of lists, as graphql_ states it for what the author wrote and the macro expansion for what it mints';
COMMENT ON COLUMN graphitron_argument.is_list IS 'whether the expression is a list. Generated from list_depth, so nothing writes it';
COMMENT ON COLUMN graphitron_argument.item_non_null IS 'whether a list''s item is non-null; NULL where the expression is not a list, which the CHECK holds';
COMMENT ON COLUMN graphitron_argument.default_value_sdl IS 'the default literal where the argument has one, authored or written by the macro; display material, never a dimension';
COMMENT ON COLUMN graphitron_argument.description IS 'the docstring the generator emits: authored, with its file''s configured note appended, which mints it, or macro-written; display material, never a dimension';

CREATE TABLE graphitron_directive_application (
  graph_name     VARCHAR NOT NULL,
  coordinate     VARCHAR NOT NULL,
  directive_name VARCHAR NOT NULL,
  ordinal        INT     NOT NULL,
  origin         VARCHAR NOT NULL,
  source_name    VARCHAR,
  source_line    INT,
  source_column  INT,
  touched_at     TIMESTAMP NOT NULL,
  PRIMARY KEY (graph_name, coordinate, directive_name, ordinal),
  FOREIGN KEY (graph_name, coordinate) REFERENCES graphitron_element (graph_name, coordinate)
    ON DELETE CASCADE,
  CHECK (origin IN ('AUTHORED', 'CONFIGURED', 'MINTED')),
  -- Both ways: an application nobody wrote has no position, and an authored one is read from
  -- graphql_directive_application, where every application has one.
  CHECK ((origin = 'AUTHORED') = (source_name IS NOT NULL))
);
COMMENT ON TABLE graphitron_directive_application IS 'Every directive application the generator emits, the author''s and the ones macro expansion minted, at the coordinate it is applied to: one row per application. For example the @key(fields: "id") federation synthesises for a node type sits here beside the @table its author wrote on it, at the same grain and answering the same questions.';
COMMENT ON COLUMN graphitron_directive_application.graph_name IS 'the owning graph''s partition, carried from whichever set supplied the row';
COMMENT ON COLUMN graphitron_directive_application.coordinate IS 'the coordinate the application sits on, as graphitron_element spells it; a reference into that relation, so an element the reading stopped emitting takes its applications with it';
COMMENT ON COLUMN graphitron_directive_application.directive_name IS 'the applied directive''s name, without the leading @';
COMMENT ON COLUMN graphitron_directive_application.ordinal IS 'the repeat within one coordinate and one directive name, numbered from zero: the author''s order on an authored application, and after every authored one on the others';
COMMENT ON COLUMN graphitron_directive_application.origin IS 'which set supplied the row: AUTHORED where a document states the application, CONFIGURED where the configuration applies it to what a document declares, MINTED where macro expansion adds it. What the renderer reads, the registry it patches already holding the first two';
COMMENT ON COLUMN graphitron_directive_application.source_name IS 'the file an authored application was written in; NULL on the others, which no document states';
COMMENT ON COLUMN graphitron_directive_application.source_line IS 'source line of the at sign, 1-based; NULL where the application is not authored';
COMMENT ON COLUMN graphitron_directive_application.source_column IS 'source column of the same; NULL where the application is not authored';
COMMENT ON COLUMN graphitron_directive_application.touched_at IS 'when the reading that last wrote this row ran. Swept per graph after the reading upserts, so an application the reading stopped deriving leaves and the rest keep their rows; an element that went takes its applications with it through the cascade';

CREATE TABLE graphitron_directive_application_arg (
  graph_name              VARCHAR NOT NULL,
  coordinate              VARCHAR NOT NULL,
  directive_name          VARCHAR NOT NULL,
  ordinal                 INT     NOT NULL,
  directive_argument_name VARCHAR NOT NULL,
  value_sdl               VARCHAR NOT NULL,
  touched_at              TIMESTAMP NOT NULL,
  PRIMARY KEY (graph_name, coordinate, directive_name, ordinal, directive_argument_name),
  FOREIGN KEY (graph_name, coordinate, directive_name, ordinal)
    REFERENCES graphitron_directive_application (graph_name, coordinate, directive_name, ordinal)
    ON DELETE CASCADE
);
COMMENT ON TABLE graphitron_directive_application_arg IS 'One argument of an application graphitron_directive_application holds: the application''s own key and the formal argument the value binds. For example the fields: "id" of a synthesised @key is one row, its value the literal an author would have typed.';
COMMENT ON COLUMN graphitron_directive_application_arg.graph_name IS 'the owning graph''s partition, carried from the application';
COMMENT ON COLUMN graphitron_directive_application_arg.coordinate IS 'the owning application''s coordinate, the second of the four columns naming it';
COMMENT ON COLUMN graphitron_directive_application_arg.directive_name IS 'the owning application''s directive name, the third';
COMMENT ON COLUMN graphitron_directive_application_arg.ordinal IS 'the owning application''s ordinal, the fourth; with the three above, a reference into graphitron_directive_application';
COMMENT ON COLUMN graphitron_directive_application_arg.directive_argument_name IS 'the definition''s formal argument this value binds, and the rest of the grain';
COMMENT ON COLUMN graphitron_directive_application_arg.value_sdl IS 'the value as SDL: as written on an authored application, and as the macro states it on a minted one, so a reader renders both the same way';
COMMENT ON COLUMN graphitron_directive_application_arg.touched_at IS 'when the reading that last wrote this row ran, swept per graph like the application''s own, so an argument removed from an application that still stands leaves';

-- ==== Macro synthesis provenance ==================================================
-- What macro expansion mints is stated by views and anchored by MacroExpansion, beside the authored
-- sets, into the tables above. Per element kind a candidate view states what the arms mint before
-- any disagreement between them is resolved, and a minted set states what survives:
-- graphitron_type_minted_candidate and graphitron_type_minted, and the field and argument pairs.
-- graphitron_minted_coinage says which application coined each minted type. A coordinate the
-- applications disagree about is withheld from every set and recorded in graphitron_minted_conflict
-- below, so no shape enters the population that no application asked for.
--
-- Precedence lives in the sets rather than in a column. A mint fills a name nobody took, so an
-- author's type or machinery field always survives; the one replacement is the carrier field an
-- @asConnection rewrites, which the field sets mark with their rewrite flag, and an argument yields
-- per name. Coinage is written for every carrier whether or not its mint wins, so a mint that stood
-- down to an author is still a row saying which application would have minted what.
--
-- Every macro mints here. @asFacet adds its types through graphitron_carrier_facet_mint, and the
-- directive applications a macro adds, the synthesised federation key and the federation directives
-- a minted type inherits from its carriers, are graphitron_directive_application's MINTED set.

CREATE TABLE graphitron_minted_conflict (
  graph_name   VARCHAR NOT NULL,
  coordinate   VARCHAR NOT NULL,
  element_kind VARCHAR NOT NULL,
  variants     INT     NOT NULL,
  PRIMARY KEY (graph_name, coordinate),
  FOREIGN KEY (graph_name) REFERENCES store_graph (graph_name),
  CHECK (element_kind IN ('NAMED_TYPE', 'FIELD', 'FIELD_ARGUMENT')),
  CHECK (variants >= 2)
);
COMMENT ON TABLE graphitron_minted_conflict IS 'A coordinate several macro applications would mint and disagree about: one row per contested coordinate in the graph. For example two carriers naming one connection through connectionName over different element types disagree about that connection''s own nodes field, which draws a row here and no row at all in graphitron_field.';
COMMENT ON COLUMN graphitron_minted_conflict.graph_name IS 'the owning graph''s partition, anchored by store_graph; the leading key dimension that keeps one workspace''s graphs apart';
COMMENT ON COLUMN graphitron_minted_conflict.coordinate IS 'the contested coordinate, spelled as graphitron_element spells one. No foreign key there, and the absence is the fact: a contested coordinate is exactly the one the anchor declined to hold, so a key into the anchor could never be satisfied by a row of this relation';
COMMENT ON COLUMN graphitron_minted_conflict.element_kind IS 'which kind of schema element the contested coordinate names, which is also which minted relation a reader joins to see what each application would have written. Three of the four the emitted family holds, an input field being minted by nothing today';
COMMENT ON COLUMN graphitron_minted_conflict.variants IS 'how many distinct payloads were minted here, always at least two, which the CHECK holds. A count of readings and not of applications: two carriers minting one coordinate the same way are no conflict and draw no row, and three carriers holding two opinions between them are two. Carried rather than left to a reader''s own count, on graphitron_spelled_table.candidates'' terms, so a message can say how many ways the schema disagrees with itself';

-- ---- supertypes over the directive families ----------------------------------------
-- Where one fact is authored at several kinds of site, the relations here are that fact, written
-- once by capture rather than reconstructed by every reader that asks a question the sites answer
-- uniformly. A union in a view is the shape this replaces, and it was never a cheap way to spell a
-- fact: it is re-derived per reader, it forces every reader to synthesise the same key, and the
-- query planner expands it once per path through whatever reads it.
--
-- Whether the per-site tables survive beside the supertype is decided by one rule, and it is the
-- data that decides, never the constraints. A site keeps a relation of its own when it carries data
-- the supertype cannot hold, and then the supertype holds the shared half beside it. A site whose
-- rows are the shared half and nothing more does not: it becomes rows of the supertype, told apart
-- by the discriminator column, and its table goes. The two are visible together in this section.
-- graphitron_spelled_reference_entry is the first kind, the sites that spell a reference each carrying
-- their own directive's payload.
--
-- The collapsing case gives up the foreign key each site had into the directive that owned its
-- rows, because a foreign key cannot span the parents a column chooses between. That is a real loss and
-- it is not a reason to keep the table: a constraint is not data, and the reference survives as an
-- invariant capture maintains and a test checks. Buying an enforced edge with a duplicated relation
-- costs a second write on every producer and a choice on every reader, which is what this section
-- exists to stop.

-- ==== The sets the emitted element anchor is the union of ==========================
-- graphitron_element is four populations, and they used to be four arms of one statement with
-- their precedence rules interleaved in Java. Each is named here instead, so a reader can ask what
-- a set contains without reading the others, and so the anchor's own writer is a union and nothing
-- else. The columns are the same four in each, the instant being the reading's rather than a set's.
--
-- Two rules are shared and are stated once per set rather than once: a coordinate several
-- applications would mint and disagree about belongs to none of them, and a coordinate the
-- transcription already anchors is not minted over. Stating them per set is what lets each set be
-- read alone and be true.

-- The carriers the expansion expands, which every arm of the mint reads and which the facet
-- resolution asks for by name. Its own relation rather than a join repeated per arm: the
-- admission test and the naming rule are one decision each, and stating them once is what stops
-- an arm disagreeing with its siblings about which fields are carriers.
CREATE TABLE graphitron_connection_carrier (
  graph_name          VARCHAR   NOT NULL,
  type_name           VARCHAR   NOT NULL,
  field_name          VARCHAR   NOT NULL,
  coordinate          VARCHAR   NOT NULL,
  connection_name     VARCHAR   NOT NULL,
  edge_name           VARCHAR   NOT NULL,
  element_type        VARCHAR   NOT NULL,
  item_sdl            VARCHAR   NOT NULL,
  item_non_null       BOOLEAN   NOT NULL,
  non_null            BOOLEAN   NOT NULL,
  ordinal             INT       NOT NULL,
  description         VARCHAR,
  default_first_value INT,
  argument_count      INT       NOT NULL,
  source_name         VARCHAR   NOT NULL,
  source_line         INT       NOT NULL,
  source_column       INT       NOT NULL,
  touched_at          TIMESTAMP NOT NULL,
  PRIMARY KEY (graph_name, type_name, field_name),
  -- The field the author wrote, which a carrier stops being when the document drops it.
  FOREIGN KEY (graph_name, type_name, field_name)
    REFERENCES graphql_field (graph_name, type_name, field_name) ON DELETE CASCADE
);
COMMENT ON TABLE graphitron_connection_carrier IS 'A field @asConnection expands, with the names and wrapping its expansion needs: one row per carrier. For example films: [Film!]! @asConnection on Query is one row naming QueryFilmsConnection, QueryFilmsConnectionEdge and the element Film!, where the same directive on a films: Film field is no row at all.';
COMMENT ON COLUMN graphitron_connection_carrier.graph_name IS 'the owning graph''s partition, carried from the application';
COMMENT ON COLUMN graphitron_connection_carrier.type_name IS 'the type declaring the carrier';
COMMENT ON COLUMN graphitron_connection_carrier.field_name IS 'the carrier field itself';
COMMENT ON COLUMN graphitron_connection_carrier.coordinate IS 'the carrier''s coordinate, spelled as graphitron_element spells one';
COMMENT ON COLUMN graphitron_connection_carrier.connection_name IS 'the connection type this carrier mints: what @asConnection(connectionName:) asked for, or the default built from the carrier''s own coordinate. Two carriers may land on one name, which is a disagreement the anchor resolves rather than a key this relation holds';
COMMENT ON COLUMN graphitron_connection_carrier.edge_name IS 'the edge type, which is the connection''s name and a suffix; derived here so no arm spells the rule a second time';
COMMENT ON COLUMN graphitron_connection_carrier.element_type IS 'the carrier''s element type, wrappers stripped: what the connection pages over';
COMMENT ON COLUMN graphitron_connection_carrier.item_sdl IS 'that element as the machinery fields write it, carrying the item nullability the author gave the list';
COMMENT ON COLUMN graphitron_connection_carrier.item_non_null IS 'whether the list''s items are non-null, which the machinery fields carry into the shapes they mint';
COMMENT ON COLUMN graphitron_connection_carrier.non_null IS 'whether the carrier itself is non-null, which the rewritten field keeps';
COMMENT ON COLUMN graphitron_connection_carrier.ordinal IS 'the carrier''s position on its type, which the rewrite does not change';
COMMENT ON COLUMN graphitron_connection_carrier.description IS 'the carrier''s docstring, carried across the rewrite unchanged';
COMMENT ON COLUMN graphitron_connection_carrier.default_first_value IS 'the page size @asConnection asked for, or NULL where it asked for none';
COMMENT ON COLUMN graphitron_connection_carrier.argument_count IS 'how many arguments the author wrote on the carrier, which is where the minted pagination arguments start numbering; they follow the authored ones rather than displacing them';
COMMENT ON COLUMN graphitron_connection_carrier.source_name IS 'the document the application was written in, carried so a reader can say which application minted a name';
COMMENT ON COLUMN graphitron_connection_carrier.source_line IS 'the application''s line, on source_name''s terms';
COMMENT ON COLUMN graphitron_connection_carrier.source_column IS 'the application''s column, on source_name''s terms';
COMMENT ON COLUMN graphitron_connection_carrier.touched_at IS 'when the reading that derived this row ran; swept per graph after the reading upserts';

CREATE VIEW graphitron_connection_carrier_rule
  (graph_name, type_name, field_name, coordinate, connection_name, edge_name,
   element_type, item_sdl, item_non_null, non_null, ordinal, description, default_first_value,
   argument_count,
   source_name, source_line, source_column) AS
SELECT b.graph_name, b.type_name, b.field_name, b.coordinate, b.connection_name,
       b.connection_name || 'Edge', b.element_type, b.item_sdl, b.item_non_null, b.non_null, b.ordinal,
       b.description, b.default_first_value, b.argument_count,
       b.source_name, b.source_line, b.source_column
  FROM (SELECT ca.graph_name, fe.type_name, fe.field_name, ca.coordinate,
               COALESCE(NULLIF(c.connection_name, ''),
                        fe.type_name || UPPER(SUBSTRING(fe.field_name FROM 1 FOR 1))
                                     || SUBSTRING(fe.field_name FROM 2) || 'Connection')
                 AS connection_name,
               f.named_type AS element_type,
               f.named_type || CASE WHEN f.item_non_null THEN '!' ELSE '' END AS item_sdl,
               COALESCE(f.item_non_null, FALSE) AS item_non_null,
               f.non_null, f.ordinal, f.description, c.default_first_value,
               CAST((SELECT COUNT(*) FROM graphql_argument g
                      WHERE g.graph_name = ca.graph_name AND g.type_name = fe.type_name
                        AND g.field_name = fe.field_name) AS INT) AS argument_count,
               ca.source_name, ca.source_line, ca.source_column
          -- The field's first @asConnection, what it wrote joined on where it wrote anything.
          FROM graphql_directive_application ca
          JOIN graphql_field_element fe
            ON fe.graph_name = ca.graph_name AND fe.coordinate = ca.coordinate
          LEFT JOIN graphitron_ast_connection_entry c
            ON c.graph_name = ca.graph_name AND c.source_name = ca.source_name
           AND c.source_line = ca.source_line AND c.source_column = ca.source_column
          JOIN graphql_field f
            ON f.graph_name = fe.graph_name
           AND f.type_name = fe.type_name
           AND f.field_name = fe.field_name
         -- A bare list of a named type and nothing deeper. list_depth answers this; the expansion
         -- used to read it off type_sdl by hand because the anchor did not carry the column.
         WHERE ca.directive_name = 'asConnection' AND ca.ordinal = 0
           AND f.is_list AND f.list_depth = 1) b;
COMMENT ON VIEW graphitron_connection_carrier_rule IS 'One row the connection carrier rule computes, in the shape graphitron_connection_carrier stores: the rule itself, evaluated on demand rather than read off disk. For example the macro-expansion stage inserts this view''s rows for one graph into graphitron_connection_carrier, which is the name every reader spells.';
-- COMMENT ON COLUMN graphitron_connection_carrier_rule.graph_name IS 'the graph_name of a row of this rule, which the stage writes into graphitron_connection_carrier.graph_name';
-- COMMENT ON COLUMN graphitron_connection_carrier_rule.type_name IS 'the type_name of a row of this rule, which the stage writes into graphitron_connection_carrier.type_name';
-- COMMENT ON COLUMN graphitron_connection_carrier_rule.field_name IS 'the field_name of a row of this rule, which the stage writes into graphitron_connection_carrier.field_name';
-- COMMENT ON COLUMN graphitron_connection_carrier_rule.coordinate IS 'the coordinate of a row of this rule, which the stage writes into graphitron_connection_carrier.coordinate';
-- COMMENT ON COLUMN graphitron_connection_carrier_rule.connection_name IS 'the connection_name of a row of this rule, which the stage writes into graphitron_connection_carrier.connection_name';
-- COMMENT ON COLUMN graphitron_connection_carrier_rule.edge_name IS 'the edge_name of a row of this rule, which the stage writes into graphitron_connection_carrier.edge_name';
-- COMMENT ON COLUMN graphitron_connection_carrier_rule.element_type IS 'the element_type of a row of this rule, which the stage writes into graphitron_connection_carrier.element_type';
-- COMMENT ON COLUMN graphitron_connection_carrier_rule.item_sdl IS 'the item_sdl of a row of this rule, which the stage writes into graphitron_connection_carrier.item_sdl';
-- COMMENT ON COLUMN graphitron_connection_carrier_rule.item_non_null IS 'the item_non_null of a row of this rule, which the stage writes into graphitron_connection_carrier.item_non_null';
-- COMMENT ON COLUMN graphitron_connection_carrier_rule.non_null IS 'the non_null of a row of this rule, which the stage writes into graphitron_connection_carrier.non_null';
-- COMMENT ON COLUMN graphitron_connection_carrier_rule.ordinal IS 'the ordinal of a row of this rule, which the stage writes into graphitron_connection_carrier.ordinal';
-- COMMENT ON COLUMN graphitron_connection_carrier_rule.description IS 'the description of a row of this rule, which the stage writes into graphitron_connection_carrier.description';
-- COMMENT ON COLUMN graphitron_connection_carrier_rule.default_first_value IS 'the default_first_value of a row of this rule, which the stage writes into graphitron_connection_carrier.default_first_value';
-- COMMENT ON COLUMN graphitron_connection_carrier_rule.argument_count IS 'the argument_count of a row of this rule, which the stage writes into graphitron_connection_carrier.argument_count';
-- COMMENT ON COLUMN graphitron_connection_carrier_rule.source_name IS 'the source_name of a row of this rule, which the stage writes into graphitron_connection_carrier.source_name';
-- COMMENT ON COLUMN graphitron_connection_carrier_rule.source_line IS 'the source_line of a row of this rule, which the stage writes into graphitron_connection_carrier.source_line';
-- COMMENT ON COLUMN graphitron_connection_carrier_rule.source_column IS 'the source_column of a row of this rule, which the stage writes into graphitron_connection_carrier.source_column';

-- An @issue absorbs every other field of its type into the voucher: a member is withheld from the
-- emitted population, so the authored sets below anti-join it, and the transcription keeps it as
-- written. Decided from structure alone, before the population is built and independently of every
-- refusal, so a member whose column fails to resolve, or an @issue refused for any reason, still
-- absorbs: A never publishes what the voucher seals. A field marked @issue or @accept is never a
-- member; where two @issue share a type (refused by the voucher stage) a member belongs to the first.
CREATE TABLE graphitron_voucher_member (
  graph_name    VARCHAR NOT NULL,
  type_name     VARCHAR NOT NULL,
  field_name    VARCHAR NOT NULL,
  coordinate    VARCHAR GENERATED ALWAYS AS (type_name || '.' || field_name) NOT NULL,
  issuing_field VARCHAR NOT NULL,
  PRIMARY KEY (graph_name, type_name, field_name),
  UNIQUE (graph_name, coordinate),
  FOREIGN KEY (graph_name, type_name, field_name)
    REFERENCES graphql_field_element (graph_name, type_name, field_name) ON DELETE CASCADE,
  FOREIGN KEY (graph_name, type_name, issuing_field)
    REFERENCES graphql_field_element (graph_name, type_name, field_name) ON DELETE CASCADE,
  CHECK (field_name <> issuing_field)
);
COMMENT ON TABLE graphitron_voucher_member IS 'One field declaration an @issue absorbs into its voucher, withheld from the emitted population. For example a VgsResultat whose voucher field carries @issue absorbs its id and eierId, two rows, while the voucher field itself is no member.';
COMMENT ON COLUMN graphitron_voucher_member.graph_name IS 'the owning graph''s partition';
COMMENT ON COLUMN graphitron_voucher_member.type_name IS 'the issuing type';
COMMENT ON COLUMN graphitron_voucher_member.field_name IS 'the absorbed field, as the transcription declares it';
COMMENT ON COLUMN graphitron_voucher_member.coordinate IS 'the absorbed field''s coordinate, the key spelled out and generated from it, so nothing writes it; the authored element set anti-joins on it';
COMMENT ON COLUMN graphitron_voucher_member.issuing_field IS 'the field carrying the @issue that absorbs it';

CREATE VIEW graphitron_voucher_member_rule
  (graph_name, type_name, field_name, issuing_field) AS
SELECT f.graph_name, f.type_name, f.field_name, MIN(i.field_name)
  FROM graphql_directive_application d
  JOIN graphql_field_element i ON i.graph_name = d.graph_name AND i.coordinate = d.coordinate
  JOIN graphql_field_element f
    ON f.graph_name = i.graph_name AND f.type_name = i.type_name AND f.field_name <> i.field_name
 WHERE d.directive_name = 'issue'
   AND NOT EXISTS (SELECT 1 FROM graphql_directive_application m
                    WHERE m.graph_name = f.graph_name AND m.coordinate = f.coordinate
                      AND m.directive_name IN ('issue', 'accept'))
 GROUP BY f.graph_name, f.type_name, f.field_name;
COMMENT ON VIEW graphitron_voucher_member_rule IS 'One voucher member the membership rule computes, in the shape graphitron_voucher_member stores: the rule itself, evaluated on demand rather than read off disk. For example the voucher-members stage writes this view''s rows for one graph into graphitron_voucher_member, which is the name every reader spells.';
-- COMMENT ON COLUMN graphitron_voucher_member_rule.graph_name IS 'the owning graph''s partition';
-- COMMENT ON COLUMN graphitron_voucher_member_rule.type_name IS 'the issuing type';
-- COMMENT ON COLUMN graphitron_voucher_member_rule.field_name IS 'the absorbed field';
-- COMMENT ON COLUMN graphitron_voucher_member_rule.issuing_field IS 'the field carrying the @issue, the first by name where two share a type';

CREATE VIEW graphitron_element_authored (graph_name, coordinate, element_kind) AS
SELECT e.graph_name, e.coordinate, e.element_kind
  FROM graphql_element e
 WHERE e.element_kind IN ('NAMED_TYPE', 'FIELD', 'INPUT_FIELD', 'ENUM_VALUE', 'FIELD_ARGUMENT')
   -- A field an @issue absorbs, and its arguments, are sealed into the voucher, not emitted.
   AND NOT EXISTS (SELECT 1 FROM graphitron_voucher_member m
                    WHERE m.graph_name = e.graph_name AND m.coordinate = e.coordinate)
   AND NOT EXISTS (SELECT 1 FROM graphql_argument_element a
                     JOIN graphitron_voucher_member m
                       ON m.graph_name = a.graph_name AND m.type_name = a.type_name
                      AND m.field_name = a.field_name
                    WHERE a.graph_name = e.graph_name AND a.coordinate = e.coordinate);
COMMENT ON VIEW graphitron_element_authored IS 'One of the four sets graphitron_element is the union of: an element an author declared, at the coordinate the transcription spells for it, of a kind this family anchors. For example the Film in type Film { title: String } is one row, and the Film.title written inside it is another.';
-- COMMENT ON COLUMN graphitron_element_authored.graph_name IS 'the owning graph''s partition, carried from the transcription';
-- COMMENT ON COLUMN graphitron_element_authored.coordinate IS 'the coordinate itself, as graphql_element spells it';
-- COMMENT ON COLUMN graphitron_element_authored.element_kind IS 'the kind, in the specification''s own vocabulary and narrowed to the five this family anchors';

-- ==== The sets the three emitted part relations are the unions of =================================
-- Each of graphitron_type, graphitron_field and graphitron_argument is an authored set and a minted
-- set, named here for the reasons the element sets above are. They are stated rather than derived
-- from the element sets, though the element grain answers a question that looks the same, because at
-- one coordinate the two disagree: a rewritten carrier is an authored element and a minted field.
-- Deriving either from the other would be right at five of the six and silently wrong at the sixth.

CREATE VIEW graphitron_type_authored (graph_name, type_name, coordinate, kind, description,
                                      note) AS
SELECT t.graph_name, t.type_name, t.type_name, t.kind, t.description, s.description_note
  FROM graphql_type t
  -- A type takes the note of the file holding its base definition, the one its description is
  -- read from; a scalar takes none.
  LEFT JOIN graphql_type_declaration d
    ON d.graph_name = t.graph_name AND d.type_name = t.type_name
   AND d.merge_ordinal = 0 AND NOT d.is_extension AND d.kind <> 'SCALAR'
  LEFT JOIN store_graph_source_input s
    ON s.graph_name = d.graph_name AND s.source_name = d.source_name;
COMMENT ON VIEW graphitron_type_authored IS 'One of the two sets graphitron_type is the union of: a type an author declared, carried across whole. For example type Film { title: String } is the row Film here, with the kind and docstring the author wrote.';
-- COMMENT ON COLUMN graphitron_type_authored.graph_name IS 'the owning graph''s partition, carried from the transcription';
-- COMMENT ON COLUMN graphitron_type_authored.type_name IS 'the type''s name, as the author spelled it';
-- COMMENT ON COLUMN graphitron_type_authored.coordinate IS 'the same name again, a named type''s coordinate being its name; spelled here so the join up to graphitron_element is a column rather than a concatenation a reader has to trust';
-- COMMENT ON COLUMN graphitron_type_authored.kind IS 'the type''s kind in graphql_type''s vocabulary, carried rather than restated';
-- COMMENT ON COLUMN graphitron_type_authored.description IS 'the docstring the author wrote, or nothing';
-- COMMENT ON COLUMN graphitron_type_authored.note IS 'the note its file''s entry configures, which the anchor appends to the description, minting the one the generator emits; NULL where none is configured';

CREATE VIEW graphitron_facet_binding
  (graph_name, type_name, field_name, ordinal, column_name, value_type_name, value_nullable,
   source_name, source_line, source_column) AS
SELECT f.graph_name, f.type_name, f.field_name, f.ordinal,
       fb.name_ref,
       f.named_type,
       CASE WHEN f.is_list THEN NOT f.item_non_null ELSE TRUE END,
       fc.source_name, fc.source_line, fc.source_column
  -- The field's first @asFacet, and the name its first @field binds.
  FROM graphql_directive_application fc
  JOIN graphql_field_element fe
    ON fe.graph_name = fc.graph_name AND fe.coordinate = fc.coordinate
  JOIN graphql_field f
    ON f.graph_name = fe.graph_name AND f.type_name = fe.type_name
   AND f.field_name = fe.field_name
  JOIN graphql_type owner
    ON owner.graph_name = f.graph_name AND owner.type_name = f.type_name
   AND owner.kind = 'INPUT_OBJECT'
  JOIN graphql_directive_application fa
    ON fa.graph_name = fc.graph_name AND fa.coordinate = fc.coordinate
   AND fa.directive_name = 'field' AND fa.ordinal = 0
  JOIN graphitron_ast_binding_entry fb
    ON fb.graph_name = fa.graph_name AND fb.source_name = fa.source_name
   AND fb.source_line = fa.source_line AND fb.source_column = fa.source_column
 WHERE fc.directive_name = 'asFacet' AND fc.ordinal = 0
   AND NOT f.non_null
   AND f.named_type <> 'ID'
   AND NOT EXISTS (SELECT 1 FROM graphql_type leaf
                    WHERE leaf.graph_name = f.graph_name AND leaf.type_name = f.named_type
                      AND leaf.kind = 'INPUT_OBJECT')
   -- The two applications that make a facet field something else instead, asked of the
   -- applications rather than of their decodes. What excludes the field is that one of them was
   -- written on it, which is a fact about the document; the decode of what it says is a later
   -- reading, and asking it here would make this view answer differently depending on how far the
   -- pass had got.
   --
   -- Siblings of the @asFacet application itself, not of the coordinate. Where several documents
   -- declare one input field the corpus honours one of them, and the declarations it did not honour
   -- contribute no directives to the merged field; anchoring the search on the position the facet
   -- marker won at is what keeps a losing declaration's @reference from disqualifying a facet the
   -- author never wrote it on.
   --
   -- @reference is not among them: it does not replace the column binding, it says which table the
   -- @field(name:) column is on, so a reference-bound facet is a row here like any other.
   AND NOT EXISTS (SELECT 1
                     FROM graphql_ast_entry mark
                     JOIN graphql_ast_entry de
                       ON de.graph_name = mark.graph_name
                      AND de.source_name = mark.source_name
                      AND de.parent_line = mark.parent_line
                      AND de.parent_column = mark.parent_column
                     JOIN graphql_ast_directive_application_entry d
                       ON d.graph_name = de.graph_name AND d.source_name = de.source_name
                      AND d.source_line = de.source_line AND d.source_column = de.source_column
                    WHERE mark.graph_name = fc.graph_name
                      AND mark.source_name = fc.source_name
                      AND mark.source_line = fc.source_line
                      AND mark.source_column = fc.source_column
                      AND d.name IN ('condition', 'nodeId'));
COMMENT ON VIEW graphitron_facet_binding IS 'What one @asFacet application binds, at the applications that are well formed: the column its counts group by, the named type those counts are keyed on, and whether such a key may be null. For example @asFacet on FilmFilter.rating is one row naming the rating column and the type its values carry.';
-- COMMENT ON COLUMN graphitron_facet_binding.graph_name IS 'the owning graph''s partition, carried from the @asFacet application';
-- COMMENT ON COLUMN graphitron_facet_binding.type_name IS 'the input object type the facet field is declared on';
-- COMMENT ON COLUMN graphitron_facet_binding.field_name IS 'the facet field''s name within that input type; with the two columns above, the grain';
-- COMMENT ON COLUMN graphitron_facet_binding.ordinal IS 'the field''s declaration order within its input type, carried from graphql_field; the inner half of the order one carrier''s facets surface in';
-- COMMENT ON COLUMN graphitron_facet_binding.column_name IS 'the @field(name:) binding as written: the column the counts group by. Which table it resolves on, the consuming carrier''s table or the table a @reference path on the field ends at, is resolved against the catalog at the use site and is not here';
-- COMMENT ON COLUMN graphitron_facet_binding.value_type_name IS 'the named type a facet key carries, the filter field''s leaf; a scalar or an enum, an input object being a decline above';
-- COMMENT ON COLUMN graphitron_facet_binding.value_nullable IS 'whether a facet key may be null: the list element''s nullability where the filter field is a list, TRUE otherwise. With value_type_name it decides both the synthesized FacetValue type the counts surface through and whether the aggregate scrubs a null key';
-- COMMENT ON COLUMN graphitron_facet_binding.source_name IS 'the @asFacet application''s own file; the position a diagnostic would carry';
-- COMMENT ON COLUMN graphitron_facet_binding.source_line IS 'source line of the application, 1-based';
-- COMMENT ON COLUMN graphitron_facet_binding.source_column IS 'source column of the application, 1-based';

CREATE VIEW graphitron_connection_facet
  (graph_name, type_name, field_name, position, filter_argument_name,
   facet_type_name, facet_field_name, column_name, value_type_name, value_nullable,
   source_name, source_line, source_column) AS
SELECT graph_name, type_name, field_name,
       ROW_NUMBER() OVER (PARTITION BY graph_name, type_name, field_name
                          ORDER BY argument_ordinal, facet_ordinal),
       filter_argument_name, facet_type_name, facet_field_name,
       column_name, value_type_name, value_nullable,
       source_name, source_line, source_column
  FROM (SELECT a.graph_name, a.type_name, a.field_name,
               a.ordinal AS argument_ordinal, fb.ordinal AS facet_ordinal,
               a.argument_name AS filter_argument_name,
               fb.type_name AS facet_type_name, fb.field_name AS facet_field_name,
               fb.column_name, fb.value_type_name, fb.value_nullable,
               fb.source_name, fb.source_line, fb.source_column,
               ROW_NUMBER() OVER (
                 PARTITION BY a.graph_name, a.type_name, a.field_name, fb.field_name
                 ORDER BY a.ordinal, fb.ordinal) AS rn
          FROM graphitron_facet_binding fb
          JOIN graphql_argument a
            ON a.graph_name = fb.graph_name AND a.named_type = fb.type_name
          -- The carriers, asked for by name. This used to infer them from the expansion's own
          -- output, a minted field whose coining coordinate was its own, which made a reading of
          -- the carriers depend on the mint having already run.
          JOIN graphitron_connection_carrier c
            ON c.graph_name = a.graph_name AND c.type_name = a.type_name
           AND c.field_name = a.field_name) carrier_facet
 WHERE rn = 1;
COMMENT ON VIEW graphitron_connection_facet IS 'Which facets one connection carrier surfaces, and in which order: one row per @asFacet application reachable from the carrier''s own filter arguments. For example films(filter: FilmFilter) @asConnection surfaces every facet FilmFilter declares, in emission order.';
-- COMMENT ON COLUMN graphitron_connection_facet.graph_name IS 'the owning graph''s partition, carried from the carrier''s arguments';
-- COMMENT ON COLUMN graphitron_connection_facet.type_name IS 'the type owning the carrier field';
-- COMMENT ON COLUMN graphitron_connection_facet.field_name IS 'the carrier field''s name within that type; with the column above, the connection carrier''s coordinate';
-- COMMENT ON COLUMN graphitron_connection_facet.position IS 'the facet''s place in this carrier''s facet list, 1-based and dense: argument declaration order, then facet field declaration order. The emission order, so a consumer reads it rather than re-deriving it from the two ordinals it was computed from';
-- COMMENT ON COLUMN graphitron_connection_facet.filter_argument_name IS 'the carrier argument the facet''s binding rides in. Half of a facet''s suppression identity at emission: a same-named field on a sibling filter argument is a different binding, and the pair with facet_field_name is what tells them apart';
-- COMMENT ON COLUMN graphitron_connection_facet.facet_type_name IS 'witness: the input object type the application was written on, which is the argument''s named type. With the column beside it this is graphitron_facet_binding''s key, so the application''s own position is one join away';
-- COMMENT ON COLUMN graphitron_connection_facet.facet_field_name IS 'the facet field''s name: the label the counts surface under, and the other half of the suppression identity';
-- COMMENT ON COLUMN graphitron_connection_facet.column_name IS 'the column the counts group by, carried from graphitron_facet_binding';
-- COMMENT ON COLUMN graphitron_connection_facet.value_type_name IS 'the named type a facet key carries, carried from graphitron_facet_binding';
-- COMMENT ON COLUMN graphitron_connection_facet.value_nullable IS 'whether a facet key may be null, carried from graphitron_facet_binding';
-- COMMENT ON COLUMN graphitron_connection_facet.source_name IS 'the @asFacet application''s own file, carried from graphitron_facet_binding: a diagnostic about a facet points at the application and not at the carrier that consumes it';
-- COMMENT ON COLUMN graphitron_connection_facet.source_line IS 'source line of the application, 1-based';
-- COMMENT ON COLUMN graphitron_connection_facet.source_column IS 'source column of the application, 1-based';

-- What one carrier's facets mint, names included. A facet is an @asFacet application the carrier
-- reaches through its filter arguments; the container and the value types follow from the carrier's
-- connection name and the facet's own scalar.
CREATE VIEW graphitron_carrier_facet_mint
  (graph_name, type_name, field_name, connection_name, facets_type_name, position,
   facet_field_name, value_type_name, value_scalar, value_nullable) AS
SELECT f.graph_name, f.type_name, f.field_name, c.connection_name,
       c.connection_name || 'Facets', CAST(f.position AS INT), f.facet_field_name,
       f.value_type_name || CASE WHEN f.value_nullable THEN 'FacetValueOrNull' ELSE 'FacetValue' END,
       f.value_type_name, f.value_nullable
  FROM graphitron_connection_facet f
  JOIN graphitron_connection_carrier c
    ON c.graph_name = f.graph_name AND c.type_name = f.type_name AND c.field_name = f.field_name;
COMMENT ON VIEW graphitron_carrier_facet_mint IS 'What one connection carrier''s facets add to the schema: one row per facet the carrier surfaces, carrying the container and value-type names the mint derives. For example films(filter: FilmFilter) @asConnection with a title facet is one row naming QueryFilmsConnectionFacets and StringFacetValue.';
-- COMMENT ON COLUMN graphitron_carrier_facet_mint.graph_name IS 'the owning graph''s partition, carried from the facet';
-- COMMENT ON COLUMN graphitron_carrier_facet_mint.type_name IS 'the type declaring the carrier';
-- COMMENT ON COLUMN graphitron_carrier_facet_mint.field_name IS 'the carrier field';
-- COMMENT ON COLUMN graphitron_carrier_facet_mint.connection_name IS 'the connection this carrier mints, which the container is named from';
-- COMMENT ON COLUMN graphitron_carrier_facet_mint.facets_type_name IS 'the per-connection container type, which is the connection''s name and a suffix';
-- COMMENT ON COLUMN graphitron_carrier_facet_mint.position IS 'the facet''s position on the container, dense per carrier and in emission order';
-- COMMENT ON COLUMN graphitron_carrier_facet_mint.facet_field_name IS 'the facet''s field on the container, which is the @asFacet site''s own name';
-- COMMENT ON COLUMN graphitron_carrier_facet_mint.value_type_name IS 'the bucket type for this facet''s values, whose name carries the scalar and whether a null value is a bucket';
-- COMMENT ON COLUMN graphitron_carrier_facet_mint.value_scalar IS 'the scalar the facet''s values are, which the bucket''s own value field returns';
-- COMMENT ON COLUMN graphitron_carrier_facet_mint.value_nullable IS 'whether a null is one of the buckets, which decides both the bucket type''s name and its value field''s nullability';

-- The mint's own provenance. Every arm of the type mint knows the application it derived a name
-- from and then drops it, the minted sets being keyed on the coordinate of the thing minted rather
-- than of the thing that minted it. A reader wanting to carry something from the application to
-- what it coined needs the pairing back, and deriving it here keeps it one statement rather than
-- an enumeration of arms restated wherever it is wanted.
CREATE VIEW graphitron_minted_coinage_rule (graph_name, type_name, coordinate) AS
SELECT DISTINCT graph_name, type_name, coordinate
  FROM (SELECT graph_name, connection_name AS type_name, coordinate
          FROM graphitron_connection_carrier
         UNION ALL
        SELECT graph_name, edge_name, coordinate
          FROM graphitron_connection_carrier
         UNION ALL
        SELECT graph_name, 'PageInfo', coordinate
          FROM graphitron_connection_carrier
         UNION ALL
        SELECT f.graph_name, f.facets_type_name, c.coordinate
          FROM graphitron_carrier_facet_mint f
          JOIN graphitron_connection_carrier c
            ON c.graph_name = f.graph_name AND c.type_name = f.type_name
           AND c.field_name = f.field_name
         UNION ALL
        SELECT f.graph_name, f.value_type_name, c.coordinate
          FROM graphitron_carrier_facet_mint f
          JOIN graphitron_connection_carrier c
            ON c.graph_name = f.graph_name AND c.type_name = f.type_name
           AND c.field_name = f.field_name) m
;
COMMENT ON VIEW graphitron_minted_coinage_rule IS 'One row the coinage rule computes, in the shape graphitron_minted_coinage stores: the rule itself, evaluated on demand rather than read off disk. For example a capture inserts this view''s rows for one graph into graphitron_minted_coinage, which is the name every reader spells; naming this relation instead asks for on-demand evaluation and gets it.';
-- COMMENT ON COLUMN graphitron_minted_coinage_rule.graph_name IS 'the owning graph''''s partition, carried from the carrier';
-- COMMENT ON COLUMN graphitron_minted_coinage_rule.type_name IS 'the minted type''''s name; not unique here, one name being coinable by several applications';
-- COMMENT ON COLUMN graphitron_minted_coinage_rule.coordinate IS 'the application that coined it, on graphitron_element_authored.coordinate''''s terms; with the name above, the grain';
CREATE TABLE graphitron_minted_coinage (
  graph_name     VARCHAR NOT NULL,
  type_name      VARCHAR NOT NULL,
  coordinate     VARCHAR NOT NULL,
  touched_at     TIMESTAMP NOT NULL,
  PRIMARY KEY (graph_name, type_name, coordinate),
  FOREIGN KEY (graph_name) REFERENCES store_graph (graph_name)
);
COMMENT ON TABLE graphitron_minted_coinage IS 'Which coordinate coined each type the expansion mints: one row per minted type name and the application it was derived from. For example films: [Film!]! @asConnection with a title facet coins QueryFilmsConnection, QueryFilmsConnectionEdge, PageInfo, QueryFilmsConnectionFacets and StringFacetValue, all at Query.films.';
COMMENT ON COLUMN graphitron_minted_coinage.graph_name IS 'the owning graph''''s partition, carried from the carrier';
COMMENT ON COLUMN graphitron_minted_coinage.type_name IS 'the minted type''''s name; not unique here, one name being coinable by several applications';
COMMENT ON COLUMN graphitron_minted_coinage.coordinate IS 'the application that coined it, on graphitron_element_authored.coordinate''''s terms; with the name above, the grain';
COMMENT ON COLUMN graphitron_minted_coinage.touched_at IS 'when the reading that last found this coinage ran: the mark the sweep reads, so a coinage still made survives a reading and one no longer made goes';

CREATE VIEW graphitron_type_minted_candidate (graph_name, type_name, coordinate, kind, description) AS
SELECT DISTINCT graph_name, type_name, type_name, 'OBJECT', description
  FROM (SELECT graph_name, connection_name AS type_name,
               'A connection to a list of items.' AS description
          FROM graphitron_connection_carrier
         UNION ALL
        SELECT graph_name, edge_name, 'An edge in a connection.'
          FROM graphitron_connection_carrier
         UNION ALL
        SELECT graph_name, 'PageInfo', 'Information about pagination in a connection.'
          FROM graphitron_connection_carrier
         UNION ALL
        SELECT graph_name, facets_type_name, 'Facet value counts for a connection.'
          FROM graphitron_carrier_facet_mint
         UNION ALL
        SELECT graph_name, value_type_name, 'One facet bucket: a filterable value and its count.'
          FROM graphitron_carrier_facet_mint) m
;
CREATE VIEW graphitron_type_minted (graph_name, type_name, coordinate, kind, description) AS
SELECT * FROM graphitron_type_minted_candidate m
 WHERE NOT EXISTS (SELECT 1 FROM graphitron_minted_conflict c
                    WHERE c.graph_name = m.graph_name AND c.coordinate = m.type_name)
   AND NOT EXISTS (SELECT 1 FROM graphql_type_element t
                    WHERE t.graph_name = m.graph_name AND t.type_name = m.type_name);
COMMENT ON VIEW graphitron_type_minted_candidate IS 'What the arms of the type mint state before any disagreement between them is resolved. For example two carriers landing on one connection name are two rows here and none in graphitron_type_minted.';
-- COMMENT ON COLUMN graphitron_type_minted_candidate.graph_name IS 'the same fact as graphitron_type_minted.graph_name, before the conflict and stand-down filters have withheld anything';
-- COMMENT ON COLUMN graphitron_type_minted_candidate.type_name IS 'the same fact as graphitron_type_minted.type_name, before the conflict and stand-down filters have withheld anything';
-- COMMENT ON COLUMN graphitron_type_minted_candidate.coordinate IS 'the same fact as graphitron_type_minted.coordinate, before the conflict and stand-down filters have withheld anything';
-- COMMENT ON COLUMN graphitron_type_minted_candidate.kind IS 'the same fact as graphitron_type_minted.kind, before the conflict and stand-down filters have withheld anything';
-- COMMENT ON COLUMN graphitron_type_minted_candidate.description IS 'the same fact as graphitron_type_minted.description, before the conflict and stand-down filters have withheld anything';
COMMENT ON VIEW graphitron_type_minted IS 'One of the two sets graphitron_type is the union of: a type macro expansion adds, filling a name no author took. For example QueryFilmsConnection where the author wrote only films: [Film!]! @asConnection.';
-- COMMENT ON COLUMN graphitron_type_minted.graph_name IS 'the owning graph''s partition, carried from the carrier';
-- COMMENT ON COLUMN graphitron_type_minted.type_name IS 'the minted type''s name: a carrier''s connection, its edge, or the page info every carrier states';
-- COMMENT ON COLUMN graphitron_type_minted.coordinate IS 'the same name again, on graphitron_type_authored.coordinate''s terms';
-- COMMENT ON COLUMN graphitron_type_minted.kind IS 'always OBJECT, the three arms minting nothing else';
-- COMMENT ON COLUMN graphitron_type_minted.description IS 'the docstring the macro writes, which is a property of the arm rather than of the carrier; identical across the carriers that state one shared type, which is what lets the distinct collapse them';

CREATE VIEW graphitron_field_authored (graph_name, type_name, field_name, coordinate, ordinal,
                                       type_sdl, named_type, non_null, list_depth, item_non_null,
                                       default_value_sdl, description, note) AS
SELECT f.graph_name, f.type_name, f.field_name, f.type_name || '.' || f.field_name, f.ordinal,
       f.type_sdl, f.named_type, f.non_null, f.list_depth, f.item_non_null,
       f.default_value_sdl, f.description, s.description_note
  FROM graphql_field f
  LEFT JOIN store_graph_source_input s ON s.graph_name = f.graph_name AND s.source_name = f.source_name
 WHERE NOT EXISTS (SELECT 1 FROM graphitron_connection_carrier c
                    WHERE c.graph_name = f.graph_name AND c.type_name = f.type_name
                      AND c.field_name = f.field_name)
   -- A field an @issue absorbs is sealed into the voucher, not emitted.
   AND NOT EXISTS (SELECT 1 FROM graphitron_voucher_member m
                    WHERE m.graph_name = f.graph_name AND m.type_name = f.type_name
                      AND m.field_name = f.field_name);
COMMENT ON VIEW graphitron_field_authored IS 'One of the two sets graphitron_field is the union of: a field an author declared that no expansion rewrote, carried across whole. For example the title in type Film { title: String }, where films: [Film!]! @asConnection is not here, the expansion having restated it.';
-- COMMENT ON COLUMN graphitron_field_authored.graph_name IS 'the owning graph''s partition, carried from the transcription';
-- COMMENT ON COLUMN graphitron_field_authored.type_name IS 'the type the field is declared on';
-- COMMENT ON COLUMN graphitron_field_authored.field_name IS 'the field''s own name';
-- COMMENT ON COLUMN graphitron_field_authored.coordinate IS 'Type.field, the specification''s spelling, which is the join up to graphitron_element';
-- COMMENT ON COLUMN graphitron_field_authored.note IS 'the note its file''s entry configures, which the anchor appends to the description, minting the one the generator emits; NULL where none is configured';
-- COMMENT ON COLUMN graphitron_field_authored.ordinal IS 'where the author wrote it among the type''s fields, carried so the emitted schema keeps their order';
-- COMMENT ON COLUMN graphitron_field_authored.type_sdl IS 'the type expression as written, wrappers included';
-- COMMENT ON COLUMN graphitron_field_authored.named_type IS 'the name at the bottom of that expression';
-- COMMENT ON COLUMN graphitron_field_authored.non_null IS 'whether the outermost wrapper is non-null';
-- COMMENT ON COLUMN graphitron_field_authored.list_depth IS 'how many list wrappers the expression has';
-- COMMENT ON COLUMN graphitron_field_authored.item_non_null IS 'whether a list''s items are non-null, and nothing where it is not a list';
-- COMMENT ON COLUMN graphitron_field_authored.default_value_sdl IS 'the default as written, which an output field never has and an input field may; the one column the minted set cannot supply';
-- COMMENT ON COLUMN graphitron_field_authored.description IS 'the docstring the author wrote, or nothing';

CREATE VIEW graphitron_field_minted_candidate (graph_name, type_name, field_name, coordinate, ordinal,
                                     type_sdl, named_type, non_null, list_depth, item_non_null,
                                     default_value_sdl, description, rewrite) AS
SELECT DISTINCT m.graph_name, m.type_name, m.field_name, m.type_name || '.' || m.field_name,
       m.ordinal, m.type_sdl, m.named_type, m.non_null, m.list_depth, m.item_non_null,
       CAST(NULL AS VARCHAR), m.description, m.rewrite
  FROM (
        -- The connection's own machinery.
        SELECT graph_name, connection_name AS type_name, 'edges' AS field_name, 0 AS ordinal,
               '[' || edge_name || '!]!' AS type_sdl, edge_name AS named_type,
               TRUE AS non_null, 1 AS list_depth, TRUE AS item_non_null,
               'A list of edges.' AS description, FALSE AS rewrite
          FROM graphitron_connection_carrier
         UNION ALL
        SELECT graph_name, connection_name, 'nodes', 1,
               '[' || item_sdl || ']!', element_type, TRUE, 1, item_non_null,
               'A list of nodes.', FALSE
          FROM graphitron_connection_carrier
         UNION ALL
        SELECT graph_name, connection_name, 'pageInfo', 2,
               'PageInfo!', 'PageInfo', TRUE, 0, NULL,
               'Information to aid in pagination.', FALSE
          FROM graphitron_connection_carrier
         UNION ALL
        -- Nullable like the connection's other aggregate: a skipped count degrades to null rather
        -- than bubbling a failure through the connection.
        SELECT graph_name, connection_name, 'totalCount', 3,
               'Int', 'Int', FALSE, 0, NULL,
               'Identifies the total count of items in the connection.', FALSE
          FROM graphitron_connection_carrier
         UNION ALL
        -- The edge's.
        SELECT graph_name, edge_name, 'cursor', 0,
               'String!', 'String', TRUE, 0, NULL,
               'A cursor for use in pagination.', FALSE
          FROM graphitron_connection_carrier
         UNION ALL
        SELECT graph_name, edge_name, 'node', 1,
               item_sdl, element_type, item_non_null, 0, NULL,
               'The item at the end of the edge.', FALSE
          FROM graphitron_connection_carrier
         UNION ALL
        -- The page info every carrier states whole, which is why the distinct above collapses them.
        SELECT graph_name, 'PageInfo', 'hasNextPage', 0,
               'Boolean!', 'Boolean', TRUE, 0, NULL,
               'When paginating forwards, are there more items?', FALSE
          FROM graphitron_connection_carrier
         UNION ALL
        SELECT graph_name, 'PageInfo', 'hasPreviousPage', 1,
               'Boolean!', 'Boolean', TRUE, 0, NULL,
               'When paginating backwards, are there more items?', FALSE
          FROM graphitron_connection_carrier
         UNION ALL
        SELECT graph_name, 'PageInfo', 'startCursor', 2,
               'String', 'String', FALSE, 0, NULL,
               'When paginating backwards, the cursor to continue.', FALSE
          FROM graphitron_connection_carrier
         UNION ALL
        SELECT graph_name, 'PageInfo', 'endCursor', 3,
               'String', 'String', FALSE, 0, NULL,
               'When paginating forwards, the cursor to continue.', FALSE
          FROM graphitron_connection_carrier
         UNION ALL
        -- The facets the carrier surfaces: the connection's own field reaching the container,
        -- the container's field per facet, and each bucket's value and count.
        SELECT graph_name, connection_name, 'facets', 4,
               facets_type_name, facets_type_name, FALSE, 0, NULL,
               'Per-facet value counts for the items in the connection.', FALSE
          FROM graphitron_carrier_facet_mint
         UNION ALL
        SELECT graph_name, facets_type_name, facet_field_name, position,
               '[' || value_type_name || '!]', value_type_name, FALSE, 1, TRUE,
               'Value counts for this facet, under the connection''s filter minus this facet''s own predicate.', FALSE
          FROM graphitron_carrier_facet_mint
         UNION ALL
        SELECT graph_name, value_type_name, 'value', 0,
               value_scalar || CASE WHEN value_nullable THEN '' ELSE '!' END, value_scalar,
               NOT value_nullable, 0, NULL,
               'The facet value; feed it back into the filter to select this bucket.', FALSE
          FROM graphitron_carrier_facet_mint
         UNION ALL
        SELECT graph_name, value_type_name, 'count', 1,
               'Int!', 'Int', TRUE, 0, NULL,
               'The number of items in this bucket.', FALSE
          FROM graphitron_carrier_facet_mint
         UNION ALL
        -- The rewrite: the carrier keeps its own coordinate, ordinal and docstring, and returns
        -- the connection under the nullability its author wrote.
        SELECT graph_name, type_name, field_name, ordinal,
               connection_name || CASE WHEN non_null THEN '!' ELSE '' END,
               connection_name, non_null, 0, NULL,
               description, TRUE
          FROM graphitron_connection_carrier) m
;
CREATE VIEW graphitron_field_minted (graph_name, type_name, field_name, coordinate, ordinal,
                                     type_sdl, named_type, non_null, list_depth, item_non_null,
                                     default_value_sdl, description, rewrite, note) AS
SELECT m.graph_name, m.type_name, m.field_name, m.coordinate, m.ordinal, m.type_sdl,
       m.named_type, m.non_null, m.list_depth, m.item_non_null, m.default_value_sdl,
       m.description, m.rewrite, s.description_note
  FROM graphitron_field_minted_candidate m
  -- A rewritten carrier keeps its author's docstring, and takes its file's note as the field it
  -- rewrites does.
  LEFT JOIN graphql_field f
    ON m.rewrite AND f.graph_name = m.graph_name AND f.type_name = m.type_name
   AND f.field_name = m.field_name
  LEFT JOIN store_graph_source_input s ON s.graph_name = f.graph_name AND s.source_name = f.source_name
 WHERE NOT EXISTS (SELECT 1 FROM graphitron_minted_conflict c
                    WHERE c.graph_name = m.graph_name AND c.coordinate = m.coordinate)
   AND (m.rewrite
        OR NOT EXISTS (SELECT 1 FROM graphql_field_element f
                        WHERE f.graph_name = m.graph_name AND f.type_name = m.type_name
                          AND f.field_name = m.field_name))
   -- A machinery field whose own type stood down to an author's declaration goes with it.
   AND (m.rewrite
        OR NOT EXISTS (SELECT 1 FROM graphql_type_element a
                        WHERE a.graph_name = m.graph_name AND a.type_name = m.type_name));
COMMENT ON VIEW graphitron_field_minted_candidate IS 'What the arms of the field mint state before any disagreement between them is resolved. For example two carriers disagreeing about one connection''s nodes field are two rows here and none in graphitron_field_minted.';
-- COMMENT ON COLUMN graphitron_field_minted_candidate.graph_name IS 'the same fact as graphitron_field_minted.graph_name, before the conflict and stand-down filters have withheld anything';
-- COMMENT ON COLUMN graphitron_field_minted_candidate.type_name IS 'the same fact as graphitron_field_minted.type_name, before the conflict and stand-down filters have withheld anything';
-- COMMENT ON COLUMN graphitron_field_minted_candidate.field_name IS 'the same fact as graphitron_field_minted.field_name, before the conflict and stand-down filters have withheld anything';
-- COMMENT ON COLUMN graphitron_field_minted_candidate.coordinate IS 'the same fact as graphitron_field_minted.coordinate, before the conflict and stand-down filters have withheld anything';
-- COMMENT ON COLUMN graphitron_field_minted_candidate.ordinal IS 'the same fact as graphitron_field_minted.ordinal, before the conflict and stand-down filters have withheld anything';
-- COMMENT ON COLUMN graphitron_field_minted_candidate.type_sdl IS 'the same fact as graphitron_field_minted.type_sdl, before the conflict and stand-down filters have withheld anything';
-- COMMENT ON COLUMN graphitron_field_minted_candidate.named_type IS 'the same fact as graphitron_field_minted.named_type, before the conflict and stand-down filters have withheld anything';
-- COMMENT ON COLUMN graphitron_field_minted_candidate.non_null IS 'the same fact as graphitron_field_minted.non_null, before the conflict and stand-down filters have withheld anything';
-- COMMENT ON COLUMN graphitron_field_minted_candidate.list_depth IS 'the same fact as graphitron_field_minted.list_depth, before the conflict and stand-down filters have withheld anything';
-- COMMENT ON COLUMN graphitron_field_minted_candidate.item_non_null IS 'the same fact as graphitron_field_minted.item_non_null, before the conflict and stand-down filters have withheld anything';
-- COMMENT ON COLUMN graphitron_field_minted_candidate.default_value_sdl IS 'the same fact as graphitron_field_minted.default_value_sdl, before the conflict and stand-down filters have withheld anything';
-- COMMENT ON COLUMN graphitron_field_minted_candidate.description IS 'the same fact as graphitron_field_minted.description, before the conflict and stand-down filters have withheld anything';
-- COMMENT ON COLUMN graphitron_field_minted_candidate.rewrite IS 'the same fact as graphitron_field_minted.rewrite, before the conflict and stand-down filters have withheld anything';
COMMENT ON VIEW graphitron_field_minted IS 'One of the two sets graphitron_field is the union of: a field macro expansion states, either adding one where the author wrote none or restating the carrier the directive sits on. For example the edges on a minted QueryFilmsConnection, and the rewritten films whose author wrote it as a plain list.';
-- COMMENT ON COLUMN graphitron_field_minted.graph_name IS 'the owning graph''s partition, carried from the minting row';
-- COMMENT ON COLUMN graphitron_field_minted.type_name IS 'the type the minted field sits on';
-- COMMENT ON COLUMN graphitron_field_minted.field_name IS 'the field''s own name';
-- COMMENT ON COLUMN graphitron_field_minted.coordinate IS 'Type.field, on graphitron_field_authored.coordinate''s terms. The one place the element grain and this one part company: a rewritten carrier is an authored element and a minted field, so this coordinate can be one graphitron_element_authored also carries, where no other minted set''s can';
-- COMMENT ON COLUMN graphitron_field_minted.ordinal IS 'where the expansion put it among the type''s fields; a rewritten carrier keeps the position its author wrote, the expansion restating it unchanged';
-- COMMENT ON COLUMN graphitron_field_minted.type_sdl IS 'the type expression the expansion wrote, wrappers included; for a rewritten carrier this is the whole of what changed';
-- COMMENT ON COLUMN graphitron_field_minted.named_type IS 'the name at the bottom of that expression';
-- COMMENT ON COLUMN graphitron_field_minted.non_null IS 'whether the outermost wrapper is non-null, which a rewritten carrier keeps from its author';
-- COMMENT ON COLUMN graphitron_field_minted.list_depth IS 'how many list wrappers the expression has';
-- COMMENT ON COLUMN graphitron_field_minted.item_non_null IS 'whether a list''s items are non-null, and nothing where it is not a list';
-- COMMENT ON COLUMN graphitron_field_minted.default_value_sdl IS 'always nothing, and stated here rather than carried: no macro writes a default onto an output field and every field minted or rewritten today is one, so the nullness is a property of this population rather than a column any arm declined to hold';
-- COMMENT ON COLUMN graphitron_field_minted.rewrite IS 'whether this row restates a field the author wrote rather than adding one. The rewritten carrier is the only arm that does, and it is what tells the element arm which coordinates are already anchored by the transcription';
-- COMMENT ON COLUMN graphitron_field_minted.description IS 'the docstring the macro wrote; identical across the carriers that state one shared machinery field, which is what lets the distinct collapse them';
-- COMMENT ON COLUMN graphitron_field_minted.note IS 'on a rewritten carrier, the note its file''s entry configures, which the anchor appends to the description, minting the one the generator emits; NULL where none is configured';

CREATE VIEW graphitron_enum_value_authored (graph_name, type_name, value_name, coordinate,
                                            ordinal, description, note) AS
SELECT v.graph_name, v.type_name, v.value_name, v.type_name || '.' || v.value_name, v.ordinal,
       v.description, s.description_note
  FROM graphql_enum_value v
  LEFT JOIN store_graph_source_input s ON s.graph_name = v.graph_name AND s.source_name = v.source_name;
COMMENT ON VIEW graphitron_enum_value_authored IS 'The one set graphitron_enum_value is filled from: an enum value an author declared, with the note its file configures. For example the G in enum Rating { G PG }.';
-- COMMENT ON COLUMN graphitron_enum_value_authored.graph_name IS 'the owning graph''s partition, carried from the transcription';
-- COMMENT ON COLUMN graphitron_enum_value_authored.type_name IS 'the enum, as the author spelled it';
-- COMMENT ON COLUMN graphitron_enum_value_authored.value_name IS 'the value, as the author spelled it';
-- COMMENT ON COLUMN graphitron_enum_value_authored.coordinate IS 'Type.VALUE, the join up to graphitron_element';
-- COMMENT ON COLUMN graphitron_enum_value_authored.ordinal IS 'the value''s position, carried from graphql_enum_value';
-- COMMENT ON COLUMN graphitron_enum_value_authored.description IS 'the docstring the author wrote, or nothing';
-- COMMENT ON COLUMN graphitron_enum_value_authored.note IS 'the note its file''s entry configures, which the anchor appends to the description, minting the one the generator emits; NULL where none is configured';

CREATE VIEW graphitron_argument_authored (graph_name, type_name, field_name, argument_name,
                                          coordinate, ordinal, type_sdl, named_type, non_null,
                                          list_depth, item_non_null, default_value_sdl,
                                          description, note) AS
SELECT a.graph_name, a.type_name, a.field_name, a.argument_name,
       a.type_name || '.' || a.field_name || '(' || a.argument_name || ':)', a.ordinal,
       a.type_sdl, a.named_type, a.non_null, a.list_depth, a.item_non_null, a.default_value_sdl,
       a.description, s.description_note
  FROM graphql_argument a
  LEFT JOIN store_graph_source_input s ON s.graph_name = a.graph_name AND s.source_name = a.source_name
 -- An argument of a field an @issue absorbs goes with its field.
 WHERE NOT EXISTS (SELECT 1 FROM graphitron_voucher_member m
                    WHERE m.graph_name = a.graph_name AND m.type_name = a.type_name
                      AND m.field_name = a.field_name);
COMMENT ON VIEW graphitron_argument_authored IS 'One of the two sets graphitron_argument is the union of: an argument an author declared, carried across whole. For example the lang in title(lang: Lang = NB): String, default included.';
-- COMMENT ON COLUMN graphitron_argument_authored.note IS 'the note its file''s entry configures, which the anchor appends to the description, minting the one the generator emits; NULL where none is configured';
-- COMMENT ON COLUMN graphitron_argument_authored.graph_name IS 'the owning graph''s partition, carried from the transcription';
-- COMMENT ON COLUMN graphitron_argument_authored.type_name IS 'the type the owning field is declared on';
-- COMMENT ON COLUMN graphitron_argument_authored.field_name IS 'the field the argument belongs to';
-- COMMENT ON COLUMN graphitron_argument_authored.argument_name IS 'the argument''s own name';
-- COMMENT ON COLUMN graphitron_argument_authored.coordinate IS 'Type.field(argument:), the specification''s spelling, the trailing colon included because the specification writes it';
-- COMMENT ON COLUMN graphitron_argument_authored.ordinal IS 'where the author wrote it among the field''s arguments';
-- COMMENT ON COLUMN graphitron_argument_authored.type_sdl IS 'the type expression as written, wrappers included';
-- COMMENT ON COLUMN graphitron_argument_authored.named_type IS 'the name at the bottom of that expression';
-- COMMENT ON COLUMN graphitron_argument_authored.non_null IS 'whether the outermost wrapper is non-null';
-- COMMENT ON COLUMN graphitron_argument_authored.list_depth IS 'how many list wrappers the expression has';
-- COMMENT ON COLUMN graphitron_argument_authored.item_non_null IS 'whether a list''s items are non-null, and nothing where it is not a list';
-- COMMENT ON COLUMN graphitron_argument_authored.default_value_sdl IS 'the default as written, or nothing';
-- COMMENT ON COLUMN graphitron_argument_authored.description IS 'the docstring the author wrote, or nothing';

CREATE VIEW graphitron_argument_minted_candidate (graph_name, type_name, field_name, argument_name,
                                        coordinate, ordinal, type_sdl, named_type, non_null,
                                        list_depth, item_non_null, default_value_sdl,
                                        description) AS
SELECT DISTINCT m.graph_name, m.type_name, m.field_name, m.argument_name,
       m.type_name || '.' || m.field_name || '(' || m.argument_name || ':)', m.ordinal,
       m.type_sdl, m.named_type, m.non_null, m.list_depth, m.item_non_null,
       m.default_value_sdl, m.description
  FROM (
        -- Pagination, on every carrier. The page size the application asked for, or the default
        -- where it asked for none, lowered to the build's maximum page size where that is smaller,
        -- so the default a client is told never exceeds the page it can receive. The 100 is
        -- ConnectionDefaults.DEFAULT_PAGE_SIZE, and the CASE its defaultPageSize (not LEAST, whose
        -- stored form H2 writes with a RESPECT NULLS the definition walk cannot parse). An authored
        -- default passes through as written; graphitron_entry_defect judges it.
        SELECT c.graph_name, c.type_name, c.field_name, 'first' AS argument_name,
               c.argument_count AS ordinal, 'Int' AS type_sdl, 'Int' AS named_type,
               FALSE AS non_null, 0 AS list_depth, CAST(NULL AS BOOLEAN) AS item_non_null,
               CAST(COALESCE(c.default_first_value,
                             CASE WHEN mx.max_page_size < 100 THEN mx.max_page_size ELSE 100 END)
                    AS VARCHAR) AS default_value_sdl,
               CAST(NULL AS VARCHAR) AS description
          FROM graphitron_connection_carrier c
          LEFT JOIN store_graph_max_allowed_page_size mx ON mx.graph_name = c.graph_name
         UNION ALL
        SELECT graph_name, type_name, field_name, 'after',
               argument_count + 1, 'String', 'String',
               FALSE, 0, NULL, NULL, NULL
          FROM graphitron_connection_carrier) m
;
CREATE VIEW graphitron_argument_minted (graph_name, type_name, field_name, argument_name,
                                        coordinate, ordinal, type_sdl, named_type, non_null,
                                        list_depth, item_non_null, default_value_sdl,
                                        description) AS
SELECT * FROM graphitron_argument_minted_candidate m
 WHERE NOT EXISTS (SELECT 1 FROM graphitron_minted_conflict c
                    WHERE c.graph_name = m.graph_name AND c.coordinate = m.coordinate)
   AND NOT EXISTS (SELECT 1 FROM graphql_argument_element a
                    WHERE a.graph_name = m.graph_name AND a.type_name = m.type_name
                      AND a.field_name = m.field_name AND a.argument_name = m.argument_name);
COMMENT ON VIEW graphitron_argument_minted_candidate IS 'What the arms of the argument mint state before any disagreement between them is resolved. For example a carrier whose author already wrote first is one row here and none in graphitron_argument_minted.';
-- COMMENT ON COLUMN graphitron_argument_minted_candidate.graph_name IS 'the same fact as graphitron_argument_minted.graph_name, before the conflict and stand-down filters have withheld anything';
-- COMMENT ON COLUMN graphitron_argument_minted_candidate.type_name IS 'the same fact as graphitron_argument_minted.type_name, before the conflict and stand-down filters have withheld anything';
-- COMMENT ON COLUMN graphitron_argument_minted_candidate.field_name IS 'the same fact as graphitron_argument_minted.field_name, before the conflict and stand-down filters have withheld anything';
-- COMMENT ON COLUMN graphitron_argument_minted_candidate.argument_name IS 'the same fact as graphitron_argument_minted.argument_name, before the conflict and stand-down filters have withheld anything';
-- COMMENT ON COLUMN graphitron_argument_minted_candidate.coordinate IS 'the same fact as graphitron_argument_minted.coordinate, before the conflict and stand-down filters have withheld anything';
-- COMMENT ON COLUMN graphitron_argument_minted_candidate.ordinal IS 'the same fact as graphitron_argument_minted.ordinal, before the conflict and stand-down filters have withheld anything';
-- COMMENT ON COLUMN graphitron_argument_minted_candidate.type_sdl IS 'the same fact as graphitron_argument_minted.type_sdl, before the conflict and stand-down filters have withheld anything';
-- COMMENT ON COLUMN graphitron_argument_minted_candidate.named_type IS 'the same fact as graphitron_argument_minted.named_type, before the conflict and stand-down filters have withheld anything';
-- COMMENT ON COLUMN graphitron_argument_minted_candidate.non_null IS 'the same fact as graphitron_argument_minted.non_null, before the conflict and stand-down filters have withheld anything';
-- COMMENT ON COLUMN graphitron_argument_minted_candidate.list_depth IS 'the same fact as graphitron_argument_minted.list_depth, before the conflict and stand-down filters have withheld anything';
-- COMMENT ON COLUMN graphitron_argument_minted_candidate.item_non_null IS 'the same fact as graphitron_argument_minted.item_non_null, before the conflict and stand-down filters have withheld anything';
-- COMMENT ON COLUMN graphitron_argument_minted_candidate.default_value_sdl IS 'the same fact as graphitron_argument_minted.default_value_sdl, before the conflict and stand-down filters have withheld anything';
-- COMMENT ON COLUMN graphitron_argument_minted_candidate.description IS 'the same fact as graphitron_argument_minted.description, before the conflict and stand-down filters have withheld anything';
COMMENT ON VIEW graphitron_argument_minted IS 'One of the two sets graphitron_argument is the union of: an argument macro expansion adds where the author wrote none, which today is a connection carrier''s pagination. For example the first and after on Query.films(first:).';
-- COMMENT ON COLUMN graphitron_argument_minted.graph_name IS 'the owning graph''s partition, carried from the minting row';
-- COMMENT ON COLUMN graphitron_argument_minted.type_name IS 'the type the owning field is declared on';
-- COMMENT ON COLUMN graphitron_argument_minted.field_name IS 'the field the argument belongs to';
-- COMMENT ON COLUMN graphitron_argument_minted.argument_name IS 'the argument''s own name';
-- COMMENT ON COLUMN graphitron_argument_minted.coordinate IS 'Type.field(argument:), on graphitron_argument_authored.coordinate''s terms';
-- COMMENT ON COLUMN graphitron_argument_minted.ordinal IS 'where the expansion put it among the field''s arguments';
-- COMMENT ON COLUMN graphitron_argument_minted.type_sdl IS 'the type expression the expansion wrote, wrappers included';
-- COMMENT ON COLUMN graphitron_argument_minted.named_type IS 'the name at the bottom of that expression';
-- COMMENT ON COLUMN graphitron_argument_minted.non_null IS 'whether the outermost wrapper is non-null';
-- COMMENT ON COLUMN graphitron_argument_minted.list_depth IS 'how many list wrappers the expression has';
-- COMMENT ON COLUMN graphitron_argument_minted.item_non_null IS 'whether a list''s items are non-null, and nothing where it is not a list';
-- COMMENT ON COLUMN graphitron_argument_minted.default_value_sdl IS 'the default the expansion wrote, which is where a page size comes from; carried rather than nulled, unlike the field set, because pagination arguments are exactly the place a macro does write one';
-- COMMENT ON COLUMN graphitron_argument_minted.description IS 'the docstring the macro wrote';

CREATE VIEW graphitron_element_minted_type (graph_name, coordinate, element_kind) AS
SELECT graph_name, type_name, 'NAMED_TYPE'
  FROM graphitron_type_minted;
COMMENT ON VIEW graphitron_element_minted_type IS 'One of the four sets graphitron_element is the union of: a type macro expansion adds to the schema, which no author declared and no two applications disagree about. For example an author writing films: [Film!]! @asConnection and nothing else gets QueryFilmsConnection here, where an author who also wrote their own QueryFilmsConnection gets no row.';
-- COMMENT ON COLUMN graphitron_element_minted_type.graph_name IS 'the owning graph''s partition, carried from the minting row';
-- COMMENT ON COLUMN graphitron_element_minted_type.coordinate IS 'the minted type''s name, which is how the specification spells a named type''s coordinate';
-- COMMENT ON COLUMN graphitron_element_minted_type.element_kind IS 'always NAMED_TYPE, the macros minting nothing else at this grain';

CREATE VIEW graphitron_element_minted_field (graph_name, coordinate, element_kind) AS
SELECT graph_name, coordinate, 'FIELD'
  FROM graphitron_field_minted
 -- A rewritten carrier is an authored element and a minted field at once: the coordinate is one
 -- the transcription already anchors, so the authored arm holds it and this one stands off.
 WHERE NOT rewrite;
COMMENT ON VIEW graphitron_element_minted_field IS 'One of the four sets graphitron_element is the union of: a field macro expansion adds to the schema, on the minted type set''s terms and one more. For example the edges and pageInfo on a minted QueryFilmsConnection, and nothing at all where the author declared that type themselves.';
-- COMMENT ON COLUMN graphitron_element_minted_field.graph_name IS 'the owning graph''s partition, carried from the minting row';
-- COMMENT ON COLUMN graphitron_element_minted_field.coordinate IS 'the field''s coordinate, Type.field in the specification''s grammar';
-- COMMENT ON COLUMN graphitron_element_minted_field.element_kind IS 'always FIELD; no macro today puts a field into an input object, and the day one does this is where the kind starts being derived';

CREATE VIEW graphitron_element_minted_argument (graph_name, coordinate, element_kind) AS
SELECT graph_name, coordinate, 'FIELD_ARGUMENT'
  FROM graphitron_argument_minted;
COMMENT ON VIEW graphitron_element_minted_argument IS 'One of the four sets graphitron_element is the union of: a field argument macro expansion adds to the schema, which today is the pagination a connection carrier gets where its author wrote none. For example the first and after on Query.films(first:) where the author wrote films: [Film!]! @asConnection with no arguments.';
-- COMMENT ON COLUMN graphitron_element_minted_argument.graph_name IS 'the owning graph''s partition, carried from the minting row';
-- COMMENT ON COLUMN graphitron_element_minted_argument.coordinate IS 'the argument''s coordinate, Type.field(argument:) in the specification''s grammar, the trailing colon included because the specification writes it';
-- COMMENT ON COLUMN graphitron_element_minted_argument.element_kind IS 'always FIELD_ARGUMENT';

CREATE TABLE graphitron_spelled_reference_entry (
  graph_name           VARCHAR NOT NULL,
  spelling             VARCHAR NOT NULL,
  namespace_part       VARCHAR,
  name_part            VARCHAR NOT NULL,
  namespace_part_upper VARCHAR GENERATED ALWAYS AS (UPPER(namespace_part)),
  name_part_upper      VARCHAR GENERATED ALWAYS AS (UPPER(name_part)),
  PRIMARY KEY (graph_name, spelling),
  FOREIGN KEY (graph_name) REFERENCES store_graph (graph_name)
);
CREATE INDEX graphitron_spelled_reference_entry_name_ix
  ON graphitron_spelled_reference_entry (graph_name, name_part_upper);
COMMENT ON TABLE graphitron_spelled_reference_entry IS 'Every table or routine name this graph authors anywhere, once per distinct spelling: the fact underneath @table(name:), a @reference path element''s table, its argument-site and @referenceFor siblings, @mutation''s delete target and @routine(name:). Seven relations carry a spelling of this shape and none of them is the spelling; each is a site that wrote one, keyed by where it was written. Keyed by the spelling itself and by nothing else, on the terms graphitron_spelled_table already argues: the resolution does not vary by site, so a spelling written at five coordinates is one fact and one row here, and a reader asking what a name resolves to never has to say which directive wrote it. That is why this relation carries no site discriminator: the shared question has no per-site answer. Arrives already split, capture writing the namespace half and the name half beside the value, so a reader matches on stored folded columns rather than on a fold computed per candidate row. The namespace half is null on an unqualified spelling, which matches on its name half alone. Written by capture at the moment each site is read, deduplicated there rather than by a reader: the same spelling authored twice is one row, and the primary key is what says so. graphitron_ast_routine_entry spells its own site''s column routine_ref where the other six spell theirs table_ref; the two are the same fact and this relation is where that is settled, a name having only one spelling once there is a relation to hold it. Deprecated: written by the decode the incumbent walk drives, which goes when the decode reads the entry relations instead of a registry. Nothing has been written to replace it yet.';
COMMENT ON COLUMN graphitron_spelled_reference_entry.graph_name IS 'the owning graph''s partition, anchored by store_graph; the leading key dimension that keeps one workspace''s graphs apart';
COMMENT ON COLUMN graphitron_spelled_reference_entry.spelling IS 'the name exactly as the author wrote it, qualifier and all; with the graph the whole key, one row per distinct spelling however many sites wrote it';
COMMENT ON COLUMN graphitron_spelled_reference_entry.namespace_part IS 'the qualifier half of the spelling as written, null on an unqualified name; a null here is the author having written no qualifier and never a qualifier withheld';
COMMENT ON COLUMN graphitron_spelled_reference_entry.name_part IS 'the name half of the spelling as written, which is the whole spelling on an unqualified name';
COMMENT ON COLUMN graphitron_spelled_reference_entry.namespace_part_upper IS 'the case-folded namespace half, computed by the database; the column a catalog match compares against, so neither side of that comparison is a fold evaluated per row';
COMMENT ON COLUMN graphitron_spelled_reference_entry.name_part_upper IS 'the case-folded name half, computed by the database; the leading column of this relation''s index because a catalog match binds it first';

CREATE TABLE graphitron_field_target (
  graph_name        VARCHAR NOT NULL,
  type_name         VARCHAR NOT NULL,
  field_name        VARCHAR NOT NULL,
  target_type_name  VARCHAR NOT NULL,
  wrapper_type_name VARCHAR,
  touched_at        TIMESTAMP NOT NULL,
  PRIMARY KEY (graph_name, type_name, field_name),
  FOREIGN KEY (graph_name, type_name, field_name)
    REFERENCES graphitron_field (graph_name, type_name, field_name) ON DELETE CASCADE
);
CREATE INDEX graphitron_field_target_wrapper_ix
  ON graphitron_field_target (graph_name, wrapper_type_name);
CREATE INDEX graphitron_field_target_type_ix
  ON graphitron_field_target (graph_name, target_type_name);
COMMENT ON TABLE graphitron_field_target IS 'A field''s target type, unwrapped from a connection where the field returns one, with the connection beside it: one row per field. For example films: [Film!]! @asConnection has the target Film and the wrapper the macro minted, and title: String has the target String and no wrapper.';
COMMENT ON COLUMN graphitron_field_target.graph_name IS 'the owning graph''s partition, anchored by store_graph; the leading key dimension that keeps one workspace''s graphs apart';
COMMENT ON COLUMN graphitron_field_target.type_name IS 'the type owning the field';
COMMENT ON COLUMN graphitron_field_target.field_name IS 'the field whose target this row states; with the two columns above the whole key, one row per field of the graph';
COMMENT ON COLUMN graphitron_field_target.target_type_name IS 'the target type''s name, unwrapped. A name and never a binding, so a reader joins graphitron_tabletype, graphql_poly_member or graphql_type on it according to what it needs to know';
COMMENT ON COLUMN graphitron_field_target.wrapper_type_name IS 'the connection type the target was unwrapped from, which is the field''s named type; null where the field returns its target directly. List and non-null wrapping are cardinality rather than a wrapper, and stay on graphitron_field';
COMMENT ON COLUMN graphitron_field_target.touched_at IS 'when the reading that derived this row ran. The reading finishes by deleting this graph''s rows carrying a different instant, which are the coordinates a rewriting moved off; a field the author removed takes its row with it through the cascade above, so the two together are what let a second reading of one store land on the first''s rows rather than meeting them on the key';

CREATE TABLE graphitron_occurrence (
  graph_name             VARCHAR   NOT NULL,
  coordinate             VARCHAR   NOT NULL,
  element_coordinate     VARCHAR   NOT NULL,
  name                   VARCHAR   NOT NULL,
  kind                   VARCHAR   NOT NULL,
  depth                  INT       NOT NULL,
  touched_at             TIMESTAMP NOT NULL,
  element_graph_ref      VARCHAR,
  element_coordinate_ref VARCHAR,
  -- The ancestors, each a function of the coordinate's grammar rather than a fact a writer states.
  parent_coordinate      VARCHAR GENERATED ALWAYS AS (CASE
    WHEN POSITION('(', coordinate) = 0 THEN
      CASE WHEN CHAR_LENGTH(coordinate) - CHAR_LENGTH(REPLACE(coordinate, '.', '')) > 1
           THEN REGEXP_REPLACE(coordinate, '\.[^.]+$', '') END
    WHEN POSITION('.', SUBSTRING(coordinate, POSITION('(', coordinate))) = 0
      THEN SUBSTRING(coordinate, 1, POSITION('(', coordinate) - 1)
    ELSE REGEXP_REPLACE(coordinate, '\.[^.]+:\)$', ':)') END),
  field_coordinate       VARCHAR GENERATED ALWAYS AS (CASE
    WHEN POSITION('(', coordinate) = 0 THEN coordinate
    ELSE SUBSTRING(coordinate, 1, POSITION('(', coordinate) - 1) END),
  argument_coordinate    VARCHAR GENERATED ALWAYS AS (CASE
    WHEN POSITION('(', coordinate) = 0 THEN NULL
    ELSE REGEXP_REPLACE(coordinate, '\(([^.:]+)[.:].*$', '($1:)') END),
  PRIMARY KEY (graph_name, coordinate),
  FOREIGN KEY (graph_name) REFERENCES store_graph (graph_name),
  -- The occurrence it hangs under; a parent the corpus no longer reaches takes its subtree with it.
  FOREIGN KEY (graph_name, parent_coordinate)
    REFERENCES graphitron_occurrence (graph_name, coordinate) ON DELETE CASCADE,
  -- What it is an occurrence of, through the anchor's own copy of the key: a key to what an anchor was
  -- built from does not cascade, and the sweep removes the row the element no longer reaches.
  FOREIGN KEY (element_graph_ref, element_coordinate_ref)
    REFERENCES graphitron_element (graph_name, coordinate) ON DELETE SET NULL,
  CHECK (element_graph_ref IS NULL OR element_graph_ref = graph_name),
  CHECK (element_coordinate_ref IS NULL OR element_coordinate_ref = element_coordinate),
  CHECK (kind IN ('FIELD', 'INPUT_FIELD', 'FIELD_ARGUMENT')),
  CHECK ((parent_coordinate IS NULL) = (depth = 0))
);
CREATE INDEX graphitron_occurrence_step_ix ON graphitron_occurrence (graph_name, parent_coordinate, name);
COMMENT ON INDEX graphitron_occurrence_step_ix IS 'Serves a written path walked one step at a time: from an occurrence, the child of a given name, so argMapping''s input.a.b resolves as one keyed join per segment rather than by building or parsing a coordinate.';
COMMENT ON TABLE graphitron_occurrence IS 'One occurrence of an element, a use of a declared field, argument or input field reached along a chain: one row per nested coordinate. For example Emne.navn.en is en on the type Emne.navn returns, which has no table of its own, and Query.films(filter.cast.firstName:) an input field under the argument filter.';
COMMENT ON COLUMN graphitron_occurrence.graph_name IS 'the owning graph''s partition, anchored by store_graph; the leading key dimension that keeps one workspace''s graphs apart';
COMMENT ON COLUMN graphitron_occurrence.coordinate IS 'where the field or argument is reached, spelled TypeName.nestingField.nestedField from the nearest field whose parent is not nested, an argument as (argument:) and an input field inside its argument''s parentheses, (argument.inputField:); with the graph, the key. A field whose parent is a root, is table-bound or is targeted by no field has its own Type.field';
COMMENT ON COLUMN graphitron_occurrence.element_coordinate IS 'the declared field, input field or argument this is an occurrence of, as graphitron_element spells it';
COMMENT ON COLUMN graphitron_occurrence.parent_coordinate IS 'the occurrence this one hangs under: the field a nested field or an argument is reached through, or the argument or input field an input field is under; null where a chain starts. Generated from the coordinate''s grammar: Type.a.b hangs under Type.a, Type.f(arg:) under Type.f and Type.f(arg.x:) under Type.f(arg:), so a change to how a coordinate is spelled lands in this expression';
COMMENT ON COLUMN graphitron_occurrence.field_coordinate IS 'the field occurrence this one is reached through or is: the coordinate itself for a field, the part before the parentheses for an argument or input field. Generated from the coordinate''s grammar, so a change to how a coordinate is spelled lands in this expression';
COMMENT ON COLUMN graphitron_occurrence.argument_coordinate IS 'the argument occurrence an argument or input field is under or is, Type.f(arg:) for both Type.f(arg:) and Type.f(arg.x.y:); null for a field. Generated from the coordinate''s grammar, so a change to how a coordinate is spelled lands in this expression';
COMMENT ON COLUMN graphitron_occurrence.name IS 'the field or argument name at this step, the last segment of the coordinate, stated so a reader walks a path by name without parsing the coordinate';
COMMENT ON COLUMN graphitron_occurrence.kind IS 'what the element is, in graphitron_element''s vocabulary: FIELD, INPUT_FIELD or FIELD_ARGUMENT, so an argument and an input field are told apart without parsing';
COMMENT ON COLUMN graphitron_occurrence.depth IS 'how many steps the occurrence is below where its chain starts, 0 at the start';
COMMENT ON COLUMN graphitron_occurrence.touched_at IS 'the reading that last wrote this row; the sweep deletes the rows an older reading wrote';
COMMENT ON COLUMN graphitron_occurrence.element_graph_ref IS 'the graph half of the element''s key, nullable so the element''s removal sets the reference null rather than cascading';
COMMENT ON COLUMN graphitron_occurrence.element_coordinate_ref IS 'the coordinate half of the element''s key, equal to element_coordinate while the element stands';

CREATE INDEX graphitron_occurrence_element_ix ON graphitron_occurrence (graph_name, element_coordinate);
COMMENT ON INDEX graphitron_occurrence_element_ix IS 'A reader holding a declared element asks for its occurrences, and the primary key, a nested coordinate, serves none of that. graphitron_argmapping_step asks it of every argMapping, which is written on a declared field, argument or input field and resolved once per place that element is reached.';

CREATE TABLE graphitron_occurrence_list_element (
  graph_name      VARCHAR   NOT NULL,
  coordinate      VARCHAR   NOT NULL,
  list_coordinate VARCHAR   NOT NULL,
  touched_at      TIMESTAMP NOT NULL,
  PRIMARY KEY (graph_name, coordinate, list_coordinate),
  FOREIGN KEY (graph_name, coordinate)
    REFERENCES graphitron_occurrence (graph_name, coordinate) ON DELETE CASCADE,
  FOREIGN KEY (graph_name, list_coordinate)
    REFERENCES graphitron_occurrence (graph_name, coordinate) ON DELETE CASCADE
);
COMMENT ON TABLE graphitron_occurrence_list_element IS 'An input field read once per element of a list above it: one row per input-field occurrence and each argument or input-field occurrence above it whose type is a list. For example Query.filmActorsByPairs(filter.pairs.actorId:) is read once per element of Query.filmActorsByPairs(filter.pairs:), and Query.filmsByFilter(filter.title:) draws no row.';
COMMENT ON COLUMN graphitron_occurrence_list_element.graph_name IS 'the owning graph''s partition';
COMMENT ON COLUMN graphitron_occurrence_list_element.coordinate IS 'the input-field occurrence read per element';
COMMENT ON COLUMN graphitron_occurrence_list_element.list_coordinate IS 'the list occurrence above it, an argument or an input field whose type is a list; with the graph and the coordinate, the grain, so an occurrence under two lists draws two rows';
COMMENT ON COLUMN graphitron_occurrence_list_element.touched_at IS 'when the reading that derived this row ran; swept per graph after the reading upserts';

CREATE VIEW graphitron_occurrence_list_element_rule (graph_name, coordinate, list_coordinate) AS
SELECT o.graph_name, o.coordinate, p.coordinate
  FROM graphitron_occurrence o
  JOIN graphitron_occurrence p
    ON p.graph_name = o.graph_name AND p.coordinate = o.parent_coordinate
  LEFT JOIN graphitron_argument a
    ON p.kind = 'FIELD_ARGUMENT' AND a.graph_name = p.graph_name AND a.coordinate = p.element_coordinate
  LEFT JOIN graphitron_field f
    ON p.kind = 'INPUT_FIELD' AND f.graph_name = p.graph_name AND f.coordinate = p.element_coordinate
 WHERE o.kind = 'INPUT_FIELD' AND (a.is_list OR f.is_list)
UNION ALL
SELECT o.graph_name, o.coordinate, l.list_coordinate
  FROM graphitron_occurrence o
  JOIN graphitron_occurrence_list_element l
    ON l.graph_name = o.graph_name AND l.coordinate = o.parent_coordinate
 WHERE o.kind = 'INPUT_FIELD';
COMMENT ON VIEW graphitron_occurrence_list_element_rule IS 'One row the list element rule computes, in the shape graphitron_occurrence_list_element stores: the rule itself, evaluated a depth at a time rather than read off disk. For example the occurrence-lists stage inserts this view''s rows at one depth into graphitron_occurrence_list_element, which is the name every reader spells.';
-- COMMENT ON COLUMN graphitron_occurrence_list_element_rule.graph_name IS 'the graph_name of a row of this rule, which the stage writes into graphitron_occurrence_list_element.graph_name';
-- COMMENT ON COLUMN graphitron_occurrence_list_element_rule.coordinate IS 'the coordinate of a row of this rule, which the stage writes into graphitron_occurrence_list_element.coordinate';
-- COMMENT ON COLUMN graphitron_occurrence_list_element_rule.list_coordinate IS 'the list_coordinate of a row of this rule, which the stage writes into graphitron_occurrence_list_element.list_coordinate';

CREATE TABLE graphitron_occurrence_overridden (
  graph_name VARCHAR   NOT NULL,
  coordinate VARCHAR   NOT NULL,
  touched_at TIMESTAMP NOT NULL,
  PRIMARY KEY (graph_name, coordinate),
  FOREIGN KEY (graph_name, coordinate)
    REFERENCES graphitron_occurrence (graph_name, coordinate) ON DELETE CASCADE
);
COMMENT ON TABLE graphitron_occurrence_overridden IS 'An occurrence at or under a @condition written with override: true, whose generated predicates that condition stands in for: one row per occurrence carrying one, and per argument or input-field occurrence under one. For example Query.films(filter:) @condition(..., override: true) on the field draws rows for Query.films, Query.films(filter:) and every input field under filter, and none for a field nested under Query.films.';
COMMENT ON COLUMN graphitron_occurrence_overridden.graph_name IS 'the owning graph''s partition';
COMMENT ON COLUMN graphitron_occurrence_overridden.coordinate IS 'the occurrence; with the graph, the grain';
COMMENT ON COLUMN graphitron_occurrence_overridden.touched_at IS 'when the reading that derived this row ran; swept per graph after the reading upserts';

CREATE VIEW graphitron_occurrence_overridden_rule (graph_name, coordinate) AS
-- An occurrence whose declaration carries @condition written with override: true.
SELECT o.graph_name, o.coordinate
  FROM graphitron_occurrence o
 WHERE EXISTS (SELECT 1 FROM graphitron_directive_application_arg a
                WHERE a.graph_name = o.graph_name AND a.coordinate = o.element_coordinate
                  AND a.directive_name = 'condition' AND a.directive_argument_name = 'override'
                  AND a.value_sdl = 'true')
UNION
-- An argument or input field under one, the depth above's stored rows; a field nested under it
-- filters by its own arguments.
SELECT o.graph_name, o.coordinate
  FROM graphitron_occurrence o
  JOIN graphitron_occurrence_overridden p
    ON p.graph_name = o.graph_name AND p.coordinate = o.parent_coordinate
 WHERE o.kind IN ('FIELD_ARGUMENT', 'INPUT_FIELD');
COMMENT ON VIEW graphitron_occurrence_overridden_rule IS 'One row the overridden rule computes, in the shape graphitron_occurrence_overridden stores: the rule itself, evaluated a depth at a time rather than read off disk. For example the occurrence-overrides stage inserts this view''s rows at one depth into graphitron_occurrence_overridden, which is the name every reader spells.';
-- COMMENT ON COLUMN graphitron_occurrence_overridden_rule.graph_name IS 'the graph_name of a row of this rule, which the stage writes into graphitron_occurrence_overridden.graph_name';
-- COMMENT ON COLUMN graphitron_occurrence_overridden_rule.coordinate IS 'the coordinate of a row of this rule, which the stage writes into graphitron_occurrence_overridden.coordinate';

-- An argMapping entry binding a parameter to an argument path, under one occurrence of its call.
-- One pair of a written argMapping, named: the mapping's site and the parameter the pair binds, the
-- first written of two naming one parameter kept. The entry's position rides along for a defect.
CREATE VIEW graphitron_argmapping_pair_rule
  (graph_name, coordinate, directive_name, ordinal, owner, parameter_name, bound_to,
   source_name, source_line, source_column, position) AS
SELECT graph_name, coordinate, directive_name, ordinal, owner, parameter_name, bound_to,
       source_name, source_line, source_column, position
  FROM (SELECT s.graph_name, s.coordinate, s.directive_name, s.ordinal, s.owner,
               e.param_name AS parameter_name, e.bound_to, e.source_name, e.source_line,
               e.source_column, e.position,
               ROW_NUMBER() OVER (PARTITION BY s.graph_name, s.coordinate, s.directive_name,
                                  s.ordinal, s.owner, e.param_name
                                  ORDER BY e.position) AS written
          FROM graphitron_ast_argmapping_pair_entry e
          JOIN graphitron_argmapping_site s
            ON s.graph_name = e.graph_name AND s.source_name = e.source_name
           AND s.source_line = e.source_line AND s.source_column = e.source_column) first_written
 WHERE written = 1;
COMMENT ON VIEW graphitron_argmapping_pair_rule IS 'One row the argMapping pair rule computes, in the shape graphitron_argmapping_pair stores: the rule itself, evaluated on demand rather than read off disk. For example the graphitron anchor inserts this view''s rows for one graph into graphitron_argmapping_pair, which is the name every reader spells.';
-- COMMENT ON COLUMN graphitron_argmapping_pair_rule.graph_name IS 'the owning graph''s partition';
-- COMMENT ON COLUMN graphitron_argmapping_pair_rule.coordinate IS 'the element the mapping''s application is on';
-- COMMENT ON COLUMN graphitron_argmapping_pair_rule.directive_name IS 'the mapping''s directive';
-- COMMENT ON COLUMN graphitron_argmapping_pair_rule.ordinal IS 'its application''s ordinal';
-- COMMENT ON COLUMN graphitron_argmapping_pair_rule.owner IS 'what the mapping is written under';
-- COMMENT ON COLUMN graphitron_argmapping_pair_rule.parameter_name IS 'the parameter the pair binds';
-- COMMENT ON COLUMN graphitron_argmapping_pair_rule.bound_to IS 'the right-hand side as written';
-- COMMENT ON COLUMN graphitron_argmapping_pair_rule.source_name IS 'the file the mapping string was written in';
-- COMMENT ON COLUMN graphitron_argmapping_pair_rule.source_line IS 'its line';
-- COMMENT ON COLUMN graphitron_argmapping_pair_rule.source_column IS 'its column';
-- COMMENT ON COLUMN graphitron_argmapping_pair_rule.position IS 'the pair''s position in its mapping';

CREATE TABLE graphitron_argmapping_pair (
  graph_name     VARCHAR   NOT NULL,
  coordinate     VARCHAR   NOT NULL,
  directive_name VARCHAR   NOT NULL,
  ordinal        INT       NOT NULL,
  owner          VARCHAR   NOT NULL,
  parameter_name VARCHAR   NOT NULL,
  bound_to       VARCHAR   NOT NULL,
  source_name    VARCHAR   NOT NULL,
  source_line    INT       NOT NULL,
  source_column  INT       NOT NULL,
  position       INT       NOT NULL,
  touched_at     TIMESTAMP NOT NULL,
  PRIMARY KEY (graph_name, coordinate, directive_name, ordinal, owner, parameter_name),
  -- The mapping the pair is one of.
  FOREIGN KEY (graph_name, coordinate, directive_name, ordinal, owner)
    REFERENCES graphitron_argmapping_site (graph_name, coordinate, directive_name, ordinal, owner)
    ON DELETE CASCADE,
  -- The entry as written, so a pair cannot outlive what an author wrote, and a defect points there.
  FOREIGN KEY (graph_name, source_name, source_line, source_column, position)
    REFERENCES graphitron_ast_argmapping_pair_entry (graph_name, source_name, source_line, source_column, position)
    ON DELETE CASCADE
);
COMMENT ON TABLE graphitron_argmapping_pair IS 'One pair of a written argMapping, named by its mapping and the parameter it binds: one row per mapping and parameter. For example input.ids on @service at Query.filmsByPath is the pair (Query.filmsByPath, service, 0, service, ids).';
COMMENT ON COLUMN graphitron_argmapping_pair.graph_name IS 'the owning graph''s partition';
COMMENT ON COLUMN graphitron_argmapping_pair.coordinate IS 'the element the mapping''s application is on; with the directive, the ordinal and the owner, its graphitron_argmapping_site';
COMMENT ON COLUMN graphitron_argmapping_pair.directive_name IS 'the mapping''s directive';
COMMENT ON COLUMN graphitron_argmapping_pair.ordinal IS 'its application''s ordinal';
COMMENT ON COLUMN graphitron_argmapping_pair.owner IS 'what the mapping is written under in its application';
COMMENT ON COLUMN graphitron_argmapping_pair.parameter_name IS 'the parameter the pair binds, its left side, completing the key: a mapping names a parameter once, and of two naming one the first written is kept';
COMMENT ON COLUMN graphitron_argmapping_pair.bound_to IS 'the right-hand side as written, an argument path or a sigil';
COMMENT ON COLUMN graphitron_argmapping_pair.source_name IS 'the file the mapping string was written in; with the line, the column and the position, the pair''s entry, where a defect about it points';
COMMENT ON COLUMN graphitron_argmapping_pair.source_line IS 'source line of the mapping string';
COMMENT ON COLUMN graphitron_argmapping_pair.source_column IS 'source column of the mapping string';
COMMENT ON COLUMN graphitron_argmapping_pair.position IS 'the pair''s position in its mapping';
COMMENT ON COLUMN graphitron_argmapping_pair.touched_at IS 'the reading that last wrote this row; the sweep deletes the rows an older reading wrote';

CREATE VIEW graphitron_argmapping_call
  (graph_name, coordinate, directive_name, ordinal, owner, parameter_name, call_coordinate,
   call_name, call_kind, bound_to, segments, head, rest, source_name, source_line, source_column,
   position) AS
-- A @service, a @routine, a @condition or an @outbox, on a field, an argument or an input field,
-- written once and taken under every occurrence of what it is written on. A path names arguments and
-- input fields, or, after an @outbox's $result, the fields of what the call returns, the sigil taken
-- off; any other sigil binds something else, and a path element's mapping binds a table.
SELECT p.graph_name, p.coordinate, p.directive_name, p.ordinal, p.owner, p.parameter_name,
       c.coordinate, c.name, c.kind, p.bound_to,
       CHAR_LENGTH(p.path) - CHAR_LENGTH(REPLACE(p.path, '.', '')) + 1,
       REGEXP_REPLACE(p.path, '\..*$', ''),
       CASE WHEN POSITION('.', p.path) = 0 THEN ''
            ELSE SUBSTRING(p.path, POSITION('.', p.path) + 1) END,
       p.source_name, p.source_line, p.source_column, p.position
  FROM (SELECT q.graph_name, q.coordinate, q.directive_name, q.ordinal, q.owner, q.parameter_name,
               q.bound_to, q.source_name, q.source_line, q.source_column, q.position,
               REGEXP_REPLACE(q.bound_to, '^\$result\.', '') AS path
          FROM graphitron_argmapping_pair q) p
  JOIN graphitron_argmapping_site s
    ON s.graph_name = p.graph_name AND s.coordinate = p.coordinate
   AND s.directive_name = p.directive_name AND s.ordinal = p.ordinal AND s.owner = p.owner
  JOIN graphitron_occurrence c
    ON c.graph_name = s.graph_name AND c.element_coordinate = s.coordinate
 WHERE (p.bound_to NOT LIKE '$%'
        OR (s.directive_name = 'outbox' AND p.bound_to LIKE '$result.%'))
   AND s.directive_name IN ('service', 'routine', 'condition', 'outbox')
   AND s.kind = 'ROOT';
COMMENT ON VIEW graphitron_argmapping_call IS 'One written argMapping entry binding a parameter to an argument path, under one occurrence of the field, argument or input field its directive is written on. For example filter.minLength on @routine at Actor.filmsNested, under Actor.filmsNested.';
-- COMMENT ON COLUMN graphitron_argmapping_call.graph_name IS 'the owning graph''s partition';
-- COMMENT ON COLUMN graphitron_argmapping_call.coordinate IS 'the element the mapping''s application is on; with the directive, the ordinal, the owner and the parameter, the pair''s key';
-- COMMENT ON COLUMN graphitron_argmapping_call.directive_name IS 'the mapping''s directive';
-- COMMENT ON COLUMN graphitron_argmapping_call.ordinal IS 'its application''s ordinal';
-- COMMENT ON COLUMN graphitron_argmapping_call.owner IS 'what the mapping is written under';
-- COMMENT ON COLUMN graphitron_argmapping_call.parameter_name IS 'the parameter the pair binds';
-- COMMENT ON COLUMN graphitron_argmapping_call.source_name IS 'the file the mapping string was written in, where a defect about it points';
-- COMMENT ON COLUMN graphitron_argmapping_call.source_line IS 'source line of the mapping string';
-- COMMENT ON COLUMN graphitron_argmapping_call.source_column IS 'source column of the mapping string';
-- COMMENT ON COLUMN graphitron_argmapping_call.position IS 'the entry''s position in its mapping, where a defect about it points';
-- COMMENT ON COLUMN graphitron_argmapping_call.call_coordinate IS 'the occurrence the directive is written on that the path is taken under';
-- COMMENT ON COLUMN graphitron_argmapping_call.call_name IS 'that occurrence''s own name, which a path on an argument or an input field may begin with';
-- COMMENT ON COLUMN graphitron_argmapping_call.call_kind IS 'that occurrence''s kind: on a FIELD the head names an argument, otherwise an input field';
-- COMMENT ON COLUMN graphitron_argmapping_call.bound_to IS 'the right-hand side as written';
-- COMMENT ON COLUMN graphitron_argmapping_call.segments IS 'how many dot-separated names it has';
-- COMMENT ON COLUMN graphitron_argmapping_call.head IS 'its first name';
-- COMMENT ON COLUMN graphitron_argmapping_call.rest IS 'what follows the first name and its dot, empty where there is one name';

-- Each step a written argMapping path takes through the occurrences under its call, stored so a
-- graph's steps are taken over its own rows: a recursive view is evaluated whole, every graph's
-- paths with it, before a reader's graph reaches it.
CREATE TABLE graphitron_argmapping_step (
  graph_name       VARCHAR   NOT NULL,
  coordinate       VARCHAR   NOT NULL,
  directive_name   VARCHAR   NOT NULL,
  ordinal          INT       NOT NULL,
  owner            VARCHAR   NOT NULL,
  parameter_name   VARCHAR   NOT NULL,
  call_coordinate  VARCHAR   NOT NULL,
  consumed         INT       NOT NULL,
  bound_to         VARCHAR   NOT NULL,
  segments         INT       NOT NULL,
  rest             VARCHAR   NOT NULL,
  step_coordinate  VARCHAR   NOT NULL,
  repeats_own_name BOOLEAN   NOT NULL,
  touched_at       TIMESTAMP NOT NULL,
  PRIMARY KEY (graph_name, coordinate, directive_name, ordinal, owner, parameter_name,
               call_coordinate, consumed),
  -- The pair, so a step cannot outlive what an author wrote.
  FOREIGN KEY (graph_name, coordinate, directive_name, ordinal, owner, parameter_name)
    REFERENCES graphitron_argmapping_pair (graph_name, coordinate, directive_name, ordinal, owner, parameter_name)
    ON DELETE CASCADE,
  -- The call's occurrence and the step's, so a place the corpus no longer reaches takes its rows.
  FOREIGN KEY (graph_name, call_coordinate)
    REFERENCES graphitron_occurrence (graph_name, coordinate) ON DELETE CASCADE,
  FOREIGN KEY (graph_name, step_coordinate)
    REFERENCES graphitron_occurrence (graph_name, coordinate) ON DELETE CASCADE,
  CHECK (consumed BETWEEN 1 AND segments)
);
COMMENT ON TABLE graphitron_argmapping_step IS 'One segment a written argMapping path consumes under one occurrence of its call, and the occurrence it reaches. For example filter.minLength on @routine at Actor.filmsNested reaches Actor.filmsNested(filter:) at 1 and Actor.filmsNested(filter.minLength:) at 2.';
COMMENT ON COLUMN graphitron_argmapping_step.graph_name IS 'the owning graph''s partition';
COMMENT ON COLUMN graphitron_argmapping_step.coordinate IS 'the element the mapping''s application is on; with the directive, the ordinal, the owner and the parameter, its graphitron_argmapping_pair';
COMMENT ON COLUMN graphitron_argmapping_step.directive_name IS 'the mapping''s directive';
COMMENT ON COLUMN graphitron_argmapping_step.ordinal IS 'its application''s ordinal';
COMMENT ON COLUMN graphitron_argmapping_step.owner IS 'what the mapping is written under in its application';
COMMENT ON COLUMN graphitron_argmapping_step.parameter_name IS 'the parameter the pair binds, completing the pair''s key';
COMMENT ON COLUMN graphitron_argmapping_step.call_coordinate IS 'the occurrence of the field, argument or input field the directive is written on that this path is taken under';
COMMENT ON COLUMN graphitron_argmapping_step.consumed IS 'how many names this step has consumed, 1 at the head, completing the key: each name reaches one occurrence under the one before, so one entry and call have one step per count';
COMMENT ON COLUMN graphitron_argmapping_step.bound_to IS 'the right-hand side as written';
COMMENT ON COLUMN graphitron_argmapping_step.segments IS 'how many dot-separated names it has';
COMMENT ON COLUMN graphitron_argmapping_step.rest IS 'the names not yet consumed, dot-separated, empty where every name is';
COMMENT ON COLUMN graphitron_argmapping_step.step_coordinate IS 'the occurrence the consumed names reach';
COMMENT ON COLUMN graphitron_argmapping_step.repeats_own_name IS 'whether the head was the call''s own name rather than something it opens into';
COMMENT ON COLUMN graphitron_argmapping_step.touched_at IS 'the reading that last wrote this row; the next step reads only this reading''s, and the sweep deletes the rows an older reading wrote';

-- The head. On a field it names one of the field's arguments; on an argument or an input field it
-- names a field of what that opens into, or the call's own name, which the coordinate's own name
-- wins where an input field shares it.
CREATE VIEW graphitron_argmapping_step_head_rule
  (graph_name, coordinate, directive_name, ordinal, owner, parameter_name, call_coordinate,
   consumed,
   bound_to, segments, rest, step_coordinate, repeats_own_name) AS
SELECT e.graph_name, e.coordinate, e.directive_name, e.ordinal, e.owner, e.parameter_name,
       e.call_coordinate,
       1, e.bound_to, e.segments, e.rest, o.coordinate, FALSE
  FROM graphitron_argmapping_call e
  JOIN graphitron_occurrence o
    ON o.graph_name = e.graph_name AND o.parent_coordinate = e.call_coordinate AND o.name = e.head
 WHERE e.bound_to NOT LIKE '$result.%'
   AND ((e.call_kind = 'FIELD' AND o.kind = 'FIELD_ARGUMENT')
        OR (e.call_kind <> 'FIELD' AND o.kind = 'INPUT_FIELD' AND e.head <> e.call_name))
UNION ALL
-- A $result path's head is a field of what the call returns: the field under the call, or, where the
-- type it returns is bound to a table and so starts chains of its own, that type's field.
SELECT e.graph_name, e.coordinate, e.directive_name, e.ordinal, e.owner, e.parameter_name,
       e.call_coordinate,
       1, e.bound_to, e.segments, e.rest, o.coordinate, FALSE
  FROM graphitron_argmapping_call e
  JOIN graphitron_occurrence o
    ON o.graph_name = e.graph_name AND o.parent_coordinate = e.call_coordinate AND o.name = e.head
   AND o.kind = 'FIELD'
 WHERE e.call_kind = 'FIELD' AND e.bound_to LIKE '$result.%'
UNION ALL
SELECT e.graph_name, e.coordinate, e.directive_name, e.ordinal, e.owner, e.parameter_name,
       e.call_coordinate,
       1, e.bound_to, e.segments, e.rest, o.coordinate, FALSE
  FROM graphitron_argmapping_call e
  JOIN graphitron_field cf ON cf.graph_name = e.graph_name AND cf.coordinate = e.coordinate
  JOIN graphitron_field_target ct
    ON ct.graph_name = cf.graph_name AND ct.type_name = cf.type_name AND ct.field_name = cf.field_name
  JOIN graphitron_occurrence o
    ON o.graph_name = e.graph_name AND o.element_coordinate = ct.target_type_name || '.' || e.head
   AND o.parent_coordinate IS NULL AND o.kind = 'FIELD'
 WHERE e.call_kind = 'FIELD' AND e.bound_to LIKE '$result.%'
UNION ALL
SELECT e.graph_name, e.coordinate, e.directive_name, e.ordinal, e.owner, e.parameter_name,
       e.call_coordinate,
       1, e.bound_to, e.segments, e.rest, e.call_coordinate, TRUE
  FROM graphitron_argmapping_call e
 WHERE e.call_kind <> 'FIELD' AND e.head = e.call_name;
COMMENT ON VIEW graphitron_argmapping_step_head_rule IS 'One head step the argMapping step rule computes, in the shape graphitron_argmapping_step stores: the rule itself, evaluated on demand rather than read off disk. For example the graphitron assembly inserts this view''s rows for one graph into graphitron_argmapping_step at 1, before the next steps.';
-- COMMENT ON COLUMN graphitron_argmapping_step_head_rule.graph_name IS 'the owning graph''s partition';
-- COMMENT ON COLUMN graphitron_argmapping_step_head_rule.coordinate IS 'the pair''s coordinate';
-- COMMENT ON COLUMN graphitron_argmapping_step_head_rule.directive_name IS 'the pair''s directive_name';
-- COMMENT ON COLUMN graphitron_argmapping_step_head_rule.ordinal IS 'the pair''s ordinal';
-- COMMENT ON COLUMN graphitron_argmapping_step_head_rule.owner IS 'the pair''s owner';
-- COMMENT ON COLUMN graphitron_argmapping_step_head_rule.parameter_name IS 'the pair''s parameter_name';
-- COMMENT ON COLUMN graphitron_argmapping_step_head_rule.call_coordinate IS 'the call occurrence the path is taken under';
-- COMMENT ON COLUMN graphitron_argmapping_step_head_rule.consumed IS 'always 1';
-- COMMENT ON COLUMN graphitron_argmapping_step_head_rule.bound_to IS 'the right-hand side as written';
-- COMMENT ON COLUMN graphitron_argmapping_step_head_rule.segments IS 'how many dot-separated names it has';
-- COMMENT ON COLUMN graphitron_argmapping_step_head_rule.rest IS 'the names after the head';
-- COMMENT ON COLUMN graphitron_argmapping_step_head_rule.step_coordinate IS 'the occurrence the head reaches';
-- COMMENT ON COLUMN graphitron_argmapping_step_head_rule.repeats_own_name IS 'whether the head was the call''s own name';

-- Every later segment names an input field of what the step before reached: one step down from the
-- stored steps, with what the writer needs to take only this reading's at one count.
CREATE VIEW graphitron_argmapping_step_next_rule
  (graph_name, coordinate, directive_name, ordinal, owner, parameter_name, call_coordinate,
   consumed,
   bound_to, segments, rest, step_coordinate, repeats_own_name, from_consumed, from_touched_at) AS
SELECT s.graph_name, s.coordinate, s.directive_name, s.ordinal, s.owner, s.parameter_name,
       s.call_coordinate,
       s.consumed + 1, s.bound_to, s.segments,
       CASE WHEN POSITION('.', s.rest) = 0 THEN ''
            ELSE SUBSTRING(s.rest, POSITION('.', s.rest) + 1) END,
       o.coordinate, s.repeats_own_name, s.consumed, s.touched_at
  FROM graphitron_argmapping_step s
  JOIN graphitron_occurrence o
    ON o.graph_name = s.graph_name AND o.parent_coordinate = s.step_coordinate
   AND o.name = REGEXP_REPLACE(s.rest, '\..*$', '') AND o.kind = 'INPUT_FIELD'
 WHERE s.consumed < s.segments
UNION ALL
-- After a $result head, each name is a field of what the field before returns, found as the head is.
SELECT s.graph_name, s.coordinate, s.directive_name, s.ordinal, s.owner, s.parameter_name,
       s.call_coordinate,
       s.consumed + 1, s.bound_to, s.segments,
       CASE WHEN POSITION('.', s.rest) = 0 THEN ''
            ELSE SUBSTRING(s.rest, POSITION('.', s.rest) + 1) END,
       o.coordinate, s.repeats_own_name, s.consumed, s.touched_at
  FROM graphitron_argmapping_step s
  JOIN graphitron_occurrence o
    ON o.graph_name = s.graph_name AND o.parent_coordinate = s.step_coordinate
   AND o.name = REGEXP_REPLACE(s.rest, '\..*$', '') AND o.kind = 'FIELD'
 WHERE s.consumed < s.segments AND s.bound_to LIKE '$result.%'
UNION ALL
SELECT s.graph_name, s.coordinate, s.directive_name, s.ordinal, s.owner, s.parameter_name,
       s.call_coordinate,
       s.consumed + 1, s.bound_to, s.segments,
       CASE WHEN POSITION('.', s.rest) = 0 THEN ''
            ELSE SUBSTRING(s.rest, POSITION('.', s.rest) + 1) END,
       o.coordinate, s.repeats_own_name, s.consumed, s.touched_at
  FROM graphitron_argmapping_step s
  JOIN graphitron_occurrence so ON so.graph_name = s.graph_name AND so.coordinate = s.step_coordinate
  JOIN graphitron_field sf ON sf.graph_name = so.graph_name AND sf.coordinate = so.element_coordinate
  JOIN graphitron_field_target st
    ON st.graph_name = sf.graph_name AND st.type_name = sf.type_name AND st.field_name = sf.field_name
  JOIN graphitron_occurrence o
    ON o.graph_name = s.graph_name
   AND o.element_coordinate = st.target_type_name || '.' || REGEXP_REPLACE(s.rest, '\..*$', '')
   AND o.parent_coordinate IS NULL AND o.kind = 'FIELD'
 WHERE s.consumed < s.segments AND s.bound_to LIKE '$result.%';
COMMENT ON VIEW graphitron_argmapping_step_next_rule IS 'One next step the argMapping step rule computes from a stored step, in the shape graphitron_argmapping_step stores: the rule itself, evaluated on demand rather than read off disk. For example the graphitron assembly inserts this view''s rows for one graph and one count into graphitron_argmapping_step, a count at a time.';
-- COMMENT ON COLUMN graphitron_argmapping_step_next_rule.graph_name IS 'the owning graph''s partition';
-- COMMENT ON COLUMN graphitron_argmapping_step_next_rule.coordinate IS 'the pair''s coordinate';
-- COMMENT ON COLUMN graphitron_argmapping_step_next_rule.directive_name IS 'the pair''s directive_name';
-- COMMENT ON COLUMN graphitron_argmapping_step_next_rule.ordinal IS 'the pair''s ordinal';
-- COMMENT ON COLUMN graphitron_argmapping_step_next_rule.owner IS 'the pair''s owner';
-- COMMENT ON COLUMN graphitron_argmapping_step_next_rule.parameter_name IS 'the pair''s parameter_name';
-- COMMENT ON COLUMN graphitron_argmapping_step_next_rule.call_coordinate IS 'the call occurrence the path is taken under';
-- COMMENT ON COLUMN graphitron_argmapping_step_next_rule.consumed IS 'the names consumed with this step';
-- COMMENT ON COLUMN graphitron_argmapping_step_next_rule.bound_to IS 'the right-hand side as written';
-- COMMENT ON COLUMN graphitron_argmapping_step_next_rule.segments IS 'how many dot-separated names it has';
-- COMMENT ON COLUMN graphitron_argmapping_step_next_rule.rest IS 'the names not yet consumed';
-- COMMENT ON COLUMN graphitron_argmapping_step_next_rule.step_coordinate IS 'the occurrence this step reaches';
-- COMMENT ON COLUMN graphitron_argmapping_step_next_rule.repeats_own_name IS 'carried from the head';
-- COMMENT ON COLUMN graphitron_argmapping_step_next_rule.from_consumed IS 'the count of the stored step this one follows, which the writer pins';
-- COMMENT ON COLUMN graphitron_argmapping_step_next_rule.from_touched_at IS 'the instant of the stored step this one follows, which the writer pins to this reading';

CREATE VIEW graphitron_argmapping_landing_rule
  (graph_name, coordinate, directive_name, ordinal, owner, parameter_name, call_coordinate,
   landing_coordinate, trailing_name, repeats_own_name, descends, receives) AS
-- Where the path stops: every name consumed, or every name but one, which then names a key column of
-- a node id at the occurrence reached and is the path end's to resolve.
SELECT s.graph_name, s.coordinate, s.directive_name, s.ordinal, s.owner, s.parameter_name,
       s.call_coordinate,
       s.step_coordinate,
       CASE WHEN s.consumed = s.segments THEN CAST(NULL AS VARCHAR) ELSE s.rest END,
       s.repeats_own_name,
       -- Past the slot the path opens: a field's argument, or the argument or input field the
       -- directive is written on.
       CASE WHEN co.kind = 'FIELD' THEN lo.parent_coordinate IS DISTINCT FROM co.coordinate
            ELSE lo.coordinate <> co.coordinate END,
       -- What a node id at the landing hands over. A key column named past it is that column. A
       -- payload key otherwise takes the id whole, as the API's clients see it; a call parameter
       -- reached by descending onto it takes a key column, one stopping on its slot the whole key.
       CASE WHEN s.consumed < s.segments THEN 'COLUMN'
            WHEN s.directive_name = 'outbox' THEN 'WHOLE'
            WHEN CASE WHEN co.kind = 'FIELD' THEN lo.parent_coordinate IS DISTINCT FROM co.coordinate
                      ELSE lo.coordinate <> co.coordinate END THEN 'COLUMN'
            ELSE 'WHOLE' END
  FROM graphitron_argmapping_step s
  JOIN graphitron_occurrence co ON co.graph_name = s.graph_name AND co.coordinate = s.call_coordinate
  JOIN graphitron_occurrence lo ON lo.graph_name = s.graph_name AND lo.coordinate = s.step_coordinate
 WHERE s.consumed >= s.segments - 1
   AND NOT EXISTS (SELECT 1 FROM graphitron_argmapping_step d
                    WHERE d.graph_name = s.graph_name AND d.coordinate = s.coordinate
                      AND d.directive_name = s.directive_name AND d.ordinal = s.ordinal
                      AND d.owner = s.owner AND d.parameter_name = s.parameter_name
                      AND d.call_coordinate = s.call_coordinate
                      AND d.consumed > s.consumed);
COMMENT ON VIEW graphitron_argmapping_landing_rule IS 'One row the argMapping landing rule computes, in the shape graphitron_argmapping_landing stores: the rule itself, evaluated on demand rather than read off disk. For example the graphitron assembly inserts this view''s rows for one graph into graphitron_argmapping_landing, which is the name every reader spells.';
-- COMMENT ON COLUMN graphitron_argmapping_landing_rule.descends IS 'the descends of a row of this rule, which the stage writes into graphitron_argmapping_landing.descends';
-- COMMENT ON COLUMN graphitron_argmapping_landing_rule.graph_name IS 'the graph_name of a row of this rule, which the stage writes into graphitron_argmapping_landing.graph_name';
-- COMMENT ON COLUMN graphitron_argmapping_landing_rule.coordinate IS 'the pair''s coordinate';
-- COMMENT ON COLUMN graphitron_argmapping_landing_rule.directive_name IS 'the pair''s directive_name';
-- COMMENT ON COLUMN graphitron_argmapping_landing_rule.ordinal IS 'the pair''s ordinal';
-- COMMENT ON COLUMN graphitron_argmapping_landing_rule.owner IS 'the pair''s owner';
-- COMMENT ON COLUMN graphitron_argmapping_landing_rule.parameter_name IS 'the pair''s parameter_name';
-- COMMENT ON COLUMN graphitron_argmapping_landing_rule.call_coordinate IS 'the call_coordinate of a row of this rule, which the stage writes into graphitron_argmapping_landing.call_coordinate';
-- COMMENT ON COLUMN graphitron_argmapping_landing_rule.landing_coordinate IS 'the landing_coordinate of a row of this rule, which the stage writes into graphitron_argmapping_landing.landing_coordinate';
-- COMMENT ON COLUMN graphitron_argmapping_landing_rule.trailing_name IS 'the trailing_name of a row of this rule, which the stage writes into graphitron_argmapping_landing.trailing_name';
-- COMMENT ON COLUMN graphitron_argmapping_landing_rule.repeats_own_name IS 'the repeats_own_name of a row of this rule, which the stage writes into graphitron_argmapping_landing.repeats_own_name';
-- COMMENT ON COLUMN graphitron_argmapping_landing_rule.receives IS 'the receives of a row of this rule, which the stage writes into graphitron_argmapping_landing.receives';

CREATE TABLE graphitron_argmapping_landing (
  graph_name         VARCHAR   NOT NULL,
  coordinate         VARCHAR   NOT NULL,
  directive_name     VARCHAR   NOT NULL,
  ordinal            INT       NOT NULL,
  owner              VARCHAR   NOT NULL,
  parameter_name     VARCHAR   NOT NULL,
  call_coordinate    VARCHAR   NOT NULL,
  landing_coordinate VARCHAR   NOT NULL,
  trailing_name      VARCHAR,
  repeats_own_name   BOOLEAN   NOT NULL,
  descends           BOOLEAN   NOT NULL,
  receives           VARCHAR   NOT NULL,
  touched_at         TIMESTAMP NOT NULL,
  PRIMARY KEY (graph_name, coordinate, directive_name, ordinal, owner, parameter_name,
               call_coordinate),
  CHECK (receives IN ('WHOLE', 'COLUMN')),
  -- The pair, so a landing cannot outlive what an author wrote.
  FOREIGN KEY (graph_name, coordinate, directive_name, ordinal, owner, parameter_name)
    REFERENCES graphitron_argmapping_pair (graph_name, coordinate, directive_name, ordinal, owner, parameter_name)
    ON DELETE CASCADE,
  -- The call's occurrence and the landing's, so a place the corpus no longer reaches takes its rows.
  FOREIGN KEY (graph_name, call_coordinate)
    REFERENCES graphitron_occurrence (graph_name, coordinate) ON DELETE CASCADE,
  FOREIGN KEY (graph_name, landing_coordinate)
    REFERENCES graphitron_occurrence (graph_name, coordinate) ON DELETE CASCADE
);
COMMENT ON TABLE graphitron_argmapping_landing IS 'Where one written argMapping entry''s argument path lands under one occurrence of its call: one row per entry and call occurrence whose path resolves. For example input.ids on @service at Query.filmsByPath lands on Query.filmsByPath(input.ids:).';
COMMENT ON COLUMN graphitron_argmapping_landing.graph_name IS 'the owning graph''s partition';
COMMENT ON COLUMN graphitron_argmapping_landing.coordinate IS 'the element the mapping''s application is on; with the directive, the ordinal, the owner and the parameter, its graphitron_argmapping_pair';
COMMENT ON COLUMN graphitron_argmapping_landing.directive_name IS 'the mapping''s directive';
COMMENT ON COLUMN graphitron_argmapping_landing.ordinal IS 'its application''s ordinal';
COMMENT ON COLUMN graphitron_argmapping_landing.owner IS 'what the mapping is written under in its application';
COMMENT ON COLUMN graphitron_argmapping_landing.parameter_name IS 'the parameter the pair binds, completing the pair''s key';
COMMENT ON COLUMN graphitron_argmapping_landing.call_coordinate IS 'the occurrence of the field, argument or input field the directive is written on, completing the key: a field of a nested type is reached once per parent, and the path resolves under each';
COMMENT ON COLUMN graphitron_argmapping_landing.landing_coordinate IS 'the argument or input-field occurrence the path names; what it is, its column, table or node identity, is that occurrence''s own binding, not restated here';
COMMENT ON COLUMN graphitron_argmapping_landing.trailing_name IS 'the path''s last name where it names nothing under the landing, NULL where every name was consumed: a key column of the node id the landing carries, which the landing''s binding resolves and judges';
COMMENT ON COLUMN graphitron_argmapping_landing.descends IS 'whether the path goes past the slot it opens, an argument of a field-level call or the argument or input field the directive is written on, rather than stopping on it';
COMMENT ON COLUMN graphitron_argmapping_landing.receives IS 'what a node id at the landing hands over: COLUMN, one key column, where the path names one past the id or, at a call parameter, descends onto it; WHOLE otherwise, the decoded key at a call parameter and the encoded id at an @outbox payload key, whose clients see the id as the API does';
COMMENT ON COLUMN graphitron_argmapping_landing.repeats_own_name IS 'whether the path began with the call''s own name, as an argument-level or input-field-level argMapping was once required to: a spelling that still resolves';
COMMENT ON COLUMN graphitron_argmapping_landing.touched_at IS 'the reading that last wrote this row; the sweep deletes the rows an older reading wrote';
CREATE INDEX graphitron_argmapping_landing_landing_ix
  ON graphitron_argmapping_landing (graph_name, landing_coordinate);
COMMENT ON INDEX graphitron_argmapping_landing_landing_ix IS 'A reader holding an occurrence asks whether an argMapping entry hands it to a call, by the occurrence''s coordinate, and the primary key, led by the entry, serves none of that.';

CREATE TABLE graphitron_fetcher (
  graph_name VARCHAR   NOT NULL,
  type_name  VARCHAR   NOT NULL,
  field_name VARCHAR   NOT NULL,
  side       VARCHAR   NOT NULL,
  touched_at TIMESTAMP NOT NULL,
  PRIMARY KEY (graph_name, type_name, field_name),
  UNIQUE (graph_name, type_name, field_name, side),
  FOREIGN KEY (graph_name, type_name, field_name)
    REFERENCES graphitron_field (graph_name, type_name, field_name) ON DELETE CASCADE,
  CHECK (side IN ('PRODUCER', 'READER'))
);
COMMENT ON TABLE graphitron_fetcher IS 'An output field''s fetcher, and whether it produces a result or reads one: one row per field. For example Query.films selects and so produces, and Film.title reads a column of the row its parent produced.';
COMMENT ON COLUMN graphitron_fetcher.graph_name IS 'the owning graph''s partition; the leading key dimension that keeps one workspace''s graphs apart';
COMMENT ON COLUMN graphitron_fetcher.type_name IS 'the object type declaring the field';
COMMENT ON COLUMN graphitron_fetcher.field_name IS 'the field; with the type, a graphitron_field key';
COMMENT ON COLUMN graphitron_fetcher.side IS 'PRODUCER where resolving the field runs something, READER where it reads from a result another fetcher produced. The subtype tables key to it with the side pinned, so a field is stated on one side only';
COMMENT ON COLUMN graphitron_fetcher.touched_at IS 'the reading that last wrote this row; the sweep deletes the rows an older reading wrote, which are the fields that stopped being fetched';

CREATE TABLE graphitron_producer (
  graph_name VARCHAR   NOT NULL,
  type_name  VARCHAR   NOT NULL,
  field_name VARCHAR   NOT NULL,
  side       VARCHAR   NOT NULL,
  kind       VARCHAR   NOT NULL,
  touched_at TIMESTAMP NOT NULL,
  PRIMARY KEY (graph_name, type_name, field_name),
  UNIQUE (graph_name, type_name, field_name, kind),
  FOREIGN KEY (graph_name, type_name, field_name, side)
    REFERENCES graphitron_fetcher (graph_name, type_name, field_name, side) ON DELETE CASCADE,
  CHECK (side = 'PRODUCER'),
  CHECK (kind IN ('SELECT', 'LOOKUP', 'COUNT', 'FACETS', 'INSERT', 'UPDATE', 'DELETE',
                  'ROUTINE', 'SERVICE'))
);
COMMENT ON TABLE graphitron_producer IS 'A field whose fetcher runs something, and what kind of thing it runs: one row per field. For example Query.films with nothing written is a SELECT, Mutation.addFilm @mutation(typeName: INSERT) an INSERT, and the totalCount of the connection a field returns a COUNT over that field''s statement.';
COMMENT ON COLUMN graphitron_producer.graph_name IS 'the owning graph''s partition; the leading key dimension that keeps one workspace''s graphs apart';
COMMENT ON COLUMN graphitron_producer.type_name IS 'the object type declaring the field';
COMMENT ON COLUMN graphitron_producer.field_name IS 'the field; with the type, a graphitron_fetcher key';
COMMENT ON COLUMN graphitron_producer.side IS 'always PRODUCER, carried so the foreign key into graphitron_fetcher holds the side as well as the field';
COMMENT ON COLUMN graphitron_producer.kind IS 'what the fetcher runs. SELECT, the rows a condition matches; LOOKUP, the rows for an ordered list of keys; COUNT and FACETS, aggregates over the statement of the producer whose connection they sit on; INSERT, UPDATE and DELETE, a write; ROUTINE, SQL around a database routine; SERVICE, a Java method. Neither the root the field sits on nor the type it produces is a column: the first is a join to graphql_root_operation and the second is graphitron_field_target';
COMMENT ON COLUMN graphitron_producer.touched_at IS 'the reading that last wrote this row; the sweep deletes the rows an older reading wrote';

-- The kinds an element can claim, by the family a reader picks among them in.
CREATE TABLE graphitron_claim_kind (
  kind   VARCHAR NOT NULL,
  family VARCHAR NOT NULL,
  PRIMARY KEY (kind),
  CHECK (family IN ('PRODUCER', 'BINDING', 'TYPE'))
);
COMMENT ON TABLE graphitron_claim_kind IS 'One kind of thing an element can claim, with the family it belongs to. For example SERVICE is a PRODUCER kind and NODE_ID a BINDING kind.';
COMMENT ON COLUMN graphitron_claim_kind.kind IS 'the kind claimed, and the whole key; unique across families, so a claim''s kind names its family alone';
COMMENT ON COLUMN graphitron_claim_kind.family IS 'which question the kind answers: PRODUCER, what a field runs, BINDING, what an occurrence of the element takes, or TYPE, what a type stands for. A reader picks among the claims of one family at one element; kinds of different families answer different questions';

-- Which pairs of claims may stand at one element. Any two claims at one element conflict unless a
-- row here admits the pair, or names the defect the pair is reported under instead.
CREATE TABLE graphitron_claim_inclusion (
  kind_a VARCHAR NOT NULL,
  kind_b VARCHAR NOT NULL,
  code   VARCHAR,
  PRIMARY KEY (kind_a, kind_b),
  FOREIGN KEY (kind_a) REFERENCES graphitron_claim_kind (kind),
  FOREIGN KEY (kind_b) REFERENCES graphitron_claim_kind (kind),
  -- A pair is stated once, its two kinds in order.
  CHECK (kind_a < kind_b)
);
COMMENT ON TABLE graphitron_claim_inclusion IS 'One pair of claims that may stand at one element, or the defect the pair is reported under instead of a conflict. For example LOOKUP with ROUTINE is reported as ROUTINE_LOOKUP_DEFERRED, a combination graphitron does not generate yet.';
COMMENT ON COLUMN graphitron_claim_inclusion.kind_a IS 'the pair''s first kind, the lesser of the two';
COMMENT ON COLUMN graphitron_claim_inclusion.kind_b IS 'the pair''s second kind';
COMMENT ON COLUMN graphitron_claim_inclusion.code IS 'the defect the pair is reported under instead of CLAIMS_CONFLICT; null where the two may stand together without a defect';

-- Every claim an element makes, by any stage, before any reader decides between them.
CREATE TABLE graphitron_claim (
  graph_name             VARCHAR   NOT NULL,
  coordinate             VARCHAR   NOT NULL,
  kind                   VARCHAR   NOT NULL,
  claimer                VARCHAR   NOT NULL,
  priority               INT       NOT NULL,
  stage                  VARCHAR   NOT NULL,
  source_name            VARCHAR,
  source_line            INT,
  source_column          INT,
  touched_at             TIMESTAMP NOT NULL,
  element_graph_ref      VARCHAR,
  element_coordinate_ref VARCHAR,
  PRIMARY KEY (graph_name, coordinate, kind, claimer),
  FOREIGN KEY (graph_name) REFERENCES store_graph (graph_name),
  FOREIGN KEY (kind) REFERENCES graphitron_claim_kind (kind),
  -- The claiming element through the claim's own copy of its key: a key to what a claim was built
  -- from does not cascade, and the sweep removes the row the reading no longer finds.
  FOREIGN KEY (element_graph_ref, element_coordinate_ref)
    REFERENCES graphitron_element (graph_name, coordinate) ON DELETE SET NULL,
  CHECK (element_graph_ref IS NULL OR element_graph_ref = graph_name),
  CHECK (element_coordinate_ref IS NULL OR element_coordinate_ref = coordinate),
  CHECK (priority >= 0),
  -- A position is all three or none: an application nobody wrote has none.
  CHECK ((source_name IS NULL) = (source_line IS NULL)
     AND (source_line IS NULL) = (source_column IS NULL))
);
COMMENT ON TABLE graphitron_claim IS 'One claim an element makes, by the element whose fact implies it: one row per element, kind and claimer. For example Query.filmsByKeys with @lookupKey on two arguments has two LOOKUP rows, one claimed by each argument, and a field carrying both @service and @routine has a SERVICE and a ROUTINE row.';
COMMENT ON COLUMN graphitron_claim.graph_name IS 'the owning graph''s partition, anchored by store_graph';
COMMENT ON COLUMN graphitron_claim.coordinate IS 'the declared element claimed for, as graphitron_element spells it: Query.films, FilmInput.title or Query.films(title:). A declaration and not an occurrence, a claim being made once where the element is declared';
COMMENT ON COLUMN graphitron_claim.kind IS 'what is claimed, a graphitron_claim_kind; with the element the key, so another spelling of the same claim changes no row';
COMMENT ON COLUMN graphitron_claim.claimer IS 'the element whose fact implies the claim: the element itself for a claim written on it, the argument for a @lookupKey, which claims its field';
COMMENT ON COLUMN graphitron_claim.priority IS 'how strong the claim is, claimed by the stage that writes it: 0 for a claim an author wrote, an inference at the strength its stage claims, a lower number stronger. The relation decides nothing; each reader picks its own winner from the claims and their priorities';
COMMENT ON COLUMN graphitron_claim.stage IS 'the stage that wrote the claim, by its class''s simple name: ProducerClaims, BindingClaims or TypeClaims. Each stage sweeps only its own claims';
COMMENT ON COLUMN graphitron_claim.source_name IS 'the file the claim was written in; null for a claim nobody wrote';
COMMENT ON COLUMN graphitron_claim.source_line IS 'the claim''s source line, 1-based';
COMMENT ON COLUMN graphitron_claim.source_column IS 'the claim''s source column: where the application claiming the kind was written. The first written of two one claimer makes of one kind is kept. An attribute and not a reference, for a defect to point at';
COMMENT ON COLUMN graphitron_claim.touched_at IS 'when the reading that last stated this claim ran: the mark the sweep reads';
COMMENT ON COLUMN graphitron_claim.element_graph_ref IS 'the graph half of the element''s key, nullable so the element''s removal sets the reference null rather than cascading';
COMMENT ON COLUMN graphitron_claim.element_coordinate_ref IS 'the coordinate half of the element''s key, equal to coordinate while the element stands';

-- What a field claims it runs: the producer family of the claims, one row per claim. A field with
-- one kind is a producer of that kind, and a field with two is the defect; a reader counts kinds,
-- two arguments' @lookupKey being one kind claimed twice.
CREATE VIEW graphitron_producer_claim (graph_name, coordinate, kind, claimer, source_name,
                                       source_line, source_column) AS
SELECT c.graph_name, c.coordinate, c.kind, c.claimer, c.source_name, c.source_line, c.source_column
  FROM graphitron_claim c
  JOIN graphitron_claim_kind k ON k.kind = c.kind AND k.family = 'PRODUCER';
COMMENT ON VIEW graphitron_producer_claim IS 'One producer claim a field has: one row per field, kind and claimer. For example a field carrying both @service and @routine has two rows of two kinds, which is the conflict the entry defects report, and a field claiming nothing has none.';
-- COMMENT ON COLUMN graphitron_producer_claim.graph_name IS 'the owning graph''s partition';
-- COMMENT ON COLUMN graphitron_producer_claim.coordinate IS 'the declared field claimed';
-- COMMENT ON COLUMN graphitron_producer_claim.kind IS 'the producer kind claimed: SERVICE, ROUTINE, INSERT, UPDATE, DELETE, UPSERT, WRITE or LOOKUP, a graphitron_producer kind but for UPSERT, a write graphitron does not generate yet, which is refused at its entry, and WRITE, a @mutation whose verb the decode could not read; neither is a producer, and both still conflict with any other claim';
-- COMMENT ON COLUMN graphitron_producer_claim.claimer IS 'the field, or the argument for a LOOKUP';
-- COMMENT ON COLUMN graphitron_producer_claim.source_name IS 'the file the claim was written in';
-- COMMENT ON COLUMN graphitron_producer_claim.source_line IS 'its line';
-- COMMENT ON COLUMN graphitron_producer_claim.source_column IS 'its column';

-- What each field's written directives claim it runs, an application at a time, the first written
-- of two one claimer makes of one kind kept.
CREATE VIEW graphitron_producer_claim_rule (graph_name, coordinate, kind, claimer, source_name,
                                            source_line, source_column, element_graph_ref,
                                            element_coordinate_ref) AS
WITH claimed (graph_name, coordinate, kind, claimer, source_name, source_line, source_column) AS (
-- @service, wherever it is written.
SELECT f.graph_name, f.coordinate, 'SERVICE', f.coordinate, da.source_name, da.source_line,
       da.source_column
  FROM graphitron_field f
  JOIN graphitron_directive_application da
    ON da.graph_name = f.graph_name AND da.coordinate = f.coordinate
   AND da.directive_name = 'service'
UNION ALL
-- @routine on a query or mutation root field, or on a child @splitQuery takes out of its parent's
-- statement. Below a root and not split, a routine is a lateral in the parent's statement, which
-- the field reads.
SELECT f.graph_name, f.coordinate, 'ROUTINE', f.coordinate, da.source_name, da.source_line,
       da.source_column
  FROM graphitron_field f
  JOIN graphitron_directive_application da
    ON da.graph_name = f.graph_name AND da.coordinate = f.coordinate
   AND da.directive_name = 'routine'
 WHERE EXISTS (SELECT 1 FROM graphql_root_operation ro
                WHERE ro.graph_name = f.graph_name AND ro.type_name = f.type_name
                  AND ro.operation IN ('QUERY', 'MUTATION'))
    OR EXISTS (SELECT 1 FROM graphitron_directive_application s
                WHERE s.graph_name = f.graph_name AND s.coordinate = f.coordinate
                  AND s.directive_name = 'splitQuery')
UNION ALL
-- @mutation on a mutation-root field, by the verb written: graphitron generates the write, so it
-- conflicts with a @service, whose author provides the code, whichever verb is written. A verb the
-- decode could not read is a WRITE, the generated write all the same.
SELECT f.graph_name, f.coordinate,
       CASE WHEN m.operation IN ('INSERT', 'UPDATE', 'DELETE', 'UPSERT') THEN m.operation
            ELSE 'WRITE' END,
       f.coordinate, da.source_name, da.source_line, da.source_column
  FROM graphitron_field f
  JOIN graphql_root_operation ro
    ON ro.graph_name = f.graph_name AND ro.type_name = f.type_name AND ro.operation = 'MUTATION'
  JOIN graphitron_directive_application da
    ON da.graph_name = f.graph_name AND da.coordinate = f.coordinate
   AND da.directive_name = 'mutation'
  LEFT JOIN graphitron_ast_mutation_entry m
    ON m.graph_name = da.graph_name AND m.source_name = da.source_name
   AND m.source_line = da.source_line AND m.source_column = da.source_column
UNION ALL
-- @lookupKey on an argument, at the query root or on a split child, where the argument's
-- application was written; inline below a root, the keys narrow the parent's statement and the
-- field reads.
SELECT f.graph_name, f.coordinate, 'LOOKUP', a.coordinate, da.source_name, da.source_line,
       da.source_column
  FROM graphitron_field f
  JOIN graphitron_argument a
    ON a.graph_name = f.graph_name AND a.type_name = f.type_name AND a.field_name = f.field_name
  JOIN graphitron_directive_application da
    ON da.graph_name = a.graph_name AND da.coordinate = a.coordinate
   AND da.directive_name = 'lookupKey'
 WHERE EXISTS (SELECT 1 FROM graphql_root_operation ro
                WHERE ro.graph_name = f.graph_name AND ro.type_name = f.type_name
                  AND ro.operation = 'QUERY')
    OR EXISTS (SELECT 1 FROM graphitron_directive_application s
                WHERE s.graph_name = f.graph_name AND s.coordinate = f.coordinate
                  AND s.directive_name = 'splitQuery')
)
SELECT graph_name, coordinate, kind, claimer, source_name, source_line, source_column, graph_name,
       coordinate
  FROM (SELECT c.graph_name, c.coordinate, c.kind, c.claimer, c.source_name, c.source_line,
               c.source_column,
               ROW_NUMBER() OVER (PARTITION BY c.graph_name, c.coordinate, c.kind, c.claimer
                                  ORDER BY c.source_name NULLS LAST, c.source_line,
                                           c.source_column) AS written
          FROM claimed c) first_written
 WHERE written = 1;
COMMENT ON VIEW graphitron_producer_claim_rule IS 'One producer claim the rule computes, in the shape graphitron_claim stores: the rule itself, evaluated on demand rather than read off disk. For example the graphitron anchor inserts this view''s rows for one graph into graphitron_claim, at the priority and under the stage ProducerClaims claims.';
-- COMMENT ON COLUMN graphitron_producer_claim_rule.graph_name IS 'the owning graph''s partition';
-- COMMENT ON COLUMN graphitron_producer_claim_rule.coordinate IS 'the declared field claimed';
-- COMMENT ON COLUMN graphitron_producer_claim_rule.kind IS 'the graphitron_producer kind claimed';
-- COMMENT ON COLUMN graphitron_producer_claim_rule.claimer IS 'the field, or the argument for a LOOKUP';
-- COMMENT ON COLUMN graphitron_producer_claim_rule.source_name IS 'the file the first claim of the kind was written in';
-- COMMENT ON COLUMN graphitron_producer_claim_rule.source_line IS 'its line';
-- COMMENT ON COLUMN graphitron_producer_claim_rule.source_column IS 'its column';
-- COMMENT ON COLUMN graphitron_producer_claim_rule.element_graph_ref IS 'the graph, as the element reference';
-- COMMENT ON COLUMN graphitron_producer_claim_rule.element_coordinate_ref IS 'the field, as the element reference';

-- What a binding claim names, beside the claim itself: the binding family's subtype of
-- graphitron_claim, a row for every binding claim.
CREATE TABLE graphitron_binding_claim (
  graph_name  VARCHAR NOT NULL,
  coordinate  VARCHAR NOT NULL,
  kind        VARCHAR NOT NULL,
  claimer     VARCHAR NOT NULL,
  named       VARCHAR,
  target_name VARCHAR,
  PRIMARY KEY (graph_name, coordinate, kind, claimer),
  -- The claim it details, whose sweep takes this row with it.
  FOREIGN KEY (graph_name, coordinate, kind, claimer)
    REFERENCES graphitron_claim (graph_name, coordinate, kind, claimer) ON DELETE CASCADE,
  CHECK (kind IN ('COLUMN', 'NODE_ID', 'EXPRESSION', 'VOUCHER')),
  -- An expression names nothing here; its method is the binding's. Nor does a voucher, which its
  -- marker's own relations state.
  CHECK (kind NOT IN ('EXPRESSION', 'VOUCHER') OR named IS NULL),
  -- Only a node id has somewhere else to put its decoded value.
  CHECK (kind = 'NODE_ID' OR target_name IS NULL)
);
COMMENT ON TABLE graphitron_binding_claim IS 'What one binding claim names: one row per binding claim in graphitron_claim. For example a field carrying @field(name: "title") has a COLUMN row naming title, and an input field carrying @nodeId(typeName: "Film") @field(name: "film") a NODE_ID row naming Film with film as its target.';
COMMENT ON COLUMN graphitron_binding_claim.graph_name IS 'the owning graph''s partition, carried from the claim';
COMMENT ON COLUMN graphitron_binding_claim.coordinate IS 'the declared element claiming, as graphitron_element spells it: Film.title, FilmInput.title or Query.films(title:)';
COMMENT ON COLUMN graphitron_binding_claim.kind IS 'the graphitron_occurrence_binding kind claimed: COLUMN from @field(name:), NODE_ID from @nodeId, EXPRESSION from @externalField, VOUCHER from @issue or @accept';
COMMENT ON COLUMN graphitron_binding_claim.claimer IS 'the element whose fact implies the claim, the element itself for every claim written today; with the three columns before it, graphitron_claim''s key';
COMMENT ON COLUMN graphitron_binding_claim.named IS 'what the claim names, as written: the column for COLUMN, the node type for NODE_ID. Null for a bare @nodeId, whose node type the binding infers, and for EXPRESSION';
COMMENT ON COLUMN graphitron_binding_claim.target_name IS 'where a NODE_ID claim''s decoded value goes, as a @field(name:) beside the @nodeId writes it: the member of the class an occurrence binds into. Whether a target is meaningful depends on the occurrence''s source, so the claim states it and the reader judges it; null where no @field is written and on every other kind';

-- What each field, input field and argument's written directives claim it binds to. None of the
-- three directives repeats, so an element's one application of each is its ordinal 0; a refused
-- schema repeating one still claims once. An enum value's @field names the sort column its @order
-- reads, which binds no occurrence, and claims nothing here.
CREATE VIEW graphitron_binding_claim_rule (graph_name, coordinate, kind, claimer, named,
                                           target_name, source_name, source_line, source_column,
                                           element_graph_ref, element_coordinate_ref) AS
WITH claimed (graph_name, coordinate, kind, named, target_name, source_name, source_line,
              source_column) AS (
-- @field(name:), the column written, where no @nodeId beside it makes the name the node id's
-- target instead.
SELECT e.graph_name, e.coordinate, 'COLUMN', b.name_ref, CAST(NULL AS VARCHAR),
       da.source_name, da.source_line, da.source_column
  FROM graphitron_element e
  JOIN graphitron_directive_application da
    ON da.graph_name = e.graph_name AND da.coordinate = e.coordinate
   AND da.directive_name = 'field' AND da.ordinal = 0
  LEFT JOIN graphitron_ast_binding_entry b
    ON b.graph_name = da.graph_name AND b.source_name = da.source_name
   AND b.source_line = da.source_line AND b.source_column = da.source_column
 WHERE e.element_kind IN ('FIELD', 'INPUT_FIELD', 'FIELD_ARGUMENT')
   AND NOT EXISTS (SELECT 1 FROM graphitron_directive_application nid
                    WHERE nid.graph_name = e.graph_name AND nid.coordinate = e.coordinate
                      AND nid.directive_name = 'nodeId' AND nid.ordinal = 0)
UNION ALL
-- @nodeId, with the node type when one is written, and the @field(name:) beside it as the target
-- its decoded value goes to.
SELECT e.graph_name, e.coordinate, 'NODE_ID', n.node_type_ref, t.name_ref,
       da.source_name, da.source_line, da.source_column
  FROM graphitron_element e
  JOIN graphitron_directive_application da
    ON da.graph_name = e.graph_name AND da.coordinate = e.coordinate
   AND da.directive_name = 'nodeId' AND da.ordinal = 0
  LEFT JOIN graphitron_ast_node_id_entry n
    ON n.graph_name = da.graph_name AND n.source_name = da.source_name
   AND n.source_line = da.source_line AND n.source_column = da.source_column
  LEFT JOIN graphitron_directive_application fa
    ON fa.graph_name = e.graph_name AND fa.coordinate = e.coordinate
   AND fa.directive_name = 'field' AND fa.ordinal = 0
  LEFT JOIN graphitron_ast_binding_entry t
    ON t.graph_name = fa.graph_name AND t.source_name = fa.source_name
   AND t.source_line = fa.source_line AND t.source_column = fa.source_column
 WHERE e.element_kind IN ('FIELD', 'INPUT_FIELD', 'FIELD_ARGUMENT')
UNION ALL
-- @externalField, on an output field.
SELECT e.graph_name, e.coordinate, 'EXPRESSION', CAST(NULL AS VARCHAR), CAST(NULL AS VARCHAR),
       da.source_name, da.source_line, da.source_column
  FROM graphitron_element e
  JOIN graphitron_directive_application da
    ON da.graph_name = e.graph_name AND da.coordinate = e.coordinate
   AND da.directive_name = 'externalField' AND da.ordinal = 0
 WHERE e.element_kind = 'FIELD'
UNION ALL
-- @issue or @accept, the voucher field: its value is the voucher, which Graphitron computes on the
-- issuing side and the representation carries on the accepting side, never a column.
SELECT e.graph_name, e.coordinate, 'VOUCHER', CAST(NULL AS VARCHAR), CAST(NULL AS VARCHAR),
       da.source_name, da.source_line, da.source_column
  FROM graphitron_element e
  JOIN graphitron_directive_application da
    ON da.graph_name = e.graph_name AND da.coordinate = e.coordinate
   AND da.directive_name IN ('issue', 'accept') AND da.ordinal = 0
 WHERE e.element_kind = 'FIELD'
)
SELECT graph_name, coordinate, kind, coordinate, named, target_name, source_name, source_line,
       source_column, graph_name, coordinate
  FROM claimed;
COMMENT ON VIEW graphitron_binding_claim_rule IS 'One binding claim the rule computes, with what it names: the rule itself, evaluated on demand rather than read off disk. For example the graphitron anchor inserts this view''s rows for one graph into graphitron_claim and graphitron_binding_claim, at the priority and under the stage BindingClaims claims.';
-- COMMENT ON COLUMN graphitron_binding_claim_rule.graph_name IS 'the owning graph''s partition';
-- COMMENT ON COLUMN graphitron_binding_claim_rule.coordinate IS 'the declared element claiming';
-- COMMENT ON COLUMN graphitron_binding_claim_rule.kind IS 'the graphitron_occurrence_binding kind claimed';
-- COMMENT ON COLUMN graphitron_binding_claim_rule.claimer IS 'the element itself';
-- COMMENT ON COLUMN graphitron_binding_claim_rule.named IS 'the column or node type the claim names';
-- COMMENT ON COLUMN graphitron_binding_claim_rule.target_name IS 'where a node id''s decoded value goes';
-- COMMENT ON COLUMN graphitron_binding_claim_rule.source_name IS 'the file the claim was written in';
-- COMMENT ON COLUMN graphitron_binding_claim_rule.source_line IS 'its line';
-- COMMENT ON COLUMN graphitron_binding_claim_rule.source_column IS 'its column';
-- COMMENT ON COLUMN graphitron_binding_claim_rule.element_graph_ref IS 'the graph, as the element reference';
-- COMMENT ON COLUMN graphitron_binding_claim_rule.element_coordinate_ref IS 'the element, as the element reference';

-- What each type's written directives claim it stands for: rows of a table from @table, an error
-- its handlers fill from an exception from @error. A claim is what was written, whether or not it
-- resolves. Neither directive repeats, so a type's one application of each is its ordinal 0,
-- whether written on its declaration or an extension; a refused schema repeating one still claims
-- once.
CREATE VIEW graphitron_type_claim_rule (graph_name, coordinate, kind, claimer, source_name,
                                        source_line, source_column, element_graph_ref,
                                        element_coordinate_ref) AS
SELECT e.graph_name, e.coordinate,
       CASE da.directive_name WHEN 'table' THEN 'TABLE_TYPE' ELSE 'ERROR_TYPE' END,
       e.coordinate, da.source_name, da.source_line, da.source_column, e.graph_name, e.coordinate
  FROM graphitron_element e
  JOIN graphitron_directive_application da
    ON da.graph_name = e.graph_name AND da.coordinate = e.coordinate
   AND da.directive_name IN ('table', 'error') AND da.ordinal = 0
 WHERE e.element_kind = 'NAMED_TYPE';
COMMENT ON VIEW graphitron_type_claim_rule IS 'One type claim the rule computes, in the shape graphitron_claim stores: the rule itself, evaluated on demand rather than read off disk. For example the graphitron anchor inserts this view''s rows for one graph into graphitron_claim, at the priority and under the stage TypeClaims claims.';
-- COMMENT ON COLUMN graphitron_type_claim_rule.graph_name IS 'the owning graph''s partition';
-- COMMENT ON COLUMN graphitron_type_claim_rule.coordinate IS 'the type claimed for';
-- COMMENT ON COLUMN graphitron_type_claim_rule.kind IS 'TABLE_TYPE or ERROR_TYPE';
-- COMMENT ON COLUMN graphitron_type_claim_rule.claimer IS 'the type itself';
-- COMMENT ON COLUMN graphitron_type_claim_rule.source_name IS 'the file the first application was written in';
-- COMMENT ON COLUMN graphitron_type_claim_rule.source_line IS 'its line';
-- COMMENT ON COLUMN graphitron_type_claim_rule.source_column IS 'its column';
-- COMMENT ON COLUMN graphitron_type_claim_rule.element_graph_ref IS 'the graph, as the element reference';
-- COMMENT ON COLUMN graphitron_type_claim_rule.element_coordinate_ref IS 'the type, as the element reference';

-- ==== SQL catalog facts ===========================================================
-- What the consumer's database declares, in SQL's vocabulary. jOOQ's generated model is the
-- reader, not the owner: reading INFORMATION_SCHEMA directly instead would leave every relation
-- name here correct. "Catalog" stays the prose word for what the family is about; only the
-- prefix carries the rule.
CREATE TABLE sql_schema (
  source_name      VARCHAR NOT NULL,
  table_schema     VARCHAR NOT NULL,
  keys_class_fqn   VARCHAR,
  tables_class_fqn VARCHAR,
  touched_at       TIMESTAMP,
  PRIMARY KEY (source_name, table_schema),
  FOREIGN KEY (source_name) REFERENCES store_source (source_name)
);
COMMENT ON TABLE sql_schema IS 'One schema the consumer''s catalog declares, carrying the generated artifacts that belong to the schema rather than to any one of its tables. For example the public schema of a codegen source, naming the Keys class holding its key constants and the Tables class holding its table constants.';
COMMENT ON COLUMN sql_schema.source_name IS 'the generated package the schema lives in; the partition this row belongs to and the key''s leading dimension, as on sql_table';
COMMENT ON COLUMN sql_schema.table_schema IS 'SQL schema name; empty string when the generated model declares no schema for its tables, which is the same fallback sql_table applies';
COMMENT ON COLUMN sql_schema.keys_class_fqn IS 'the fully qualified name of the generated Keys class holding this schema''s key constants, resolved by loading it off the codegen classpath rather than by concatenating a configured package with ".Keys". The guess and the fact diverge under multi-schema layouts, where each schema gets its own Keys class in its own package. Null when the generated model carries no Keys class for the schema, which is a fact: a schema with no keys has no constants to name. Goto-definition on @reference(key:) lands in this class, so it is a join key rather than a completion nicety.';
COMMENT ON COLUMN sql_schema.tables_class_fqn IS 'the fully qualified name of the generated Tables class holding this schema''s table constants, on exactly the terms the column beside it states: resolved by loading it off the codegen classpath rather than by concatenating a configured package with ".Tables", the guess and the fact diverging under multi-schema layouts where each schema gets its own Tables class in its own package. Null when the generated model carries no Tables class for the schema, which is a fact rather than a gap. This is the column that lets a reader assemble a table reference without a live catalog: every other part of one is already here or on sql_table, and the constants class was the single piece reachable only through the codegen loader, so its absence was what kept table references a walk-side construction';
COMMENT ON COLUMN sql_schema.touched_at IS 'when the reading that produced this row ran. The reading finishes by deleting this source''s rows carrying a different instant, which are the tables, columns and keys the consumer''s database no longer has and which an upsert alone cannot find. Nullable because one writer of these relations sets nothing here, and a row with no instant is not this reading''s';

CREATE TABLE sql_table (
  source_name  VARCHAR NOT NULL,
  table_schema VARCHAR NOT NULL,
  table_name   VARCHAR NOT NULL,
  table_type   VARCHAR NOT NULL,
  jooq_name    VARCHAR NOT NULL,
  class_fqn    VARCHAR NOT NULL,
  record_class_fqn VARCHAR NOT NULL,
  description  VARCHAR,
  table_schema_upper VARCHAR GENERATED ALWAYS AS (UPPER(table_schema)),
  table_name_upper   VARCHAR GENERATED ALWAYS AS (UPPER(table_name)),
  touched_at         TIMESTAMP,
  PRIMARY KEY (source_name, table_schema, table_name),
  FOREIGN KEY (source_name) REFERENCES store_source (source_name),
  FOREIGN KEY (source_name, table_schema) REFERENCES sql_schema (source_name, table_schema)
);
COMMENT ON TABLE sql_table IS 'One table the consumer''s catalog declares. For example public.film, carrying the kind of object it is, the generated jOOQ table class and the record class its rows bind to.';
COMMENT ON COLUMN sql_table.source_name IS 'the generated package the table''s schema lives in; the partition this row belongs to and the key''s leading dimension, so two modules'' catalogs carrying one (schema, table) coordinate coexist instead of the second build clobbering the first. The package rather than the classpath entry it was loaded from, because one jar carries every schema a codegen run produced and invalidating the jar would discard them all, while the package is the granularity codegen actually rewrites. Schemas flattened into one package (jOOQ''s outputSchemaToDefault) share a source, which is correct: they are regenerated together';
COMMENT ON COLUMN sql_table.table_schema IS 'SQL schema the table lives in';
COMMENT ON COLUMN sql_table.table_name IS 'SQL table name';
COMMENT ON COLUMN sql_table.table_type IS 'what kind of table-like object this is, in jOOQ''s TableOptions.TableType vocabulary: TABLE, TEMPORARY, VIEW, MATERIALIZED_VIEW, FUNCTION, EXPRESSION or UNKNOWN. A property of the object every catalog states and this family recorded none of, so the store could not tell a base table from a view. FUNCTION is the value that carries weight today: it marks a table-valued function''s result, which has no primary key and no foreign keys by construction, and that one property is what every carve-out on a function-backed field turns on. A reader asking whether a name is table-valued asks this column rather than reaching back into the live catalog. The callable behind a FUNCTION row is its own subject in sql_routine, joined on the shared (source, schema, name).';
COMMENT ON COLUMN sql_table.class_fqn IS 'the fully qualified name of the generated jOOQ table class, read off the live Table during the catalog walk. Per table, unlike the Keys class name, which is per schema and lives on sql_schema. Goto-definition on @table(name:) and @field(name:) lands in this class, and the classpath census reads the generated jOOQ package''s classes as headers, without their members, so code_class holds the class by name and nothing in the code family says which table it is generated for. That is the sql family''s fact, and this column is the join key that reaches generated sources from a table.';
COMMENT ON COLUMN sql_table.record_class_fqn IS 'the fully qualified name of the record class jOOQ binds this table''s rows to, read off the live Table during the catalog walk. A different fact from class_fqn beside it, and neither spells the other: that is the generated table class an author navigates to, this is the row type a producer method hands back, and the naming relation between them is jOOQ codegen configuration rather than anything the store may assume. Always present, a table always having a row type; a table jOOQ generated no record class for reports org.jooq.Record, which is the catalog''s own answer and stands as written, a reader that wants only generated records comparing against that name rather than reading a NULL. The classpath census reads the generated record class as a header, without its members, and nothing in the code family says which table a record class belongs to: that is the sql family''s fact and this column states it, so it is how a type bound to a table reaches a class name.';
COMMENT ON COLUMN sql_table.jooq_name IS 'the generated jOOQ Java field name for the table; under a family named for SQL this is the one foreign column, so the prefix marks it rather than leaving a reader to infer it';
COMMENT ON COLUMN sql_table.description IS 'the database comment on the table, when present';
COMMENT ON COLUMN sql_table.table_schema_upper IS 'the upper-cased form of the column beside it, for the case-insensitive match against the namespace half of an authored table or routine reference. Generated, so nothing writes it and nothing can. Fold only where an authored spelling meets a catalog name. Two values of one family are compared exactly, and a comparison that does want a fold on both sides reaches this column by joining sql_table on its key rather than by having it forwarded through a derived view';
COMMENT ON COLUMN sql_table.table_name_upper IS 'the upper-cased form of the column beside it, for the case-insensitive match against the name half of an authored table or routine reference, and against the upper-cased type name where the name argument was omitted. Generated, so nothing writes it and nothing can. Fold only where an authored spelling meets a catalog name. Two values of one family are compared exactly, and a comparison that does want a fold on both sides reaches this column by joining sql_table on its key rather than by having it forwarded through a derived view.';
COMMENT ON COLUMN sql_table.touched_at IS 'when the reading that produced this row ran. The reading finishes by deleting this source''s rows carrying a different instant, which are the tables, columns and keys the consumer''s database no longer has and which an upsert alone cannot find. Nullable because one writer of these relations sets nothing here, and a row with no instant is not this reading''s';
CREATE INDEX ix_sql_table_record_class_fqn ON sql_table (record_class_fqn, source_name);
COMMENT ON INDEX ix_sql_table_record_class_fqn IS 'Serves the match of a class to the table whose record class it is, which graphitron_occurrence_producer_result_rule makes for a producer''s element class.';
CREATE INDEX ix_sql_table_class_fqn ON sql_table (class_fqn);
COMMENT ON INDEX ix_sql_table_class_fqn IS 'Serves the match of a method parameter''s erased class to the table it names, which graphitron_join_path_step_rule makes inline.';
CREATE INDEX ix_sql_table_name_upper ON sql_table (source_name, table_name_upper);
COMMENT ON INDEX ix_sql_table_name_upper IS 'Serves the match of an authored table name to the table it names within one source, case aside, which an outbox target''s verdict reads per graph.';

CREATE TABLE sql_table_record_supertype (
  source_name    VARCHAR NOT NULL,
  table_schema   VARCHAR NOT NULL,
  table_name     VARCHAR NOT NULL,
  supertype_name VARCHAR NOT NULL,
  PRIMARY KEY (source_name, table_schema, table_name, supertype_name),
  FOREIGN KEY (source_name, table_schema, table_name)
    REFERENCES sql_table (source_name, table_schema, table_name) ON DELETE CASCADE
);
COMMENT ON TABLE sql_table_record_supertype IS 'Every type a table''s generated jOOQ record is, itself excluded: the superclass chain above the record class and every interface it or they implement, transitively. For example public.customer''s CustomerRecord being an UpdatableRecordImpl, an UpdatableRecord, a TableRecord and a Record. Captured rather than derived, which is the one thing about this relation a reader has to know before reading it: the classpath census reads the generated jOOQ package''s classes as headers, without their members, and the store holds no supertype edge above CustomerRecord, so no closure could climb from one. The catalog walk holds the record Class itself, Table.getRecordType() being what sql_table.record_class_fqn is read from, so its declared ancestry is one more fact off a class the walk already has. It holds the closure and not the edges, unlike the census pair below it, and the reason is the same fact: the chain above a generated record runs through jOOQ''s own runtime classes, which no census scans and which are not tables, so the store holds no edges a closure could be recomputed from. A census-side twin of this relation once existed, a closure over the classpath''s own supertype edges, and it is gone: nothing ever read it, and what a reader wanting to climb a consumer class actually asks is the code family, where the reading resolves a supertype chain while it has the classfiles open. java.lang.Object is a row here, where a relation of declared edges would have left it out to keep itself to what the source wrote: this states what the class is rather than what it declared, and a record is an Object, which is also what a live Class.isAssignableFrom says. Absent for a table jOOQ generated no record for, the catalog answering org.jooq.Record there, which is no record class rather than a record named that.';
COMMENT ON COLUMN sql_table_record_supertype.source_name IS 'the generated package the table''s schema lives in, as on sql_table; the key''s leading dimension and the refresh unit the whole sql_ family is scoped by';
COMMENT ON COLUMN sql_table_record_supertype.table_schema IS 'the table''s SQL schema, as on sql_table';
COMMENT ON COLUMN sql_table_record_supertype.table_name IS 'the table''s SQL name, as on sql_table; with the two columns above, the table whose record class this row is about. Keyed on the table rather than on the record class, so the row is deleted with its table and no reader has to reconcile two spellings of one identity';
COMMENT ON COLUMN sql_table_record_supertype.supertype_name IS 'the fully-qualified binary name of one type the record class is, a nested one spelled with the $ the JVM uses, and spelled the way the reading spells a class name so a declared parameter type compares to it exactly. Every element of the closure and not only the declared parents, the relation holding a closure for the reason its own comment gives; the record class itself is deliberately not a row, a reader asking about it holding sql_table.record_class_fqn already. Frequently not a class the reading reached and never a foreign key: jOOQ''s runtime classes are not scanned, which is what makes capturing this necessary rather than derivable';

CREATE TABLE sql_column (
  source_name  VARCHAR NOT NULL,
  table_schema VARCHAR NOT NULL,
  table_name   VARCHAR NOT NULL,
  column_name  VARCHAR NOT NULL,
  ordinal      INT     NOT NULL,
  jooq_name    VARCHAR NOT NULL,
  sql_type     VARCHAR NOT NULL,
  binding_type VARCHAR NOT NULL,
  database_type VARCHAR NOT NULL,
  nullable     BOOLEAN NOT NULL,
  defaulted    BOOLEAN NOT NULL,
  declared_length INT CHECK (declared_length > 0),
  description  VARCHAR,
  column_name_upper VARCHAR GENERATED ALWAYS AS (UPPER(column_name)),
  jooq_name_upper   VARCHAR GENERATED ALWAYS AS (UPPER(jooq_name)),
  touched_at        TIMESTAMP,
  PRIMARY KEY (source_name, table_schema, table_name, column_name),
  FOREIGN KEY (source_name, table_schema, table_name) REFERENCES sql_table (source_name, table_schema, table_name)
);
COMMENT ON TABLE sql_column IS 'One column of one table the consumer''s catalog declares. For example film.title, a varchar the generated model binds to java.lang.String.';
COMMENT ON COLUMN sql_column.source_name IS 'the owning partition''s generated-package source, as on sql_table; the key''s leading dimension';
COMMENT ON COLUMN sql_column.table_schema IS 'SQL schema the table lives in';
COMMENT ON COLUMN sql_column.table_name IS 'SQL table name';
COMMENT ON COLUMN sql_column.column_name IS 'SQL column name';
COMMENT ON COLUMN sql_column.ordinal IS 'column position in the table definition, read from Table.fields() rather than from the reflective field walk, whose order is unspecified';
COMMENT ON COLUMN sql_column.jooq_name IS 'the generated jOOQ Java field name; the one column here written in the reader''s vocabulary rather than SQL''s';
COMMENT ON COLUMN sql_column.sql_type IS 'the column''s SQL type as jOOQ reports it';
COMMENT ON COLUMN sql_column.binding_type IS 'the fully qualified Java type jOOQ binds the column to, as Field.getType() reports it; read off the live Field during the catalog walk and unrecoverable afterwards, since nothing outside the codegen classpath can resolve a configured binding. Hover renders it beside the SQL type, which is why a column needs both and why keeping only one of them capped what the editor could say about a column.';
COMMENT ON COLUMN sql_column.database_type IS 'the fully qualified Java type jOOQ exchanges with the database for the column, the converter''s fromType() off the live Field; equal to binding_type on a column with no converter, and the type behind the conversion on one with a converter, java.lang.Long for a bigint bound to java.lang.String. Captured beside binding_type for the same reason, that only the codegen classpath can answer it. A node-id decode reads the pair: a key value is written as the binding type''s text, and parsing that text as the database type instead can drop what the binding type carries, the time of day of a date-only database type bound to LocalDateTime';
COMMENT ON COLUMN sql_column.nullable IS 'whether the column admits NULL';
COMMENT ON COLUMN sql_column.defaulted IS 'whether the database fills the column when an insert leaves it out: a declared default or an identity, as jOOQ''s generated DataType states it. A NOT NULL column that is not defaulted must be given a value by every insert';
COMMENT ON COLUMN sql_column.declared_length IS 'the length the column''s type declares, as jOOQ reports it, for example 255 for film.title''s varchar(255); in the dialect''s own unit, characters on PostgreSQL and bytes or characters on Oracle by the column''s length semantics, which the catalog does not say; null when the type declares no length';
COMMENT ON COLUMN sql_column.description IS 'the database comment on the column, when present';
COMMENT ON COLUMN sql_column.column_name_upper IS 'the upper-cased form of the column beside it, for the case-insensitive match against an authored column reference or the field name standing in for one. Generated, so nothing writes it and nothing can. Fold only where an authored spelling meets a catalog name. Two values of one family are compared exactly, and a comparison that does want a fold on both sides reaches this column by joining sql_column on its key rather than by having it forwarded through a derived view. sql_name_matched_key_column is the worked example of that second sentence: both of its column names are catalog values, so it reaches a key column''s fold through the foreign key sql_constraint_column already declares here';
COMMENT ON COLUMN sql_column.jooq_name_upper IS 'the upper-cased form of the column beside it, for the case-insensitive match against an authored column reference or the field name standing in for one, which is the tier tried before the SQL name. Generated, so nothing writes it and nothing can. Fold only where an authored spelling meets a catalog name. Two values of one family are compared exactly, and a comparison that does want a fold on both sides reaches this column by joining sql_column on its key rather than by having it forwarded through a derived view';
COMMENT ON COLUMN sql_column.touched_at IS 'when the reading that produced this row ran. The reading finishes by deleting this source''s rows carrying a different instant, which are the tables, columns and keys the consumer''s database no longer has and which an upsert alone cannot find. Nullable because one writer of these relations sets nothing here, and a row with no instant is not this reading''s';

CREATE TABLE sql_column_record_accessor (
  source_name   VARCHAR NOT NULL,
  table_schema  VARCHAR NOT NULL,
  table_name    VARCHAR NOT NULL,
  column_name   VARCHAR NOT NULL,
  getter_name   VARCHAR NOT NULL,
  property_name VARCHAR NOT NULL,
  touched_at    TIMESTAMP,
  PRIMARY KEY (source_name, table_schema, table_name, column_name),
  FOREIGN KEY (source_name, table_schema, table_name, column_name)
    REFERENCES sql_column (source_name, table_schema, table_name, column_name) ON DELETE CASCADE
);
COMMENT ON TABLE sql_column_record_accessor IS 'The public no-argument getter this table''s generated record reads one column through. For example film.title, which FilmRecord reads through getTitle, the Bean Validation property title.';
COMMENT ON COLUMN sql_column_record_accessor.source_name IS 'the generated package the table''s schema lives in, as on sql_column; the key''s leading dimension and the refresh unit the sweep is scoped by';
COMMENT ON COLUMN sql_column_record_accessor.table_schema IS 'the table''s SQL schema, as on sql_column';
COMMENT ON COLUMN sql_column_record_accessor.table_name IS 'the table''s SQL name, as on sql_column';
COMMENT ON COLUMN sql_column_record_accessor.column_name IS 'the column''s SQL name, as on sql_column; with the three columns above, the column this row is about';
COMMENT ON COLUMN sql_column_record_accessor.getter_name IS 'the getter''s method name: get, then the column''s SQL name with space, hyphen and dot read as underscores and each underscore-separated word capitalised with the rest of it lower-cased, which is the name jOOQ''s default generator strategy writes. For example BILDE gives getBilde and film_id gives getFilmId. Present only where the record class declares that name as a public no-argument instance method whose return type the column''s Java type is assignable to, which also rejects a name jOOQ disambiguated against a method of Record';
COMMENT ON COLUMN sql_column_record_accessor.property_name IS 'the Bean Validation property the getter names: the getter''s name without get, decapitalised the way java.beans does, so a name starting with two capitals keeps them. What a Validator.validateProperty call on the record names, and what a constraint mapped onto the record''s getter is registered under';
COMMENT ON COLUMN sql_column_record_accessor.touched_at IS 'when the reading that produced this row ran, as on sql_column; the reading finishes by deleting this source''s rows carrying a different instant, which are the getters the regenerated records no longer have';

CREATE TABLE sql_enum_binding (
  source_name  VARCHAR NOT NULL,
  class_fqn    VARCHAR NOT NULL,
  table_schema VARCHAR,
  type_name    VARCHAR,
  touched_at   TIMESTAMP,
  PRIMARY KEY (source_name, class_fqn),
  FOREIGN KEY (source_name) REFERENCES store_source (source_name)
);
COMMENT ON TABLE sql_enum_binding IS 'One Java enum class some column of one catalog source binds to. For example the class generated for the mpaa_rating database type, which film.rating binds to, and equally a hand-written enum a configured converter binds a column to.';
COMMENT ON COLUMN sql_enum_binding.source_name IS 'the owning partition''s generated-package source, as on sql_table; the key''s leading dimension. A class reachable from two sources is two rows, on code_class.source_name''s terms';
COMMENT ON COLUMN sql_enum_binding.class_fqn IS 'the fully qualified name of the enum class, as Field.getType() reports it; the value a declared parameter type is compared against, and the reason the comparison can be an equality rather than a fold: both sides are binary names nobody wrote by hand. An array-typed column contributes no row, its bound type being the array and not the element';
COMMENT ON COLUMN sql_enum_binding.table_schema IS 'the SQL schema declaring the database enum type this class was generated for; NULL where the class names no catalog type, which is the converter-bound Java enum the table comment describes, and NULL again where it names one that is not schema-scoped. Not a foreign key into sql_schema for the first reason: that half is not a schema the walk failed to resolve, it is a row for which no schema is the right answer';
COMMENT ON COLUMN sql_enum_binding.type_name IS 'the database enum type''s own name, as the generated class reports it; NULL where the class names no catalog type, which is the wider of the two silences beside it. Carried so a reader can name the type an author would see in their database rather than only the class jOOQ generated from it';
COMMENT ON COLUMN sql_enum_binding.touched_at IS 'when the reading that produced this row ran. The reading finishes by deleting this source''s rows carrying a different instant, which are the tables, columns and keys the consumer''s database no longer has and which an upsert alone cannot find. Nullable because one writer of these relations sets nothing here, and a row with no instant is not this reading''s';

CREATE TABLE sql_enum_binding_literal (
  source_name   VARCHAR NOT NULL,
  class_fqn     VARCHAR NOT NULL,
  constant_name VARCHAR NOT NULL,
  literal       VARCHAR NOT NULL,
  ordinal       INT     NOT NULL,
  touched_at    TIMESTAMP,
  PRIMARY KEY (source_name, class_fqn, constant_name),
  -- Two constants spelling one database value would make the value name no constant in particular.
  UNIQUE (source_name, class_fqn, literal),
  FOREIGN KEY (source_name, class_fqn) REFERENCES sql_enum_binding (source_name, class_fqn) ON DELETE CASCADE
);
COMMENT ON TABLE sql_enum_binding_literal IS 'One constant of one bound enum class, with the value the database stores for it. For example the constant PG_13 of the class generated for mpaa_rating, whose literal is PG-13.';
COMMENT ON COLUMN sql_enum_binding_literal.source_name IS 'the owning partition''s generated-package source, as on sql_enum_binding';
COMMENT ON COLUMN sql_enum_binding_literal.class_fqn IS 'the bound enum class, as on sql_enum_binding';
COMMENT ON COLUMN sql_enum_binding_literal.constant_name IS 'the constant''s Java name, Enum.name(); with the class, the key';
COMMENT ON COLUMN sql_enum_binding_literal.literal IS 'the value the database stores for the constant: EnumType.getLiteral() on a jOOQ-generated enum, where it differs from the name whenever the literal is not a Java identifier (PG-13 against PG_13), and the name itself on a converter-bound Java enum, which has no literal of its own and whose converter is what the column stores';
COMMENT ON COLUMN sql_enum_binding_literal.ordinal IS 'the constant''s declaration position, Enum.ordinal(), so a reader lists the literals in the order the type declares them';
COMMENT ON COLUMN sql_enum_binding_literal.touched_at IS 'when the reading that produced this row ran, swept with sql_enum_binding''s rows by the same reading';

CREATE TABLE sql_constraint (
  source_name     VARCHAR NOT NULL,
  table_schema    VARCHAR NOT NULL,
  table_name      VARCHAR NOT NULL,
  constraint_name VARCHAR NOT NULL,
  constraint_type VARCHAR NOT NULL,
  jooq_name       VARCHAR,
  key_position    INT,
  table_schema_upper    VARCHAR GENERATED ALWAYS AS (UPPER(table_schema)),
  constraint_name_upper VARCHAR GENERATED ALWAYS AS (UPPER(constraint_name)),
  jooq_name_upper       VARCHAR GENERATED ALWAYS AS (UPPER(jooq_name)),
  touched_at            TIMESTAMP,
  PRIMARY KEY (source_name, table_schema, table_name, constraint_name),
  -- The key with its form beside it, which the primary key already makes unique; it is here so
  -- sql_primary_key can reference a constraint of one form and no other.
  UNIQUE (source_name, table_schema, table_name, constraint_name, constraint_type),
  FOREIGN KEY (source_name, table_schema, table_name) REFERENCES sql_table (source_name, table_schema, table_name),
  CHECK (constraint_type IN ('PRIMARY KEY', 'UNIQUE', 'FOREIGN KEY'))
);
COMMENT ON TABLE sql_constraint IS 'One named constraint of one table. For example film_pkey on public.film, of type PRIMARY KEY, at its position in the table''s uniqueness enumeration.';
COMMENT ON COLUMN sql_constraint.jooq_name IS 'the generated Keys-class constant name for this constraint, which is what an author types in @reference(key:). Resolved by reference identity over the Keys class''s fields rather than by any formula over the constraint name, so a name colliding across schemas cannot mis-resolve; that resolution needs the live key on the codegen classpath and is unrecoverable afterwards. Null when the constraint resolves to no constant, which is a fact and not a failure: a generated model need not carry a Keys class, and a key with no constant is one nobody can name. Nullable where sql_table.jooq_name and sql_column.jooq_name are not, because a table and a column always have a generated Java name and a constraint need not.';
COMMENT ON COLUMN sql_constraint.key_position IS 'where this constraint sits in the table''s uniqueness enumeration, jOOQ''s Table.getKeys() order with the primary key folded in, counting from zero. Captured rather than derived because the order is the generated model''s and nothing in the constraint''s own name or columns recovers it. It exists because a consumer picking one row-identifying key out of several has to pick the one the generator picks, and the generator walks this enumeration; without the position a relation ranking candidate keys would have to invent a tiebreaker among unique keys, and an invented precedence that happens to agree today is the kind of second answer that diverges silently later. Null on a FOREIGN KEY row, which is not in this enumeration at all: absence here means the constraint identifies no row rather than that its position is unknown.';
COMMENT ON COLUMN sql_constraint.source_name IS 'the owning partition''s generated-package source, as on sql_table; the key''s leading dimension';
COMMENT ON COLUMN sql_constraint.table_schema IS 'SQL schema the table lives in';
COMMENT ON COLUMN sql_constraint.table_name IS 'SQL table name';
COMMENT ON COLUMN sql_constraint.constraint_name IS 'SQL constraint name';
COMMENT ON COLUMN sql_constraint.constraint_type IS 'the standard''s TABLE_CONSTRAINTS vocabulary; the domain is closed over what the catalog walk reads, so a violation is a capture bug';
COMMENT ON COLUMN sql_constraint.table_schema_upper IS 'the upper-cased form of the column beside it, for the case-insensitive match against the namespace half of an authored key reference, which names the schema of the table holding the constraint rather than any schema of the constraint''s own. Generated, so nothing writes it and nothing can. Fold only where an authored spelling meets a catalog name. Two values of one family are compared exactly, and a comparison that does want a fold on both sides reaches this column by joining sql_constraint on its key rather than by having it forwarded through a derived view';
COMMENT ON COLUMN sql_constraint.constraint_name_upper IS 'the upper-cased form of the column beside it, for the case-insensitive match against the name half of an authored key reference. Generated, so nothing writes it and nothing can. Fold only where an authored spelling meets a catalog name. Two values of one family are compared exactly, and a comparison that does want a fold on both sides reaches this column by joining sql_constraint on its key rather than by having it forwarded through a derived view';
COMMENT ON COLUMN sql_constraint.jooq_name_upper IS 'the upper-cased form of the column beside it, for the case-insensitive match against the name half of an authored key reference, eligible only where no SQL constraint name answers it. NULL where jooq_name is, which is the constraint that resolves to no constant and therefore matches no reference. Generated, so nothing writes it and nothing can. Fold only where an authored spelling meets a catalog name. Two values of one family are compared exactly, and a comparison that does want a fold on both sides reaches this column by joining sql_constraint on its key rather than by having it forwarded through a derived view';
COMMENT ON COLUMN sql_constraint.touched_at IS 'when the reading that produced this row ran. The reading finishes by deleting this source''s rows carrying a different instant, which are the tables, columns and keys the consumer''s database no longer has and which an upsert alone cannot find. Nullable because one writer of these relations sets nothing here, and a row with no instant is not this reading''s';
CREATE INDEX sql_constraint_name_upper_ix ON sql_constraint (constraint_name_upper, source_name);
COMMENT ON INDEX sql_constraint_name_upper_ix IS 'A written key meets the catalog by its folded SQL name, the primary key leading with the source and the table and so serving none of it. Measured on a sis capture of 2026-10-21, 453 key elements against 1737 constraints: graphitron_path_element_key_rule took 0.6 to 1.7 s with no index here and 8 to 80 ms with this one and its jOOQ-name sibling.';
CREATE INDEX sql_constraint_jooq_name_upper_ix ON sql_constraint (jooq_name_upper, source_name);
COMMENT ON INDEX sql_constraint_jooq_name_upper_ix IS 'The same match by the folded Keys constant, which a written key falls back to where no SQL name answers it, and which opptak writes for most of its keys.';

CREATE TABLE sql_constraint_column (
  source_name     VARCHAR NOT NULL,
  table_schema    VARCHAR NOT NULL,
  table_name      VARCHAR NOT NULL,
  constraint_name VARCHAR NOT NULL,
  position        INT     NOT NULL,
  column_name     VARCHAR NOT NULL,
  touched_at      TIMESTAMP,
  PRIMARY KEY (source_name, table_schema, table_name, constraint_name, position),
  FOREIGN KEY (source_name, table_schema, table_name, constraint_name)
    REFERENCES sql_constraint (source_name, table_schema, table_name, constraint_name),
  FOREIGN KEY (source_name, table_schema, table_name, column_name)
    REFERENCES sql_column (source_name, table_schema, table_name, column_name)
);
COMMENT ON TABLE sql_constraint_column IS 'One position in one constraint''s column list, naming the column that sits there. For example position 0 of film_actor''s primary key, naming actor_id.';
COMMENT ON COLUMN sql_constraint_column.source_name IS 'the owning partition''s generated-package source, as on sql_table; the key''s leading dimension';
COMMENT ON COLUMN sql_constraint_column.table_schema IS 'SQL schema the table lives in';
COMMENT ON COLUMN sql_constraint_column.table_name IS 'SQL table name';
COMMENT ON COLUMN sql_constraint_column.constraint_name IS 'SQL constraint name';
COMMENT ON COLUMN sql_constraint_column.position IS '0-based position in the constraint''s column list';
COMMENT ON COLUMN sql_constraint_column.column_name IS 'SQL column name';
COMMENT ON COLUMN sql_constraint_column.touched_at IS 'when the reading that produced this row ran. The reading finishes by deleting this source''s rows carrying a different instant, which are the tables, columns and keys the consumer''s database no longer has and which an upsert alone cannot find. Nullable because one writer of these relations sets nothing here, and a row with no instant is not this reading''s';

CREATE TABLE sql_primary_key (
  source_name     VARCHAR NOT NULL,
  table_schema    VARCHAR NOT NULL,
  table_name      VARCHAR NOT NULL,
  constraint_name VARCHAR NOT NULL,
  constraint_type VARCHAR NOT NULL DEFAULT 'PRIMARY KEY',
  touched_at      TIMESTAMP,
  PRIMARY KEY (source_name, table_schema, table_name),
  FOREIGN KEY (source_name, table_schema, table_name, constraint_name, constraint_type)
    REFERENCES sql_constraint (source_name, table_schema, table_name, constraint_name, constraint_type),
  CHECK (constraint_type = 'PRIMARY KEY')
);
COMMENT ON TABLE sql_primary_key IS 'One table''s primary key, naming the constraint that is it. For example public.film, whose primary key is the constraint film_pkey.';
COMMENT ON COLUMN sql_primary_key.source_name IS 'the owning partition''s generated-package source, as on sql_table; the key''s leading dimension';
COMMENT ON COLUMN sql_primary_key.table_schema IS 'SQL schema the table lives in';
COMMENT ON COLUMN sql_primary_key.table_name IS 'SQL table name';
COMMENT ON COLUMN sql_primary_key.constraint_name IS 'the name of the PRIMARY KEY constraint in sql_constraint';
COMMENT ON COLUMN sql_primary_key.constraint_type IS 'always PRIMARY KEY, and here only so the foreign key into sql_constraint carries the form: a row naming a unique key or a foreign key as a table''s primary key is refused by the database rather than found by a query. Defaulted, so no writer names it';
COMMENT ON COLUMN sql_primary_key.touched_at IS 'when the reading that produced this row ran. The reading finishes by deleting this source''s rows carrying a different instant, which are the tables, columns and keys the consumer''s database no longer has and which an upsert alone cannot find. Nullable because one writer of these relations sets nothing here, and a row with no instant is not this reading''s';

CREATE TABLE sql_name_matched_key_column (
  source_name    VARCHAR NOT NULL,
  table_schema   VARCHAR NOT NULL,
  table_name     VARCHAR NOT NULL,
  column_name    VARCHAR NOT NULL,
  to_source_name VARCHAR NOT NULL,
  to_schema      VARCHAR NOT NULL,
  to_table       VARCHAR NOT NULL,
  to_column      VARCHAR NOT NULL,
  position       INT     NOT NULL,
  PRIMARY KEY (source_name, table_schema, table_name,
               to_source_name, to_schema, to_table, position),
  FOREIGN KEY (source_name, table_schema, table_name)
    REFERENCES sql_table (source_name, table_schema, table_name) ON DELETE CASCADE,
  FOREIGN KEY (to_source_name, to_schema, to_table)
    REFERENCES sql_table (source_name, table_schema, table_name) ON DELETE CASCADE,
  FOREIGN KEY (source_name, table_schema, table_name, column_name)
    REFERENCES sql_column (source_name, table_schema, table_name, column_name) ON DELETE CASCADE,
  FOREIGN KEY (to_source_name, to_schema, to_table, to_column)
    REFERENCES sql_column (source_name, table_schema, table_name, column_name) ON DELETE CASCADE
);
COMMENT ON TABLE sql_name_matched_key_column IS 'One column of the key that matches a table-valued function''s result to a table by column name. For example a function result exposing organisasjonskode, matched against the primary key of public.organisasjon, is one row at position 0.';
COMMENT ON COLUMN sql_name_matched_key_column.source_name IS 'the departing function result''s generated-package source, as on sql_table';
COMMENT ON COLUMN sql_name_matched_key_column.table_schema IS 'the departing function result''s SQL schema';
COMMENT ON COLUMN sql_name_matched_key_column.table_name IS 'the departing function result''s SQL name; always a table of type FUNCTION, this rule having no subject where a foreign key could be read instead';
COMMENT ON COLUMN sql_name_matched_key_column.to_source_name IS 'the arriving table''s catalog source';
COMMENT ON COLUMN sql_name_matched_key_column.to_schema IS 'the arriving table''s SQL schema';
COMMENT ON COLUMN sql_name_matched_key_column.to_table IS 'the arriving table''s SQL name; a table with a primary key, which is what there is to match against';
COMMENT ON COLUMN sql_name_matched_key_column.position IS 'the arriving key column''s own ordinal, copied from sql_constraint_column where the constraint declares it rather than assigned here. A join predicate does not care in which order its equalities are conjoined, so this is not what makes the pairing correct; it is what lets a consumer build a key tuple in the key''s order without going back to the constraint for one, and what gives every consumer the same order without agreeing on a tie-break';
COMMENT ON COLUMN sql_name_matched_key_column.to_column IS 'the arriving table''s primary-key column at that position';
COMMENT ON COLUMN sql_name_matched_key_column.column_name IS 'the function result''s column of the same name, which is the one the join reads. NOT NULL: a key with an unexposed column is not stated at all, so this column never carries the absence its predecessor did';

CREATE TABLE sql_column_spelling (
  source_name    VARCHAR NOT NULL,
  table_schema   VARCHAR NOT NULL,
  table_name     VARCHAR NOT NULL,
  spelling_upper VARCHAR NOT NULL,
  column_name    VARCHAR NOT NULL,
  matched_by     VARCHAR NOT NULL,
  reach          INT     NOT NULL,
  PRIMARY KEY (source_name, table_schema, table_name, spelling_upper, column_name),
  FOREIGN KEY (source_name, table_schema, table_name, column_name)
    REFERENCES sql_column (source_name, table_schema, table_name, column_name) ON DELETE CASCADE,
  CHECK (matched_by IN ('SQL_NAME', 'JOOQ_NAME')),
  CHECK (reach >= 1)
);
COMMENT ON TABLE sql_column_spelling IS 'One column a written name reaches on a table, folded by case: by its SQL name where any column of the table carries that name, else by its generated jOOQ name. For example the spelling FILM_ID reaches public.film.film_id by SQL_NAME, with a reach of one.';
COMMENT ON COLUMN sql_column_spelling.source_name IS 'the table''s generated-package source, as on sql_table';
COMMENT ON COLUMN sql_column_spelling.table_schema IS 'the table''s SQL schema';
COMMENT ON COLUMN sql_column_spelling.table_name IS 'the table''s SQL name';
COMMENT ON COLUMN sql_column_spelling.spelling_upper IS 'the name folded by case, which is where an authored spelling meets the catalog: a reader folds the author''s @field(name:) or field name and joins here, and compares nothing else';
COMMENT ON COLUMN sql_column_spelling.column_name IS 'the column the spelling reaches, as the catalog spells it';
COMMENT ON COLUMN sql_column_spelling.matched_by IS 'which of the column''s names the spelling met: SQL_NAME, the column''s own; JOOQ_NAME, the generated one, which answers only where no column of the table carries the spelling as its SQL name';
COMMENT ON COLUMN sql_column_spelling.reach IS 'how many columns of the table the spelling reaches under that precedence, the same on every row of one spelling: one is a resolution, more is an ambiguity, and a spelling no column answers has no row';

CREATE TABLE sql_referential_constraint (
  source_name                VARCHAR NOT NULL,
  table_schema               VARCHAR NOT NULL,
  table_name                 VARCHAR NOT NULL,
  constraint_name            VARCHAR NOT NULL,
  referenced_source_name     VARCHAR NOT NULL,
  referenced_schema          VARCHAR NOT NULL,
  referenced_table           VARCHAR NOT NULL,
  referenced_constraint_name VARCHAR NOT NULL,
  touched_at                 TIMESTAMP,
  PRIMARY KEY (source_name, table_schema, table_name, constraint_name),
  -- The key with the constraint it references beside it, which the primary key already makes
  -- unique; it is here so a column of this key can reference the key and its target together.
  UNIQUE (source_name, table_schema, table_name, constraint_name,
          referenced_source_name, referenced_schema, referenced_table, referenced_constraint_name),
  FOREIGN KEY (source_name, table_schema, table_name, constraint_name)
    REFERENCES sql_constraint (source_name, table_schema, table_name, constraint_name),
  FOREIGN KEY (referenced_source_name, referenced_schema, referenced_table, referenced_constraint_name)
    REFERENCES sql_constraint (source_name, table_schema, table_name, constraint_name)
);
COMMENT ON TABLE sql_referential_constraint IS 'One foreign key''s reference to the constraint it resolves against. For example film_actor''s foreign key to film, referencing the film_pkey constraint of public.film.';
COMMENT ON COLUMN sql_referential_constraint.source_name IS 'the owning partition''s generated-package source, as on sql_table; the key''s leading dimension';
COMMENT ON COLUMN sql_referential_constraint.table_schema IS 'schema of the declaring table';
COMMENT ON COLUMN sql_referential_constraint.table_name IS 'the declaring (source) table';
COMMENT ON COLUMN sql_referential_constraint.constraint_name IS 'SQL constraint name';
COMMENT ON COLUMN sql_referential_constraint.referenced_source_name IS 'the referenced constraint''s own generated-package source: equal to source_name for the ordinary in-package reference, different exactly when a foreign key crosses schemas that codegen wrote into different packages, which the multi-schema layout produces. Part of the composite reference, since the constraint''s key leads with its source';
COMMENT ON COLUMN sql_referential_constraint.referenced_schema IS 'schema of the referenced constraint''s table; part of the composite reference, not a denormalisation';
COMMENT ON COLUMN sql_referential_constraint.referenced_table IS 'the referenced constraint''s table';
COMMENT ON COLUMN sql_referential_constraint.referenced_constraint_name IS 'the referenced constraint''s name';
COMMENT ON COLUMN sql_referential_constraint.touched_at IS 'when the reading that produced this row ran. The reading finishes by deleting this source''s rows carrying a different instant, which are the tables, columns and keys the consumer''s database no longer has and which an upsert alone cannot find. Nullable because one writer of these relations sets nothing here, and a row with no instant is not this reading''s';

CREATE TABLE sql_referential_constraint_column (
  source_name                VARCHAR NOT NULL,
  table_schema               VARCHAR NOT NULL,
  table_name                 VARCHAR NOT NULL,
  constraint_name            VARCHAR NOT NULL,
  position                   INT     NOT NULL,
  referenced_source_name     VARCHAR NOT NULL,
  referenced_schema          VARCHAR NOT NULL,
  referenced_table           VARCHAR NOT NULL,
  referenced_constraint_name VARCHAR NOT NULL,
  referenced_position        INT     NOT NULL,
  touched_at                 TIMESTAMP,
  PRIMARY KEY (source_name, table_schema, table_name, constraint_name, position),
  UNIQUE (source_name, table_schema, table_name, constraint_name, referenced_position),
  FOREIGN KEY (source_name, table_schema, table_name, constraint_name, position)
    REFERENCES sql_constraint_column (source_name, table_schema, table_name, constraint_name, position),
  FOREIGN KEY (source_name, table_schema, table_name, constraint_name,
               referenced_source_name, referenced_schema, referenced_table, referenced_constraint_name)
    REFERENCES sql_referential_constraint (source_name, table_schema, table_name, constraint_name,
               referenced_source_name, referenced_schema, referenced_table, referenced_constraint_name),
  FOREIGN KEY (referenced_source_name, referenced_schema, referenced_table, referenced_constraint_name,
               referenced_position)
    REFERENCES sql_constraint_column (source_name, table_schema, table_name, constraint_name, position)
);
COMMENT ON TABLE sql_referential_constraint_column IS 'One column of one foreign key, and the position of the referenced key it names. For example position 0 of reordered_fk_child_parent_fkey, fk_b, names position 1 of reordered_pk_parent_pkey, pk_b.';
COMMENT ON COLUMN sql_referential_constraint_column.source_name IS 'the owning partition''s generated-package source, as on sql_table; the key''s leading dimension';
COMMENT ON COLUMN sql_referential_constraint_column.table_schema IS 'schema of the declaring table';
COMMENT ON COLUMN sql_referential_constraint_column.table_name IS 'the declaring (source) table';
COMMENT ON COLUMN sql_referential_constraint_column.constraint_name IS 'the foreign key''s name';
COMMENT ON COLUMN sql_referential_constraint_column.position IS 'the place in the foreign key''s own column list, 0-based; with the four columns above, the foreign key''s own sql_constraint_column row';
COMMENT ON COLUMN sql_referential_constraint_column.referenced_source_name IS 'the referenced constraint''s generated-package source, forwarded from sql_referential_constraint so the column can only name a position of the constraint its key references';
COMMENT ON COLUMN sql_referential_constraint_column.referenced_schema IS 'schema of the referenced constraint''s table, forwarded as the source above is';
COMMENT ON COLUMN sql_referential_constraint_column.referenced_table IS 'the referenced constraint''s table, forwarded as the source above is';
COMMENT ON COLUMN sql_referential_constraint_column.referenced_constraint_name IS 'the referenced constraint''s name, forwarded as the source above is';
COMMENT ON COLUMN sql_referential_constraint_column.referenced_position IS 'the position in the referenced constraint''s own column list that this column references, which is where the REFERENCES list puts it and not, in general, this column''s own position: SQL lets that list order the key''s columns any way it likes. A position rather than a column name, so the referenced column has one answer, the referenced constraint''s own sql_constraint_column row';
COMMENT ON COLUMN sql_referential_constraint_column.touched_at IS 'when the reading that produced this row ran, swept as sql_referential_constraint''s instant is';


CREATE TABLE sql_table_reference (
  source_name            VARCHAR NOT NULL,
  table_schema           VARCHAR NOT NULL,
  table_name             VARCHAR NOT NULL,
  referenced_source_name VARCHAR NOT NULL,
  referenced_schema      VARCHAR NOT NULL,
  referenced_table       VARCHAR NOT NULL,
  constraints            INT     NOT NULL,
  touched_at             TIMESTAMP NOT NULL,
  PRIMARY KEY (source_name, table_schema, table_name,
               referenced_source_name, referenced_schema, referenced_table)
);
COMMENT ON TABLE sql_table_reference IS 'One ordered pair of tables at least one foreign key connects, and how many connect it. For example film_actor to film is one row saying 1, and a pair two foreign keys join is one row saying 2.';
COMMENT ON COLUMN sql_table_reference.source_name IS 'the declaring table''s generated-package source, as on sql_table; the key''s leading dimension';
COMMENT ON COLUMN sql_table_reference.table_schema IS 'schema of the declaring table, the end the foreign keys sit on';
COMMENT ON COLUMN sql_table_reference.table_name IS 'the declaring table''s SQL name';
COMMENT ON COLUMN sql_table_reference.referenced_source_name IS 'the referenced table''s own generated-package source, equal to source_name for the ordinary in-package reference and different exactly where a foreign key crosses schemas codegen wrote into different packages';
COMMENT ON COLUMN sql_table_reference.referenced_schema IS 'schema of the referenced table';
COMMENT ON COLUMN sql_table_reference.referenced_table IS 'the referenced table''s SQL name. The pair is ordered: the declaring end and the referenced end are not interchangeable, and a pair keyed the other way round is a different row or no row at all';
COMMENT ON COLUMN sql_table_reference.constraints IS 'how many foreign keys connect the pair in this direction; 1 where the route between the two tables is unambiguous, which is what a reader discovering a key rather than naming one tests for. Counted here rather than by each reader, because a reader that counts is a per-row aggregate over the census and this is a fact about the catalog that does not vary with who asks';
COMMENT ON COLUMN sql_table_reference.touched_at IS 'when the reading that produced this row ran, on sql_referential_constraint''s terms: the reading finishes by deleting this source''s rows carrying a different instant. NOT NULL where that relation''s is nullable, this one having exactly one writer, and load-bearing rather than tidy: a pair row that outlives the foreign key it counted says 1 about a pair with none, which is the arm a discovering reader takes';

CREATE TABLE sql_index (
  source_name  VARCHAR NOT NULL,
  table_schema VARCHAR NOT NULL,
  table_name   VARCHAR NOT NULL,
  index_name   VARCHAR NOT NULL,
  touched_at   TIMESTAMP,
  PRIMARY KEY (source_name, table_schema, table_name, index_name),
  FOREIGN KEY (source_name, table_schema, table_name) REFERENCES sql_table (source_name, table_schema, table_name)
);
COMMENT ON TABLE sql_index IS 'One index of one table, which is the population @order(index:) and @index resolve against. For example idx_actor_last_name on public.actor.';
COMMENT ON COLUMN sql_index.source_name IS 'the owning partition''s generated-package source, as on sql_table; the key''s leading dimension';
COMMENT ON COLUMN sql_index.table_schema IS 'SQL schema the table lives in';
COMMENT ON COLUMN sql_index.table_name IS 'SQL table name';
COMMENT ON COLUMN sql_index.index_name IS 'SQL index name';
COMMENT ON COLUMN sql_index.touched_at IS 'when the reading that produced this row ran. The reading finishes by deleting this source''s rows carrying a different instant, which are the tables, columns and keys the consumer''s database no longer has and which an upsert alone cannot find. Nullable because one writer of these relations sets nothing here, and a row with no instant is not this reading''s';

CREATE TABLE sql_index_column (
  source_name  VARCHAR NOT NULL,
  table_schema VARCHAR NOT NULL,
  table_name   VARCHAR NOT NULL,
  index_name   VARCHAR NOT NULL,
  position     INT     NOT NULL,
  column_name  VARCHAR NOT NULL,
  touched_at   TIMESTAMP,
  PRIMARY KEY (source_name, table_schema, table_name, index_name, position),
  FOREIGN KEY (source_name, table_schema, table_name, index_name)
    REFERENCES sql_index (source_name, table_schema, table_name, index_name)
);
COMMENT ON TABLE sql_index_column IS 'One position in one index''s column list, naming the column that sits there. For example position 0 of idx_actor_last_name, naming last_name.';
COMMENT ON COLUMN sql_index_column.source_name IS 'the owning partition''s generated-package source, as on sql_table; the key''s leading dimension';
COMMENT ON COLUMN sql_index_column.table_schema IS 'SQL schema the table lives in';
COMMENT ON COLUMN sql_index_column.table_name IS 'SQL table name';
COMMENT ON COLUMN sql_index_column.index_name IS 'SQL index name';
COMMENT ON COLUMN sql_index_column.position IS '0-based position in the index''s column list';
COMMENT ON COLUMN sql_index_column.column_name IS 'SQL column name';
COMMENT ON COLUMN sql_index_column.touched_at IS 'when the reading that produced this row ran. The reading finishes by deleting this source''s rows carrying a different instant, which are the tables, columns and keys the consumer''s database no longer has and which an upsert alone cannot find. Nullable because one writer of these relations sets nothing here, and a row with no instant is not this reading''s';

CREATE TABLE sql_routine (
  source_name          VARCHAR NOT NULL,
  table_schema         VARCHAR NOT NULL,
  routine_name         VARCHAR NOT NULL,
  routine_type         VARCHAR NOT NULL,
  routines_class_fqn   VARCHAR,
  routines_method_name VARCHAR,
  routine_name_upper   VARCHAR GENERATED ALWAYS AS (UPPER(routine_name)),
  touched_at           TIMESTAMP,
  PRIMARY KEY (source_name, table_schema, routine_name),
  FOREIGN KEY (source_name) REFERENCES store_source (source_name),
  FOREIGN KEY (source_name, table_schema) REFERENCES sql_schema (source_name, table_schema)
);
COMMENT ON TABLE sql_routine IS 'One callable the consumer''s catalog declares. For example the table-valued function public.films_for_actor, whose generated call surface is the Routines method filmsForActor.';
COMMENT ON COLUMN sql_routine.source_name IS 'the owning partition''s generated-package source, as on sql_table; the key''s leading dimension';
COMMENT ON COLUMN sql_routine.table_schema IS 'SQL schema the routine lives in';
COMMENT ON COLUMN sql_routine.routine_name IS 'SQL routine name; for a table-valued function this is also its sql_table row''s table_name, the two being one database object read two ways. The key inherits sql_table''s one hole with it: an overload set sharing a SQL name collides in both relations, jOOQ distinguishing overloads only by generated class name';
COMMENT ON COLUMN sql_routine.routine_type IS 'the standard''s ROUTINE_TYPE vocabulary: FUNCTION or PROCEDURE. FUNCTION for a table-valued function and for a scalar function, PROCEDURE for a routine that returns no value; a routine with a sql_table row of the same name is table-valued, one without is called through its Configuration-first method. It is the discriminator that lets the other form arrive without reshaping, which is the whole argument for a supertype relation';
COMMENT ON COLUMN sql_routine.routines_class_fqn IS 'the fully qualified name of the generated Routines class carrying this routine''s call surface, or NULL when the generated model exposes none. Captured beside the method name because the parameters below are a fact about one method: jOOQ generates several forms per routine (a Configuration-first execute form, a value-parameter form, a Field-expression form), and a parameter list that did not name its method would not say which one it described. NULL here and on the method name is also what distinguishes a routine with no parameters from one whose call surface the generated model does not expose, the two being the same zero rows in sql_routine_parameter otherwise.';
COMMENT ON COLUMN sql_routine.routines_method_name IS 'the Routines-class method the parameters below describe: the value-parameter form, the one an emitted FROM clause calls, for a table-valued function, and the Configuration-first execute form for a routine that is no table. NULL exactly when routines_class_fqn is';
COMMENT ON COLUMN sql_routine.routine_name_upper IS 'the upper-cased form of the column beside it, for the case-insensitive match against a routine name an author writes in a configuration; generated so a reading never has to know the folding';
CREATE INDEX sql_routine_name_upper_ix ON sql_routine (routine_name_upper, source_name);
COMMENT ON COLUMN sql_routine.touched_at IS 'when the reading that produced this row ran. The reading finishes by deleting this source''s rows carrying a different instant, which are the tables, columns and keys the consumer''s database no longer has and which an upsert alone cannot find. Nullable because one writer of these relations sets nothing here, and a row with no instant is not this reading''s';

CREATE TABLE sql_routine_parameter (
  source_name  VARCHAR NOT NULL,
  table_schema VARCHAR NOT NULL,
  routine_name VARCHAR NOT NULL,
  position     INT     NOT NULL,
  jooq_name    VARCHAR NOT NULL,
  binding_type VARCHAR NOT NULL,
  sql_name     VARCHAR,
  touched_at   TIMESTAMP,
  PRIMARY KEY (source_name, table_schema, routine_name, position),
  FOREIGN KEY (source_name, table_schema, routine_name)
    REFERENCES sql_routine (source_name, table_schema, routine_name)
);
COMMENT ON TABLE sql_routine_parameter IS 'One position in one routine''s call-surface parameter list, as the generated method takes it. For example position 0 of public.films_for_actor, a java.lang.Integer the generated method names pActorId.';
COMMENT ON COLUMN sql_routine_parameter.source_name IS 'the owning partition''s generated-package source, as on sql_table; the key''s leading dimension';
COMMENT ON COLUMN sql_routine_parameter.table_schema IS 'SQL schema the routine lives in';
COMMENT ON COLUMN sql_routine_parameter.routine_name IS 'SQL routine name';
COMMENT ON COLUMN sql_routine_parameter.position IS '0-based position in the call surface''s parameter list, which is the routine''s declaration order';
COMMENT ON COLUMN sql_routine_parameter.jooq_name IS 'the generated method parameter''s Java name, read reflectively; jOOQ''s camelCase transform of the database''s own parameter name, and the closest this relation gets to it. Reflection reports it only when the consumer compiled their jOOQ output with -parameters, and reports arg0, arg1 otherwise. The generator already depends on that flag, matching @routine(argMapping:) against these names, so recording the name makes an existing dependency visible rather than creating one.';
COMMENT ON COLUMN sql_routine_parameter.binding_type IS 'the fully qualified Java type the generated method takes at this position, as on sql_column.binding_type. Unlike a column, a parameter carries no declared SQL type beside it: jOOQ generates no Routine object for a table-valued function, so the declared type survives only as an anonymous bind placeholder behind a protected field on TableImpl, and was left out rather than shipped always-null';
COMMENT ON COLUMN sql_routine_parameter.sql_name IS 'the database''s own name for the parameter, read off the generated Routine class, for a routine that is no table: a name an author writes in a configuration, which jooq_name only camelCases. NULL on a table-valued function''s parameter, whose reading never asked for it';
COMMENT ON COLUMN sql_routine_parameter.touched_at IS 'when the reading that produced this row ran. The reading finishes by deleting this source''s rows carrying a different instant, which are the tables, columns and keys the consumer''s database no longer has and which an upsert alone cannot find. Nullable because one writer of these relations sets nothing here, and a row with no instant is not this reading''s';

CREATE TABLE sql_node_metadata (
  source_name       VARCHAR NOT NULL,
  table_schema      VARCHAR NOT NULL,
  table_name        VARCHAR NOT NULL,
  type_id           VARCHAR NOT NULL,
  touched_at        TIMESTAMP,
  PRIMARY KEY (source_name, table_schema, table_name),
  FOREIGN KEY (source_name, table_schema, table_name)
    REFERENCES sql_table (source_name, table_schema, table_name),
  CHECK (type_id <> '')
);
COMMENT ON TABLE sql_node_metadata IS 'One table whose generated jOOQ class publishes node-identity metadata graphitron can use. For example a film table class stating a type id of film and a key-columns array naming film_id, against a table class stating neither, which has no row here at all.';
COMMENT ON COLUMN sql_node_metadata.source_name IS 'the owning partition''s generated-package source, as on sql_table; the key''s leading dimension';
COMMENT ON COLUMN sql_node_metadata.table_schema IS 'SQL schema the table lives in';
COMMENT ON COLUMN sql_node_metadata.table_name IS 'SQL table name. With the two columns above this is sql_table''s full key: the metadata is a property of the table rather than of the class, which is why the key is the table''s and not a class name';
COMMENT ON COLUMN sql_node_metadata.type_id IS 'the type id the class states, a non-empty string';
COMMENT ON COLUMN sql_node_metadata.touched_at IS 'when the reading that produced this row ran. The reading finishes by deleting this source''s rows carrying a different instant, which are the tables, columns and keys the consumer''s database no longer has and the metadata a class no longer publishes';

CREATE TABLE sql_node_key_column (
  source_name  VARCHAR NOT NULL,
  table_schema VARCHAR NOT NULL,
  table_name   VARCHAR NOT NULL,
  position     INT     NOT NULL,
  column_name  VARCHAR NOT NULL,
  touched_at   TIMESTAMP,
  PRIMARY KEY (source_name, table_schema, table_name, position),
  FOREIGN KEY (source_name, table_schema, table_name)
    REFERENCES sql_node_metadata (source_name, table_schema, table_name),
  FOREIGN KEY (source_name, table_schema, table_name, column_name)
    REFERENCES sql_column (source_name, table_schema, table_name, column_name)
);
COMMENT ON TABLE sql_node_key_column IS 'One position in the key-columns array of a table whose node metadata graphitron can use, naming the column it resolves to. For example position 0 of a film table class''s array, naming film_id.';
COMMENT ON COLUMN sql_node_key_column.source_name IS 'the owning partition''s generated-package source, as on sql_table; the key''s leading dimension';
COMMENT ON COLUMN sql_node_key_column.table_schema IS 'SQL schema the table lives in';
COMMENT ON COLUMN sql_node_key_column.table_name IS 'SQL table name';
COMMENT ON COLUMN sql_node_key_column.position IS '0-based index in the stated array, recorded rather than reconstructed: the encoded identity depends on the declared order, so a reader that recovered the order from the table''s columns or from a key would encode ids that disagree with the ones already issued';
COMMENT ON COLUMN sql_node_key_column.column_name IS 'the table''s column the entry names, by its SQL name';
COMMENT ON COLUMN sql_node_key_column.touched_at IS 'when the reading that produced this row ran, swept with sql_node_metadata';

CREATE TABLE sql_node_metadata_unreadable (
  source_name  VARCHAR NOT NULL,
  table_schema VARCHAR NOT NULL,
  table_name   VARCHAR NOT NULL,
  touched_at   TIMESTAMP,
  PRIMARY KEY (source_name, table_schema, table_name),
  FOREIGN KEY (source_name, table_schema, table_name)
    REFERENCES sql_table (source_name, table_schema, table_name)
);
COMMENT ON TABLE sql_node_metadata_unreadable IS 'One table whose generated class declares node-identity metadata graphitron cannot use. For example a table class stating __NODE_TYPE_ID and no __NODE_KEY_COLUMNS, or a key-columns array naming a column the table does not have.';
COMMENT ON COLUMN sql_node_metadata_unreadable.source_name IS 'the owning partition''s generated-package source, as on sql_table; the key''s leading dimension';
COMMENT ON COLUMN sql_node_metadata_unreadable.table_schema IS 'SQL schema the table lives in';
COMMENT ON COLUMN sql_node_metadata_unreadable.table_name IS 'SQL table name; with the two columns above, sql_table''s key';
COMMENT ON COLUMN sql_node_metadata_unreadable.touched_at IS 'when the reading that produced this row ran, swept with the catalog''s other rows';

CREATE TABLE sql_node_legacy_key_column (
  source_name  VARCHAR NOT NULL,
  table_schema VARCHAR NOT NULL,
  table_name   VARCHAR NOT NULL,
  position     INT     NOT NULL,
  column_name  VARCHAR NOT NULL,
  touched_at   TIMESTAMP,
  PRIMARY KEY (source_name, table_schema, table_name, position),
  FOREIGN KEY (source_name, table_schema, table_name)
    REFERENCES sql_node_metadata (source_name, table_schema, table_name),
  FOREIGN KEY (source_name, table_schema, table_name, column_name)
    REFERENCES sql_column (source_name, table_schema, table_name, column_name)
);
COMMENT ON TABLE sql_node_legacy_key_column IS 'One position in the legacy key-columns array of a table whose node metadata graphitron can use, naming the column it resolves to. For example position 2 of an inventory table class''s __NODE_LEGACY_KEY_COLUMNS, naming last_update.';
COMMENT ON COLUMN sql_node_legacy_key_column.source_name IS 'the owning partition''s generated-package source, as on sql_table; the key''s leading dimension';
COMMENT ON COLUMN sql_node_legacy_key_column.table_schema IS 'SQL schema the table lives in';
COMMENT ON COLUMN sql_node_legacy_key_column.table_name IS 'SQL table name. The foreign key is into sql_node_metadata, so a legacy array on a class publishing no usable identity pair has no row here';
COMMENT ON COLUMN sql_node_legacy_key_column.position IS '0-based index in the stated array, recorded rather than reconstructed: it is the order the values sit in inside every id issued under the old key';
COMMENT ON COLUMN sql_node_legacy_key_column.column_name IS 'the table''s column the entry names, by its SQL name';
COMMENT ON COLUMN sql_node_legacy_key_column.touched_at IS 'when the reading that produced this row ran, swept with sql_node_metadata';

CREATE TABLE sql_node_legacy_key_unreadable (
  source_name  VARCHAR NOT NULL,
  table_schema VARCHAR NOT NULL,
  table_name   VARCHAR NOT NULL,
  touched_at   TIMESTAMP,
  PRIMARY KEY (source_name, table_schema, table_name),
  FOREIGN KEY (source_name, table_schema, table_name)
    REFERENCES sql_table (source_name, table_schema, table_name)
);
COMMENT ON TABLE sql_node_legacy_key_unreadable IS 'One table whose generated class declares a legacy node key-columns array graphitron cannot use. For example a table class stating __NODE_LEGACY_KEY_COLUMNS with a null entry, or stating it with no usable __NODE_TYPE_ID and __NODE_KEY_COLUMNS beside it.';
COMMENT ON COLUMN sql_node_legacy_key_unreadable.source_name IS 'the owning partition''s generated-package source, as on sql_table; the key''s leading dimension';
COMMENT ON COLUMN sql_node_legacy_key_unreadable.table_schema IS 'SQL schema the table lives in';
COMMENT ON COLUMN sql_node_legacy_key_unreadable.table_name IS 'SQL table name; with the two columns above, sql_table''s key';
COMMENT ON COLUMN sql_node_legacy_key_unreadable.touched_at IS 'when the reading that produced this row ran, swept with the catalog''s other rows';

CREATE TABLE graphitron_tabletype (
  graph_name        VARCHAR NOT NULL,
  type_name         VARCHAR NOT NULL,
  named_type_kind   VARCHAR NOT NULL,
  table_source_name VARCHAR NOT NULL,
  table_schema      VARCHAR NOT NULL,
  table_name        VARCHAR NOT NULL,
  PRIMARY KEY (graph_name, type_name),
  -- The type and the kind it is: boundness is a fact about an object or an interface, so a table
  -- is a type of one of those kinds, held there by the supertype's own key. Cascading, a type that
  -- stops being one, or changes kind, having no binding to keep.
  FOREIGN KEY (graph_name, type_name, named_type_kind)
    REFERENCES graphitron_type (graph_name, type_name, kind) ON DELETE CASCADE,
  CHECK (named_type_kind IN ('OBJECT', 'INTERFACE')),
  FOREIGN KEY (table_source_name, table_schema, table_name)
    REFERENCES sql_table (source_name, table_schema, table_name) ON DELETE CASCADE,
  -- Free, the primary key already implying it, and what lets a relation carrying both a type and
  -- the table it resolved to reference the pair rather than each half separately.
  UNIQUE (graph_name, type_name, table_source_name, table_schema, table_name)
);
COMMENT ON TABLE graphitron_tabletype IS 'A graph type that resolved to exactly one catalog table: one row per type whose @table spelling the catalog answered unambiguously. For example a Film type over @table(name: "film") draws a row naming the film table in the schema that declares it, while a spelling two schemas both declare draws none and is found by anti-join against the entry the author wrote.';
COMMENT ON COLUMN graphitron_tabletype.graph_name IS 'the owning graph''s partition, anchored by store_graph; the leading key dimension that keeps one workspace''s graphs apart';
COMMENT ON COLUMN graphitron_tabletype.type_name IS 'the graph type the binding is for, anchored by graphql_type through its kind. With the graph this is the whole key, and that is the resolution''s own claim: a type resolving to two tables is not a row here, so the key is what says the binding is settled rather than a count beside it saying how settled';
COMMENT ON COLUMN graphitron_tabletype.named_type_kind IS 'which of the six named type kinds the bound type is, OBJECT or INTERFACE, carried here so the reference into graphql_type can name the pair and the store can refuse a binding on a kind that cannot carry one. Not a fact of its own and not a second answer to what kind a type is: the foreign key is what makes it the same answer, and a row disagreeing with the type relation cannot be written. A union, a scalar or an enum with a @table on it resolves to no row here at all, which puts the author''s mistake where every other unresolved application already sits, the anti-join against the @table applications';
COMMENT ON COLUMN graphitron_tabletype.table_source_name IS 'the codegen source the table came from, the first of the three columns naming one catalog table';
COMMENT ON COLUMN graphitron_tabletype.table_schema IS 'the table''s schema as the catalog spells it';
COMMENT ON COLUMN graphitron_tabletype.table_name IS 'the table''s own name as the catalog spells it; with the two columns above, a foreign key into sql_table, which is what a resolved binding can carry and an unresolved one cannot. The first crossing in this schema from a graph-keyed relation into the source-keyed catalog, and it cascades on delete, which is what makes the crossing sound rather than merely permitted: a catalog source is shared between graphs and recrawled whole, so without the cascade a source could not be recrawled while any graph still named its tables. With it, a recrawled source takes the bindings that named it, and the graphs concerned rebuild theirs the next time they capture. That is the honest outcome of the two available: a reader finds no binding rather than one naming a table the catalog no longer has, which is what the relations this replaces leave behind because they carry no key here at all';
-- The types over one table, which a rule asking what is bound to a table probes per candidate
-- row: graph first, so the probe stays inside the graph its writer reads.
CREATE INDEX graphitron_tabletype_table_ix
  ON graphitron_tabletype (graph_name, table_source_name, table_schema, table_name);

CREATE TABLE graphitron_node (
  graph_name     VARCHAR NOT NULL,
  type_name      VARCHAR NOT NULL,
  type_id        VARCHAR NOT NULL,
  type_id_origin VARCHAR NOT NULL,
  resolvable     BOOLEAN NOT NULL,
  PRIMARY KEY (graph_name, type_name),
  FOREIGN KEY (graph_name, type_name) REFERENCES graphitron_tabletype (graph_name, type_name)
    ON DELETE CASCADE,
  CHECK (type_id_origin IN ('SDL_DECLARED', 'JOOQ_METADATA', 'TYPE_NAME'))
);
COMMENT ON TABLE graphitron_node IS 'Which of a graph''s types are nodes, with the wire type id each answers to: one row per node type, from the authored population and the published one alike. For example a Customer carrying @node over @table draws a row, a type merely implementing Node over a table whose class publishes __NODE_TYPE_ID draws one beside it, and a @node on a type with no @table draws none.';
COMMENT ON COLUMN graphitron_node.graph_name IS 'the owning graph''s partition, anchored by store_graph; the leading key dimension that keeps one workspace''s graphs apart';
COMMENT ON COLUMN graphitron_node.type_name IS 'the type that is a node. The foreign key is into graphitron_tabletype rather than into the type coordinate, and that is the relation''s central claim: @node only takes effect on a type that also carries @table, so a node is a table-bound type before it is anything else and one that is not table bound cannot be a row here. A @node written on a type with no binding is a @node application in graphql_directive_application and no row here, and the anti-join between the two is where an author is told so. Cascading on delete, the dependency being existential rather than merely referential: a type that stops resolving to a table stops being a node, and the two are rewritten in one pass by the same gatherer';
COMMENT ON COLUMN graphitron_node.type_id IS 'the wire type id this node answers to, resolved rather than as written: what the author declared where they declared one, what the backing class publishes where they did not, and the type''s own name where neither says. Never null, the last of those three always answering, so a reader encoding an id needs no fallback of its own';
COMMENT ON COLUMN graphitron_node.type_id_origin IS 'which of the three answered, in the order they are tried: SDL_DECLARED from @node(typeId:), JOOQ_METADATA from the backing class''s __NODE_TYPE_ID, TYPE_NAME from the type itself. Carried because a diagnostic that says an id collides has to say where each came from, and because the tiers are a precedence a reader must not re-derive. The key columns'' own origin is a separate column on a separate relation, the two axes being independent: an author may declare the id and leave the columns to the catalog, or the reverse';
COMMENT ON COLUMN graphitron_node.resolvable IS 'whether this subgraph fetches the node by its id: false where the type''s first @node says resolvable: false, true otherwise, a node the backing class publishes included. A node that is not resolvable is one another subgraph owns, and a node like any other: it implements Node, its id binds, encodes and decodes like any node''s and its type id counts towards the graph''s uniqueness. Only what fetches by id reads this: Query.node and nodes answer its id with null, and federation gets no key minted for it';

CREATE TABLE graphitron_node_table (
  graph_name        VARCHAR   NOT NULL,
  table_source_name VARCHAR   NOT NULL,
  table_schema      VARCHAR   NOT NULL,
  table_name        VARCHAR   NOT NULL,
  node_count        INT       NOT NULL,
  node_type_name    VARCHAR,
  touched_at        TIMESTAMP NOT NULL,
  PRIMARY KEY (graph_name, table_source_name, table_schema, table_name),
  FOREIGN KEY (graph_name) REFERENCES store_graph (graph_name),
  FOREIGN KEY (table_source_name, table_schema, table_name)
    REFERENCES sql_table (source_name, table_schema, table_name) ON DELETE CASCADE,
  FOREIGN KEY (graph_name, node_type_name) REFERENCES graphitron_node (graph_name, type_name)
    ON DELETE CASCADE,
  CHECK (node_count >= 1),
  CHECK ((node_count = 1) = (node_type_name IS NOT NULL))
);
COMMENT ON TABLE graphitron_node_table IS 'A table at least one node of a graph declares itself over: one row per graph and table, with how many nodes do and, where one alone does, which. For example a film table only Film is bound to draws (film, 1, Film), and one Film and FilmAlias are both bound to draws (film, 2) with no node.';
COMMENT ON COLUMN graphitron_node_table.graph_name IS 'the owning graph''s partition';
COMMENT ON COLUMN graphitron_node_table.table_source_name IS 'the codegen source the table came from';
COMMENT ON COLUMN graphitron_node_table.table_schema IS 'the table''s schema as the catalog spells it';
COMMENT ON COLUMN graphitron_node_table.table_name IS 'the table''s own name; with the graph and the two columns above, the grain';
COMMENT ON COLUMN graphitron_node_table.node_count IS 'how many of the graph''s nodes are bound to the table, at least one: a table no node is over has no row, so a reader asking for the one node over a table tells none from several by the row''s absence or this count';
COMMENT ON COLUMN graphitron_node_table.node_type_name IS 'the node, where it is the only one over the table, and null where several are, so the one node over a table is a lookup rather than a count and a second probe for another node';
COMMENT ON COLUMN graphitron_node_table.touched_at IS 'the reading that last wrote this row; the sweep deletes the rows an older reading wrote';

CREATE VIEW graphitron_node_table_rule
  (graph_name, table_source_name, table_schema, table_name, node_count, node_type_name) AS
SELECT b.graph_name, b.table_source_name, b.table_schema, b.table_name, CAST(COUNT(*) AS INT),
       CASE WHEN COUNT(*) = 1 THEN MIN(n.type_name) END
  FROM graphitron_tabletype b
  JOIN graphitron_node n ON n.graph_name = b.graph_name AND n.type_name = b.type_name
 GROUP BY b.graph_name, b.table_source_name, b.table_schema, b.table_name;
COMMENT ON VIEW graphitron_node_table_rule IS 'A table at least one node of a graph declares itself over: one row per graph and table, with how many nodes do and, where one alone does, which, in the shape graphitron_node_table stores. For example a film table only Film is bound to draws (film, 1, Film).';

-- A @nodeId whose typeName: names an interface or union that is no node itself: an id of several
-- node types, decoded per member. Stated once at the claim, which names the type, so the decode
-- shape and the container defects ask one relation rather than each joining the type and the node
-- again.
CREATE TABLE graphitron_binding_claim_container (
  graph_name     VARCHAR   NOT NULL,
  coordinate     VARCHAR   NOT NULL,
  kind           VARCHAR   NOT NULL,
  claimer        VARCHAR   NOT NULL,
  touched_at     TIMESTAMP NOT NULL,
  PRIMARY KEY (graph_name, coordinate, kind, claimer),
  FOREIGN KEY (graph_name, coordinate, kind, claimer)
    REFERENCES graphitron_binding_claim (graph_name, coordinate, kind, claimer) ON DELETE CASCADE,
  CHECK (kind = 'NODE_ID')
);
COMMENT ON TABLE graphitron_binding_claim_container IS 'A @nodeId naming an interface or union that is no node type itself: one row per NODE_ID binding claim naming one, the claim naming the type. For example an argument carrying @nodeId(typeName: "AddressOccupant"), a union of Customer and Staff, has a row, and one naming Film has none.';
COMMENT ON COLUMN graphitron_binding_claim_container.graph_name IS 'the owning graph''s partition';
COMMENT ON COLUMN graphitron_binding_claim_container.coordinate IS 'the declared element claiming, an argument or an input field';
COMMENT ON COLUMN graphitron_binding_claim_container.kind IS 'always NODE_ID, pinned so the foreign key holds the row to a node id claim';
COMMENT ON COLUMN graphitron_binding_claim_container.claimer IS 'the element itself';
COMMENT ON COLUMN graphitron_binding_claim_container.touched_at IS 'the reading that last wrote this row; the sweep deletes the rows an older reading wrote';

CREATE VIEW graphitron_binding_claim_container_rule
  (graph_name, coordinate, kind, claimer) AS
SELECT cl.graph_name, cl.coordinate, cl.kind, cl.claimer
  FROM graphitron_binding_claim cl
  JOIN graphitron_type t
    ON t.graph_name = cl.graph_name AND t.type_name = cl.named AND t.kind IN ('INTERFACE', 'UNION')
 WHERE cl.kind = 'NODE_ID'
   AND NOT EXISTS (SELECT 1 FROM graphitron_node n
                    WHERE n.graph_name = cl.graph_name AND n.type_name = cl.named);
COMMENT ON VIEW graphitron_binding_claim_container_rule IS 'A @nodeId naming an interface or union that is no node type itself: one row per NODE_ID binding claim naming one, the claim naming the type, in the shape graphitron_binding_claim_container stores. For example an argument carrying @nodeId(typeName: "AddressOccupant"), a union of Customer and Staff, has a row, and one naming Film has none.';

CREATE TABLE graphitron_node_keycolumn (
  graph_name        VARCHAR NOT NULL,
  type_name         VARCHAR NOT NULL,
  position          INT     NOT NULL,
  column_name       VARCHAR NOT NULL,
  column_origin     VARCHAR NOT NULL,
  table_source_name VARCHAR NOT NULL,
  table_schema      VARCHAR NOT NULL,
  table_name        VARCHAR NOT NULL,
  column_name_upper VARCHAR GENERATED ALWAYS AS (UPPER(column_name)),
  PRIMARY KEY (graph_name, type_name, position),
  FOREIGN KEY (graph_name, type_name) REFERENCES graphitron_node (graph_name, type_name)
    ON DELETE CASCADE,
  FOREIGN KEY (graph_name, type_name, table_source_name, table_schema, table_name)
    REFERENCES graphitron_tabletype
      (graph_name, type_name, table_source_name, table_schema, table_name) ON DELETE CASCADE,
  FOREIGN KEY (table_source_name, table_schema, table_name, column_name)
    REFERENCES sql_column (source_name, table_schema, table_name, column_name) ON DELETE CASCADE,
  CHECK (position >= 0),
  CHECK (column_origin IN ('SDL_PINNED', 'JOOQ_METADATA', 'CATALOG_PRIMARY_KEY'))
);
COMMENT ON TABLE graphitron_node_keycolumn IS 'A node type''s key columns, in key order and resolved against the table it is bound to: one row per position, naming a column the catalog has. For example a Customer over the customer table draws its primary key columns, an author pinning keyColumns: ["email"] draws that column instead, and a pinned name the table does not have draws nothing at all.';
COMMENT ON COLUMN graphitron_node_keycolumn.graph_name IS 'the owning graph''s partition, carried from the node whose key this is';
COMMENT ON COLUMN graphitron_node_keycolumn.type_name IS 'the node type this column is part of the identity of. The foreign key is into graphitron_node, so a type that is not a node has no key columns here however well its table is keyed: the two questions are asked in that order and only one of them is about the catalog';
COMMENT ON COLUMN graphitron_node_keycolumn.position IS 'the column''s place in the key tuple, numbered from zero in the order ids are built and read. The order is the whole reason this is a relation of its own rather than a list on the node: an id encoded against one order and decoded against another finds the wrong row rather than failing';
COMMENT ON COLUMN graphitron_node_keycolumn.column_name IS 'the catalog column, spelled as the catalog spells it and not as whoever named it did. A pinned keyColumns entry and a generated class''s constant are both authored spellings that meet a catalog name here, so both are folded to resolve and neither spelling survives into this column; what was written stays in graphitron_ast_node_keycolumn_entry and in sql_node_key_column respectively';
COMMENT ON COLUMN graphitron_node_keycolumn.column_origin IS 'which of the three populations answered: SDL_PINNED from @node(keyColumns:), JOOQ_METADATA from the backing class''s __NODE_KEY_COLUMNS, CATALOG_PRIMARY_KEY from the bound table''s own key. Repeated on every position rather than held once per type, the tier being uniform across a key tuple by construction: one tier answers for the whole list or none does, so the repetition is a functional dependency inside a derived relation and not a second grain';
COMMENT ON COLUMN graphitron_node_keycolumn.column_name_upper IS 'the case fold of the column, stored so a reader matching an authored spelling against it compares two stored values and an index can serve. Minted here rather than left to each reader because this is where an authored name meets a catalog one and the crossing happens once: before this relation the answer was a spelling with nowhere to reach, so every consumer folded at its own join. It duplicates sql_column''s own fold of the same value, deliberately, the alternative being a join per reader for a column this relation already carries';
COMMENT ON COLUMN graphitron_node_keycolumn.table_source_name IS 'the catalog source declaring the table this column belongs to. Carried, with the schema and table beside it, so the row can reference both the type''s binding and the column itself: without them the relation could name a column of some other table and nothing would say so';
COMMENT ON COLUMN graphitron_node_keycolumn.table_schema IS 'the bound table''s schema, half of the reference that ties this column to the type''s own binding rather than to any table having such a column';
COMMENT ON COLUMN graphitron_node_keycolumn.table_name IS 'the bound table, cascading with the catalog that declares it: a recrawled source takes its columns and these rows with it, which is the same lifetime rule graphitron_tabletype carries';

CREATE TABLE graphitron_node_legacy_keycolumn (
  graph_name        VARCHAR NOT NULL,
  type_id           VARCHAR NOT NULL,
  position          INT     NOT NULL,
  column_name       VARCHAR NOT NULL,
  current_position  INT,
  column_origin     VARCHAR NOT NULL,
  table_source_name VARCHAR NOT NULL,
  table_schema      VARCHAR NOT NULL,
  table_name        VARCHAR NOT NULL,
  PRIMARY KEY (graph_name, type_id, position),
  UNIQUE (graph_name, type_id, column_name),
  UNIQUE (graph_name, type_id, current_position),
  FOREIGN KEY (graph_name) REFERENCES store_graph (graph_name) ON DELETE CASCADE,
  FOREIGN KEY (table_source_name, table_schema, table_name, column_name)
    REFERENCES sql_column (source_name, table_schema, table_name, column_name) ON DELETE CASCADE,
  CHECK (position >= 0),
  CHECK (current_position IS NULL OR current_position >= 0),
  CHECK (column_origin IN ('SDL_PINNED', 'JOOQ_METADATA'))
);
COMMENT ON TABLE graphitron_node_legacy_keycolumn IS 'One position of the legacy key shape a wire type id answers to in a graph, resolved against the table the type id''s ids are rows of. For example type id RentalItem with keyColumns ["rental_id"] and legacyKeyColumns ["customer_id", "rental_id", "rental_date"] draws three rows, rental_id at position 1 with current position 0.';
COMMENT ON COLUMN graphitron_node_legacy_keycolumn.graph_name IS 'the owning graph''s partition';
COMMENT ON COLUMN graphitron_node_legacy_keycolumn.type_id IS 'the wire type id whose old ids carry this shape. Keyed by the type id rather than by a type, because an id names its id space by type id and the runtime that converts an id knows nothing else about its target';
COMMENT ON COLUMN graphitron_node_legacy_keycolumn.position IS 'the value''s place inside an id issued under the old key, numbered from zero';
COMMENT ON COLUMN graphitron_node_legacy_keycolumn.column_name IS 'the catalog column, spelled as the catalog spells it';
COMMENT ON COLUMN graphitron_node_legacy_keycolumn.current_position IS 'the column''s place in the current key, null for a column the current key dropped: the pick a conversion makes, computed once here rather than by matching names where the conversion is emitted';
COMMENT ON COLUMN graphitron_node_legacy_keycolumn.column_origin IS 'which statement the shape came from: SDL_PINNED from @node(legacyKeyColumns:), JOOQ_METADATA from the bound table class''s __NODE_LEGACY_KEY_COLUMNS. Carried because the fix for a catalog-origin defect is in the generator configuration, not the schema';
COMMENT ON COLUMN graphitron_node_legacy_keycolumn.table_source_name IS 'the catalog source declaring the table the type id''s ids are rows of';
COMMENT ON COLUMN graphitron_node_legacy_keycolumn.table_schema IS 'that table''s schema';
COMMENT ON COLUMN graphitron_node_legacy_keycolumn.table_name IS 'that table, cascading with the catalog that declares it';

CREATE TABLE graphitron_node_legacy_key_defect (
  graph_name VARCHAR NOT NULL,
  type_name  VARCHAR NOT NULL,
  code       VARCHAR NOT NULL,
  detail     VARCHAR NOT NULL,
  site       VARCHAR NOT NULL,
  PRIMARY KEY (graph_name, type_name, code),
  FOREIGN KEY (graph_name, type_name) REFERENCES graphitron_tabletype (graph_name, type_name)
    ON DELETE CASCADE,
  CHECK (code IN ('NODE_LEGACY_KEY_COLUMN_UNRESOLVED', 'NODE_LEGACY_KEY_MISSES_KEY_COLUMN',
                  'NODE_LEGACY_KEY_REORDERS_KEY', 'NODE_LEGACY_KEY_REPEATS_COLUMN',
                  'NODE_LEGACY_KEY_DISAGREES_WITH_METADATA', 'NODE_LEGACY_TYPE_ID_SHARED')),
  CHECK (site IN ('NODE', 'TABLE'))
);
COMMENT ON TABLE graphitron_node_legacy_key_defect IS 'One rule a table-bound type''s legacy key shape breaks, in one graph, which is why the shape its type id answers to is not anchored. For example an InventoryItem whose legacyKeyColumns leave out its current key column inventory_id gives one NODE_LEGACY_KEY_MISSES_KEY_COLUMN row whose detail is inventory_id.';
COMMENT ON COLUMN graphitron_node_legacy_key_defect.graph_name IS 'the owning graph''s partition';
COMMENT ON COLUMN graphitron_node_legacy_key_defect.type_name IS 'the table-bound type whose statement of the shape, or whose share of the type id, breaks the rule';
COMMENT ON COLUMN graphitron_node_legacy_key_defect.code IS 'the rule, as graphitron_defect_type names it';
COMMENT ON COLUMN graphitron_node_legacy_key_defect.detail IS 'what the author fixes: the spelling or column the rule failed on, or the shared type id';
COMMENT ON COLUMN graphitron_node_legacy_key_defect.site IS 'where the editor points: NODE for a shape the type''s @node states, TABLE for one its table class states or a type id it shares, which every bound type carries a @table for';


-- ==== What a schema may name in Java ==============================================
-- One relation per thing an author writes, rather than one index of every class. A census answers
-- what the classpath holds, so its one scope rule has to serve every reader and serves none of
-- them exactly; an arm answers what may be written at one directive and carries the predicate that
-- decides it.
-- The methods are held once. Whether a method may be named at @service and whether it may be
-- named at @condition are two questions and two relations, but what the method returns, what it
-- takes and what it throws are properties of the declaration and do not vary by the coordinate
-- somebody reached it through. So code_method and its satellites hold those once and the arms are
-- membership over them. The population is the reactor's public methods, which is what makes this
-- affordable and what keeps it from being a census: the classpath's other hundred thousand
-- methods are nobody's to name.

CREATE TABLE code_class (
  source_name VARCHAR NOT NULL,
  class_name  VARCHAR NOT NULL,
  file_path   VARCHAR NOT NULL,
  touched_at  TIMESTAMP NOT NULL,
  PRIMARY KEY (source_name, class_name),
  FOREIGN KEY (source_name, file_path)
    REFERENCES store_class_file (source_name, file_path) ON DELETE CASCADE
);
COMMENT ON TABLE code_class IS 'One class the reading read, and the file under the entry it was read out of. For example a consumer''s FilmService on the reactor''s own output, beside a jOOQ interface on a declared jar.';
COMMENT ON COLUMN code_class.file_path IS 'the file it was read out of, under that entry. Not part of the key, a file being free to declare more than one class; the foreign key is what lets a file the next reading does not find take its classes, and their members, with it';
COMMENT ON COLUMN code_class.source_name IS 'the classpath entry the class was read from; the key''s leading dimension, and the reason one name declared by two entries is two classes. A graph resolves a name to one of them through code_graph_class, which holds the copy its classpath order puts first; a reader that wants every entry declaring a name, to name the entry in a refusal, reaches this relation through store_graph_source';
COMMENT ON COLUMN code_class.class_name IS 'the fully-qualified binary name as the classfile spells it';
COMMENT ON COLUMN code_class.touched_at IS 'when the reading that produced this row ran; swept with the entry it was read from';

CREATE TABLE code_graph_class (
  graph_name  VARCHAR   NOT NULL,
  class_name  VARCHAR   NOT NULL,
  source_name VARCHAR   NOT NULL,
  touched_at  TIMESTAMP NOT NULL,
  PRIMARY KEY (graph_name, class_name),
  FOREIGN KEY (graph_name, source_name)
    REFERENCES store_graph_source (graph_name, source_name) ON DELETE CASCADE,
  FOREIGN KEY (source_name, class_name)
    REFERENCES code_class (source_name, class_name) ON DELETE CASCADE
);
CREATE INDEX code_graph_class_source_ix ON code_graph_class (source_name, class_name);
COMMENT ON INDEX code_graph_class_source_ix IS 'Serves the cascade from code_class: an entry the next reading no longer finds deletes its classes, and each deletes the rows naming it here, which the primary key, leading with the graph, cannot find without a scan.';
COMMENT ON TABLE code_graph_class IS 'The class a graph''s name resolves to: one row per class name any entry on the graph''s classpath declares, naming the entry whose copy the graph sees. For example a FilmService on the consumer''s own output and on a library jar listed after it is one row naming the output. The sakila example graph holds 5,403 rows.';
COMMENT ON COLUMN code_graph_class.graph_name IS 'the reading graph''s partition; with the class name, the key';
COMMENT ON COLUMN code_graph_class.class_name IS 'the fully-qualified binary name, as code_class spells it; with the graph, the key, so a name two entries declare is one row';
COMMENT ON COLUMN code_graph_class.source_name IS 'the entry whose copy the graph sees: of the graph''s entries declaring the name, the one with the lowest store_graph_dependency.position, as the JVM would load it. An entry the graph claims without a position, a capture handed no build classpath being the case, stands after every positioned entry, and two of those are ordered by name. Not part of the key, which is the point: a reader joining code_ rows on this column and the class name reads one copy, where joining through store_graph_source reads every entry''s';
COMMENT ON COLUMN code_graph_class.touched_at IS 'when the reading that last wrote this row ran. Every capture of the graph rewrites the whole partition and deletes the graph''s rows carrying another instant, never skipping it because no entry changed: the order is the graph''s and can move under unchanged entries, and a winning entry leaving hands its names to the next entry declaring them';

CREATE VIEW code_graph_class_rule (graph_name, class_name, source_name) AS
-- The graph's entries declaring the name, and none ahead of this one: a lower position, or, where
-- neither has one or both share one, a lower name. The anti-join probes code_class's key with each
-- of the graph's entries, which is a seek per entry rather than a scan.
SELECT g.graph_name, c.class_name, c.source_name
  FROM store_graph_source g
  JOIN code_class c ON c.source_name = g.source_name
  LEFT JOIN store_graph_dependency d
    ON d.graph_name = g.graph_name AND d.source_name = g.source_name
 WHERE NOT EXISTS (SELECT 1 FROM store_graph_source ag
                     JOIN code_class ac ON ac.source_name = ag.source_name AND ac.class_name = c.class_name
                     LEFT JOIN store_graph_dependency ad
                       ON ad.graph_name = ag.graph_name AND ad.source_name = ag.source_name
                    WHERE ag.graph_name = g.graph_name AND ag.source_name <> g.source_name
                      AND (COALESCE(ad.position, 2147483647) < COALESCE(d.position, 2147483647)
                           OR (COALESCE(ad.position, 2147483647) = COALESCE(d.position, 2147483647)
                               AND ag.source_name < g.source_name)));
COMMENT ON VIEW code_graph_class_rule IS 'One row the graph class rule computes, in the shape code_graph_class stores: the rule itself, evaluated on demand rather than read off disk. For example the code gatherer''s graph-classes stage inserts this view''s rows for one graph into code_graph_class, which is the name every reader spells.';
-- COMMENT ON COLUMN code_graph_class_rule.graph_name IS 'the graph_name of a row of this rule, which the stage writes into code_graph_class.graph_name';
-- COMMENT ON COLUMN code_graph_class_rule.class_name IS 'the class_name of a row of this rule, which the stage writes into code_graph_class.class_name';
-- COMMENT ON COLUMN code_graph_class_rule.source_name IS 'the source_name of a row of this rule, which the stage writes into code_graph_class.source_name';

CREATE TABLE code_type (
  source_name  VARCHAR NOT NULL,
  type_name    VARCHAR NOT NULL,
  display_name VARCHAR NOT NULL,
  root_class   VARCHAR,
  touched_at   TIMESTAMP NOT NULL,
  PRIMARY KEY (source_name, type_name),
  FOREIGN KEY (source_name) REFERENCES store_source (source_name) ON DELETE CASCADE
);
COMMENT ON TABLE code_type IS 'One type the signatures of an entry''s methods mention, as the source wrote it. For example java.util.List<no.sikt.example.Film>, beside the plain java.lang.String and the int that other positions carry.';
COMMENT ON COLUMN code_type.source_name IS 'the classpath entry whose signatures mention the type; the key''s leading dimension, so a type is swept with the entry that mentioned it rather than outliving it. A type name is global and this relation is not, which is the same trade every relation in the family makes: what a reading read is what it can answer for';
COMMENT ON COLUMN code_type.type_name IS 'the type as the source declared it, type arguments kept and packages kept, which is what makes it a key: two Foo<X> from different packages render alike and are two types. A primitive is its own spelling and an array is its component''s with brackets, so the three silences a resolution cannot tell apart, a primitive, an array and a type variable, are told apart here by the name itself. A type variable spells only its own identifier, so two methods writing T share this row; that costs nothing while the only thing stored about it is that it resolves to no class, and stops being adequate the moment anything method-specific is';
COMMENT ON COLUMN code_type.display_name IS 'the same type with its packages dropped, which is what a surface shows a person: List<Film> where the name beside it is java.util.List<no.sikt.example.Film>. A rendering and not an identity, which is why it is not the key: two Foo<X> from different packages render alike. Here rather than at each site because a rendering is a property of the type, so it is stated once per type rather than once per position carrying one, and here rather than nowhere because the editor surfaces render a member''s type and a store that held only identities could not tell them what to show';
COMMENT ON COLUMN code_type.touched_at IS 'when the reading that produced this row ran; swept with the entry it was read from';

CREATE TABLE code_type_element (
  source_name   VARCHAR NOT NULL,
  type_name     VARCHAR NOT NULL,
  element_class VARCHAR NOT NULL,
  delivery      VARCHAR NOT NULL,
  touched_at    TIMESTAMP NOT NULL,
  PRIMARY KEY (source_name, type_name),
  FOREIGN KEY (source_name, type_name)
    REFERENCES code_type (source_name, type_name) ON DELETE CASCADE,
  CHECK (delivery IN ('DIRECT', 'WRAPPED', 'MANY'))
);
COMMENT ON TABLE code_type_element IS 'What a type resolves to once its delivery containers are peeled off, for the types that resolve to a class at all. For example java.util.List<no.sikt.example.Film> resolving to Film, many of them.';
COMMENT ON COLUMN code_type_element.source_name IS 'the entry whose signatures mention the type, as on code_type; the key''s leading dimension';
COMMENT ON COLUMN code_type_element.type_name IS 'the type, as on code_type, completing the key; the row is deleted with it';
COMMENT ON COLUMN code_type_element.element_class IS 'the binary name of the class the type arrives at once every container is peeled off it. Presence is the fact this relation states, which is why the columns are not on the type: a void, a primitive, an array and a type variable name no class, and a placeholder would make four different silences look like one answer. Not a foreign key: a type delivering a class no classpath entry declares is the ordinary case at the end of a declared type, so a reader learns the name here and learns nothing further about it';
COMMENT ON COLUMN code_type_element.delivery IS 'how a caller receives what the type hands over: DIRECT where the type is the class and nothing was peeled, WRAPPED where containers were peeled and none of them multiplies, MANY where at least one does. A List, a Set, a Collection or a jOOQ Result multiplies; an Optional, a CompletableFuture or a Map does not, those being one value in a wrapper. The decision rather than the containers behind it, which is what lets a reader ask its own question without knowing the vocabulary: whether one value may be handed to a position is DIRECT, and whether a field backed by this type is a list is MANY. Stating it as the container''s own name would make both questions a test against a class name, and a rule that turns on java.util.List not happening to equal java.lang.Integer is a coincidence doing load-bearing work';
COMMENT ON COLUMN code_type_element.touched_at IS 'when the reading that produced this row ran; swept with the type it hangs on';

CREATE TABLE code_type_element_argument (
  source_name    VARCHAR NOT NULL,
  type_name      VARCHAR NOT NULL,
  position       INT     NOT NULL CHECK (position >= 0),
  argument_class VARCHAR NOT NULL,
  touched_at     TIMESTAMP NOT NULL,
  PRIMARY KEY (source_name, type_name, position),
  FOREIGN KEY (source_name, type_name)
    REFERENCES code_type_element (source_name, type_name) ON DELETE CASCADE
);
COMMENT ON TABLE code_type_element_argument IS 'One type argument of the element a type delivers, by its position, where it names a class exactly. For example java.util.List<org.jooq.Row2<java.lang.Integer, java.lang.String>> delivering Row2, whose argument 0 is Integer and argument 1 String.';
COMMENT ON COLUMN code_type_element_argument.source_name IS 'the entry whose signatures mention the type, as on code_type_element';
COMMENT ON COLUMN code_type_element_argument.type_name IS 'the type, as on code_type_element; the row is deleted with it';
COMMENT ON COLUMN code_type_element_argument.position IS 'the 0-based position of the argument among the element''s type arguments, as written';
COMMENT ON COLUMN code_type_element_argument.argument_class IS 'the binary name of the class written at that position. A position naming no class exactly, a wildcard, a bounded one included, a type variable or an array, has no row, so a reader requiring a class at every position sees the gap rather than a placeholder';
COMMENT ON COLUMN code_type_element_argument.touched_at IS 'when the reading that produced this row ran; swept with the type it hangs on';

CREATE TABLE code_method (
  source_name VARCHAR NOT NULL,
  class_name  VARCHAR NOT NULL,
  method_name VARCHAR NOT NULL,
  descriptor  VARCHAR NOT NULL,
  is_static   BOOLEAN NOT NULL,
  result_type VARCHAR NOT NULL,
  result_erased_class  VARCHAR,
  result_element_class VARCHAR,
  result_delivery      VARCHAR,
  result_first_argument_class VARCHAR,
  touched_at  TIMESTAMP NOT NULL,
  PRIMARY KEY (source_name, class_name, method_name, descriptor),
  FOREIGN KEY (source_name, class_name)
    REFERENCES code_class (source_name, class_name) ON DELETE CASCADE,
  FOREIGN KEY (source_name, result_type) REFERENCES code_type (source_name, type_name)
    ON DELETE CASCADE,
  CHECK (result_delivery IS NULL OR result_delivery IN ('DIRECT', 'WRAPPED', 'MANY')),
  -- A peel lands on a class or it does not land, so the two say the same silence together.
  CHECK ((result_element_class IS NULL) = (result_delivery IS NULL))
);
COMMENT ON TABLE code_method IS 'One public method of a class the reactor built, which is the population every directive naming Java draws its candidates from. For example filmsByRating(DSLContext, String) on a consumer''s FilmService.';
COMMENT ON COLUMN code_method.source_name IS 'the classpath entry the declaring class was read from; the key''s leading dimension. With the class beside it this row hangs on code_class, so a class a compile removed takes its methods with it rather than leaving them until the whole entry goes';
COMMENT ON COLUMN code_method.class_name IS 'the declaring class''s binary name, the left part of what an author writes at a directive';
COMMENT ON COLUMN code_method.method_name IS 'the method''s own name, the right part of it. Not a key on its own: a name an author writes may denote several declarations, and the count of rows sharing one is what says so';
COMMENT ON COLUMN code_method.result_erased_class IS 'the class the result type erases to, type arguments dropped: java.util.List for a List<Film> and the class itself where the type is one. NULL where it erases to no class, which a primitive, a void, an array and a type variable are alike in. Here rather than on a shared row because a parse is a fact about the position that wrote it: the dictionary that held it was keyed by the spelling, so it was shared by every class mentioning it and no per-class reading could decide its fate';
COMMENT ON COLUMN code_method.result_element_class IS 'the class the result delivers once its containers are peeled off, which is the question its readers ask: which class backs the GraphQL type this method produces. NULL where the type resolves to no class at all';
COMMENT ON COLUMN code_method.result_delivery IS 'how the result delivers that class, DIRECT where the type is one, WRAPPED inside an Optional and MANY inside a collection. What a field declared a list is checked against, a single-delivering method behind a list field being an author error. NULL with the element beside it';
COMMENT ON COLUMN code_method.descriptor IS 'the JVM method descriptor, completing the key. What tells two overloads apart, which no rendering of the erased types can: two methods taking same-named types from different packages render alike';
COMMENT ON COLUMN code_method.is_static IS 'whether the method is static. A property of the declaration rather than of any directive, though it is what @service reads to decide whether a holder is needed and what @condition folds on before admitting a set of overloads as one target';
COMMENT ON COLUMN code_method.result_first_argument_class IS 'the class the result type names as its first type argument, on code_method_parameter.first_argument_class'' terms, or NULL where it names none. Field<FilmRecord> says FilmRecord, which no peel reaches, a jOOQ Field being an expression of its argument rather than a container of it: what an @externalField method hands a field is this class, and a Field<Boolean> is what a condition method may return besides a Condition';
COMMENT ON COLUMN code_method.result_type IS 'the type the method results in, by reference. Not a relation of its own beside the parameters, because a result is the one thing a method has exactly one of and it carries neither a name nor an ordinal to be bound at: a parameter binds a type to a named position, and a result is the type';
COMMENT ON COLUMN code_method.touched_at IS 'when the reading that produced this row ran; swept by the reading that replaces it';

CREATE TABLE code_method_parameter (
  source_name    VARCHAR NOT NULL,
  class_name     VARCHAR NOT NULL,
  method_name    VARCHAR NOT NULL,
  descriptor     VARCHAR NOT NULL,
  position       INT NOT NULL,
  parameter_name VARCHAR,
  parameter_type VARCHAR NOT NULL,
  erased_class   VARCHAR,
  element_class  VARCHAR,
  delivery       VARCHAR,
  first_argument_class VARCHAR,
  role           VARCHAR NOT NULL,
  extraction     VARCHAR NOT NULL,
  touched_at     TIMESTAMP NOT NULL,
  PRIMARY KEY (source_name, class_name, method_name, descriptor, position),
  FOREIGN KEY (source_name, class_name, method_name, descriptor)
    REFERENCES code_method (source_name, class_name, method_name, descriptor) ON DELETE CASCADE,
  FOREIGN KEY (source_name, parameter_type) REFERENCES code_type (source_name, type_name)
    ON DELETE CASCADE,
  CHECK (role IN ('DSL_CONTEXT', 'CONFIGURATION', 'TABLE_CONCRETE', 'TABLE_ANY', 'OTHER')),
  CHECK (extraction IN ('DIRECT', 'ENUM_VALUE_OF')),
  CHECK (delivery IS NULL OR delivery IN ('DIRECT', 'WRAPPED', 'MANY')),
  CHECK ((element_class IS NULL) = (delivery IS NULL))
);
COMMENT ON TABLE code_method_parameter IS 'One position in a method''s parameter list: the type bound there, the name it is bound under, and what the type alone says the position is for. For example position 0 of filmTitleContains, named film and playing the TABLE_CONCRETE role.';
COMMENT ON COLUMN code_method_parameter.erased_class IS 'the class the parameter type erases to, on code_method.result_erased_class'' terms; what a binding compares against when it asks whether an argument can be passed here';
COMMENT ON COLUMN code_method_parameter.element_class IS 'the class the parameter delivers once its containers are peeled off, on code_method.result_element_class'' terms';
COMMENT ON COLUMN code_method_parameter.delivery IS 'how the parameter delivers that class, on code_method.result_delivery'' terms; NULL with the element beside it';
COMMENT ON COLUMN code_method_parameter.source_name IS 'the entry the declaring class was read from, as on code_method; the key''s leading dimension';
COMMENT ON COLUMN code_method_parameter.class_name IS 'the declaring class, as on code_method';
COMMENT ON COLUMN code_method_parameter.method_name IS 'the method, as on code_method';
COMMENT ON COLUMN code_method_parameter.descriptor IS 'the method''s descriptor, as on code_method; with the three columns above, the method this position belongs to, and the row is deleted with it';
COMMENT ON COLUMN code_method_parameter.position IS 'the position in the parameter list, 0-based, completing the key. Position is the key and not the name, because a name is what a classfile may omit and a position is what it always carries';
COMMENT ON COLUMN code_method_parameter.parameter_name IS 'the parameter''s name as the source declared it, or NULL where the class was compiled without -parameters and the classfile carries no MethodParameters attribute. What a GraphQL argument binds to and what an argMapping entry targets, so a run that finds it absent refuses the binding rather than guessing; a reader must not read NULL as an unnamed parameter';
COMMENT ON COLUMN code_type.root_class IS 'the fully-qualified class the type names at its root position, type arguments dropped: java.util.List for a List<Film>, and the class itself where the type is one. NULL where the root names no class, which a primitive, a void, an array and a type variable are alike in, so a reader asking what a value has to be to be assigned here reads the absence as "not a class" and does not have to tell those four apart; type_name does tell them apart, for the reader that has to. What a position accepts, and deliberately not how many it accepts: a List<Film> accepts a list, and that it delivers films is code_type_element.delivery''s answer to a different question. The two are stated separately because they diverge exactly where it matters, a reader comparing against a jOOQ record class wanting the list and a reader asking whether one value can be handed over wanting the films';
COMMENT ON COLUMN code_method_parameter.parameter_type IS 'the type bound at this position, by reference. A parameter is a binding rather than a description: what the type is and what it resolves to are the type''s own facts and are stated once however many positions carry it, which over this module''s main sources is thirteen hundred positions over two hundred types';
COMMENT ON COLUMN code_method_parameter.first_argument_class IS 'the class the declaration names as its first type argument, read off the census''s reference at that position, or NULL where it names none: a raw or non-generic type, a type variable or an unbounded wildcard there. Set<FilmRecord> says FilmRecord and Set<List<FilmRecord>> says java.util.List, which element_class and delivery do not tell apart';
COMMENT ON COLUMN code_method_parameter.role IS 'what the position is for as far as its type alone decides, in a closed vocabulary of five, and the five are exclusive because no type satisfies two of them. DSL_CONTEXT: the run''s own jOOQ context is passed here, the position declared as org.jooq.DSLContext exactly. CONFIGURATION: the same context as an org.jooq.Configuration, declared exactly so; a class implementing either is OTHER, a value of that class. TABLE_CONCRETE: the declaration names one generated table, the sql_table whose class_fqn is the erased class. TABLE_ANY: the declaration is org.jooq.Table itself, raw or wildcarded, a type variable, or org.jooq.TableLike, which every table is, so the position takes whatever table the site supplies; java.lang.Object takes one too and is OTHER, naming no table type. OTHER: everything else, whose role is the application''s to decide from the arguments and context keys in scope at the site. Decided here rather than by a reader because deciding the table roles needs an assignability walk, which a reader either re-derives through a recursive closure or asks a loader for';
COMMENT ON COLUMN code_method_parameter.extraction IS 'how a value bound to this position is coerced into it, decided by the declared type alone: ENUM_VALUE_OF where that type is an enum and DIRECT otherwise. The standing rule rather than the last word, a parameter bound to a slot carrying @nodeId receiving that slot''s decoded key instead, an exception the generator applies. Decided by loading the class, which is what makes it answerable for both populations at once: an author''s own enum and a generated one a column binds to, the second living in the package this reading excludes and so reachable no other way';
COMMENT ON COLUMN code_method_parameter.touched_at IS 'when the reading that produced this row ran; swept with the method it hangs on';

CREATE TABLE code_read_slot (
  source_name     VARCHAR NOT NULL,
  class_name      VARCHAR NOT NULL,
  method_name     VARCHAR NOT NULL,
  descriptor      VARCHAR NOT NULL,
  declaring_class VARCHAR NOT NULL,
  slot_name       VARCHAR NOT NULL,
  slot_type       VARCHAR NOT NULL,
  erased_class    VARCHAR,
  element_class   VARCHAR,
  delivery        VARCHAR,
  origin          VARCHAR NOT NULL,
  touched_at      TIMESTAMP NOT NULL,
  PRIMARY KEY (source_name, class_name, method_name, descriptor),
  FOREIGN KEY (source_name, class_name)
    REFERENCES code_class (source_name, class_name) ON DELETE CASCADE,
  FOREIGN KEY (source_name, slot_type) REFERENCES code_type (source_name, type_name)
    ON DELETE CASCADE,
  CHECK (origin IN ('RECORD_COMPONENT', 'BEAN_ACCESSOR')),
  CHECK (delivery IS NULL OR delivery IN ('DIRECT', 'WRAPPED', 'MANY')),
  CHECK ((element_class IS NULL) = (delivery IS NULL))
);
COMMENT ON TABLE code_read_slot IS 'One member name a class offers an author, the method that reads it and what reading it yields. For example a Film record offering title through its title() accessor, or a FilmDto offering it through getTitle().';
COMMENT ON COLUMN code_read_slot.source_name IS 'the entry the declaring class was read from, as on code_method; the key''s leading dimension';
COMMENT ON COLUMN code_read_slot.class_name IS 'the class offering the member, which is the class an author names and not always the class the accessor is written on. A member a base class declares is one the subclass offers, so this is where the walk found it rather than where it was declared. Keyed into code_class, so a class offering members is one the reading actually read rather than a name appearing here and nowhere else';
COMMENT ON COLUMN code_read_slot.method_name IS 'the method that reads the member. The accessor is the key rather than the name an author writes, because the name is the part that is not unique: a class spelling one property getTitle and isTitle offers title twice';
COMMENT ON COLUMN code_read_slot.descriptor IS 'the method''s descriptor, completing the key: two accessors of one name on one class are two slots, which is what overloading is';
COMMENT ON COLUMN code_read_slot.declaring_class IS 'the class the accessor is written on, which is the class a jump to the member''s own source lands in. Equal to the offering class wherever the class declares its own member and different wherever it inherits one. No foreign key, for the reason the write side names the call it makes without keying to it: a base class may be read from a different classpath entry than the class offering its members, so the method''s own row sits under a key this one does not carry, and a constraint would refuse exactly the inheritance this column exists to record';
COMMENT ON COLUMN code_read_slot.slot_type IS 'what reading the member yields, as code_type spells it. Carried rather than reached through the accessor''s own row, because what a member yields is a fact about the class offering it and not about the method behind it. The two agree wherever a class declares its own member. They part at inheritance: an inherited accessor has no row under the offering class, and its base may have been read from another entry or not read at all, so a slot typed only through one could not exist. And a base class declaring K getId() offers Integer to a subclass extending it at Integer, which only the offering class can say. The spelling is the accessor''s declared result today, type variables unsubstituted, so that case reads K here; this column is where the substituted type goes when the reading states it';
COMMENT ON COLUMN code_read_slot.erased_class IS 'the class what the member yields erases to, on code_method.result_erased_class'' terms. Here rather than through the accessor for the reasons slot_type gives';
COMMENT ON COLUMN code_read_slot.element_class IS 'the class the member delivers once its containers are peeled off, on code_method.result_element_class'' terms: which class backs the GraphQL type a field reading this member produces';
COMMENT ON COLUMN code_read_slot.delivery IS 'how the member delivers that class, on code_method.result_delivery'' terms; NULL with the element beside it';
COMMENT ON COLUMN code_read_slot.slot_name IS 'the name @field(name:) resolves against: a record component''s own name, or the property a getter offers, which is the remainder after get or is with its first letter lowered. Deliberately not unique within a class, two spellings of one property being two rows; a reader wanting one takes the first and a reader offering candidates offers both';
COMMENT ON COLUMN code_read_slot.origin IS 'RECORD_COMPONENT or BEAN_ACCESSOR, which is a fact about the offering class rather than the member: a class takes exactly one arm, chosen by its declared form, so a record answers with its components and anything else with its getters. Carried because two readers turn on it, one choosing where a go-to-definition lands and one choosing the noun a diagnostic uses';
COMMENT ON COLUMN code_read_slot.touched_at IS 'when the reading that produced this row ran; swept with the accessor it hangs on';
CREATE INDEX code_read_slot_name_ix ON code_read_slot (source_name, slot_name);
COMMENT ON INDEX code_read_slot_name_ix IS 'The slot name is a join key rather than a filter, graphitron_type_backing_rule''s hop matching every coordinate in a graph against every slot a source offers without binding a class first, so the answer is a product and the name is the only thing narrowing it. The primary key leads with the class and cannot serve that, and the same access without an index on the name was measured in minutes rather than seconds on the relation this replaces.';

CREATE TABLE code_construction (
  source_name VARCHAR NOT NULL,
  class_name  VARCHAR NOT NULL,
  shape       VARCHAR NOT NULL,
  descriptor  VARCHAR NOT NULL,
  touched_at  TIMESTAMP NOT NULL,
  PRIMARY KEY (source_name, class_name),
  FOREIGN KEY (source_name, class_name)
    REFERENCES code_class (source_name, class_name) ON DELETE CASCADE,
  CHECK (shape IN ('POSITIONAL', 'SETTERS'))
);
COMMENT ON TABLE code_construction IS 'How a value of one class is made, for the classes a generator has to make one of. For example a FilmInput record, made by calling its canonical constructor with every component at once.';
COMMENT ON COLUMN code_construction.source_name IS 'the entry the class was read from, as on code_class; the key''s leading dimension';
COMMENT ON COLUMN code_construction.class_name IS 'the class being made, keyed into code_class because how a value is made is a fact about a class: a parameter names a type, but what is eventually constructed is the class that type delivers, and it is that class a compile can change. So a class the next reading does not find takes its construction and its write slots with it';
COMMENT ON COLUMN code_construction.shape IS 'POSITIONAL or SETTERS: whether the members go in through the constructor all at once or one at a time afterwards. A record is the first, everything else with a usable no-argument constructor is the second, and a jOOQ record is the second like any other, being made empty and then filled. Carried because two emitters fork on it and it is the decision rather than the evidence for it: reading it off the class''s declared form would put the rule in the readers';
COMMENT ON COLUMN code_construction.descriptor IS 'the constructor to call. At POSITIONAL that is the canonical one, whose parameters are the components in header order; at SETTERS it is ()V. Named by descriptor rather than by presence because a class may declare several and only one of them is the one this shape means';
COMMENT ON COLUMN code_construction.touched_at IS 'when the reading that produced this row ran; swept with the class it hangs on';

CREATE TABLE code_constructor (
  source_name VARCHAR   NOT NULL,
  class_name  VARCHAR   NOT NULL,
  descriptor  VARCHAR   NOT NULL,
  touched_at  TIMESTAMP NOT NULL,
  PRIMARY KEY (source_name, class_name, descriptor),
  FOREIGN KEY (source_name, class_name)
    REFERENCES code_class (source_name, class_name) ON DELETE CASCADE
);
COMMENT ON TABLE code_constructor IS 'One public constructor of a class declaring an instance @service method: one row per class and constructor, overloads told apart by descriptor. For example SampleInstanceService(DSLContext), the one public constructor of a class whose titleByFilmId an instance @service names.';
COMMENT ON COLUMN code_constructor.source_name IS 'the entry the class was read from, as on code_class; the key''s leading dimension';
COMMENT ON COLUMN code_constructor.class_name IS 'the class the constructor makes, keyed into code_class, so a class the next reading does not find takes its constructors with it';
COMMENT ON COLUMN code_constructor.descriptor IS 'the constructor''s descriptor, completing the key: a class may declare several public constructors, and the descriptor is what tells them apart';
COMMENT ON COLUMN code_constructor.touched_at IS 'when the reading that produced this row ran; swept with the class it hangs on';

CREATE TABLE code_constructor_parameter (
  source_name    VARCHAR   NOT NULL,
  class_name     VARCHAR   NOT NULL,
  descriptor     VARCHAR   NOT NULL,
  position       INT       NOT NULL,
  parameter_name VARCHAR,
  parameter_type VARCHAR   NOT NULL,
  erased_class   VARCHAR,
  role           VARCHAR   NOT NULL,
  touched_at     TIMESTAMP NOT NULL,
  PRIMARY KEY (source_name, class_name, descriptor, position),
  FOREIGN KEY (source_name, class_name, descriptor)
    REFERENCES code_constructor (source_name, class_name, descriptor) ON DELETE CASCADE,
  FOREIGN KEY (source_name, parameter_type) REFERENCES code_type (source_name, type_name)
    ON DELETE CASCADE,
  CHECK (role IN ('DSL_CONTEXT', 'CONFIGURATION', 'TABLE_CONCRETE', 'TABLE_ANY', 'OTHER'))
);
COMMENT ON TABLE code_constructor_parameter IS 'One position in a public constructor''s parameter list: the type bound there, the name it is bound under, and what the type alone says the position is for. For example position 0 of SampleInstanceService(DSLContext), named ctx and playing the DSL_CONTEXT role.';
COMMENT ON COLUMN code_constructor_parameter.source_name IS 'the entry the class was read from, as on code_constructor';
COMMENT ON COLUMN code_constructor_parameter.class_name IS 'the class, as on code_constructor';
COMMENT ON COLUMN code_constructor_parameter.descriptor IS 'the constructor''s descriptor, as on code_constructor; with the two columns above, the constructor this position belongs to, and the row is deleted with it';
COMMENT ON COLUMN code_constructor_parameter.position IS 'the position in the parameter list, 0-based, completing the key, on code_method_parameter.position''s terms';
COMMENT ON COLUMN code_constructor_parameter.parameter_name IS 'the parameter''s name as the source declared it, or NULL where the class was compiled without -parameters, on code_method_parameter.parameter_name''s terms; what a context key binds to';
COMMENT ON COLUMN code_constructor_parameter.parameter_type IS 'the type bound at this position, by reference, as on code_method_parameter.parameter_type';
COMMENT ON COLUMN code_constructor_parameter.erased_class IS 'the class the parameter type erases to, on code_method_parameter.erased_class''s terms';
COMMENT ON COLUMN code_constructor_parameter.role IS 'what the position is for as far as its type alone decides, by the rule and in the vocabulary of code_method_parameter.role: DSL_CONTEXT or CONFIGURATION where the position is declared as that jOOQ type exactly, the two table roles, else OTHER';
COMMENT ON COLUMN code_constructor_parameter.touched_at IS 'when the reading that produced this row ran; swept with the constructor it hangs on';

CREATE VIEW code_constructor_buildable (source_name, class_name, descriptor, width) AS
-- Every position is the jOOQ context, which the run holds one of: a DSLContext by exact type, at
-- most once, so the constructors this admits take nothing or one DSLContext and no two are equally
-- wide. A position anything else fills, a context key included, is one the run cannot supply.
SELECT c.source_name, c.class_name, c.descriptor,
       (SELECT COUNT(*) FROM code_constructor_parameter p
         WHERE p.source_name = c.source_name AND p.class_name = c.class_name
           AND p.descriptor = c.descriptor)
  FROM code_constructor c
 WHERE NOT EXISTS (SELECT 1 FROM code_constructor_parameter p
                    WHERE p.source_name = c.source_name AND p.class_name = c.class_name
                      AND p.descriptor = c.descriptor
                      AND (p.role <> 'DSL_CONTEXT' OR p.position > 0));
COMMENT ON VIEW code_constructor_buildable IS 'One public constructor the run can call to make an object an instance service method runs on: every parameter the jOOQ context, at most once. For example SampleInstanceService(DSLContext) and a no-argument constructor are buildable, and one taking a String is not.';
-- COMMENT ON COLUMN code_constructor_buildable.source_name IS 'the entry the class was read from, as on code_constructor';
-- COMMENT ON COLUMN code_constructor_buildable.class_name IS 'the class the constructor makes';
-- COMMENT ON COLUMN code_constructor_buildable.descriptor IS 'the constructor''s descriptor, completing its key in code_constructor';
-- COMMENT ON COLUMN code_constructor_buildable.width IS 'how many parameters it takes, which is what makes one buildable constructor wider than another';

CREATE TABLE code_write_slot (
  source_name VARCHAR NOT NULL,
  class_name  VARCHAR NOT NULL,
  method_name VARCHAR NOT NULL,
  descriptor  VARCHAR NOT NULL,
  position    INT NOT NULL,
  slot_name   VARCHAR NOT NULL,
  slot_type   VARCHAR NOT NULL,
  erased_class  VARCHAR,
  element_class VARCHAR,
  delivery      VARCHAR,
  touched_at  TIMESTAMP NOT NULL,
  PRIMARY KEY (source_name, class_name, method_name, descriptor, position),
  FOREIGN KEY (source_name, class_name)
    REFERENCES code_construction (source_name, class_name) ON DELETE CASCADE,
  FOREIGN KEY (source_name, slot_type) REFERENCES code_type (source_name, type_name)
    ON DELETE CASCADE,
  CHECK (delivery IS NULL OR delivery IN ('DIRECT', 'WRAPPED', 'MANY')),
  CHECK ((element_class IS NULL) = (delivery IS NULL))
);
COMMENT ON TABLE code_write_slot IS 'One member an author can fill when a value of the class is made, and the call that fills it. For example a FilmInput''s title, filled at argument zero of its canonical constructor.';
COMMENT ON COLUMN code_write_slot.source_name IS 'the entry the class was read from, as on code_construction';
COMMENT ON COLUMN code_write_slot.class_name IS 'the class being made, as on code_construction; the row is deleted with it';
COMMENT ON COLUMN code_write_slot.method_name IS 'the call that fills the member: the constructor at POSITIONAL, where every slot names the same one, and the setter at SETTERS, where each names its own';
COMMENT ON COLUMN code_write_slot.descriptor IS 'that call''s descriptor, completing its key';
COMMENT ON COLUMN code_write_slot.position IS 'which argument of the call carries the member, counted from zero. At POSITIONAL it is the component''s place in the record header, which is what makes the call emittable in one go; at SETTERS it is zero, a setter taking one argument. Part of the key because one call carries many members at POSITIONAL and the argument is what tells them apart';
COMMENT ON COLUMN code_write_slot.slot_name IS 'the name @field(name:) resolves against on an input: the record component''s own name, or the property a setter fills, which is the remainder after set with its first letter lowered. Deliberately not unique within a class, on code_read_slot''s terms: a class spelling one property two ways offers it twice and this relation declines to choose between them';
COMMENT ON COLUMN code_write_slot.slot_type IS 'what the member is filled with, as code_type spells it. The write side''s answer to the question code_method.result_type answers for reading: a value bound here is coerced into this type. Carried with its parse rather than reached through the call''s own row, because a POSITIONAL call is a constructor and constructors have no code_method row, and an inherited setter has none under the class being made; the write side is a parameter position and says so on code_method_parameter''s terms';
COMMENT ON COLUMN code_write_slot.erased_class IS 'the class the member''s type erases to, on code_method_parameter.erased_class'' terms';
COMMENT ON COLUMN code_write_slot.element_class IS 'the class the member takes once its containers are peeled off, on code_method_parameter.element_class'' terms: which class the value bound here is built as';
COMMENT ON COLUMN code_write_slot.delivery IS 'how the member takes that class, on code_method_parameter.delivery'' terms; NULL with the element beside it';
COMMENT ON COLUMN code_write_slot.touched_at IS 'when the reading that produced this row ran; swept with the construction it hangs on';
CREATE INDEX code_write_slot_name_ix ON code_write_slot (source_name, slot_name);
COMMENT ON INDEX code_write_slot_name_ix IS 'The read side''s index, for the same access and the same reason: graphitron_type_backing_rule''s hop matches every input coordinate in a graph against every member a source can fill, without binding a class first, so the answer is a product and the name is the only thing narrowing it. The primary key leads with the class and the foreign key with the entry, and neither can serve that. Measured rather than assumed: on a corpus of five thousand fillable members, the arm without this index scanned two and a half million rows against the read arm''s twenty thousand, the planner falling back to the foreign key''s own index and filtering the name per row. Both arms took about the same wall clock, which is why the plan is what says this is needed and the clock is not.';

CREATE TABLE code_method_exception (
  source_name     VARCHAR NOT NULL,
  class_name      VARCHAR NOT NULL,
  method_name     VARCHAR NOT NULL,
  descriptor      VARCHAR NOT NULL,
  exception_class VARCHAR NOT NULL,
  touched_at      TIMESTAMP NOT NULL,
  PRIMARY KEY (source_name, class_name, method_name, descriptor, exception_class),
  FOREIGN KEY (source_name, class_name, method_name, descriptor)
    REFERENCES code_method (source_name, class_name, method_name, descriptor) ON DELETE CASCADE
);
COMMENT ON TABLE code_method_exception IS 'One exception a method declares it throws. For example filmsByRating declaring java.io.IOException.';
COMMENT ON COLUMN code_method_exception.source_name IS 'the entry the declaring class was read from, as on code_method; the key''s leading dimension';
COMMENT ON COLUMN code_method_exception.class_name IS 'the declaring class, as on code_method';
COMMENT ON COLUMN code_method_exception.method_name IS 'the method, as on code_method';
COMMENT ON COLUMN code_method_exception.descriptor IS 'the method''s descriptor, as on code_method; with the three columns above, the method this clause belongs to, and the row is deleted with it';
COMMENT ON COLUMN code_method_exception.exception_class IS 'the exception by binary name, completing the key. A set and not a list: the clause is read to decide whether same-named declarations agree and whether a field''s @error channel covers them, and neither comparison is order-sensitive, so declaration order would be a column nothing reads and a second way for two equal clauses to differ. Deliberately no foreign key to code_throwable: the classes a throws clause names are usually the JDK''s, which no classpath entry ships, so a name here is ordinarily a name and nothing further';
COMMENT ON COLUMN code_method_exception.touched_at IS 'when the reading that produced this row ran; swept with the method it hangs on';

CREATE TABLE code_service_method (
  source_name VARCHAR NOT NULL,
  class_name  VARCHAR NOT NULL,
  method_name VARCHAR NOT NULL,
  descriptor  VARCHAR NOT NULL,
  touched_at  TIMESTAMP NOT NULL,
  PRIMARY KEY (source_name, class_name, method_name, descriptor),
  FOREIGN KEY (source_name, class_name, method_name, descriptor)
    REFERENCES code_method (source_name, class_name, method_name, descriptor) ON DELETE CASCADE
);
COMMENT ON TABLE code_service_method IS 'One method an author may name in @service(service:). For example a public static filmsByRating(DSLContext, String) on a consumer''s FilmService.';
COMMENT ON COLUMN code_service_method.source_name IS 'the entry the declaring class was read from, as on code_method; the key''s leading dimension';
COMMENT ON COLUMN code_service_method.class_name IS 'the declaring class, as on code_method';
COMMENT ON COLUMN code_service_method.method_name IS 'the method, as on code_method';
COMMENT ON COLUMN code_service_method.descriptor IS 'the method''s descriptor, completing the key. The whole row is the key: what the method returns and takes is code_method''s and does not vary by the directive that reached it, so membership is the only thing this relation has to say';
COMMENT ON COLUMN code_service_method.touched_at IS 'when the reading that produced this row ran; swept with the method it hangs on';

CREATE TABLE code_condition_method (
  source_name VARCHAR NOT NULL,
  class_name  VARCHAR NOT NULL,
  method_name VARCHAR NOT NULL,
  descriptor  VARCHAR NOT NULL,
  touched_at  TIMESTAMP NOT NULL,
  PRIMARY KEY (source_name, class_name, method_name, descriptor),
  FOREIGN KEY (source_name, class_name, method_name, descriptor)
    REFERENCES code_method (source_name, class_name, method_name, descriptor) ON DELETE CASCADE
);
COMMENT ON TABLE code_condition_method IS 'One method an author may name in @condition(condition:). For example a public static filmTitleContains(Film, String) returning an org.jooq.Condition.';
COMMENT ON COLUMN code_condition_method.source_name IS 'the entry the declaring class was read from, as on code_method; the key''s leading dimension';
COMMENT ON COLUMN code_condition_method.class_name IS 'the declaring class, as on code_method';
COMMENT ON COLUMN code_condition_method.method_name IS 'the method, as on code_method';
COMMENT ON COLUMN code_condition_method.descriptor IS 'the method''s descriptor, completing the key. The whole row is the key, on code_service_method.descriptor''s terms; the return type this arm admits on is fixed by the admission and would repeat its own predicate on every row';
COMMENT ON COLUMN code_condition_method.touched_at IS 'when the reading that produced this row ran; swept with the method it hangs on';

CREATE TABLE code_external_field_method (
  source_name VARCHAR NOT NULL,
  class_name  VARCHAR NOT NULL,
  method_name VARCHAR NOT NULL,
  descriptor  VARCHAR NOT NULL,
  touched_at  TIMESTAMP NOT NULL,
  PRIMARY KEY (source_name, class_name, method_name, descriptor),
  FOREIGN KEY (source_name, class_name, method_name, descriptor)
    REFERENCES code_method (source_name, class_name, method_name, descriptor) ON DELETE CASCADE
);
COMMENT ON TABLE code_external_field_method IS 'One method an author may name in @externalField(reference:). For example a public static titleUpper(Film) returning an org.jooq.Field.';
COMMENT ON COLUMN code_external_field_method.source_name IS 'the entry the declaring class was read from, as on code_method; the key''s leading dimension';
COMMENT ON COLUMN code_external_field_method.class_name IS 'the declaring class, as on code_method';
COMMENT ON COLUMN code_external_field_method.method_name IS 'the method, as on code_method';
COMMENT ON COLUMN code_external_field_method.descriptor IS 'the method''s descriptor, completing the key. The table the lifter lifts from was a column here and is code_method_parameter''s role at position 0: a parameter''s type is the parameter''s fact, and a reader asking which table a lifter takes asks the position rather than the arm';
COMMENT ON COLUMN code_external_field_method.touched_at IS 'when the reading that produced this row ran; swept with the method it hangs on';

CREATE TABLE code_scalar_constant (
  source_name VARCHAR NOT NULL,
  class_name  VARCHAR NOT NULL,
  field_name  VARCHAR NOT NULL,
  input_type  VARCHAR,
  touched_at  TIMESTAMP NOT NULL,
  PRIMARY KEY (source_name, class_name, field_name),
  FOREIGN KEY (source_name, class_name)
    REFERENCES code_class (source_name, class_name) ON DELETE CASCADE
);
-- What a @scalarType reference names, the class and the field, read without the classpath entry
-- the reference does not carry.
CREATE INDEX code_scalar_constant_ref_ix
  ON code_scalar_constant (class_name, field_name);
COMMENT ON TABLE code_scalar_constant IS 'One constant an author may name in @scalarType(scalar:), and the Java type its scalar coerces to. For example a DATE_TIME field coercing to java.time.OffsetDateTime.';
COMMENT ON COLUMN code_scalar_constant.source_name IS 'the classpath entry the owning class was read from, anchored by store_source; the key''s leading dimension, and what a reader joins through to scope by the graph''s own source set, or by how the graph''s build reached the entry on store_graph_dependency';
COMMENT ON COLUMN code_scalar_constant.class_name IS 'the owning class''s binary name, the left part of the reference an author writes';
COMMENT ON COLUMN code_scalar_constant.field_name IS 'the constant''s own name, the right part of that reference; completing the key';
COMMENT ON COLUMN code_scalar_constant.input_type IS 'the fully-qualified Java type a value of this constant''s scalar arrives as, the input parameter of the Coercing it holds, boxed where that is primitive. NULL where the constant does not resolve to one, which folds four cases this arm does not tell apart: the class does not load, the field is not a public static GraphQLScalarType, its initialiser throws, or the coercing declares no usable input. The one column here that a classfile cannot answer, read by loading the class instead, so absence is unresolved and never not-a-scalar';
COMMENT ON COLUMN code_scalar_constant.touched_at IS 'when the reading that produced this row ran; the reading ends by deleting the rows of the entries it read that still carry an older instant, which are the constants a recompiled entry no longer declares';

CREATE TABLE code_throwable (
  source_name VARCHAR NOT NULL,
  class_name  VARCHAR NOT NULL,
  touched_at  TIMESTAMP NOT NULL,
  PRIMARY KEY (source_name, class_name),
  FOREIGN KEY (source_name) REFERENCES store_source (source_name) ON DELETE CASCADE
);
COMMENT ON TABLE code_throwable IS 'One throwable on the classpath, which is what an author may name as an @error handler''s exception. For example org.jooq.exception.IntegrityConstraintViolationException, read from the jOOQ jar.';
COMMENT ON COLUMN code_throwable.source_name IS 'the classpath entry the class was read from, anchored by store_source; the key''s leading dimension, and what a reader joins through to rank a candidate by origin or by coordinate, which store_graph_dependency holds per graph';
COMMENT ON COLUMN code_throwable.class_name IS 'the throwable''s binary name, which is what an author writes; completing the key';
COMMENT ON COLUMN code_throwable.touched_at IS 'when the reading that produced this row ran; the reading ends by deleting the rows of the entries it read that still carry an older instant, which are the throwables a recompiled entry no longer declares';

CREATE TABLE code_throwable_supertype (
  source_name    VARCHAR NOT NULL,
  class_name     VARCHAR NOT NULL,
  supertype_name VARCHAR NOT NULL,
  touched_at     TIMESTAMP NOT NULL,
  PRIMARY KEY (source_name, class_name, supertype_name),
  FOREIGN KEY (source_name, class_name)
    REFERENCES code_throwable (source_name, class_name) ON DELETE CASCADE
);
COMMENT ON TABLE code_throwable_supertype IS 'Every type a throwable is, itself excluded: the superclass chain above it and every interface it or they implement, transitively. For example IntegrityConstraintViolationException being a DataAccessException, a RuntimeException, an Exception, a Throwable and an Object.';
COMMENT ON COLUMN code_throwable_supertype.source_name IS 'the entry the throwable was read from, as on code_throwable; the key''s leading dimension';
COMMENT ON COLUMN code_throwable_supertype.class_name IS 'the throwable this row is about, as on code_throwable; the row is deleted with it';
COMMENT ON COLUMN code_throwable_supertype.supertype_name IS 'one type the throwable is, by binary name, completing the key. java.lang.Throwable is a row on every throwable, being the admission fact itself, and java.lang.Object is a row for the same reason it is one on sql_table_record_supertype: this states what the class is rather than what its source declared, and a throwable is an Object';
COMMENT ON COLUMN code_throwable_supertype.touched_at IS 'when the reading that produced this row ran; swept with the throwable it hangs on';

-- ==== Java source declaration facts ===============================================
-- What the consumer's .java sources declare, in the source language's vocabulary: where each
-- class, method and field is written, and what its doc comment says. Its own population beside
-- the classpath reading rather than columns on it, joined to it by name and never keyed by it.
-- Three facts force that separation. A source parse yields arity where a classfile yields a
-- descriptor, so the two cannot share a method key. The reading excludes the generated jOOQ
-- package, which is exactly where a jump from @table or @field(name:) has to land, so a family
-- hanging off code_class could not answer for the half that matters most. And a .java edit
-- refreshes here without a generator round, so the two populations may legitimately disagree
-- between cadences; no view here asserts they agree, because the skew is real and visible skew
-- beats ambient skew.
-- The family is file-keyed, and its files are deliberately not store_source rows: store_source
-- is a capture round's read set, and a .java file is read by neither the SDL walk nor the
-- classpath scan. java_file carries this family's own freshness bookkeeping instead, which keeps
-- store_source's kind taxonomy closed and its currency scan proportional to what capture reads.
-- Graph scoping, for a query that needs it, happens on the code_ or sql_ side of the name join
-- through store_graph_source; this family answers for a file, and a file belongs to whoever
-- compiles it.
CREATE TABLE java_file (
  file        VARCHAR NOT NULL,
  source_root VARCHAR NOT NULL,
  stamp       VARCHAR NOT NULL,
  read_at     TIMESTAMP,
  PRIMARY KEY (file)
);
COMMENT ON TABLE java_file IS 'One .java file whose declarations this store holds, and the stamp they were read at. For example a consumer''s FilmService.java, under the root it was walked from and stamped with the content hash it was parsed at.';
COMMENT ON COLUMN java_file.file IS 'absolute normalised path of the source file; the family''s partition dimension and the grain its refresh runs at. Path form, as store_source spells a schema file, but never a store_source row (see this family''s charter) and never joined to code_class.source_name, which names a classpath entry rather than a source file';
COMMENT ON COLUMN java_file.source_root IS 'the walked root the file was reached under, on code_class.source_name''s terms: where the row came from, and so the scope whoever put it there owns. A walk prunes the files that left its own roots and leaves a sibling module''s alone. A file reachable under two nested roots is attributed to whichever root reached it first in the walk''s own order, one row either way';
COMMENT ON COLUMN java_file.stamp IS 'content hash of the file as parsed, spelled <scheme>:<hex> like every stamp SourceStamp writes and always the sha256: scheme here, this family reading every file it stamps. On ClasspathSources'' terms and for its reasons: modification time is a heuristic that a checkout, a rebase or a container layer defeats. NOT NULL because a file that cannot be read cannot be parsed either, so there is no partially-written partition to record';
COMMENT ON COLUMN java_file.read_at IS 'when the content behind this row''s stamp began being read, on store_source.read_at''s terms and for its reasons: written for every file a refresh hashed, whether it rewrote the row or found the stamp still current, and taken before the walk that read the file rather than at the write. A refresh that can establish the file has not moved since this instant skips the hash entirely, which is the whole saving; a refresh that cannot hashes it exactly as it did before the column existed. NULL only where no pass has dated the row yet, which is a transient state rather than the cold-start one: a DDL change rebuilds every persisted store, so the first pass after this column arrived fills it. What makes a session start cold is the comparison rather than the null, a value a previous session wrote being below this session''s floor';

CREATE TABLE java_source_root (
  source_root     VARCHAR NOT NULL,
  newest_modified TIMESTAMP NOT NULL,
  read_at         TIMESTAMP NOT NULL,
  PRIMARY KEY (source_root)
);
COMMENT ON TABLE java_source_root IS 'One walked source root, and when the newest .java file under it was last modified. For example a service module''s src/main/java, whose newest file was saved after the module last compiled.';
COMMENT ON COLUMN java_source_root.source_root IS 'the walked root, absolute and normalised, as java_file.source_root spells it; the key';
COMMENT ON COLUMN java_source_root.newest_modified IS 'the newest modification time among the .java files the walk found under the root, as the filesystem reports it. Recorded for the one question a time answers, whether the sources changed since the module compiled, and believed for nothing else: whether a file is read again is the stamp''s to decide, a checkout or a rebase moving times without moving content';
COMMENT ON COLUMN java_source_root.read_at IS 'when the walk that measured it began; a root the walk covers and finds no file under has no row';

CREATE TABLE java_class_declaration (
  file          VARCHAR NOT NULL,
  class_name    VARCHAR NOT NULL,
  source_line   INT     NOT NULL,
  source_column INT     NOT NULL,
  javadoc       VARCHAR,
  PRIMARY KEY (file, class_name),
  FOREIGN KEY (file) REFERENCES java_file (file)
);
COMMENT ON TABLE java_class_declaration IS 'One class, interface, enum, record or annotation declaration written in a source file, at the position the parse read it. For example the FilmService declaration at line 12 of that file, carrying the doc comment written above it.';
COMMENT ON COLUMN java_class_declaration.file IS 'the source file the declaration is written in; the family''s partition dimension and the key''s leading column';
COMMENT ON COLUMN java_class_declaration.class_name IS 'the dotted name the declaration spells: the file''s package, then the chain of enclosing class simple names. The join key to code_class.class_name, matched by name and by nothing else, a generated jOOQ class being a header there, without its members, and a whole declaration here';
COMMENT ON COLUMN java_class_declaration.source_line IS 'line of the declaration, 1-based per the Compiler Tree API''s LineMap; the store holds the parse''s own convention and an editor surface converts to its own. A parse positions every declaration it reads, so -1, that API''s own no-position sentinel, is defensive: it is carried through rather than dropped, because a declaration whose position is missing still has a doc comment worth holding';
COMMENT ON COLUMN java_class_declaration.source_column IS 'column of the declaration, 1-based on the same terms as source_line';
COMMENT ON COLUMN java_class_declaration.javadoc IS 'the declaration''s doc comment as the parse retained it, stripped; NULL where the declaration carries none, absence being a fact rather than an empty string. Display material, never a dimension';

CREATE TABLE java_method_declaration (
  file            VARCHAR NOT NULL,
  class_name      VARCHAR NOT NULL,
  method_name     VARCHAR NOT NULL,
  ordinal         INT     NOT NULL,
  parameter_count INT     NOT NULL,
  source_line     INT     NOT NULL,
  source_column   INT     NOT NULL,
  javadoc         VARCHAR,
  PRIMARY KEY (file, class_name, method_name, ordinal),
  FOREIGN KEY (file, class_name) REFERENCES java_class_declaration (file, class_name)
);
COMMENT ON TABLE java_method_declaration IS 'One method declaration on a declared class. For example the first findFilm declaration on FilmService at ordinal 0, beside a second overload of the same name at ordinal 1.';
COMMENT ON COLUMN java_method_declaration.file IS 'the source file the declaration is written in; the family''s partition dimension and the key''s leading column';
COMMENT ON COLUMN java_method_declaration.class_name IS 'the declaring class, as java_class_declaration spells it';
COMMENT ON COLUMN java_method_declaration.method_name IS 'the declared method name; not a key on its own, overloads sharing it';
COMMENT ON COLUMN java_method_declaration.ordinal IS 'declaration order within one file, class and method name, 0-based: the overload discriminator that keeps this key natural where the classfile side uses a descriptor. It follows the parse''s source order, so it is stable across re-parses of unchanged text and says nothing about which overload a call would bind to';
COMMENT ON COLUMN java_method_declaration.parameter_count IS 'the declared arity, which is what an unattributed parse can know: parameter types resolve to unqualified names as written rather than to the erased types the reading carries, so arity is the part that is a fact and the types are deliberately absent';
COMMENT ON COLUMN java_method_declaration.source_line IS 'line of the declaration, 1-based per the Compiler Tree API''s LineMap; the store holds the parse''s own convention and an editor surface converts to its own. A parse positions every declaration it reads, so -1, that API''s own no-position sentinel, is defensive: it is carried through rather than dropped, because a declaration whose position is missing still has a doc comment worth holding';
COMMENT ON COLUMN java_method_declaration.source_column IS 'column of the declaration, 1-based on the same terms as source_line';
COMMENT ON COLUMN java_method_declaration.javadoc IS 'the declaration''s doc comment as the parse retained it, stripped; NULL where the declaration carries none. Display material, never a dimension';

CREATE TABLE java_field_declaration (
  file          VARCHAR NOT NULL,
  class_name    VARCHAR NOT NULL,
  field_name    VARCHAR NOT NULL,
  source_line   INT     NOT NULL,
  source_column INT     NOT NULL,
  javadoc       VARCHAR,
  PRIMARY KEY (file, class_name, field_name),
  FOREIGN KEY (file, class_name) REFERENCES java_class_declaration (file, class_name)
);
COMMENT ON TABLE java_field_declaration IS 'One field declaration on a declared class, meaning a variable whose immediate encloser is the class. For example the FILM_ID constant on a generated Film table class, which is how a column''s own declaration becomes reachable.';
COMMENT ON COLUMN java_field_declaration.file IS 'the source file the declaration is written in; the family''s partition dimension and the key''s leading column';
COMMENT ON COLUMN java_field_declaration.class_name IS 'the declaring class, as java_class_declaration spells it';
COMMENT ON COLUMN java_field_declaration.field_name IS 'the declared field name as written; the Java name, which is what joins to a generated table class''s column constant, never the SQL column name';
COMMENT ON COLUMN java_field_declaration.source_line IS 'line of the declaration, 1-based per the Compiler Tree API''s LineMap; the store holds the parse''s own convention and an editor surface converts to its own. A parse positions every declaration it reads, so -1, that API''s own no-position sentinel, is defensive: it is carried through rather than dropped, because a declaration whose position is missing still has a doc comment worth holding';
COMMENT ON COLUMN java_field_declaration.source_column IS 'column of the declaration, 1-based on the same terms as source_line';
COMMENT ON COLUMN java_field_declaration.javadoc IS 'the declaration''s doc comment as the parse retained it, stripped; NULL where the declaration carries none. Display material, never a dimension';

-- ==== Compile oracle facts ========================================================
-- What the JDK compiler reported about a compile round over the emitted sources, in
-- javax.tools.Diagnostic's vocabulary. The family's writer runs after capture, on the dev
-- loop's compile cadence: in the batch pipeline javac runs in the consumer's own build after
-- the generator exits, so only a dev session ever writes here and a batch run's partition
-- stays empty rather than claiming anything it cannot know. One boundary is this family's own
-- and one-sided: an oracle's transcription is never derived, and a detection over store rows
-- must never acquire an oracle's family, or transcription and derivation blur.
CREATE TABLE javac_diagnostic (
  graph_name    VARCHAR NOT NULL,
  file          VARCHAR NOT NULL,
  line_number   BIGINT  NOT NULL,
  column_number BIGINT  NOT NULL,
  ordinal       INT     NOT NULL,
  kind          VARCHAR NOT NULL,
  code          VARCHAR,
  message       VARCHAR NOT NULL,
  PRIMARY KEY (graph_name, file, line_number, column_number, ordinal),
  FOREIGN KEY (graph_name) REFERENCES store_graph (graph_name)
);
COMMENT ON TABLE javac_diagnostic IS 'One javac diagnostic from the latest compile round over a graph''s emitted sources. For example an ERROR at line 42 of a generated FilmResolver.java, carrying the compiler''s own code and rendered message.';
COMMENT ON COLUMN javac_diagnostic.graph_name IS 'the graph whose emitted sources the round compiled; the partition dimension, anchored by store_graph and the scope of every statement the writer issues';
COMMENT ON COLUMN javac_diagnostic.file IS 'path of the generated .java javac anchored the diagnostic on, as javac named it and in java_file.file''s form, or the "(no source)" sentinel where javac reported no source; never NULL, this column being part of the key';
COMMENT ON COLUMN javac_diagnostic.line_number IS 'javac''s 1-based line, or -1 (javax.tools.Diagnostic.NOPOS) where javac reported no position; a sentinel, never NULL, this column being part of the key';
COMMENT ON COLUMN javac_diagnostic.column_number IS 'javac''s 1-based column, on the same NOPOS sentinel terms as line_number';
COMMENT ON COLUMN javac_diagnostic.ordinal IS 'tie-breaker assigned in round order per (graph_name, file, line_number, column_number), so repeated identical diagnostics at one position keep the key natural rather than decoration on a surrogate counter';
COMMENT ON COLUMN javac_diagnostic.kind IS 'javax.tools.Diagnostic.Kind.name(). An open column: a CHECK enumerating an externally owned taxonomy would be a hand-maintained copy of javac''s enum, the closed-CHECK convention covering only taxonomies the model owns';
COMMENT ON COLUMN javac_diagnostic.code IS 'Diagnostic.getCode(), the compiler''s stable diagnostic identifier; NULL exactly where javac returns none, and the typed dimension a display list never had';
COMMENT ON COLUMN javac_diagnostic.message IS 'javac''s own rendered text (root locale); a transcribed fact because the oracle authored it, but display material: never a dimension, never an agreement anchor';

-- ==== Derived intent: claims ======================================================
--
-- DEPRECATED, THE WHOLE FAMILY. Every other family in this store is some gatherer's: the
-- gatherer reads one corpus, owns the relations it writes, and answers for their lifecycle.
-- This one is nobody's, and the roster says so out loud. Of 84 relations here, 9 carry an
-- owner in meta_relation and the rest carry none; sql_ is 16 of 17 and code_ is 16 of 16.
--
-- A family with no owner is where a fact goes when nobody placed it, and the cost of that is
-- not untidiness. It is that the fact arrives late. A reader needing something the store does
-- not hold derives it here, over rows several families upstream, and the next reader needing the same
-- thing derives it again from a slightly different angle. When such a derivation turns out to be
-- dear, the only answer available at this depth is to materialize it, so a register grew to do
-- that: every rule it ever held was a relation in this family, and not one was in a family that
-- had an owner. That was the shape of the problem rather than a coincidence. Materializing is
-- what a store does when it cannot move a fact earlier, and it cannot move a fact earlier when
-- nobody owns where the fact would go; the register emptied when its rules became stages of the
-- graphitron gatherer, which owns them, and those relations left this family for that one.
--
-- So the rule for anything landing here from now on is: do not. If a fact is missing, capture it
-- as early as it can be captured, in the family that owns the corpus it comes from, where every
-- reader reaches it and no reader re-derives it. The ownership section of
-- docs/architecture/explanation/fact-model.adoc carries the rule for deciding which family that
-- is, and what becomes of a rule whose facts genuinely cross more than one.
--
-- Nine relations here are declared in meta_relation and their comments are their declarations
-- rendered, which MetaDeclarationGateTest holds verbatim, so they carry no notice of their own
-- and this header speaks for them.
--
-- A resolution is a resident in its own right rather than a CTE inside its first reader.
-- graphitron_spelled_table answers the rule every table name is subject to whatever site wrote it,
-- and graphitron_tabletype keys a type's @table over it rather than copying it; graphitron_path_element_table then states what a
-- @reference path element names apart from the join path that walks it. A @routine binds no table:
-- graphitron_tabletype is the @table population alone, and the type a field whose path
-- ends on a @routine returns has the function's result as its rows, which graphitron_routine_result
-- states for every reader that asks where such a type is read.
--
-- The family's second resident group is the input occurrence surface: the path relation and
-- its step child at the DDL tail enumerate every occurrence of the input surface under a use
-- site (an occurrence path is its own identity, so this lands ahead of any input-member
-- coordinate work).
--
-- The family's fourth resident group is the class-backing chain, which answers which Java class
-- a type is backed by and is a chain rather than a relation because that question decomposes.
-- The class-side half of it is no longer resident here: code_type_element peels a type down to
-- the class it delivers and the reading writes that down, so the chain starts from a captured fact
-- rather than from a derivation over the census. The graphitron gatherer now anchors the rest as
-- graphitron_type_backing, after the classpath is read: a producer's resolved method grounds a
-- type, and the closure over the members each backed class offers reaches the rest, with
-- intent_type_backing_conflict naming the types answered more than one way. The decomposition is
-- the point: the walk being replaced carried the grounding, the peel, the hop, the cardinality
-- reading and a table shadow as clauses of one procedure, and each of those is a fact with its own
-- grain and its own anchor.
--
-- A resolution is keyed by whatever its own question is about, which is why not every resident
-- leads with graph_name. What a declared type delivers is the case that established it: a rule
-- over the classpath with no graph in it, carrying the source's key, reached by a graph through
-- store_graph_source like any other source-keyed fact. Keying it by graph would have made one copy
-- of the answer per graph that reads the class, which is a claim about the graph the rule never
-- makes. That keying is also what let the fact leave this family without being restated: a row
-- keyed by its own question rather than by its reader is one the gatherer owning the corpus can
-- write, and code_type_element writes it there now. Which phase a row belongs to is decided by
-- what its value is a function of, and never by which key it happens to carry: a row recomputable
-- from captured facts alone is a derived fact, whatever produced it.
--
-- sql_name_matched_key_column is the same shape one family over, and it shows what the keying buys
-- besides economy. Whether a table-valued function's result can be keyed to a table at all is a
-- question about a catalog, so the relation carries no graph either; and because it does not, the
-- two consumers that ask it can find their two ends in completely different places.
-- graphitron_join_path_step_rule finds them in an authored path element, and a routine
-- write finds them in its own path's landing and its payload data field's fill. Keyed by a coordinate, the rule would have had to be written once per kind of
-- coordinate that asks, which is the duplication the generator carries today and the reason this
-- relation exists.

CREATE TABLE graphitron_spelled_table (
  graph_name        VARCHAR NOT NULL,
  spelling          VARCHAR NOT NULL,
  table_source_name VARCHAR NOT NULL,
  table_schema      VARCHAR NOT NULL,
  table_name        VARCHAR NOT NULL,
  candidates        INTEGER NOT NULL,
  PRIMARY KEY (graph_name, spelling, table_source_name, table_schema, table_name),
  FOREIGN KEY (graph_name) REFERENCES store_graph (graph_name)
);
COMMENT ON TABLE graphitron_spelled_table IS 'How a written table name resolves against the catalog census: one row per candidate table, keyed on the spelling itself rather than on any one site that wrote it. For example a schema writing @table(name: "film") and a @reference path element naming film draws one row between them, and a name two schemas both declare draws two rows saying two candidates.';
COMMENT ON COLUMN graphitron_spelled_table.graph_name IS 'the owning graph''s partition, carried from the authoring relation';
COMMENT ON COLUMN graphitron_spelled_table.spelling IS 'the table name as written at some site in this graph, qualifier included where one was written; the key this resolution answers for';
COMMENT ON COLUMN graphitron_spelled_table.table_source_name IS 'the resolved table''s catalog partition, the first column of the sql_table key this row names';
COMMENT ON COLUMN graphitron_spelled_table.table_schema IS 'the resolved table''s SQL schema; what tells two candidates of one spelling apart';
COMMENT ON COLUMN graphitron_spelled_table.table_name IS 'the resolved table''s SQL name. With the two columns above this is sql_table''s full key';
COMMENT ON COLUMN graphitron_spelled_table.candidates IS 'how many tables the spelling resolves to, this row being one of them; 1 on an unambiguous spelling';

CREATE TABLE graphitron_path_element_key (
  graph_name             VARCHAR NOT NULL,
  source_name            VARCHAR NOT NULL,
  source_line            INT     NOT NULL,
  source_column          INT     NOT NULL,
  constraint_source_name VARCHAR NOT NULL,
  constraint_schema      VARCHAR NOT NULL,
  constraint_table       VARCHAR NOT NULL,
  constraint_name        VARCHAR NOT NULL,
  matched_by             VARCHAR NOT NULL,
  touched_at             TIMESTAMP NOT NULL,
  PRIMARY KEY (graph_name, source_name, source_line, source_column,
               constraint_source_name, constraint_schema, constraint_table, constraint_name),
  CHECK (matched_by IN ('SQL_NAME', 'JOOQ_NAME')),
  FOREIGN KEY (graph_name, source_name, source_line, source_column)
    REFERENCES graphitron_ast_reference_key_step_entry (graph_name, source_name, source_line, source_column)
    ON DELETE CASCADE,
  FOREIGN KEY (constraint_source_name, constraint_schema, constraint_table, constraint_name)
    REFERENCES sql_referential_constraint (source_name, table_schema, table_name, constraint_name)
    ON DELETE CASCADE
);
COMMENT ON TABLE graphitron_path_element_key IS 'A foreign key a path element names: one row per element and candidate key. For example {key: "film_actor_actor_id_fkey"} names public.film_actor''s key to actor, and an unqualified {key: "note_event_fk"} names both schemas'' note_event_fk.';
COMMENT ON COLUMN graphitron_path_element_key.graph_name IS 'the owning graph''s partition, carried from the element''s entry';
COMMENT ON COLUMN graphitron_path_element_key.source_name IS 'the file the element was written in';
COMMENT ON COLUMN graphitron_path_element_key.source_line IS 'the element''s source line, 1-based';
COMMENT ON COLUMN graphitron_path_element_key.source_column IS 'the element''s source column. With the three columns before it, the element''s key in graphitron_ast_reference_key_step_entry, which holds the spelling this row resolves';
COMMENT ON COLUMN graphitron_path_element_key.constraint_source_name IS 'the catalog partition of the table holding the key';
COMMENT ON COLUMN graphitron_path_element_key.constraint_schema IS 'the SQL schema of the table holding the key';
COMMENT ON COLUMN graphitron_path_element_key.constraint_table IS 'the table holding the key, the referencing side';
COMMENT ON COLUMN graphitron_path_element_key.constraint_name IS 'the key''s SQL name. With the three columns before it, sql_referential_constraint''s key';
COMMENT ON COLUMN graphitron_path_element_key.matched_by IS 'which name the written spelling matched: SQL_NAME, the key''s SQL name, or JOOQ_NAME, the generated Keys constant, which answers only where no SQL name in the graph''s catalogs does. The editor and the MCP server say which an author wrote';
COMMENT ON COLUMN graphitron_path_element_key.touched_at IS 'when the reading that last found this candidate ran: the mark the sweep reads, so a candidate no longer found goes';

CREATE VIEW graphitron_path_element_key_rule
  (graph_name, source_name, source_line, source_column,
   constraint_source_name, constraint_schema, constraint_table, constraint_name, matched_by) AS
-- The generator's precedence: a written name is a key's SQL name wherever one in the graph's
-- catalogs answers it, and only where none does is it the generated Keys constant. A schema written
-- before the name binds the schema of the table holding the key, after that choice and never
-- instead of it. Both sides are stored folded columns, so each match is an equality.
SELECT k.graph_name, k.source_name, k.source_line, k.source_column,
       c.source_name, c.table_schema, c.table_name, c.constraint_name, 'SQL_NAME'
  FROM graphitron_ast_reference_key_step_entry k
  JOIN store_graph_source m ON m.graph_name = k.graph_name
  JOIN sql_constraint c
    ON c.source_name = m.source_name AND c.constraint_name_upper = k.key_ref_name_part_upper
  JOIN sql_referential_constraint rc
    ON rc.source_name = c.source_name AND rc.table_schema = c.table_schema
   AND rc.table_name = c.table_name AND rc.constraint_name = c.constraint_name
 WHERE k.key_ref_namespace_part_upper IS NULL OR c.table_schema_upper = k.key_ref_namespace_part_upper
UNION ALL
SELECT k.graph_name, k.source_name, k.source_line, k.source_column,
       c.source_name, c.table_schema, c.table_name, c.constraint_name, 'JOOQ_NAME'
  FROM graphitron_ast_reference_key_step_entry k
  JOIN store_graph_source m ON m.graph_name = k.graph_name
  JOIN sql_constraint c
    ON c.source_name = m.source_name AND c.jooq_name_upper = k.key_ref_name_part_upper
  JOIN sql_referential_constraint rc
    ON rc.source_name = c.source_name AND rc.table_schema = c.table_schema
   AND rc.table_name = c.table_name AND rc.constraint_name = c.constraint_name
 WHERE (k.key_ref_namespace_part_upper IS NULL OR c.table_schema_upper = k.key_ref_namespace_part_upper)
   AND NOT EXISTS (SELECT 1 FROM sql_constraint s
                     JOIN sql_referential_constraint src
                       ON src.source_name = s.source_name AND src.table_schema = s.table_schema
                      AND src.table_name = s.table_name AND src.constraint_name = s.constraint_name
                     JOIN store_graph_source sm ON sm.source_name = s.source_name
                    WHERE sm.graph_name = k.graph_name
                      AND s.constraint_name_upper = k.key_ref_name_part_upper);
COMMENT ON VIEW graphitron_path_element_key_rule IS 'One row the path element key rule computes, in the shape graphitron_path_element_key stores: the rule itself, evaluated on demand rather than read off disk. For example a capture inserts this view''s rows for one graph into graphitron_path_element_key, which is the name every reader spells; naming this relation instead asks for on-demand evaluation and gets it, which is a performance bug rather than a wrong answer.';
-- COMMENT ON COLUMN graphitron_path_element_key_rule.graph_name IS 'the owning graph''s partition, carried from the element''s entry';
-- COMMENT ON COLUMN graphitron_path_element_key_rule.source_name IS 'the file the element was written in';
-- COMMENT ON COLUMN graphitron_path_element_key_rule.source_line IS 'the element''s source line';
-- COMMENT ON COLUMN graphitron_path_element_key_rule.source_column IS 'the element''s source column';
-- COMMENT ON COLUMN graphitron_path_element_key_rule.constraint_source_name IS 'the catalog partition of the table holding the candidate key';
-- COMMENT ON COLUMN graphitron_path_element_key_rule.constraint_schema IS 'the SQL schema of that table';
-- COMMENT ON COLUMN graphitron_path_element_key_rule.constraint_table IS 'the table holding the candidate key';
-- COMMENT ON COLUMN graphitron_path_element_key_rule.constraint_name IS 'the candidate key''s SQL name';
-- COMMENT ON COLUMN graphitron_path_element_key_rule.matched_by IS 'SQL_NAME or JOOQ_NAME, the arm that matched the spelling';

CREATE TABLE graphitron_path_element_primary_key (
  graph_name        VARCHAR NOT NULL,
  source_name       VARCHAR NOT NULL,
  source_line       INT     NOT NULL,
  source_column     INT     NOT NULL,
  table_source_name VARCHAR NOT NULL,
  table_schema      VARCHAR NOT NULL,
  table_name        VARCHAR NOT NULL,
  matched_by        VARCHAR NOT NULL,
  touched_at        TIMESTAMP NOT NULL,
  PRIMARY KEY (graph_name, source_name, source_line, source_column,
               table_source_name, table_schema, table_name),
  CHECK (matched_by IN ('SQL_NAME', 'JOOQ_NAME')),
  FOREIGN KEY (graph_name, source_name, source_line, source_column)
    REFERENCES graphitron_ast_reference_key_step_entry (graph_name, source_name, source_line, source_column)
    ON DELETE CASCADE,
  FOREIGN KEY (table_source_name, table_schema, table_name)
    REFERENCES sql_primary_key (source_name, table_schema, table_name)
    ON DELETE CASCADE
);
COMMENT ON TABLE graphitron_path_element_primary_key IS 'A table''s own primary key a path element names: one row per element whose key: spelling names a table''s primary key, per candidate key. For example {key: "film_pkey"} names public.film''s primary key, which joins each film row to itself.';
COMMENT ON COLUMN graphitron_path_element_primary_key.graph_name IS 'the owning graph''s partition, carried from the element''s entry';
COMMENT ON COLUMN graphitron_path_element_primary_key.source_name IS 'the file the element was written in';
COMMENT ON COLUMN graphitron_path_element_primary_key.source_line IS 'the element''s source line, 1-based';
COMMENT ON COLUMN graphitron_path_element_primary_key.source_column IS 'the element''s source column. With the three columns before it, the element''s key in graphitron_ast_reference_key_step_entry, which holds the spelling this row resolves';
COMMENT ON COLUMN graphitron_path_element_primary_key.table_source_name IS 'the catalog partition of the table whose primary key the element names';
COMMENT ON COLUMN graphitron_path_element_primary_key.table_schema IS 'the SQL schema of that table';
COMMENT ON COLUMN graphitron_path_element_primary_key.table_name IS 'the table whose primary key the element names. With the two columns before it, sql_primary_key''s key, which names the constraint';
COMMENT ON COLUMN graphitron_path_element_primary_key.matched_by IS 'which name the written spelling matched: SQL_NAME, the key''s SQL name, or JOOQ_NAME, the generated Keys constant, which answers only where no primary key''s SQL name in the graph''s catalogs does. The editor and the MCP server say which an author wrote';
COMMENT ON COLUMN graphitron_path_element_primary_key.touched_at IS 'when the reading that last found this candidate ran: the mark the sweep reads, so a candidate no longer found goes';

CREATE VIEW graphitron_path_element_primary_key_rule
  (graph_name, source_name, source_line, source_column,
   table_source_name, table_schema, table_name, matched_by) AS
-- The precedence graphitron_path_element_key_rule states for a foreign key, over primary keys: a
-- written name is a primary key's SQL name wherever one in the graph's catalogs answers it, and only
-- where none does is it the generated Keys constant. A schema written before the name binds the
-- schema of the key's table.
SELECT k.graph_name, k.source_name, k.source_line, k.source_column,
       p.source_name, p.table_schema, p.table_name, 'SQL_NAME'
  FROM graphitron_ast_reference_key_step_entry k
  JOIN store_graph_source m ON m.graph_name = k.graph_name
  JOIN sql_constraint c
    ON c.source_name = m.source_name AND c.constraint_name_upper = k.key_ref_name_part_upper
  JOIN sql_primary_key p
    ON p.source_name = c.source_name AND p.table_schema = c.table_schema
   AND p.table_name = c.table_name AND p.constraint_name = c.constraint_name
 WHERE k.key_ref_namespace_part_upper IS NULL OR c.table_schema_upper = k.key_ref_namespace_part_upper
UNION ALL
SELECT k.graph_name, k.source_name, k.source_line, k.source_column,
       p.source_name, p.table_schema, p.table_name, 'JOOQ_NAME'
  FROM graphitron_ast_reference_key_step_entry k
  JOIN store_graph_source m ON m.graph_name = k.graph_name
  JOIN sql_constraint c
    ON c.source_name = m.source_name AND c.jooq_name_upper = k.key_ref_name_part_upper
  JOIN sql_primary_key p
    ON p.source_name = c.source_name AND p.table_schema = c.table_schema
   AND p.table_name = c.table_name AND p.constraint_name = c.constraint_name
 WHERE (k.key_ref_namespace_part_upper IS NULL OR c.table_schema_upper = k.key_ref_namespace_part_upper)
   AND NOT EXISTS (SELECT 1 FROM sql_constraint s
                     JOIN sql_primary_key sp
                       ON sp.source_name = s.source_name AND sp.table_schema = s.table_schema
                      AND sp.table_name = s.table_name AND sp.constraint_name = s.constraint_name
                     JOIN store_graph_source sm ON sm.source_name = s.source_name
                    WHERE sm.graph_name = k.graph_name
                      AND s.constraint_name_upper = k.key_ref_name_part_upper);
COMMENT ON VIEW graphitron_path_element_primary_key_rule IS 'One row the path element primary key rule computes, in the shape graphitron_path_element_primary_key stores: the rule itself, evaluated on demand rather than read off disk. For example a capture inserts this view''s rows for one graph into graphitron_path_element_primary_key, which is the name every reader spells; naming this relation instead asks for on-demand evaluation and gets it, which is a performance bug rather than a wrong answer.';
-- COMMENT ON COLUMN graphitron_path_element_primary_key_rule.graph_name IS 'the owning graph''s partition, carried from the element''s entry';
-- COMMENT ON COLUMN graphitron_path_element_primary_key_rule.source_name IS 'the file the element was written in';
-- COMMENT ON COLUMN graphitron_path_element_primary_key_rule.source_line IS 'the element''s source line';
-- COMMENT ON COLUMN graphitron_path_element_primary_key_rule.source_column IS 'the element''s source column';
-- COMMENT ON COLUMN graphitron_path_element_primary_key_rule.table_source_name IS 'the catalog partition of the table whose primary key the element names';
-- COMMENT ON COLUMN graphitron_path_element_primary_key_rule.table_schema IS 'the SQL schema of that table';
-- COMMENT ON COLUMN graphitron_path_element_primary_key_rule.table_name IS 'the table whose primary key the element names';
-- COMMENT ON COLUMN graphitron_path_element_primary_key_rule.matched_by IS 'SQL_NAME or JOOQ_NAME, the arm that matched the spelling';

CREATE TABLE graphitron_path_element_table (
  graph_name        VARCHAR NOT NULL,
  source_name       VARCHAR NOT NULL,
  source_line       INT     NOT NULL,
  source_column     INT     NOT NULL,
  table_source_name VARCHAR NOT NULL,
  table_schema      VARCHAR NOT NULL,
  table_name        VARCHAR NOT NULL,
  touched_at        TIMESTAMP NOT NULL,
  PRIMARY KEY (graph_name, source_name, source_line, source_column,
               table_source_name, table_schema, table_name),
  FOREIGN KEY (graph_name, source_name, source_line, source_column)
    REFERENCES graphitron_ast_reference_table_step_entry (graph_name, source_name, source_line, source_column)
    ON DELETE CASCADE,
  FOREIGN KEY (table_source_name, table_schema, table_name)
    REFERENCES sql_table (source_name, table_schema, table_name) ON DELETE CASCADE
);
COMMENT ON TABLE graphitron_path_element_table IS 'A table a path element names: one row per element and candidate table. For example {table: "film_actor"} names public.film_actor, and {table: "multischema_a.note"} names that schema''s note alone.';
COMMENT ON COLUMN graphitron_path_element_table.graph_name IS 'the owning graph''s partition, carried from the element''s entry';
COMMENT ON COLUMN graphitron_path_element_table.source_name IS 'the file the element was written in';
COMMENT ON COLUMN graphitron_path_element_table.source_line IS 'the element''s source line, 1-based';
COMMENT ON COLUMN graphitron_path_element_table.source_column IS 'the element''s source column. With the three columns before it, the element''s key in graphitron_ast_reference_table_step_entry, which holds the spelling this row resolves';
COMMENT ON COLUMN graphitron_path_element_table.table_source_name IS 'the named table''s catalog partition';
COMMENT ON COLUMN graphitron_path_element_table.table_schema IS 'the named table''s SQL schema';
COMMENT ON COLUMN graphitron_path_element_table.table_name IS 'the named table''s SQL name. With the two columns before it, sql_table''s key';
COMMENT ON COLUMN graphitron_path_element_table.touched_at IS 'when the reading that last found this candidate ran: the mark the sweep reads, so a candidate no longer found goes';

CREATE VIEW graphitron_path_element_table_rule
  (graph_name, source_name, source_line, source_column,
   table_source_name, table_schema, table_name) AS
-- A qualified name binds the schema and the name; an unqualified one, whose namespace half is null,
-- matches on its name in any of the graph's catalogs. Both sides are stored folded columns.
SELECT t.graph_name, t.source_name, t.source_line, t.source_column,
       st.source_name, st.table_schema, st.table_name
  FROM graphitron_ast_reference_table_step_entry t
  JOIN store_graph_source m ON m.graph_name = t.graph_name
  JOIN sql_table st
    ON st.source_name = m.source_name AND st.table_name_upper = t.table_ref_name_part_upper
 WHERE t.table_ref_namespace_part_upper IS NULL OR st.table_schema_upper = t.table_ref_namespace_part_upper;
COMMENT ON VIEW graphitron_path_element_table_rule IS 'One row the path element table rule computes, in the shape graphitron_path_element_table stores: the rule itself, evaluated on demand rather than read off disk. For example a capture inserts this view''s rows for one graph into graphitron_path_element_table, which is the name every reader spells; naming this relation instead asks for on-demand evaluation and gets it, which is a performance bug rather than a wrong answer.';
-- COMMENT ON COLUMN graphitron_path_element_table_rule.graph_name IS 'the owning graph''s partition, carried from the element''s entry';
-- COMMENT ON COLUMN graphitron_path_element_table_rule.source_name IS 'the file the element was written in';
-- COMMENT ON COLUMN graphitron_path_element_table_rule.source_line IS 'the element''s source line';
-- COMMENT ON COLUMN graphitron_path_element_table_rule.source_column IS 'the element''s source column';
-- COMMENT ON COLUMN graphitron_path_element_table_rule.table_source_name IS 'the candidate table''s catalog partition';
-- COMMENT ON COLUMN graphitron_path_element_table_rule.table_schema IS 'the candidate table''s SQL schema';
-- COMMENT ON COLUMN graphitron_path_element_table_rule.table_name IS 'the candidate table''s SQL name';

CREATE TABLE graphitron_path_element_method (
  graph_name         VARCHAR NOT NULL,
  source_name        VARCHAR NOT NULL,
  source_line        INT     NOT NULL,
  source_column      INT     NOT NULL,
  method_source_name VARCHAR NOT NULL,
  method_class_name  VARCHAR NOT NULL,
  method_name        VARCHAR NOT NULL,
  method_descriptor  VARCHAR NOT NULL,
  touched_at         TIMESTAMP NOT NULL,
  PRIMARY KEY (graph_name, source_name, source_line, source_column,
               method_source_name, method_class_name, method_name, method_descriptor),
  FOREIGN KEY (graph_name, source_name, source_line, source_column)
    REFERENCES graphitron_ast_reference_condition_step_entry (graph_name, source_name, source_line, source_column)
    ON DELETE CASCADE,
  FOREIGN KEY (method_source_name, method_class_name, method_name, method_descriptor)
    REFERENCES code_condition_method (source_name, class_name, method_name, descriptor) ON DELETE CASCADE
);
COMMENT ON TABLE graphitron_path_element_method IS 'A condition method a path element names: one row per element and candidate method. For example {condition: {className: "no.example.Conditions", method: "liveActor"}} names that class''s liveActor, one row per overload.';
COMMENT ON COLUMN graphitron_path_element_method.graph_name IS 'the owning graph''s partition, carried from the element''s entry';
COMMENT ON COLUMN graphitron_path_element_method.source_name IS 'the file the element was written in';
COMMENT ON COLUMN graphitron_path_element_method.source_line IS 'the element''s source line, 1-based';
COMMENT ON COLUMN graphitron_path_element_method.source_column IS 'the element''s source column. With the three columns before it, the element''s key in graphitron_ast_reference_condition_step_entry, which holds the class and method this row resolves';
COMMENT ON COLUMN graphitron_path_element_method.method_source_name IS 'the classpath entry the method was read from';
COMMENT ON COLUMN graphitron_path_element_method.method_class_name IS 'the class declaring the method';
COMMENT ON COLUMN graphitron_path_element_method.method_name IS 'the method';
COMMENT ON COLUMN graphitron_path_element_method.method_descriptor IS 'the method''s descriptor, telling overloads apart. With the three columns before it, code_condition_method''s key';
COMMENT ON COLUMN graphitron_path_element_method.touched_at IS 'when the reading that last found this candidate ran: the mark the sweep reads, so a candidate no longer found goes';

CREATE VIEW graphitron_path_element_method_rule
  (graph_name, source_name, source_line, source_column,
   method_source_name, method_class_name, method_name, method_descriptor) AS
-- The class and method as written, among the condition methods of the class the graph resolves the
-- name to; an element naming no class or no method names nothing.
SELECT c.graph_name, c.source_name, c.source_line, c.source_column,
       cm.source_name, cm.class_name, cm.method_name, cm.descriptor
  FROM graphitron_ast_reference_condition_step_entry c
  JOIN code_graph_class m ON m.graph_name = c.graph_name AND m.class_name = c.class_name
  JOIN code_condition_method cm
    ON cm.source_name = m.source_name AND cm.class_name = m.class_name AND cm.method_name = c.method;
COMMENT ON VIEW graphitron_path_element_method_rule IS 'One row the path element method rule computes, in the shape graphitron_path_element_method stores: the rule itself, evaluated on demand rather than read off disk. For example a capture inserts this view''s rows for one graph into graphitron_path_element_method, which is the name every reader spells; naming this relation instead asks for on-demand evaluation and gets it, which is a performance bug rather than a wrong answer.';
-- COMMENT ON COLUMN graphitron_path_element_method_rule.graph_name IS 'the owning graph''s partition, carried from the element''s entry';
-- COMMENT ON COLUMN graphitron_path_element_method_rule.source_name IS 'the file the element was written in';
-- COMMENT ON COLUMN graphitron_path_element_method_rule.source_line IS 'the element''s source line';
-- COMMENT ON COLUMN graphitron_path_element_method_rule.source_column IS 'the element''s source column';
-- COMMENT ON COLUMN graphitron_path_element_method_rule.method_source_name IS 'the candidate method''s classpath entry';
-- COMMENT ON COLUMN graphitron_path_element_method_rule.method_class_name IS 'the class declaring the candidate method';
-- COMMENT ON COLUMN graphitron_path_element_method_rule.method_name IS 'the candidate method';
-- COMMENT ON COLUMN graphitron_path_element_method_rule.method_descriptor IS 'the candidate method''s descriptor';

CREATE TABLE graphitron_path_element_routine (
  graph_name          VARCHAR NOT NULL,
  source_name         VARCHAR NOT NULL,
  source_line         INT     NOT NULL,
  source_column       INT     NOT NULL,
  routine_source_name VARCHAR NOT NULL,
  table_schema        VARCHAR NOT NULL,
  routine_name        VARCHAR NOT NULL,
  touched_at          TIMESTAMP NOT NULL,
  PRIMARY KEY (graph_name, source_name, source_line, source_column,
               routine_source_name, table_schema, routine_name),
  FOREIGN KEY (graph_name, source_name, source_line, source_column)
    REFERENCES graphitron_ast_routine_entry (graph_name, source_name, source_line, source_column)
    ON DELETE CASCADE,
  FOREIGN KEY (routine_source_name, table_schema, routine_name)
    REFERENCES sql_routine (source_name, table_schema, routine_name) ON DELETE CASCADE
);
COMMENT ON TABLE graphitron_path_element_routine IS 'A routine a path element names: one row per @routine element and candidate routine with a generated call. For example @routine(name: "films_for_actor") names public.films_for_actor, whose call is the Routines method filmsForActor.';
COMMENT ON COLUMN graphitron_path_element_routine.graph_name IS 'the owning graph''s partition, carried from the element''s entry';
COMMENT ON COLUMN graphitron_path_element_routine.source_name IS 'the file the element was written in';
COMMENT ON COLUMN graphitron_path_element_routine.source_line IS 'the element''s source line, 1-based';
COMMENT ON COLUMN graphitron_path_element_routine.source_column IS 'the element''s source column. With the three columns before it, the element''s key in graphitron_ast_routine_entry, which holds the spelling this row resolves';
COMMENT ON COLUMN graphitron_path_element_routine.routine_source_name IS 'the named routine''s catalog partition';
COMMENT ON COLUMN graphitron_path_element_routine.table_schema IS 'the named routine''s SQL schema';
COMMENT ON COLUMN graphitron_path_element_routine.routine_name IS 'the named routine''s SQL name. With the two columns before it, sql_routine''s key, which the function''s row in sql_table shares';
COMMENT ON COLUMN graphitron_path_element_routine.touched_at IS 'when the reading that last found this candidate ran: the mark the sweep reads, so a candidate no longer found goes';

CREATE VIEW graphitron_path_element_routine_rule
  (graph_name, source_name, source_line, source_column,
   routine_source_name, table_schema, routine_name) AS
-- The routine name meets the graph's catalogs as a written table name does, a routine with no
-- generated call naming nothing the generator could call.
SELECT r.graph_name, r.source_name, r.source_line, r.source_column,
       sr.source_name, sr.table_schema, sr.routine_name
  FROM graphitron_ast_routine_entry r
  JOIN graphitron_spelled_table s
    ON s.graph_name = r.graph_name AND s.spelling = r.routine_ref
  JOIN sql_routine sr
    ON sr.source_name = s.table_source_name AND sr.table_schema = s.table_schema
   AND sr.routine_name = s.table_name
 WHERE sr.routines_class_fqn IS NOT NULL;
COMMENT ON VIEW graphitron_path_element_routine_rule IS 'One row the path element routine rule computes, in the shape graphitron_path_element_routine stores: the rule itself, evaluated on demand rather than read off disk. For example a capture inserts this view''s rows for one graph into graphitron_path_element_routine, which is the name every reader spells; naming this relation instead asks for on-demand evaluation and gets it, which is a performance bug rather than a wrong answer.';
-- COMMENT ON COLUMN graphitron_path_element_routine_rule.graph_name IS 'the owning graph''s partition, carried from the element''s entry';
-- COMMENT ON COLUMN graphitron_path_element_routine_rule.source_name IS 'the file the element was written in';
-- COMMENT ON COLUMN graphitron_path_element_routine_rule.source_line IS 'the element''s source line';
-- COMMENT ON COLUMN graphitron_path_element_routine_rule.source_column IS 'the element''s source column';
-- COMMENT ON COLUMN graphitron_path_element_routine_rule.routine_source_name IS 'the candidate routine''s catalog partition';
-- COMMENT ON COLUMN graphitron_path_element_routine_rule.table_schema IS 'the candidate routine''s SQL schema';
-- COMMENT ON COLUMN graphitron_path_element_routine_rule.routine_name IS 'the candidate routine''s SQL name';

CREATE TABLE graphitron_routine_result (
  graph_name        VARCHAR NOT NULL,
  type_name         VARCHAR NOT NULL,
  field_name        VARCHAR NOT NULL,
  target_type_name  VARCHAR NOT NULL,
  table_source_name VARCHAR NOT NULL,
  table_schema      VARCHAR NOT NULL,
  table_name        VARCHAR NOT NULL,
  touched_at        TIMESTAMP NOT NULL,
  PRIMARY KEY (graph_name, type_name, field_name),
  FOREIGN KEY (graph_name, type_name, field_name)
    REFERENCES graphitron_field (graph_name, type_name, field_name) ON DELETE CASCADE,
  FOREIGN KEY (table_source_name, table_schema, table_name)
    REFERENCES sql_table (source_name, table_schema, table_name) ON DELETE CASCADE
);
-- Readers ask by the type a field returns: is it one whose rows are a function's result.
CREATE INDEX graphitron_routine_result_target_ix ON graphitron_routine_result (graph_name, target_type_name);
COMMENT ON TABLE graphitron_routine_result IS 'Where a field''s path ends on a @routine: one row per field whose last written element is a @routine naming one routine, with the function whose result the rows of the type it returns are. For example Actor.films over @routine(name: "films_for_actor") returns ActorFilm, whose rows are films_for_actor''s result; a mutation''s @routine is a write and draws no row.';
COMMENT ON COLUMN graphitron_routine_result.graph_name IS 'the owning graph''s partition';
COMMENT ON COLUMN graphitron_routine_result.type_name IS 'the type declaring the field';
COMMENT ON COLUMN graphitron_routine_result.field_name IS 'the field whose path ends on the @routine';
COMMENT ON COLUMN graphitron_routine_result.target_type_name IS 'the type the field returns, a connection''s element where the field returns one: the type whose rows are the function''s result';
COMMENT ON COLUMN graphitron_routine_result.table_source_name IS 'the function''s catalog partition';
COMMENT ON COLUMN graphitron_routine_result.table_schema IS 'the function''s SQL schema';
COMMENT ON COLUMN graphitron_routine_result.table_name IS 'the function''s name: with the two columns before it, the key of its FUNCTION row in sql_table, which no type is bound to';
COMMENT ON COLUMN graphitron_routine_result.touched_at IS 'when the reading that last found this row ran: the mark the sweep reads, so a field whose path no longer ends on a @routine goes';

CREATE VIEW graphitron_routine_result_rule
  (graph_name, type_name, field_name, target_type_name,
   table_source_name, table_schema, table_name) AS
-- The function a field's path ends on, where its last written element is a @routine naming one
-- routine: the rows of the type it returns are that function's result. A write's routine is not one,
-- its payload holding an object as any write's does. The declaration read is the one graphql_field
-- anchored, so a field declared twice is read once.
SELECT gf.graph_name, gf.type_name, gf.field_name, ft.target_type_name,
       fn.source_name, fn.table_schema, fn.table_name
  FROM graphql_field gf
  JOIN graphitron_field_target ft
    ON ft.graph_name = gf.graph_name AND ft.type_name = gf.type_name AND ft.field_name = gf.field_name
  JOIN graphitron_ast_field_path_entry e
    ON e.graph_name = gf.graph_name AND e.source_name = gf.source_name
   AND e.field_line = gf.source_line AND e.field_column = gf.source_column
  JOIN graphitron_path_element_routine er
    ON er.graph_name = e.graph_name AND er.source_name = e.source_name
   AND er.source_line = e.element_line AND er.source_column = e.element_column
  JOIN sql_table fn
    ON fn.source_name = er.routine_source_name AND fn.table_schema = er.table_schema
   AND fn.table_name = er.routine_name
 WHERE NOT EXISTS (SELECT 1 FROM graphitron_ast_field_path_entry later
                    WHERE later.graph_name = e.graph_name AND later.source_name = e.source_name
                      AND later.field_line = e.field_line AND later.field_column = e.field_column
                      AND later.position > e.position)
   AND NOT EXISTS (SELECT 1 FROM graphitron_path_element_routine other
                    WHERE other.graph_name = er.graph_name AND other.source_name = er.source_name
                      AND other.source_line = er.source_line
                      AND other.source_column = er.source_column
                      AND NOT (other.routine_source_name = er.routine_source_name
                               AND other.table_schema = er.table_schema
                               AND other.routine_name = er.routine_name))
   AND NOT EXISTS (SELECT 1 FROM graphql_root_operation ro
                    WHERE ro.graph_name = gf.graph_name AND ro.type_name = gf.type_name
                      AND ro.operation = 'MUTATION');
COMMENT ON VIEW graphitron_routine_result_rule IS 'One row the routine result rule computes, in the shape graphitron_routine_result stores: the rule itself, evaluated on demand rather than read off disk. For example a capture inserts this view''s rows for one graph into graphitron_routine_result, which is the name every reader spells; naming this relation instead asks for on-demand evaluation and gets it, which is a performance bug rather than a wrong answer.';
-- COMMENT ON COLUMN graphitron_routine_result_rule.graph_name IS 'the owning graph''s partition';
-- COMMENT ON COLUMN graphitron_routine_result_rule.type_name IS 'the type declaring the field';
-- COMMENT ON COLUMN graphitron_routine_result_rule.field_name IS 'the field whose path ends on the @routine';
-- COMMENT ON COLUMN graphitron_routine_result_rule.target_type_name IS 'the type the field returns';
-- COMMENT ON COLUMN graphitron_routine_result_rule.table_source_name IS 'the function''s catalog partition';
-- COMMENT ON COLUMN graphitron_routine_result_rule.table_schema IS 'the function''s SQL schema';
-- COMMENT ON COLUMN graphitron_routine_result_rule.table_name IS 'the function''s name';

CREATE TABLE graphitron_defect_type (
  code      VARCHAR NOT NULL,
  severity  VARCHAR NOT NULL,
  basis     VARCHAR NOT NULL,
  lsp_code  VARCHAR,
  statement VARCHAR NOT NULL,
  PRIMARY KEY (code),
  CHECK (severity IN ('error', 'warning')),
  CHECK (basis IN ('SPECIFICATION', 'GRAPHITRON', 'UNSUPPORTED'))
);
COMMENT ON TABLE graphitron_defect_type IS 'One rule a schema can break, declared once: what to call it, how bad it is, what the verdict rests on, and the sentence that states the rule. For example CONNECTION_RETURN is an error resting on graphitron''s directive contract, whose statement is that a @routine write re-reads by the keys it returned rather than by a page.';
COMMENT ON COLUMN graphitron_defect_type.code IS 'the defect''s name, and the whole key. Declared here rather than captured, so it carries no graph and no instant: the vocabulary is a property of this generator and not of anybody''s schema';
COMMENT ON COLUMN graphitron_defect_type.severity IS 'whether a build stops on it, stated once per defect rather than once per row. A function of the code and nothing else, which is why it lives beside the code and not on the findings';
COMMENT ON COLUMN graphitron_defect_type.basis IS 'what the verdict rests on, which is also what an author does about it: SPECIFICATION where the GraphQL specification forbids the schema, GRAPHITRON where graphitron''s directives give it no meaning and changing them removes the defect, UNSUPPORTED where it means something under both and graphitron does not do it yet, so an author works around it rather than fixing it. A function of the code exactly as the severity is; never the generator''s fault, the generator running only on a schema that validates';
COMMENT ON COLUMN graphitron_defect_type.lsp_code IS 'the diagnostic code an editor shows and filters by, null where none is published. The one part of a defect''s name a consumer reads as data rather than as prose, which is what keeps the code column load-bearing rather than a label';
COMMENT ON COLUMN graphitron_defect_type.statement IS 'the rule, as one author-facing sentence. The message a consumer renders quotes this and the finding''s detail; neither is stored per row';

CREATE TABLE federation_version (
  source_name VARCHAR   NOT NULL,
  version     VARCHAR   NOT NULL,
  touched_at  TIMESTAMP NOT NULL,
  PRIMARY KEY (source_name, version),
  FOREIGN KEY (source_name) REFERENCES store_source (source_name) ON DELETE CASCADE
);
COMMENT ON TABLE federation_version IS 'One federation specification version the federation library supports. For example v2.10, a link whose url ends in v2.10 being one the library on graphitron''s classpath accepts.';
COMMENT ON COLUMN federation_version.source_name IS 'the library, by its group and artifact, anchored by store_source, whose stamp is the content of the jar these rows were read from; the jar carries no Maven metadata naming its release, so a changed stamp is read whole';
COMMENT ON COLUMN federation_version.version IS 'the version as a link''s url spells it after the federation specification''s prefix, for example v2.10, which is how graphitron_ast_federation_link_entry spells the version a link names';
COMMENT ON COLUMN federation_version.touched_at IS 'the reading of the library that last wrote this row; a row the latest reading did not write is a version the library stopped supporting, and goes';

CREATE TABLE federation_written_version (
  source_name VARCHAR NOT NULL,
  version     VARCHAR NOT NULL,
  PRIMARY KEY (source_name),
  -- A version the library supports, so a generator naming one the library dropped fails at capture,
  -- saying so, rather than at the assembly.
  FOREIGN KEY (source_name, version) REFERENCES federation_version (source_name, version)
    ON DELETE CASCADE
);
COMMENT ON TABLE federation_written_version IS 'The federation version a link graphitron adds names, under the library it is read against. For example v2.10, which a graph federated only through a configured tag links to.';
COMMENT ON COLUMN federation_written_version.source_name IS 'the library, on federation_version''s terms; the whole key, graphitron writing one version';
COMMENT ON COLUMN federation_written_version.version IS 'the version, as FederationSpec.URL names it after the specification''s prefix';

CREATE TABLE federation_version_definition (
  source_name     VARCHAR NOT NULL,
  version         VARCHAR NOT NULL,
  name            VARCHAR NOT NULL,
  kind            VARCHAR NOT NULL,
  unimported_name VARCHAR NOT NULL,
  repeatable      BOOLEAN,
  description     VARCHAR,
  touched_at      TIMESTAMP NOT NULL,
  PRIMARY KEY (source_name, version, name),
  FOREIGN KEY (source_name, version) REFERENCES federation_version (source_name, version)
    ON DELETE CASCADE,
  CHECK (kind IN ('DIRECTIVE', 'SCALAR', 'ENUM')),
  -- A directive is spelled with its at sign, as an import list spells it, and only a directive
  -- repeats or not.
  CHECK ((kind = 'DIRECTIVE') = (name LIKE '@%')),
  CHECK ((kind = 'DIRECTIVE') = (unimported_name LIKE '@%')),
  CHECK ((kind = 'DIRECTIVE') = (repeatable IS NOT NULL))
);
COMMENT ON TABLE federation_version_definition IS 'One definition a federation version brings into a schema that links it. For example @key under v2.10, a repeatable directive a link importing it names key and one that does not names federation__key, and FieldSet, a scalar.';
COMMENT ON COLUMN federation_version_definition.source_name IS 'the library, on federation_version''s terms';
COMMENT ON COLUMN federation_version_definition.version IS 'the version, anchored by federation_version';
COMMENT ON COLUMN federation_version_definition.name IS 'the definition''s name in the specification, spelled as an import list spells it: a directive''s with its at sign, a type''s bare';
COMMENT ON COLUMN federation_version_definition.kind IS 'DIRECTIVE, SCALAR or ENUM, the kinds the specification defines; a definition of another kind refuses the capture rather than arriving unmodelled';
COMMENT ON COLUMN federation_version_definition.unimported_name IS 'the name the library gives the definition in a schema whose link does not import it, spelled as name is: the specification''s namespace prefixed, federation__key, or the name itself where the library always imports it, as @link';
COMMENT ON COLUMN federation_version_definition.repeatable IS 'whether the directive may be applied more than once at one site; NULL on a type';
COMMENT ON COLUMN federation_version_definition.description IS 'the definition''s description as the specification writes it, NULL where it writes none';
COMMENT ON COLUMN federation_version_definition.touched_at IS 'the reading of the library that last wrote this row; a row the latest reading did not write is a definition the version stopped bringing in, and goes';

CREATE TABLE federation_version_directive_argument (
  source_name       VARCHAR NOT NULL,
  version           VARCHAR NOT NULL,
  name              VARCHAR NOT NULL,
  argument_name     VARCHAR NOT NULL,
  ordinal           INT     NOT NULL,
  type_sdl          VARCHAR NOT NULL,
  named_type        VARCHAR NOT NULL,
  non_null          BOOLEAN NOT NULL,
  is_list           BOOLEAN NOT NULL,
  item_non_null     BOOLEAN,
  default_value_sdl VARCHAR,
  description       VARCHAR,
  touched_at        TIMESTAMP NOT NULL,
  PRIMARY KEY (source_name, version, name, argument_name),
  FOREIGN KEY (source_name, version, name)
    REFERENCES federation_version_definition (source_name, version, name) ON DELETE CASCADE
);
COMMENT ON TABLE federation_version_directive_argument IS 'One argument a federation version''s directive declares. For example fields: FieldSet! of @key under v2.10, its type named by the specification.';
COMMENT ON COLUMN federation_version_directive_argument.source_name IS 'the library, on federation_version''s terms';
COMMENT ON COLUMN federation_version_directive_argument.version IS 'the version';
COMMENT ON COLUMN federation_version_directive_argument.name IS 'the directive, with its at sign, anchored by federation_version_definition';
COMMENT ON COLUMN federation_version_directive_argument.argument_name IS 'the argument''s name';
COMMENT ON COLUMN federation_version_directive_argument.ordinal IS 'the argument''s position in the definition, from 0';
COMMENT ON COLUMN federation_version_directive_argument.type_sdl IS 'the argument''s type as the specification writes it, its named type under the specification''s name';
COMMENT ON COLUMN federation_version_directive_argument.named_type IS 'the type the argument''s wrapping bottoms out in, under the specification''s name, which a schema may see under another';
COMMENT ON COLUMN federation_version_directive_argument.non_null IS 'whether the outermost type is non-null';
COMMENT ON COLUMN federation_version_directive_argument.is_list IS 'whether the type, under its outermost non-null, is a list';
COMMENT ON COLUMN federation_version_directive_argument.item_non_null IS 'whether the innermost item of a list is non-null; NULL where the type is no list';
COMMENT ON COLUMN federation_version_directive_argument.default_value_sdl IS 'the default as the specification writes it, NULL where it declares none';
COMMENT ON COLUMN federation_version_directive_argument.description IS 'the argument''s description, NULL where the specification writes none';
COMMENT ON COLUMN federation_version_directive_argument.touched_at IS 'the reading of the library that last wrote this row, on federation_version_definition''s terms';

CREATE TABLE federation_version_import (
  source_name VARCHAR   NOT NULL,
  version     VARCHAR   NOT NULL,
  name        VARCHAR   NOT NULL,
  touched_at  TIMESTAMP NOT NULL,
  PRIMARY KEY (source_name, version, name),
  FOREIGN KEY (source_name, version, name)
    REFERENCES federation_version_definition (source_name, version, name) ON DELETE CASCADE
);
COMMENT ON TABLE federation_version_import IS 'One name a federation version''s link may import. For example @key and FieldSet under v2.10, and @context only from the version that introduced it.';
COMMENT ON COLUMN federation_version_import.source_name IS 'the library, on federation_version''s terms';
COMMENT ON COLUMN federation_version_import.version IS 'the version, anchored by federation_version';
COMMENT ON COLUMN federation_version_import.name IS 'the name as a link''s import list spells it, a directive''s with its at sign and a type''s bare, so the list as written joins it by equality. What the library accepts as an import at this version rather than what its definition file holds, the two differing where versions share a file and a directive is younger than the file''s first version';
COMMENT ON COLUMN federation_version_import.touched_at IS 'the reading of the library that last wrote this row; a row the latest reading did not write is a name the version stopped letting a link import, and goes';

CREATE TABLE graphitron_federation_link (
  graph_name    VARCHAR   NOT NULL,
  origin        VARCHAR   NOT NULL,
  version       VARCHAR   NOT NULL,
  source_name   VARCHAR,
  source_line   INT,
  source_column INT,
  touched_at    TIMESTAMP NOT NULL,
  -- A graph opts in to federation once, however it came to.
  PRIMARY KEY (graph_name),
  FOREIGN KEY (graph_name) REFERENCES store_graph (graph_name),
  -- The authored link, so the opt-in cannot outlive the application that states it.
  FOREIGN KEY (graph_name, source_name, source_line, source_column)
    REFERENCES graphitron_ast_federation_link_entry (graph_name, source_name, source_line, source_column)
    ON DELETE CASCADE,
  CHECK (origin IN ('AUTHORED', 'CONFIGURED')),
  -- An authored link is the application it names; a configured one names none. Both name a
  -- version, the configured one the generator's.
  CHECK ((origin = 'AUTHORED') = (source_name IS NOT NULL))
);
COMMENT ON TABLE graphitron_federation_link IS 'A graph opts in to Apollo Federation, and how: one row per federated graph. For example a schema extension applying @link with a federation url is one AUTHORED row naming that application, and a graph whose only opt-in is a <schemaInput tag> is one CONFIGURED row naming none.';
COMMENT ON COLUMN graphitron_federation_link.graph_name IS 'the owning graph''s partition and the whole key: a graph is federated or it is not';
COMMENT ON COLUMN graphitron_federation_link.origin IS 'AUTHORED where a document applies a federation @link, CONFIGURED where none does and a <schemaInput tag> asks for the @link that declares @tag';
COMMENT ON COLUMN graphitron_federation_link.version IS 'the federation version the link names: the authored link''s as written, and on a configured link the version the generator writes, which is what the link''s imports are read against';
COMMENT ON COLUMN graphitron_federation_link.source_name IS 'the file holding the authored application; NULL on a configured link, which no document states';
COMMENT ON COLUMN graphitron_federation_link.source_line IS 'source line of the authored application''s at sign';
COMMENT ON COLUMN graphitron_federation_link.source_column IS 'source column of the same';
COMMENT ON COLUMN graphitron_federation_link.touched_at IS 'the reading that last wrote this row; a row this reading did not write is an opt-in the corpus or the configuration dropped, and goes';

CREATE TABLE graphitron_federation_link_import (
  graph_name VARCHAR   NOT NULL,
  ordinal    INT       NOT NULL,
  name       VARCHAR   NOT NULL,
  alias      VARCHAR,
  touched_at TIMESTAMP NOT NULL,
  PRIMARY KEY (graph_name, ordinal),
  FOREIGN KEY (graph_name) REFERENCES graphitron_federation_link (graph_name) ON DELETE CASCADE
);
COMMENT ON TABLE graphitron_federation_link_import IS 'One name a graph''s federation link imports, in the order it is written: one row per import. For example import: ["@key", {name: "@shareable", as: "@federatedShareable"}] gives two rows, and a third importing @tag where a tag is configured.';
COMMENT ON COLUMN graphitron_federation_link_import.graph_name IS 'the federated graph, anchored by graphitron_federation_link';
COMMENT ON COLUMN graphitron_federation_link_import.ordinal IS 'the import''s index in the list as written, from 0, and after it what graphitron adds';
COMMENT ON COLUMN graphitron_federation_link_import.name IS 'the name imported, a directive''s with its at sign';
COMMENT ON COLUMN graphitron_federation_link_import.alias IS 'the local name an authored import binds it to, NULL where it keeps its own';
COMMENT ON COLUMN graphitron_federation_link_import.touched_at IS 'the reading that last wrote this row, on graphitron_federation_link''s terms';

CREATE VIEW graphitron_federation_link_rule
  (graph_name, origin, version, source_name, source_line, source_column) AS
WITH authored (graph_name, version, source_name, source_line, source_column, rank) AS (
  SELECT graph_name, version, source_name, source_line, source_column,
         ROW_NUMBER() OVER (PARTITION BY graph_name
                            ORDER BY source_name, source_line, source_column)
    FROM graphitron_ast_federation_link_entry)
SELECT graph_name, 'AUTHORED', version, source_name, source_line, source_column
  FROM authored
 WHERE rank = 1
UNION ALL
-- The configured link names the version graphitron writes, as the federation gatherer recorded it
-- under the library the graph claims.
SELECT g.graph_name, 'CONFIGURED',
       (SELECT w.version FROM federation_written_version w
          JOIN store_graph_source m ON m.source_name = w.source_name
         WHERE m.graph_name = g.graph_name),
       CAST(NULL AS VARCHAR), CAST(NULL AS INT), CAST(NULL AS INT)
  FROM (SELECT DISTINCT graph_name FROM store_graph_source_input WHERE tag IS NOT NULL) g
 WHERE NOT EXISTS (SELECT 1 FROM authored a WHERE a.graph_name = g.graph_name);
COMMENT ON VIEW graphitron_federation_link_rule IS 'The rule graphitron_federation_link stores: one row per graph that opts in to federation, the way it opts in. For example the graphitron anchor inserts this view''s rows for one graph into graphitron_federation_link, which is the name every reader spells.';
-- COMMENT ON COLUMN graphitron_federation_link_rule.graph_name IS 'the graph opting in';
-- COMMENT ON COLUMN graphitron_federation_link_rule.origin IS 'AUTHORED or CONFIGURED, on graphitron_federation_link''s terms';
-- COMMENT ON COLUMN graphitron_federation_link_rule.version IS 'the authored version, or the generator''s on a configured link';
-- COMMENT ON COLUMN graphitron_federation_link_rule.source_name IS 'the authored application''s file, NULL on a configured link';
-- COMMENT ON COLUMN graphitron_federation_link_rule.source_line IS 'the authored application''s line';
-- COMMENT ON COLUMN graphitron_federation_link_rule.source_column IS 'the authored application''s column';

CREATE VIEW graphitron_federation_link_import_rule (graph_name, ordinal, name, alias) AS
WITH authored (graph_name, ordinal, name, alias) AS (
SELECT l.graph_name, v.position, i.name, i.alias
  FROM graphitron_federation_link l
  JOIN graphql_ast_applied_argument_entry a
    ON a.graph_name = l.graph_name AND a.source_name = l.source_name
   AND a.parent_line = l.source_line AND a.parent_column = l.source_column
   AND a.name = 'import'
  JOIN graphql_ast_value_entry v
    ON v.graph_name = a.graph_name AND v.source_name = a.source_name
   AND v.holder_line = a.source_line AND v.holder_column = a.source_column
  JOIN graphitron_ast_link_import_entry i
    ON i.graph_name = v.graph_name AND i.source_name = v.source_name
   AND i.source_line = v.source_line AND i.source_column = v.source_column
 WHERE l.origin = 'AUTHORED'),
-- What graphitron applies itself, the mint and the configuration, that the link's version lets it
-- import and the link does not import already. The library is the one the graph claims.
-- Driven from the version's imports, a few dozen, each probing the applications.
added (graph_name, name) AS (
  SELECT DISTINCT l.graph_name, f.name
    FROM graphitron_federation_link l
    JOIN store_graph_source m ON m.graph_name = l.graph_name
    JOIN federation_version_import f
      ON f.source_name = m.source_name AND f.version = l.version
   WHERE EXISTS (SELECT 1 FROM graphitron_directive_application a
                  WHERE a.graph_name = l.graph_name AND '@' || a.directive_name = f.name
                    AND a.origin IN ('MINTED', 'CONFIGURED'))
     AND NOT EXISTS (SELECT 1 FROM authored w
                      WHERE w.graph_name = l.graph_name AND w.name = f.name))
SELECT graph_name, ordinal, name, alias FROM authored
UNION ALL
-- After every authored import, in name order.
SELECT d.graph_name,
       CAST(COALESCE((SELECT MAX(w.ordinal) + 1 FROM authored w WHERE w.graph_name = d.graph_name), 0)
            + ROW_NUMBER() OVER (PARTITION BY d.graph_name ORDER BY d.name) - 1 AS INT),
       d.name, CAST(NULL AS VARCHAR)
  FROM added d;
COMMENT ON VIEW graphitron_federation_link_import_rule IS 'The rule graphitron_federation_link_import stores: one row per name a graph''s federation link imports. For example an authored link''s imports come across in the order written, and after them each directive graphitron applies that the link''s version lets it import.';
-- COMMENT ON COLUMN graphitron_federation_link_import_rule.graph_name IS 'the federated graph';
-- COMMENT ON COLUMN graphitron_federation_link_import_rule.ordinal IS 'the import''s index in the written list, and after it the added ones in name order';
-- COMMENT ON COLUMN graphitron_federation_link_import_rule.name IS 'the name imported';
-- COMMENT ON COLUMN graphitron_federation_link_import_rule.alias IS 'the authored alias, or NULL, an added import keeping its own name';

CREATE TABLE graphitron_federation_definition (
  graph_name  VARCHAR   NOT NULL,
  name        VARCHAR   NOT NULL,
  local_name  VARCHAR   NOT NULL,
  kind        VARCHAR   NOT NULL,
  source_name VARCHAR   NOT NULL,
  version     VARCHAR   NOT NULL,
  touched_at  TIMESTAMP NOT NULL,
  PRIMARY KEY (graph_name, name),
  -- Two definitions under one local name would be two answers to what that name means.
  UNIQUE (graph_name, local_name),
  FOREIGN KEY (graph_name) REFERENCES graphitron_federation_link (graph_name) ON DELETE CASCADE,
  FOREIGN KEY (source_name, version, name)
    REFERENCES federation_version_definition (source_name, version, name) ON DELETE CASCADE
);
COMMENT ON TABLE graphitron_federation_definition IS 'One federation definition a graph''s link brings in, under the name the graph sees it by. For example @key as @key where the link imports it, as @federation__key where it does not, and FieldSet as federation__FieldSet unless imported.';
COMMENT ON COLUMN graphitron_federation_definition.graph_name IS 'the federated graph, anchored by graphitron_federation_link';
COMMENT ON COLUMN graphitron_federation_definition.name IS 'the definition''s name in the specification, as federation_version_definition spells it';
COMMENT ON COLUMN graphitron_federation_definition.local_name IS 'the name the graph sees it by, spelled as name is: the alias an import binds, the name itself where the link imports it, and otherwise the name the library gives an unimported definition';
COMMENT ON COLUMN graphitron_federation_definition.kind IS 'DIRECTIVE, SCALAR or ENUM, on federation_version_definition''s terms';
COMMENT ON COLUMN graphitron_federation_definition.source_name IS 'the library the graph claims, which with the version names the definition read';
COMMENT ON COLUMN graphitron_federation_definition.version IS 'the version the graph''s link names';
COMMENT ON COLUMN graphitron_federation_definition.touched_at IS 'the reading that last wrote this row; a row this reading did not write is one the link stopped bringing in, and goes';

CREATE VIEW graphitron_federation_definition_rule
  (graph_name, name, local_name, kind, source_name, version) AS
SELECT l.graph_name, d.name,
       CASE WHEN EXISTS (SELECT 1 FROM graphitron_federation_link_import i
                          WHERE i.graph_name = l.graph_name AND i.name = d.name)
            THEN COALESCE((SELECT i.alias FROM graphitron_federation_link_import i
                            WHERE i.graph_name = l.graph_name AND i.name = d.name
                            ORDER BY i.ordinal FETCH FIRST 1 ROW ONLY), d.name)
            ELSE d.unimported_name END,
       d.kind, d.source_name, d.version
  FROM graphitron_federation_link l
  JOIN store_graph_source m ON m.graph_name = l.graph_name
  JOIN federation_version_definition d ON d.source_name = m.source_name AND d.version = l.version;
COMMENT ON VIEW graphitron_federation_definition_rule IS 'The rule graphitron_federation_definition stores: one row per federation definition a graph''s link brings in. For example every definition of the version the link names, under the name its imports give it.';
-- COMMENT ON COLUMN graphitron_federation_definition_rule.graph_name IS 'the federated graph';
-- COMMENT ON COLUMN graphitron_federation_definition_rule.name IS 'the specification''s name';
-- COMMENT ON COLUMN graphitron_federation_definition_rule.local_name IS 'the name the graph sees';
-- COMMENT ON COLUMN graphitron_federation_definition_rule.kind IS 'the definition''s kind';
-- COMMENT ON COLUMN graphitron_federation_definition_rule.source_name IS 'the library the graph claims';
-- COMMENT ON COLUMN graphitron_federation_definition_rule.version IS 'the version the link names';

CREATE TABLE graphitron_directive (
  graph_name     VARCHAR   NOT NULL,
  directive_name VARCHAR   NOT NULL,
  origin         VARCHAR   NOT NULL,
  repeatable     BOOLEAN   NOT NULL,
  description    VARCHAR,
  touched_at     TIMESTAMP NOT NULL,
  PRIMARY KEY (graph_name, directive_name),
  FOREIGN KEY (graph_name) REFERENCES store_graph (graph_name),
  CHECK (origin IN ('AUTHORED', 'FEDERATION'))
);
COMMENT ON TABLE graphitron_directive IS 'A directive the graph''s schema declares, written or brought in by its federation link. For example a graph linking federation and importing @key holds key here as FEDERATION beside every directive its documents define, and federation__shareable where the link leaves @shareable out.';
COMMENT ON COLUMN graphitron_directive.graph_name IS 'the owning graph''s partition';
COMMENT ON COLUMN graphitron_directive.directive_name IS 'the directive''s name in the graph, without its at sign, on graphql_directive''s terms';
COMMENT ON COLUMN graphitron_directive.origin IS 'AUTHORED where a document defines it, the bundled vocabulary and the specification''s own included, FEDERATION where the link brings it in. A name both claim is the document''s, the composition refusing the collision';
COMMENT ON COLUMN graphitron_directive.repeatable IS 'whether it may be applied more than once at one site';
COMMENT ON COLUMN graphitron_directive.description IS 'its description, NULL where none is written';
COMMENT ON COLUMN graphitron_directive.touched_at IS 'the reading that last wrote this row; a row this reading did not write is a directive the graph stopped declaring, and goes';

CREATE VIEW graphitron_directive_rule (graph_name, directive_name, origin, repeatable, description) AS
SELECT graph_name, directive_name, 'AUTHORED', repeatable, description
  FROM graphql_directive
UNION ALL
SELECT f.graph_name, SUBSTRING(f.local_name FROM 2), 'FEDERATION', d.repeatable, d.description
  FROM graphitron_federation_definition f
  JOIN federation_version_definition d
    ON d.source_name = f.source_name AND d.version = f.version AND d.name = f.name
 WHERE f.kind = 'DIRECTIVE'
   AND NOT EXISTS (SELECT 1 FROM graphql_directive g
                    WHERE g.graph_name = f.graph_name
                      AND g.directive_name = SUBSTRING(f.local_name FROM 2));
COMMENT ON VIEW graphitron_directive_rule IS 'The rule graphitron_directive stores: one row per directive a graph declares. For example what its documents define, and the federation directives its link brings in under the names it brings them in by.';
-- COMMENT ON COLUMN graphitron_directive_rule.graph_name IS 'the owning graph';
-- COMMENT ON COLUMN graphitron_directive_rule.directive_name IS 'the directive''s name, without its at sign';
-- COMMENT ON COLUMN graphitron_directive_rule.origin IS 'AUTHORED or FEDERATION';
-- COMMENT ON COLUMN graphitron_directive_rule.repeatable IS 'whether it repeats';
-- COMMENT ON COLUMN graphitron_directive_rule.description IS 'its description';

CREATE TABLE graphitron_directive_argument (
  graph_name        VARCHAR   NOT NULL,
  directive_name    VARCHAR   NOT NULL,
  argument_name     VARCHAR   NOT NULL,
  ordinal           INT       NOT NULL,
  type_sdl          VARCHAR   NOT NULL,
  named_type        VARCHAR   NOT NULL,
  non_null          BOOLEAN   NOT NULL,
  is_list           BOOLEAN   NOT NULL,
  item_non_null     BOOLEAN,
  default_value_sdl VARCHAR,
  description       VARCHAR,
  touched_at        TIMESTAMP NOT NULL,
  PRIMARY KEY (graph_name, directive_name, argument_name),
  FOREIGN KEY (graph_name, directive_name)
    REFERENCES graphitron_directive (graph_name, directive_name) ON DELETE CASCADE
);
COMMENT ON TABLE graphitron_directive_argument IS 'One argument a directive the graph declares takes. For example fields: federation__FieldSet! of @key in a graph whose link imports @key and not FieldSet, its type under the name the graph sees.';
COMMENT ON COLUMN graphitron_directive_argument.graph_name IS 'the owning graph''s partition';
COMMENT ON COLUMN graphitron_directive_argument.directive_name IS 'the directive, anchored by graphitron_directive';
COMMENT ON COLUMN graphitron_directive_argument.argument_name IS 'the argument''s name';
COMMENT ON COLUMN graphitron_directive_argument.ordinal IS 'its position in the definition, from 0';
COMMENT ON COLUMN graphitron_directive_argument.type_sdl IS 'its type, the named type spelled as the graph sees it';
COMMENT ON COLUMN graphitron_directive_argument.named_type IS 'the type its wrapping bottoms out in, as the graph names it';
COMMENT ON COLUMN graphitron_directive_argument.non_null IS 'whether the outermost type is non-null';
COMMENT ON COLUMN graphitron_directive_argument.is_list IS 'whether the type is a list';
COMMENT ON COLUMN graphitron_directive_argument.item_non_null IS 'whether a list''s innermost item is non-null; NULL where the type is no list';
COMMENT ON COLUMN graphitron_directive_argument.default_value_sdl IS 'its default as written, NULL where none is declared';
COMMENT ON COLUMN graphitron_directive_argument.description IS 'its description, NULL where none is written';
COMMENT ON COLUMN graphitron_directive_argument.touched_at IS 'the reading that last wrote this row, on graphitron_directive''s terms';

CREATE VIEW graphitron_directive_argument_rule
  (graph_name, directive_name, argument_name, ordinal, type_sdl, named_type, non_null, is_list,
   item_non_null, default_value_sdl, description) AS
SELECT a.graph_name, a.directive_name, a.argument_name, a.ordinal, a.type_sdl, a.named_type,
       a.non_null, a.is_list, a.item_non_null, a.default_value_sdl, a.description
  FROM graphql_directive_argument a
UNION ALL
-- A federation argument's type is the specification's name, which the graph may see under another.
SELECT f.graph_name, SUBSTRING(f.local_name FROM 2), a.argument_name, a.ordinal,
       REPLACE(a.type_sdl, a.named_type, COALESCE(t.local_name, a.named_type)),
       COALESCE(t.local_name, a.named_type),
       a.non_null, a.is_list, a.item_non_null, a.default_value_sdl, a.description
  FROM graphitron_federation_definition f
  JOIN federation_version_directive_argument a
    ON a.source_name = f.source_name AND a.version = f.version AND a.name = f.name
  LEFT JOIN graphitron_federation_definition t
    ON t.graph_name = f.graph_name AND t.name = a.named_type AND t.kind <> 'DIRECTIVE'
 WHERE f.kind = 'DIRECTIVE'
   AND NOT EXISTS (SELECT 1 FROM graphql_directive g
                    WHERE g.graph_name = f.graph_name
                      AND g.directive_name = SUBSTRING(f.local_name FROM 2));
COMMENT ON VIEW graphitron_directive_argument_rule IS 'The rule graphitron_directive_argument stores: one row per argument of a directive a graph declares. For example the arguments its documents write, and those of the federation directives its link brings in.';
-- COMMENT ON COLUMN graphitron_directive_argument_rule.graph_name IS 'the owning graph';
-- COMMENT ON COLUMN graphitron_directive_argument_rule.directive_name IS 'the directive';
-- COMMENT ON COLUMN graphitron_directive_argument_rule.argument_name IS 'the argument';
-- COMMENT ON COLUMN graphitron_directive_argument_rule.ordinal IS 'its position';
-- COMMENT ON COLUMN graphitron_directive_argument_rule.type_sdl IS 'its type as the graph names it';
-- COMMENT ON COLUMN graphitron_directive_argument_rule.named_type IS 'its named type as the graph names it';
-- COMMENT ON COLUMN graphitron_directive_argument_rule.non_null IS 'whether non-null';
-- COMMENT ON COLUMN graphitron_directive_argument_rule.is_list IS 'whether a list';
-- COMMENT ON COLUMN graphitron_directive_argument_rule.item_non_null IS 'whether a list''s item is non-null';
-- COMMENT ON COLUMN graphitron_directive_argument_rule.default_value_sdl IS 'its default';
-- COMMENT ON COLUMN graphitron_directive_argument_rule.description IS 'its description';

CREATE VIEW graphitron_type_federation (graph_name, type_name, coordinate, kind, description) AS
SELECT f.graph_name, f.local_name, f.local_name, f.kind, d.description
  FROM graphitron_federation_definition f
  JOIN federation_version_definition d
    ON d.source_name = f.source_name AND d.version = f.version AND d.name = f.name
 WHERE f.kind <> 'DIRECTIVE';
COMMENT ON VIEW graphitron_type_federation IS 'One of the sets graphitron_type is the union of: a type a graph''s federation link brings in. For example federation__FieldSet, the scalar @key''s fields: argument takes, in a graph whose link does not import FieldSet.';
-- COMMENT ON COLUMN graphitron_type_federation.graph_name IS 'the federated graph';
-- COMMENT ON COLUMN graphitron_type_federation.type_name IS 'the type as the graph names it';
-- COMMENT ON COLUMN graphitron_type_federation.coordinate IS 'its coordinate, which for a named type is its name';
-- COMMENT ON COLUMN graphitron_type_federation.kind IS 'SCALAR or ENUM';
-- COMMENT ON COLUMN graphitron_type_federation.description IS 'its description as the specification writes it';

CREATE VIEW graphitron_synthesized_node_type_id
  (graph_name, type_name, type_id) AS
SELECT n.graph_name, n.type_name, n.type_id
  FROM graphitron_node n
 WHERE n.resolvable
   AND EXISTS (SELECT 1 FROM graphitron_ast_compose_directive_entry c
                WHERE c.graph_name = n.graph_name
                  AND c.directive_name = '@nodeType');
COMMENT ON VIEW graphitron_synthesized_node_type_id IS 'Which node types publish their wire type id in the emitted schema as @nodeType, because the graph composes that directive. For example a graph whose schema applies @composeDirective(name: "@nodeType") gets one row per node type, Film''s carrying the id its @node declares, its class publishes, or its own name. A stub, @node(resolvable: false), gets none: the subgraph owning the entity publishes its id.';
-- COMMENT ON COLUMN graphitron_synthesized_node_type_id.graph_name IS 'the owning graph''s partition, carried from the node relation';
-- COMMENT ON COLUMN graphitron_synthesized_node_type_id.type_name IS 'the node type the application is synthesized for; keyed with the graph, one row per node type that gets one';
-- COMMENT ON COLUMN graphitron_synthesized_node_type_id.type_id IS 'the wire type id the application carries, as graphitron_node resolved it: what the author declared, else what the backing class publishes, else the type''s own name. Never null, graphitron_node''s last tier always answering';

CREATE VIEW graphitron_directive_application_authored
  (graph_name, coordinate, directive_name, ordinal, origin,
   source_name, source_line, source_column) AS
SELECT d.graph_name, d.coordinate, d.directive_name, d.ordinal, 'AUTHORED',
       d.source_name, d.source_line, d.source_column
  FROM graphql_directive_application d
  JOIN graphitron_element e ON e.graph_name = d.graph_name AND e.coordinate = d.coordinate;
COMMENT ON VIEW graphitron_directive_application_authored IS 'One of the three sets graphitron_directive_application is the union of: an application an author wrote at a coordinate the emitted population holds, carried across whole. For example the @table on type Film @table(name: "film") is a row at Film here, with the position the author wrote it at.';
-- COMMENT ON COLUMN graphitron_directive_application_authored.graph_name IS 'the owning graph''s partition';
-- COMMENT ON COLUMN graphitron_directive_application_authored.coordinate IS 'the coordinate the application sits on';
-- COMMENT ON COLUMN graphitron_directive_application_authored.directive_name IS 'the applied directive''s name';
-- COMMENT ON COLUMN graphitron_directive_application_authored.ordinal IS 'the repeat, as graphql_directive_application numbers it';
-- COMMENT ON COLUMN graphitron_directive_application_authored.origin IS 'always AUTHORED';
-- COMMENT ON COLUMN graphitron_directive_application_authored.source_name IS 'the file the application was written in';
-- COMMENT ON COLUMN graphitron_directive_application_authored.source_line IS 'source line of the at sign';
-- COMMENT ON COLUMN graphitron_directive_application_authored.source_column IS 'source column of the at sign';

CREATE VIEW graphitron_configured_tag_rule (graph_name, coordinate, ordinal, value_sdl) AS
WITH applied (graph_name, coordinate, site_order, tag) AS (
  -- A field or an input field, declared at one site, takes the tag of its file unless it carries one.
  SELECT f.graph_name, f.type_name || '.' || f.field_name, 0, s.tag
    FROM graphql_field f
    JOIN store_graph_source_input s ON s.graph_name = f.graph_name AND s.source_name = f.source_name
   WHERE s.tag IS NOT NULL
     AND NOT EXISTS (SELECT 1 FROM graphql_directive_application d
                      WHERE d.graph_name = f.graph_name
                        AND d.coordinate = f.type_name || '.' || f.field_name
                        AND d.directive_name = 'tag')
  UNION ALL
  SELECT a.graph_name, a.type_name || '.' || a.field_name || '(' || a.argument_name || ':)', 0, s.tag
    FROM graphql_argument a
    JOIN store_graph_source_input s ON s.graph_name = a.graph_name AND s.source_name = a.source_name
   WHERE s.tag IS NOT NULL
     AND NOT EXISTS (SELECT 1 FROM graphql_directive_application d
                      WHERE d.graph_name = a.graph_name
                        AND d.coordinate = a.type_name || '.' || a.field_name
                                           || '(' || a.argument_name || ':)'
                        AND d.directive_name = 'tag')
  UNION ALL
  SELECT v.graph_name, v.type_name || '.' || v.value_name, 0, s.tag
    FROM graphql_enum_value v
    JOIN store_graph_source_input s ON s.graph_name = v.graph_name AND s.source_name = v.source_name
   WHERE s.tag IS NOT NULL
     AND NOT EXISTS (SELECT 1 FROM graphql_directive_application d
                      WHERE d.graph_name = v.graph_name
                        AND d.coordinate = v.type_name || '.' || v.value_name
                        AND d.directive_name = 'tag')
  UNION ALL
  -- A union is tagged per declaration site, each site taking the tag of its own file unless the site
  -- carries one, so a union declared in two tagged files carries both.
  SELECT t.graph_name, t.type_name, t.merge_ordinal, s.tag
    FROM graphql_type_declaration t
    JOIN store_graph_source_input s ON s.graph_name = t.graph_name AND s.source_name = t.source_name
   WHERE t.kind = 'UNION' AND s.tag IS NOT NULL
     AND NOT EXISTS (SELECT 1 FROM graphql_ast_entry e
                       JOIN graphql_ast_directive_application_entry a
                         ON a.graph_name = e.graph_name AND a.source_name = e.source_name
                        AND a.source_line = e.source_line AND a.source_column = e.source_column
                      WHERE e.graph_name = t.graph_name AND e.source_name = t.source_name
                        AND e.parent_line = t.source_line AND e.parent_column = t.source_column
                        AND a.name = 'tag'))
SELECT p.graph_name, p.coordinate,
       CAST((SELECT COUNT(*) FROM graphql_directive_application d
              WHERE d.graph_name = p.graph_name AND d.coordinate = p.coordinate
                AND d.directive_name = 'tag') AS INT)
         + CAST(ROW_NUMBER() OVER (PARTITION BY p.graph_name, p.coordinate
                                   ORDER BY p.site_order) AS INT) - 1,
       '"' || p.tag || '"'
  FROM applied p
  JOIN graphitron_element e ON e.graph_name = p.graph_name AND e.coordinate = p.coordinate;
COMMENT ON VIEW graphitron_configured_tag_rule IS 'One row the configured-tag rule computes, in the shape graphitron_configured_tag stores: the rule itself, evaluated on demand rather than read off disk. For example a capture inserts this view''s rows for one graph into graphitron_configured_tag, which is the name every reader spells; naming this relation instead asks for on-demand evaluation and gets it.';
-- COMMENT ON COLUMN graphitron_configured_tag_rule.graph_name IS 'the owning graph''s partition';
-- COMMENT ON COLUMN graphitron_configured_tag_rule.coordinate IS 'the element the tag is applied to: a field, an input field, an argument, an enum value, or a union';
-- COMMENT ON COLUMN graphitron_configured_tag_rule.ordinal IS 'after every authored @tag at the coordinate, in declaration-site order where a union takes several';
-- COMMENT ON COLUMN graphitron_configured_tag_rule.value_sdl IS 'the tag as the name: argument an author would have written';
CREATE TABLE graphitron_configured_tag (
  graph_name     VARCHAR NOT NULL,
  coordinate     VARCHAR NOT NULL,
  ordinal        INT NOT NULL,
  value_sdl      VARCHAR NOT NULL,
  touched_at     TIMESTAMP NOT NULL,
  PRIMARY KEY (graph_name, coordinate, ordinal),
  FOREIGN KEY (graph_name) REFERENCES store_graph (graph_name)
);
COMMENT ON TABLE graphitron_configured_tag IS 'The rule <schemaInput tag> states, as a relation: one row per @tag the configuration applies to an element of the emitted population. For example a field declared in a file whose entry carries tag stable, and which carries no @tag of its own, is one row naming stable.';
COMMENT ON COLUMN graphitron_configured_tag.graph_name IS 'the owning graph''s partition';
COMMENT ON COLUMN graphitron_configured_tag.coordinate IS 'the element the tag is applied to: a field, an input field, an argument, an enum value, or a union';
COMMENT ON COLUMN graphitron_configured_tag.ordinal IS 'after every authored @tag at the coordinate, in declaration-site order where a union takes several';
COMMENT ON COLUMN graphitron_configured_tag.value_sdl IS 'the tag as the name: argument an author would have written';
COMMENT ON COLUMN graphitron_configured_tag.touched_at IS 'when the reading that last found this tag ran: the mark the sweep reads, so a tag still applied survives a reading and one no longer applied goes';

CREATE VIEW graphitron_directive_application_configured
  (graph_name, coordinate, directive_name, ordinal, origin,
   source_name, source_line, source_column) AS
SELECT c.graph_name, c.coordinate, 'tag', c.ordinal, 'CONFIGURED',
       CAST(NULL AS VARCHAR), CAST(NULL AS INT), CAST(NULL AS INT)
  FROM graphitron_configured_tag c;
COMMENT ON VIEW graphitron_directive_application_configured IS 'One of the three sets graphitron_directive_application is the union of: an application the configuration adds to what a document declares. For example the @tag(name: "stable") a field takes from the entry its file was matched by.';
-- COMMENT ON COLUMN graphitron_directive_application_configured.graph_name IS 'the owning graph''s partition';
-- COMMENT ON COLUMN graphitron_directive_application_configured.coordinate IS 'the element the configuration applies the directive to';
-- COMMENT ON COLUMN graphitron_directive_application_configured.directive_name IS 'the directive the configuration applies';
-- COMMENT ON COLUMN graphitron_directive_application_configured.ordinal IS 'after every authored application of the same directive at the same coordinate';
-- COMMENT ON COLUMN graphitron_directive_application_configured.origin IS 'always CONFIGURED';
-- COMMENT ON COLUMN graphitron_directive_application_configured.source_name IS 'always NULL, a configured application having no position';
-- COMMENT ON COLUMN graphitron_directive_application_configured.source_line IS 'always NULL';
-- COMMENT ON COLUMN graphitron_directive_application_configured.source_column IS 'always NULL';

CREATE VIEW graphitron_carrier_directive_rule
  (graph_name, type_name, coordinate, directive_name, ordinal, value_sdl) AS
WITH carried (graph_name, coordinate, directive_name, ordinal, value_sdl) AS (
  SELECT d.graph_name, d.coordinate, d.directive_name, d.ordinal, a.value_sdl
    FROM graphql_directive_application d
    LEFT JOIN graphql_directive_application_arg a
      ON a.graph_name = d.graph_name AND a.coordinate = d.coordinate
     AND a.directive_name = d.directive_name AND a.ordinal = d.ordinal
     AND a.directive_argument_name = 'name'
   WHERE d.directive_name IN ('tag', 'shareable')
  UNION ALL
  SELECT c.graph_name, c.coordinate, 'tag', c.ordinal, c.value_sdl
    FROM graphitron_configured_tag c)
SELECT m.graph_name, m.type_name, m.coordinate, c.directive_name, c.ordinal, c.value_sdl
  FROM graphitron_minted_coinage m
  JOIN graphitron_type_minted t ON t.graph_name = m.graph_name AND t.type_name = m.type_name
  JOIN carried c ON c.graph_name = m.graph_name AND c.coordinate = m.coordinate;
COMMENT ON VIEW graphitron_carrier_directive_rule IS 'One row the carrier-directive rule computes, in the shape graphitron_carrier_directive stores: the rule itself, evaluated on demand rather than read off disk. For example a capture inserts this view''s rows for one graph into graphitron_carrier_directive, which is the name every reader spells; naming this relation instead asks for on-demand evaluation and gets it.';
-- COMMENT ON COLUMN graphitron_carrier_directive_rule.graph_name IS 'the owning graph''s partition';
-- COMMENT ON COLUMN graphitron_carrier_directive_rule.type_name IS 'the minted type the carrier coined; only a type the mint did not stand down for, an author''s declaration inheriting nothing';
-- COMMENT ON COLUMN graphitron_carrier_directive_rule.coordinate IS 'the carrier field';
-- COMMENT ON COLUMN graphitron_carrier_directive_rule.directive_name IS 'tag or shareable';
-- COMMENT ON COLUMN graphitron_carrier_directive_rule.ordinal IS 'the application''s order on the carrier';
-- COMMENT ON COLUMN graphitron_carrier_directive_rule.value_sdl IS 'the tag''s name: argument as SDL; NULL on @shareable, which takes none';
CREATE TABLE graphitron_carrier_directive (
  graph_name     VARCHAR NOT NULL,
  type_name      VARCHAR NOT NULL,
  coordinate     VARCHAR NOT NULL,
  directive_name VARCHAR NOT NULL,
  ordinal        INT NOT NULL,
  value_sdl      VARCHAR,
  touched_at     TIMESTAMP NOT NULL,
  PRIMARY KEY (graph_name, type_name, coordinate, directive_name, ordinal),
  FOREIGN KEY (graph_name) REFERENCES store_graph (graph_name)
);
COMMENT ON TABLE graphitron_carrier_directive IS 'The federation directives on the fields that coined a minted type: one row per @tag or @shareable a carrier carries, authored or configured. For example films: [Film!]! @asConnection @tag(name: "public") gives QueryFilmsConnection a row naming the public tag on Query.films.';
COMMENT ON COLUMN graphitron_carrier_directive.graph_name IS 'the owning graph''s partition';
COMMENT ON COLUMN graphitron_carrier_directive.type_name IS 'the minted type the carrier coined; only a type the mint did not stand down for, an author''s declaration inheriting nothing';
COMMENT ON COLUMN graphitron_carrier_directive.coordinate IS 'the carrier field';
COMMENT ON COLUMN graphitron_carrier_directive.directive_name IS 'tag or shareable';
COMMENT ON COLUMN graphitron_carrier_directive.ordinal IS 'the application''s order on the carrier';
COMMENT ON COLUMN graphitron_carrier_directive.value_sdl IS 'the tag''s name: argument as SDL; NULL on @shareable, which takes none';
COMMENT ON COLUMN graphitron_carrier_directive.touched_at IS 'when the reading that last found this directive on this carrier ran: the mark the sweep reads, so one still carried survives a reading and one no longer carried goes';

CREATE VIEW graphitron_inherited_directive
  (graph_name, type_name, directive_name, ordinal, value_sdl) AS
WITH carriers (graph_name, type_name, carrier_count, first_carrier) AS (
  SELECT graph_name, type_name, COUNT(DISTINCT coordinate), MIN(coordinate)
    FROM graphitron_minted_coinage
   GROUP BY graph_name, type_name),
kept (graph_name, type_name, value_sdl) AS (
  SELECT d.graph_name, d.type_name, d.value_sdl
    FROM graphitron_carrier_directive d
    JOIN carriers c ON c.graph_name = d.graph_name AND c.type_name = d.type_name
   WHERE d.directive_name = 'tag' AND d.value_sdl IS NOT NULL
   GROUP BY d.graph_name, d.type_name, d.value_sdl, c.carrier_count
  HAVING COUNT(DISTINCT d.coordinate) = c.carrier_count)
-- A tag every carrier carries, in the first carrier's order.
SELECT k.graph_name, k.type_name, 'tag',
       CAST(ROW_NUMBER() OVER (PARTITION BY k.graph_name, k.type_name
                               ORDER BY MIN(f.ordinal)) AS INT) - 1,
       k.value_sdl
  FROM kept k
  JOIN carriers c ON c.graph_name = k.graph_name AND c.type_name = k.type_name
  JOIN graphitron_carrier_directive f
    ON f.graph_name = k.graph_name AND f.type_name = k.type_name
   AND f.coordinate = c.first_carrier AND f.directive_name = 'tag' AND f.value_sdl = k.value_sdl
 GROUP BY k.graph_name, k.type_name, k.value_sdl
UNION ALL
-- @shareable where any carrier is.
SELECT DISTINCT d.graph_name, d.type_name, 'shareable', 0, CAST(NULL AS VARCHAR)
  FROM graphitron_carrier_directive d
 WHERE d.directive_name = 'shareable';
COMMENT ON VIEW graphitron_inherited_directive IS 'The federation directives a minted type inherits from its carriers: the tags every carrier carries and @shareable when any carrier is. For example a PageInfo two carriers share carries only the tag both carry, and is shareable because one of them is.';
-- COMMENT ON COLUMN graphitron_inherited_directive.graph_name IS 'the owning graph''s partition';
-- COMMENT ON COLUMN graphitron_inherited_directive.type_name IS 'the minted type that inherits';
-- COMMENT ON COLUMN graphitron_inherited_directive.directive_name IS 'tag or shareable';
-- COMMENT ON COLUMN graphitron_inherited_directive.ordinal IS 'a tag''s position in the first carrier''s order, the first carrier being the least coordinate; zero on @shareable';
-- COMMENT ON COLUMN graphitron_inherited_directive.value_sdl IS 'the tag''s name: argument as SDL; NULL on @shareable';

CREATE TABLE graphitron_minted_key (
  graph_name  VARCHAR NOT NULL,
  type_name   VARCHAR NOT NULL,
  role        VARCHAR NOT NULL,
  fields      VARCHAR NOT NULL,
  resolvable  BOOLEAN NOT NULL,
  ordinal     INT     NOT NULL,
  PRIMARY KEY (graph_name, type_name, role),
  UNIQUE (graph_name, type_name, ordinal),
  FOREIGN KEY (graph_name, type_name) REFERENCES graphitron_tabletype (graph_name, type_name)
    ON DELETE CASCADE,
  CHECK (role IN ('NODE', 'ISSUE', 'ACCEPT'))
);
COMMENT ON TABLE graphitron_minted_key IS 'One federation key a graph mints on one of its table-bound types, with the rule that minted it. For example a node type of a federation-linked graph whose author wrote no id key carries one NODE row, fields id and resolvable.';
COMMENT ON COLUMN graphitron_minted_key.graph_name IS 'the owning graph''s partition';
COMMENT ON COLUMN graphitron_minted_key.type_name IS 'the type the key is minted on. Into graphitron_tabletype because every rule minting a key mints it on a table-bound type, and cascading because a type that stops resolving to a table stops carrying one';
COMMENT ON COLUMN graphitron_minted_key.role IS 'the rule that minted the key: NODE, federation''s entity rule, a resolvable node of a federated graph keyed by its id where no authored key spells id; ISSUE, the voucher key, an @issue field keying its type, not resolvable here; ACCEPT, the voucher key, an @accept field keying its type beside the authored key, resolvable here';
COMMENT ON COLUMN graphitron_minted_key.fields IS 'the key''s field set as federation spells it inside @key(fields:), unquoted: id for a NODE key; the marked field''s name for an ISSUE or ACCEPT key';
COMMENT ON COLUMN graphitron_minted_key.resolvable IS 'what the key''s resolvable: argument says, whether this subgraph resolves the entity by it: true for a NODE key, a stub never being minted one, and for an ACCEPT key; false for an ISSUE key';
COMMENT ON COLUMN graphitron_minted_key.ordinal IS 'the key''s place among the type''s @key applications: after every key its author wrote, then in the order of the roles that minted keys on it. Stated here rather than counted by each set that renders the application, so the application and its arguments cannot disagree about which @key they are';

-- Federation's entity rule: a node of a federated graph is keyed by its id unless an authored key
-- already spells id, federation needing the entity declaration in the emitted SDL and a
-- node carrying a globally unique id by definition. A node is graphitron_node's, explicit or inferred
-- from the table's node metadata alike, and a graph is federated however it opted in. A stub,
-- @node(resolvable: false), is another subgraph's to resolve, and that subgraph publishes its key. The key
-- comes after every key the author wrote. Decided from the transcription, the node relation and the
-- link, all upstream of the emitted population; the application sets join the element themselves.
CREATE VIEW graphitron_minted_key_rule
  (graph_name, type_name, role, fields, resolvable, ordinal) AS
WITH minted (graph_name, type_name, role, fields, resolvable, role_order) AS (
SELECT n.graph_name, n.type_name, 'NODE', 'id', TRUE, 0
  FROM graphitron_node n
 WHERE n.resolvable
   AND EXISTS (SELECT 1 FROM graphitron_federation_link l WHERE l.graph_name = n.graph_name)
   -- An authored key spelling id is the type's id key, whatever the id binds: federation knows keys,
   -- and a second key spelling id would publish one key twice (the federation-keys ruling in
   -- fact-model.adoc). How it resolves is its binding's. The decode is reached through the
   -- application the corpus honours, at the at sign both share. Positions are dense from zero, so
   -- one selection whose one segment is id is the selection at zero, its segment at zero named id,
   -- with no selection at one and no second segment: each a probe on the entries' whole key.
   AND NOT EXISTS (SELECT 1 FROM graphql_directive_application d
                     JOIN graphitron_ast_federation_key_segment_entry g
                       ON g.graph_name = d.graph_name AND g.source_name = d.source_name
                      AND g.source_line = d.source_line AND g.source_column = d.source_column
                      AND g.position = 0 AND g.segment_position = 0 AND g.segment_name = 'id'
                    WHERE d.graph_name = n.graph_name AND d.coordinate = n.type_name
                      AND d.directive_name = 'key'
                      AND NOT EXISTS (SELECT 1 FROM graphitron_ast_federation_key_selection_entry p
                                       WHERE p.graph_name = g.graph_name AND p.source_name = g.source_name
                                         AND p.source_line = g.source_line
                                         AND p.source_column = g.source_column AND p.position = 1)
                      AND NOT EXISTS (SELECT 1 FROM graphitron_ast_federation_key_segment_entry h
                                       WHERE h.graph_name = g.graph_name AND h.source_name = g.source_name
                                         AND h.source_line = g.source_line
                                         AND h.source_column = g.source_column AND h.position = 0
                                         AND h.segment_position = 1))
UNION ALL
-- @issue: the voucher field keys the issuing type, not resolvable here, so a router can reach the
-- other subgraph's entity from this one only through the voucher. Its field set is the field the
-- author marked; the first where two share a type, which the voucher stage refuses. Not on a node,
-- which the voucher stage refuses too, so the type carries no node key beside it.
SELECT tt.graph_name, tt.type_name, 'ISSUE', MIN(i.field_name), FALSE, 1
  FROM graphql_directive_application d
  JOIN graphql_field_element i ON i.graph_name = d.graph_name AND i.coordinate = d.coordinate
  JOIN graphitron_tabletype tt ON tt.graph_name = i.graph_name AND tt.type_name = i.type_name
 WHERE d.directive_name = 'issue'
   AND EXISTS (SELECT 1 FROM graphitron_federation_link l WHERE l.graph_name = tt.graph_name)
   AND NOT EXISTS (SELECT 1 FROM graphitron_node n
                    WHERE n.graph_name = tt.graph_name AND n.type_name = tt.type_name)
 GROUP BY tt.graph_name, tt.type_name
UNION ALL
-- @accept: the voucher field keys the accepting type, resolvable here, beside the key the author
-- wrote, so a router hands this subgraph the voucher it fetched from the issuing one. Its field set is
-- the field the author marked; the first where two share a type, which the voucher stage refuses. A
-- node may accept, so its node key and this one are both minted, numbered once below.
SELECT tt.graph_name, tt.type_name, 'ACCEPT', MIN(i.field_name), TRUE, 2
  FROM graphql_directive_application d
  JOIN graphql_field_element i ON i.graph_name = d.graph_name AND i.coordinate = d.coordinate
  JOIN graphitron_tabletype tt ON tt.graph_name = i.graph_name AND tt.type_name = i.type_name
 WHERE d.directive_name = 'accept'
   AND EXISTS (SELECT 1 FROM graphitron_federation_link l WHERE l.graph_name = tt.graph_name)
 GROUP BY tt.graph_name, tt.type_name
)
-- Numbered once over every role, after every key the author wrote, so two roles minting on one type
-- cannot collide.
SELECT m.graph_name, m.type_name, m.role, m.fields, m.resolvable,
       CAST((SELECT COUNT(*) FROM graphql_directive_application k
              WHERE k.graph_name = m.graph_name AND k.coordinate = m.type_name
                AND k.directive_name = 'key') AS INT)
       + CAST(ROW_NUMBER() OVER (PARTITION BY m.graph_name, m.type_name ORDER BY m.role_order) AS INT) - 1
  FROM minted m;
COMMENT ON VIEW graphitron_minted_key_rule IS 'One key the minting rules compute, in the shape graphitron_minted_key stores: the rules themselves, evaluated on demand rather than read off disk. For example the minted-keys stage writes this view''s rows for one graph into graphitron_minted_key, which is the name every reader spells.';
-- COMMENT ON COLUMN graphitron_minted_key_rule.graph_name IS 'the owning graph''s partition';
-- COMMENT ON COLUMN graphitron_minted_key_rule.type_name IS 'the type the key is minted on';
-- COMMENT ON COLUMN graphitron_minted_key_rule.role IS 'the rule that mints it';
-- COMMENT ON COLUMN graphitron_minted_key_rule.fields IS 'the key''s field set, unquoted';
-- COMMENT ON COLUMN graphitron_minted_key_rule.resolvable IS 'what the key''s resolvable: argument says';
-- COMMENT ON COLUMN graphitron_minted_key_rule.ordinal IS 'the key''s place among the type''s @key applications';

CREATE VIEW graphitron_directive_application_minted
  (graph_name, coordinate, directive_name, ordinal, origin,
   source_name, source_line, source_column) AS
-- Every key graphitron_minted_key states, on an emitted type, at the ordinal it states.
SELECT k.graph_name, k.type_name, 'key', k.ordinal,
       'MINTED', CAST(NULL AS VARCHAR), CAST(NULL AS INT), CAST(NULL AS INT)
  FROM graphitron_minted_key k
  JOIN graphitron_element e ON e.graph_name = k.graph_name AND e.coordinate = k.type_name
UNION ALL
SELECT i.graph_name, i.type_name, i.directive_name, i.ordinal,
       'MINTED', CAST(NULL AS VARCHAR), CAST(NULL AS INT), CAST(NULL AS INT)
  FROM graphitron_inherited_directive i
  JOIN graphitron_element e ON e.graph_name = i.graph_name AND e.coordinate = i.type_name
UNION ALL
SELECT t.graph_name, t.type_name, 'nodeType',
       CAST((SELECT COUNT(*) FROM graphql_directive_application d
              WHERE d.graph_name = t.graph_name AND d.coordinate = t.type_name
                AND d.directive_name = 'nodeType') AS INT),
       'MINTED', CAST(NULL AS VARCHAR), CAST(NULL AS INT), CAST(NULL AS INT)
  FROM graphitron_synthesized_node_type_id t
  JOIN graphitron_element e ON e.graph_name = t.graph_name AND e.coordinate = t.type_name
UNION ALL
-- The voucher field of an ISSUE or ACCEPT key is kept from the client schema.
SELECT k.graph_name, k.type_name || '.' || k.fields, 'inaccessible',
       CAST((SELECT COUNT(*) FROM graphql_directive_application d
              WHERE d.graph_name = k.graph_name AND d.coordinate = k.type_name || '.' || k.fields
                AND d.directive_name = 'inaccessible') AS INT),
       'MINTED', CAST(NULL AS VARCHAR), CAST(NULL AS INT), CAST(NULL AS INT)
  FROM graphitron_minted_key k
  JOIN graphitron_element e ON e.graph_name = k.graph_name AND e.coordinate = k.type_name || '.' || k.fields
 WHERE k.role IN ('ISSUE', 'ACCEPT');
COMMENT ON VIEW graphitron_directive_application_minted IS 'One of the three sets graphitron_directive_application is the union of: an application macro expansion adds. For example @key(fields: "id") on a node type in a federation-linked graph whose author declared no id key, or the @tag a minted Connection inherits from its carrier.';
-- COMMENT ON COLUMN graphitron_directive_application_minted.graph_name IS 'the owning graph''s partition';
-- COMMENT ON COLUMN graphitron_directive_application_minted.coordinate IS 'the coordinate the macro applies the directive to';
-- COMMENT ON COLUMN graphitron_directive_application_minted.directive_name IS 'the directive the macro applies';
-- COMMENT ON COLUMN graphitron_directive_application_minted.ordinal IS 'after every authored application of the same directive at the same coordinate, a minted type having none';
-- COMMENT ON COLUMN graphitron_directive_application_minted.origin IS 'always MINTED';
-- COMMENT ON COLUMN graphitron_directive_application_minted.source_name IS 'always NULL, a minted application having no position';
-- COMMENT ON COLUMN graphitron_directive_application_minted.source_line IS 'always NULL';
-- COMMENT ON COLUMN graphitron_directive_application_minted.source_column IS 'always NULL';

CREATE VIEW graphitron_directive_application_arg_authored
  (graph_name, coordinate, directive_name, ordinal, directive_argument_name, value_sdl) AS
SELECT a.graph_name, a.coordinate, a.directive_name, a.ordinal,
       a.directive_argument_name, a.value_sdl
  FROM graphql_directive_application_arg a
  JOIN graphitron_element e ON e.graph_name = a.graph_name AND e.coordinate = a.coordinate;
COMMENT ON VIEW graphitron_directive_application_arg_authored IS 'One of the three sets graphitron_directive_application_arg is the union of: an argument an author passed to an application the authored set carries. For example the name: "film" of type Film @table(name: "film") is one row here.';
-- COMMENT ON COLUMN graphitron_directive_application_arg_authored.graph_name IS 'the owning graph''s partition';
-- COMMENT ON COLUMN graphitron_directive_application_arg_authored.coordinate IS 'the owning application''s coordinate';
-- COMMENT ON COLUMN graphitron_directive_application_arg_authored.directive_name IS 'the owning application''s directive name';
-- COMMENT ON COLUMN graphitron_directive_application_arg_authored.ordinal IS 'the owning application''s ordinal';
-- COMMENT ON COLUMN graphitron_directive_application_arg_authored.directive_argument_name IS 'the formal argument the value binds';
-- COMMENT ON COLUMN graphitron_directive_application_arg_authored.value_sdl IS 'the value as written';

CREATE VIEW graphitron_directive_application_arg_configured
  (graph_name, coordinate, directive_name, ordinal, directive_argument_name, value_sdl) AS
SELECT c.graph_name, c.coordinate, 'tag', c.ordinal, 'name', c.value_sdl
  FROM graphitron_configured_tag c;
COMMENT ON VIEW graphitron_directive_application_arg_configured IS 'One of the three sets graphitron_directive_application_arg is the union of: an argument the configuration passes to an application it adds. For example the name: "stable" of a configured tag is one row here.';
-- COMMENT ON COLUMN graphitron_directive_application_arg_configured.graph_name IS 'the owning graph''s partition';
-- COMMENT ON COLUMN graphitron_directive_application_arg_configured.coordinate IS 'the owning application''s coordinate';
-- COMMENT ON COLUMN graphitron_directive_application_arg_configured.directive_name IS 'the owning application''s directive name';
-- COMMENT ON COLUMN graphitron_directive_application_arg_configured.ordinal IS 'the owning application''s ordinal';
-- COMMENT ON COLUMN graphitron_directive_application_arg_configured.directive_argument_name IS 'always name, the one argument @tag takes';
-- COMMENT ON COLUMN graphitron_directive_application_arg_configured.value_sdl IS 'the configured tag as SDL';

CREATE VIEW graphitron_directive_application_arg_minted
  (graph_name, coordinate, directive_name, ordinal, directive_argument_name, value_sdl) AS
-- A minted key's two arguments, as graphitron_minted_key states them.
SELECT k.graph_name, k.type_name, 'key', k.ordinal, 'fields', '"' || k.fields || '"'
  FROM graphitron_minted_key k
  JOIN graphitron_element e ON e.graph_name = k.graph_name AND e.coordinate = k.type_name
UNION ALL
SELECT k.graph_name, k.type_name, 'key', k.ordinal, 'resolvable',
       CASE WHEN k.resolvable THEN 'true' ELSE 'false' END
  FROM graphitron_minted_key k
  JOIN graphitron_element e ON e.graph_name = k.graph_name AND e.coordinate = k.type_name
UNION ALL
SELECT i.graph_name, i.type_name, i.directive_name, i.ordinal, 'name', i.value_sdl
  FROM graphitron_inherited_directive i
  JOIN graphitron_element e ON e.graph_name = i.graph_name AND e.coordinate = i.type_name
 WHERE i.directive_name = 'tag'
UNION ALL
SELECT t.graph_name, t.type_name, 'nodeType',
       CAST((SELECT COUNT(*) FROM graphql_directive_application d
              WHERE d.graph_name = t.graph_name AND d.coordinate = t.type_name
                AND d.directive_name = 'nodeType') AS INT),
       'typeId', '"' || REPLACE(REPLACE(t.type_id, '\', '\\'), '"', '\"') || '"'
  FROM graphitron_synthesized_node_type_id t
  JOIN graphitron_element e ON e.graph_name = t.graph_name AND e.coordinate = t.type_name;
COMMENT ON VIEW graphitron_directive_application_arg_minted IS 'One of the three sets graphitron_directive_application_arg is the union of: an argument macro expansion passes to an application it adds. For example the fields: "id" and resolvable: true of a synthesised @key are two rows here.';
-- COMMENT ON COLUMN graphitron_directive_application_arg_minted.graph_name IS 'the owning graph''s partition';
-- COMMENT ON COLUMN graphitron_directive_application_arg_minted.coordinate IS 'the owning application''s coordinate';
-- COMMENT ON COLUMN graphitron_directive_application_arg_minted.directive_name IS 'the owning application''s directive name';
-- COMMENT ON COLUMN graphitron_directive_application_arg_minted.ordinal IS 'the owning application''s ordinal';
-- COMMENT ON COLUMN graphitron_directive_application_arg_minted.directive_argument_name IS 'the formal argument the value binds';
-- COMMENT ON COLUMN graphitron_directive_application_arg_minted.value_sdl IS 'the value as SDL, which the macro states';

CREATE TABLE graphitron_code_reference (
  graph_name         VARCHAR NOT NULL,
  coordinate         VARCHAR NOT NULL,
  directive_name     VARCHAR NOT NULL,
  ordinal            INT     NOT NULL,
  owner              VARCHAR NOT NULL,
  kind               VARCHAR NOT NULL,
  source_name        VARCHAR NOT NULL,
  source_line        INT     NOT NULL,
  source_column      INT     NOT NULL,
  method_source_name VARCHAR NOT NULL,
  method_class_name  VARCHAR NOT NULL,
  method_name        VARCHAR NOT NULL,
  method_descriptor  VARCHAR NOT NULL,
  touched_at         TIMESTAMP NOT NULL,
  PRIMARY KEY (graph_name, coordinate, directive_name, ordinal, owner),
  UNIQUE (graph_name, coordinate, directive_name, ordinal, owner, kind),
  -- The application the reference is written in, so a reference cannot outlive it.
  FOREIGN KEY (graph_name, coordinate, directive_name, ordinal)
    REFERENCES graphql_directive_application (graph_name, coordinate, directive_name, ordinal)
    ON DELETE CASCADE,
  -- The reference as written, kept for a defect to point at, so a resolution cannot outlive the
  -- writing it resolves.
  FOREIGN KEY (graph_name, source_name, source_line, source_column)
    REFERENCES graphitron_ast_code_reference_entry (graph_name, source_name, source_line, source_column)
    ON DELETE CASCADE,
  -- The method, so a reading that no longer finds it takes the resolution with it.
  FOREIGN KEY (method_source_name, method_class_name, method_name, method_descriptor)
    REFERENCES code_method (source_name, class_name, method_name, descriptor) ON DELETE CASCADE,
  CHECK (kind IN ('ROOT', 'PATH_ELEMENT', 'ORDER_FIELD', 'ORDER_FIELD_PATH', 'ROUTE_PATH'))
);
COMMENT ON TABLE graphitron_code_reference IS 'The one method a written Java code reference names, where the graph''s classpath answers with exactly one. For example @service(service: {className: "no.example.CityService", method: "cityUppercase"}) draws one row naming the one cityUppercase that class declares, and a misspelt method draws none.';
COMMENT ON COLUMN graphitron_code_reference.graph_name IS 'the owning graph''s partition, carried from the written reference';
COMMENT ON COLUMN graphitron_code_reference.coordinate IS 'the element the application writing the reference is on: a type, a field, an argument or an input field';
COMMENT ON COLUMN graphitron_code_reference.directive_name IS 'the directive whose application wrote the reference';
COMMENT ON COLUMN graphitron_code_reference.ordinal IS 'the application''s ordinal, with the coordinate and the directive naming the application in graphql_directive_application';
COMMENT ON COLUMN graphitron_code_reference.owner IS 'the names the reference was written under in its application, spelled, completing the key: service for a root reference, path.0 for a path element''s condition, fields.1 for an @order field''s method, fields.1.path.0 for a condition in that field''s path. Names and ordinals and no position, so editing the file above it changes no row';
COMMENT ON COLUMN graphitron_code_reference.kind IS 'which owner the reference has: ROOT on the application itself, PATH_ELEMENT on a path element, ORDER_FIELD on an @order field, ORDER_FIELD_PATH on an element of that field''s path, ROUTE_PATH under the removed @multitableReference';
COMMENT ON COLUMN graphitron_code_reference.source_name IS 'the file the reference was written in; with the line and the column, where a defect about it points, and the reference''s key in graphitron_ast_code_reference_entry. An attribute and not the key';
COMMENT ON COLUMN graphitron_code_reference.source_line IS 'source line of the node the reference was written as';
COMMENT ON COLUMN graphitron_code_reference.source_column IS 'source column of the same';
COMMENT ON COLUMN graphitron_code_reference.method_source_name IS 'the classpath entry the resolved method was read from, the first of the four columns naming one code_method row; one of the entries the graph reached through store_graph_source';
COMMENT ON COLUMN graphitron_code_reference.method_class_name IS 'the class declaring the resolved method, equal to what the author wrote, the match being exact: Java names are case-sensitive and a misspelling resolves to nothing rather than to a near match';
COMMENT ON COLUMN graphitron_code_reference.method_name IS 'the resolved method''s name: the reference''s, or the field''s where an @externalField wrote none, as graphitron_code_reference_site states it';
COMMENT ON COLUMN graphitron_code_reference.method_descriptor IS 'the resolved method''s JVM descriptor, completing the reference into code_method. Not in the key: a reference matching two overloads is ambiguous and draws no row, so the descriptor is what the one method is rather than what tells two rows apart';
COMMENT ON COLUMN graphitron_code_reference.touched_at IS 'when the reading that derived this row ran. Swept per graph after the reading upserts, so a reference that stopped resolving leaves and the rest stay; a reference the author removed goes through the cascade on its written form';

CREATE INDEX ix_spelled_table_spelling ON graphitron_spelled_table (graph_name, spelling);
COMMENT ON INDEX ix_spelled_table_spelling IS 'Serves the resolution key itself, which is the only way any reader reaches this relation: the namings in the view bodies (graphitron_entry_defect_table_rule, graphitron_path_element_routine_rule) both join on the graph and the spelling and nothing else. The index this relation''s own declaration already anticipates in arguing that both sides of both comparisons are stored folded columns, so the match is an equality an index can serve. Measured on the read-cost gate''s twelve-unit fixture with statistics current, the five indexes this file declares against none of them: the separate-fetch view since replaced by graphitron_producer cost 11957 scans without them and 669 with them, the type binding view since replaced by graphitron_tabletype 357 against 198, and a node id decode defect view since dissolved 1901 against 1419. This index is the one that moves all three; it is the widest-reaching of the five by reader count, every relation reaching a spelling reaching it through one of the bodies above. Not UNIQUE, and the one target here where that is a statement about the answer rather than about the key: a spelling two schemas both declare is several rows and candidates says so, ambiguity being rows and never a decline.';

CREATE TABLE graphitron_type_member (
  graph_name       VARCHAR   NOT NULL,
  container_name   VARCHAR   NOT NULL,
  container_kind   VARCHAR   NOT NULL,
  member_type_name VARCHAR   NOT NULL,
  member_kind      VARCHAR   NOT NULL,
  position         INT       NOT NULL,
  touched_at       TIMESTAMP NOT NULL,
  PRIMARY KEY (graph_name, container_name, member_type_name),
  -- Both ends are types of the kinds that can stand there, held by the supertype's own key.
  FOREIGN KEY (graph_name, container_name, container_kind)
    REFERENCES graphitron_type (graph_name, type_name, kind) ON DELETE CASCADE,
  FOREIGN KEY (graph_name, member_type_name, member_kind)
    REFERENCES graphitron_type (graph_name, type_name, kind) ON DELETE CASCADE,
  CHECK (container_kind IN ('UNION', 'INTERFACE')),
  CHECK (member_kind IN ('OBJECT', 'INTERFACE'))
);
COMMENT ON TABLE graphitron_type_member IS 'A member of a polymorphic type: one row per union or interface and each type it admits. For example Searchable = Film | Language draws Film and Language under Searchable, and type Language implements Node draws Language under Node.';
COMMENT ON COLUMN graphitron_type_member.graph_name IS 'the owning graph''s partition';
COMMENT ON COLUMN graphitron_type_member.container_name IS 'the union or interface; with the graph and the member, the grain';
COMMENT ON COLUMN graphitron_type_member.container_kind IS 'UNION or INTERFACE, the container''s kind, pinned so the foreign key holds it to a type of that kind';
COMMENT ON COLUMN graphitron_type_member.member_type_name IS 'the type the container admits: a union''s listed member, or a type implementing the interface';
COMMENT ON COLUMN graphitron_type_member.member_kind IS 'OBJECT, or INTERFACE for an interface implementing another, pinned as the container''s kind is';
COMMENT ON COLUMN graphitron_type_member.position IS 'the member''s place as its declaration states it: in the union''s list, or the interface''s place in the implementing type''s list, as graphql_union_member and graphql_implements_interface number them';
COMMENT ON COLUMN graphitron_type_member.touched_at IS 'when the reading that derived this row ran; swept per graph after the reading upserts';

CREATE VIEW graphitron_type_member_rule
  (graph_name, container_name, container_kind, member_type_name, member_kind, position) AS
SELECT u.graph_name, u.union_name, c.kind, u.member_type_name, m.kind, u.position
  FROM graphql_union_member u
  JOIN graphitron_type c
    ON c.graph_name = u.graph_name AND c.type_name = u.union_name AND c.kind = 'UNION'
  JOIN graphitron_type m
    ON m.graph_name = u.graph_name AND m.type_name = u.member_type_name
   AND m.kind IN ('OBJECT', 'INTERFACE')
UNION ALL
SELECT i.graph_name, i.interface_name, c.kind, i.type_name, m.kind, i.position
  FROM graphql_implements_interface i
  JOIN graphitron_type c
    ON c.graph_name = i.graph_name AND c.type_name = i.interface_name AND c.kind = 'INTERFACE'
  JOIN graphitron_type m
    ON m.graph_name = i.graph_name AND m.type_name = i.type_name
   AND m.kind IN ('OBJECT', 'INTERFACE');
COMMENT ON VIEW graphitron_type_member_rule IS 'One row the type member rule computes, in the shape graphitron_type_member stores: the rule itself, evaluated on demand rather than read off disk. For example the macro-expansion stage inserts this view''s rows for one graph into graphitron_type_member, which is the name every reader spells.';
-- COMMENT ON COLUMN graphitron_type_member_rule.graph_name IS 'the graph_name of a row of this rule, which the stage writes into graphitron_type_member.graph_name';
-- COMMENT ON COLUMN graphitron_type_member_rule.container_name IS 'the container_name of a row of this rule, which the stage writes into graphitron_type_member.container_name';
-- COMMENT ON COLUMN graphitron_type_member_rule.container_kind IS 'the container_kind of a row of this rule, which the stage writes into graphitron_type_member.container_kind';
-- COMMENT ON COLUMN graphitron_type_member_rule.member_type_name IS 'the member_type_name of a row of this rule, which the stage writes into graphitron_type_member.member_type_name';
-- COMMENT ON COLUMN graphitron_type_member_rule.member_kind IS 'the member_kind of a row of this rule, which the stage writes into graphitron_type_member.member_kind';
-- COMMENT ON COLUMN graphitron_type_member_rule.position IS 'the position of a row of this rule, which the stage writes into graphitron_type_member.position';

CREATE TABLE graphitron_scalar_class (
  graph_name VARCHAR   NOT NULL,
  type_name  VARCHAR   NOT NULL,
  kind       VARCHAR   NOT NULL,
  java_class VARCHAR   NOT NULL,
  touched_at TIMESTAMP NOT NULL,
  PRIMARY KEY (graph_name, type_name),
  -- A scalar, held there by the supertype's own key; a type that stops being one takes its class.
  FOREIGN KEY (graph_name, type_name, kind)
    REFERENCES graphitron_type (graph_name, type_name, kind) ON DELETE CASCADE,
  CHECK (kind = 'SCALAR')
);
COMMENT ON TABLE graphitron_scalar_class IS 'The Java class a scalar''s values arrive as: one row per scalar whose class is known. For example Int arrives as java.lang.Integer, and scalar Money @scalarType(scalar: "com.example.Scalars.MONEY") as the input type of the constant''s Coercing.';
COMMENT ON COLUMN graphitron_scalar_class.graph_name IS 'the owning graph''s partition';
COMMENT ON COLUMN graphitron_scalar_class.type_name IS 'the scalar; with the graph, the grain';
COMMENT ON COLUMN graphitron_scalar_class.kind IS 'SCALAR, pinned so the foreign key holds the row to a type of that kind';
COMMENT ON COLUMN graphitron_scalar_class.java_class IS 'the fully-qualified class graphql-java delivers a value as, boxed: a built-in''s by graphql-java''s own coercing, any other''s by the constant its @scalarType names among the graph''s classpath entries. Whether a parameter of a primitive or another type accepts it is the reader''s question, not this column''s';
COMMENT ON COLUMN graphitron_scalar_class.touched_at IS 'when the reading that derived this row ran; swept per graph after the reading upserts';
-- A reader holding a parameter's type asks whether any scalar arrives as it.
CREATE INDEX graphitron_scalar_class_java_ix ON graphitron_scalar_class (graph_name, java_class);

CREATE VIEW graphitron_scalar_class_rule (graph_name, type_name, kind, java_class) AS
-- A scalar whose candidates disagree has no class: the constant is named in two entries that
-- coerce differently, and nothing says which the generator is handed.
SELECT graph_name, type_name, 'SCALAR', MIN(java_class)
  FROM (SELECT t.graph_name, t.type_name, b.java_class
          FROM graphitron_type t
          JOIN (VALUES ('ID', 'java.lang.String'), ('String', 'java.lang.String'),
                       ('Int', 'java.lang.Integer'), ('Float', 'java.lang.Double'),
                       ('Boolean', 'java.lang.Boolean')) b (scalar, java_class)
            ON b.scalar = t.type_name
         WHERE t.kind = 'SCALAR'
        UNION ALL
        SELECT t.graph_name, t.type_name, k.input_type
          FROM graphql_directive_application da
          JOIN graphitron_ast_scalar_type_entry e
            ON e.graph_name = da.graph_name AND e.source_name = da.source_name
           AND e.source_line = da.source_line AND e.source_column = da.source_column
          JOIN graphitron_type t
            ON t.graph_name = da.graph_name AND t.type_name = da.coordinate AND t.kind = 'SCALAR'
          JOIN code_graph_class g
            ON g.graph_name = da.graph_name AND g.class_name = e.scalar_ref_class_part
          JOIN code_scalar_constant k
            ON k.source_name = g.source_name AND k.class_name = g.class_name
           AND k.field_name = e.scalar_ref_field_part
         WHERE da.directive_name = 'scalarType' AND da.ordinal = 0 AND k.input_type IS NOT NULL) c
 GROUP BY graph_name, type_name
HAVING COUNT(DISTINCT java_class) = 1;
COMMENT ON VIEW graphitron_scalar_class_rule IS 'One row the scalar class rule computes, in the shape graphitron_scalar_class stores: the rule itself, evaluated on demand rather than read off disk. For example the macro-expansion stage inserts this view''s rows for one graph into graphitron_scalar_class, which is the name every reader spells.';
-- COMMENT ON COLUMN graphitron_scalar_class_rule.graph_name IS 'the graph_name of a row of this rule, which the stage writes into graphitron_scalar_class.graph_name';
-- COMMENT ON COLUMN graphitron_scalar_class_rule.type_name IS 'the type_name of a row of this rule, which the stage writes into graphitron_scalar_class.type_name';
-- COMMENT ON COLUMN graphitron_scalar_class_rule.kind IS 'the kind of a row of this rule, which the stage writes into graphitron_scalar_class.kind';
-- COMMENT ON COLUMN graphitron_scalar_class_rule.java_class IS 'the java_class of a row of this rule, which the stage writes into graphitron_scalar_class.java_class';

CREATE TABLE graphitron_occurrence_input_type (
  graph_name VARCHAR   NOT NULL,
  coordinate VARCHAR   NOT NULL,
  type_name  VARCHAR   NOT NULL,
  type_kind  VARCHAR   NOT NULL,
  is_list    BOOLEAN   NOT NULL,
  java_class VARCHAR,
  touched_at TIMESTAMP NOT NULL,
  PRIMARY KEY (graph_name, coordinate),
  FOREIGN KEY (graph_name, coordinate)
    REFERENCES graphitron_occurrence (graph_name, coordinate) ON DELETE CASCADE,
  -- The type it takes, of the kind it is, by the supertype's own key.
  FOREIGN KEY (graph_name, type_name, type_kind)
    REFERENCES graphitron_type (graph_name, type_name, kind) ON DELETE CASCADE,
  CHECK (type_kind IN ('SCALAR', 'ENUM', 'INPUT_OBJECT'))
);
COMMENT ON TABLE graphitron_occurrence_input_type IS 'The type an argument or input field occurrence takes, and the Java class its values arrive as: one row per such occurrence. For example Query.films(filter:) takes the input object FilmFilter and has no class, and Query.films(filter.releaseYear:) takes Int, arriving as java.lang.Integer.';
COMMENT ON COLUMN graphitron_occurrence_input_type.graph_name IS 'the owning graph''s partition';
COMMENT ON COLUMN graphitron_occurrence_input_type.coordinate IS 'the argument or input field occurrence; with the graph, the grain';
COMMENT ON COLUMN graphitron_occurrence_input_type.type_name IS 'the named type the declared element takes, its wrappers removed';
COMMENT ON COLUMN graphitron_occurrence_input_type.type_kind IS 'SCALAR, ENUM or INPUT_OBJECT, the named type''s kind, pinned so the foreign key holds it to a type of that kind';
COMMENT ON COLUMN graphitron_occurrence_input_type.is_list IS 'whether the declared element is a list';
COMMENT ON COLUMN graphitron_occurrence_input_type.java_class IS 'the class one value of the named type arrives as, graphitron_scalar_class''s, NULL for an enum, an input object or a scalar whose class is not known; the list is is_list''s to say';
COMMENT ON COLUMN graphitron_occurrence_input_type.touched_at IS 'when the reading that derived this row ran; swept per graph after the reading upserts';

CREATE VIEW graphitron_occurrence_input_type_rule
  (graph_name, coordinate, type_name, type_kind, is_list, java_class) AS
SELECT e.graph_name, e.coordinate, t.type_name, t.kind, COALESCE(ga.is_list, gf.is_list), sc.java_class
  FROM graphitron_occurrence e
  LEFT JOIN graphitron_argument ga ON ga.graph_name = e.graph_name AND ga.coordinate = e.element_coordinate
  LEFT JOIN graphitron_field gf ON gf.graph_name = e.graph_name AND gf.coordinate = e.element_coordinate
  JOIN graphitron_type t ON t.graph_name = e.graph_name AND t.type_name = COALESCE(ga.named_type, gf.named_type)
  LEFT JOIN graphitron_scalar_class sc ON sc.graph_name = t.graph_name AND sc.type_name = t.type_name
 WHERE e.kind IN ('FIELD_ARGUMENT', 'INPUT_FIELD')
   AND t.kind IN ('SCALAR', 'ENUM', 'INPUT_OBJECT');
COMMENT ON VIEW graphitron_occurrence_input_type_rule IS 'One row the occurrence input type rule computes, in the shape graphitron_occurrence_input_type stores: the rule itself, evaluated on demand rather than read off disk. For example the occurrences stage inserts this view''s rows for one graph into graphitron_occurrence_input_type, which is the name every reader spells.';
-- COMMENT ON COLUMN graphitron_occurrence_input_type_rule.graph_name IS 'the graph_name of a row of this rule, which the stage writes into graphitron_occurrence_input_type.graph_name';
-- COMMENT ON COLUMN graphitron_occurrence_input_type_rule.coordinate IS 'the coordinate of a row of this rule, which the stage writes into graphitron_occurrence_input_type.coordinate';
-- COMMENT ON COLUMN graphitron_occurrence_input_type_rule.type_name IS 'the type_name of a row of this rule, which the stage writes into graphitron_occurrence_input_type.type_name';
-- COMMENT ON COLUMN graphitron_occurrence_input_type_rule.type_kind IS 'the type_kind of a row of this rule, which the stage writes into graphitron_occurrence_input_type.type_kind';
-- COMMENT ON COLUMN graphitron_occurrence_input_type_rule.is_list IS 'the is_list of a row of this rule, which the stage writes into graphitron_occurrence_input_type.is_list';
-- COMMENT ON COLUMN graphitron_occurrence_input_type_rule.java_class IS 'the java_class of a row of this rule, which the stage writes into graphitron_occurrence_input_type.java_class';

CREATE TABLE graphitron_connection_position (
  position   VARCHAR NOT NULL,
  role       VARCHAR NOT NULL,
  field_name VARCHAR NOT NULL,
  PRIMARY KEY (position),
  UNIQUE (role, field_name),
  CHECK (role IN ('CONNECTION', 'EDGE', 'PAGE_INFO'))
);
COMMENT ON TABLE graphitron_connection_position IS 'One position of the connection shape: the field a connection, its edge or its page info fills it with. For example TOTAL_COUNT is a connection''s totalCount, NODE an edge''s node and END_CURSOR the page info''s endCursor.';
COMMENT ON COLUMN graphitron_connection_position.position IS 'the position, the key a field filling it names';
COMMENT ON COLUMN graphitron_connection_position.role IS 'the type of the shape the position is a field of: CONNECTION, EDGE or PAGE_INFO';
COMMENT ON COLUMN graphitron_connection_position.field_name IS 'the name of the field that fills it, as the Relay Cursor Connections specification spells it (edges, pageInfo, node, cursor and the four page-info fields) or as graphitron adds it (nodes, totalCount, facets)';
INSERT INTO graphitron_connection_position VALUES
  ('EDGES', 'CONNECTION', 'edges'),
  ('NODES', 'CONNECTION', 'nodes'),
  ('PAGE_INFO', 'CONNECTION', 'pageInfo'),
  ('TOTAL_COUNT', 'CONNECTION', 'totalCount'),
  ('FACETS', 'CONNECTION', 'facets'),
  ('NODE', 'EDGE', 'node'),
  ('CURSOR', 'EDGE', 'cursor'),
  ('HAS_NEXT_PAGE', 'PAGE_INFO', 'hasNextPage'),
  ('HAS_PREVIOUS_PAGE', 'PAGE_INFO', 'hasPreviousPage'),
  ('START_CURSOR', 'PAGE_INFO', 'startCursor'),
  ('END_CURSOR', 'PAGE_INFO', 'endCursor');

CREATE TABLE graphitron_edge (
  graph_name     VARCHAR   NOT NULL,
  type_name      VARCHAR   NOT NULL,
  kind           VARCHAR   NOT NULL,
  item_type_name VARCHAR   NOT NULL,
  touched_at     TIMESTAMP NOT NULL,
  PRIMARY KEY (graph_name, type_name),
  -- An edge is an object type, held there by the supertype's own key.
  FOREIGN KEY (graph_name, type_name, kind)
    REFERENCES graphitron_type (graph_name, type_name, kind) ON DELETE CASCADE,
  FOREIGN KEY (graph_name, item_type_name)
    REFERENCES graphitron_type (graph_name, type_name) ON DELETE CASCADE,
  CHECK (kind = 'OBJECT')
);
COMMENT ON TABLE graphitron_edge IS 'An edge of a Relay connection and the item its node names: one row per edge type. For example FilmsEdge, whose node field names Film, draws one row naming Film, however many connections page through it.';
COMMENT ON COLUMN graphitron_edge.graph_name IS 'the owning graph''s partition';
COMMENT ON COLUMN graphitron_edge.type_name IS 'the edge type, an OBJECT some connection''s edges field names; with the graph, the grain';
COMMENT ON COLUMN graphitron_edge.kind IS 'always OBJECT, pinned so the foreign key holds the edge to an object type';
COMMENT ON COLUMN graphitron_edge.item_type_name IS 'the type the edge carries, read off its node field''s named type with its wrappers stripped. A name and not a binding: whether the item is bound to a table is graphitron_tabletype''s answer';
COMMENT ON COLUMN graphitron_edge.touched_at IS 'when the reading that derived this row ran; swept per graph after the reading upserts, so a type that stopped being an edge leaves';

CREATE VIEW graphitron_edge_rule (graph_name, type_name, kind, item_type_name) AS
-- From the connection down, each step a key probe; an edge two connections share is one row.
SELECT DISTINCT et.graph_name, et.type_name, et.kind, n.named_type
  FROM graphitron_type c
  JOIN graphitron_field e
    ON e.graph_name = c.graph_name AND e.type_name = c.type_name AND e.field_name = 'edges'
  JOIN graphitron_type et
    ON et.graph_name = e.graph_name AND et.type_name = e.named_type AND et.kind = 'OBJECT'
  JOIN graphitron_field n
    ON n.graph_name = et.graph_name AND n.type_name = et.type_name AND n.field_name = 'node'
 WHERE c.kind = 'OBJECT';
COMMENT ON VIEW graphitron_edge_rule IS 'One row the edge rule computes, in the shape graphitron_edge stores: the rule itself, evaluated on demand rather than read off disk. For example the macro-expansion stage inserts this view''s rows for one graph into graphitron_edge, which is the name every reader spells.';
-- COMMENT ON COLUMN graphitron_edge_rule.graph_name IS 'the graph_name of a row of this rule, which the stage writes into graphitron_edge.graph_name';
-- COMMENT ON COLUMN graphitron_edge_rule.type_name IS 'the type_name of a row of this rule, which the stage writes into graphitron_edge.type_name';
-- COMMENT ON COLUMN graphitron_edge_rule.kind IS 'the kind of a row of this rule, which the stage writes into graphitron_edge.kind';
-- COMMENT ON COLUMN graphitron_edge_rule.item_type_name IS 'the item_type_name of a row of this rule, which the stage writes into graphitron_edge.item_type_name';

CREATE TABLE graphitron_connection (
  graph_name     VARCHAR   NOT NULL,
  type_name      VARCHAR   NOT NULL,
  kind           VARCHAR   NOT NULL,
  edge_type_name VARCHAR   NOT NULL,
  touched_at     TIMESTAMP NOT NULL,
  PRIMARY KEY (graph_name, type_name),
  -- A connection is an object type, held there by the supertype's own key.
  FOREIGN KEY (graph_name, type_name, kind)
    REFERENCES graphitron_type (graph_name, type_name, kind) ON DELETE CASCADE,
  -- Its edge, which carries the item; two connections may share one edge.
  FOREIGN KEY (graph_name, edge_type_name)
    REFERENCES graphitron_edge (graph_name, type_name) ON DELETE CASCADE,
  CHECK (kind = 'OBJECT')
);
COMMENT ON TABLE graphitron_connection IS 'A Relay connection type and the edge it pages through: one row per type whose shape is a connection. For example a FilmsConnection declaring edges: [FilmsEdge] draws one row naming FilmsEdge, and a type that is not a connection draws none, so a reader left-joins this rather than joining it.';
COMMENT ON COLUMN graphitron_connection.graph_name IS 'the owning graph''s partition';
COMMENT ON COLUMN graphitron_connection.type_name IS 'the connection type itself, the wrapper a field returns; with the graph, the grain';
COMMENT ON COLUMN graphitron_connection.kind IS 'always OBJECT, pinned so the foreign key holds the connection to an object type';
COMMENT ON COLUMN graphitron_connection.edge_type_name IS 'the edge type its edges field names, a graphitron_edge row, whose item is what the connection pages';
COMMENT ON COLUMN graphitron_connection.touched_at IS 'when the reading that derived this row ran; swept per graph after the reading upserts, so a type that stopped being a connection leaves';

CREATE VIEW graphitron_connection_rule (graph_name, type_name, kind, edge_type_name) AS
SELECT c.graph_name, c.type_name, c.kind, e.named_type
  FROM graphitron_type c
  JOIN graphitron_field e
    ON e.graph_name = c.graph_name AND e.type_name = c.type_name AND e.field_name = 'edges'
  JOIN graphitron_type et
    ON et.graph_name = e.graph_name AND et.type_name = e.named_type AND et.kind = 'OBJECT'
  JOIN graphitron_field n
    ON n.graph_name = et.graph_name AND n.type_name = et.type_name AND n.field_name = 'node'
 WHERE c.kind = 'OBJECT';
COMMENT ON VIEW graphitron_connection_rule IS 'One row the connection rule computes, in the shape graphitron_connection stores: the rule itself, evaluated on demand rather than read off disk. For example the macro-expansion stage inserts this view''s rows for one graph into graphitron_connection, which is the name every reader spells.';
-- COMMENT ON COLUMN graphitron_connection_rule.graph_name IS 'the graph_name of a row of this rule, which the stage writes into graphitron_connection.graph_name';
-- COMMENT ON COLUMN graphitron_connection_rule.type_name IS 'the type_name of a row of this rule, which the stage writes into graphitron_connection.type_name';
-- COMMENT ON COLUMN graphitron_connection_rule.kind IS 'the kind of a row of this rule, which the stage writes into graphitron_connection.kind';
-- COMMENT ON COLUMN graphitron_connection_rule.edge_type_name IS 'the edge_type_name of a row of this rule, which the stage writes into graphitron_connection.edge_type_name';

CREATE TABLE graphitron_field_position (
  graph_name VARCHAR   NOT NULL,
  type_name  VARCHAR   NOT NULL,
  field_name VARCHAR   NOT NULL,
  position   VARCHAR   NOT NULL,
  touched_at TIMESTAMP NOT NULL,
  PRIMARY KEY (graph_name, type_name, field_name),
  -- A type fills a position once.
  UNIQUE (graph_name, type_name, position),
  FOREIGN KEY (graph_name, type_name, field_name)
    REFERENCES graphitron_field (graph_name, type_name, field_name) ON DELETE CASCADE,
  FOREIGN KEY (position) REFERENCES graphitron_connection_position (position)
);
COMMENT ON TABLE graphitron_field_position IS 'A field that fills a position of the connection shape: one row per field. For example FilmsConnection.totalCount fills TOTAL_COUNT, and PageInfo.endCursor fills END_CURSOR however many connections share PageInfo; a field filling no position has no row.';
COMMENT ON COLUMN graphitron_field_position.graph_name IS 'the owning graph''s partition';
COMMENT ON COLUMN graphitron_field_position.type_name IS 'the connection, edge or page info type declaring the field';
COMMENT ON COLUMN graphitron_field_position.field_name IS 'the field; with the graph and the type, the grain';
COMMENT ON COLUMN graphitron_field_position.position IS 'the position it fills, a graphitron_connection_position row of the role its type plays';
COMMENT ON COLUMN graphitron_field_position.touched_at IS 'when the reading that derived this row ran; swept per graph after the reading upserts, so a field that stopped filling a position leaves';

CREATE VIEW graphitron_field_position_rule (graph_name, type_name, field_name, position) AS
-- A connection's fields, its edge's fields, and the fields of the type its pageInfo field names.
SELECT f.graph_name, f.type_name, f.field_name, p.position
  FROM graphitron_connection c
  JOIN graphitron_field f ON f.graph_name = c.graph_name AND f.type_name = c.type_name
  JOIN graphitron_connection_position p ON p.role = 'CONNECTION' AND p.field_name = f.field_name
UNION
SELECT f.graph_name, f.type_name, f.field_name, p.position
  FROM graphitron_edge e
  JOIN graphitron_field f ON f.graph_name = e.graph_name AND f.type_name = e.type_name
  JOIN graphitron_connection_position p ON p.role = 'EDGE' AND p.field_name = f.field_name
UNION
SELECT f.graph_name, f.type_name, f.field_name, p.position
  FROM graphitron_connection c
  JOIN graphitron_connection_position pp ON pp.position = 'PAGE_INFO'
  JOIN graphitron_field pf
    ON pf.graph_name = c.graph_name AND pf.type_name = c.type_name AND pf.field_name = pp.field_name
  JOIN graphitron_field f ON f.graph_name = pf.graph_name AND f.type_name = pf.named_type
  JOIN graphitron_connection_position p ON p.role = 'PAGE_INFO' AND p.field_name = f.field_name;
COMMENT ON VIEW graphitron_field_position_rule IS 'One row the field position rule computes, in the shape graphitron_field_position stores: the rule itself, evaluated on demand rather than read off disk. For example the macro-expansion stage inserts this view''s rows for one graph into graphitron_field_position, which is the name every reader spells.';
-- COMMENT ON COLUMN graphitron_field_position_rule.graph_name IS 'the owning graph''s partition';
-- COMMENT ON COLUMN graphitron_field_position_rule.type_name IS 'the connection, edge or page info type';
-- COMMENT ON COLUMN graphitron_field_position_rule.field_name IS 'the field';
-- COMMENT ON COLUMN graphitron_field_position_rule.position IS 'the position it fills';

CREATE VIEW graphitron_field_target_rule
  (graph_name, type_name, field_name, target_type_name, wrapper_type_name) AS
SELECT f.graph_name, f.type_name, f.field_name,
       COALESCE(ed.item_type_name, f.named_type),
       CASE WHEN ed.item_type_name IS NOT NULL THEN f.named_type END
  FROM graphitron_field f
  LEFT JOIN graphitron_connection cn
    ON cn.graph_name = f.graph_name AND cn.type_name = f.named_type
  LEFT JOIN graphitron_edge ed
    ON ed.graph_name = cn.graph_name AND ed.type_name = cn.edge_type_name;
COMMENT ON VIEW graphitron_field_target_rule IS 'One row the field target rule computes, in the shape graphitron_field_target stores: the rule itself, evaluated on demand rather than read off disk. For example a capture inserts this view''s rows for one graph into graphitron_field_target, which is the name every reader spells; naming this relation instead asks for on-demand evaluation and gets it, which is a performance bug rather than a wrong answer.';
-- COMMENT ON COLUMN graphitron_field_target_rule.graph_name IS 'the owning graph''s partition, carried from graphitron_field';
-- COMMENT ON COLUMN graphitron_field_target_rule.type_name IS 'the type owning the field';
-- COMMENT ON COLUMN graphitron_field_target_rule.field_name IS 'the field whose target this row states';
-- COMMENT ON COLUMN graphitron_field_target_rule.target_type_name IS 'the connection''s item where the field''s named type is a connection, and the named type otherwise';
-- COMMENT ON COLUMN graphitron_field_target_rule.wrapper_type_name IS 'the field''s named type where it is a connection, and null otherwise';

-- graphitron_field_target is declared ahead of the connections, so the reference from a wrapper to
-- the connection it names is added here: a field's wrapper is a recognised connection or nothing.
ALTER TABLE graphitron_field_target ADD FOREIGN KEY (graph_name, wrapper_type_name)
  REFERENCES graphitron_connection (graph_name, type_name) ON DELETE CASCADE;

CREATE TABLE graphitron_entry_defect (
  graph_name    VARCHAR NOT NULL,
  source_name   VARCHAR NOT NULL,
  source_line   INT     NOT NULL,
  source_column INT     NOT NULL,
  code          VARCHAR NOT NULL,
  stage         VARCHAR NOT NULL,
  detail        VARCHAR,
  touched_at    TIMESTAMP NOT NULL,
  PRIMARY KEY (graph_name, source_name, source_line, source_column, code, stage),
  FOREIGN KEY (graph_name) REFERENCES store_graph (graph_name),
  -- The written position, so a defect is always somewhere an editor can point, and goes when the
  -- document stops writing it. What the position concerns is not stored beside it:
  -- graphitron_entry_defect_site reaches the element in fixed hops.
  FOREIGN KEY (graph_name, source_name, source_line, source_column)
    REFERENCES graphql_ast_entry (graph_name, source_name, source_line, source_column)
    ON DELETE CASCADE,
  -- The vocabulary, so a code nothing declares is unwritable rather than merely unexpected. The
  -- rule view's arm joined this relation to reach a severity; here it is a constraint as well.
  FOREIGN KEY (code) REFERENCES graphitron_defect_type (code)
);

COMMENT ON TABLE graphitron_entry_defect IS 'A defect a schema has, one row per defect at the written position an author edits to fix it, under the code naming the rule and the stage raising it: the supertype, which a gatherer is encouraged to extend with subtype and detail relations where a defect has more to say than its code and detail. For example an @orderBy on a @routine mutation field draws one row at the @orderBy''s line, reading READ_SURFACE_ON_WRITE; a detail relation such as graphitron_argmapping_pair_defect is keyed by this key, with a foreign key to it ON DELETE CASCADE, so a swept defect takes its details with it.';
COMMENT ON COLUMN graphitron_entry_defect.graph_name IS 'the owning graph''s partition, anchored by store_graph; the leading key dimension that keeps one workspace''s graphs apart';
COMMENT ON COLUMN graphitron_entry_defect.source_name IS 'the file the offending directive was written in, the first of the three columns naming its position';
COMMENT ON COLUMN graphitron_entry_defect.source_line IS 'the offending directive''s source line, 1-based per the graphql-java convention';
COMMENT ON COLUMN graphitron_entry_defect.source_column IS 'the offending directive''s source column; with the two columns above, the entry this defect is about. The key is the entry and not the coordinate, because a coordinate is an aggregate over the sites that declare it and two offending applications at one coordinate are two things to fix';
COMMENT ON COLUMN graphitron_entry_defect.code IS 'which defect, a graphitron_defect_type key and a foreign key into it: one entry may break two rules and then carries two rows, there being no ranking here and nothing to choose between them';
COMMENT ON COLUMN graphitron_entry_defect.stage IS 'the stage that raised it, a meta_stage key, completing the key: a rule two stages raise at one entry is two rows, nobody owning a code, and a stage sweeps the rows it raised';
COMMENT ON COLUMN graphitron_entry_defect.detail IS 'the specific a rendered message quotes back, null where the code says everything';
COMMENT ON COLUMN graphitron_entry_defect.touched_at IS 'when the reading that last found this defect ran: the mark the sweep reads. The stage that raised a row deletes its own rows a reading did not mark, so a defect the schema no longer has goes and another stage''s rows stay';

-- The claims a claim defect is about, one row per claim the rule weighed and found in conflict: the
-- defect names the element, and each claim where it was written.
CREATE TABLE graphitron_entry_defect_claim (
  graph_name    VARCHAR   NOT NULL,
  source_name   VARCHAR   NOT NULL,
  source_line   INT       NOT NULL,
  source_column INT       NOT NULL,
  code          VARCHAR   NOT NULL,
  stage         VARCHAR   NOT NULL,
  coordinate    VARCHAR   NOT NULL,
  kind          VARCHAR   NOT NULL,
  claimer       VARCHAR   NOT NULL,
  touched_at    TIMESTAMP NOT NULL,
  PRIMARY KEY (graph_name, source_name, source_line, source_column, code, stage, coordinate, kind,
               claimer),
  -- The defect it details, so a swept defect takes its claims with it.
  FOREIGN KEY (graph_name, source_name, source_line, source_column, code, stage)
    REFERENCES graphitron_entry_defect (graph_name, source_name, source_line, source_column, code, stage)
    ON DELETE CASCADE,
  -- The claim, so a claim the reading no longer makes is named by nothing.
  FOREIGN KEY (graph_name, coordinate, kind, claimer)
    REFERENCES graphitron_claim (graph_name, coordinate, kind, claimer) ON DELETE CASCADE
);
COMMENT ON TABLE graphitron_entry_defect_claim IS 'One claim a claim defect is about: one row per defect and claim in conflict. For example a field carrying both @service and @mutation draws a CLAIMS_CONFLICT at the field with a SERVICE row and an INSERT row under it, each claim pointing at where it was written.';
COMMENT ON COLUMN graphitron_entry_defect_claim.graph_name IS 'the owning graph''s partition, carried from the defect';
COMMENT ON COLUMN graphitron_entry_defect_claim.source_name IS 'the defect''s file';
COMMENT ON COLUMN graphitron_entry_defect_claim.source_line IS 'the defect''s line, 1-based';
COMMENT ON COLUMN graphitron_entry_defect_claim.source_column IS 'the defect''s column, 1-based';
COMMENT ON COLUMN graphitron_entry_defect_claim.code IS 'the defect''s code, CLAIMS_CONFLICT or ROUTINE_LOOKUP_DEFERRED; with the four columns before it, the defect''s key';
COMMENT ON COLUMN graphitron_entry_defect_claim.stage IS 'the stage that raised the defect it details, which wrote this row and sweeps it; with the defect''s other key columns, the defect';
COMMENT ON COLUMN graphitron_entry_defect_claim.coordinate IS 'the element the claim is for, the one the defect sits at';
COMMENT ON COLUMN graphitron_entry_defect_claim.kind IS 'the claim''s kind';
COMMENT ON COLUMN graphitron_entry_defect_claim.claimer IS 'the element that makes the claim; with the two columns before it, the claim''s key';
COMMENT ON COLUMN graphitron_entry_defect_claim.touched_at IS 'when the reading that last stated this row ran: the mark the sweep reads';

-- The members a polymorphic @nodeId's defect names, under it: one defect per defect, its members a
-- relation beneath it.
CREATE TABLE graphitron_entry_defect_member (
  graph_name       VARCHAR   NOT NULL,
  source_name      VARCHAR   NOT NULL,
  source_line      INT       NOT NULL,
  source_column    INT       NOT NULL,
  code             VARCHAR   NOT NULL,
  stage            VARCHAR   NOT NULL,
  member_type_name VARCHAR   NOT NULL,
  touched_at       TIMESTAMP NOT NULL,
  PRIMARY KEY (graph_name, source_name, source_line, source_column, code, stage, member_type_name),
  -- The defect it details, so a swept defect takes its members with it.
  FOREIGN KEY (graph_name, source_name, source_line, source_column, code, stage)
    REFERENCES graphitron_entry_defect (graph_name, source_name, source_line, source_column, code, stage)
    ON DELETE CASCADE
);
COMMENT ON TABLE graphitron_entry_defect_member IS 'One member a polymorphic @nodeId''s defect names: one row per defect and member. For example a union of Film and Actor whose @nodeId lands on a parameter taking FilmRecord draws a NODE_ID_SLOT_NOT_SUPERTYPE_OF_MEMBER defect with an Actor row under it.';
COMMENT ON COLUMN graphitron_entry_defect_member.graph_name IS 'the owning graph''s partition, carried from the defect';
COMMENT ON COLUMN graphitron_entry_defect_member.source_name IS 'the defect''s file';
COMMENT ON COLUMN graphitron_entry_defect_member.source_line IS 'the defect''s line, 1-based';
COMMENT ON COLUMN graphitron_entry_defect_member.source_column IS 'the defect''s column, 1-based';
COMMENT ON COLUMN graphitron_entry_defect_member.code IS 'the defect''s code, NODE_ID_MEMBER_NOT_NODE_TYPE, NODE_ID_SLOT_NOT_SUPERTYPE_OF_MEMBER, DISCRIMINATOR_MISSING or TABLE_INTERFACE_PARTICIPANT_UNBOUND; with the four columns before it, the defect''s key';
COMMENT ON COLUMN graphitron_entry_defect_member.stage IS 'the stage that raised the defect it details, which wrote this row and sweeps it; with the defect''s other key columns, the defect';
COMMENT ON COLUMN graphitron_entry_defect_member.member_type_name IS 'the member the defect names';
COMMENT ON COLUMN graphitron_entry_defect_member.touched_at IS 'when the reading that last stated this row ran: the mark the sweep reads';

CREATE TABLE graphitron_entry_defect_table (
  graph_name        VARCHAR   NOT NULL,
  source_name       VARCHAR   NOT NULL,
  source_line       INT       NOT NULL,
  source_column     INT       NOT NULL,
  code              VARCHAR   NOT NULL,
  stage             VARCHAR   NOT NULL,
  table_source_name VARCHAR   NOT NULL,
  table_schema      VARCHAR   NOT NULL,
  table_name        VARCHAR   NOT NULL,
  touched_at        TIMESTAMP NOT NULL,
  PRIMARY KEY (graph_name, source_name, source_line, source_column, code, stage,
               table_source_name, table_schema, table_name),
  -- The defect it details, so a swept defect takes its tables with it.
  FOREIGN KEY (graph_name, source_name, source_line, source_column, code, stage)
    REFERENCES graphitron_entry_defect (graph_name, source_name, source_line, source_column, code, stage)
    ON DELETE CASCADE,
  -- The table, so a table the catalog no longer has is named by nothing.
  FOREIGN KEY (table_source_name, table_schema, table_name)
    REFERENCES sql_table (source_name, table_schema, table_name)
    ON DELETE CASCADE
);
COMMENT ON TABLE graphitron_entry_defect_table IS 'One table a defect names: one row per defect and candidate table. For example @table(name: "note") where multischema_a and multischema_b both declare note draws a TABLE_AMBIGUOUS defect with a row for each.';
COMMENT ON COLUMN graphitron_entry_defect_table.graph_name IS 'the owning graph''s partition, carried from the defect';
COMMENT ON COLUMN graphitron_entry_defect_table.source_name IS 'the defect''s file';
COMMENT ON COLUMN graphitron_entry_defect_table.source_line IS 'the defect''s line, 1-based';
COMMENT ON COLUMN graphitron_entry_defect_table.source_column IS 'the defect''s column, 1-based';
COMMENT ON COLUMN graphitron_entry_defect_table.code IS 'the defect''s code, TABLE_AMBIGUOUS';
COMMENT ON COLUMN graphitron_entry_defect_table.stage IS 'the stage that raised the defect it details, which wrote this row and sweeps it; with the defect''s other key columns, the defect';
COMMENT ON COLUMN graphitron_entry_defect_table.table_source_name IS 'the catalog source of a table the defect names';
COMMENT ON COLUMN graphitron_entry_defect_table.table_schema IS 'that table''s schema';
COMMENT ON COLUMN graphitron_entry_defect_table.table_name IS 'that table''s name';
COMMENT ON COLUMN graphitron_entry_defect_table.touched_at IS 'when the reading that last stated this row ran: the mark the sweep reads';

-- The @routine a field's written path steps through, under a claim defect it is in: a path step and
-- no claim, so it has a detail of its own.
CREATE TABLE graphitron_entry_defect_path_step (
  graph_name         VARCHAR   NOT NULL,
  source_name        VARCHAR   NOT NULL,
  source_line        INT       NOT NULL,
  source_column      INT       NOT NULL,
  code               VARCHAR   NOT NULL,
  stage              VARCHAR   NOT NULL,
  step_source_name   VARCHAR   NOT NULL,
  step_source_line   INT       NOT NULL,
  step_source_column INT       NOT NULL,
  touched_at         TIMESTAMP NOT NULL,
  PRIMARY KEY (graph_name, source_name, source_line, source_column, code, stage, step_source_name,
               step_source_line, step_source_column),
  -- The defect it details, so a swept defect takes its steps with it.
  FOREIGN KEY (graph_name, source_name, source_line, source_column, code, stage)
    REFERENCES graphitron_entry_defect (graph_name, source_name, source_line, source_column, code, stage)
    ON DELETE CASCADE,
  -- The step's written @routine, so one the document stops writing is named by nothing.
  FOREIGN KEY (graph_name, step_source_name, step_source_line, step_source_column)
    REFERENCES graphql_ast_entry (graph_name, source_name, source_line, source_column)
    ON DELETE CASCADE
);
COMMENT ON TABLE graphitron_entry_defect_path_step IS 'One @routine a field''s written path steps through, under the claim defect it conflicts in: one row per defect and step. For example a field carrying @service and a @routine below a root without @splitQuery draws a CLAIMS_CONFLICT with a SERVICE claim and this row for the routine.';
COMMENT ON COLUMN graphitron_entry_defect_path_step.graph_name IS 'the owning graph''s partition, carried from the defect';
COMMENT ON COLUMN graphitron_entry_defect_path_step.source_name IS 'the defect''s file';
COMMENT ON COLUMN graphitron_entry_defect_path_step.source_line IS 'the defect''s line, 1-based';
COMMENT ON COLUMN graphitron_entry_defect_path_step.source_column IS 'the defect''s column, 1-based';
COMMENT ON COLUMN graphitron_entry_defect_path_step.code IS 'the defect''s code, CLAIMS_CONFLICT; with the four columns before it, the defect''s key';
COMMENT ON COLUMN graphitron_entry_defect_path_step.stage IS 'the stage that raised the defect it details, which wrote this row and sweeps it; with the defect''s other key columns, the defect';
COMMENT ON COLUMN graphitron_entry_defect_path_step.step_source_name IS 'the file the @routine is written in';
COMMENT ON COLUMN graphitron_entry_defect_path_step.step_source_line IS 'the @routine''s line, 1-based';
COMMENT ON COLUMN graphitron_entry_defect_path_step.step_source_column IS 'the @routine''s column, 1-based';
COMMENT ON COLUMN graphitron_entry_defect_path_step.touched_at IS 'when the reading that last stated this row ran: the mark the sweep reads';

CREATE VIEW graphitron_entry_defect_site
  (graph_name, source_name, source_line, source_column, code, detail,
   coordinate, type_name, field_name) AS
-- The element a defect's position is about, in fixed hops: a declaration is its own element, a
-- directive application's element is its parent, an applied argument's is its application's, and
-- a value's is reached through the node holding it. A holder is an applied argument when the value
-- was written inside a directive, and otherwise the declaration carrying it as a default.
SELECT d.graph_name, d.source_name, d.source_line, d.source_column, d.code, d.detail,
       el.coordinate,
       CASE WHEN ef.coordinate IS NULL THEN el.coordinate ELSE ef.type_name END,
       ef.field_name
  -- One finding per position and code however many stages raised it, two stages raising one rule
  -- wording it alike, so the stage is all that is collapsed.
  FROM (SELECT DISTINCT graph_name, source_name, source_line, source_column, code, detail
          FROM graphitron_entry_defect) d
  JOIN graphql_ast_entry n
    ON n.graph_name = d.graph_name AND n.source_name = d.source_name
   AND n.source_line = d.source_line AND n.source_column = d.source_column
  LEFT JOIN graphql_ast_value_entry v
    ON v.graph_name = d.graph_name AND v.source_name = d.source_name
   AND v.source_line = d.source_line AND v.source_column = d.source_column
  LEFT JOIN graphql_ast_entry h
    ON h.graph_name = v.graph_name AND h.source_name = v.source_name
   AND h.source_line = v.holder_line AND h.source_column = v.holder_column
  -- The application, where the position is one or sits inside one.
  LEFT JOIN graphql_ast_entry a
    ON a.graph_name = n.graph_name AND a.source_name = n.source_name
   AND a.source_line = CASE
         WHEN h.entry_kind = 'APPLIED_ARGUMENT' THEN h.parent_line
         WHEN n.entry_kind = 'APPLIED_ARGUMENT' THEN n.parent_line
         WHEN n.entry_kind IN ('TYPE_DIRECTIVE', 'FIELD_DIRECTIVE', 'INPUT_VALUE_DIRECTIVE',
                               'ENUM_VALUE_DIRECTIVE', 'SCHEMA_DIRECTIVE') THEN n.source_line END
   AND a.source_column = CASE
         WHEN h.entry_kind = 'APPLIED_ARGUMENT' THEN h.parent_column
         WHEN n.entry_kind = 'APPLIED_ARGUMENT' THEN n.parent_column
         WHEN n.entry_kind IN ('TYPE_DIRECTIVE', 'FIELD_DIRECTIVE', 'INPUT_VALUE_DIRECTIVE',
                               'ENUM_VALUE_DIRECTIVE', 'SCHEMA_DIRECTIVE') THEN n.source_column END
  LEFT JOIN graphql_ast_element_entry el
    ON el.graph_name = n.graph_name AND el.source_name = n.source_name
   AND el.source_line = COALESCE(a.parent_line, h.source_line, n.source_line)
   AND el.source_column = COALESCE(a.parent_column, h.source_column, n.source_column)
  LEFT JOIN graphql_element_field ef
    ON ef.graph_name = el.graph_name AND ef.coordinate = el.coordinate;
COMMENT ON VIEW graphitron_entry_defect_site IS 'One finding an author reads, with the element its position is about: one row per position and code over the stages that raised it, and the coordinate, type and field an editor or a report names it by. For example a READ_SURFACE_ON_WRITE row at the @orderBy written on Mutation.rentFilm reads Mutation.rentFilm, Mutation and rentFilm here.';
-- COMMENT ON COLUMN graphitron_entry_defect_site.graph_name IS 'the owning graph''s partition, carried from the defect';
-- COMMENT ON COLUMN graphitron_entry_defect_site.source_name IS 'the file of the defect''s written position, carried from the defect';
-- COMMENT ON COLUMN graphitron_entry_defect_site.source_line IS 'the line of that position, carried from the defect';
-- COMMENT ON COLUMN graphitron_entry_defect_site.source_column IS 'the column of that position, carried from the defect; with the code, the defect''s own key';
-- COMMENT ON COLUMN graphitron_entry_defect_site.code IS 'which rule, carried from the defect';
-- COMMENT ON COLUMN graphitron_entry_defect_site.detail IS 'the specific a rendered message quotes back, carried from the defect';
-- COMMENT ON COLUMN graphitron_entry_defect_site.coordinate IS 'the element the position is about, as graphql_ast_element_entry spells it: a type, a field, an argument or an input field, or $schema for the schema block';
-- COMMENT ON COLUMN graphitron_entry_defect_site.type_name IS 'the type owning that element, or the element itself where it is a type';
-- COMMENT ON COLUMN graphitron_entry_defect_site.field_name IS 'the field that element is or belongs to, NULL where it is a type';

-- Where an occurrence chain starts: a field of an object type that is a root, is table-bound or is
-- targeted by no output field, a connection type being targeted by the field that returns it, and a
-- field of an interface with a table of its own. A field of a
-- multi-table interface is reached through its participants' own fields, and an input field only
-- under an argument.
CREATE VIEW graphitron_occurrence_start_rule
  (graph_name, coordinate, element_coordinate, name, kind) AS
SELECT f.graph_name, f.coordinate, f.coordinate, f.field_name, 'FIELD'
  FROM graphitron_field f
  JOIN graphitron_type t ON t.graph_name = f.graph_name AND t.type_name = f.type_name
 WHERE (t.kind = 'OBJECT'
        AND (EXISTS (SELECT 1 FROM graphitron_tabletype b
                      WHERE b.graph_name = t.graph_name AND b.type_name = t.type_name)
             OR (NOT EXISTS (SELECT 1 FROM graphitron_field_target ft
                               JOIN graphitron_type o
                                 ON o.graph_name = ft.graph_name AND o.type_name = ft.type_name
                                AND o.kind IN ('OBJECT', 'INTERFACE')
                              WHERE ft.graph_name = t.graph_name
                                AND ft.target_type_name = t.type_name)
                 AND NOT EXISTS (SELECT 1 FROM graphitron_field_target ft
                                   JOIN graphitron_type o
                                     ON o.graph_name = ft.graph_name AND o.type_name = ft.type_name
                                    AND o.kind IN ('OBJECT', 'INTERFACE')
                                  WHERE ft.graph_name = t.graph_name
                                    AND ft.wrapper_type_name = t.type_name))))
    OR (t.kind = 'INTERFACE'
        AND EXISTS (SELECT 1 FROM graphitron_tabletype b
                     WHERE b.graph_name = t.graph_name AND b.type_name = t.type_name));
COMMENT ON VIEW graphitron_occurrence_start_rule IS 'One occurrence a chain starts at, in the shape graphitron_occurrence stores at depth 0: the rule itself, evaluated on demand rather than read off disk. For example Film.title on the table-bound Film, and Mutation.createFilm on the root.';
-- COMMENT ON COLUMN graphitron_occurrence_start_rule.graph_name IS 'the owning graph''s partition';
-- COMMENT ON COLUMN graphitron_occurrence_start_rule.coordinate IS 'the field''s own Type.field';
-- COMMENT ON COLUMN graphitron_occurrence_start_rule.element_coordinate IS 'the same, the field being its own element';
-- COMMENT ON COLUMN graphitron_occurrence_start_rule.name IS 'the field name';
-- COMMENT ON COLUMN graphitron_occurrence_start_rule.kind IS 'always FIELD';

-- One step down from an occurrence this reading has written: into the fields of the object type with
-- no table a field targets, the connection type for a field returning one rather than the element
-- the target names, onto a field's arguments, and into the fields of the input type an argument
-- or an input field is, spelled inside the argument's parentheses, so Type.field.x is only ever a
-- nested output field. The chain grows only through a nested field, so a target with a table, an
-- interface or a union ends it, its participants' fields starting their own. The writer adds the
-- first-visit guard, which needs the types already on the chain and so a walk up it.
CREATE VIEW graphitron_occurrence_step_rule
  (graph_name, parent_coordinate, parent_depth, coordinate, element_coordinate, name, kind,
   entered_type_name) AS
WITH parent (graph_name, coordinate, element_coordinate, kind, depth) AS (
  SELECT o.graph_name, o.coordinate, o.element_coordinate, o.kind, o.depth
    FROM graphitron_occurrence o
    JOIN store_graph g ON g.graph_name = o.graph_name AND g.last_captured = o.touched_at
)
SELECT p.graph_name, p.coordinate, p.depth, p.coordinate || '.' || c.field_name, c.coordinate,
       c.field_name, 'FIELD', t.type_name
  FROM parent p
  JOIN graphitron_field f ON f.graph_name = p.graph_name AND f.coordinate = p.element_coordinate
  JOIN graphitron_field_target ft
    ON ft.graph_name = f.graph_name AND ft.type_name = f.type_name AND ft.field_name = f.field_name
  JOIN graphitron_type t
    ON t.graph_name = ft.graph_name
   AND t.type_name = COALESCE(ft.wrapper_type_name, ft.target_type_name) AND t.kind = 'OBJECT'
  JOIN graphitron_field c ON c.graph_name = t.graph_name AND c.type_name = t.type_name
 WHERE p.kind = 'FIELD'
   AND NOT EXISTS (SELECT 1 FROM graphitron_tabletype b
                    WHERE b.graph_name = t.graph_name AND b.type_name = t.type_name)
UNION ALL
SELECT p.graph_name, p.coordinate, p.depth, p.coordinate || '(' || a.argument_name || ':)',
       a.coordinate, a.argument_name, 'FIELD_ARGUMENT', CAST(NULL AS VARCHAR)
  FROM parent p
  JOIN graphitron_field f ON f.graph_name = p.graph_name AND f.coordinate = p.element_coordinate
  JOIN graphitron_argument a
    ON a.graph_name = f.graph_name AND a.type_name = f.type_name AND a.field_name = f.field_name
 WHERE p.kind = 'FIELD'
UNION ALL
SELECT p.graph_name, p.coordinate, p.depth,
       LEFT(p.coordinate, CHAR_LENGTH(p.coordinate) - 2) || '.' || c.field_name || ':)', c.coordinate,
       c.field_name, 'INPUT_FIELD', t.type_name
  FROM parent p
  JOIN graphitron_argument a ON a.graph_name = p.graph_name AND a.coordinate = p.element_coordinate
  JOIN graphitron_type t
    ON t.graph_name = a.graph_name AND t.type_name = a.named_type AND t.kind = 'INPUT_OBJECT'
  JOIN graphitron_field c ON c.graph_name = t.graph_name AND c.type_name = t.type_name
 WHERE p.kind = 'FIELD_ARGUMENT'
UNION ALL
SELECT p.graph_name, p.coordinate, p.depth,
       LEFT(p.coordinate, CHAR_LENGTH(p.coordinate) - 2) || '.' || c.field_name || ':)', c.coordinate,
       c.field_name, 'INPUT_FIELD', t.type_name
  FROM parent p
  JOIN graphitron_field f ON f.graph_name = p.graph_name AND f.coordinate = p.element_coordinate
  JOIN graphitron_type t
    ON t.graph_name = f.graph_name AND t.type_name = f.named_type AND t.kind = 'INPUT_OBJECT'
  JOIN graphitron_field c ON c.graph_name = t.graph_name AND c.type_name = t.type_name
 WHERE p.kind = 'INPUT_FIELD';
COMMENT ON VIEW graphitron_occurrence_step_rule IS 'One occurrence one step below an occurrence this reading wrote, before the first-visit guard: the rule the writer applies a depth at a time. For example Emne.navn.en under Emne.navn, Query.films(filter:) under Query.films, and Query.films(filter.cast:) under Query.films(filter:).';
-- COMMENT ON COLUMN graphitron_occurrence_step_rule.graph_name IS 'the owning graph''s partition';
-- COMMENT ON COLUMN graphitron_occurrence_step_rule.parent_coordinate IS 'the occurrence stepped down from';
-- COMMENT ON COLUMN graphitron_occurrence_step_rule.parent_depth IS 'its depth, which the writer''s pass selects on';
-- COMMENT ON COLUMN graphitron_occurrence_step_rule.coordinate IS 'the child''s coordinate';
-- COMMENT ON COLUMN graphitron_occurrence_step_rule.element_coordinate IS 'the child''s declared element';
-- COMMENT ON COLUMN graphitron_occurrence_step_rule.name IS 'the child''s name at this step';
-- COMMENT ON COLUMN graphitron_occurrence_step_rule.kind IS 'FIELD, INPUT_FIELD or FIELD_ARGUMENT';
-- COMMENT ON COLUMN graphitron_occurrence_step_rule.entered_type_name IS 'the type whose fields the step enters, which the first-visit guard tests against the chain; null for an argument, which enters none';

CREATE VIEW intent_resolved_node_key_shape
  (graph_name, type_name, arity, record_class, sole_column_name, sole_column_java_type) AS
SELECT DISTINCT k.graph_name, k.type_name, k.arity, t.record_class_fqn,
       CASE WHEN k.arity = 1 THEN k.column_name END,
       CASE WHEN k.arity = 1 THEN c.binding_type END
  FROM (SELECT graph_name, type_name, column_name,
               table_source_name, table_schema, table_name,
               CAST(COUNT(*) OVER (PARTITION BY graph_name, type_name) AS INT) AS arity
          FROM graphitron_node_keycolumn) k
  LEFT JOIN sql_table t
    ON t.source_name = k.table_source_name AND t.table_schema = k.table_schema
   AND t.table_name = k.table_name
   AND t.record_class_fqn <> 'org.jooq.Record'
  JOIN sql_column c
    ON c.source_name = k.table_source_name AND c.table_schema = k.table_schema
   AND c.table_name = k.table_name AND c.column_name = k.column_name;
COMMENT ON VIEW intent_resolved_node_key_shape IS 'Deprecated with the whole intent_ family, which has no owning gatherer and is being retired. A fact derived here belongs in the family that owns the corpus it comes from, captured as early as it can be so that every reader reaches it instead of deriving it again. A node type''s key reduced to what a slot receiving it has to agree with: how many columns the key has, the row type that carries the whole tuple, and where the key is one column that column''s name and the Java type it binds as. The relation a destination or a refusal reads when the question is not which columns the key is but whether a given slot can hold it. Every value here is a function of the key-column relation beside it and the type''s own table binding, so this states no new fact and exists for one reason: three consumers would otherwise each aggregate the key list and each re-resolve the binding, which is the inline multiplicity the fact model''s own measurements warn about, and a reader that wants the columns themselves still reads the relation this reduces. Arity is a count over the winning tier''s whole list, which is sound only because that relation picks a tier rather than a position; a per-position pick would make this number the count of a spliced list. It is counted before the two catalog reaches below it rather than after, which is not a stylistic ordering: either outer join can in principle match a key column twice, two catalog columns folding to one name being the case, and a count taken after that would report a key longer than the key is. The record class is the generated row type of the type''s own table, absent where the binding is ambiguous, where no table binds at all, and where the catalog answers org.jooq.Record, which sql_table''s own comment says is the catalog reporting no generated record rather than a record named that; the exclusion is a join predicate here so that absence is one thing at every reader instead of two. The two sole_ columns are stated only at arity one and are NULL above it, which is determined by the arity beside them rather than by anything unknown: a composite key has no single column, so a NULL here at arity two is the key''s shape and not a missing reading. Their absence at arity one is the ordinary catalog absence: a pinned key column resolves with no table at all, on the key-column relation''s own rule, so a name that names nothing the table has still has a row there and reaches no type here. A reader gating on type agreement therefore stands aside on the NULL rather than refusing, which is the discipline intent_resolved_node_key_projection already states for its own version of this operand.';
-- COMMENT ON COLUMN intent_resolved_node_key_shape.graph_name IS 'the owning graph''s partition, carried from the key-column relation';
-- COMMENT ON COLUMN intent_resolved_node_key_shape.type_name IS 'the graph type whose node key this row describes; one row per type that resolved any key column at all, and no row for a type that resolved none';
-- COMMENT ON COLUMN intent_resolved_node_key_shape.arity IS 'how many columns the winning tier''s key list has, one or more. The number a refusal at a single-valued slot quotes, and the number that decides whether such a slot can carry the decode at all';
-- COMMENT ON COLUMN intent_resolved_node_key_shape.record_class IS 'the fully qualified name of the generated jOOQ record for the type''s own table, which is the row type that can hold the whole key tuple whatever its arity. NULL where the type''s table binding is ambiguous or absent, and NULL where jOOQ generated no record class for the bound table. Spelled as the reading spells a class name, so a parameter''s declared type compares to it exactly; the reading never scanned the generated package, so a name here is no promise that code_class holds the class, on graphitron_type_backing.class_name''s terms';
-- COMMENT ON COLUMN intent_resolved_node_key_shape.sole_column_name IS 'at arity one, that column''s name as the winning tier spells it, carried so a message about a single-valued slot need not re-join the key list; NULL at any higher arity, where there is no single column to name';
-- COMMENT ON COLUMN intent_resolved_node_key_shape.sole_column_java_type IS 'at arity one, the Java type jOOQ binds that column as, from sql_column.binding_type: the value a single-valued slot would receive, and the left operand of the agreement such a slot requires. NULL at any higher arity by the shape of the key, and NULL at arity one where the catalog cannot answer, which is an ambiguous or absent table binding or a pinned column name the bound table does not have. A reader cannot tell those two apart from this column alone and does not need to: it reads the arity beside it first, and above one the agreement is not the question';

-- Which result a type holds and what it is a result of. A producer produces a result and a reader
-- reads from one, handing its target what it read, so a result flows down from its producer through
-- readers to every type it reaches. Its shape says how a field of the type is fetched: a ROW is a row
-- of a statement graphitron runs, which the field's read is projected into, and an OBJECT is a value
-- in memory, read through an accessor. One shape per type is the rule; a type holding both is the
-- defect.
CREATE TABLE graphitron_result (
  graph_name VARCHAR   NOT NULL,
  type_name  VARCHAR   NOT NULL,
  shape      VARCHAR   NOT NULL,
  touched_at TIMESTAMP NOT NULL,
  PRIMARY KEY (graph_name, type_name, shape),
  FOREIGN KEY (graph_name, type_name)
    REFERENCES graphitron_type (graph_name, type_name) ON DELETE CASCADE,
  CHECK (shape IN ('ROW', 'OBJECT'))
);
COMMENT ON TABLE graphitron_result IS 'A type holds a result of this shape: one row per type and shape. For example Film @table(name: "film") holds a ROW, a directiveless type nested under one of its fields holds a ROW of film too, and the connection a paginated field returns holds an OBJECT its edges, nodes and page info read.';
COMMENT ON COLUMN graphitron_result.graph_name IS 'the owning graph''s partition';
COMMENT ON COLUMN graphitron_result.type_name IS 'the object type holding the result';
COMMENT ON COLUMN graphitron_result.shape IS 'ROW, a row of a statement graphitron runs, which a field''s read is projected into; or OBJECT, a value handed over, which a field reads through an accessor. Who built the value, the author''s class or graphitron''s carrier, is the producer''s fact and not the shape''s, and how an accessor reads it, the Record API for a jOOQ record or a getter, is graphitron_result_class''s. A table''s own record a service hands back is an OBJECT: nothing selected it, and a field moving from it back into the tables refetches';
COMMENT ON COLUMN graphitron_result.touched_at IS 'the reading that last wrote this row; the sweep deletes the rows an older reading wrote';

CREATE TABLE graphitron_result_table (
  graph_name        VARCHAR   NOT NULL,
  type_name         VARCHAR   NOT NULL,
  shape             VARCHAR   NOT NULL,
  table_source_name VARCHAR   NOT NULL,
  table_schema      VARCHAR   NOT NULL,
  table_name        VARCHAR   NOT NULL,
  touched_at        TIMESTAMP NOT NULL,
  PRIMARY KEY (graph_name, type_name, table_source_name, table_schema, table_name),
  FOREIGN KEY (graph_name, type_name, shape)
    REFERENCES graphitron_result (graph_name, type_name, shape) ON DELETE CASCADE,
  FOREIGN KEY (table_source_name, table_schema, table_name)
    REFERENCES sql_table (source_name, table_schema, table_name) ON DELETE CASCADE,
  CHECK (shape = 'ROW')
);
COMMENT ON TABLE graphitron_result_table IS 'A ROW a type holds is a row of this table: one row per type and table. For example a type nested under Film.details holds film''s rows, and a type nested under two tables'' fields holds both.';
COMMENT ON COLUMN graphitron_result_table.graph_name IS 'the owning graph''s partition';
COMMENT ON COLUMN graphitron_result_table.type_name IS 'the type holding the row';
COMMENT ON COLUMN graphitron_result_table.shape IS 'always ROW, pinned so the foreign key holds the type to a row result';
COMMENT ON COLUMN graphitron_result_table.table_source_name IS 'the catalog the table is read from; with the schema and the name, an sql_table key';
COMMENT ON COLUMN graphitron_result_table.table_schema IS 'the table''s schema';
COMMENT ON COLUMN graphitron_result_table.table_name IS 'the table whose row it is: the type''s own binding, or, for a type with none, the table of the row it is nested in';
COMMENT ON COLUMN graphitron_result_table.touched_at IS 'the reading that last wrote this row; the sweep deletes the rows an older reading wrote';

CREATE TABLE graphitron_result_pivot (
  graph_name       VARCHAR   NOT NULL,
  type_name        VARCHAR   NOT NULL,
  shape            VARCHAR   NOT NULL,
  pivot_type_name  VARCHAR   NOT NULL,
  pivot_field_name VARCHAR   NOT NULL,
  touched_at       TIMESTAMP NOT NULL,
  PRIMARY KEY (graph_name, type_name, pivot_type_name, pivot_field_name),
  FOREIGN KEY (graph_name, type_name, shape)
    REFERENCES graphitron_result (graph_name, type_name, shape) ON DELETE CASCADE,
  FOREIGN KEY (graph_name, pivot_type_name, pivot_field_name)
    REFERENCES graphitron_field (graph_name, type_name, field_name) ON DELETE CASCADE,
  CHECK (shape = 'ROW')
);
COMMENT ON TABLE graphitron_result_pivot IS 'A ROW a type holds is the row a @pivot field''s aggregate makes: one row per type and pivot field. For example Film.translations @pivot(on: "lang_code", value: "title_txt") makes Translations a row with one column per slot.';
COMMENT ON COLUMN graphitron_result_pivot.graph_name IS 'the owning graph''s partition';
COMMENT ON COLUMN graphitron_result_pivot.type_name IS 'the type holding the row, the pivot field''s own type';
COMMENT ON COLUMN graphitron_result_pivot.shape IS 'always ROW, pinned so the foreign key holds the type to a row result';
COMMENT ON COLUMN graphitron_result_pivot.pivot_type_name IS 'the type declaring the @pivot field';
COMMENT ON COLUMN graphitron_result_pivot.pivot_field_name IS 'the @pivot field whose aggregate makes the row; each slot reads one of its columns';
COMMENT ON COLUMN graphitron_result_pivot.touched_at IS 'the reading that last wrote this row; the sweep deletes the rows an older reading wrote';

CREATE TABLE graphitron_result_class (
  graph_name VARCHAR   NOT NULL,
  type_name  VARCHAR   NOT NULL,
  shape      VARCHAR   NOT NULL,
  class_name VARCHAR   NOT NULL,
  touched_at TIMESTAMP NOT NULL,
  PRIMARY KEY (graph_name, type_name, class_name),
  FOREIGN KEY (graph_name, type_name, shape)
    REFERENCES graphitron_result (graph_name, type_name, shape) ON DELETE CASCADE,
  CHECK (shape = 'OBJECT')
);
COMMENT ON TABLE graphitron_result_class IS 'An OBJECT a type holds is an instance of this class: one row per type and class. For example a type a @service returns its own record for holds that record, and a carrier graphitron builds, a connection or a write''s payload, has no row.';
COMMENT ON COLUMN graphitron_result_class.graph_name IS 'the owning graph''s partition';
COMMENT ON COLUMN graphitron_result_class.type_name IS 'the type holding the object';
COMMENT ON COLUMN graphitron_result_class.shape IS 'always OBJECT, pinned so the foreign key holds the type to an object result';
COMMENT ON COLUMN graphitron_result_class.class_name IS 'the class, as graphitron_type_backing names it from what a producer returns or a member delivers';
COMMENT ON COLUMN graphitron_result_class.touched_at IS 'the reading that last wrote this row; the sweep deletes the rows an older reading wrote';

CREATE INDEX graphql_ast_field_definition_entry_coordinate_ix
  ON graphql_ast_field_definition_entry (graph_name, type_name, name);
COMMENT ON INDEX graphql_ast_field_definition_entry_coordinate_ix IS 'The coordinate side''s probe: graphitron_entry_defect_rule reaches a producing field''s definition site from its type and name, where the primary key leads with the site.';
CREATE INDEX graphql_ast_input_field_entry_coordinate_ix
  ON graphql_ast_input_field_entry (graph_name, type_name, name);
COMMENT ON INDEX graphql_ast_input_field_entry_coordinate_ix IS 'The coordinate side''s probe: graphitron_occurrence_binding_entry_defect_rule reaches an input field''s declaration from its type and name, where the primary key leads with the site.';

-- How a field reads the result its parent holds: under a ROW, a column of it, an expression
-- projected into it, or a row nested in it; under an OBJECT, an accessor. A field that is a
-- producer, or claims a kind it is no producer of, is not here.
CREATE TABLE graphitron_reader (
  graph_name VARCHAR   NOT NULL,
  type_name  VARCHAR   NOT NULL,
  field_name VARCHAR   NOT NULL,
  side       VARCHAR   NOT NULL,
  reads      VARCHAR   NOT NULL,
  touched_at TIMESTAMP NOT NULL,
  PRIMARY KEY (graph_name, type_name, field_name),
  FOREIGN KEY (graph_name, type_name, field_name, side)
    REFERENCES graphitron_fetcher (graph_name, type_name, field_name, side) ON DELETE CASCADE,
  CHECK (side = 'READER'),
  CHECK (reads IN ('COLUMN', 'EXPRESSION', 'NESTED', 'ACCESSOR'))
);
COMMENT ON TABLE graphitron_reader IS 'A field whose fetcher reads from the result its parent holds, and how: one row per field. For example Film.title reads a COLUMN of film''s row, and a connection''s edges reads its page through an ACCESSOR.';
COMMENT ON COLUMN graphitron_reader.graph_name IS 'the owning graph''s partition';
COMMENT ON COLUMN graphitron_reader.type_name IS 'the object type declaring the field';
COMMENT ON COLUMN graphitron_reader.field_name IS 'the field; with the type, a graphitron_fetcher key';
COMMENT ON COLUMN graphitron_reader.side IS 'always READER, carried so the foreign key into graphitron_fetcher holds the side as well as the field';
COMMENT ON COLUMN graphitron_reader.reads IS 'under a ROW: COLUMN, a column of the row; EXPRESSION, an @externalField projected into its statement; NESTED, a row nested in it, for an object target. Under an OBJECT: ACCESSOR, an outcome''s errors field among them, its type being a value its producer hands back. A node id''s encoding and an outcome are facts of the field and of the producer, graphitron_producer_outcome, not ways of reading';
COMMENT ON COLUMN graphitron_reader.touched_at IS 'the reading that last wrote this row; the sweep deletes the rows an older reading wrote';

CREATE TABLE graphitron_errors_field (
  graph_name     VARCHAR   NOT NULL,
  type_name      VARCHAR   NOT NULL,
  field_name     VARCHAR   NOT NULL,
  container_name VARCHAR   NOT NULL,
  touched_at     TIMESTAMP NOT NULL,
  PRIMARY KEY (graph_name, type_name, field_name),
  FOREIGN KEY (graph_name, type_name, field_name)
    REFERENCES graphitron_field (graph_name, type_name, field_name) ON DELETE CASCADE
);
COMMENT ON TABLE graphitron_errors_field IS 'A field whose value is a list of errors: one row per nullable list of a union or an interface whose every member is @error, or of one @error type itself. For example FilmLookupPayload.errors: [FilmLookupError], the union of FilmLookupNotFound, FilmLookupInvalid and FilmLookupClientFacing.';
COMMENT ON COLUMN graphitron_errors_field.graph_name IS 'the owning graph''s partition';
COMMENT ON COLUMN graphitron_errors_field.type_name IS 'the object type declaring the field';
COMMENT ON COLUMN graphitron_errors_field.field_name IS 'the field; with the type, a graphitron_field key';
COMMENT ON COLUMN graphitron_errors_field.container_name IS 'the type the list holds: a union or interface whose members are the @error types an error is matched to, or the one @error type itself';
COMMENT ON COLUMN graphitron_errors_field.touched_at IS 'the reading that last wrote this row; the sweep deletes the rows an older reading wrote';

CREATE TABLE graphitron_producer_outcome (
  graph_name        VARCHAR   NOT NULL,
  type_name         VARCHAR   NOT NULL,
  field_name        VARCHAR   NOT NULL,
  kind              VARCHAR   NOT NULL,
  outcome_type_name VARCHAR   NOT NULL,
  errors_field_name VARCHAR   NOT NULL,
  touched_at        TIMESTAMP NOT NULL,
  PRIMARY KEY (graph_name, type_name, field_name),
  FOREIGN KEY (graph_name, type_name, field_name, kind)
    REFERENCES graphitron_producer (graph_name, type_name, field_name, kind) ON DELETE CASCADE,
  FOREIGN KEY (graph_name, outcome_type_name, errors_field_name)
    REFERENCES graphitron_errors_field (graph_name, type_name, field_name) ON DELETE CASCADE,
  CHECK (kind IN ('SERVICE', 'INSERT', 'UPDATE', 'DELETE', 'ROUTINE'))
);
COMMENT ON TABLE graphitron_producer_outcome IS 'A producer whose result is an outcome, and the field its errors arrive at: one row per service, write or routine whose target declares exactly one errors field. For example Query.filmLookup @service returning FilmLookupPayload, whose one errors field is errors: [FilmLookupError], catches what the service throws and hands it to errors.';
COMMENT ON COLUMN graphitron_producer_outcome.graph_name IS 'the owning graph''s partition';
COMMENT ON COLUMN graphitron_producer_outcome.type_name IS 'the type declaring the field, a root operation type or any other';
COMMENT ON COLUMN graphitron_producer_outcome.field_name IS 'the field; with the type and the kind, a graphitron_producer key';
COMMENT ON COLUMN graphitron_producer_outcome.kind IS 'the producer''s kind, carried so the foreign key holds the outcome to a producer that can hand one back';
COMMENT ON COLUMN graphitron_producer_outcome.outcome_type_name IS 'the type the field returns, which holds the value on success and the errors on failure';
COMMENT ON COLUMN graphitron_producer_outcome.errors_field_name IS 'the outcome type''s one errors field; with the outcome type, a graphitron_errors_field key';
COMMENT ON COLUMN graphitron_producer_outcome.touched_at IS 'the reading that last wrote this row; the sweep deletes the rows an older reading wrote';

CREATE TABLE graphitron_producer_routine (
  graph_name        VARCHAR   NOT NULL,
  type_name         VARCHAR   NOT NULL,
  field_name        VARCHAR   NOT NULL,
  kind              VARCHAR   NOT NULL,
  source_name       VARCHAR   NOT NULL,
  source_line       INT       NOT NULL,
  source_column     INT       NOT NULL,
  routine_source_name VARCHAR NOT NULL,
  table_schema      VARCHAR   NOT NULL,
  routine_name      VARCHAR   NOT NULL,
  touched_at        TIMESTAMP NOT NULL,
  PRIMARY KEY (graph_name, type_name, field_name),
  FOREIGN KEY (graph_name, type_name, field_name, kind)
    REFERENCES graphitron_producer (graph_name, type_name, field_name, kind) ON DELETE CASCADE,
  FOREIGN KEY (graph_name, source_name, source_line, source_column)
    REFERENCES graphitron_ast_routine_entry (graph_name, source_name, source_line, source_column)
    ON DELETE CASCADE,
  FOREIGN KEY (routine_source_name, table_schema, routine_name)
    REFERENCES sql_routine (source_name, table_schema, routine_name) ON DELETE CASCADE,
  CHECK (kind = 'ROUTINE')
);
COMMENT ON TABLE graphitron_producer_routine IS 'What a routine producer calls: its first @routine application and the database routine that names; one row per routine producer whose routine resolved to one callable. For example Query.filmsForActor @routine(name: "films_for_actor") calls public.films_for_actor.';
COMMENT ON COLUMN graphitron_producer_routine.graph_name IS 'the owning graph''s partition';
COMMENT ON COLUMN graphitron_producer_routine.type_name IS 'the type declaring the field';
COMMENT ON COLUMN graphitron_producer_routine.field_name IS 'the field; with the type and the kind, a graphitron_producer key';
COMMENT ON COLUMN graphitron_producer_routine.kind IS 'always ROUTINE, pinned so the foreign key holds the producer to a routine';
COMMENT ON COLUMN graphitron_producer_routine.source_name IS 'the file the first @routine was written in; with the line and column, its graphitron_ast_routine_entry. The applications after it are elements of the field''s reference path, not producers';
COMMENT ON COLUMN graphitron_producer_routine.source_line IS 'the first @routine''s source line';
COMMENT ON COLUMN graphitron_producer_routine.source_column IS 'the first @routine''s source column';
COMMENT ON COLUMN graphitron_producer_routine.routine_source_name IS 'the catalog the routine is read from; with the schema and the name, an sql_routine key';
COMMENT ON COLUMN graphitron_producer_routine.table_schema IS 'the routine''s schema';
COMMENT ON COLUMN graphitron_producer_routine.routine_name IS 'the routine, the one callable the written name resolves to';
COMMENT ON COLUMN graphitron_producer_routine.touched_at IS 'the reading that last wrote this row; the sweep deletes the rows an older reading wrote';

CREATE TABLE graphitron_join_path_claim (
  graph_name             VARCHAR   NOT NULL,
  element_coordinate     VARCHAR   NOT NULL,
  target_type            VARCHAR   NOT NULL,
  claim_kind            VARCHAR   NOT NULL,
  source_name            VARCHAR   NOT NULL,
  source_line            INT       NOT NULL,
  source_column          INT       NOT NULL,
  first_place            INT       NOT NULL,
  last_place             INT       NOT NULL,
  touched_at             TIMESTAMP NOT NULL,
  element_graph_ref      VARCHAR,
  element_coordinate_ref VARCHAR,
  target_graph_ref       VARCHAR,
  target_type_ref        VARCHAR,
  PRIMARY KEY (graph_name, element_coordinate, target_type),
  FOREIGN KEY (graph_name) REFERENCES store_graph (graph_name),
  -- The declared element and the type it reaches, each through the claim's own copy of the key: a
  -- key to what a claim was built from does not cascade, and the sweep removes the row the
  -- reading no longer finds.
  FOREIGN KEY (element_graph_ref, element_coordinate_ref)
    REFERENCES graphitron_element (graph_name, coordinate) ON DELETE SET NULL,
  FOREIGN KEY (target_graph_ref, target_type_ref)
    REFERENCES graphitron_type (graph_name, type_name) ON DELETE SET NULL,
  CHECK (element_graph_ref IS NULL OR element_graph_ref = graph_name),
  CHECK (element_coordinate_ref IS NULL OR element_coordinate_ref = element_coordinate),
  CHECK (target_graph_ref IS NULL OR target_graph_ref = graph_name),
  CHECK (target_type_ref IS NULL OR target_type_ref = target_type),
  CHECK (claim_kind IN ('FIELD', 'REFERENCE_FOR', 'ARGUMENT', 'INPUT_FIELD')),
  CHECK (first_place IN (0, 1)),
  CHECK (first_place = 0 OR claim_kind = 'FIELD'),
  CHECK (last_place >= 0)
);
COMMENT ON TABLE graphitron_join_path_claim IS 'One place a path is written, by the declared element it is written on and the type it reaches: one row per field declaration writing @routine or @reference, @referenceFor application, argument and input field writing a path. For example Store.people with @referenceFor(type: "Staff") is the claim (Store.people, Staff), of kind REFERENCE_FOR.';
COMMENT ON COLUMN graphitron_join_path_claim.graph_name IS 'the owning graph''s partition, anchored by store_graph';
COMMENT ON COLUMN graphitron_join_path_claim.element_coordinate IS 'the declared field, argument or input field the path is written on, as graphitron_element spells it: Customer.address, Query.people(storeId:), StockFilter.languageId. A declaration and not an occurrence, a path being written once where it is declared; a path in any file follows it by this and the target type';
COMMENT ON COLUMN graphitron_join_path_claim.target_type IS 'the type the path reaches: the member a @referenceFor names, else the type the declaration names, unwrapped from a connection for an output field, a scalar or input type included. With the coordinate the key, so two @referenceFor on one field naming different members are two claims, and the first written of two naming one type is the one kept';
COMMENT ON COLUMN graphitron_join_path_claim.claim_kind IS 'what wrote the path: FIELD, a field declaration''s @routine and @reference applications composed; REFERENCE_FOR, one @referenceFor application; ARGUMENT, an argument; or INPUT_FIELD, an input field, whose written elements become a path per occurrence';
COMMENT ON COLUMN graphitron_join_path_claim.source_name IS 'the file the claim was written in';
COMMENT ON COLUMN graphitron_join_path_claim.source_line IS 'the claim''s source line, 1-based';
COMMENT ON COLUMN graphitron_join_path_claim.source_column IS 'the claim''s source column; with the two columns before it, the claim position graphitron_ast_path_entry keys its elements by within this file. An attribute and not a reference: a position is only a key within its own file, and the claim is named by the coordinate and the target type';
COMMENT ON COLUMN graphitron_join_path_claim.first_place IS 'the place the path starts at: 1 where place 0 is a root field''s leading @routine, its producer''s call and so no step of the path, else 0';
COMMENT ON COLUMN graphitron_join_path_claim.last_place IS 'the last place written under the claim''s position; the claim writes a path where it is at least first_place, so a root field writing only its leading @routine writes none';
COMMENT ON COLUMN graphitron_join_path_claim.touched_at IS 'when the reading that last stated this claim ran: the mark the sweep reads, so a claim a reading no longer finds goes with the paths following it';
COMMENT ON COLUMN graphitron_join_path_claim.element_graph_ref IS 'the graph half of the element''s key, nullable so the element''s removal sets the reference null rather than cascading';
COMMENT ON COLUMN graphitron_join_path_claim.element_coordinate_ref IS 'the coordinate half of the element''s key, equal to element_coordinate while the element stands';
COMMENT ON COLUMN graphitron_join_path_claim.target_graph_ref IS 'the graph half of the target type''s key, nullable so the type''s removal sets the reference null rather than cascading';
COMMENT ON COLUMN graphitron_join_path_claim.target_type_ref IS 'the type half of the target type''s key, equal to target_type while the type stands; null where the type named is none the graph has';

CREATE TABLE graphitron_occurrence_source (
  graph_name VARCHAR   NOT NULL,
  coordinate VARCHAR   NOT NULL,
  kind       VARCHAR   NOT NULL,
  rule       VARCHAR   NOT NULL,
  touched_at TIMESTAMP NOT NULL,
  PRIMARY KEY (graph_name, coordinate),
  -- What each subtype references, so a subtype row can only hang under a source of its own kind.
  UNIQUE (graph_name, coordinate, kind),
  FOREIGN KEY (graph_name, coordinate)
    REFERENCES graphitron_occurrence (graph_name, coordinate) ON DELETE CASCADE,
  CHECK (kind IN ('TABLE', 'OBJECT'))
);
COMMENT ON TABLE graphitron_occurrence_source IS 'What one occurrence''s values come from: one row per occurrence that has a source. For example Film.title''s values are rows of film, of kind TABLE, and Query.filmBlurbHolder.blurb''s are read off an instance of FilmBlurbHolder, of kind OBJECT.';
COMMENT ON COLUMN graphitron_occurrence_source.graph_name IS 'the owning graph''s partition, carried from the occurrence';
COMMENT ON COLUMN graphitron_occurrence_source.coordinate IS 'the occurrence whose source this is, at its nested coordinate; with the graph, the key and a reference into graphitron_occurrence, so a source goes with its occurrence';
COMMENT ON COLUMN graphitron_occurrence_source.kind IS 'TABLE, rows of the tables graphitron_occurrence_source_table names, or OBJECT, an instance of the class graphitron_occurrence_source_object names; carried into each subtype''s key so a subtype of the other kind cannot be written';
COMMENT ON COLUMN graphitron_occurrence_source.rule IS 'the rule whose claim took effect, the one of smallest priority value in graphitron_occurrence_source_precedence among those claiming the occurrence; with the graph and the coordinate a reference to that claim, so the source goes with it';
COMMENT ON COLUMN graphitron_occurrence_source.touched_at IS 'the reading that last wrote this row; the sweep deletes the rows an older reading wrote';

CREATE TABLE graphitron_occurrence_source_table (
  graph_name        VARCHAR   NOT NULL,
  coordinate        VARCHAR   NOT NULL,
  table_source_name VARCHAR   NOT NULL,
  table_schema      VARCHAR   NOT NULL,
  table_name        VARCHAR   NOT NULL,
  kind              VARCHAR   NOT NULL,
  touched_at        TIMESTAMP NOT NULL,
  table_source_ref  VARCHAR,
  table_schema_ref  VARCHAR,
  table_name_ref    VARCHAR,
  PRIMARY KEY (graph_name, coordinate, table_source_name, table_schema, table_name),
  FOREIGN KEY (graph_name, coordinate, kind)
    REFERENCES graphitron_occurrence_source (graph_name, coordinate, kind) ON DELETE CASCADE,
  -- The table, through the row's own copy of its key: a key to what an anchor was built from does
  -- not cascade, and the sweep removes the row the reading no longer finds.
  FOREIGN KEY (table_source_ref, table_schema_ref, table_name_ref)
    REFERENCES sql_table (source_name, table_schema, table_name) ON DELETE SET NULL,
  CHECK (table_source_ref IS NULL OR table_source_ref = table_source_name),
  CHECK (table_schema_ref IS NULL OR table_schema_ref = table_schema),
  CHECK (table_name_ref IS NULL OR table_name_ref = table_name),
  CHECK (kind = 'TABLE')
);
COMMENT ON TABLE graphitron_occurrence_source_table IS 'One table an occurrence''s values are rows of: one row per occurrence and table. For example Film.details.length is read from film, and an argument of a field returning a union of Film and Language has a row for film and one for language.';
COMMENT ON COLUMN graphitron_occurrence_source_table.graph_name IS 'the owning graph''s partition, carried from the source';
COMMENT ON COLUMN graphitron_occurrence_source_table.coordinate IS 'the occurrence whose values are rows of the table';
COMMENT ON COLUMN graphitron_occurrence_source_table.table_source_name IS 'the table''s catalog partition; with the schema and the name, an sql_table key';
COMMENT ON COLUMN graphitron_occurrence_source_table.table_schema IS 'the table''s SQL schema';
COMMENT ON COLUMN graphitron_occurrence_source_table.table_name IS 'the table the values are rows of, a function''s derived table included; with the coordinate the key, so a source over several tables has a row per table';
COMMENT ON COLUMN graphitron_occurrence_source_table.kind IS 'always TABLE, pinned so the foreign key holds the row to a source of kind TABLE';
COMMENT ON COLUMN graphitron_occurrence_source_table.touched_at IS 'the reading that last wrote this row; the sweep deletes the rows an older reading wrote';
COMMENT ON COLUMN graphitron_occurrence_source_table.table_source_ref IS 'the catalog half of the table''s key, nullable so the table''s removal sets the reference null rather than cascading';
COMMENT ON COLUMN graphitron_occurrence_source_table.table_schema_ref IS 'the schema half of the table''s key, equal to table_schema while the table stands';
COMMENT ON COLUMN graphitron_occurrence_source_table.table_name_ref IS 'the name half of the table''s key, equal to table_name while the table stands';

CREATE TABLE graphitron_occurrence_source_object (
  graph_name       VARCHAR   NOT NULL,
  coordinate       VARCHAR   NOT NULL,
  kind             VARCHAR   NOT NULL,
  class_name       VARCHAR   NOT NULL,
  touched_at       TIMESTAMP NOT NULL,
  class_source_ref VARCHAR,
  class_name_ref   VARCHAR,
  PRIMARY KEY (graph_name, coordinate),
  FOREIGN KEY (graph_name, coordinate, kind)
    REFERENCES graphitron_occurrence_source (graph_name, coordinate, kind) ON DELETE CASCADE,
  -- The class, through the row's own copy of its key, where the reading read the class at all.
  FOREIGN KEY (class_source_ref, class_name_ref)
    REFERENCES code_class (source_name, class_name) ON DELETE SET NULL,
  CHECK ((class_source_ref IS NULL) = (class_name_ref IS NULL)),
  CHECK (class_name_ref IS NULL OR class_name_ref = class_name),
  CHECK (kind = 'OBJECT')
);
COMMENT ON TABLE graphitron_occurrence_source_object IS 'The class an occurrence''s values are an instance of: one row per occurrence whose source is an object. For example Query.filmBlurbHolder.blurb is read off the FilmBlurbHolder its parent''s service hands back.';
COMMENT ON COLUMN graphitron_occurrence_source_object.graph_name IS 'the owning graph''s partition, carried from the source';
COMMENT ON COLUMN graphitron_occurrence_source_object.coordinate IS 'the occurrence whose values are read off the object; with the graph, the key, one class per occurrence since a coordinate names one producer';
COMMENT ON COLUMN graphitron_occurrence_source_object.kind IS 'always OBJECT, pinned so the foreign key holds the row to a source of kind OBJECT';
COMMENT ON COLUMN graphitron_occurrence_source_object.class_name IS 'the class the parent field''s own producer hands back, its method''s result with containers peeled off';
COMMENT ON COLUMN graphitron_occurrence_source_object.touched_at IS 'the reading that last wrote this row; the sweep deletes the rows an older reading wrote';
COMMENT ON COLUMN graphitron_occurrence_source_object.class_source_ref IS 'the classpath entry half of the class''s code_class key, nullable so the class''s removal sets the reference null rather than cascading; null where none of the graph''s entries declares the class';
COMMENT ON COLUMN graphitron_occurrence_source_object.class_name_ref IS 'the name half of the class''s key, equal to class_name while the class stands';

CREATE TABLE graphitron_path_need (
  graph_name      VARCHAR   NOT NULL,
  coordinate      VARCHAR   NOT NULL,
  target_type     VARCHAR   NOT NULL,
  start_kind      VARCHAR   NOT NULL,
  touched_at      TIMESTAMP NOT NULL,
  target_graph_ref VARCHAR,
  target_type_ref VARCHAR,
  PRIMARY KEY (graph_name, coordinate, target_type),
  -- What each subtype references, so a subtype row can only hang under a need of its own kind.
  UNIQUE (graph_name, coordinate, target_type, start_kind),
  FOREIGN KEY (graph_name, coordinate)
    REFERENCES graphitron_occurrence (graph_name, coordinate) ON DELETE CASCADE,
  -- The target type, through the need's own copy of its key: a key to what an anchor was built from
  -- does not cascade, and the sweep removes the row the reading no longer finds.
  FOREIGN KEY (target_graph_ref, target_type_ref)
    REFERENCES graphitron_type (graph_name, type_name) ON DELETE SET NULL,
  CHECK (start_kind IN ('TABLE', 'OBJECT')),
  CHECK (target_graph_ref IS NULL OR target_graph_ref = graph_name),
  CHECK (target_type_ref IS NULL OR target_type_ref = target_type)
);
COMMENT ON TABLE graphitron_path_need IS 'One type an occurrence must reach from its source: one row per occurrence and target type, with whether the path toward it starts on a table or on an object. For example Query.search(languageId:), an argument of a field returning a union of Film and Language, needs Film and Language, each from a table.';
COMMENT ON COLUMN graphitron_path_need.graph_name IS 'the owning graph''s partition, carried from the occurrence';
COMMENT ON COLUMN graphitron_path_need.coordinate IS 'the occurrence whose need this is, at its nested coordinate; with the graph, a reference into graphitron_occurrence, so a need goes with the occurrence';
COMMENT ON COLUMN graphitron_path_need.target_type IS 'the type the occurrence reaches: a field''s target where it has a table or none; each member with a table of a union, a multi-table interface or a single-table interface, never the interface itself; for an argument or input field, each type its parent''s needs reach. With the coordinate the key, as a claim is keyed by its element and target type';
COMMENT ON COLUMN graphitron_path_need.start_kind IS 'TABLE where the path starts on one of the occurrence''s source tables, graphitron_path_need_table; OBJECT where it starts on the object the occurrence''s values are read off. Carried into each subtype''s key so a subtype of the other kind cannot be written';
COMMENT ON COLUMN graphitron_path_need.touched_at IS 'when the reading that last stated this need ran: the mark the sweep reads, so a need a reading no longer finds goes with its subtype, path, steps and stop';
COMMENT ON COLUMN graphitron_path_need.target_graph_ref IS 'the graph half of the target type''s key, nullable so the type''s removal sets the reference null rather than cascading';
COMMENT ON COLUMN graphitron_path_need.target_type_ref IS 'the type half of the target type''s key, equal to target_type while the type stands; null where the type is none graphitron_type holds';

CREATE TABLE graphitron_path_need_table (
  graph_name           VARCHAR   NOT NULL,
  coordinate           VARCHAR   NOT NULL,
  target_type          VARCHAR   NOT NULL,
  start_kind           VARCHAR   NOT NULL,
  start_source_name    VARCHAR   NOT NULL,
  start_schema         VARCHAR   NOT NULL,
  start_table          VARCHAR   NOT NULL,
  landing_source_name  VARCHAR,
  landing_schema       VARCHAR,
  landing_table        VARCHAR,
  rule                 VARCHAR   NOT NULL,
  touched_at           TIMESTAMP NOT NULL,
  start_graph_ref      VARCHAR,
  start_coordinate_ref VARCHAR,
  start_source_ref     VARCHAR,
  start_schema_ref     VARCHAR,
  start_table_ref      VARCHAR,
  landing_source_ref   VARCHAR,
  landing_schema_ref   VARCHAR,
  landing_table_ref    VARCHAR,
  PRIMARY KEY (graph_name, coordinate, target_type),
  -- The need it details, pinned to the kind that starts on a table.
  FOREIGN KEY (graph_name, coordinate, target_type, start_kind)
    REFERENCES graphitron_path_need (graph_name, coordinate, target_type, start_kind)
    ON DELETE CASCADE,
  -- The start and the landing, each through the need's own copy of its key: a key to what an anchor
  -- was built from does not cascade, and the sweep removes the row the reading no longer finds.
  FOREIGN KEY (start_graph_ref, start_coordinate_ref, start_source_ref, start_schema_ref,
               start_table_ref)
    REFERENCES graphitron_occurrence_source_table (graph_name, coordinate, table_source_name,
                                                   table_schema, table_name) ON DELETE SET NULL,
  FOREIGN KEY (landing_source_ref, landing_schema_ref, landing_table_ref)
    REFERENCES sql_table (source_name, table_schema, table_name) ON DELETE SET NULL,
  CHECK (start_graph_ref IS NULL OR start_graph_ref = graph_name),
  CHECK (start_coordinate_ref IS NULL OR start_coordinate_ref = coordinate),
  CHECK (start_source_ref IS NULL OR start_source_ref = start_source_name),
  CHECK (start_schema_ref IS NULL OR start_schema_ref = start_schema),
  CHECK (start_table_ref IS NULL OR start_table_ref = start_table),
  CHECK (start_kind = 'TABLE'),
  -- A landing is a table or not yet known, all three of its columns together.
  CHECK ((landing_source_name IS NULL) = (landing_table IS NULL)
         AND (landing_schema IS NULL) = (landing_table IS NULL)),
  CHECK (landing_source_ref IS NULL OR landing_source_ref = landing_source_name),
  CHECK (landing_schema_ref IS NULL OR landing_schema_ref = landing_schema),
  CHECK (landing_table_ref IS NULL OR landing_table_ref = landing_table)
);
COMMENT ON TABLE graphitron_path_need_table IS 'One type an occurrence with a table source must reach: one row per occurrence and target type, with the source table it starts on and the table it lands on. For example Query.search(languageId:), an argument of a field returning a union of Film and Language, needs Film from film and Language from language, and Film.languageName, a scalar that writes a path, needs String from film with its landing not yet known.';
COMMENT ON COLUMN graphitron_path_need_table.graph_name IS 'the owning graph''s partition, carried from the occurrence';
COMMENT ON COLUMN graphitron_path_need_table.coordinate IS 'the occurrence whose need this is, at its nested coordinate; with the graph, a reference into graphitron_occurrence, so a need goes with the occurrence';
COMMENT ON COLUMN graphitron_path_need_table.target_type IS 'the type the occurrence reaches; with the two columns before it, the need''s key';
COMMENT ON COLUMN graphitron_path_need_table.start_kind IS 'always TABLE, pinned so the foreign key holds the row to a need that starts on a table';
COMMENT ON COLUMN graphitron_path_need_table.start_source_name IS 'the catalog partition of the source table the path starts on';
COMMENT ON COLUMN graphitron_path_need_table.start_schema IS 'the SQL schema of the source table the path starts on';
COMMENT ON COLUMN graphitron_path_need_table.start_table IS 'the source table the path starts on, one of the occurrence''s graphitron_occurrence_source_table rows: for a field its one source table, for an argument where its field lands for the target type, for an input field its parent''s start';
COMMENT ON COLUMN graphitron_path_need_table.landing_source_name IS 'the catalog partition of the table the path lands on, null with landing_table';
COMMENT ON COLUMN graphitron_path_need_table.landing_schema IS 'the SQL schema of the table the path lands on, null with landing_table';
COMMENT ON COLUMN graphitron_path_need_table.landing_table IS 'the table the path lands on: a table-bound target''s own table, the start table for a target bound to none, and null for a scalar whose declaration writes a path until its steps say where it lands. An attribute and not a key, so a need is one row however its landing is learnt';
COMMENT ON COLUMN graphitron_path_need_table.rule IS 'the rule whose claim took effect, the one of smallest priority value in graphitron_path_need_precedence among those claiming the occurrence; with the graph, the coordinate and the type a reference to that claim, so the need''s table side goes with it';
COMMENT ON COLUMN graphitron_path_need_table.touched_at IS 'when the reading that last stated this need ran, as its need''s; carried so a reader of the table side filters on its own row';
COMMENT ON COLUMN graphitron_path_need_table.start_graph_ref IS 'the graph half of the start''s graphitron_occurrence_source_table key, nullable so the source table row''s removal sets the reference null rather than cascading';
COMMENT ON COLUMN graphitron_path_need_table.start_coordinate_ref IS 'the coordinate half of the start''s key, equal to coordinate while the source table row stands';
COMMENT ON COLUMN graphitron_path_need_table.start_source_ref IS 'the catalog half of the start''s key, equal to start_source_name while the source table row stands';
COMMENT ON COLUMN graphitron_path_need_table.start_schema_ref IS 'the schema half of the start''s key, equal to start_schema while the source table row stands';
COMMENT ON COLUMN graphitron_path_need_table.start_table_ref IS 'the table half of the start''s key, equal to start_table while the source table row stands';
COMMENT ON COLUMN graphitron_path_need_table.landing_source_ref IS 'the catalog half of the landing table''s sql_table key, nullable so the table''s removal sets the reference null rather than cascading';
COMMENT ON COLUMN graphitron_path_need_table.landing_schema_ref IS 'the schema half of the landing table''s key, equal to landing_schema while the table stands';
COMMENT ON COLUMN graphitron_path_need_table.landing_table_ref IS 'the name half of the landing table''s key, equal to landing_table while the table stands';

CREATE TABLE graphitron_path_need_object (
  graph_name           VARCHAR   NOT NULL,
  coordinate           VARCHAR   NOT NULL,
  target_type          VARCHAR   NOT NULL,
  start_kind           VARCHAR   NOT NULL,
  start_class          VARCHAR   NOT NULL,
  touched_at           TIMESTAMP NOT NULL,
  start_graph_ref      VARCHAR,
  start_coordinate_ref VARCHAR,
  PRIMARY KEY (graph_name, coordinate, target_type),
  -- The need it details, pinned to the kind that starts on an object.
  FOREIGN KEY (graph_name, coordinate, target_type, start_kind)
    REFERENCES graphitron_path_need (graph_name, coordinate, target_type, start_kind)
    ON DELETE CASCADE,
  -- The object source it starts on, through the need's own copy of its key.
  FOREIGN KEY (start_graph_ref, start_coordinate_ref)
    REFERENCES graphitron_occurrence_source_object (graph_name, coordinate) ON DELETE SET NULL,
  CHECK (start_kind = 'OBJECT'),
  CHECK (start_graph_ref IS NULL OR start_graph_ref = graph_name),
  CHECK (start_coordinate_ref IS NULL OR start_coordinate_ref = coordinate)
);
COMMENT ON TABLE graphitron_path_need_object IS 'One type an occurrence with an object source must reach: one row per occurrence and target type, with the class it starts on. For example Query.filmBlurbHolder.blurb, read off the FilmBlurbHolder its parent''s service hands back, needs FilmBlurb from FilmBlurbHolder.';
COMMENT ON COLUMN graphitron_path_need_object.graph_name IS 'the owning graph''s partition, carried from the need';
COMMENT ON COLUMN graphitron_path_need_object.coordinate IS 'the occurrence whose need this is';
COMMENT ON COLUMN graphitron_path_need_object.target_type IS 'the type the occurrence reaches, its field''s target; with the two columns before it, the need''s key';
COMMENT ON COLUMN graphitron_path_need_object.start_kind IS 'always OBJECT, pinned so the foreign key holds the row to a need that starts on an object';
COMMENT ON COLUMN graphitron_path_need_object.start_class IS 'the class the path starts on, the occurrence''s object source''s';
COMMENT ON COLUMN graphitron_path_need_object.touched_at IS 'when the reading that last stated this need ran, as its need''s';
COMMENT ON COLUMN graphitron_path_need_object.start_graph_ref IS 'the graph half of the object source''s key, nullable so the source''s removal sets the reference null rather than cascading';
COMMENT ON COLUMN graphitron_path_need_object.start_coordinate_ref IS 'the coordinate half of the object source''s key, equal to coordinate while the source stands';

CREATE TABLE graphitron_path (
  graph_name  VARCHAR   NOT NULL,
  coordinate  VARCHAR   NOT NULL,
  target_type VARCHAR   NOT NULL,
  kind        VARCHAR   NOT NULL,
  origin      VARCHAR   NOT NULL,
  touched_at  TIMESTAMP NOT NULL,
  PRIMARY KEY (graph_name, coordinate, target_type),
  -- What each subtype references, so a subtype row can only hang under a path of its own kind.
  UNIQUE (graph_name, coordinate, target_type, kind),
  FOREIGN KEY (graph_name, coordinate, target_type)
    REFERENCES graphitron_path_need (graph_name, coordinate, target_type) ON DELETE CASCADE,
  CHECK (kind IN ('JOIN', 'ACCESSOR')),
  CHECK (origin IN ('WRITTEN', 'INHERITED', 'INFERRED', 'EMPTY'))
);
COMMENT ON TABLE graphitron_path IS 'How one need is met: one row per need a path meets, with its kind and where it came from. For example Staff.homeAddress, inherited from Person.homeAddress, meets its need for Address by a JOIN path of origin INHERITED, and Film.title by an EMPTY one ending where it starts.';
COMMENT ON COLUMN graphitron_path.graph_name IS 'the owning graph''s partition, carried from the need';
COMMENT ON COLUMN graphitron_path.coordinate IS 'the occurrence whose need the path meets';
COMMENT ON COLUMN graphitron_path.target_type IS 'the type the need reaches; with the two columns before it, the need''s key, so a path is one-to-one with the need it meets and goes with it';
COMMENT ON COLUMN graphitron_path.kind IS 'JOIN, joins from a table source, graphitron_join_path; or ACCESSOR, accessor calls from an object source, graphitron_accessor_path. Carried into each subtype''s key so a subtype of the other kind cannot be written';
COMMENT ON COLUMN graphitron_path.origin IS 'where the path came from: WRITTEN at the claim of the element the occurrence is of; INHERITED from an interface''s field, one row per implementation; INFERRED, a path whose steps ride inferred keys; or EMPTY, ending where it starts, its own origin so an empty path is never read as a failed inference';
COMMENT ON COLUMN graphitron_path.touched_at IS 'when the reading that last stated this path ran: the mark the sweep reads';

CREATE TABLE graphitron_join_path (
  graph_name         VARCHAR   NOT NULL,
  coordinate         VARCHAR   NOT NULL,
  target_type        VARCHAR   NOT NULL,
  kind               VARCHAR   NOT NULL,
  target_source_name VARCHAR   NOT NULL,
  target_schema      VARCHAR   NOT NULL,
  target_table       VARCHAR   NOT NULL,
  touched_at         TIMESTAMP NOT NULL,
  target_source_ref  VARCHAR,
  target_schema_ref  VARCHAR,
  target_table_ref   VARCHAR,
  PRIMARY KEY (graph_name, coordinate, target_type),
  FOREIGN KEY (graph_name, coordinate, target_type, kind)
    REFERENCES graphitron_path (graph_name, coordinate, target_type, kind) ON DELETE CASCADE,
  -- The table reached, through the row's own copy of its key: a key to what an anchor was built from
  -- does not cascade, and the sweep removes the row the reading no longer finds.
  FOREIGN KEY (target_source_ref, target_schema_ref, target_table_ref)
    REFERENCES sql_table (source_name, table_schema, table_name) ON DELETE SET NULL,
  CHECK (target_source_ref IS NULL OR target_source_ref = target_source_name),
  CHECK (target_schema_ref IS NULL OR target_schema_ref = target_schema),
  CHECK (target_table_ref IS NULL OR target_table_ref = target_table),
  CHECK (kind = 'JOIN')
);
COMMENT ON TABLE graphitron_join_path IS 'The table a join path reaches: one row per path of kind JOIN. For example Customer.address reaches address, and Film.title, an empty path, reaches film, where it starts.';
COMMENT ON COLUMN graphitron_join_path.graph_name IS 'the owning graph''s partition, carried from the path';
COMMENT ON COLUMN graphitron_join_path.coordinate IS 'the occurrence whose need the path meets';
COMMENT ON COLUMN graphitron_join_path.target_type IS 'the type the need reaches; with the two columns before it, the path''s key';
COMMENT ON COLUMN graphitron_join_path.kind IS 'always JOIN, pinned so the foreign key holds the row to a path of kind JOIN';
COMMENT ON COLUMN graphitron_join_path.target_source_name IS 'the catalog partition of the table the path reaches';
COMMENT ON COLUMN graphitron_join_path.target_schema IS 'the SQL schema of the table the path reaches';
COMMENT ON COLUMN graphitron_join_path.target_table IS 'the table the path reaches, never null: its last step''s destination, or its start where it is empty';
COMMENT ON COLUMN graphitron_join_path.touched_at IS 'when the reading that last stated this path ran: the mark the sweep reads';
COMMENT ON COLUMN graphitron_join_path.target_source_ref IS 'the catalog half of the reached table''s sql_table key, nullable so the table''s removal sets the reference null rather than cascading';
COMMENT ON COLUMN graphitron_join_path.target_schema_ref IS 'the schema half of the reached table''s key, equal to target_schema while the table stands';
COMMENT ON COLUMN graphitron_join_path.target_table_ref IS 'the name half of the reached table''s key, equal to target_table while the table stands';

CREATE TABLE graphitron_join_path_claimed (
  graph_name            VARCHAR   NOT NULL,
  coordinate            VARCHAR   NOT NULL,
  target_type           VARCHAR   NOT NULL,
  claim_coordinate      VARCHAR   NOT NULL,
  claim_target_type     VARCHAR   NOT NULL,
  touched_at            TIMESTAMP NOT NULL,
  claim_graph_ref       VARCHAR,
  claim_coordinate_ref  VARCHAR,
  claim_target_type_ref VARCHAR,
  PRIMARY KEY (graph_name, coordinate, target_type),
  FOREIGN KEY (graph_name, coordinate, target_type)
    REFERENCES graphitron_join_path (graph_name, coordinate, target_type) ON DELETE CASCADE,
  -- The claim, through the row's own copy of its key: a swept claim sets the reference null, and the
  -- sweep removes the row the reading no longer finds.
  FOREIGN KEY (claim_graph_ref, claim_coordinate_ref, claim_target_type_ref)
    REFERENCES graphitron_join_path_claim (graph_name, element_coordinate, target_type)
    ON DELETE SET NULL,
  CHECK (claim_graph_ref IS NULL OR claim_graph_ref = graph_name),
  CHECK (claim_coordinate_ref IS NULL OR claim_coordinate_ref = claim_coordinate),
  CHECK (claim_target_type_ref IS NULL OR claim_target_type_ref = claim_target_type)
);
COMMENT ON TABLE graphitron_join_path_claimed IS 'The claim a written or inherited join path follows: one row per join path of origin WRITTEN or INHERITED, the origin being the supertype''s and so out of reach of a check here. For example Staff.homeAddress, inherited from Person.homeAddress, follows the claim (Person.homeAddress, Address), which lies in another file.';
COMMENT ON COLUMN graphitron_join_path_claimed.graph_name IS 'the owning graph''s partition, carried from the path';
COMMENT ON COLUMN graphitron_join_path_claimed.coordinate IS 'the occurrence whose need the path meets';
COMMENT ON COLUMN graphitron_join_path_claimed.target_type IS 'the type the need reaches; with the two columns before it, the join path''s key';
COMMENT ON COLUMN graphitron_join_path_claimed.claim_coordinate IS 'the declared element of the claim the path follows, which may lie in another file';
COMMENT ON COLUMN graphitron_join_path_claimed.claim_target_type IS 'the target type of the claim the path follows; with claim_coordinate, graphitron_join_path_claim''s key';
COMMENT ON COLUMN graphitron_join_path_claimed.touched_at IS 'when the reading that last stated this path ran: the mark the sweep reads';
COMMENT ON COLUMN graphitron_join_path_claimed.claim_graph_ref IS 'the graph half of the claim''s key, nullable so the claim''s removal sets the reference null rather than cascading';
COMMENT ON COLUMN graphitron_join_path_claimed.claim_coordinate_ref IS 'the element half of the claim''s key, equal to claim_coordinate while the claim stands';
COMMENT ON COLUMN graphitron_join_path_claimed.claim_target_type_ref IS 'the type half of the claim''s key, equal to claim_target_type while the claim stands';

CREATE TABLE graphitron_accessor_path (
  graph_name              VARCHAR   NOT NULL,
  coordinate              VARCHAR   NOT NULL,
  target_type             VARCHAR   NOT NULL,
  kind                    VARCHAR   NOT NULL,
  target_class_name       VARCHAR   NOT NULL,
  touched_at              TIMESTAMP NOT NULL,
  target_class_source_ref VARCHAR,
  target_class_name_ref   VARCHAR,
  PRIMARY KEY (graph_name, coordinate, target_type),
  FOREIGN KEY (graph_name, coordinate, target_type, kind)
    REFERENCES graphitron_path (graph_name, coordinate, target_type, kind) ON DELETE CASCADE,
  -- The class reached, through the row's own copy of its key, where the reading read the class at all.
  FOREIGN KEY (target_class_source_ref, target_class_name_ref)
    REFERENCES code_class (source_name, class_name) ON DELETE SET NULL,
  CHECK ((target_class_source_ref IS NULL) = (target_class_name_ref IS NULL)),
  CHECK (target_class_name_ref IS NULL OR target_class_name_ref = target_class_name),
  CHECK (kind = 'ACCESSOR')
);
COMMENT ON TABLE graphitron_accessor_path IS 'The class an accessor path reaches: one row per path of kind ACCESSOR. For example Query.filmBlurbHolder.blurb, read off a FilmBlurbHolder, reaches FilmBlurb by its blurb() accessor.';
COMMENT ON COLUMN graphitron_accessor_path.graph_name IS 'the owning graph''s partition, carried from the path';
COMMENT ON COLUMN graphitron_accessor_path.coordinate IS 'the occurrence whose need the path meets';
COMMENT ON COLUMN graphitron_accessor_path.target_type IS 'the type the need reaches; with the two columns before it, the path''s key';
COMMENT ON COLUMN graphitron_accessor_path.kind IS 'always ACCESSOR, pinned so the foreign key holds the row to a path of kind ACCESSOR';
COMMENT ON COLUMN graphitron_accessor_path.target_class_name IS 'the class the path reaches, its last accessor''s result, or its start where it is empty';
COMMENT ON COLUMN graphitron_accessor_path.touched_at IS 'when the reading that last stated this path ran: the mark the sweep reads';
COMMENT ON COLUMN graphitron_accessor_path.target_class_source_ref IS 'the classpath entry half of the class''s code_class key, nullable so the class''s removal sets the reference null rather than cascading; null where none of the graph''s entries declares the class';
COMMENT ON COLUMN graphitron_accessor_path.target_class_name_ref IS 'the name half of the class''s key, equal to target_class_name while the class stands';

CREATE TABLE graphitron_accessor_path_step (
  graph_name       VARCHAR   NOT NULL,
  coordinate       VARCHAR   NOT NULL,
  target_type      VARCHAR   NOT NULL,
  position         INT       NOT NULL,
  slot_source_name VARCHAR   NOT NULL,
  slot_class_name  VARCHAR   NOT NULL,
  slot_method_name VARCHAR   NOT NULL,
  slot_descriptor  VARCHAR   NOT NULL,
  touched_at       TIMESTAMP NOT NULL,
  PRIMARY KEY (graph_name, coordinate, target_type, position),
  FOREIGN KEY (graph_name, coordinate, target_type)
    REFERENCES graphitron_accessor_path (graph_name, coordinate, target_type) ON DELETE CASCADE,
  FOREIGN KEY (slot_source_name, slot_class_name, slot_method_name, slot_descriptor)
    REFERENCES code_read_slot (source_name, class_name, method_name, descriptor) ON DELETE CASCADE,
  CHECK (position >= 0)
);
COMMENT ON TABLE graphitron_accessor_path_step IS 'One member call an accessor path makes: one row per path and position, naming the member''s code_read_slot row. For example Query.filmBlurbHolder.blurb calls FilmBlurbHolder.blurb() at position 0; a path where the object passes through calls nothing and has no step.';
COMMENT ON COLUMN graphitron_accessor_path_step.graph_name IS 'the owning graph''s partition, carried from the path';
COMMENT ON COLUMN graphitron_accessor_path_step.coordinate IS 'the occurrence whose path this is';
COMMENT ON COLUMN graphitron_accessor_path_step.target_type IS 'the type the path reaches; with the two columns before it, the path''s key';
COMMENT ON COLUMN graphitron_accessor_path_step.position IS 'the call''s place in the path, from zero in the order made';
COMMENT ON COLUMN graphitron_accessor_path_step.slot_source_name IS 'the classpath entry of the member''s code_read_slot row';
COMMENT ON COLUMN graphitron_accessor_path_step.slot_class_name IS 'the class the member is read on';
COMMENT ON COLUMN graphitron_accessor_path_step.slot_method_name IS 'the method that reads the member';
COMMENT ON COLUMN graphitron_accessor_path_step.slot_descriptor IS 'the method''s descriptor; with the three before it, the code_read_slot row';
COMMENT ON COLUMN graphitron_accessor_path_step.touched_at IS 'when the reading that last stated this step ran; a step a reading no longer takes goes with its path or by the sweep';

CREATE TABLE graphitron_join_path_step (
  graph_name       VARCHAR   NOT NULL,
  coordinate       VARCHAR   NOT NULL,
  target_type      VARCHAR   NOT NULL,
  position         INT       NOT NULL,
  from_source_name VARCHAR   NOT NULL,
  from_schema      VARCHAR   NOT NULL,
  from_table       VARCHAR   NOT NULL,
  to_source_name   VARCHAR   NOT NULL,
  to_schema        VARCHAR   NOT NULL,
  to_table         VARCHAR   NOT NULL,
  element_place    INT,
  as_name          VARCHAR,
  touched_at       TIMESTAMP NOT NULL,
  from_source_ref  VARCHAR,
  from_schema_ref  VARCHAR,
  from_table_ref   VARCHAR,
  to_source_ref    VARCHAR,
  to_schema_ref    VARCHAR,
  to_table_ref     VARCHAR,
  PRIMARY KEY (graph_name, coordinate, target_type, position),
  -- A step belongs to its need, not to the path meeting it: a met need has its path and its
  -- steps, and a stopped need has the steps it took and its stop.
  FOREIGN KEY (graph_name, coordinate, target_type)
    REFERENCES graphitron_path_need (graph_name, coordinate, target_type) ON DELETE CASCADE,
  -- The two tables, each through the step's own copy of its key: a key to what an anchor was built
  -- from does not cascade, and the sweep removes the step the reading no longer takes.
  FOREIGN KEY (from_source_ref, from_schema_ref, from_table_ref)
    REFERENCES sql_table (source_name, table_schema, table_name) ON DELETE SET NULL,
  FOREIGN KEY (to_source_ref, to_schema_ref, to_table_ref)
    REFERENCES sql_table (source_name, table_schema, table_name) ON DELETE SET NULL,
  CHECK (from_source_ref IS NULL OR from_source_ref = from_source_name),
  CHECK (from_schema_ref IS NULL OR from_schema_ref = from_schema),
  CHECK (from_table_ref IS NULL OR from_table_ref = from_table),
  CHECK (to_source_ref IS NULL OR to_source_ref = to_source_name),
  CHECK (to_schema_ref IS NULL OR to_schema_ref = to_schema),
  CHECK (to_table_ref IS NULL OR to_table_ref = to_table),
  CHECK (position >= 0),
  CHECK (element_place >= 0)
);
COMMENT ON TABLE graphitron_join_path_step IS 'One step a join path takes: one row per need and position the path toward it stepped through, from one table to the next, with the place of the written element it resolved where one did. For example Customer.city over @reference(path: [{key: "customer_address_id_fkey"}, {key: "address_city_id_fkey"}]) is two steps, customer to address and address to city.';
COMMENT ON COLUMN graphitron_join_path_step.graph_name IS 'the owning graph''s partition, carried from the need';
COMMENT ON COLUMN graphitron_join_path_step.coordinate IS 'the occurrence whose need the step is toward';
COMMENT ON COLUMN graphitron_join_path_step.target_type IS 'the type the need reaches; with the two columns before it, the need''s key, so a step goes with its need. A met need''s steps are its path''s, a stopped need''s the ones taken before its stop';
COMMENT ON COLUMN graphitron_join_path_step.position IS 'the step''s place in the path, numbered from zero in the order taken';
COMMENT ON COLUMN graphitron_join_path_step.from_source_name IS 'the catalog partition of the table the step leaves';
COMMENT ON COLUMN graphitron_join_path_step.from_schema IS 'the SQL schema of the table the step leaves';
COMMENT ON COLUMN graphitron_join_path_step.from_table IS 'the table the step leaves: the need''s start at the first step, the previous step''s to_table after it';
COMMENT ON COLUMN graphitron_join_path_step.to_source_name IS 'the catalog partition of the table the step reaches';
COMMENT ON COLUMN graphitron_join_path_step.to_schema IS 'the SQL schema of the table the step reaches';
COMMENT ON COLUMN graphitron_join_path_step.to_table IS 'the table the step reaches, where the next step leaves from';
COMMENT ON COLUMN graphitron_join_path_step.element_place IS 'the place of the element the step resolved in the written list of the claim its path follows, as graphitron_ast_path_entry numbers it; NULL for an inferred step and for the step a @routine takes to its @table';
COMMENT ON COLUMN graphitron_join_path_step.as_name IS 'the as: name the element carries, which an argument or input field names to start on this step; NULL where none is written';
COMMENT ON COLUMN graphitron_join_path_step.touched_at IS 'when the reading that last took this step ran: the mark the sweep reads, so a step a reading no longer takes goes with its children';
COMMENT ON COLUMN graphitron_join_path_step.from_source_ref IS 'the catalog half of the departed table''s sql_table key, nullable so the table''s removal sets the reference null rather than cascading';
COMMENT ON COLUMN graphitron_join_path_step.from_schema_ref IS 'the schema half of the departed table''s key, equal to from_schema while the table stands';
COMMENT ON COLUMN graphitron_join_path_step.from_table_ref IS 'the name half of the departed table''s key, equal to from_table while the table stands';
COMMENT ON COLUMN graphitron_join_path_step.to_source_ref IS 'the catalog half of the reached table''s sql_table key, nullable so the table''s removal sets the reference null rather than cascading';
COMMENT ON COLUMN graphitron_join_path_step.to_schema_ref IS 'the schema half of the reached table''s key, equal to to_schema while the table stands';
COMMENT ON COLUMN graphitron_join_path_step.to_table_ref IS 'the name half of the reached table''s key, equal to to_table while the table stands';

CREATE TABLE graphitron_join_path_step_column (
  graph_name       VARCHAR   NOT NULL,
  coordinate       VARCHAR   NOT NULL,
  target_type      VARCHAR   NOT NULL,
  position         INT       NOT NULL,
  ordinal          INT       NOT NULL,
  from_source_name VARCHAR   NOT NULL,
  from_schema      VARCHAR   NOT NULL,
  from_table       VARCHAR   NOT NULL,
  from_column      VARCHAR   NOT NULL,
  to_source_name   VARCHAR   NOT NULL,
  to_schema        VARCHAR   NOT NULL,
  to_table         VARCHAR   NOT NULL,
  to_column        VARCHAR   NOT NULL,
  touched_at       TIMESTAMP NOT NULL,
  from_source_ref  VARCHAR,
  from_schema_ref  VARCHAR,
  from_table_ref   VARCHAR,
  from_column_ref  VARCHAR,
  to_source_ref    VARCHAR,
  to_schema_ref    VARCHAR,
  to_table_ref     VARCHAR,
  to_column_ref    VARCHAR,
  PRIMARY KEY (graph_name, coordinate, target_type, position, ordinal),
  FOREIGN KEY (graph_name, coordinate, target_type, position)
    REFERENCES graphitron_join_path_step (graph_name, coordinate, target_type, position)
    ON DELETE CASCADE,
  -- The two columns, each through the pair's own copy of its key, on the step's terms.
  FOREIGN KEY (from_source_ref, from_schema_ref, from_table_ref, from_column_ref)
    REFERENCES sql_column (source_name, table_schema, table_name, column_name) ON DELETE SET NULL,
  FOREIGN KEY (to_source_ref, to_schema_ref, to_table_ref, to_column_ref)
    REFERENCES sql_column (source_name, table_schema, table_name, column_name) ON DELETE SET NULL,
  CHECK (from_source_ref IS NULL OR from_source_ref = from_source_name),
  CHECK (from_schema_ref IS NULL OR from_schema_ref = from_schema),
  CHECK (from_table_ref IS NULL OR from_table_ref = from_table),
  CHECK (from_column_ref IS NULL OR from_column_ref = from_column),
  CHECK (to_source_ref IS NULL OR to_source_ref = to_source_name),
  CHECK (to_schema_ref IS NULL OR to_schema_ref = to_schema),
  CHECK (to_table_ref IS NULL OR to_table_ref = to_table),
  CHECK (to_column_ref IS NULL OR to_column_ref = to_column),
  CHECK (ordinal >= 0)
);
COMMENT ON TABLE graphitron_join_path_step_column IS 'A column pair a step of a join path joins on: one row per step and pair. For example the step from customer to address joins customer.address_id to address.address_id, one pair.';
COMMENT ON COLUMN graphitron_join_path_step_column.graph_name IS 'the owning graph''s partition, carried from the step';
COMMENT ON COLUMN graphitron_join_path_step_column.coordinate IS 'the occurrence, as on the step';
COMMENT ON COLUMN graphitron_join_path_step_column.target_type IS 'the need''s target type, as on the step';
COMMENT ON COLUMN graphitron_join_path_step_column.position IS 'the step''s position; with the columns before it, the step this pair belongs to';
COMMENT ON COLUMN graphitron_join_path_step_column.ordinal IS 'the pair''s place in the key, numbered from zero in the key''s own column order';
COMMENT ON COLUMN graphitron_join_path_step_column.from_source_name IS 'the catalog partition of the step''s from_table';
COMMENT ON COLUMN graphitron_join_path_step_column.from_schema IS 'the SQL schema of the step''s from_table';
COMMENT ON COLUMN graphitron_join_path_step_column.from_table IS 'the step''s from_table';
COMMENT ON COLUMN graphitron_join_path_step_column.from_column IS 'the column on the side the step leaves';
COMMENT ON COLUMN graphitron_join_path_step_column.to_source_name IS 'the catalog partition of the step''s to_table';
COMMENT ON COLUMN graphitron_join_path_step_column.to_schema IS 'the SQL schema of the step''s to_table';
COMMENT ON COLUMN graphitron_join_path_step_column.to_table IS 'the step''s to_table';
COMMENT ON COLUMN graphitron_join_path_step_column.to_column IS 'the column on the side the step reaches, equal to from_column in the join';
COMMENT ON COLUMN graphitron_join_path_step_column.touched_at IS 'when the reading that last took the step ran, as on the step';
COMMENT ON COLUMN graphitron_join_path_step_column.from_source_ref IS 'the catalog half of the departing column''s sql_column key, nullable so the column''s removal sets the reference null rather than cascading';
COMMENT ON COLUMN graphitron_join_path_step_column.from_schema_ref IS 'the schema half of the departing column''s key, equal to from_schema while the column stands';
COMMENT ON COLUMN graphitron_join_path_step_column.from_table_ref IS 'the table half of the departing column''s key, equal to from_table while the column stands';
COMMENT ON COLUMN graphitron_join_path_step_column.from_column_ref IS 'the name half of the departing column''s key, equal to from_column while the column stands';
COMMENT ON COLUMN graphitron_join_path_step_column.to_source_ref IS 'the catalog half of the reached column''s sql_column key, nullable so the column''s removal sets the reference null rather than cascading';
COMMENT ON COLUMN graphitron_join_path_step_column.to_schema_ref IS 'the schema half of the reached column''s key, equal to to_schema while the column stands';
COMMENT ON COLUMN graphitron_join_path_step_column.to_table_ref IS 'the table half of the reached column''s key, equal to to_table while the column stands';
COMMENT ON COLUMN graphitron_join_path_step_column.to_column_ref IS 'the name half of the reached column''s key, equal to to_column while the column stands';

CREATE TABLE graphitron_join_path_step_key (
  graph_name             VARCHAR   NOT NULL,
  coordinate             VARCHAR   NOT NULL,
  target_type            VARCHAR   NOT NULL,
  position               INT       NOT NULL,
  constraint_source_name VARCHAR   NOT NULL,
  constraint_schema      VARCHAR   NOT NULL,
  constraint_table       VARCHAR   NOT NULL,
  constraint_name        VARCHAR   NOT NULL,
  touched_at             TIMESTAMP NOT NULL,
  constraint_source_ref  VARCHAR,
  constraint_schema_ref  VARCHAR,
  constraint_table_ref   VARCHAR,
  constraint_name_ref    VARCHAR,
  PRIMARY KEY (graph_name, coordinate, target_type, position),
  FOREIGN KEY (graph_name, coordinate, target_type, position)
    REFERENCES graphitron_join_path_step (graph_name, coordinate, target_type, position)
    ON DELETE CASCADE,
  -- The key, through the row's own copy of its key, on the step's terms.
  FOREIGN KEY (constraint_source_ref, constraint_schema_ref, constraint_table_ref,
               constraint_name_ref)
    REFERENCES sql_referential_constraint (source_name, table_schema, table_name, constraint_name)
    ON DELETE SET NULL,
  CHECK (constraint_source_ref IS NULL OR constraint_source_ref = constraint_source_name),
  CHECK (constraint_schema_ref IS NULL OR constraint_schema_ref = constraint_schema),
  CHECK (constraint_table_ref IS NULL OR constraint_table_ref = constraint_table),
  CHECK (constraint_name_ref IS NULL OR constraint_name_ref = constraint_name)
);
COMMENT ON TABLE graphitron_join_path_step_key IS 'The written foreign key a step of a join path rode: one row per step whose claim names its key. For example {key: "customer_address_id_fkey"} from customer rides customer_address_id_fkey; a key the step inferred is graphitron_join_path_step_inferred_key''s.';
COMMENT ON COLUMN graphitron_join_path_step_key.graph_name IS 'the owning graph''s partition, carried from the step';
COMMENT ON COLUMN graphitron_join_path_step_key.coordinate IS 'the occurrence, as on the step';
COMMENT ON COLUMN graphitron_join_path_step_key.target_type IS 'the need''s target type, as on the step';
COMMENT ON COLUMN graphitron_join_path_step_key.position IS 'the step''s position; with the columns before it, the step';
COMMENT ON COLUMN graphitron_join_path_step_key.constraint_source_name IS 'the catalog partition of the table holding the key';
COMMENT ON COLUMN graphitron_join_path_step_key.constraint_schema IS 'the SQL schema of the table holding the key';
COMMENT ON COLUMN graphitron_join_path_step_key.constraint_table IS 'the table holding the key, the referencing side, whichever way the step rode it';
COMMENT ON COLUMN graphitron_join_path_step_key.constraint_name IS 'the key''s SQL name, with the three columns before it sql_referential_constraint''s key';
COMMENT ON COLUMN graphitron_join_path_step_key.touched_at IS 'when the reading that last took the step ran, as on the step';
COMMENT ON COLUMN graphitron_join_path_step_key.constraint_source_ref IS 'the catalog half of the key''s sql_referential_constraint key, nullable so the key''s removal sets the reference null rather than cascading';
COMMENT ON COLUMN graphitron_join_path_step_key.constraint_schema_ref IS 'the schema half of that key, equal to constraint_schema while the key stands';
COMMENT ON COLUMN graphitron_join_path_step_key.constraint_table_ref IS 'the table half of that key, equal to constraint_table while the key stands';
COMMENT ON COLUMN graphitron_join_path_step_key.constraint_name_ref IS 'the name half of that key, equal to constraint_name while the key stands';

CREATE TABLE graphitron_join_path_step_inferred_key (
  graph_name             VARCHAR   NOT NULL,
  coordinate             VARCHAR   NOT NULL,
  target_type            VARCHAR   NOT NULL,
  position               INT       NOT NULL,
  constraint_source_name VARCHAR   NOT NULL,
  constraint_schema      VARCHAR   NOT NULL,
  constraint_table       VARCHAR   NOT NULL,
  constraint_name        VARCHAR   NOT NULL,
  touched_at             TIMESTAMP NOT NULL,
  constraint_source_ref  VARCHAR,
  constraint_schema_ref  VARCHAR,
  constraint_table_ref   VARCHAR,
  constraint_name_ref    VARCHAR,
  PRIMARY KEY (graph_name, coordinate, target_type, position),
  FOREIGN KEY (graph_name, coordinate, target_type, position)
    REFERENCES graphitron_join_path_step (graph_name, coordinate, target_type, position)
    ON DELETE CASCADE,
  -- The key, through the row's own copy of its key, on the step's terms.
  FOREIGN KEY (constraint_source_ref, constraint_schema_ref, constraint_table_ref,
               constraint_name_ref)
    REFERENCES sql_referential_constraint (source_name, table_schema, table_name, constraint_name)
    ON DELETE SET NULL,
  CHECK (constraint_source_ref IS NULL OR constraint_source_ref = constraint_source_name),
  CHECK (constraint_schema_ref IS NULL OR constraint_schema_ref = constraint_schema),
  CHECK (constraint_table_ref IS NULL OR constraint_table_ref = constraint_table),
  CHECK (constraint_name_ref IS NULL OR constraint_name_ref = constraint_name)
);
COMMENT ON TABLE graphitron_join_path_step_inferred_key IS 'The one foreign key between a step''s two tables, which the step rode where nothing named a key: one row per step whose key is inferred. For example the step from customer to address where nothing is written, or {table: "address"} is, rides customer_address_id_fkey, the one key joining them.';
COMMENT ON COLUMN graphitron_join_path_step_inferred_key.graph_name IS 'the owning graph''s partition, carried from the step';
COMMENT ON COLUMN graphitron_join_path_step_inferred_key.coordinate IS 'the occurrence, as on the step';
COMMENT ON COLUMN graphitron_join_path_step_inferred_key.target_type IS 'the need''s target type, as on the step';
COMMENT ON COLUMN graphitron_join_path_step_inferred_key.position IS 'the step''s position; with the columns before it, the step';
COMMENT ON COLUMN graphitron_join_path_step_inferred_key.constraint_source_name IS 'the catalog partition of the table holding the key';
COMMENT ON COLUMN graphitron_join_path_step_inferred_key.constraint_schema IS 'the SQL schema of the table holding the key';
COMMENT ON COLUMN graphitron_join_path_step_inferred_key.constraint_table IS 'the table holding the key, the referencing side, whichever way the step rode it';
COMMENT ON COLUMN graphitron_join_path_step_inferred_key.constraint_name IS 'the key''s SQL name, with the three columns before it sql_referential_constraint''s key';
COMMENT ON COLUMN graphitron_join_path_step_inferred_key.touched_at IS 'when the reading that last took the step ran, as on the step';
COMMENT ON COLUMN graphitron_join_path_step_inferred_key.constraint_source_ref IS 'the catalog half of the key''s sql_referential_constraint key, nullable so the key''s removal sets the reference null rather than cascading';
COMMENT ON COLUMN graphitron_join_path_step_inferred_key.constraint_schema_ref IS 'the schema half of that key, equal to constraint_schema while the key stands';
COMMENT ON COLUMN graphitron_join_path_step_inferred_key.constraint_table_ref IS 'the table half of that key, equal to constraint_table while the key stands';
COMMENT ON COLUMN graphitron_join_path_step_inferred_key.constraint_name_ref IS 'the name half of that key, equal to constraint_name while the key stands';

CREATE TABLE graphitron_join_path_step_primary_key (
  graph_name        VARCHAR   NOT NULL,
  coordinate        VARCHAR   NOT NULL,
  target_type       VARCHAR   NOT NULL,
  position          INT       NOT NULL,
  table_source_name VARCHAR   NOT NULL,
  table_schema      VARCHAR   NOT NULL,
  table_name        VARCHAR   NOT NULL,
  touched_at        TIMESTAMP NOT NULL,
  table_source_ref  VARCHAR,
  table_schema_ref  VARCHAR,
  table_name_ref    VARCHAR,
  PRIMARY KEY (graph_name, coordinate, target_type, position),
  FOREIGN KEY (graph_name, coordinate, target_type, position)
    REFERENCES graphitron_join_path_step (graph_name, coordinate, target_type, position)
    ON DELETE CASCADE,
  -- The primary key, through the row's own copy of its key, on the step's terms.
  FOREIGN KEY (table_source_ref, table_schema_ref, table_name_ref)
    REFERENCES sql_primary_key (source_name, table_schema, table_name) ON DELETE SET NULL,
  CHECK (table_source_ref IS NULL OR table_source_ref = table_source_name),
  CHECK (table_schema_ref IS NULL OR table_schema_ref = table_schema),
  CHECK (table_name_ref IS NULL OR table_name_ref = table_name)
);
COMMENT ON TABLE graphitron_join_path_step_primary_key IS 'The primary key a step of a join path rode to join a row to itself: one row per step whose {key:} names its table''s own primary key. For example Film.sameRow over @reference(path: [{key: "film_pkey"}]) is one step from film back to film on film_pkey, reading the parent''s own row.';
COMMENT ON COLUMN graphitron_join_path_step_primary_key.graph_name IS 'the owning graph''s partition, carried from the step';
COMMENT ON COLUMN graphitron_join_path_step_primary_key.coordinate IS 'the occurrence, as on the step';
COMMENT ON COLUMN graphitron_join_path_step_primary_key.target_type IS 'the need''s target type, as on the step';
COMMENT ON COLUMN graphitron_join_path_step_primary_key.position IS 'the step''s position; with the columns before it, the step';
COMMENT ON COLUMN graphitron_join_path_step_primary_key.table_source_name IS 'the catalog partition of the table whose primary key the step rode';
COMMENT ON COLUMN graphitron_join_path_step_primary_key.table_schema IS 'the SQL schema of that table';
COMMENT ON COLUMN graphitron_join_path_step_primary_key.table_name IS 'the table whose primary key the step rode, with the two columns before it sql_primary_key''s key';
COMMENT ON COLUMN graphitron_join_path_step_primary_key.touched_at IS 'when the reading that last took the step ran, as on the step';
COMMENT ON COLUMN graphitron_join_path_step_primary_key.table_source_ref IS 'the catalog half of the primary key''s sql_primary_key key, nullable so the key''s removal sets the reference null rather than cascading';
COMMENT ON COLUMN graphitron_join_path_step_primary_key.table_schema_ref IS 'the schema half of that key, equal to table_schema while the key stands';
COMMENT ON COLUMN graphitron_join_path_step_primary_key.table_name_ref IS 'the table half of that key, equal to table_name while the key stands';

CREATE TABLE graphitron_join_path_step_matched_key (
  graph_name        VARCHAR   NOT NULL,
  coordinate        VARCHAR   NOT NULL,
  target_type       VARCHAR   NOT NULL,
  position          INT       NOT NULL,
  table_source_name VARCHAR   NOT NULL,
  table_schema      VARCHAR   NOT NULL,
  table_name        VARCHAR   NOT NULL,
  touched_at        TIMESTAMP NOT NULL,
  table_source_ref  VARCHAR,
  table_schema_ref  VARCHAR,
  table_name_ref    VARCHAR,
  PRIMARY KEY (graph_name, coordinate, target_type, position),
  FOREIGN KEY (graph_name, coordinate, target_type, position)
    REFERENCES graphitron_join_path_step (graph_name, coordinate, target_type, position)
    ON DELETE CASCADE,
  -- The landing's primary key, through the row's own copy of its key, on the step's terms.
  FOREIGN KEY (table_source_ref, table_schema_ref, table_name_ref)
    REFERENCES sql_primary_key (source_name, table_schema, table_name) ON DELETE SET NULL,
  CHECK (table_source_ref IS NULL OR table_source_ref = table_source_name),
  CHECK (table_schema_ref IS NULL OR table_schema_ref = table_schema),
  CHECK (table_name_ref IS NULL OR table_name_ref = table_name)
);
COMMENT ON TABLE graphitron_join_path_step_matched_key IS 'The primary key a step from a routine''s derived table to a table rode, its columns matched by name among the derived table''s: one row per such step. For example Actor.films over @routine(name: "films_for_actor") returning [Film] steps from the function table films_for_actor to film on film_pkey, film_id matched by name.';
COMMENT ON COLUMN graphitron_join_path_step_matched_key.graph_name IS 'the owning graph''s partition, carried from the step';
COMMENT ON COLUMN graphitron_join_path_step_matched_key.coordinate IS 'the occurrence, as on the step';
COMMENT ON COLUMN graphitron_join_path_step_matched_key.target_type IS 'the need''s target type, as on the step';
COMMENT ON COLUMN graphitron_join_path_step_matched_key.position IS 'the step''s position; with the columns before it, the step, which leaves a FUNCTION sql_table';
COMMENT ON COLUMN graphitron_join_path_step_matched_key.table_source_name IS 'the catalog partition of the table the step reaches, whose primary key it rode';
COMMENT ON COLUMN graphitron_join_path_step_matched_key.table_schema IS 'the SQL schema of that table';
COMMENT ON COLUMN graphitron_join_path_step_matched_key.table_name IS 'the table the step reaches, with the two columns before it sql_primary_key''s key; each of its primary-key columns is matched by name to a column of the derived table, the pairs being graphitron_join_path_step_column''s';
COMMENT ON COLUMN graphitron_join_path_step_matched_key.touched_at IS 'when the reading that last took the step ran, as on the step';
COMMENT ON COLUMN graphitron_join_path_step_matched_key.table_source_ref IS 'the catalog half of the primary key''s sql_primary_key key, nullable so the key''s removal sets the reference null rather than cascading';
COMMENT ON COLUMN graphitron_join_path_step_matched_key.table_schema_ref IS 'the schema half of that key, equal to table_schema while the key stands';
COMMENT ON COLUMN graphitron_join_path_step_matched_key.table_name_ref IS 'the table half of that key, equal to table_name while the key stands';

CREATE TABLE graphitron_join_path_step_method (
  graph_name         VARCHAR   NOT NULL,
  coordinate         VARCHAR   NOT NULL,
  target_type        VARCHAR   NOT NULL,
  position           INT       NOT NULL,
  method_source_name VARCHAR   NOT NULL,
  method_class_name  VARCHAR   NOT NULL,
  method_name        VARCHAR   NOT NULL,
  method_descriptor  VARCHAR   NOT NULL,
  touched_at         TIMESTAMP NOT NULL,
  method_source_ref     VARCHAR,
  method_class_ref      VARCHAR,
  method_name_ref       VARCHAR,
  method_descriptor_ref VARCHAR,
  PRIMARY KEY (graph_name, coordinate, target_type, position, method_source_name,
               method_class_name, method_name, method_descriptor),
  FOREIGN KEY (graph_name, coordinate, target_type, position)
    REFERENCES graphitron_join_path_step (graph_name, coordinate, target_type, position)
    ON DELETE CASCADE,
  -- The method, through the row's own copy of its key beside the spelled one the primary key
  -- holds, on the step's terms.
  FOREIGN KEY (method_source_ref, method_class_ref, method_name_ref, method_descriptor_ref)
    REFERENCES code_condition_method (source_name, class_name, method_name, descriptor)
    ON DELETE SET NULL,
  CHECK (method_source_ref IS NULL OR method_source_ref = method_source_name),
  CHECK (method_class_ref IS NULL OR method_class_ref = method_class_name),
  CHECK (method_name_ref IS NULL OR method_name_ref = method_name),
  CHECK (method_descriptor_ref IS NULL OR method_descriptor_ref = method_descriptor)
);
COMMENT ON TABLE graphitron_join_path_step_method IS 'The condition method a step of a join path joins or filters by: one row per step, the one overload whose two table parameters take the step''s from and to table. For example Customer.homeAddress, inherited from Person.homeAddress, calls homeAddress(Customer, Address) where Staff.homeAddress calls homeAddress(Staff, Address).';
COMMENT ON COLUMN graphitron_join_path_step_method.graph_name IS 'the owning graph''s partition, carried from the step';
COMMENT ON COLUMN graphitron_join_path_step_method.coordinate IS 'the occurrence, as on the step';
COMMENT ON COLUMN graphitron_join_path_step_method.target_type IS 'the need''s target type, as on the step';
COMMENT ON COLUMN graphitron_join_path_step_method.position IS 'the step''s position; with the columns before it, the step. A step with column rows is filtered by this method, one without is joined by it';
COMMENT ON COLUMN graphitron_join_path_step_method.method_source_name IS 'the classpath entry the method was read from';
COMMENT ON COLUMN graphitron_join_path_step_method.method_class_name IS 'the class declaring the method';
COMMENT ON COLUMN graphitron_join_path_step_method.method_name IS 'the method';
COMMENT ON COLUMN graphitron_join_path_step_method.method_descriptor IS 'the method''s descriptor; with the three columns before it, code_condition_method''s key';
COMMENT ON COLUMN graphitron_join_path_step_method.touched_at IS 'when the reading that last took the step ran, as on the step';
COMMENT ON COLUMN graphitron_join_path_step_method.method_source_ref IS 'the classpath entry half of the method''s code_condition_method key, nullable so the method''s removal sets the reference null rather than cascading';
COMMENT ON COLUMN graphitron_join_path_step_method.method_class_ref IS 'the class half of that key, equal to method_class_name while the method stands';
COMMENT ON COLUMN graphitron_join_path_step_method.method_name_ref IS 'the name half of that key, equal to method_name while the method stands';
COMMENT ON COLUMN graphitron_join_path_step_method.method_descriptor_ref IS 'the descriptor half of that key, equal to method_descriptor while the method stands';

CREATE TABLE graphitron_join_path_step_routine (
  graph_name          VARCHAR   NOT NULL,
  coordinate          VARCHAR   NOT NULL,
  target_type         VARCHAR   NOT NULL,
  position            INT       NOT NULL,
  routine_source_name VARCHAR   NOT NULL,
  table_schema        VARCHAR   NOT NULL,
  routine_name        VARCHAR   NOT NULL,
  touched_at          TIMESTAMP NOT NULL,
  routine_source_ref  VARCHAR,
  routine_schema_ref  VARCHAR,
  routine_name_ref    VARCHAR,
  PRIMARY KEY (graph_name, coordinate, target_type, position),
  FOREIGN KEY (graph_name, coordinate, target_type, position)
    REFERENCES graphitron_join_path_step (graph_name, coordinate, target_type, position)
    ON DELETE CASCADE,
  -- The routine, through the row's own copy of its key, on the step's terms.
  FOREIGN KEY (routine_source_ref, routine_schema_ref, routine_name_ref)
    REFERENCES sql_routine (source_name, table_schema, routine_name) ON DELETE SET NULL,
  CHECK (routine_source_ref IS NULL OR routine_source_ref = routine_source_name),
  CHECK (routine_schema_ref IS NULL OR routine_schema_ref = table_schema),
  CHECK (routine_name_ref IS NULL OR routine_name_ref = routine_name)
);
COMMENT ON TABLE graphitron_join_path_step_routine IS 'The routine a step of a join path calls: one row per step a @routine element took. For example Actor.films over @routine(name: "films_for_actor") is one step from actor to films_for_actor, calling public.films_for_actor.';
COMMENT ON COLUMN graphitron_join_path_step_routine.graph_name IS 'the owning graph''s partition, carried from the step';
COMMENT ON COLUMN graphitron_join_path_step_routine.coordinate IS 'the occurrence, as on the step';
COMMENT ON COLUMN graphitron_join_path_step_routine.target_type IS 'the need''s target type, as on the step';
COMMENT ON COLUMN graphitron_join_path_step_routine.position IS 'the step''s position; with the columns before it, the step''s key';
COMMENT ON COLUMN graphitron_join_path_step_routine.routine_source_name IS 'the routine''s catalog partition';
COMMENT ON COLUMN graphitron_join_path_step_routine.table_schema IS 'the routine''s SQL schema';
COMMENT ON COLUMN graphitron_join_path_step_routine.routine_name IS 'the routine''s SQL name, with the two columns before it sql_routine''s key; its result is the table the step lands on';
COMMENT ON COLUMN graphitron_join_path_step_routine.touched_at IS 'when the reading that last took the step ran, as on the step';
COMMENT ON COLUMN graphitron_join_path_step_routine.routine_source_ref IS 'the catalog half of the routine''s sql_routine key, nullable so the routine''s removal sets the reference null rather than cascading';
COMMENT ON COLUMN graphitron_join_path_step_routine.routine_schema_ref IS 'the schema half of that key, equal to table_schema while the routine stands';
COMMENT ON COLUMN graphitron_join_path_step_routine.routine_name_ref IS 'the name half of that key, equal to routine_name while the routine stands';

CREATE TABLE graphitron_join_path_step_parameter (
  graph_name         VARCHAR   NOT NULL,
  coordinate         VARCHAR   NOT NULL,
  target_type        VARCHAR   NOT NULL,
  position           INT       NOT NULL,
  parameter_position INT       NOT NULL,
  parameter_name     VARCHAR   NOT NULL,
  from_source_name   VARCHAR,
  from_schema        VARCHAR,
  from_table         VARCHAR,
  from_column        VARCHAR,
  argument           VARCHAR,
  touched_at         TIMESTAMP NOT NULL,
  from_source_ref    VARCHAR,
  from_schema_ref    VARCHAR,
  from_table_ref     VARCHAR,
  from_column_ref    VARCHAR,
  PRIMARY KEY (graph_name, coordinate, target_type, position, parameter_position),
  FOREIGN KEY (graph_name, coordinate, target_type, position)
    REFERENCES graphitron_join_path_step_routine (graph_name, coordinate, target_type, position)
    ON DELETE CASCADE,
  -- The column, where the parameter is one, through the row's own copy of its key, on the step's
  -- terms.
  FOREIGN KEY (from_source_ref, from_schema_ref, from_table_ref, from_column_ref)
    REFERENCES sql_column (source_name, table_schema, table_name, column_name) ON DELETE SET NULL,
  CHECK (from_source_ref IS NULL OR from_source_ref = from_source_name),
  CHECK (from_schema_ref IS NULL OR from_schema_ref = from_schema),
  CHECK (from_table_ref IS NULL OR from_table_ref = from_table),
  CHECK (from_column_ref IS NULL OR from_column_ref = from_column),
  -- A parameter is bound from one place: a column of the table the step departs, or an argument.
  CHECK ((from_column IS NULL) <> (argument IS NULL)),
  CHECK (parameter_position >= 0)
);
COMMENT ON TABLE graphitron_join_path_step_parameter IS 'Where a routine step''s parameter takes its value: one row per step and parameter, a column of the table the step departs or an argument of the field. For example Actor.films over @routine(name: "films_for_actor", argMapping: "pActorId: $source.actor_id, pMinLength: minLength") binds pActorId from actor.actor_id and pMinLength from the argument minLength.';
COMMENT ON COLUMN graphitron_join_path_step_parameter.graph_name IS 'the owning graph''s partition, carried from the step';
COMMENT ON COLUMN graphitron_join_path_step_parameter.coordinate IS 'the occurrence, as on the step';
COMMENT ON COLUMN graphitron_join_path_step_parameter.target_type IS 'the need''s target type, as on the step';
COMMENT ON COLUMN graphitron_join_path_step_parameter.position IS 'the routine step''s position; with the columns before it, the routine step this parameter belongs to';
COMMENT ON COLUMN graphitron_join_path_step_parameter.parameter_position IS 'the parameter''s position in the routine''s call, as sql_routine_parameter numbers it';
COMMENT ON COLUMN graphitron_join_path_step_parameter.parameter_name IS 'the parameter''s name in the generated call, the name a mapping writes';
COMMENT ON COLUMN graphitron_join_path_step_parameter.from_source_name IS 'where the parameter is a column: the catalog partition of the table the step departs';
COMMENT ON COLUMN graphitron_join_path_step_parameter.from_schema IS 'where the parameter is a column: that table''s SQL schema';
COMMENT ON COLUMN graphitron_join_path_step_parameter.from_table IS 'where the parameter is a column: the table the step departs';
COMMENT ON COLUMN graphitron_join_path_step_parameter.from_column IS 'where the parameter is a column: the column, so the call is made once per row of that table; NULL where it is an argument';
COMMENT ON COLUMN graphitron_join_path_step_parameter.argument IS 'where the parameter is an argument: the argument path its name reads, an argument''s name or a dot path into an input, the parameter''s own name where nothing was written for it; NULL where it is a column';
COMMENT ON COLUMN graphitron_join_path_step_parameter.touched_at IS 'when the reading that last took the step ran, as on the step';
COMMENT ON COLUMN graphitron_join_path_step_parameter.from_source_ref IS 'the catalog half of the column''s sql_column key, nullable so the column''s removal sets the reference null rather than cascading; NULL where the parameter is an argument';
COMMENT ON COLUMN graphitron_join_path_step_parameter.from_schema_ref IS 'the schema half of that key, equal to from_schema while the column stands';
COMMENT ON COLUMN graphitron_join_path_step_parameter.from_table_ref IS 'the table half of that key, equal to from_table while the column stands';
COMMENT ON COLUMN graphitron_join_path_step_parameter.from_column_ref IS 'the name half of that key, equal to from_column while the column stands';

CREATE TABLE graphitron_join_path_stop (
  graph_name    VARCHAR   NOT NULL,
  coordinate    VARCHAR   NOT NULL,
  target_type   VARCHAR   NOT NULL,
  position      INT       NOT NULL,
  element_place INT,
  moves         INT       NOT NULL,
  touched_at    TIMESTAMP NOT NULL,
  PRIMARY KEY (graph_name, coordinate, target_type),
  FOREIGN KEY (graph_name, coordinate, target_type)
    REFERENCES graphitron_path_need (graph_name, coordinate, target_type) ON DELETE CASCADE,
  CHECK (position >= 0),
  CHECK (element_place >= 0),
  CHECK (moves <> 1 AND moves >= 0)
);
COMMENT ON TABLE graphitron_join_path_stop IS 'One need whose join path stopped short: one row per need whose path met a step it could not take, with where and how many moves it found there. For example {key: "film_actor_actor_id_fkey"} written on a Film field stops the path from film at position 0, no move leaving film.';
COMMENT ON COLUMN graphitron_join_path_stop.graph_name IS 'the owning graph''s partition, carried from the need';
COMMENT ON COLUMN graphitron_join_path_stop.coordinate IS 'the occurrence whose need stopped';
COMMENT ON COLUMN graphitron_join_path_stop.target_type IS 'the type the need reaches; with the two columns before it, the need''s key, one stop per need';
COMMENT ON COLUMN graphitron_join_path_stop.position IS 'the position at which the path could not take its next step: the first position with no row in graphitron_join_path_step for this need, the steps before it being the ones taken';
COMMENT ON COLUMN graphitron_join_path_stop.element_place IS 'the place of the written element there in the list of the claim the path follows, as graphitron_ast_path_entry numbers it, which is where a defect about the stop is reported; NULL where no element was written, as for an inferred step';
COMMENT ON COLUMN graphitron_join_path_stop.moves IS 'how many moves were found from where the path stood: none, where nothing leads on, or several, where more than one way does; never one, one being a step';
COMMENT ON COLUMN graphitron_join_path_stop.touched_at IS 'when the reading that last stopped here ran: the mark the sweep reads';


CREATE VIEW graphitron_join_path_claimed_rule
  (graph_name, coordinate, target_type, claim_coordinate, claim_target_type, origin) AS
-- An output field's needs, each with the field it is an occurrence of.
WITH need (graph_name, coordinate, target_type, element_coordinate, type_name, field_name) AS (
  SELECT n.graph_name, n.coordinate, n.target_type, f.coordinate, f.type_name, f.field_name
    FROM graphitron_path_need n
    JOIN graphitron_occurrence o
      ON o.graph_name = n.graph_name AND o.coordinate = n.coordinate AND o.kind = 'FIELD'
    JOIN graphitron_field f
      ON f.graph_name = o.graph_name AND f.coordinate = o.element_coordinate
),
-- An argument's or input field's needs, each with the element it is an occurrence of.
slot_need (graph_name, coordinate, target_type, element_coordinate) AS (
  SELECT n.graph_name, n.coordinate, n.target_type, o.element_coordinate
    FROM graphitron_path_need n
    JOIN graphitron_occurrence o
      ON o.graph_name = n.graph_name AND o.coordinate = n.coordinate
     AND o.kind IN ('FIELD_ARGUMENT', 'INPUT_FIELD')
),
-- Each claim an interface's same-named field makes for a need of an implementation: its
-- @referenceFor naming the need's type first, else its field claim where that walks to the type,
-- the type itself or a member of the single-table interface it targets. Only where the field's own
-- declaration claims nothing covering the need.
inherited (graph_name, coordinate, target_type, interface_name, claim_coordinate,
           claim_target_type) AS (
  SELECT n.graph_name, n.coordinate, n.target_type, ii.interface_name,
         COALESCE(irf.element_coordinate, ifc.element_coordinate),
         COALESCE(irf.target_type, ifc.target_type)
    FROM need n
    JOIN graphql_implements_interface ii
      ON ii.graph_name = n.graph_name AND ii.type_name = n.type_name
    JOIN graphitron_field inf
      ON inf.graph_name = ii.graph_name AND inf.type_name = ii.interface_name
     AND inf.field_name = n.field_name
    LEFT JOIN graphitron_join_path_claim irf
      ON irf.graph_name = inf.graph_name AND irf.element_coordinate = inf.coordinate
     AND irf.claim_kind = 'REFERENCE_FOR' AND irf.target_type = n.target_type
    LEFT JOIN graphitron_join_path_claim ifc
      ON ifc.graph_name = inf.graph_name AND ifc.element_coordinate = inf.coordinate
     AND ifc.claim_kind = 'FIELD'
     AND (ifc.target_type = n.target_type
          OR EXISTS (SELECT 1 FROM graphitron_tabletype it
                       JOIN graphql_implements_interface im
                         ON im.graph_name = it.graph_name AND im.interface_name = it.type_name
                      WHERE it.graph_name = ifc.graph_name AND it.type_name = ifc.target_type
                        AND im.type_name = n.target_type))
   WHERE (irf.graph_name IS NOT NULL OR ifc.graph_name IS NOT NULL)
     AND NOT EXISTS (SELECT 1 FROM graphitron_join_path_claim own
                      WHERE own.graph_name = n.graph_name
                        AND own.element_coordinate = n.element_coordinate
                        AND (own.claim_kind <> 'REFERENCE_FOR' OR own.target_type = n.target_type))
)
-- The field's own @referenceFor naming the need's type.
SELECT n.graph_name, n.coordinate, n.target_type, rf.element_coordinate, rf.target_type, 'WRITTEN'
  FROM need n
  JOIN graphitron_join_path_claim rf
    ON rf.graph_name = n.graph_name AND rf.element_coordinate = n.element_coordinate
   AND rf.claim_kind = 'REFERENCE_FOR' AND rf.target_type = n.target_type
UNION ALL
-- Else its own field claim, where it walks to the need's type: the field's target itself, or a
-- member of the single-table interface it targets. On a union or a multi-table interface it covers
-- the members and walks to none.
SELECT n.graph_name, n.coordinate, n.target_type, fc.element_coordinate, fc.target_type, 'WRITTEN'
  FROM need n
  JOIN graphitron_join_path_claim fc
    ON fc.graph_name = n.graph_name AND fc.element_coordinate = n.element_coordinate
   AND fc.claim_kind = 'FIELD'
 WHERE (fc.target_type = n.target_type
        OR EXISTS (SELECT 1 FROM graphitron_tabletype it
                     JOIN graphql_implements_interface im
                       ON im.graph_name = it.graph_name AND im.interface_name = it.type_name
                    WHERE it.graph_name = fc.graph_name AND it.type_name = fc.target_type
                      AND im.type_name = n.target_type))
   AND NOT EXISTS (SELECT 1 FROM graphitron_join_path_claim rf
                    WHERE rf.graph_name = n.graph_name AND rf.element_coordinate = n.element_coordinate
                      AND rf.claim_kind = 'REFERENCE_FOR' AND rf.target_type = n.target_type)
UNION ALL
-- Else the one claim inherited: an interface extending another overrides it, and two interfaces
-- neither extending the other leave none, which INHERITED_PATH_AMBIGUOUS reports.
SELECT i.graph_name, i.coordinate, i.target_type, MIN(i.claim_coordinate),
       MIN(i.claim_target_type), 'INHERITED'
  FROM inherited i
 WHERE NOT EXISTS (SELECT 1 FROM inherited j
                     JOIN graphql_implements_interface x
                       ON x.graph_name = j.graph_name AND x.type_name = j.interface_name
                      AND x.interface_name = i.interface_name
                    WHERE j.graph_name = i.graph_name AND j.coordinate = i.coordinate
                      AND j.target_type = i.target_type)
 GROUP BY i.graph_name, i.coordinate, i.target_type
HAVING COUNT(*) = 1
UNION ALL
-- An argument's or input field's own @referenceFor naming the need's type. Nothing is inherited at
-- an argument or input field.
SELECT s.graph_name, s.coordinate, s.target_type, rf.element_coordinate, rf.target_type, 'WRITTEN'
  FROM slot_need s
  JOIN graphitron_join_path_claim rf
    ON rf.graph_name = s.graph_name AND rf.element_coordinate = s.element_coordinate
   AND rf.claim_kind = 'REFERENCE_FOR' AND rf.target_type = s.target_type
UNION ALL
-- Else its own @reference, matched by the element alone: that claim reaches the declared type, a
-- scalar or an input type, and not the type the need reaches.
SELECT s.graph_name, s.coordinate, s.target_type, c.element_coordinate, c.target_type, 'WRITTEN'
  FROM slot_need s
  JOIN graphitron_join_path_claim c
    ON c.graph_name = s.graph_name AND c.element_coordinate = s.element_coordinate
   AND c.claim_kind IN ('ARGUMENT', 'INPUT_FIELD')
 WHERE NOT EXISTS (SELECT 1 FROM graphitron_join_path_claim rf
                    WHERE rf.graph_name = s.graph_name AND rf.element_coordinate = s.element_coordinate
                      AND rf.claim_kind = 'REFERENCE_FOR' AND rf.target_type = s.target_type);
COMMENT ON VIEW graphitron_join_path_claimed_rule IS 'The claim a need follows: one row per need of an occurrence that a claim covers and walks to, with the claim and whether it is the element''s own or inherited. For example Staff.homeAddress, writing nothing, follows (Person.homeAddress, Address) as INHERITED, Store.people''s need for Staff follows its own @referenceFor, (Store.people, Staff), and an argument writing @reference follows its own claim for every type its field reaches.';
-- COMMENT ON COLUMN graphitron_join_path_claimed_rule.graph_name IS 'the owning graph''s partition, carried from the need';
-- COMMENT ON COLUMN graphitron_join_path_claimed_rule.coordinate IS 'the occurrence whose need this is: a field, an argument or an input field';
-- COMMENT ON COLUMN graphitron_join_path_claimed_rule.target_type IS 'the type the need reaches; with the two columns before it, the need''s key';
-- COMMENT ON COLUMN graphitron_join_path_claimed_rule.claim_coordinate IS 'the declared element the followed claim is written on: the element itself, or an interface''s same-named field';
-- COMMENT ON COLUMN graphitron_join_path_claimed_rule.claim_target_type IS 'the type the followed claim reaches; with the coordinate before it, the claim''s key';
-- COMMENT ON COLUMN graphitron_join_path_claimed_rule.origin IS 'WRITTEN for the element''s own claim and INHERITED for an interface field''s, as graphitron_path.origin takes it';

CREATE VIEW graphitron_join_path_step_rule
  (graph_name, claim_coordinate, claim_target_type, position, element_place,
   element_source_name, element_line, element_column, as_name, resolved, last_element,
   from_source_name, from_schema, from_table, to_source_name, to_schema, to_table, move,
   constraint_source_name, constraint_schema, constraint_table, constraint_name, fk_on_from,
   routine_source_name, routine_schema, routine_name) AS
-- Each claim on a field or an input field: where it was written, which of its places the path starts at, a
-- root field's leading @routine being its producer's call and so no step, whether the field reads
-- one row, which is the way a key from a table to itself is ridden, and whether it is a mutation's,
-- which never takes the step after a routine: the write's statement holds its locks, so nothing is
-- joined onward in it, and what the write returns is lifted onto its table's rows, or read off by a
-- payload's data field, in a statement of its own. The flags are CASE expressions rather than bare
-- EXISTS: H2 pushes a predicate onto a view's boolean column and writes one over a bare EXISTS it
-- cannot parse back.
WITH claim (graph_name, claim_coordinate, claim_target_type, source_name, anchor_line,
            anchor_column, first_place, single_valued, on_mutation) AS (
  SELECT c.graph_name, c.element_coordinate, c.target_type, c.source_name, c.source_line,
         c.source_column,
         c.first_place,
         CASE WHEN NOT (f.is_list OR nv.wrapper_type_name IS NOT NULL) OR nt.kind IN ('SCALAR', 'ENUM')
              THEN TRUE ELSE FALSE END,
         CASE WHEN ro.operation = 'MUTATION' THEN TRUE ELSE FALSE END
    FROM graphitron_join_path_claim c
    JOIN graphitron_field f
      ON f.graph_name = c.graph_name AND f.coordinate = c.element_coordinate
    JOIN graphitron_field_target nv
      ON nv.graph_name = f.graph_name AND nv.type_name = f.type_name AND nv.field_name = f.field_name
    JOIN graphitron_type nt ON nt.graph_name = f.graph_name AND nt.type_name = f.named_type
    LEFT JOIN graphql_root_operation ro ON ro.graph_name = f.graph_name AND ro.type_name = f.type_name
   UNION ALL
  -- Each claim on an argument, its path starting at its first place, read as a field reading one
  -- row where the argument holds one value.
  SELECT c.graph_name, c.element_coordinate, c.target_type, c.source_name, c.source_line,
         c.source_column, 0,
         CASE WHEN NOT a.is_list OR at.kind IN ('SCALAR', 'ENUM') THEN TRUE ELSE FALSE END,
         FALSE
    FROM graphitron_join_path_claim c
    JOIN graphitron_argument a
      ON a.graph_name = c.graph_name AND a.coordinate = c.element_coordinate
    JOIN graphitron_type at ON at.graph_name = a.graph_name AND at.type_name = a.named_type
),
-- Each written element from the path's first place on, at the position its step takes, with
-- whether it is the claim's only element and whether it names a key or a table.
element (graph_name, claim_coordinate, claim_target_type, position, place, source_name,
         element_line, element_column, as_name, single_valued, last_element, sole, has_key,
         has_table) AS (
  SELECT cl.graph_name, cl.claim_coordinate, cl.claim_target_type, e.place - cl.first_place,
         e.place, e.source_name, e.element_line, e.element_column, e.as_name, cl.single_valued,
         CASE WHEN NOT EXISTS (SELECT 1 FROM graphitron_ast_path_entry e1
                                WHERE e1.graph_name = e.graph_name AND e1.source_name = e.source_name
                                  AND e1.anchor_line = e.anchor_line
                                  AND e1.anchor_column = e.anchor_column AND e1.place = e.place + 1)
              THEN TRUE ELSE FALSE END,
         CASE WHEN e.place = 0
                   AND NOT EXISTS (SELECT 1 FROM graphitron_ast_path_entry e1
                                    WHERE e1.graph_name = e.graph_name AND e1.source_name = e.source_name
                                      AND e1.anchor_line = e.anchor_line
                                      AND e1.anchor_column = e.anchor_column AND e1.place = 1)
              THEN TRUE ELSE FALSE END,
         CASE WHEN EXISTS (SELECT 1 FROM graphitron_path_element_key k
                            WHERE k.graph_name = e.graph_name AND k.source_name = e.source_name
                              AND k.source_line = e.element_line AND k.source_column = e.element_column)
                OR EXISTS (SELECT 1 FROM graphitron_path_element_primary_key pk
                            WHERE pk.graph_name = e.graph_name AND pk.source_name = e.source_name
                              AND pk.source_line = e.element_line
                              AND pk.source_column = e.element_column)
              THEN TRUE ELSE FALSE END,
         CASE WHEN EXISTS (SELECT 1 FROM graphitron_path_element_table t
                            WHERE t.graph_name = e.graph_name AND t.source_name = e.source_name
                              AND t.source_line = e.element_line AND t.source_column = e.element_column)
              THEN TRUE ELSE FALSE END
    FROM claim cl
    JOIN graphitron_ast_path_entry e
      ON e.graph_name = cl.graph_name AND e.source_name = cl.source_name
     AND e.anchor_line = cl.anchor_line AND e.anchor_column = cl.anchor_column
     AND e.place >= cl.first_place
)
-- The element itself, with no destination, whether or not it allows a move: what a stop reports,
-- with whether the element names anything. A @routine moves from wherever the path stands, so one
-- with no move names no routine with a generated call.
SELECT el.graph_name, el.claim_coordinate, el.claim_target_type, el.position, el.place,
       el.source_name, el.element_line, el.element_column, el.as_name,
       CASE WHEN el.has_key OR el.has_table
              OR EXISTS (SELECT 1 FROM graphitron_path_element_method m
                          WHERE m.graph_name = el.graph_name AND m.source_name = el.source_name
                            AND m.source_line = el.element_line
                            AND m.source_column = el.element_column)
            THEN TRUE ELSE FALSE END,
       el.last_element,
       CAST(NULL AS VARCHAR), CAST(NULL AS VARCHAR), CAST(NULL AS VARCHAR),
       CAST(NULL AS VARCHAR), CAST(NULL AS VARCHAR), CAST(NULL AS VARCHAR), CAST(NULL AS VARCHAR),
       CAST(NULL AS VARCHAR), CAST(NULL AS VARCHAR), CAST(NULL AS VARCHAR), CAST(NULL AS VARCHAR),
       CAST(NULL AS BOOLEAN), CAST(NULL AS VARCHAR), CAST(NULL AS VARCHAR), CAST(NULL AS VARCHAR)
  FROM element el
UNION ALL
-- A written key ridden away from its declaring table; one from a table to itself only where the
-- field reads one row.
SELECT el.graph_name, el.claim_coordinate, el.claim_target_type, el.position, el.place,
       el.source_name, el.element_line, el.element_column, el.as_name, CAST(NULL AS BOOLEAN), CAST(NULL AS BOOLEAN),
       rc.source_name, rc.table_schema, rc.table_name,
       rc.referenced_source_name, rc.referenced_schema, rc.referenced_table, 'KEY',
       rc.source_name, rc.table_schema, rc.table_name, rc.constraint_name, TRUE,
       CAST(NULL AS VARCHAR), CAST(NULL AS VARCHAR), CAST(NULL AS VARCHAR)
  FROM element el
  JOIN graphitron_path_element_key k
    ON k.graph_name = el.graph_name AND k.source_name = el.source_name
   AND k.source_line = el.element_line AND k.source_column = el.element_column
  JOIN sql_referential_constraint rc
    ON rc.source_name = k.constraint_source_name AND rc.table_schema = k.constraint_schema
   AND rc.table_name = k.constraint_table AND rc.constraint_name = k.constraint_name
 WHERE NOT (rc.source_name = rc.referenced_source_name AND rc.table_schema = rc.referenced_schema
            AND rc.table_name = rc.referenced_table)
    OR el.single_valued
UNION ALL
-- The same key ridden toward its declaring table; one from a table to itself only where the field
-- reads many rows.
SELECT el.graph_name, el.claim_coordinate, el.claim_target_type, el.position, el.place,
       el.source_name, el.element_line, el.element_column, el.as_name, CAST(NULL AS BOOLEAN), CAST(NULL AS BOOLEAN),
       rc.referenced_source_name, rc.referenced_schema, rc.referenced_table,
       rc.source_name, rc.table_schema, rc.table_name, 'KEY',
       rc.source_name, rc.table_schema, rc.table_name, rc.constraint_name, FALSE,
       CAST(NULL AS VARCHAR), CAST(NULL AS VARCHAR), CAST(NULL AS VARCHAR)
  FROM element el
  JOIN graphitron_path_element_key k
    ON k.graph_name = el.graph_name AND k.source_name = el.source_name
   AND k.source_line = el.element_line AND k.source_column = el.element_column
  JOIN sql_referential_constraint rc
    ON rc.source_name = k.constraint_source_name AND rc.table_schema = k.constraint_schema
   AND rc.table_name = k.constraint_table AND rc.constraint_name = k.constraint_name
 WHERE NOT (rc.source_name = rc.referenced_source_name AND rc.table_schema = rc.referenced_schema
            AND rc.table_name = rc.referenced_table)
    OR NOT el.single_valued
UNION ALL
-- A table's own primary key, joining each row to itself: the claim's only element, on a field
-- reading one row.
SELECT el.graph_name, el.claim_coordinate, el.claim_target_type, el.position, el.place,
       el.source_name, el.element_line, el.element_column, el.as_name, CAST(NULL AS BOOLEAN), CAST(NULL AS BOOLEAN),
       pk.table_source_name, pk.table_schema, pk.table_name,
       pk.table_source_name, pk.table_schema, pk.table_name, 'PRIMARY_KEY',
       CAST(NULL AS VARCHAR), CAST(NULL AS VARCHAR), CAST(NULL AS VARCHAR), CAST(NULL AS VARCHAR),
       CAST(NULL AS BOOLEAN), CAST(NULL AS VARCHAR), CAST(NULL AS VARCHAR), CAST(NULL AS VARCHAR)
  FROM element el
  JOIN graphitron_path_element_primary_key pk
    ON pk.graph_name = el.graph_name AND pk.source_name = el.source_name
   AND pk.source_line = el.element_line AND pk.source_column = el.element_column
 WHERE el.sole AND el.single_valued
UNION ALL
-- A table, reached over each foreign key it declares toward the table the path stands at.
SELECT el.graph_name, el.claim_coordinate, el.claim_target_type, el.position, el.place,
       el.source_name, el.element_line, el.element_column, el.as_name, CAST(NULL AS BOOLEAN), CAST(NULL AS BOOLEAN),
       rc.referenced_source_name, rc.referenced_schema, rc.referenced_table,
       t.table_source_name, t.table_schema, t.table_name, 'INFERRED_KEY',
       rc.source_name, rc.table_schema, rc.table_name, rc.constraint_name, FALSE,
       CAST(NULL AS VARCHAR), CAST(NULL AS VARCHAR), CAST(NULL AS VARCHAR)
  FROM element el
  JOIN graphitron_path_element_table t
    ON t.graph_name = el.graph_name AND t.source_name = el.source_name
   AND t.source_line = el.element_line AND t.source_column = el.element_column
  JOIN sql_referential_constraint rc
    ON rc.source_name = t.table_source_name AND rc.table_schema = t.table_schema
   AND rc.table_name = t.table_name
 WHERE NOT el.has_key
   AND (NOT (rc.source_name = rc.referenced_source_name AND rc.table_schema = rc.referenced_schema
             AND rc.table_name = rc.referenced_table)
        OR NOT el.single_valued)
UNION ALL
-- A table, reached over each foreign key the table the path stands at declares toward it.
SELECT el.graph_name, el.claim_coordinate, el.claim_target_type, el.position, el.place,
       el.source_name, el.element_line, el.element_column, el.as_name, CAST(NULL AS BOOLEAN), CAST(NULL AS BOOLEAN),
       rc.source_name, rc.table_schema, rc.table_name,
       t.table_source_name, t.table_schema, t.table_name, 'INFERRED_KEY',
       rc.source_name, rc.table_schema, rc.table_name, rc.constraint_name, TRUE,
       CAST(NULL AS VARCHAR), CAST(NULL AS VARCHAR), CAST(NULL AS VARCHAR)
  FROM element el
  JOIN graphitron_path_element_table t
    ON t.graph_name = el.graph_name AND t.source_name = el.source_name
   AND t.source_line = el.element_line AND t.source_column = el.element_column
  JOIN sql_referential_constraint rc
    ON rc.referenced_source_name = t.table_source_name AND rc.referenced_schema = t.table_schema
   AND rc.referenced_table = t.table_name
 WHERE NOT el.has_key
   AND (NOT (rc.source_name = rc.referenced_source_name AND rc.table_schema = rc.referenced_schema
             AND rc.table_name = rc.referenced_table)
        OR el.single_valued)
UNION ALL
-- A table, reached from a function's derived table by the named table's primary key, its columns
-- matched by name among the derived table's.
SELECT DISTINCT el.graph_name, el.claim_coordinate, el.claim_target_type, el.position, el.place,
       el.source_name, el.element_line, el.element_column, el.as_name, CAST(NULL AS BOOLEAN), CAST(NULL AS BOOLEAN),
       n.source_name, n.table_schema, n.table_name,
       t.table_source_name, t.table_schema, t.table_name, 'MATCHED_KEY',
       CAST(NULL AS VARCHAR), CAST(NULL AS VARCHAR), CAST(NULL AS VARCHAR), CAST(NULL AS VARCHAR),
       CAST(NULL AS BOOLEAN), CAST(NULL AS VARCHAR), CAST(NULL AS VARCHAR), CAST(NULL AS VARCHAR)
  FROM element el
  JOIN graphitron_path_element_table t
    ON t.graph_name = el.graph_name AND t.source_name = el.source_name
   AND t.source_line = el.element_line AND t.source_column = el.element_column
  JOIN sql_name_matched_key_column n
    ON n.to_source_name = t.table_source_name AND n.to_schema = t.table_schema
   AND n.to_table = t.table_name
 WHERE NOT el.has_key
UNION ALL
-- A @routine: a call made from whichever table the path stands at, landing on its function's
-- derived table, one move per routine the element names.
SELECT el.graph_name, el.claim_coordinate, el.claim_target_type, el.position, el.place,
       el.source_name, el.element_line, el.element_column, el.as_name, CAST(NULL AS BOOLEAN), CAST(NULL AS BOOLEAN),
       CAST(NULL AS VARCHAR), CAST(NULL AS VARCHAR), CAST(NULL AS VARCHAR),
       fn.source_name, fn.table_schema, fn.table_name, 'ROUTINE',
       CAST(NULL AS VARCHAR), CAST(NULL AS VARCHAR), CAST(NULL AS VARCHAR), CAST(NULL AS VARCHAR),
       CAST(NULL AS BOOLEAN), er.routine_source_name, er.table_schema, er.routine_name
  FROM element el
  JOIN graphitron_path_element_routine er
    ON er.graph_name = el.graph_name AND er.source_name = el.source_name
   AND er.source_line = el.element_line AND er.source_column = el.element_column
  JOIN sql_table fn
    ON fn.source_name = er.routine_source_name AND fn.table_schema = er.table_schema
   AND fn.table_name = er.routine_name
UNION ALL
-- A condition alone: its method's second parameter names where it lands, one move per table it
-- names, and its first, where it names a table, is the only table it departs; a first parameter
-- naming no table departs any.
SELECT DISTINCT el.graph_name, el.claim_coordinate, el.claim_target_type, el.position, el.place,
       el.source_name, el.element_line, el.element_column, el.as_name, CAST(NULL AS BOOLEAN), CAST(NULL AS BOOLEAN),
       d.source_name, d.table_schema, d.table_name,
       arrives.source_name, arrives.table_schema, arrives.table_name, 'METHOD',
       CAST(NULL AS VARCHAR), CAST(NULL AS VARCHAR), CAST(NULL AS VARCHAR), CAST(NULL AS VARCHAR),
       CAST(NULL AS BOOLEAN), CAST(NULL AS VARCHAR), CAST(NULL AS VARCHAR), CAST(NULL AS VARCHAR)
  FROM element el
  JOIN graphitron_path_element_method pm
    ON pm.graph_name = el.graph_name AND pm.source_name = el.source_name
   AND pm.source_line = el.element_line AND pm.source_column = el.element_column
  JOIN code_method_parameter ap
    ON ap.source_name = pm.method_source_name AND ap.class_name = pm.method_class_name
   AND ap.method_name = pm.method_name AND ap.descriptor = pm.method_descriptor AND ap.position = 1
  JOIN store_graph_source am ON am.graph_name = el.graph_name
  JOIN sql_table arrives ON arrives.source_name = am.source_name AND arrives.class_fqn = ap.erased_class
  LEFT JOIN code_method_parameter dp
    ON dp.source_name = pm.method_source_name AND dp.class_name = pm.method_class_name
   AND dp.method_name = pm.method_name AND dp.descriptor = pm.method_descriptor AND dp.position = 0
  LEFT JOIN sql_table d ON d.source_name = am.source_name AND d.class_fqn = dp.erased_class
 WHERE NOT el.has_key AND NOT el.has_table
UNION ALL
-- The step no element writes: where a read's written path has ended on a function's derived table
-- and the claim reaches a @table type, from the derived table to that table by its primary key's
-- columns matched by name. A derived table exposing none of them leaves the path on the function.
SELECT DISTINCT cl.graph_name, cl.claim_coordinate, cl.claim_target_type,
       e.place + 1 - cl.first_place, CAST(NULL AS INT), CAST(NULL AS VARCHAR), CAST(NULL AS INT),
       CAST(NULL AS INT), CAST(NULL AS VARCHAR), CAST(NULL AS BOOLEAN), CAST(NULL AS BOOLEAN),
       n.source_name, n.table_schema, n.table_name,
       b.table_source_name, b.table_schema, b.table_name, 'MATCHED_KEY',
       CAST(NULL AS VARCHAR), CAST(NULL AS VARCHAR), CAST(NULL AS VARCHAR), CAST(NULL AS VARCHAR),
       CAST(NULL AS BOOLEAN), CAST(NULL AS VARCHAR), CAST(NULL AS VARCHAR), CAST(NULL AS VARCHAR)
  FROM claim cl
  JOIN graphitron_ast_path_entry e
    ON e.graph_name = cl.graph_name AND e.source_name = cl.source_name
   AND e.anchor_line = cl.anchor_line AND e.anchor_column = cl.anchor_column
  JOIN graphitron_tabletype b
    ON b.graph_name = cl.graph_name AND b.type_name = cl.claim_target_type
  JOIN sql_name_matched_key_column n
    ON n.to_source_name = b.table_source_name AND n.to_schema = b.table_schema
   AND n.to_table = b.table_name
 WHERE NOT cl.on_mutation
   AND NOT EXISTS (SELECT 1 FROM graphitron_ast_path_entry nx
                    WHERE nx.graph_name = e.graph_name AND nx.source_name = e.source_name
                      AND nx.anchor_line = e.anchor_line AND nx.anchor_column = e.anchor_column
                      AND nx.place = e.place + 1);
COMMENT ON VIEW graphitron_join_path_step_rule IS 'A move one written element of a claim allows from a table: one row per claim, position, departure and move, and one row per element with no destination. For example {key: "customer_address_id_fkey"} on Customer.address allows customer to address, and {table: "language"} on a Film field allows film to language over each of film''s two keys.';
-- COMMENT ON COLUMN graphitron_join_path_step_rule.graph_name IS 'the owning graph''s partition, carried from the claim';
-- COMMENT ON COLUMN graphitron_join_path_step_rule.claim_coordinate IS 'the declared element the claim is written on';
-- COMMENT ON COLUMN graphitron_join_path_step_rule.claim_target_type IS 'the type the claim reaches; with the coordinate before it, the claim''s key';
-- COMMENT ON COLUMN graphitron_join_path_step_rule.position IS 'the position of the step the move takes: the element''s place, less one on a root field whose first element is its producer''s @routine';
-- COMMENT ON COLUMN graphitron_join_path_step_rule.element_place IS 'the element''s place in the claim''s written list, as graphitron_ast_path_entry numbers it; NULL for the step after a routine, which no element writes';
-- COMMENT ON COLUMN graphitron_join_path_step_rule.element_source_name IS 'the file the element was written in; NULL where no element writes the move';
-- COMMENT ON COLUMN graphitron_join_path_step_rule.element_line IS 'the element''s source line';
-- COMMENT ON COLUMN graphitron_join_path_step_rule.element_column IS 'the element''s source column';
-- COMMENT ON COLUMN graphitron_join_path_step_rule.as_name IS 'the element''s as: name, where it has one';
-- COMMENT ON COLUMN graphitron_join_path_step_rule.resolved IS 'on the element''s row with no destination, whether it names a key, a table or a condition method that resolved; NULL on a move';
-- COMMENT ON COLUMN graphitron_join_path_step_rule.last_element IS 'on the element''s row with no destination, whether it is the last its claim writes; NULL on a move';
-- COMMENT ON COLUMN graphitron_join_path_step_rule.from_source_name IS 'the catalog partition of the table the move departs; NULL where it departs any';
-- COMMENT ON COLUMN graphitron_join_path_step_rule.from_schema IS 'the departure''s SQL schema';
-- COMMENT ON COLUMN graphitron_join_path_step_rule.from_table IS 'the table the move departs; NULL where the move departs any, a @routine or a condition whose first parameter names no table';
-- COMMENT ON COLUMN graphitron_join_path_step_rule.to_source_name IS 'the catalog partition of the table the move arrives at';
-- COMMENT ON COLUMN graphitron_join_path_step_rule.to_schema IS 'the arrival''s SQL schema';
-- COMMENT ON COLUMN graphitron_join_path_step_rule.to_table IS 'the table the move arrives at; NULL on the element''s own row, which is no move';
-- COMMENT ON COLUMN graphitron_join_path_step_rule.move IS 'how the move joins: KEY a written foreign key, INFERRED_KEY a foreign key a table element rides, PRIMARY_KEY the self-join, MATCHED_KEY a primary key matched by name from a derived table, ROUTINE a call, METHOD a condition alone';
-- COMMENT ON COLUMN graphitron_join_path_step_rule.constraint_source_name IS 'the ridden foreign key''s catalog partition, for KEY and INFERRED_KEY';
-- COMMENT ON COLUMN graphitron_join_path_step_rule.constraint_schema IS 'the ridden foreign key''s schema';
-- COMMENT ON COLUMN graphitron_join_path_step_rule.constraint_table IS 'the table declaring the ridden foreign key';
-- COMMENT ON COLUMN graphitron_join_path_step_rule.constraint_name IS 'the ridden foreign key''s name';
-- COMMENT ON COLUMN graphitron_join_path_step_rule.fk_on_from IS 'whether the ridden foreign key is declared on the departure';
-- COMMENT ON COLUMN graphitron_join_path_step_rule.routine_source_name IS 'the called routine''s catalog partition, for ROUTINE';
-- COMMENT ON COLUMN graphitron_join_path_step_rule.routine_schema IS 'the called routine''s schema';
-- COMMENT ON COLUMN graphitron_join_path_step_rule.routine_name IS 'the called routine''s name';

CREATE TABLE code_delivery_container (
  container_class VARCHAR NOT NULL,
  element_index   VARCHAR NOT NULL,
  multiplies      BOOLEAN NOT NULL,
  PRIMARY KEY (container_class)
);
COMMENT ON TABLE code_delivery_container IS 'One class a declared type delivers something through, with the type-argument position its element sits at and whether passing through it makes the delivery many. For example java.util.List delivers its argument at position 0, many.';
COMMENT ON COLUMN code_delivery_container.container_class IS 'the fully-qualified binary name of the container class, spelled as the census spells a class name';
COMMENT ON COLUMN code_delivery_container.element_index IS 'the 0-based type-argument position the delivered element sits at, as a type_path step: 0 for the single-argument containers, 1 for a map, whose key is not what it delivers';
COMMENT ON COLUMN code_delivery_container.multiplies IS 'whether passing through this container makes the delivery many rather than one. A collection multiplies and a wrapper does not, which is why the two live in one relation rather than two: both are stepped through by the same descent, and only what the step means to cardinality differs. A map is the case worth stating, and it is FALSE: a map from a key to one value delivers one, and a map from a key to a list delivers many because of the list, so the map itself is transparent and the descent through it decides nothing.';
INSERT INTO code_delivery_container VALUES
  ('java.util.List', '0', TRUE),
  ('java.util.Set', '0', TRUE),
  ('java.util.Collection', '0', TRUE),
  ('java.util.Optional', '0', FALSE),
  ('java.util.concurrent.CompletableFuture', '0', FALSE),
  ('org.jooq.Result', '0', TRUE),
  ('java.util.Map', '1', FALSE);

