  ('splitquery-redundant-on-service-child', 'CLASSIFIER', 'WARNING'),
  ('redundant-record-directive', 'CLASSIFIER', 'WARNING'),
  ('asconnection-same-table-pk-in', 'CLASSIFIER', 'WARNING'),
  ('dml-write-length-unrouted', 'CLASSIFIER', 'WARNING'),
