CREATE TABLE store_graph_progress (
  graph_name     VARCHAR   NOT NULL,
  gatherer_name  VARCHAR   NOT NULL,
  last_started   TIMESTAMP NOT NULL,
  last_completed TIMESTAMP,
  time_spent_ms  BIGINT GENERATED ALWAYS AS (
    CASE WHEN last_completed >= last_started
         THEN DATEDIFF(MILLISECOND, last_started, last_completed) END),
  PRIMARY KEY (graph_name, gatherer_name),
  FOREIGN KEY (graph_name) REFERENCES store_graph (graph_name) ON DELETE CASCADE,
  FOREIGN KEY (gatherer_name) REFERENCES meta_gatherer (gatherer_name) ON DELETE CASCADE
);
COMMENT ON TABLE store_graph_progress IS 'How far a capture of one graph got: one row per gatherer that reads it, and one for the capture as a whole. For example a capture that hung in the graphitron gatherer leaves its row started after it last completed, every gatherer before it completed with this reading''s instants, and the capture row incomplete.';
COMMENT ON COLUMN store_graph_progress.graph_name IS 'the graph the capture read; with the gatherer, the key';
COMMENT ON COLUMN store_graph_progress.gatherer_name IS 'the gatherer, or capture for the whole of it; keyed into meta_gatherer, so a row names a gatherer the schema declares';
COMMENT ON COLUMN store_graph_progress.last_started IS 'when the gatherer last began reading this graph, by the wall clock; committed before it does anything, so a gatherer that never returns has already said it started';
COMMENT ON COLUMN store_graph_progress.last_completed IS 'when the gatherer last finished reading this graph, by the wall clock, written once its work was committed; NULL until it first has, and earlier than last_started while it runs or after it stopped partway';
COMMENT ON COLUMN store_graph_progress.time_spent_ms IS 'how long the last reading took, in milliseconds, where it finished; NULL while the gatherer runs or after it stopped partway, the completion then belonging to an earlier reading';

CREATE TABLE store_graph_write (
  graph_name    VARCHAR   NOT NULL,
  captured_at   TIMESTAMP NOT NULL,
  gatherer_name VARCHAR   NOT NULL,
  table_name    VARCHAR   NOT NULL,
  statements    INT       NOT NULL,
  rows_written  BIGINT    NOT NULL,
  time_spent_ms BIGINT    NOT NULL,
  prepare_ms    BIGINT    NOT NULL,
  PRIMARY KEY (graph_name, captured_at, gatherer_name, table_name),
  FOREIGN KEY (graph_name) REFERENCES store_graph (graph_name) ON DELETE CASCADE,
  FOREIGN KEY (gatherer_name) REFERENCES meta_gatherer (gatherer_name) ON DELETE CASCADE,
  CHECK (statements > 0),
  CHECK (rows_written >= 0),
  CHECK (time_spent_ms >= 0),
  CHECK (prepare_ms >= 0)
);
COMMENT ON TABLE store_graph_write IS 'How long one finished capture of a graph spent writing one table: one row per table each gatherer wrote, every capture keeping its own. For example graphitron_occurrence_column written by the graphitron gatherer in two statements, its rule evaluated inside the insert.';
COMMENT ON COLUMN store_graph_write.graph_name IS 'the graph the capture read';
COMMENT ON COLUMN store_graph_write.captured_at IS 'when the capture began, by the wall clock, as its row in store_graph_progress records it; with the graph, which capture this is';
COMMENT ON COLUMN store_graph_write.gatherer_name IS 'the gatherer running when the table was written, or capture for writes outside any; keyed into meta_gatherer';
COMMENT ON COLUMN store_graph_write.table_name IS 'the table written, as the statement names it, in upper case';
COMMENT ON COLUMN store_graph_write.statements IS 'how many insert, merge, update and delete statements wrote it, a batch counting once';
COMMENT ON COLUMN store_graph_write.rows_written IS 'the rows those statements reported changing';
COMMENT ON COLUMN store_graph_write.time_spent_ms IS 'the milliseconds those statements took to execute between them, a stage''s rule being evaluated inside its write; preparing them is prepare_ms';
COMMENT ON COLUMN store_graph_write.prepare_ms IS 'the milliseconds H2 spent preparing those statements, parsing and planning them before they ran; near nothing for a statement its session''s cache already held';

CREATE TABLE store_graph_write_stage (
  graph_name    VARCHAR   NOT NULL,
  captured_at   TIMESTAMP NOT NULL,
  gatherer_name VARCHAR   NOT NULL,
  table_name    VARCHAR   NOT NULL,
  stage_name    VARCHAR   NOT NULL,
  statements    INT       NOT NULL,
  rows_written  BIGINT    NOT NULL,
  time_spent_ms BIGINT    NOT NULL,
  prepare_ms    BIGINT    NOT NULL,
  PRIMARY KEY (graph_name, captured_at, gatherer_name, table_name, stage_name),
  FOREIGN KEY (graph_name, captured_at, gatherer_name, table_name)
    REFERENCES store_graph_write (graph_name, captured_at, gatherer_name, table_name) ON DELETE CASCADE,
  FOREIGN KEY (stage_name) REFERENCES meta_stage (stage_name) ON DELETE CASCADE,
  CHECK (statements > 0),
  CHECK (rows_written >= 0),
  CHECK (time_spent_ms >= 0),
  CHECK (prepare_ms >= 0)
);
COMMENT ON TABLE store_graph_write_stage IS 'One table one stage of a gatherer''s anchor phase wrote in one finished capture of a graph, and how long that stage spent on it. For example graphitron_path_need written by the occurrence-depths stage of the graphitron gatherer, once per depth.';
COMMENT ON COLUMN store_graph_write_stage.graph_name IS 'the graph the capture read';
COMMENT ON COLUMN store_graph_write_stage.captured_at IS 'when the capture began; with the graph, which capture this is';
COMMENT ON COLUMN store_graph_write_stage.gatherer_name IS 'the gatherer whose anchor phase ran the stage; with the graph, the capture and the table, the store_graph_write row this details';
COMMENT ON COLUMN store_graph_write_stage.table_name IS 'the table written, as the statement names it, in upper case';
COMMENT ON COLUMN store_graph_write_stage.stage_name IS 'the stage running when the table was written, a meta_stage key';
COMMENT ON COLUMN store_graph_write_stage.statements IS 'how many insert, merge, update and delete statements the stage wrote it with, a batch counting once';
COMMENT ON COLUMN store_graph_write_stage.rows_written IS 'the rows those statements reported changing';
COMMENT ON COLUMN store_graph_write_stage.time_spent_ms IS 'the milliseconds those statements took to execute between them';
COMMENT ON COLUMN store_graph_write_stage.prepare_ms IS 'the milliseconds H2 spent preparing those statements before they ran';

CREATE TABLE store_graph_read (
  graph_name    VARCHAR   NOT NULL,
  captured_at   TIMESTAMP NOT NULL,
  gatherer_name VARCHAR   NOT NULL,
  relation_name VARCHAR   NOT NULL,
  statements    INT       NOT NULL,
  rows_read     BIGINT    NOT NULL,
  time_spent_ms BIGINT    NOT NULL,
  prepare_ms    BIGINT    NOT NULL,
  PRIMARY KEY (graph_name, captured_at, gatherer_name, relation_name),
  FOREIGN KEY (graph_name) REFERENCES store_graph (graph_name) ON DELETE CASCADE,
  FOREIGN KEY (gatherer_name) REFERENCES meta_gatherer (gatherer_name) ON DELETE CASCADE,
  CHECK (statements > 0),
  CHECK (rows_read >= 0),
  CHECK (time_spent_ms >= 0),
  CHECK (prepare_ms >= 0),
  CHECK (time_spent_ms + prepare_ms >= 1)
);
COMMENT ON TABLE store_graph_read IS 'How long one finished capture of a graph spent reading one relation: one row per relation each gatherer spent a millisecond or more preparing and reading, every capture keeping its own. For example a rule view read by a stage that fetches it into Java and inserts the rows, the view evaluated in the read.';
COMMENT ON COLUMN store_graph_read.graph_name IS 'the graph the capture read';
COMMENT ON COLUMN store_graph_read.captured_at IS 'when the capture began, on store_graph_write''s terms, so a capture''s reads and writes are one capture';
COMMENT ON COLUMN store_graph_read.gatherer_name IS 'the gatherer running when the relation was read, or capture for reads outside any; keyed into meta_gatherer';
COMMENT ON COLUMN store_graph_read.relation_name IS 'the first relation the query reads from, a table or a view, in upper case; a rule a stage fetches is named by its view';
COMMENT ON COLUMN store_graph_read.statements IS 'how many queries read it';
COMMENT ON COLUMN store_graph_read.rows_read IS 'the rows those queries returned, where the result was fetched whole';
COMMENT ON COLUMN store_graph_read.time_spent_ms IS 'the milliseconds those queries took to execute between them, fetch included; a relation whose queries took less than one with their preparing is not recorded';
COMMENT ON COLUMN store_graph_read.prepare_ms IS 'the milliseconds H2 spent preparing those queries, parsing and planning them before they ran';

CREATE TABLE meta_gatherer_corpus (
  gatherer_name VARCHAR NOT NULL,
  corpus_name   VARCHAR NOT NULL,
  PRIMARY KEY (gatherer_name, corpus_name),
  FOREIGN KEY (gatherer_name) REFERENCES meta_gatherer (gatherer_name),
  FOREIGN KEY (corpus_name) REFERENCES meta_corpus (corpus_name)
);
COMMENT ON TABLE meta_gatherer_corpus IS 'One corpus a gatherer reads: a declared pairing of one gatherer with one outside input. For example the catalog gatherer carries two rows, catalog and classpath. A gatherer with at least one row here is a crawler, and this junction is the store''s definition of that word: a transcription pass whose rows about its own corpus may not vary with any other corpus''s contents. A gatherer with no row here reads no corpus at all: it reads captured rows, and is thereby free to cross corpora, which is what the derivation gatherer is. The graphitron gatherer is the one that is both: its capture phase decodes the documents'' graphitron directives as written, and its anchor phase resolves them against the catalog, the classpath and the configuration, so it declares all four and its edges say whose rows the anchor reads.';
COMMENT ON COLUMN meta_gatherer_corpus.gatherer_name IS 'the reading gatherer, a meta_gatherer key';
COMMENT ON COLUMN meta_gatherer_corpus.corpus_name IS 'the corpus read, a meta_corpus key';

INSERT INTO meta_gatherer_corpus VALUES
  ('sdl', 'sdl'),
  ('classpath-source', 'classpath'),
  -- Which entries to read is the classpath the build declared, handed to the reading with the rest
  -- of the configuration.
  ('classpath-source', 'configuration'),
  ('code', 'classpath'),
  ('graphql-source', 'sdl'),
  -- The reading expands the recipe to find the files, and what each matching entry configures for
  -- its files is recorded where the match is made.
  ('graphql-source', 'configuration'),
  ('graphql-ast', 'sdl'),
  -- The documents' graphitron directives are decoded as written, and the anchor then resolves them
  -- against the catalog, the classpath and the configuration: the grains it anchors live in all
  -- four.
  ('graphitron', 'sdl'),
  ('graphitron', 'catalog'),
  ('graphitron', 'classpath'),
  ('graphitron', 'configuration'),
  ('graphql-assembly', 'sdl'),
  -- The assembly judges the corpus as the generator composes it, and the composition is configured:
  -- the inputs' tags and notes reach the schema it judges, so its rows vary with the configuration
  -- as well as with the documents.
  ('graphql-assembly', 'configuration'),
  ('jooq', 'catalog'),
  ('store', 'configuration'),
  ('java-source', 'java-source'),
  ('compile', 'javac'),
  ('federation', 'federation');

CREATE TABLE meta_gatherer_dependency (
  gatherer_name VARCHAR NOT NULL,
  depends_on    VARCHAR NOT NULL,
  PRIMARY KEY (gatherer_name, depends_on),
  FOREIGN KEY (gatherer_name) REFERENCES meta_gatherer (gatherer_name),
  FOREIGN KEY (depends_on) REFERENCES meta_gatherer (gatherer_name),
  CHECK (gatherer_name <> depends_on)
);
COMMENT ON TABLE meta_gatherer_dependency IS 'One declared read edge between gatherers: the first may read rows the second produced. For example the derivation gatherer depends on every crawler, which is what running last means once it stops being a position. Declared rather than derived from the view bodies, deliberately: the declaration states the intended shape, and the view-ownership gate denies a declared view that reads outside its owner''s dependency set, so a view forking the shape fails instead of widening it. A crawler''s capture carries no edges: its rows about its own corpus may not vary with any other corpus''s contents, which is the same statement as depending on nobody, so the sdl and catalog gatherers stand independent of each other and of everything else. An edge runs from a gatherer that crosses corpora: the graphitron gatherer, whose anchor phase resolves what its capture phase decoded against the transcription, the catalog and the classpath, and the derivation gatherer downstream of them all. The roster drives no execution: the order gatherers run in is FactCapture.capture''s statement order, and these edges are what that order has to satisfy. What makes the order able to satisfy them is that each gatherer''s rows are flushed to the store before the next one starts, a flush inside the load''s one transaction being what lets a downstream gatherer read an upstream''s rows without publishing a partition mid-load.';
COMMENT ON COLUMN meta_gatherer_dependency.gatherer_name IS 'the dependent gatherer, the one performing the read; a meta_gatherer key';
COMMENT ON COLUMN meta_gatherer_dependency.depends_on IS 'the prerequisite gatherer whose rows may be read; a meta_gatherer key, and never the dependent itself, the CHECK refusing the length-one cycle';

INSERT INTO meta_gatherer_dependency VALUES
  ('graphitron', 'sdl'),
  -- Whether a directive was written at a coordinate is a fact about the document, so the arms that
  -- ask it read the transcription rather than the decode of what it says. The decode is a later and
  -- stricter reading, and a view asking it would answer differently depending on how far the pass
  -- had got.
  -- And the decode keys each application to the node the transcription wrote at its position.
  ('graphitron', 'graphql-ast'),
  -- What an application names is resolved in the anchor, so the anchor runs after the catalog and
  -- the classpath have been read; before them it could only copy the author's strings.
  ('graphitron', 'jooq'),
  -- A condition element routes by its method's signature, which the classpath reading captured.
  -- ModelCapture runs CodeCapture before this gatherer for that reason, and the chain resolution
  -- has read the signature across that boundary for as long as the arm has existed.
  ('graphitron', 'code'),
  -- A link's added imports are the ones its federation version allows, and a configured link names
  -- the version graphitron writes; the federation gatherer records both, scoped by the graph's claim
  -- on the library. ModelCapture runs it first.
  ('graphitron', 'federation'),
  ('graphitron', 'store'),
  -- The composition hands federation-jvm the link with the imports the anchor settled, so
  -- ModelCapture runs the assembly after the graphitron gatherer.
  ('graphql-assembly', 'graphitron'),
  -- The tags the configuration applies are a rule over what each file's entry configures, which the
  -- source reading records. ModelCapture runs it first.
  ('graphitron', 'graphql-source'),
  ('code', 'classpath-source'),
  -- The handle class a graph names for its session identity is read for its members whatever
  -- package or origin it is in, and the name is a row the store gatherer wrote first.
  ('code', 'store'),
  ('derivation', 'store'),
  ('derivation', 'classpath-source'),
  ('derivation', 'sdl'),
  ('derivation', 'graphql-source'),
  ('derivation', 'graphql-ast'),
  ('derivation', 'graphql-assembly'),
  ('derivation', 'graphitron'),
  ('derivation', 'jooq'),
  ('derivation', 'java-source'),
  ('derivation', 'compile'),
  ('derivation', 'code'),
  ('derivation', 'federation');

CREATE TABLE meta_grain (
  grain_name    VARCHAR NOT NULL,
  instance_text VARCHAR NOT NULL,
  key_shape     VARCHAR NOT NULL,
  corpus_name   VARCHAR NOT NULL,
  PRIMARY KEY (grain_name),
  FOREIGN KEY (corpus_name) REFERENCES meta_corpus (corpus_name),
  CHECK (CHAR_LENGTH(instance_text) BETWEEN 1 AND 300),
  CHECK (CHAR_LENGTH(key_shape) >= 1)
);
COMMENT ON TABLE meta_grain IS 'One grain this store knows about: what one row of a relation at this grain is about. For example a grain named field with key shape graph_name, type_name, field_name says one row is one field of one type in one graph. The store already states every grain twice without naming it, a relation''s primary key being its grain as columns and its comment''s first sentence being its grain as prose; this roster is the same fact as data, and a declared base table''s key must equal its grain''s shape (gated).';
COMMENT ON COLUMN meta_grain.grain_name IS 'the grain''s name, the roster''s key, in lowercase kebab case';
COMMENT ON COLUMN meta_grain.instance_text IS 'one sentence saying what one instance of the grain is; length-checked';
COMMENT ON COLUMN meta_grain.key_shape IS 'the canonical key as a comma-separated column list in key order; a declared base table at this grain carries exactly this primary key (gated)';
COMMENT ON COLUMN meta_grain.corpus_name IS 'the corpus the grain lives in, a meta_corpus key; where a declared relation''s owner reads any corpus at all, the grain''s corpus must be among them (gated)';

CREATE TABLE meta_relation (
  relation_name VARCHAR NOT NULL,
  grain_name    VARCHAR NOT NULL,
  owner_name    VARCHAR NOT NULL,
  grain_text    VARCHAR NOT NULL,
  example       VARCHAR NOT NULL,
  rationale     VARCHAR NOT NULL,
  PRIMARY KEY (relation_name),
  FOREIGN KEY (grain_name) REFERENCES meta_grain (grain_name),
  FOREIGN KEY (owner_name) REFERENCES meta_gatherer (gatherer_name),
  CHECK (CHAR_LENGTH(grain_text) BETWEEN 1 AND 300),
  CHECK (CHAR_LENGTH(example) BETWEEN 1 AND 300),
  CHECK (CHAR_LENGTH(rationale) BETWEEN 1 AND 1500)
);
COMMENT ON TABLE meta_relation IS 'One declared relation: which grain it is at, which gatherer owns it, what one of its rows is, one example of one, and why the relation exists at all. For example a row for sql_column names its grain, the catalog gatherer as its owner, and one concrete column as its example. A relation with no row is one nobody has declared yet; the roster of those is pinned in MetaDeclarationGateTest, frozen when this model landed and only ever shrinking, so a new relation cannot arrive undeclared. A declared relation''s own comment must equal grain_text and example joined (gated), which keeps the inline description a SQL client shows and these columns from drifting apart.';
COMMENT ON COLUMN meta_relation.relation_name IS 'the declared relation''s name, the key; must name an observed relation (gated)';
COMMENT ON COLUMN meta_relation.grain_name IS 'the grain the relation is at, a meta_grain key';
COMMENT ON COLUMN meta_relation.owner_name IS 'the gatherer that owns the relation, a meta_gatherer key, the column named for the role the reference plays; a declared view may read only relations its owner owns or declares a dependency on (gated)';
COMMENT ON COLUMN meta_relation.grain_text IS 'the one sentence saying what one row is: a single sentence by GrainSentence''s own rule, and the first sentence of the relation''s comment (both gated)';
COMMENT ON COLUMN meta_relation.example IS 'one example row stated concretely, and the remainder of the relation''s comment after the grain sentence (gated)';
COMMENT ON COLUMN meta_relation.rationale IS 'why this relation exists, a paragraph at most by the CHECK beside it; measurements, rejected shapes and arguments with earlier authors belong in the architecture docs rather than here';

