   'one position in one table''s stated legacy node key-columns array',
   'source_name, table_schema, table_name, position', 'catalog'),
  ('classpath-class',
   'one class of one classpath entry',
   'source_name, class_name', 'classpath'),
  ('graph-class',
   'one class name the classpath of one graph declares',
   'graph_name, class_name', 'classpath'),
  ('class-file',
   'one class file under one classpath entry',
   'source_name, file_path', 'classpath'),
  ('class-ancestor',
   'one type one class is, the class itself excluded',
   'source_name, class_name, supertype_name', 'classpath'),
  ('class-constructor',
   'one public constructor of one class, overloads told apart by descriptor',
   'source_name, class_name, descriptor', 'classpath'),
  ('class-method',
   'one method of one class, overloads told apart by descriptor',
   'source_name, class_name, method_name, descriptor', 'classpath'),
  ('construction-argument',
   'one argument of one call that fills a member when a value of one class is made',
   'source_name, class_name, method_name, descriptor, position', 'classpath'),
  ('declared-type',
   'one type as a source declared it, within one classpath entry',
   'source_name, type_name', 'classpath'),
  ('declared-type-argument',
   'one type argument of the element one declared type delivers, by its position',
   'source_name, type_name, position', 'classpath'),
  ('method-exception',
   'one exception one method declares it throws',
   'source_name, class_name, method_name, descriptor, exception_class', 'classpath'),
  ('constructor-parameter',
   'one position in one constructor''s parameter list',
   'source_name, class_name, descriptor, position', 'classpath'),
  ('method-parameter',
   'one position in one method''s parameter list',
   'source_name, class_name, method_name, descriptor, position', 'classpath'),
  ('scalar-type-field',
   'one static field of one class holding a GraphQL scalar type',
   'source_name, class_name, field_name', 'classpath'),
  ('source-file',
   'one .java source file this store holds declarations from',
   'file', 'java-source'),
  ('source-class-declaration',
   'one class declaration written in one source file',
   'file, class_name', 'java-source'),
  ('source-method-declaration',
   'one method declaration on one declared class, overloads told apart by declaration order',
   'file, class_name, method_name, ordinal', 'java-source'),
  ('source-field-declaration',
   'one field declaration on one declared class',
   'file, class_name, field_name', 'java-source'),
  ('compile-diagnostic',
   'one diagnostic the compiler reported at one position of one file, in one graph''s round',
   'graph_name, file, line_number, column_number, ordinal', 'javac');

INSERT INTO graphitron_claim_kind VALUES
